INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふふっ…そんなとこ\nツンツンしないで\nくすぐったいよ～", 2, 88, 1, 102, 8, 100202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう\nよく眠れた？　今日も\n一日、頑張ろうね♪", 2, 89, 1, 1, 1, 100202, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹空いちゃった…\nそうだ。騎士クンも\n一緒にお昼食べない？", 2, 90, 1, 2, 1, 100202, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間…\nそろそろ寝なくちゃ\nおやすみなさい", 2, 91, 1, 3, 1, 100202, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よし…\nこれなら\n褒めてもらえるかな？", 3, 92, 1, 1, 1, 100202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("がんばることも\n必要だけど\nお休みも大切だよね", 3, 93, 1, 2, 1, 100202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい～♪\n騎士クンは\nこういうのって好き？", 3, 94, 1, 3, 1, 100202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦う前にもこうやって\n落ち着けたら\nいいのに", 3, 95, 1, 4, 1, 100202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの…！\nよ、良かったら\n一緒に…！", 3, 96, 1, 5, 1, 100202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンと一緒に\n冒険するなら\n体力がないと…！", 3, 97, 1, 6, 1, 100202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近服のサイズが\n合わないんだけど…\n食べ過ぎなのかな？", 3, 98, 1, 7, 1, 100202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…やっぱり\n月刊恋愛指南は\nためになる…", 3, 99, 1, 8, 1, 100202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("装備の手入れでも\nしようかな…", 1, 101, 1, 1, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次に鍛えるべきは\n肉体面か精神面か\nどちらにしよう…？", 1, 102, 1, 2, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ツムギが作ってくれた\nこの服…一体\nいつサイズを…？", 1, 103, 1, 3, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仲間なんていらない\nそう思ってた頃も\nあったな…", 1, 104, 1, 4, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("考えごとをしていると\nつい部屋中を\n歩いてしまうな", 1, 105, 1, 5, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼は\nどこまで強くなるのか\n私も負けられないな", 1, 106, 1, 101, 4, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私が一本を取られる\nなんてね…願い事は\nもう決まったのかな？", 1, 107, 1, 102, 8, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ、キミだったのか\n人の気配がしたから\n誰かと思ったよ", 2, 108, 1, 1, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("斬りかかるつもりなら\nちゃんとかかってきて\n…呼んだだけ？", 2, 109, 1, 2, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なに？　私に相談？\n戦いについてなら\n喜んで", 2, 110, 1, 3, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今のが突き？\n軽い！　もっと鋭く！\nさあ、もう一回！", 2, 111, 1, 4, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃっ！　ど、どこを\n触ってるの！？\n…油断した", 2, 112, 1, 101, 4, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミにはこれからも\n私のそばに…\nいや、なんでもない", 2, 113, 1, 102, 8, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう\n今日も充実した\n一日にしていこう", 2, 114, 1, 1, 1, 100301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ\nお茶の時間か\nキミも一緒にどう？", 2, 115, 1, 2, 1, 100301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("遅くまで大変だね\nまだ仕事があるなら\n手伝おうか？", 2, 116, 1, 3, 1, 100301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦いを経てもなお\n美しくあるように…\nこれでよし♪", 3, 117, 1, 1, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦ってばかりで\n休まないと、また\nユイに怒られるな", 3, 118, 1, 2, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒヨリみたいに\n練習相手に…\nいや、やめておこう", 3, 119, 1, 3, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これはいい…\n戦いの前の精神統一に\nもってこいじゃないか", 3, 120, 1, 4, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時々は落ち着いた\n時間を過ごすのも\n悪くない…", 3, 121, 1, 5, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼に負けないよう\n私も更に強くなろう\n共に戦うために！", 3, 122, 1, 6, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食事は大切だけど\n食べ過ぎには\n注意しておこう…", 3, 123, 1, 7, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ユイ…！\nこ、こんな本を\n読んでいたのか…！", 3, 124, 1, 8, 1, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海だけじゃなくて\n川でも釣りがしたいな\n道具も新調しよう", 1, 126, 1, 1, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ツムギが作ってくれた\nこの服…一体\nいつサイズを…？", 1, 127, 1, 2, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼は\nどこまで強くなるのか\n私も負けられないな", 1, 128, 1, 3, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ修行の\n内容を新しくしよう\nより厳しいものにね", 1, 129, 1, 4, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("強くなって…誰にも\n妨げられない自由な\n生き方がしたい", 1, 130, 1, 5, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まさか風邪を引くとは\n彼の看病のおかげで\nすっかり良く\nなったけど", 1, 131, 1, 101, 8, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私が一本を取られる\nなんてね…願い事は\nもう決まったのかな？", 1, 132, 1, 102, 8, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたの？\nなんでもない？\nそれなら良かった", 2, 133, 1, 1, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんまり突っつくと\nお返しするよ？\n覚悟は出来てる？", 2, 134, 1, 2, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇ、今度また\n釣りに行かない？\n大きいのを狙おう", 2, 135, 1, 3, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("修行がしたいの？\nそれを早く言ってよ\nすぐに出発しよう！", 2, 136, 1, 4, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひょっとして\n今のも一本だなんて\n言わないよね？", 2, 137, 1, 101, 8, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミにはこれからも\n私のそばに…\nいや、なんでもない", 2, 138, 1, 102, 8, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は仕事？\nそれとも修行？\n良ければ付き合うよ", 2, 139, 1, 1, 1, 100302, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休息も時には\n必要だと、仲間から\n教わったよ", 2, 140, 1, 2, 1, 100302, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("遅くまで大変だね\nまだ仕事があるなら\n手伝おうか？", 2, 141, 1, 3, 1, 100302, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("髪の長さを少し\n変えてみようかな…\nわ、私は何を…！", 3, 142, 1, 1, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休息があってこそ\n万全な状態で\n戦えるんだ", 3, 143, 1, 2, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒヨリみたいに\n練習相手に…\nいや、やめておこう", 3, 144, 1, 3, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体と同様に\n心もほぐれるね…\nはぁ…", 3, 145, 1, 4, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休む時は休む\nヒヨリもそろそろ\n覚えて欲しいな…", 3, 146, 1, 5, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼に負けないよう\n私も更に強くなろう\n共に戦うために！", 3, 147, 1, 6, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("修行のせいか\n最近食べる量が\n増えてきたような…", 3, 148, 1, 7, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ユイ…！\nこ、こんな本を\n読んでいたのか…！", 3, 149, 1, 8, 1, 100302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お宝の予感！\n部屋中を\n探検しちゃうぞ～", 1, 151, 1, 1, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("落とし穴…どこに\n作ったんだっけ？", 1, 152, 1, 2, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うえ～ん！\n…嘘泣きしたら\n相手は油断するかな", 1, 153, 1, 3, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハニートラップって\nすごく甘いお菓子で\nイタズラするのかな？", 1, 154, 1, 4, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かくれんぼする人\nこの指、と～まれ！", 1, 155, 1, 5, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミソギ以外の人に\nイタズラされちゃ\nダメだよ！", 1, 156, 1, 101, 4, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミソギと遊ぶ？\nミソギに遊ばれる？", 1, 157, 1, 102, 8, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいこと思いついた！\nい、イタズラとかじゃ\nないよ～", 2, 158, 1, 1, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うわっ！？\n　にいちゃんが、\nミソギにイタズラ？", 2, 159, 1, 2, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんの\n通りそうなところに\nバナナの皮を…", 2, 160, 1, 3, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんのオデコと\nホッペと鼻と目と耳に\n落書きを…", 2, 161, 1, 4, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここ、ミソギ探検隊の\n基地にしようよ！", 2, 162, 1, 101, 4, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("だ～れだ…って？\nにいちゃんの声くらい\nわかるよ！\n大好きだもん♪", 2, 163, 1, 102, 8, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃん、おはよ！\n目覚まし時計を\n止めておいたのに、\nよく起きられたね～♪", 2, 164, 1, 1, 1, 100401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんが\n昼寝したら、\nイタズラし放題♪", 2, 165, 1, 2, 1, 100401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の探検も\nおもしろそう！\nねぇ出かけちゃダメ？", 2, 166, 1, 3, 1, 100401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イタズラには\nお色気も必要…\nうん、完璧！", 3, 167, 1, 1, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("座ったら、ブーッって\nいう音が出たら、\nおもしろいな～♪", 3, 168, 1, 2, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい！\nミソギ探検隊の\nマスコットにしよう♪", 3, 169, 1, 3, 1, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("吸うとくしゃみが\n止まらなくなるお香を\nここに…くしゅっ！", 3, 170, 1, 4, 1, 100401, 0, 0);
