INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("右にプリン左にプリン\n後ろにもプリン♪\n前にはオマエなの～！", 2, 260, 1, 3, 1, 100701, 0, 0);
