INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もし太陽が滅んでも\nボクの美しさで大地を\n照らしてあげる！", 1, 301, 1, 1, 1, 100801, 0, 0);
