INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美しい…\nキミの瞳に写るボクは\nより一層きれいだ", 2, 313, 1, 102, 8, 100801, 0, 0);
