INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("バラの花びらいっぱい\n浮かべたお風呂に\n入ってから\n寝ようっと♪", 2, 341, 1, 3, 1, 100802, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鏡よ、鏡。この世で\n一番可愛いボクに\nお似合いの人はだれ？", 3, 342, 1, 1, 1, 100802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクが座ったソファは\n「美しいソファ」に\nランクアップした！", 3, 343, 1, 2, 1, 100802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("可愛いものを\n可愛いって言える\nボクって可愛いよね！", 3, 344, 1, 3, 1, 100802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("服を羽織るように\n香りをまとうボク…\n美しい、美しすぎる！", 3, 345, 1, 4, 1, 100802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冷えは美容の大敵\nなんだから！\nここ、ボクの場所ね！", 3, 346, 1, 5, 1, 100802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("運動は苦手なのに\n運動するボクの姿は\n可愛いなんて…罪♪", 3, 347, 1, 6, 1, 100802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクが食べると\n食べ物まで\n可愛いなあ…", 3, 348, 1, 7, 1, 100802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクが触った瞬間に\nこの本は美を\n携えてしまうんだ", 3, 349, 1, 8, 1, 100802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「第１０部２０章\n終焉戦争、開幕」\n…これでよし！", 1, 351, 1, 1, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度シグルドに\n私の魔法を一つ\n伝授してやるか", 1, 352, 1, 2, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここでは風が\n吹いてこないな…\n換気したい！", 1, 353, 1, 3, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうだ、ナナカに\nこの間借りた本を\n返さないと…", 1, 354, 1, 4, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まずは包帯をとって\n手から龍の形の\n炎を出して…", 1, 355, 1, 5, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シグルド…\n今頃何処で何を\nしているのだろう…", 1, 356, 1, 101, 4, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近、彼の姿が\nまぶしく見える…\nどうして…？", 1, 357, 1, 102, 8, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("辞書を知らないか？\n…探している\n理由は聞くな", 2, 358, 1, 1, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうだ！\n貴様の技にも\n名前をつけてやろう！", 2, 359, 1, 2, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私に触れても力を\n奪われないのは\n貴様くらいだぞ？", 2, 360, 1, 3, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何事だ？\nまさか我が瞳に\n魅入られたのか？", 2, 361, 1, 4, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴様がそばにいると\nとても安心できる…\n…不思議だ", 2, 362, 1, 101, 4, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("い、いきなり目の前に\n現れるな！　ドキドキ\nするだろうがぁ！", 2, 363, 1, 102, 8, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「覚醒」めたか…\n行くぞ、悪を討つ\n戦いに出発だ！", 2, 364, 1, 1, 1, 100901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼間は「ヤツら」も\n襲ってはこない…\n束の間の休息だ", 2, 365, 1, 2, 1, 100901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうした？　夜はまだ\nこれから…ふぁ…\nね、眠くなどないぞ！", 2, 366, 1, 3, 1, 100901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何か足りないな…\n暗黒騎士の紋章を\n作ろうかな", 3, 367, 1, 1, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くっ…！\n私を眠りの国へ\n誘うつもりか！", 3, 368, 1, 2, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このようなものに\n懐柔されるものか！\n…されるものか！", 3, 369, 1, 3, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これを使えば\nもっとそれっぽい\n雰囲気が出そうだ", 3, 370, 1, 4, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これが我らの求めた\n安寧か…\n悪くない…", 3, 371, 1, 5, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この程度\n前世での激闘に\n比べれば…！", 3, 372, 1, 6, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近金欠でな…\nいやぁありがたい…", 3, 373, 1, 7, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにも\n前世の記憶が\n眠っていたとは…", 3, 374, 1, 8, 1, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「第１３部１章\n閃光のシグルド」\n…ついに登場だな", 1, 376, 1, 1, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何故だ…何故\nこうもあっさり金欠に\n逆戻りするのだ！？", 1, 377, 1, 2, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やはり転生者という\n設定はカッコイイ…\n天才だな、私！", 1, 378, 1, 3, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうだ、ナナカに\nこの間借りた本を\n返さないと…", 1, 379, 1, 4, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ今日の分の\n魔力を溜めないと\nまた魔力切れが…", 1, 380, 1, 5, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近奴がそばに\nいるだけで、鼓動が\n早くなるのは何故だ？", 1, 381, 1, 101, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シ、シグルド…！\nだめだ…妄想でも\n上手く言えない…", 1, 382, 1, 102, 8, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだ？　新たな\n賞金の情報を\n持ってきたのか？", 2, 383, 1, 1, 8, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("名乗りやポーズは\nその強度で相手を\n圧倒する技術だ", 2, 384, 1, 2, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいか、魔法の\n詠唱中は絶対に\n声をかけるなよ？", 2, 385, 1, 3, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おお、ちょうど今\n貴様専用の設定集を\n作成中だぞ！", 2, 386, 1, 4, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴様がそばにいると\nとても安心できる…\n…不思議だ", 2, 387, 1, 101, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("い、いきなり目の前に\n現れるな！　ドキドキ\nするだろうがぁ！", 2, 388, 1, 102, 8, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜更かしのせいか\nまだ眠気が…いや！\nこれは組織の罠だ！", 2, 389, 1, 1, 8, 100902, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("平穏な時に\n出来るだけ魔力を\n溜めておかねば…", 2, 390, 1, 2, 1, 100902, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜になると、力が\n増した気分になるな\n…なりませんか？", 2, 391, 1, 3, 1, 100902, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何か足りないな…\n暗黒騎士の紋章を\n作ろうかな", 3, 392, 1, 1, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、おのれ\nヒュプノス…\n私は負けないぞ…", 3, 393, 1, 2, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くっくっくっ…\n貴様は特別団員に\nしてやろう", 3, 394, 1, 3, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これを使えば\nもっとそれっぽい\n雰囲気が出そうだ", 3, 395, 1, 4, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これが我らの求めた\n安寧か…\n悪くない…", 3, 396, 1, 5, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新たな戦いに備えて\n魔力だけでなく\n体力も鍛えねば！", 3, 397, 1, 6, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食事は魔力に\n変換する体力の\n元になるのだ！", 3, 398, 1, 7, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フフフ…\nこれを覚えれば\nもっと強く…！", 3, 399, 1, 8, 1, 100902, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんほんまに\nはんなりしてて、\n王子はんって感じやわ", 1, 401, 1, 1, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この絵本の王子はん、\n王子はんみたいで\nええなぁ♪", 1, 402, 1, 2, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちがガラスの靴を\n落としたら、王子はん\n見つけてくれるやろか", 1, 403, 1, 3, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マホマホ王国\n次期国王の王子はん\n…見てみたいわ～", 1, 404, 1, 4, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんのために\n糸を紡いで、\n編み物でもしまひょか", 1, 405, 1, 5, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マホ姫と王子はん、\n絵本の世界より\nベストカップルや", 1, 406, 1, 101, 4, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんと\n一緒にいると\n胸がせわしのー\nうごいてかなん", 1, 407, 1, 102, 8, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちら並んでたら\nお雛様みたいに\n見えると思いまへん？", 2, 408, 1, 1, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんを\n国に連れて帰ったら\nみんな大歓迎して\nくれるやろなぁ", 2, 409, 1, 2, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんは、\n絵本から出てきた人\nみたいやね～", 2, 410, 1, 3, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちの話し方\nのんびりしてます\nやろか？", 2, 411, 1, 4, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マホ姫の手は\nつべたいから、\n王子はんが温めて？", 2, 412, 1, 101, 4, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちがもし悪い魔法に\nかかったら、王子はん\n口づけしてくれはる？", 2, 413, 1, 102, 8, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝は小鳥はんも\nおなかがすいてるから\nよう飛び回りはるねえ", 2, 414, 1, 1, 1, 101001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お茶請けはお大福が\nよろしおすけど\nクッキーもええなあ", 2, 415, 1, 2, 1, 101001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うち、普段から\n夢見がちやけど…\nほんに眠い時間やわぁ", 2, 416, 1, 3, 1, 101001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんに\n会いに行くなら、\nおめかしせな\nあかんなぁ", 3, 417, 1, 1, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はんなりした\nええお椅子やわぁ\nほっこりしますなあ", 3, 418, 1, 2, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かいらしもんが\nいっぱいで、\nマホマホ王国みたい\nやわぁ", 3, 419, 1, 3, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("心地ええどす。まるで\nお花畑にいるようやね", 3, 420, 1, 4, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽかぽかどす。\n心まであったかく\nなりますわぁ", 3, 421, 1, 5, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁはぁ、お姫はんは\n激しい運動は\nしぃひんもんどす～", 3, 422, 1, 6, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…あんまり\n速う食べられへんけど\n美味しいわぁ", 3, 423, 1, 7, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("絵本、絵本～\n幸せやわぁ♪", 3, 424, 1, 8, 1, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんにとって\n自慢の姫になるえ～", 1, 426, 1, 1, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カボチャの馬車に\nガラスの靴…\n欲しいなぁ", 1, 427, 1, 2, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちがガラスの靴を\n落としたら、王子はん\n見つけてくれるやろか", 1, 428, 1, 3, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マホマホ王国\n次期国王の王子はん\n…見てみたいわ～", 1, 429, 1, 4, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほんまなぁ\nこの絵本が面白いんよ\n王子はんに\n読んであげよ", 1, 430, 1, 5, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マホ姫と王子はん\n絵本の世界より\nベストカップルや", 1, 431, 1, 101, 8, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんと\n一緒にいると\n胸がせわしのー\nうごいてかなん", 1, 432, 1, 102, 8, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまには、王子はんの\n好きな絵本も\n知りたいな～", 2, 433, 1, 1, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんを\n国に連れて帰ったら\nみんな大歓迎して\nくれるやろなぁ", 2, 434, 1, 2, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そのうち、王子はんの\nお国にも連れてって\nもらえますやろか？", 2, 435, 1, 3, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("絵本読むんも\nええなぁ…", 2, 436, 1, 4, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちがもし悪い魔法に\nかかったら、王子はん\n口づけしてくれはる？", 2, 437, 1, 101, 8, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちら並んでたら\nお雛様みたいに\n見えると思いまへん？", 2, 438, 1, 102, 8, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝は小鳥はんも\nおなかがすいてるから\nよう飛び回りはるねえ", 2, 439, 1, 1, 1, 101002, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マホマホ王国では\nこの時分は\nみんなお昼寝\nしてたんよ", 2, 440, 1, 2, 1, 101002, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜に飛んだり鳴いたり\nする鳥はんもおるんよ\n昼は寝てはるんかねぇ", 2, 441, 1, 3, 1, 101002, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんに\n会いに行くなら\nおめかしせな\nあかんなぁ", 3, 442, 1, 1, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんも一緒に\nゆっくりしていっても\nええんよ？", 3, 443, 1, 2, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かいらしい子やねぇ\nうちとお友だちに\nなってくれるん？", 3, 444, 1, 3, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("癒しアイテムって\nほんま、好っきゃわぁ", 3, 445, 1, 4, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちのお城にも\nほしいわぁ。帰ったら\nさっそく準備せな\nあかんなぁ", 3, 446, 1, 5, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋の中で運動\nできるのも、なかなか\n面白いもんやわぁ", 3, 447, 1, 6, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいひいわ～\nマホマホ王国には\nない味やわぁ", 3, 448, 1, 7, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しっかり知識を\n身につけんと\n魔法も使えへん\nからなぁ", 3, 449, 1, 8, 1, 101002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("１、２、３、４…\nあれ？　いま、\n何段目まで\n編んだっけ？", 1, 451, 1, 1, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おやつのケーキは\n苺かチョコ…\nどっちも食べよう！", 1, 452, 1, 2, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("い、いけない！\n縫い針落としちゃった", 1, 453, 1, 3, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ケーキをクレープで\n巻いたら…\n大ヒット商品の予感！", 1, 454, 1, 4, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「どうだ！妹暮らし」\nってことわざ\nなかったっけ？", 1, 455, 1, 5, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんに、\nお洋服でも\n作ろうかな？", 1, 456, 1, 101, 4, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここがお兄ちゃんの\n部屋…\nドキドキしちゃう～", 1, 457, 1, 102, 8, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇ、おにいちゃん\n一緒に、スイーツでも\n食べにいかない？", 2, 458, 1, 1, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリームついてた！？\nさっき食べた、\nケーキかも…！", 2, 459, 1, 2, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("勉強、見てくれるん\nですか？　やった～♪", 2, 460, 1, 3, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("服がほつれてますよ？\n直してあげます！", 2, 461, 1, 4, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私をお嫁さんに\nしたいなら、予約は\nお早目に、ですよ♪", 2, 462, 1, 101, 4, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇねぇお兄ちゃん！\n…えへへ、\n呼んでみただけ♪", 2, 463, 1, 102, 8, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も１日\n勉強がんばります！\n…少しは遊ぼうかな", 2, 464, 1, 1, 1, 101101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼休憩に\n甘いものが\n食べたいです～", 2, 465, 1, 2, 1, 101101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねむいです～\nでももうちょっと\n勉強しないと～…", 2, 466, 1, 3, 1, 101101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服、かわいい♪\n今度作って\nみよっと～！", 3, 467, 1, 1, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("勉強で疲れたから\n休憩しよ～っと", 3, 468, 1, 2, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい♪\n私が服を作って\nあげよっか？", 3, 469, 1, 3, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リラックスできます～\nお兄ちゃんが隣に\nいるみたい！", 3, 470, 1, 4, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("のんびりしたら、\nまた勉強しよっと！", 3, 471, 1, 5, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("運動すると勉強も\nはかどるよね！", 3, 472, 1, 6, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいし～！\nお兄ちゃんにも\nおすそ上げしますね！", 3, 473, 1, 7, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんの記憶を\n戻す方法、どこかに\n書いてないかな？", 3, 474, 1, 8, 1, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ケーキの食べ過ぎで\nお腹が…うぅ、\n因果横暴だよー…", 1, 476, 1, 1, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("１、２、３、４…\nあれ？　いま、\n何段目まで\n編んだっけ？", 1, 477, 1, 2, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("い、いけない！\n縫い針落としちゃった", 1, 478, 1, 3, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("笑う時には服着ます！", 1, 479, 1, 4, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「どうだ！妹暮らし」\nってことわざ\nなかったっけ？", 1, 480, 1, 5, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんに、\nお洋服でも\n作ろうかな？", 1, 481, 1, 101, 8, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんが帰って\nきたら、何して遊ぼう\nかな～？", 1, 482, 1, 102, 8, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("勉強、見てくれるん\nですか？　やった～♪", 2, 483, 1, 1, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリームついてた！？\nさっき食べた、\nケーキかも…！", 2, 484, 1, 2, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃん！\nそろそろ、おやつに\nしませんか？", 2, 485, 1, 3, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("勉強は…\n明日にしようっと", 2, 486, 1, 4, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("妹だけど、大人な\nレディですからね！", 2, 487, 1, 101, 8, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("な、ナデナデとか\n恥ずかしいな～", 2, 488, 1, 102, 8, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も１日\n勉強がんばります！\n…少しは遊ぼうかな", 2, 489, 1, 1, 1, 101102, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼休憩に\n甘いものが\n食べたいです～", 2, 490, 1, 2, 1, 101102, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんは\n夜強いんですね\n私は眠くて…", 2, 491, 1, 3, 1, 101102, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("服装や髪形が変わると\n気分も変わるよね", 3, 492, 1, 1, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここで寝ちゃったら\n受験勉強が～…\nぐーー", 3, 493, 1, 2, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい♪\n私が服を作って\nあげよっか？", 3, 494, 1, 3, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いまならどんな試験も\n合格できそうです！", 3, 495, 1, 4, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("のんびりしたら\nまた勉強しよっと！", 3, 496, 1, 5, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんを\n守るためには\n毎日、鍛えなくちゃ！", 3, 497, 1, 6, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいし～！\nお兄ちゃんにも\nおすそ上げしますね！", 3, 498, 1, 7, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本の服\nかわいいなぁ♪\n私に作れるかな？", 3, 499, 1, 8, 1, 101102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("う～ん、今なら\nどこでだって\n眠れちゃいそう…", 1, 501, 1, 1, 1, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たくさん寝すぎて、\n夢の中か現実か\nわかんなく\nなっちゃうんだよね～", 1, 502, 1, 2, 1, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…はっ！？\nね、寝てないよ？\nホントだよっ", 1, 503, 1, 3, 1, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぐっすり眠って\nパワーを\nフルチャージっ☆", 1, 504, 1, 4, 1, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もし、超能力のことが\nバレたら…ブルブル", 1, 505, 1, 5, 1, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("テレパシーで\nキミの心を覗けたら\n…なんてね！", 1, 506, 1, 101, 4, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミを抱き枕に…\nじょ、冗談冗談！", 1, 507, 1, 102, 8, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～、なになに？\n一緒にお昼寝する？", 2, 508, 1, 1, 1, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("忘れ物しちゃった。\nま、いっか！\nえ、ダメ？", 2, 509, 1, 2, 1, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おおっ、相談ごと？\nなにかな\nなにかな～？", 2, 510, 1, 3, 1, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("う～ん、もしかして\nキミにも仲良しになる\n超能力があるのかも！", 2, 511, 1, 4, 1, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むむ～…どう？\nテレパシーで、私の\n気持ちを送ったよ！", 2, 512, 1, 101, 4, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えっ？　私とキミとの\n相性？　むむ～…\nうん、バッチリだよ☆", 2, 513, 1, 102, 8, 101201, 0, 0);
