INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("全然読めない～\nそだ、ヒデサイに\n読んでもらおっと！", 3, 599, 1, 8, 1, 101602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっさー\n踊ってると、どんどん\n楽しくなるさー！", 1, 601, 1, 1, 1, 101701, 0, 0);
