INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハイターイ！　元気な\nあいさつが一番さ～！", 1, 603, 1, 3, 1, 101701, 0, 0);
