INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("空手の型の\n練習するさー\nキミもどう？", 2, 611, 1, 4, 1, 101701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よ～し、手をつないで\n踊るさ～！\n恥ずかしがること\nないさ～", 2, 612, 1, 101, 4, 101701, 0, 0);
