INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("勉強勉強で\n疲れたよね？\n膝枕してあげる！", 2, 659, 1, 2, 1, 101801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("テストがんばったね～\nご褒美に先生が\n特別な授業\nしてあげるね？", 2, 660, 1, 3, 1, 101801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("学院の外でも\n私は君の先生よ\nなんでも聞いてね♪", 2, 661, 1, 4, 1, 101801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今読んでるのは\nヒロインが年下の子と\n恋に落ちる話…あ、\n深い意味はないのよ～", 2, 662, 1, 101, 4, 101801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("生徒は全員可愛いけど\n君は少し特別…\nみんなには内緒よ？", 2, 663, 1, 102, 8, 101801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("学校に\n遅刻しないように\n早く準備しないとね", 2, 664, 1, 1, 1, 101801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("男の子といっしょに\nお弁当を食べるの、\n夢なんだ～", 2, 665, 1, 2, 1, 101801, 2, 0);
