INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("勉強勉強で\n疲れたよね？\n膝枕してあげる！", 2, 684, 1, 2, 1, 101802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("宿題はもうやった？\n苦手なところは\n先生が見てあげる♪", 2, 685, 1, 3, 1, 101802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んん？　なんだか\n元気がないみたい\n先生がぎゅぅ～って\nしてあげる…　", 2, 686, 1, 4, 1, 101802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君のお勉強も\nだいぶ進んできたね～\n補習卒業も近いかな？\n少し寂しいけど…", 2, 687, 1, 101, 8, 101802, 0, 0);
