INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子を相手に、\n演技の練習～", 3, 769, 1, 3, 1, 102101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リボンや服に\n染み込ませておこう。\nいつでもいい匂い♪", 3, 770, 1, 4, 1, 102101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ。\nぽっかぽかです…", 3, 771, 1, 5, 1, 102101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁはぁ…\nふひぃ…\nはうぅぅぅ～～", 3, 772, 1, 6, 1, 102101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…えへへ、\n美味しいものを\n食べてると幸せです", 3, 773, 1, 7, 1, 102101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戯曲を読んで\n自分が演じるところを\n想像するの…", 3, 774, 1, 8, 1, 102101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいものを\nこうして並べて…\nはぁ…落ちつくぅ♪", 1, 776, 1, 1, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁ～、この部屋は\n時間がゆったりと\n流れてるみたい", 1, 777, 1, 2, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この台本、感動…\n涙が止まらないよぉ\nいつか演じてみたいな", 1, 778, 1, 3, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お芝居には\n人間観察が大事…\nじーーーーーー…", 1, 779, 1, 4, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あえいうえおあお\nかけきくけ、かっ…\nむ、難しいですぅぅ", 1, 780, 1, 5, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、お腹が空いた時は\n言ってくださいね\nが、頑張って\n作ります！", 1, 781, 1, 101, 8, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("れ、恋愛劇…\nお、お兄ちゃんと\n練習…", 1, 782, 1, 102, 8, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こ、この本、とっても\nおもしろいんですよ♪", 2, 783, 1, 1, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんと\nいっぱい話せた日は、\n嬉しくなっちゃいます", 2, 784, 1, 2, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何か私にできる事\n…そうだ！\nお掃除しますね！", 2, 785, 1, 3, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私、ちょっとずつ、\n自分に自信が\nついてきたかもです…", 2, 786, 1, 4, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リボンがかわいい？\nほ、ほぇぇぇ～～\nは、恥ずかしいですぅ", 2, 787, 1, 101, 8, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃん…♪\nえへへ、呼んでみた\nだけです…♪", 2, 788, 1, 102, 8, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます♪\n声出しして、お芝居の\n練習しなくちゃ", 2, 789, 1, 1, 1, 102102, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お茶にしますか？\nクッキー焼いたので、\nよかったら…", 2, 790, 1, 2, 1, 102102, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寝る前に\n台本を読むと、\n覚えやすいんです", 2, 791, 1, 3, 1, 102102, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("可愛い女の子に変身！\n出来ますように…♪", 3, 792, 1, 1, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぅ…\nフッカフカァ…\n癒されちゃいます…", 3, 793, 1, 2, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子を相手に\n演技の練習～", 3, 794, 1, 3, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リボンや服に\n染み込ませておこう\nいつでもいい匂い♪", 3, 795, 1, 4, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ\nぽっかぽかです…", 3, 796, 1, 5, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え、演劇には\nた、体力も重要\nだから～", 3, 797, 1, 6, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("残さず\n食べますね…！", 3, 798, 1, 7, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戯曲を読んで\n自分が演じるところを\n想像するの…", 3, 799, 1, 8, 1, 102102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、人見知りを\n治すための練習に\n付き合ってくれない？", 1, 801, 1, 1, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アカリみたいに\nかわいくなるには、\nどうすればいいのかな", 1, 802, 1, 2, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レアカードをゲット！\nねえねえ、\nすごいでしょ！？", 1, 803, 1, 3, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ア、アイツと同じ\n部屋にいるのよね…\nって、だから何よ！？", 1, 804, 1, 4, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("楽しいゲームって\nやめどきが\n見つからないわ", 1, 805, 1, 5, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もっと女の子らしく\nなったらアイツも\n嬉しいかな…って、\n何考えてるの！？", 1, 806, 1, 101, 4, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うぅ…最近、\nアイツを見るとなんか\nドキドキするのよね", 1, 807, 1, 102, 8, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ゲームに負けた罰\nだからって、\nくすぐるのは…\nあはは…ダメだって！", 2, 808, 1, 1, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンタと話すのは割と\n緊張しないのよね\n…なんでかな", 2, 809, 1, 2, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("待ちきれない…\n新作ゲームの発売日が\n待ちきれない…", 2, 810, 1, 3, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンタは人見知り\nしないタチよね？\nいいなあ～…", 2, 811, 1, 4, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ア、アンタってさ\n好きな人とかい…\nなな、何でもない！", 2, 812, 1, 101, 4, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンタと…そ、その\nこうして話してるのも\nわわ、悪くないわね！", 2, 813, 1, 102, 8, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おおおおはよう！\n…よし！　ちゃんと\nあいさつできたわ！", 2, 814, 1, 1, 1, 102201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒にごはんとか…\nううん、やっぱいい！\nなんでもないからっ！", 2, 815, 1, 2, 1, 102201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜はこれからよ！\n朝まで\nゲームするからね！", 2, 816, 1, 3, 1, 102201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アカリみたいに\n可愛くなるのは\n難しいかな", 3, 817, 1, 1, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寝っ転がりながら\nゲームができれば\n気分が良さそう", 3, 818, 1, 2, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("可愛い…けど、\n私には似合わないかな", 3, 819, 1, 3, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はあ、リラックスして\nゲームができるわ", 3, 820, 1, 4, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん…暖かくて、\n寝落ちしちゃいそう", 3, 821, 1, 5, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ゲーム感覚でやると、\n体動かすのも\n楽しいわね", 3, 822, 1, 6, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ゲームは頭使うから\nそのぶん\n栄養がいるのよ", 3, 823, 1, 7, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ、なるほど\n友だちを作るには\n笑顔が大事っと…", 3, 824, 1, 8, 1, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さあ、今日は\n何のゲームで\n遊ぼうかな？", 1, 826, 1, 1, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒にゲームができる\n人がいるっていうのも\n新鮮だな…", 1, 827, 1, 2, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レアカードをゲット！\nすごいでしょ！？", 1, 828, 1, 3, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アカリってどうやって\n友達作ってるんだろ？\nコツがあるのかな…", 1, 829, 1, 4, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("楽しいゲームって\nやめどきが\n見つからないわ", 1, 830, 1, 5, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うぅ…最近\nアイツを見るとなんか\nドキドキするのよね", 1, 831, 1, 101, 8, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ね、ねえ\nもう少しその…\n一緒にゲームしない？", 1, 832, 1, 102, 8, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、人見知りを\n治すための練習に\n付き合ってくれない？", 2, 833, 1, 1, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("欲しいゲームが\n見つからなくて…\n探すの手伝って！", 2, 834, 1, 2, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、見て！\n新しいゲームを\n買って来たの！", 2, 835, 1, 3, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ゲームに負けた罰\nだからって、くすぐる\nのは…あ、あはは！\nだ、ダメだって！", 2, 836, 1, 4, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ア、アンタってさ\n好きな人とかい…\nなな、何でもない！", 2, 837, 1, 101, 8, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、あのさ…\nもう少し、そこに\nいてくれてもいいわよ", 2, 838, 1, 102, 8, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おおおおはよう！\n…よし！　ちゃんと\nあいさつできたわ！", 2, 839, 1, 1, 1, 102202, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒にごはんとか…\nううん、やっぱいい！\nなんでもないからっ！", 2, 840, 1, 2, 1, 102202, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜はこれからよ！\n朝まで\nゲームするからね！", 2, 841, 1, 3, 1, 102202, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もっと女の子らしく\nなったらアイツも\n嬉しいかな…って、\n何考えてるの！？", 3, 842, 1, 1, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふああ…\n徹夜明けには\n辛い誘惑だな…", 3, 843, 1, 2, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("可愛い…けど、\n私には似合わないかな", 3, 844, 1, 3, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうのに詳しいと\n女の子っぽく\n見えたりするのかな", 3, 845, 1, 4, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寒い日は\nここでゲームするのが\n最高のぜいたくよね", 3, 846, 1, 5, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近ゲームばかりだし\nたまにはいいかな？", 3, 847, 1, 6, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ゲームは頭使うから\nそのぶん\n栄養がいるのよ", 3, 848, 1, 7, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ、なるほど\n友だちを作るには\n笑顔が大事っと…", 3, 849, 1, 8, 1, 102202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じゃんけんぽん！\nあっち向いてほい！\nあ～ん、負けたぁ\n　『勝ったぜ！』", 1, 851, 1, 1, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷうきちがいれば、\nなんでも出来ちゃうよ", 1, 852, 1, 2, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("発声練習しよっと\nぷうきち\nフルスイ～ング！", 1, 853, 1, 3, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここで、ぷうきち\nフルスイングは、\nまずいかな～？", 1, 854, 1, 4, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この部屋、ぷうきちを\n置く場所はないのかな", 1, 855, 1, 5, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんって…\nちょっとぷうきちに\n似てるかも♪", 1, 856, 1, 101, 4, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんにも、\nぷうきちのこと\n好きになって\nもらいたいな～", 1, 857, 1, 102, 8, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おやつは、\n私とぷうきちの\n二人分用意してね♪", 2, 858, 1, 1, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷうきちが、お腹\nペコペコだって～\n何かちょうだい！", 2, 859, 1, 2, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『アヤネに手出したら\n…坊ちゃんでも、\n分かってんな？』", 2, 860, 1, 3, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷうきちとの\n連携を磨いてるの！\nもっと仲良くなるよ！", 2, 861, 1, 4, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("特別だからね？\nもっと触っていいよ\n…ぷうきちのこと", 2, 862, 1, 101, 4, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんのこと、\n「ぷう兄」って\n呼ぼうかな？", 2, 863, 1, 102, 8, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんって\n朝早いんだね～\n私はまだ眠いよ～", 2, 864, 1, 1, 1, 102301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁ～…ぷうきちと\nお昼寝してくるね…", 2, 865, 1, 2, 1, 102301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷうきちと\nおしゃべりしてたら\nもうこんな時間…", 2, 866, 1, 3, 1, 102301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『座り心地がいいな』\nぷうきちは座れない\nでしょ？", 3, 868, 1, 2, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい～！\nぷうきちのお友達に\nしちゃおうかな？", 3, 869, 1, 3, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいニオイ～♪\nぷうきちも\n気に入ったみたい！", 3, 870, 1, 4, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽわぽわする～\nぷうきちも\n気持ちいい？", 3, 871, 1, 5, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしい～\nぷうきちも\n食べてみる？", 3, 873, 1, 7, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷうきち！\nこの本、読んで～！", 3, 874, 1, 8, 1, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうして失敗ばっかり\nこうなったら\n腹を切るしか～！", 1, 901, 1, 1, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あれ？　あれ？\nお部屋の中で迷子に\nなっちゃいました～", 1, 902, 1, 2, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたら転ばなく\nなるんでしょうか？", 1, 903, 1, 3, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わわわわ～～っ\nふう…\nきゃ、きゃあっ！", 1, 904, 1, 4, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私のドジで、\nこのお部屋を\n壊しちゃったら\nどうしましょう～～", 1, 905, 1, 5, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしい料理で\nお出迎えしなくちゃ！", 1, 906, 1, 101, 4, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一生懸命\nご奉仕しますよ～♪", 1, 907, 1, 102, 8, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("耳かきしましょうか？\nえ？　こわい？", 2, 908, 1, 1, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お疲れでしたら、\nお昼寝しませんか？\n膝枕もしますよ？", 2, 909, 1, 2, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おかえりなさいませ\nご主人さま♪", 2, 910, 1, 3, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すみません\nすみません\nすみません～～", 2, 911, 1, 4, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メイドの私が、\nこんな気持ちを持って\nいいんでしょうか…", 2, 912, 1, 101, 4, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私のこと、\n専属メイドと思って\n頼ってくださいね", 2, 913, 1, 102, 8, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます♪\n今日も一日がんば…\nきゃ、きゃあ！", 2, 914, 1, 1, 1, 102501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ごはん…\n失敗しちゃいましたぁ\nお、おやつでリベンジします！", 2, 915, 1, 2, 1, 102501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日の目標は\nドジをしないです！\nき、昨日の目標も\nドジをしないでした", 2, 916, 1, 3, 1, 102501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、メイド服が\nほつれてる\n後でお裁縫しなくちゃ", 3, 917, 1, 1, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休憩が終わったら\nお洗濯にお料理に\nお掃除もしないと！", 3, 918, 1, 2, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい♪\nあとでお洗濯\nしてあげますね", 3, 919, 1, 3, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…\nお嬢様のお部屋にも\n置いてあげたいです", 3, 920, 1, 4, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここでお洗濯ものを\n乾かしましょうか", 3, 921, 1, 5, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あわわわっ…\nこ、転びそうです～！", 3, 922, 1, 6, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これくらい\nおいしいものを\n作ってみたいです～", 3, 923, 1, 7, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("物語のメイドさんって\n御主人さまを好きに\nなるんですよね…", 3, 924, 1, 8, 1, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("失敗したら、この\nお部屋追い出され\nちゃうかも～？", 1, 926, 1, 1, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あれ？　あれ？\nお部屋の中で迷子に\nなっちゃいました～", 1, 927, 1, 2, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうやったら、立派な\nメイドになれるのかな", 1, 928, 1, 3, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("塩にはＳマーク\n砂糖にはＳマーク\n…あ、あれ！？", 1, 929, 1, 4, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ご用があれば\nなんでも言って\nくださいね", 1, 930, 1, 5, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("迷惑をかけすぎて…\n嫌われちゃったら\nどうしましょう", 1, 931, 1, 101, 8, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メイドの私が\nこんな気持ちを持って\nいいんでしょうか…　", 1, 932, 1, 102, 8, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おでかけですか？\nいってらっしゃいませ\nご主人さま♪", 2, 933, 1, 1, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうして失敗ばっかり\nこうなったら\n腹を切るしか～！", 2, 934, 1, 2, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私、またなにか\nやっちゃいましたか？", 2, 935, 1, 3, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしいお茶っ葉が\n手に入りました～♪\n一緒に飲みませんか？", 2, 936, 1, 4, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("転んだふりであの人に\n…って！\nなんでもないですよ！", 2, 937, 1, 101, 8, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私、できることなら\nなんでもやりますよ\nあなたのためですから", 2, 938, 1, 102, 8, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます♪\n今日も一日がんば…\nう、うわあ！", 2, 939, 1, 1, 1, 102502, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ごはん…\n失敗しちゃいましたぁ\nお、おやつでリベンジします！", 2, 940, 1, 2, 1, 102502, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日の目標は\nドジをしないです！\nき、昨日の目標も\nドジをしないでした", 2, 941, 1, 3, 1, 102502, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、メイド服が\nほつれてる\n後でお裁縫しなくちゃ", 3, 942, 1, 1, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい座り心地です～\nこれならお嬢さまも\nゆったりできますね♪", 3, 943, 1, 2, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい♪\nあとでお洗濯\nしてあげますね", 3, 944, 1, 3, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…\nお嬢様のお部屋にも\n置いてあげたいです", 3, 945, 1, 4, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かいですけど\n…私が火に近づいて\n大丈夫でしょうか！？", 3, 946, 1, 5, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("運動しようとすると\nいつも怪我するん\nですよね…", 3, 947, 1, 6, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなに美味しいもの\nメイドの私には\nもったいないです～！", 3, 948, 1, 7, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("物語のメイドさんって\n御主人さまを好きに\nなるんですよね…", 3, 949, 1, 8, 1, 102502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの方と私だけの\n部屋にしたいですわ", 1, 951, 1, 1, 1, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの方は私のもの…\n眼も耳も鼻も口も髪も\n首も胸も腰も手も脚も\nぬくもりも心も…！", 1, 952, 1, 2, 1, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("運命とは決して\n抗えないもの…\nクスクス…クスクス", 1, 953, 1, 3, 1, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋からあの方の\n香りが…\nああ、至福ですわ", 1, 954, 1, 4, 1, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("毒にも薬にもならない\n存在なんて嫌ですわ\nどうせならとびきりの\n毒でありたい…", 1, 955, 1, 5, 1, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クスクス…\nあの方とデートする\nイメトレ中ですわ\nクスクスクスクス…", 1, 956, 1, 101, 4, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("記憶を戻す研究より\n記憶をねつ造する研究\nのほうが良いかしら？\n伴侶という設定で…", 1, 957, 1, 102, 8, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("運命を信じますか？\nもちろん絶対当然\n信じますわよね？", 2, 958, 1, 1, 1, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この薬は起床時就寝前\n食前食後食間に、毎日\n服用してください。\n惚れ薬ですわ", 2, 959, 1, 2, 1, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お願いがあるのです。\n新しい研究の実験台に\n…", 2, 960, 1, 3, 1, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっそり栽培している\n毒きのこが毒々しく\n育ちましたわ…", 2, 961, 1, 4, 1, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなた様の前では\n普通の女の子…\n少し毒薬づくりが\n得意なだけの…", 2, 962, 1, 101, 4, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の身も心も、全てが\nあなた様のもの。\nあなた様の全ても…", 2, 963, 1, 102, 8, 102701, 0, 0);
