INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さっ！　家の中でも\n効率的に\nトレーニングよ！", 3, 1047, 1, 6, 1, 102802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しっかり食べて\n栄養補給、栄養補給！", 3, 1048, 1, 7, 1, 102802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("知識から過去を学んで\n未来に活かすわよ", 3, 1049, 1, 8, 1, 102802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("可愛い子が\nいっぱいいるなぁ…\n誰か私とユニット\n組んでくれないかな？", 1, 1051, 1, 1, 1, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度のライブ会場、\nいつもより大きいから\n楽しみなんだ～！", 1, 1052, 1, 2, 1, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新曲の衣装、もうすぐ\n出来あがるんだって！\n楽しみだな～", 1, 1053, 1, 3, 1, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼とデュエット\nしてみたいな～♪", 1, 1054, 1, 4, 1, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キラキラ無病息災、\nドキドキ一日一善…\n作詞って難しい～", 1, 1055, 1, 5, 1, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ファンはもちろん\n大事だけど…\n彼のことは、もっと\n大切にしたいな…", 1, 1056, 1, 101, 4, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("写真集見なくても、\n本物がここに\nいるのにな～", 1, 1057, 1, 102, 8, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("握手会の練習、\n付き合ってくれない？", 2, 1058, 1, 1, 1, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("写真集のポーズ\n練習中～！\nど、どうかな？", 2, 1059, 1, 2, 1, 102901, 0, 0);
