INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ね、次のライブ\n観に来てくれる？\nいい席とっとくから！", 2, 1061, 1, 4, 1, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇ、台本読むの\nつきあってくれる？\n恋人役に\nなってほしいんだ", 2, 1062, 1, 101, 4, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新曲、聞いてくれた？\nキミとのことを\nテーマにしたんだよ。\nどこかは秘密だけど♪", 2, 1063, 1, 102, 8, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝の発声練習に\n行くけど、キミも\n一緒に来ない？", 2, 1064, 1, 1, 1, 102901, 1, 0);
