INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の帳が二人を包み\n…こういう方向性の\n歌詞も悪くないなぁ。", 2, 1066, 1, 3, 1, 102901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身だしなみオッケー！\nアイドルはいつでも\n完璧でいなくちゃ！", 3, 1067, 1, 1, 1, 102901, 0, 0);
