INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むむ、アクダイカンの\n気配がするデース", 1, 1129, 1, 4, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クニトリ合戦\n楽しみデース！", 1, 1130, 1, 5, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近、ショーグンの\nそばにいると\nドキドキするデス…", 1, 1131, 1, 101, 8, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグンの身は\n何があってもワタシが\n守るデス！", 1, 1132, 1, 102, 8, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、ショーグン\n出陣はいつで\nゴザルデス！？", 2, 1133, 1, 1, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イクサの前に\nホネ休めも大事デスよ\nゆっくりするデース！", 2, 1134, 1, 2, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さ、さすがショーグン\nデス…いつの間に\n背後を！？", 2, 1135, 1, 3, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒に忍法考える\nデス！\nショーグン用の\n忍法も必要デスね！", 2, 1136, 1, 4, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見つめられると\nドキドキするデス…\n新しい忍法デスか？", 2, 1137, 1, 101, 8, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグン！\nえへへ…これからも\nおそばに置いて\nクダサイね？", 2, 1138, 1, 102, 8, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい朝デス！\nトーゴク風の朝ゴハン\n作るデス！", 2, 1139, 1, 1, 1, 103002, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうお昼デス\nお昼寝するデスか？", 2, 1140, 1, 2, 1, 103002, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろおネム\nデース…\n一緒に寝るデス？", 2, 1141, 1, 3, 1, 103002, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("服の乱れは心の乱れ\nデス！　きっちり\nしないといけないデス", 3, 1142, 1, 1, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("心地よくて眠く\nなってきマス…\nもしやテキコクの\n罠デスか！？", 3, 1143, 1, 2, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これを変わり身の\n術に…かわいそう\nだから止めるデス", 3, 1144, 1, 3, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワビサビというもの\nデスね！\n素晴らしいデス！", 3, 1145, 1, 4, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身体を暖めてイクサに\n向かうデス！", 3, 1146, 1, 5, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグンのお役に\n立つため、修行\nあるのみデス！", 3, 1147, 1, 6, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美味しいデス…\n酢昆布を和えて\nみたいデス", 3, 1148, 1, 7, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("物事を知って\n来たるべきイクサに\n活かすデス", 3, 1149, 1, 8, 1, 103002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さん、そろそろ\n子離れを…しない？\nそうですか…", 1, 1151, 1, 1, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("父は、いつも男性に\nきびしいですね", 1, 1152, 1, 2, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("占ってほしい人は、\nいつでも言って\nください", 1, 1153, 1, 3, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの手相は…\nて、手を握るのって\n緊張しますね", 1, 1154, 1, 4, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この部屋、風水的にも\n運気が上がりそうです", 1, 1155, 1, 5, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人とのこと占って\nみようかな…\n好き…嫌い…\n好き♪…き、嫌い", 1, 1156, 1, 101, 4, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私との相性ですか？\nそれなら占う必要は\nありませんよ…\nふふっ♪", 1, 1157, 1, 102, 8, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("女難の相が\n出ていますね…\n気をつけてください", 2, 1158, 1, 1, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のあなたの運勢は\n大きょ…\n大吉です", 2, 1159, 1, 2, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("父と散歩中です。\n毎日決まったコースを\n散歩させないと、\nストレスが溜まるので", 2, 1160, 1, 3, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("小僧！\nシノブに触るとは\nいい度胸じゃねぇか！", 2, 1161, 1, 4, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたに触られると、\n動悸が早くなります\nもしかして心霊現象？", 2, 1162, 1, 101, 4, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もたくさんの幽霊\nに慕われていますね。\n素敵です", 2, 1163, 1, 102, 8, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n今日の運勢を\n占いましょうか？", 2, 1164, 1, 1, 1, 103101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のラッキー\nアイテムはドクロです\n良ければ父を\nお貸ししましょうか？", 2, 1165, 1, 2, 1, 103101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のあなたの運気は\n最高潮でした。\nもうすぐ今日は\n終わりますが", 2, 1166, 1, 3, 1, 103101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さん。\nいつも、身だしなみに\n気を使ってるけど、\nあまり変わってないよ", 3, 1167, 1, 1, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一休みしましょう。\n憑かれて疲れました", 3, 1168, 1, 2, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい…\n付喪神が宿らないかな", 3, 1169, 1, 3, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さん、\nリラックスし過ぎると\n成仏しちゃうよ？", 3, 1170, 1, 4, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちいいです…\n極楽浄土みたい…", 3, 1171, 1, 5, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁはぁ…\nお、お父さん、\n代わりに運動して…", 3, 1172, 1, 6, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さんも\n食べたいの？\n死んでるのに？", 3, 1173, 1, 7, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本…\nもしかして予言書？", 3, 1174, 1, 8, 1, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいる幽霊は\nみんな幸せそうです", 1, 1176, 1, 1, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さんが\n女の子ばかりに\n声をかけるので\n困っています", 1, 1177, 1, 2, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("成仏はうれしいこと\nです…でも友達が\n減るのは寂しいですね", 1, 1178, 1, 3, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("幽霊に好かれる人は\n素敵な方です\nもちろん、あなたも", 1, 1179, 1, 4, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さん、そろそろ\n子離れを…しない？\nそうですか…", 1, 1180, 1, 5, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("生きている人に\n好かれるには、\nどうすればいい\nのでしょう？", 1, 1181, 1, 101, 8, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さん、どうしたら\nあの人のことを\n認めてくれますか？", 1, 1182, 1, 102, 8, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この部屋、風水的にも\n運気が上がりそうです", 2, 1183, 1, 1, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シノブには指一本\n触れさせん！\nガブッ！！", 2, 1184, 1, 2, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの手相は…\nて、手を握るのって\n緊張しますね", 2, 1185, 1, 3, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ラップ音？\nいえ、父のいびきです", 2, 1186, 1, 4, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私との相性ですか？\nそれなら占う必要は\nありませんよ…\nふふっ♪", 2, 1187, 1, 101, 8, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("前世って信じますか？\n私とあなたは\nもしかすると…", 2, 1188, 1, 102, 8, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のラッキー\nアイテムはドクロです\n良ければ父を\nお貸ししましょうか？", 2, 1189, 1, 1, 1, 103102, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明るい時間は\nあまり得意では\nないんです…", 2, 1190, 1, 2, 1, 103102, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜のお散歩に\n行きませんか？\n知り合いの幽霊に\n挨拶して回るんです", 2, 1191, 1, 3, 1, 103102, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さん\nいつも、身だしなみに\n気を使ってるけど\nあまり変わってないよ", 3, 1192, 1, 1, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うとうと…\nあれ…\n走馬灯が見える…", 3, 1193, 1, 2, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい…\nお父さんみたい…", 3, 1194, 1, 3, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さん\nリラックスし過ぎると\n成仏しちゃうよ？", 3, 1195, 1, 4, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("快適です…\n幽霊もどんどん\n集まってきますね…", 3, 1196, 1, 5, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁはぁ…\nお、お父さん、\n代わりに運動して…", 3, 1197, 1, 6, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さんの分も、\n私が食べるね", 3, 1198, 1, 7, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本の占い\n私の占いと違う…", 3, 1199, 1, 8, 1, 103102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私だって、一人で\n買い物ぐらい\nできますわ…きっと", 1, 1201, 1, 1, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ新しい\n案件を始めないと\nいけませんわね", 1, 1202, 1, 2, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一日も早く、\n一人前の商人に\nなりたいものです", 1, 1203, 1, 3, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("平和を買うのには\nどれほどのお金が\n必要なのかしら？", 1, 1204, 1, 4, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここももう少し広いと\n落ち着くのですけど。\n改築しませんこと？", 1, 1205, 1, 5, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの方はお金で雇った\nわけではないのに\n私といてくださる…", 1, 1206, 1, 101, 4, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たとえ私が間違っても\nきっとあの方が\n正してくれますわ…", 1, 1207, 1, 102, 8, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私と、庶民向けの\nお店へ一緒に\n参りませんか？", 2, 1208, 1, 1, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("資産運用？\nお幾らほど\n増やしたいのです？", 2, 1209, 1, 2, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんぶり勘定だとよく\n言われるのですが…\n例えが小さすぎます！", 2, 1210, 1, 3, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お金で解決するのは\n悪いことでは\nありませんわよね？", 2, 1211, 1, 4, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("その、よろしければ\n私とお散歩など\nいかがです？", 2, 1212, 1, 101, 4, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もしあなたさまが\n道に迷われるなら、\n私もお供いたします！", 2, 1213, 1, 102, 8, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早起きは三ルピの徳と\n申しますが…\nもっとお得ですわね", 2, 1214, 1, 1, 1, 103201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食は町の屋台で\n立ったまま食べて\nみたいですわ！", 2, 1215, 1, 2, 1, 103201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よろしければ\nお休み前のミルクを\n御一緒にいかが？", 2, 1216, 1, 3, 1, 103201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("だらしない身なりでは\n取引相手に信用して\nいただけませんものね", 3, 1217, 1, 1, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この感触と安らぎ…\n素晴らしい\n費用対効果ですわ…", 3, 1218, 1, 2, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何の見返りも求めず\nただひたすら愛でて\nいたいのです！", 3, 1219, 1, 3, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("目に見えないものに\nお金をかけるのが\n真の贅沢ですわ！", 3, 1220, 1, 4, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誰ひとり寒い思いを\nしない町にするために\n私にできる事は…", 3, 1221, 1, 5, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("健康はお金では\n買えませんが\n運動器具は別ですわ！", 3, 1222, 1, 6, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なかなか\n美味ですわ\nシェフはどちらに？", 3, 1223, 1, 7, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("経済の仕組みを\nしっかりと\n学ばなくては…", 3, 1224, 1, 8, 1, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ新しい\n案件を始めないと\nいけませんわね", 1, 1226, 1, 1, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ええと、これは\nおいくらで買ったん\nでしたっけ？", 1, 1227, 1, 2, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お金を見せたら\n態度が変わる人は\n信用できませんわ", 1, 1228, 1, 3, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("地図が読めずとも\n道に迷わない方って\nいらっしゃるのですね", 1, 1229, 1, 4, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この狭さも\n慣れれば\n快適ですわ♪", 1, 1230, 1, 5, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの方はお金で雇った\nわけではないのに\n私といてくださる…", 1, 1231, 1, 101, 8, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たとえ私が間違っても\nきっとあの方が\n正してくれますわ…", 1, 1232, 1, 102, 8, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一人前の商人に\n相応しい居振る舞いを\nしたいものですわ", 2, 1233, 1, 1, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("幼い頃\nお店屋さんごっこを\nなさいましたか？", 2, 1234, 1, 2, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("資産運用？\nお幾らほど\n増やしたいのです？", 2, 1235, 1, 3, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度一緒に…\nパーティにでも\n行きませんこと？", 2, 1236, 1, 4, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("その、よろしければ\n私とお散歩など\nいかがです？", 2, 1237, 1, 101, 8, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたさまの優しさは\nお金には\n代えられませんわね", 2, 1238, 1, 102, 8, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なぜだか\n眠り足りないような\n感じがしますわ…", 2, 1239, 1, 1, 1, 103202, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食は町の屋台で\n立ったまま食べて\nみたいですわ！", 2, 1240, 1, 2, 1, 103202, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よろしければ\nお休み前のミルクを\n御一緒にいかが？", 2, 1241, 1, 3, 1, 103202, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドレスは汚れていない\nようですが…やだ\n髪がほつれてますわ！", 3, 1242, 1, 1, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういったものに\n腰を沈めると…\nき、気が緩んで…", 3, 1243, 1, 2, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何の見返りも求めず\nただひたすら愛でて\nいたいのです！", 3, 1244, 1, 3, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("香りは質のいいものと\nそうでないものが\nはっきり分かりますわ", 3, 1245, 1, 4, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誰ひとり寒い思いを\nしない町にするために\n私にできる事は…", 3, 1246, 1, 5, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("目標は遠くに\n置いた方が励みに\nなりますわ！", 3, 1247, 1, 6, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なかなか\n美味ですわ\nシェフはどちらに？", 3, 1248, 1, 7, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("商人って、物語では\n悪役にされやすいの\nですね…", 3, 1249, 1, 8, 1, 103202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("家の中のものを使って\n物ボケ、考えるべ！", 1, 1251, 1, 1, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("毎日の日課…それは\n炊事、洗濯、大喜利\nだべ！", 1, 1252, 1, 2, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちに塀ができたら、\nへー、って言いたい！", 1, 1253, 1, 3, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オラが作る料理は\nこの後スタッフで\n美味しくいただくべよ", 1, 1254, 1, 4, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エリザベスも\n連れてきてぇ～", 1, 1255, 1, 5, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんちゃんも、\nエリザベスと同じ位\nめんこいべ♪", 1, 1256, 1, 101, 4, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オラとあんちゃん、\n息がぴったりに\nなってきたべ…！", 1, 1257, 1, 102, 8, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おぉ！　そんな急に\nツッコまれたら、\nびっくらこくべやー！", 2, 1258, 1, 1, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ネタはオラが書くけど\nあんちゃんが\n書きたかったら\n書いてもいいんだぞ？", 2, 1259, 1, 2, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんちゃん、オラには\n容赦なんかせずに\nツッコんでくれて\nいいから！", 2, 1260, 1, 3, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("押すなよ、\n絶対押すなよ\n…なんて\n言ってないべさ？", 2, 1261, 1, 4, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うう…あんちゃんに\nツッコまれたくて\nうずうずしてきたべ～", 2, 1262, 1, 101, 4, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("将来的には夫婦漫才\nってのも…あ、ひ、\nひとりごとだべさ～！", 2, 1263, 1, 102, 8, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！　一緒に\n牛の乳しぼりいくべ？", 2, 1264, 1, 1, 1, 103301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼だ～腹が減っては\n笑いはできぬ～！", 2, 1265, 1, 2, 1, 103301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もよく働いたべ！\nさ、今からは\nお笑いの練習だ～！", 2, 1266, 1, 3, 1, 103301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("舞台に上がる前に\n身なりは整えねぇと\nだめだべ～！", 3, 1267, 1, 1, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ナイスなイスに\n座りたい、\nなんちゃって！", 3, 1268, 1, 2, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("めんこいのは、\nスベっても許される\nからずるいべな～？", 3, 1269, 1, 3, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("必要以上に\n癒されちまうべや～", 3, 1270, 1, 4, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽかぽかだ…\nウケた会場みてぇだ", 3, 1271, 1, 5, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お笑い芸人は、\n体が資本だべさ～！", 3, 1272, 1, 6, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…\nボケることも\n忘れちまう美味さだ～", 3, 1273, 1, 7, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ネタ作りのヒントが\n載ってねぇか探すべ", 3, 1274, 1, 8, 1, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さぁ今日も張り切って\n漫才の練習するべさ！", 1, 1276, 1, 1, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この部屋でも、商品\n売っていいんだべか？", 1, 1277, 1, 2, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眼鏡を頭の上に乗せて\n「メガネメガネ～」\nって言う練習した方が\nいいべか？", 1, 1278, 1, 3, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("漫才を持ち時間に\n収めるには、何度も\n練習するしかねぇべ", 1, 1279, 1, 4, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エリザベスも\n連れてきてぇ～", 1, 1280, 1, 5, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うう…あんちゃんに\nツッコまれたくて\nうずうずしてきたべ～", 1, 1281, 1, 101, 8, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんちゃんに\n採れたての食材を\n食わしてやりてぇ～", 1, 1282, 1, 102, 8, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("押すなよ\n絶対押すなよ\n…なんて\n言ってないべさ？", 2, 1283, 1, 1, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんちゃん、百連\nツッコミ特訓だ～！", 2, 1284, 1, 2, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんちゃん、オラには\n容赦なんかせずに\nツッコんでくれて\nいいから！", 2, 1285, 1, 3, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「なんでだべ～！」\nって言いながら\nツッコむといいべ！", 2, 1286, 1, 4, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あはは～あんちゃんの\nツッコミはやっぱり\n気持ちいいなぁ～", 2, 1287, 1, 101, 8, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("将来的には夫婦漫才\nってのも…あ、ひ\nひとりごとだべさ～！", 2, 1288, 1, 102, 8, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！\n今日もいい\nネタ作り日和だ！", 2, 1289, 1, 1, 1, 103302, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼だな\nご飯を食べたら、\nネタの練習するべ！", 2, 1290, 1, 2, 1, 103302, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間だべ\nネタ作りは\n明日にするべ…", 2, 1291, 1, 3, 1, 103302, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん…衣装、\nずれてねぇべか？", 3, 1292, 1, 1, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ナイスなイスに\n座りたい\nなんちゃって！", 3, 1293, 1, 2, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はう～\nなまらめんこいべや～", 3, 1294, 1, 3, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("必要以上に\n癒されちまうべや～", 3, 1295, 1, 4, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("笑いをとることを\n忘れるほど\nあったけぇべ～", 3, 1296, 1, 5, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たくさん運動して\n動きでも笑いがとれる\nように頑張るべ～！", 3, 1297, 1, 6, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…\nボケることも\n忘れちまう美味さだ～", 3, 1298, 1, 7, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("幅広く教養を\n身につけて\nいいネタ作るべ！", 3, 1299, 1, 8, 1, 103302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("通りにいる\nカップル…爆発\nすればいいのに…", 1, 1301, 1, 1, 1, 103401, 0, 0);
