INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近調子がいいのは\n牧場の牛乳やチーズの\nおかげでしょうか？", 2, 1386, 1, 4, 1, 103802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しおりを探している？\nあ、本に挟む方ですね\nドキドキしました…", 2, 1387, 1, 101, 8, 103802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の病気\n悪化してるのかも！？\nすごく胸がドキドキ\nするんです…", 2, 1388, 1, 102, 8, 103802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えっと、朝食の前には\nこの薬を飲んで…\n食後にはこの薬を…", 2, 1389, 1, 1, 1, 103802, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…お昼の薬？\nあ、飲み忘れてました\nありがとうございます", 2, 1390, 1, 2, 1, 103802, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この薬を飲むと\n眠くなっちゃうんです\nでもまだ、あなたと\nお話したいし～", 2, 1391, 1, 3, 1, 103802, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寝てばかりなので、\n髪が乱れてないかな\n…？　", 3, 1392, 1, 1, 1, 103802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し休もう\n…やっぱり\nたくさん休もう", 3, 1393, 1, 2, 1, 103802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子がいれば\n病室に一人でも\n寂しくないですね", 3, 1394, 1, 3, 1, 103802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いろんな効能が？\n健康になる香りも\nあるのでしょうか？", 3, 1395, 1, 4, 1, 103802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こうして温まって\nいると、病気も\n治る気がします", 3, 1396, 1, 5, 1, 103802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私も、少しは\n体力をつけないと\nいけませんよね　", 3, 1397, 1, 6, 1, 103802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いっぱい食べて\n健康な体にならないと", 3, 1398, 1, 7, 1, 103802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("続きが気になって\n読むのを止める\nタイミングが…", 3, 1399, 1, 8, 1, 103802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("友達ができたら、\n山の上でお弁当…\n夢が広がります…", 1, 1401, 1, 1, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、忘れずに\nお花に水を\nあげなきゃ…", 1, 1402, 1, 2, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子を作って、\nみなさんに振る舞って\n友達作戦！　とか…", 1, 1403, 1, 3, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ新しい\n草人形を作って\n友達作りの特訓を…", 1, 1404, 1, 4, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("植物のお世話って、\nぼっちにとっては、\n救い…なんです…", 1, 1405, 1, 5, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ＢＢ団の活動日…\nまだかな…\nうふふふっ", 1, 1406, 1, 101, 4, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もっともっとあの人の\nそばで、一緒に友達を\n作っていきたいな…", 1, 1407, 1, 102, 8, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、こんにちは！\n今日もＢＢ団で\nお世話になります！", 2, 1408, 1, 1, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの…私の友達作りの\n練習方法、間違って\nませんよね…？", 2, 1409, 1, 2, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうだ、今度、\n森に一緒に木の苗を\n植えに行きませんか？", 2, 1410, 1, 3, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人とお話するのって、\n私、大好きです！\n友達ふやすぞ～！", 2, 1411, 1, 4, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと話してると、\nまるで私がぼっちじゃ\nないみたいです！", 2, 1412, 1, 101, 4, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("友達もほしいけど…\nあなたに会えたことが\n私の一番の幸せです", 2, 1413, 1, 102, 8, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます！\n今日もＢＢ団、\nがんばるぞー！", 2, 1414, 1, 1, 1, 104001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだか、お腹が\n空いてきました。\nお昼ごはんー♪", 2, 1415, 1, 2, 1, 104001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう眠いかもです…\n明日は友達、\nできるといいなあ…", 2, 1416, 1, 3, 1, 104001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私がもっと\n可愛ければ、\n友達できるかなあ？", 3, 1417, 1, 1, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわあ…のんびり\nしすぎないように\n気を付けなきゃです", 3, 1418, 1, 2, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいなあ。\nこの子とも\n友達になりたい…", 3, 1419, 1, 3, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りです…\n精神統一して\n友達のイメトレ…", 3, 1420, 1, 4, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("灯りを見てると、\n心がなごみます～", 3, 1421, 1, 5, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…\nおいしいです…！\nみなさんもぜひ！", 3, 1422, 1, 6, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしいです…\n私に友達がいたら、\n分けてあげたいな", 3, 1423, 1, 7, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("友達作りの\n参考になりそうなこと\n書いてないかな～？", 3, 1424, 1, 8, 1, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("友達作りは、焦らず\n慌てず、じっくりと…", 1, 1426, 1, 1, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひとつ屋根の下\nって感じ…\nいいですねえ…", 1, 1427, 1, 2, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("煮汁、煮汁が\n噴きこぼれて\nいませんか～", 1, 1428, 1, 3, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度、みなさんと\nピクニックとか…\nいってみたいな", 1, 1429, 1, 4, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼっちでもいい\nたくましく育てば\n…なんて", 1, 1430, 1, 5, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近、毎日あの人の\nこと考えちゃいます\nどうしてだろう…", 1, 1431, 1, 101, 8, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もっともっとあの人の\nそばで、一緒に友達を\n作っていきたいな…", 1, 1432, 1, 102, 8, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ！　ＢＢ団の活動\nですか？　嬉しくて\n飛び跳ねちゃいます！", 2, 1433, 1, 1, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたとのお話で友達\n作りの練習になるなら\n一石二鳥です！", 2, 1434, 1, 2, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私少しは人と話しても\nテンパらなくなって\nきましたかね…？", 2, 1435, 1, 3, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの、友達作りの\n新しい作戦\n考えてみたんですっ！", 2, 1436, 1, 4, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたとお話する時の\nこの気持ち、私の宝物\nなんです…えへへ", 2, 1437, 1, 101, 8, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("友達もほしいけど…\nあなたに会えたことが\n私の一番の幸せです", 2, 1438, 1, 102, 8, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝ですね！\nこんないい朝は\n友達作りのチャンス！", 2, 1439, 1, 1, 1, 104002, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの…そろそろお腹\nすきませんか？\nお昼ごはんは…", 2, 1440, 1, 2, 1, 104002, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう眠いかもです…\n明日は友達\nできるといいなあ…", 2, 1441, 1, 3, 1, 104002, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私…見た目\nそこまで変じゃ\nないですよね…？", 3, 1442, 1, 1, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほわあ～…\nふかふかって\nいいものですね～", 3, 1443, 1, 2, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子みたいな\nあいくるしさを\n目指したいです！", 3, 1444, 1, 3, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("灯りを見てると\n心がなごみます～", 3, 1445, 1, 4, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬくぬくで、なんだか\n眠くなっちゃいますね", 3, 1446, 1, 5, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身体を鍛えて\nみなさんを\n守ります！", 3, 1447, 1, 6, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…\nおいしいです…！\nみなさんもぜひ！", 3, 1448, 1, 7, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("友達作りの\n参考になりそうなこと\n書いてないかな～？", 3, 1449, 1, 8, 1, 104002, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("唱喚の歌は、みだりに\n歌っていいものでは\nないんです", 1, 1451, 1, 1, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここでアイドルの\n練習は、さすがに\n迷惑ですよね？", 1, 1452, 1, 2, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("練習してもあんまり\n疲れなくなった…\nアイドルのおかげかな", 1, 1453, 1, 3, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人々の平和を守る旅に\n同行してくれる人を\n探していて…", 1, 1454, 1, 4, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あとで曲を復習して\nおかないと…", 1, 1455, 1, 5, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("踊りを見られるのは\nまだ恥ずかしいけど\nあの人になら…", 1, 1456, 1, 101, 4, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("浜辺で曲を書こうと\n思うんですけど…\n一緒に行きませんか？", 1, 1457, 1, 102, 8, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつも応援ありがとう\nございます♪　これは\nあ、握手の練習です！", 2, 1458, 1, 1, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え、もう練習の時間？\nごめんなさい\nすぐ準備します！", 2, 1459, 1, 2, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("守るべき人たちに\n笑顔でいてもらうのも\n大切なんですね", 2, 1460, 1, 3, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歌える曲を増やそうと\n思って。どんな曲が\n聞きたいですか？", 2, 1461, 1, 4, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("～～♪　あれ？\n今私、歌ってました？\n気づきませんでした", 2, 1462, 1, 101, 4, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…歌って欲しい？\n喜んで♪\nどの歌にしましょう？", 2, 1463, 1, 102, 8, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます♪\n少し歌の練習を\nしてきますね", 2, 1464, 1, 1, 1, 104201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうお昼なんですか？\n練習に夢中で\n気づきませんでした", 2, 1465, 1, 2, 1, 104201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日の予定は…\nアイドルはやることが\n多いみたいで…", 2, 1466, 1, 3, 1, 104201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見た目については\n前よりも気をつけてと\nノゾミに言われてます", 3, 1467, 1, 1, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歌の調子をよくする\nためには休息も\n必要ですよね…", 3, 1468, 1, 2, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子たちを\n相手に練習して\nみようかな…♪", 3, 1469, 1, 3, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…疲れてるのかな\n落ち着けているのが\n自分でもわかります", 3, 1470, 1, 4, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいると\n穏やかな旋律が\n浮かんできます…", 3, 1471, 1, 5, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歌うためには\n体力づくりは\n欠かせません", 3, 1472, 1, 6, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歌った後は\nお腹が空いて\nしまうんです", 3, 1473, 1, 7, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("音楽について\n理論も勉強\nしないと…", 3, 1474, 1, 8, 1, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歌うことの楽しさ\n分かってきました\nもっと歌いたいな…", 1, 1476, 1, 1, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("練習してもあんまり\n疲れなくなった…\nアイドルのおかげかな", 1, 1477, 1, 2, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("精霊も強くなったし\nもっとたくさんの人を\n守りたいです", 1, 1478, 1, 3, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近、よく頭の中に\n歌が浮かんできます\n不思議な感覚…", 1, 1479, 1, 4, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("楽譜を買いました\n思いついた歌を\n書き留めておくために", 1, 1480, 1, 5, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("浜辺で曲を書こうと\n思うんですけど…\n一緒に行きませんか？", 1, 1481, 1, 101, 8, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の中にある\n私だけの歌…\n作ってみようかな？", 1, 1482, 1, 102, 8, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("守るべき人たちに\n笑顔でいてもらうのも\n大切なんですね", 2, 1483, 1, 1, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歌える曲を増やそうと\n思って。どんな曲が\n聞きたいですか？", 2, 1484, 1, 2, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔物退治ですか！？\n…違います？\n良かった…", 2, 1485, 1, 3, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつも応援ありがとう\nございます♪　これは\nあ、握手の練習です！", 2, 1486, 1, 4, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…歌って欲しい？\n喜んで♪\nどの歌にしましょう？", 2, 1487, 1, 101, 8, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("～～♪　あれ？\n今私、歌ってました？\n気づきませんでした", 2, 1488, 1, 102, 8, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("呼吸を深く、大きく…\nこれでちゃんと\n目が覚めますよ", 2, 1489, 1, 1, 1, 104202, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し休んだら\n午後の練習に\n行ってきますね", 2, 1490, 1, 2, 1, 104202, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("曲を作っていたら\nもうこんな時間…\nおやすみなさい", 2, 1491, 1, 3, 1, 104202, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見た目については\n前よりも気をつけてと\nノゾミに言われてます", 3, 1492, 1, 1, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ～…♪\nよく体がほぐれます…\nいい歌が歌えそうです", 3, 1493, 1, 2, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいと思う\n気持ちを、歌にしても\nいいかも知れませんね", 3, 1494, 1, 3, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…疲れてるのかな\n落ち着けているのが\n自分でもわかります", 3, 1495, 1, 4, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいると\n穏やかな旋律が\n浮かんできます…", 3, 1496, 1, 5, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もっと体力をつけて\n最高のライブを\nファンに届けます！", 3, 1497, 1, 6, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これでも一応\n体形には気をつけて\n食べてるんですよ？", 3, 1498, 1, 7, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("読書は歌に\n新しい風を\n吹き込んでくれます", 3, 1499, 1, 8, 1, 104202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("店の新メニューでも\n考えるかな", 1, 1501, 1, 1, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしの店から、\n出前を届けようか？", 1, 1502, 1, 2, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パトロール、\nパトロール…\nここは異常なしかな？", 1, 1503, 1, 3, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腹へったら食う！\n悩んだら寝る！\nそれが一番だろ？", 1, 1504, 1, 4, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("のんびりし過ぎるのも\n…性に合わねぇな", 1, 1505, 1, 5, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろあいつ、\n腹すかしてるん\nじゃないかな？", 1, 1506, 1, 101, 4, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日の献立は…\nあいつの好きなものに\nしてやるか", 1, 1507, 1, 102, 8, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("強くなりたいなら、\nあたしがビシバシ\n鍛えてやるよ", 2, 1508, 1, 1, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("天気がいい日は\n外で運動したく\nならねぇか？", 2, 1509, 1, 2, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腹減ったか？　なんか\n作ってやろうか？", 2, 1510, 1, 3, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん？　なんだよ、\n相談事か？\nなんでも言ってくれ", 2, 1511, 1, 4, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お前が好きな飯って\nなんだ？\n今度、作ってやるよ", 2, 1512, 1, 101, 4, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お前って不思議だよな\n一緒にいるとなんだか\n…なんでもねーよ", 2, 1513, 1, 102, 8, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちいい朝だな！\n体を動かしたい気分だ\n付き合ってくれるか", 2, 1514, 1, 1, 1, 104301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼飯もう食ったか？\nまだなら、あたしが\nなんか作ってやるよ", 2, 1515, 1, 2, 1, 104301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日中たっぷり動いたら\nそのぶん夜はしっかり\n休んどけよな", 2, 1516, 1, 3, 1, 104301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("た、たまにはその…\nかわいい格好とか\nしても…", 3, 1517, 1, 1, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ、\n一休みすっかなぁ～", 3, 1518, 1, 2, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うっ！　か、かわいい\nじゃねぇか", 3, 1519, 1, 3, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へー　いい匂いだな\nあいつもこういうの\n好きなのかな…", 3, 1520, 1, 4, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ〜！\n温かいと、つい\nウトウトしちまうな", 3, 1521, 1, 5, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オラオラオラーーー！\n燃えるぜーーー！", 3, 1522, 1, 6, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい味してるぜ！\nうちの店でも\n出してみたいな", 3, 1523, 1, 7, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("文字を読んでると\nどうしても眠く\nなっちまうんだよなぁ", 3, 1524, 1, 8, 1, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パトロール終了～\n本日も異常なしっと！", 1, 1526, 1, 1, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしの店から\n出前を届けようか？", 1, 1527, 1, 2, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつ、早く\n帰ってこないかな", 1, 1528, 1, 3, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつ\n腹すかせてないと\nいいんだけど…", 1, 1529, 1, 4, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("のんびりし過ぎるのも\n…性に合わねぇな", 1, 1530, 1, 5, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつの事を思うと\n胸があったかくなる？\nなんだコレ…？", 1, 1531, 1, 101, 8, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日の献立は…\nあいつの好きなものに\nしてやるか", 1, 1532, 1, 102, 8, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん？　なんだよ\n相談事か？\nなんでも言ってくれ", 2, 1533, 1, 1, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("天気がいい日は\n外で運動したく\nならねぇか？", 2, 1534, 1, 2, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腹減ったか？　なんか\n作ってやろうか？", 2, 1535, 1, 3, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腹へったら食う！\n悩んだら寝る！\nそれが一番だろ？", 2, 1536, 1, 4, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのさ…できれば\nもっとそばに…いや\nなんでもねぇ忘れろ！", 2, 1537, 1, 101, 8, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お前って不思議だよな\n一緒にいるとなんだか\n…なんでもねーよ", 2, 1538, 1, 102, 8, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちいい朝だな！\n体を動かしたい気分だ\n付き合ってくれるか？", 2, 1539, 1, 1, 1, 104302, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼飯もう食ったか？\nまだなら、あたしが\nなんか作ってやるよ", 2, 1540, 1, 2, 1, 104302, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんま夜更しすんなよ\n明日に響いたら\n大変だろ？", 2, 1541, 1, 3, 1, 104302, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("た、たまにはその…\nかわいい格好とか\nしても…", 3, 1542, 1, 1, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ～♪\n疲れがとれるな～", 3, 1543, 1, 2, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うっ！　か、かわいい\nじゃねぇか", 3, 1544, 1, 3, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へー　いい匂いだな\nあいつもこういうの\n好きなのかな…", 3, 1545, 1, 4, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ～！\n温かいと、つい\nウトウトしちまうな", 3, 1546, 1, 5, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オラオラオラーーー！\n燃えるぜーーー！", 3, 1547, 1, 6, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい味してるぜ！\nうちの店でも\n出してみたいな", 3, 1548, 1, 7, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("料理だけじゃなく\n経営術とかも\n学んどかねぇと…", 3, 1549, 1, 8, 1, 104302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近なにも\nしてくれません…\n焦らしてるんですね", 1, 1551, 1, 1, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぐふふ、じゅるり…\nい、いけない、また\nいつの間にかよだれが", 1, 1552, 1, 2, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("好きな武器といえば\n剣より槍より\nやっぱり鞭…ぐふふ", 1, 1553, 1, 3, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「無数の触手が\nクウカの柔肌に\n食い込み」…ぐふふ", 1, 1554, 1, 4, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もしドＳさんが\nＭに転じたらと思うと\n身の毛がよだちます！", 1, 1555, 1, 5, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんを登場\nさせるだけで、妄想に\n無限の広がりが！", 1, 1556, 1, 101, 4, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ…\nジロジロ見てたの\n気づいちゃいました？", 1, 1557, 1, 102, 8, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("視線を感じると\n思ったら…やはり\nドＳさんでしたか", 2, 1558, 1, 1, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は\nどんなヒドイことを\nしてくれるんですか？\nぐふふふ", 2, 1559, 1, 2, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつの間にそこに！？\nまさかクウカを監視\nしていたのですか！？", 2, 1560, 1, 3, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クウカに触るつもり\nですか？　触るつもり\nなのですねっ！？", 2, 1561, 1, 4, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クウカにナニをする\nつもりですか…\n期待してしまいます！", 2, 1562, 1, 101, 4, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんの視界に入る\nだけでドキドキが…\nこれが恋！？", 2, 1563, 1, 102, 8, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます。\n朝からお盛んですね？\nぐふふ…", 2, 1564, 1, 1, 1, 104501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなにも日の高い\nうちからドＳさんは…\nじゅるり", 2, 1565, 1, 2, 1, 104501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜はこれから、\nですよ…\nぐふ、ぐふふふ…", 2, 1566, 1, 3, 1, 104501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キレイにおめかし\nしたのに力ずくで…\nぐふふふ", 3, 1567, 1, 1, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ソファの背にクウカを\n押し付けて…ぐふふ\nいいですね\nソファドン", 3, 1568, 1, 2, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「見た目とは裏腹に\nそれは激しく攻め\nたてて」…ぐふふふ", 3, 1569, 1, 3, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("香りを吸ったクウカの\n頬は紅潮し目はうるみ\nもはや抗う力も…！", 3, 1570, 1, 4, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ、身体が\n火照って…\nぐふ、ぐふふ…", 3, 1571, 1, 5, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ、はぁ、こうして\nクウカの体力を\n奪ってから…ぐふふ", 3, 1572, 1, 6, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食欲が満たされたら\nつ、次はやはり…！\nそうなのですね！？", 3, 1573, 1, 7, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本の下に、\nそういう本を\nカムフラージュ？", 3, 1574, 1, 8, 1, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「ドＳさんと踊り子\n乱舞の一夜」…\n次の日記はこれで…", 1, 1576, 1, 1, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近なにも\nしてくれません…\n焦らしてるんですね", 1, 1577, 1, 2, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("も、妄想が\n足りません…\n禁断症状がっ…！", 1, 1578, 1, 3, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もしドＳさんが\nＭに転じたらと思うと\n身の毛がよだちます！", 1, 1579, 1, 4, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はどんなドＳを\nされるのか、想像する\nだけで…ぐふふふ", 1, 1580, 1, 5, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じっとしてると\nドＳさんのことばかり\n考えてしまいますね", 1, 1581, 1, 101, 8, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("妄想が止まらなくて\nクウカどうにかなって\nしまいそうです！", 1, 1582, 1, 102, 8, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんといると体が\n火照って…クウカは\nいやらしい子です！", 2, 1583, 1, 1, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ…\nジロジロ見てたの\n気づいちゃいました？", 2, 1584, 1, 2, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんのおかげで\n新しい扉が開けそう\nです…じゅるり", 2, 1585, 1, 3, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いやー！　ドＳさんに\n襲われ…襲って\nくれないんですか？", 2, 1586, 1, 4, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クウカはドＳさんに\n身も心も堕とされて\nしまったのですね", 2, 1587, 1, 101, 8, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんがお望みなら\nクウカは\nどんなことだって！", 2, 1588, 1, 102, 8, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝だからこそ\nできる妄想が\nあります…ぐふふ", 2, 1589, 1, 1, 1, 104502, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな日の高いうち\nからドＳさんは…\nじゅるり", 2, 1590, 1, 2, 1, 104502, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今夜は一晩中…\nなんですね？\nぐふふ…", 2, 1591, 1, 3, 1, 104502, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("意外と難しいんですよ\n正しい亀甲縛りと\nいうものは…", 3, 1592, 1, 1, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くつろいで油断\nしているスキに何を\nされるのでしょう！？", 3, 1593, 1, 2, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「見た目とは裏腹に\nそれは激しく攻め\nたてて」…ぐふふふ", 3, 1594, 1, 3, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは禁断の香り…\nああっ一段階上の\n妄想が開花するうぅ！", 3, 1595, 1, 4, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああっ、暖気がまるで\nロウソクのように\nクウカを攻めますっ！", 3, 1596, 1, 5, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("激しい攻めを受けきる\nためには、鍛えないと\nいけないのですね", 3, 1597, 1, 6, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなにいっぱい\n入りません…\nお腹にっ！", 3, 1598, 1, 7, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんな本も\nよく見ると\nいやらしいです…！", 3, 1599, 1, 8, 1, 104502, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この前遊んだ猫、\nモッフモフ\nだったにゃあ…♪", 1, 1601, 1, 1, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほっぺやお腹が、\n肉球ぐらいぷにぷに…\nこれはまずいにゃ…", 1, 1602, 1, 2, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大きな仕事が\n決まったにゃ！\n腕が鳴るにゃ～♪", 1, 1603, 1, 3, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おやつのたい焼き、\nつぶあんとこしあん、\nどっちに\nしようかにゃ？", 1, 1604, 1, 4, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うにゃー…\nもうちょっとお昼寝\nしたかったにゃ…\nむにゃむにゃ…", 1, 1605, 1, 5, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミに呼ばれると、\n猫まっしぐらな気分に\nなっちゃうにゃ♪", 1, 1606, 1, 101, 4, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミのおかげで\nギルドの仕事も\n大成功だにゃ♪\nありがとにゃ♪", 1, 1607, 1, 102, 8, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うずうず…その指、\nじゃれついても\nいいかにゃ？", 2, 1608, 1, 1, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃ？　あたしに何か\nご入り用かにゃ？\nお安くしとくにゃ～♪", 2, 1609, 1, 2, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん、なんだか\n退屈にゃ～\n遊んで、遊んで～？", 2, 1610, 1, 3, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素早い動きのコツ？\nタダじゃ教えて\nあげられないにゃ～♪", 2, 1611, 1, 4, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そんなにあたしを\nなでたいにゃ？\nキミならなでさせて\nあげてもいいかにゃー", 2, 1612, 1, 101, 4, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふにゃあ、ねえねえ、\n一緒にゴロゴロ\nしようにゃあ？", 2, 1613, 1, 102, 8, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい朝にゃ！\n顔を洗ってくるにゃ！", 2, 1614, 1, 1, 1, 104601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むーん、そろそろ\nお昼…猫たちにも\n猫缶を…", 2, 1615, 1, 2, 1, 104601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわあ…眠いにゃ…\n猫は布団で\n丸くなるにゃ", 2, 1616, 1, 3, 1, 104601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("客商売では、\n外見のチェックも\n欠かせないのにゃ！", 3, 1617, 1, 1, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うにゃ～！\nお昼寝に\nぴったりにゃ", 3, 1618, 1, 2, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ…量産したら\n子どもにバカ売れ\nしそうだにゃ！", 3, 1619, 1, 3, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この灯り、まるで\n猫みたいな\n癒し効果にゃ！", 3, 1620, 1, 4, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふにゃあ、\nあったかいと猫は丸く\nなっちゃうのにゃあ…", 3, 1621, 1, 5, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本当は外で\n運動したいん\nだけどにゃ", 3, 1622, 1, 6, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むーん、\n美味しいにゃー！\nたい焼きに\n匹敵するにゃ！", 3, 1623, 1, 7, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…猫の\nしつけ方は、と…", 3, 1624, 1, 8, 1, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいネコの置物を\nゲットしたにゃ！\nどこに飾ろうか\nにゃ～♪", 1, 1626, 1, 1, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕事の交渉がうまく\n行ったにゃ～♪\nいい気分だにゃ～♪", 1, 1627, 1, 2, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねこじゃらしには\n食いついちゃうにゃ\nびしっ！　びしっ！", 1, 1628, 1, 3, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほっぺやお腹が、肉球\nぐらいぷにぷに…\nこれはまずいにゃ…", 1, 1629, 1, 4, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さっきのたいやき\nおいしかったにゃ♪\nごろごろごろ…", 1, 1630, 1, 5, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("手作りのたい焼き\nあいつは食べて\nくれるかにゃ…？", 1, 1631, 1, 101, 8, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつには、いつか\nたっぷり恩返しが\nしたいにゃ…", 1, 1632, 1, 102, 8, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃーに？　あたしの\nことがそんなに気に\nなるのかにゃ？", 2, 1633, 1, 1, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしのこと…\nしっかり捕まえ\nといてにゃ？", 2, 1634, 1, 2, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしの力が\n必要かにゃ？　猫の手\n貸してあげるにゃ♪", 2, 1635, 1, 3, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たいやきとクレープを\n合わせれば…\n新しい商売のニオイが\nするにゃ…！", 2, 1636, 1, 4, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふにゃあ、ねえねえ\n一緒にゴロゴロ\nしようにゃあ？", 2, 1637, 1, 101, 8, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミと一緒にいると\n楽しくなってつい\nじゃれちゃうにゃ！", 2, 1638, 1, 102, 8, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい朝にゃ！\n顔を洗ってくるにゃ！", 2, 1639, 1, 1, 1, 104602, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろおっひる～\nにゃーんか\n食べたい…", 2, 1640, 1, 2, 1, 104602, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん、眠くなって\nきたにゃ。あたしは\n夜行性じゃないのにゃ", 2, 1641, 1, 3, 1, 104602, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃにゃ…\n髪が乱れてるにゃ", 3, 1642, 1, 1, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふっかふかにゃ～\n猫がねころん\nじゃうにゃ", 3, 1643, 1, 2, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ、猫と匹敵する\nぐらいかわいいにゃ！", 3, 1644, 1, 3, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("猫でもこわくない\n優しい灯りにゃ！", 3, 1645, 1, 4, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽっかぽか\nしあわせな気分にゃ～", 3, 1646, 1, 5, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("雨の日でも運動\nできるのは、濡れ\nなくて便利だにゃ！", 3, 1647, 1, 6, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美味しいにゃ～！\nこれ、朝昼晩\n食べたいにゃ！", 3, 1648, 1, 7, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本を読んで\n猫の気持ちを\n勉強するのにゃ！", 3, 1649, 1, 8, 1, 104602, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("内職手伝える人\nいないかしら？", 1, 1651, 1, 1, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次の依頼は、\nこういう計画で…\nうん、完璧ね！", 1, 1652, 1, 2, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次の特売セールに\n向けて、しっかり\n準備しないと！", 1, 1653, 1, 3, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("配達の後に売り子\n次に採取のバイト…\nうん、効率的ね", 1, 1654, 1, 4, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一日に受ける\nバイトの数、もう少し\n増やしたいわね", 1, 1655, 1, 5, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("師匠として\n頼りにされたいし\nもっと頑張らなきゃ！", 1, 1656, 1, 101, 4, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("男の子と効率的に\n仲良くなる方法…\nこればっかりは難題ね", 1, 1657, 1, 102, 8, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら、\nちょうどよかった\n今から一緒に\nバイトでもどう？", 2, 1658, 1, 1, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("相談事かしら？\nそれくらいなら\n無料でいいわよ", 2, 1659, 1, 2, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("背後の気配なら\nすぐ分かるわ\n試してみる？", 2, 1660, 1, 3, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("道具やお金の管理は\n大丈夫？　手伝うから\nいつでも言って", 2, 1661, 1, 4, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇ができたから\n働きたいけど…\nキミとの時間も大切ね", 2, 1662, 1, 101, 4, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、あの…\n私はキミにとって…\nいや、何でもないわ", 2, 1663, 1, 102, 8, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！\n今日も朝から\nバイトよ！", 2, 1664, 1, 1, 1, 104801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼時ね。\n少し休憩したら、\nまた働くわよ！", 2, 1665, 1, 2, 1, 104801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間！\n明日もバイトで\n朝早いのよ…", 2, 1666, 1, 3, 1, 104801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("接客業の依頼が\nある時は、外見も\nキレイにしないとね", 3, 1667, 1, 1, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～バイトで\n疲れたから癒される～", 3, 1668, 1, 2, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これを内職で\n作ったら\n儲かるかしら？", 3, 1669, 1, 3, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リフレッシュできたわ\nこれでまた、バリバリ\n働けるわね！", 3, 1670, 1, 4, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("風邪を引いたら効率が\n落ちちゃうから、\n暖めないと！", 3, 1671, 1, 5, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("働き続けるには\n健康第一！　それには\n運動が一番よ", 3, 1672, 1, 6, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…\n腹が減っては\n戦ができぬ、よ！", 3, 1673, 1, 7, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日々絶えず学んで、\n生活に活かすのよ！", 3, 1674, 1, 8, 1, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("家計簿をつけなきゃ！\n覚えている時に\nやっておかないとね", 1, 1676, 1, 1, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次の依頼は\nこういう計画で…\nうん、完璧ね！", 1, 1677, 1, 2, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギルドの経費\nあとちょっとだけ\n削れそうね…", 1, 1678, 1, 3, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少しでも時給のいい\nバイトがしたいけど\nなかなか\n出会えないのよ", 1, 1679, 1, 4, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度のバイトも\nなかなか大変そう\nね…腕が鳴るわ", 1, 1680, 1, 5, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("男の子と効率的に\n仲良くなる方法…\nこればっかりは難題ね", 1, 1681, 1, 101, 8, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私、どうしたんだろ？\n仕事中もずっと\n彼のこと考えてる…", 1, 1682, 1, 102, 8, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この間はヘルプに\n来てくれてありがとう\n頼んで正解だったわ", 2, 1683, 1, 1, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見つけた！　ちょうど\n頼みたいことが\nあるんだけど、いい？", 2, 1684, 1, 2, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今から\n休憩するところなの\n一緒にどう？", 2, 1685, 1, 3, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん？　どうしたの？\n私のことが\n気になるの？", 2, 1686, 1, 4, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…たまには甘えても\nいい？　私だって\n弱る時はあるのよ", 2, 1687, 1, 101, 8, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇ができたから\n働きたいけど…\nキミとの時間も大切ね", 2, 1688, 1, 102, 8, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！\nいい朝ね。一緒に\nランニングでもいく？", 2, 1689, 1, 1, 1, 104802, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼時ね\n少し休憩したら\nまた働くわよ！", 2, 1690, 1, 2, 1, 104802, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間！\n明日もバイトで\n朝早いのよ…", 2, 1691, 1, 3, 1, 104802, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("女の子らしく…\nどうも忘れちゃう\nのよね", 3, 1692, 1, 1, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここで少し\n休んだら\nまたバイトよ！", 3, 1693, 1, 2, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これを内職で\n作ったら\n儲かるかしら？", 3, 1694, 1, 3, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕事から帰ってきて\nこういうのがあると\n素敵ね", 3, 1695, 1, 4, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しっかり身体を\n温めて、血流を\nよくしなくっちゃ", 3, 1696, 1, 5, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これで休憩中も\n無駄なく\n鍛えられるわ♪", 3, 1697, 1, 6, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…よく\n食べて、よく働く！\nそれが私のモットーよ", 3, 1698, 1, 7, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日々絶えず学んで\n生活に活かすのよ！", 3, 1699, 1, 8, 1, 104802, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇だし、お料理と\nお掃除とお洗濯と\n買い物しようかな？", 1, 1701, 1, 1, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こうして歩いていれば\n弟くんが声をかけて\nくれるはず…", 1, 1702, 1, 2, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんがどんな生活を\nしてるのか調べるのも\nお姉ちゃんの務め！", 1, 1703, 1, 3, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん、\n弟くんのにおい…\n近くにいるね？", 1, 1704, 1, 4, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんの痕跡を\n部屋中に\n残しちゃおっと♪", 1, 1705, 1, 5, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この部屋を、\n私と弟くんの\n愛の巣に…", 1, 1706, 1, 101, 4, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～…弟くん\n禁断症状だよ～", 1, 1707, 1, 102, 8, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんの部屋は\nお姉ちゃんの\n部屋だよね～", 2, 1708, 1, 1, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいこいいこ～♪\nどう、お姉ちゃんの\nナデナデは？", 2, 1709, 1, 2, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("姉と弟の外出は\nデートって\nいうのかな？", 2, 1710, 1, 3, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう！\nイタズラする子には\nお姉ちゃんチョップ！", 2, 1711, 1, 4, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんが\nぎゅ～ってして\nあげるね♪", 2, 1712, 1, 101, 4, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、あのね…\nたまにはお姉ちゃんも\n甘えていい？", 2, 1713, 1, 102, 8, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("着替えは？　荷物は？\nお出かけの準備は\nお姉ちゃんが手伝うね", 2, 1714, 1, 1, 1, 104901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("出かけるなら\n明るいうちに\n帰ってくるんだよ！", 2, 1715, 1, 2, 1, 104901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだ起きてるの？\nそれじゃあ、\nお姉ちゃんも\n夜更かししちゃお☆", 2, 1716, 1, 3, 1, 104901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きれいなお姉ちゃん\n好きだよね♪", 3, 1717, 1, 1, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにお姉ちゃんの\n匂いを、た～っぷり\n残しておこうっと♪", 3, 1718, 1, 2, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい♪\nお姉ちゃんチョップ！", 3, 1719, 1, 3, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り、\n弟くん好きかな？", 3, 1720, 1, 4, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ、弟くんみたいに\nあったかいね～", 3, 1721, 1, 5, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ダイエットダイエット\nきれいなお姉ちゃんに\nならなくちゃ", 3, 1722, 1, 6, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、これ\n弟くんが好きな\n味付けだね！", 3, 1723, 1, 7, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんが読んでいいか\nお姉ちゃんが先に\n中を確認しなくちゃ！", 3, 1724, 1, 8, 1, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇だし、お料理と\nお掃除とお洗濯と\n買い物しようかな？", 1, 1726, 1, 1, 1, 104902, 0, 0);
