INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("具合が悪い？\nなら診てあげる\nまずは触診から…", 2, 1810, 1, 3, 1, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("植物に興味あるの？\nなら教えてあげるわ\n色々とね…", 2, 1811, 1, 4, 1, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミの傍にいるだけで\n高揚しちゃうのは\n何故かしら…？", 2, 1812, 1, 101, 4, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私はおしおきする\n側のことが多いけど…\nキミにはされたいかも", 2, 1813, 1, 102, 8, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼までに調合用の\n花を集めたいの\n手伝ってくれる？", 2, 1814, 1, 1, 1, 105101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら、もうお昼？\nそろそろ一息\n入れましょうか", 2, 1815, 1, 2, 1, 105101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜も更けて来たわね\n私は朝まで実験だけど\n見学していく？", 2, 1816, 1, 3, 1, 105101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("医者たるもの\nいつだって\n清潔に…♪", 3, 1817, 1, 1, 1, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいわねこれ\n仮眠の時に\n使わせてもらうわ", 3, 1818, 1, 2, 1, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬいぐるみなら\n動物も…", 3, 1819, 1, 3, 1, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…\n仕事場にも\n置いてみようかしら", 3, 1820, 1, 4, 1, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいると\nついウトウト\nしちゃうわ…", 3, 1821, 1, 5, 1, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("座ってる時間が多いと\n運動不足になるし\nたまにはいいわね", 3, 1822, 1, 6, 1, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("研究していると\nつい食べるのを\n忘れちゃうのよね", 3, 1823, 1, 7, 1, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("実験もいいけど\nいつか成果を\n本にしないと…", 3, 1824, 1, 8, 1, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("徹夜はツラいけど\n集中すると時間の\n感覚がなくなって…", 1, 1826, 1, 1, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("痛みに悶える顔って\nどうしてあんなに\n興奮するのかしら？", 1, 1827, 1, 2, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼に罵られたら\nどんな気分かしら\n意外と快感かも？", 1, 1828, 1, 3, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("毒を薄めると\n薬になるのって\n今でも不思議だわ", 1, 1829, 1, 4, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("綺麗なバラには\nトゲがあるけど\n魅力の一つよね", 1, 1830, 1, 5, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カレをさりげなく\n惚れさせる方法を\n研究するわよ…♪", 1, 1831, 1, 101, 8, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("好意に気づいて貰える\n薬って、どうすれば\n作れるのかしら", 1, 1832, 1, 102, 8, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("構って欲しいの？\nじゃあ、君の体を\n調べさせて？", 2, 1833, 1, 1, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("実験に付き合って\n大丈夫よ、試すのは\nただの栄養剤だから", 2, 1834, 1, 2, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("欲しい薬が\nあったら言ってね\n調合してみるから", 2, 1835, 1, 3, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おしおきされたいの？\nキミにだったら\nいつでもしてあげる", 2, 1836, 1, 4, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミの傍にいるだけで\n高揚しちゃうのは\n何故かしら…？", 2, 1837, 1, 101, 8, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私はおしおきする\n側のことが多いけど…\nキミにはされたいかも", 2, 1838, 1, 102, 8, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝しか取れない\n植物があるの\n採取しに行くわよ", 2, 1839, 1, 1, 1, 105102, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼時ってやけに\n眠たくなるわよね\n…調べたくなるわ", 2, 1840, 1, 2, 1, 105102, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日くらいは\nゆっくり眠りたいわ\n…キミと一緒にね", 2, 1841, 1, 3, 1, 105102, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身なりについて\n研究するのも\n楽しそうね", 3, 1842, 1, 1, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休息に必要な道具は\n妥協せずに選ぶ！\nこれだけは譲れないわ", 3, 1843, 1, 2, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまにはこういう\n可愛らしいものに\n触れないとね♪", 3, 1844, 1, 3, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…\n仕事場にも\n置いてみようかしら", 3, 1845, 1, 4, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕事がなかったら\nこのまますーっと\n眠りたいのに…", 3, 1846, 1, 5, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("運動しないと\n体型の維持が…", 3, 1847, 1, 6, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("適度な食事も\n大切よね", 3, 1848, 1, 7, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まさか私が\n恋愛読本を読む\n日が来るなんて…", 3, 1849, 1, 8, 1, 105102, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぺっぺっ！\n…い、いけないっ！", 1, 1851, 1, 1, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いっけな～い！\nひづめで床に傷が！", 1, 1852, 1, 2, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("太っちゃったかも～！\n伐採でダイエット\nしなくっちゃ！", 1, 1853, 1, 3, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きちんと生活すると\n毛づやが良くなる\nみたいなのよね～", 1, 1854, 1, 4, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんな、体重\nどれくらいなのかな？", 1, 1855, 1, 5, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体力なら自信\nあるんだけど…\n恋にはちょっぴり\n臆病になっちゃう", 1, 1856, 1, 101, 4, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか人間の女の子\nみたいなデート、\nしてみたいな～♪", 1, 1857, 1, 102, 8, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私ね「どこにでもいる\n普通の女の子」って\n言葉が憧れなんだ～♪", 2, 1858, 1, 1, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("チャームポイント？\n自分では分からない\nけど…まつげかなぁ？", 2, 1859, 1, 2, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リマリマ～♪\nはっ！？\nわ、私ったら今何を？", 2, 1860, 1, 3, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("力仕事ならまかせて！", 2, 1861, 1, 4, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人間になりたいな～\nそれか、あなたが\n私みたいな姿に…♪", 2, 1862, 1, 101, 4, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しょうがないなあ、\nこんなにモフらせるの\nあなただけだよ？", 2, 1863, 1, 102, 8, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今朝は寝癖がひどいわ\nしっぽの辺りとか～", 2, 1864, 1, 1, 1, 105201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランチは\nおしゃれなカフェで\nしてみたいな～♪", 2, 1865, 1, 2, 1, 105201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お肌のケアに\nパックしながら\n寝ようかな～", 2, 1866, 1, 3, 1, 105201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やだっ、\nまた寝ぐせついてる！\n直さないと！", 3, 1867, 1, 1, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミシッっていった！\n私、重すぎるかも！？", 3, 1868, 1, 2, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ！　あなたも\n美人さんね～♪", 3, 1869, 1, 3, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ、まったり…\n四足歩行しちゃい\nそうだわ…", 3, 1870, 1, 4, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったか～い♪\n…私、毛皮だから\n暑すぎるかも", 3, 1871, 1, 5, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("な、なんだか野生に\n帰っちゃいそう！", 3, 1872, 1, 6, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぱくぱく、もぐもぐ、\nぺっぺっ…\nやだ、はしたない！", 3, 1873, 1, 7, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きゃーーー！\nこの恋愛小説\nとっても\nドキドキしちゃう～", 3, 1874, 1, 8, 1, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵ね～、居るだけで\n女子力があがりそうな\nお部屋だわ～", 1, 1876, 1, 1, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私、大丈夫かしら？\n他の子に怖がられたり\nしないかな…？", 1, 1877, 1, 2, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("動物苑…って\n嫌なギルド名ね…", 1, 1878, 1, 3, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("好き、嫌い、好き…\nあっ！　うっかりして\n花占いのお花\n食べちゃった！", 1, 1879, 1, 4, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここ、女の子らしい\nものでいっぱいね～！\nときめいちゃうわ～♪", 1, 1880, 1, 5, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体力なら自信\nあるんだけど…\n恋にはちょっぴり\n臆病になっちゃう", 1, 1881, 1, 101, 8, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人が\n来てくれるまで薪割り\nでもしてよっかな？", 1, 1882, 1, 102, 8, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒にお出かけ？\nうれしいけど…\n心の準備が！\nはわわわ！", 2, 1883, 1, 1, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたの？\n急に抱きついてきて…\n癒されたいの？", 2, 1884, 1, 2, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぺっぺっ！\n…い、いけないっ！", 2, 1885, 1, 3, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メタモルアップルを\nここで食べたら、\nみんな驚くわよね", 2, 1886, 1, 4, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しょうがないなあ、\nこんなにモフらせるの\nあなただけだよ？", 2, 1887, 1, 101, 8, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人間になりたいな～\nそれか、あなたが\n私みたいな姿に…♪", 2, 1888, 1, 102, 8, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今朝は寝癖がひどいわ\nしっぽの辺りとか～", 2, 1889, 1, 1, 1, 105202, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ダイエット中だから\nお昼は抜いてるの～", 2, 1890, 1, 2, 1, 105202, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お肌のケアに\nパックしながら\n寝ようかな～", 2, 1891, 1, 3, 1, 105202, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちゃんとかわいく\nしてないと刈られ…\n狩られちゃうもんね！", 3, 1892, 1, 1, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミシッっていった！\n私、重すぎるかも！？", 3, 1893, 1, 2, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ！　あなたも\n美人さんね～♪", 3, 1894, 1, 3, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り～\n森の中にいるみたいに\nとっても落ち着く～", 3, 1895, 1, 4, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵～♪　…\nきゃっ！　私の毛が\nたいへんなことに～！", 3, 1896, 1, 5, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("な、なんだか野生に\n帰っちゃいそう！", 3, 1897, 1, 6, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何を食べるかより\n誰と食べるかが\n大事なのよね", 3, 1898, 1, 7, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きゃーーー！\nこの恋愛小説\nとっても\nドキドキしちゃう～", 3, 1899, 1, 8, 1, 105202, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヴァイスフリューゲル\nを盛り上げる方法、\n共に語らおう！", 1, 1901, 1, 1, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私は子供ではない…！\nが、お菓子は\nいただこう！", 1, 1902, 1, 2, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋はきちんと\n片づけておかなくては\n部屋の汚れは\n心の汚れだ", 1, 1903, 1, 3, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むむむ…明日\n目が覚めたら、身長が\n伸びていないものか…", 1, 1904, 1, 4, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子が常備されて\nいる部屋。そんな\nものが、私の好みだ…", 1, 1905, 1, 5, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつとの新たな\n鍛錬が\n待ち遠しいな…！", 1, 1906, 1, 101, 4, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近、あいつと\n過ごしていて、毎日が\n充実しているな…", 1, 1907, 1, 102, 8, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("軍人の本分は日々の\n研鑽にあるからな。\n今日も鍛錬に\n行かないか？", 2, 1908, 1, 1, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("毎日牛乳を飲んでいる\nのだが、なかなか背が\n伸びないものだな…", 2, 1909, 1, 2, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴公にも、飴をくれて\nやろうか？\nあまいぞ～！\n美味しいぞ～！", 2, 1910, 1, 3, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私ともっと高く、\n共に飛ぼう！", 2, 1911, 1, 4, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴公は、本当に頼りに\nなる男だな…いや、\nふとそう思っただけだ", 2, 1912, 1, 101, 4, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴公と共にいられる\nことは私の喜びだ。\nこれからも\nよろしく頼むぞ", 2, 1913, 1, 102, 8, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うむ、いい朝だ。\n本国の夜明けを\n思い出してしまうな！", 2, 1914, 1, 1, 1, 105301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ昼食に\nするか。腹が減っては\n戦はできないからな", 2, 1915, 1, 2, 1, 105301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわああ…私は子供\nではないが…眠い時は\n眠いのだ…", 2, 1916, 1, 3, 1, 105301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身だしなみは、心の\n在りようを映すから\n気をつけなくてはな", 3, 1917, 1, 1, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふう…軍人たるもの\n常日頃、油断は\nできないのだが…\nお、落ち着くな…", 3, 1918, 1, 2, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うむ…このかわいさ…\n本国に持って\n帰りたい…", 3, 1919, 1, 3, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このともし火、戦いに\n明け暮れる我らの心を\n癒すものだな…", 3, 1920, 1, 4, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はあ～、ぽかぽか…\nい、いや！\n気を緩めないぞっ！", 3, 1921, 1, 5, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うおおおおおっ！\n鍛錬、鍛錬、\n鍛錬っ！！", 3, 1922, 1, 6, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつ戦いになっても\n困らぬように、\n腹八分目に\nしておくのだ！", 3, 1923, 1, 7, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これを読んで、新たな\n戦術を編み出すぞっ！", 3, 1924, 1, 8, 1, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまには掃除でも\nするか。部屋が\n綺麗になるのは\n喜ばしいことだ", 1, 1926, 1, 1, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋の中では\n剣を振り回せないのが\n玉に瑕だな…", 1, 1927, 1, 2, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子が常備されて\nいる部屋。そんな\nものが、私の好みだ…", 1, 1928, 1, 3, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("毎日牛乳を飲んでいる\nのだが、なかなか背が\n伸びないものだな…", 1, 1929, 1, 4, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("家庭を守れない者が\n国を守れるはずが\nない。この部屋も\n私が守るぞ！", 1, 1930, 1, 5, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつは今頃、何を\nしているのだろうな…\nふふっ", 1, 1931, 1, 101, 8, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつと会える日が\nこんなにも待ち遠しく\nなるとはな…", 1, 1932, 1, 102, 8, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("軍人の本分は日々の\n研鑽にあるからな\n今日も鍛錬に\n行かないか？", 2, 1933, 1, 1, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おお、今日も鍛錬の\n時間だったか！\nすまないな\nすぐ行く！", 2, 1934, 1, 2, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私は子供ではない！\nが…たまには童心に\n帰りたい時もある…", 2, 1935, 1, 3, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴公にも、飴を\nくれてやろうか？\nあまいぞ～！\n美味しいぞ～！", 2, 1936, 1, 4, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私と歩きたいのか…？\nそうだな。二人で\n散歩でも行こうか", 2, 1937, 1, 101, 8, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴公と共にいられる\nことは私の喜びだ\nこれからも\nよろしく頼むぞ", 2, 1938, 1, 102, 8, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うむ、いい朝だ\n本国の夜明けを\n思い出してしまうな！", 2, 1939, 1, 1, 1, 105302, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ昼時だな\n鍛錬の手を緩めて\n昼食にするか", 2, 1940, 1, 2, 1, 105302, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寝る前に…あと少し\nだけ、鍛錬を…", 2, 1941, 1, 3, 1, 105302, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヴァイス\nフリューゲルの一員と\nして恥ずかしくないよう\n身なりを整えなくては", 3, 1942, 1, 1, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふう…軍人たるもの\n常日頃、油断は\nできないのだが…\nお、落ち着くな…", 3, 1943, 1, 2, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うむ…このかわいさ…\n本国に持って\n帰りたい…", 3, 1944, 1, 3, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このともし火\n戦いに明け暮れる\n我らの心を\n癒すものだな…", 3, 1945, 1, 4, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はあ～、ぽかぽか…\nい、いや！\n気を緩めないぞっ！", 3, 1946, 1, 5, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うおおおおおっ！\n鍛錬、鍛錬\n鍛錬っ！！", 3, 1947, 1, 6, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつ戦いになっても\n困らぬように\n腹八分目に\nしておくのだ！", 3, 1948, 1, 7, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うむ…脳細胞が\n活性化してきたぞ\n読書は大事だな", 3, 1949, 1, 8, 1, 105302, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私たちの騎空艇\nどんなデザインに\nしよう…？", 1, 1951, 1, 1, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("団員募集の\nポスター\n作ろうっと♪", 1, 1952, 1, 2, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("父さん…\n今頃どこで\n何してるんだろ？", 1, 1953, 1, 3, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎空艇に乗って、\n誰もいったことがない\n場所を見つけたいな", 1, 1954, 1, 4, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("父さん以上の\n世界一の\n騎空士になりたい！", 1, 1955, 1, 5, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仲間と行く空の旅…\n何度想像しても\nドキドキするなぁ", 1, 1956, 1, 101, 4, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("父さん…\n私にもね、大切な\n仲間ができたよ", 1, 1957, 1, 102, 8, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕事の依頼？\nすぐに支度\nしてくるね！", 2, 1958, 1, 1, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえねえ！\n団員募集のポスター\n一緒に作ろうよ！", 2, 1959, 1, 2, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なーにー？\nどうしたの？\n今呼んだよね？", 2, 1960, 1, 3, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今は休憩中だよ？\nだからあなたも\nゆっくりしてて", 2, 1961, 1, 4, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私にとってあなたは\nとっても頼りになる、\n自慢の団員だよ！", 2, 1962, 1, 101, 4, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さんに会えたら、\n大切な仲間として\nあなたを紹介するね！", 2, 1963, 1, 102, 8, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！\n体の調子はどう？\n今日は頑張れそう？", 2, 1964, 1, 1, 1, 105701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえねえ、お昼\n食べに行こうよ！\nお腹空いちゃった", 2, 1965, 1, 2, 1, 105701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…あれ？\nおしゃべりしてたら\nもうこんな時間？", 2, 1966, 1, 3, 1, 105701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうせならオシャレな\n騎空士って\n呼ばれたいな", 3, 1967, 1, 1, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ、疲れた～…\nちょっとだけ\n休んじゃおっと", 3, 1968, 1, 2, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よし！　キミは\n今から団長代理だ！\n…なんてね♪", 3, 1969, 1, 3, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り～♪\n気持ちが\n落ち着く～…", 3, 1970, 1, 4, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これって\n騎空艇に\n置けるかな…？", 3, 1971, 1, 5, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんな仕事でも\nこなせるような\n体力がないとね…！", 3, 1972, 1, 6, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あむっ…うん！\n美味しい～！\n今度作ってみよう♪", 3, 1973, 1, 7, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("空を冒険するには\n色んなことを\n知っておかないと…", 3, 1974, 1, 8, 1, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…戻らなくなったよ\nどうすれば元に\n戻る…？", 1, 1976, 1, 1, 1, 105702, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇だよ…\nどこかに強い人は\nいないか？", 1, 1977, 1, 2, 1, 105702, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ジョブチェンジ！\n…叫んでも\n戻らないよ", 1, 1978, 1, 3, 1, 105702, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今のうちに、\n魔物退治の\n仕事に行くね！", 1, 1979, 1, 4, 1, 105702, 0, 0);
