INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます！\nお掃除の方、\nはじめていきますね", 2, 2155, 1, 1, 1, 190801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("皆さん、お昼ごはんの\nご要望がありましたら\n用意致しますよ♪", 2, 2156, 1, 2, 1, 190801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここは夜でも\nにぎやかですね", 2, 2157, 1, 3, 1, 190801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…\n少しうとうと\nしてしまった", 1, 2158, 1, 1, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("室内だし兜を脱ぐか\n…いや\nやはりやめておこう", 1, 2159, 1, 2, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋にいると\n鎧が蒸し暑くなるが\n我慢せねば…", 1, 2160, 1, 3, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕事が門番だからか\n部屋にいても\nじっとしてしまう…", 1, 2161, 1, 4, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年と会話したことを\n思いだすと\n自然と楽しくなるな", 1, 2162, 1, 5, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年のことを考えると\n顔がにやけてしまう", 1, 2163, 1, 101, 4, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年は今頃\n平和に過ごせて\nいるかな…", 1, 2164, 1, 102, 8, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん？　悪いが\n兜は脱がないぞ", 2, 2165, 1, 1, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私と遊びたいのか？\nそう言われても\n何をしていいやら…", 2, 2166, 1, 2, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鎧が重くないかって？\n大丈夫。けっこう\n鍛えているからな", 2, 2167, 1, 3, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年、寒くはないか？\nいや自分がこうなので\n人が薄着に見えてね", 2, 2168, 1, 4, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君といると、兜の中が\nいつもより暑いんだ", 2, 2169, 1, 101, 4, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私としゃべりたい？\n物好きだな\nでも、嬉しいよ", 2, 2170, 1, 102, 8, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早いな少年\nえ？　私の仕事に\n合わせてくれたのか", 2, 2171, 1, 1, 1, 104701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食の誘い？\n嬉しいけど\n人前では食べないんだ", 2, 2172, 1, 2, 1, 104701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王宮騎士団の\n日報を書かなければ…\n『何事もなし』、と", 2, 2173, 1, 3, 1, 104701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鎧を着ているから\n感触が分かりづらい\nのが残念だ…", 3, 2175, 1, 2, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、かわいいな…\n私には似合わないが\nぎゅ…ってしよう", 3, 2176, 1, 3, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("良い香りだ…\n普段はどうしても\n鉄くさくなるからな", 3, 2177, 1, 4, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わかっていたけど\n鎧を着たまま暖炉に\nあたると暑い…", 3, 2178, 1, 5, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兜を脱がずに食べる\nうん、段々コツが\n掴めてきた…", 3, 2180, 1, 7, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兜があっても\n意外と本くらいは\n難なく読めるんだ", 3, 2181, 1, 8, 1, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("居心地よくて\nゴロゴロしちゃうよ～\n…いつも通りだね", 1, 2183, 1, 1, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドングリの木\n近くに生えてない？", 1, 2184, 1, 2, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("快適な寝床があれば\nそれだけで幸せだねぇ", 1, 2185, 1, 3, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしと一緒に\nだらけてくれる人が\nいそうだねぇ", 1, 2186, 1, 4, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここなら牧場よりも\n速く配達が\n届きそうだね～", 1, 2187, 1, 5, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんパン買ったし\nあいつにも\n分けてあげよう", 1, 2188, 1, 101, 4, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつと一緒に\nだらけられたら\n最高に幸せだね", 1, 2189, 1, 102, 8, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドングリでも\nつまみながら\n一緒にゲームしようよ", 2, 2190, 1, 1, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("横になりたいから\n枕になっておくれよ～\nあんたあったかいしさ", 2, 2191, 1, 2, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドングリあげるから\nあんパン買ってきて～", 2, 2192, 1, 3, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("う～\n疲れちゃったよ～\nおんぶして運んで～", 2, 2193, 1, 4, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたといると\nリア充って\n感じがするよ", 2, 2194, 1, 101, 4, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたが一生\n世話してくれたら\n人生安泰なんだけどね", 2, 2195, 1, 102, 8, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわ～っ…\nおはよう…あたしは\nまだ眠いよ", 2, 2196, 1, 1, 1, 102601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろお昼寝でも\nしたい気分だねぇ", 2, 2197, 1, 2, 1, 102601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("徹夜でゲームするけど\nあんたもどうだい？\nあたしは強いよ", 2, 2198, 1, 3, 1, 102601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ…だめだこれ。\n気持ち良くて\n落ちそう…", 3, 2200, 1, 2, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいものに\n囲まれて寝るのも\nよさそうだねぇ…", 3, 2201, 1, 3, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("心身ともに\nリラックスした状態で\nぐうたら出来そうだね", 3, 2202, 1, 4, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふい～…\nごくらくごくらく…\n暖かいねぇ", 3, 2203, 1, 5, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べてすぐ寝ると\n牛になるって\n本当なのかな？", 3, 2205, 1, 7, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おー！　この本なら\nあたしも居眠りせずに\n読めそうだよ", 3, 2206, 1, 8, 1, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソル…\nおっきな街だなぁ…", 1, 2208, 1, 1, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ロザリア…\nきっと、いるよね？", 1, 2209, 1, 2, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近、弓の練習\nサボっちゃってるな…", 1, 2210, 1, 3, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日の私は\n森番じゃなくて\n家番だよ！", 1, 2211, 1, 4, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっとだけ\n慣れてきたかも？", 1, 2212, 1, 5, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか、\nあの人と一緒に…", 1, 2213, 1, 101, 4, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…なんか最近、\nあの人のこと\nばっかり…", 1, 2214, 1, 102, 8, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もしよかったら\n街に出かけない？", 2, 2215, 1, 1, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この部屋、\n妖精さんも\n気に入るかも！", 2, 2216, 1, 2, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は\nなににしよっか？", 2, 2217, 1, 3, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はどこ行く？", 2, 2218, 1, 4, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまには二人で…\nな、なんちゃって！", 2, 2219, 1, 101, 4, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近、\nずっと楽しいんだ！\nあなたのおかげかな", 2, 2220, 1, 102, 8, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！\n今日も一緒に\n頑張ろうね！", 2, 2221, 1, 1, 1, 106301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼はどうする？\nあなたのオススメに\n連れて行って欲しいな", 2, 2222, 1, 2, 1, 106301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルは\n夜でも賑やかだね！", 2, 2223, 1, 3, 1, 106301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁっ！\nすっごく\nふわふわだよ！", 3, 2225, 1, 2, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわい～！\nぎゅってしたく\nなっちゃうかも！", 3, 2226, 1, 3, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん\nなんか…いい匂い？", 3, 2227, 1, 4, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すっごいなー\nあったかいなー！", 3, 2228, 1, 5, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁっ、おいしい！\nもっと食べたい\nかも…！", 3, 2230, 1, 7, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("も、文字は苦手…\nでも、頑張らないと\nだよね…！", 3, 2231, 1, 8, 1, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にんじんとピーマンを\n食べないでいい方法\nないかな…", 1, 2233, 1, 1, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カップケーキが\n食べたいな…", 1, 2234, 1, 2, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("予習が終わりました！\nさて、次は復習を\nしないと…", 1, 2235, 1, 3, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人の部屋にいる\n私って…もしかして\nふしんしゃなんじゃ？", 1, 2236, 1, 4, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("男の人は、みんな\nへんたいだと\n聞きました…", 1, 2237, 1, 5, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人に、一緒に\n遊んでほしいけど…\nな、なんていえば？", 1, 2238, 1, 101, 4, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早く大人になりたいな\n…あの人と同じくらい", 1, 2239, 1, 102, 8, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼ、防犯魔石を\n鳴らしますよ！？", 2, 2240, 1, 1, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へんたい！？　…\nあ、あなたでしたか～\nやっぱりへんたーい！", 2, 2241, 1, 2, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ宿題です\nやっておいて\nくださいね", 2, 2242, 1, 3, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、遅刻ですよ\n待っていたんですから", 2, 2243, 1, 4, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にらめっこですか？\nあ、あなたの前で変顔\nするのはちょっと…", 2, 2244, 1, 101, 4, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの…何歳まで\n子供だと思いますか？", 2, 2245, 1, 102, 8, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("顔を洗って、着替えて\n朝ごはんを食べて、\n歯を磨いて…", 2, 2246, 1, 1, 1, 103601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("て、鉄棒の練習！？　\nほ、他のことを\nしませんか？", 2, 2247, 1, 2, 1, 103601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ね、眠くないです\n子供ではありません\nから…ふわぁ", 2, 2248, 1, 3, 1, 103601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひと休みしよっと\n………うん、\nひと休みおしまい♪", 3, 2250, 1, 2, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("つ、つぶらな瞳には\n弱いんです", 3, 2251, 1, 3, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リラックスできますね\n集中力も\n上がりそうです", 3, 2252, 1, 4, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいと\n眠くなっちゃうな…\n勉強しなくちゃなのに", 3, 2253, 1, 5, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ピーマンもこれくらい\nおいしければ\nいいのに…", 3, 2255, 1, 7, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本、むずかしい\n…もっと勉強\nがんばらなくちゃ", 3, 2256, 1, 8, 1, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はみんなに\nなにを読んで\nあげようかしら", 1, 2258, 1, 1, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("子どもたちと同じ\n目線で考えるのが\n大事よね", 1, 2259, 1, 2, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お天気が良い日は\nみんなでお散歩に\n行きたいわね～", 1, 2260, 1, 3, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鬼ごっこにかくれんぼ\n…みんなは\nどっちが好きかしら", 1, 2261, 1, 4, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お遊戯会の配役、\n考え出すと\n大変だわ～", 1, 2262, 1, 5, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼は優しいから、\nきっと良い\nお父さんになるわね", 1, 2263, 1, 101, 4, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼には私がいないと\n…っていうのは少し\n過保護すぎるかしら？", 1, 2264, 1, 102, 8, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("保育園の行事を\n考えてるんだけど…\n良い案ないかしら？", 2, 2265, 1, 1, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度、子どもたちと\nおやつを作るから、\n食べに来てね", 2, 2266, 1, 2, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よかったら一緒に\n絵本を作らない？", 2, 2267, 1, 3, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたはいつも元気ね\n先生も見習わないと♪", 2, 2268, 1, 4, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先生は\nずーっと、ずーっと、\nあなたの味方だからね", 2, 2269, 1, 101, 4, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたみたいな\nいい子をお世話できて\n先生は幸せものだわ", 2, 2270, 1, 102, 8, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう～\nちゃんと朝ごはんは\n食べた？", 2, 2271, 1, 1, 1, 101501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼寝の時間ね♪\nあなたも一緒に\n寝ましょうか", 2, 2272, 1, 2, 1, 101501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すっかり真っ暗ね。\n今日も一日、\nよくできました♪", 2, 2273, 1, 3, 1, 101501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかねぇ♪\n年甲斐もなく、\n飛び跳ねちゃいそう", 3, 2275, 1, 2, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あらあら、かわいい！\n保育園のみんなに\n見せてあげたいわ", 3, 2276, 1, 3, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りね～\n保育園にも\n置こうかしら", 3, 2277, 1, 4, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寒い日は、ここで\n子どもたちに絵本を\n読んであげましょ♪", 3, 2278, 1, 5, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美味しい～♪\n遠足に持っていったら\nみんな喜びそう", 3, 2280, 1, 7, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなが\n楽しめる読み聞かせの\n方法特集♪　素敵ねぇ", 3, 2281, 1, 8, 1, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("世界の前に、\nこの部屋を征服\nしてやろう♪", 1, 2283, 1, 1, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("拠点とはやはり\n斯くあるべきじゃの", 1, 2284, 1, 2, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眷属の物はわらわの物\n故に、この部屋は\nわらわの部屋じゃな！", 1, 2285, 1, 3, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("永く眠っている間に\n随分と世界は変わった\nようじゃな…", 1, 2286, 1, 4, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うるさいのう～\nまったく、近頃の\n若いもんは…", 1, 2287, 1, 5, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あやつが来てから\n動悸が治まらぬ…\n如何ような病で\nあろうかの…", 1, 2288, 1, 101, 4, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眷属よ、どこに行った\nのじゃ？\nわらわの世話を\n許可するのじゃ", 1, 2289, 1, 102, 8, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いずれ世界は\n我が手中に収まる\nふふふ、\n楽しみじゃのう", 2, 2290, 1, 1, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眷属よ、わらわから\n離れてはならんぞ！\n子供に戻ってしまう\nではないか！", 2, 2291, 1, 2, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トマトジュースが\n欲しいのじゃ！\n野菜ジュースでは\nダメだぞ！", 2, 2292, 1, 3, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("蚊にくわれたぞ！\nわらわの血を吸う\nとは～！", 2, 2293, 1, 4, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こら、頭をなでるな\nお主はこの姿でも\n子供扱いするのか？", 2, 2294, 1, 101, 4, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お主が望むなら世界の\n半分をくれてやっても\n良いのじゃぞ？", 2, 2295, 1, 102, 8, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝早くから感心じゃの\nさすがわらわの\n眷属じゃ", 2, 2296, 1, 1, 1, 104401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("太陽は苦手じゃ…\nこの部屋の中で\n過ごそうぞ", 2, 2297, 1, 2, 1, 104401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜も更けてきた！\nわらわ達の時間は\nこれからじゃ～♪", 2, 2298, 1, 3, 1, 104401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よい座り心地じゃ\nわらわの玉座としよう", 3, 2300, 1, 2, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("可愛いではないか\nわらわの眷属に\nしてやろうかのう", 3, 2301, 1, 3, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うむ、良い気持ちじゃ\nこれを作った者、\n褒めてつかわすぞ", 3, 2302, 1, 4, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたたかい…\n身も心も\n浄化されるようじゃ", 3, 2303, 1, 5, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("吸血鬼のわらわが、\nこのようなもの…\nうまい♪", 3, 2305, 1, 7, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このまま大人の姿を\n保つ方法…どこかに\n書いてないかのう", 3, 2306, 1, 8, 1, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いろんな人がいて\nいろんな服を着てて…\n目の保養になります♪", 1, 2308, 1, 1, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レイ様への新作\nどんな服にしよう…\n方向性が絞れない～！", 1, 2309, 1, 2, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("忘れないうちに\n隠し糸のメンテナンス\nやっておこうっと！", 1, 2310, 1, 3, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むっ！　あの人の\nスリーサイズは…\nほほう…なるほど♪", 1, 2311, 1, 4, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ノゾミさんの\n衣装はああして\nチカさんのは…", 1, 2312, 1, 5, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私がアイドル…\n…実感ないけど\n精一杯やってみよう", 1, 2313, 1, 101, 4, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まさか私が\nアイドルになるなんて\n思ってなかったです", 1, 2314, 1, 102, 8, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんですかぁ？\n衣装作りで疲れて\n眠いんですぅ…", 2, 2315, 1, 1, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あーっ！　また\n服がほつれてる…\nしょうがないですね", 2, 2316, 1, 2, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はっ！　ちょうど今\n新しいデザインが\n思い浮かびました！", 2, 2317, 1, 3, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇そうですね？\n時間あるなら仕事\n手伝ってください！", 2, 2318, 1, 4, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしました？\n新しい服が\n欲しくなりましたか？", 2, 2319, 1, 101, 4, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんのおかげで\nカルミナでも\n頑張れてますよ！", 2, 2320, 1, 102, 8, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます…\nなんで朝って毎日\nやってくるんでしょう", 2, 2321, 1, 1, 1, 105401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹空きましたね\n騎士さんはちゃんと\n御飯食べましたか？", 2, 2322, 1, 2, 1, 105401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の方が\n作業が捗るのは\n私だけですかね？", 2, 2323, 1, 3, 1, 105401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このふかふか具合\nいい素材を\n使ってますね", 3, 2325, 1, 2, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("小さくて可愛い♪\nそうだ！　レイ様の\nぬいぐるみを…！", 3, 2326, 1, 3, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういう時くらい\n何も考えずに\nリラックスしないと♪", 3, 2327, 1, 4, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("炎を使った服って\nカッコ良いかも…\nでも材料がな～…", 3, 2328, 1, 5, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何をするにも\n食事は大切！\n体力が資本です！", 3, 2330, 1, 7, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私もいつか\nデザインを\nまとめて本に…", 3, 2331, 1, 8, 1, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("またお魚を\n捕りにいこうかな♪", 1, 2333, 1, 1, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろみんなも\nお腹が空くころ\nじゃないですか～？", 1, 2334, 1, 2, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここなら、\n日焼けの心配は\nありませんね！", 1, 2335, 1, 3, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お刺身に焼き貝…\nお腹が魚介類を\n求めてますっ！", 1, 2336, 1, 4, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぐのも食べるのも\n大得意です！", 1, 2337, 1, 5, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人と二人で\n浜辺を散歩…\n素敵ですねぇ", 1, 2338, 1, 101, 4, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人に水着を\n褒めてもらえたら、\nすごく嬉しいなぁ", 1, 2339, 1, 102, 8, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまには釣りじゃなく\n一緒に素潜りでも\n行きませんか？", 2, 2340, 1, 1, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("男の子に水着を\n見られるのって\n少し緊張しちゃいます", 2, 2341, 1, 2, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギルドハウスの\nみんなとも、\n海に行きたいですね！", 2, 2342, 1, 3, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの水着、\n私が選んであげます！", 2, 2343, 1, 4, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぎの練習なら\n付き合いますよ！\n手取り足取り♪", 2, 2344, 1, 101, 4, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着姿が好きなら\nいくらでも\n着てあげますよぉ♪", 2, 2345, 1, 102, 8, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝の海も\n幻想的で\nいいですよねぇ～！", 2, 2346, 1, 1, 1, 107501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼はみんなで、\n海鮮バーベキューとか\nどうでしょう！", 2, 2347, 1, 2, 1, 107501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の海は星が\nきれいですよ！\n見に行きましょう！", 2, 2348, 1, 3, 1, 107501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぎ疲れたので\nちょっと休憩です～", 3, 2350, 1, 2, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたにも、\n可愛い水着を\n着せてあげたいです", 3, 2351, 1, 3, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだか、\nリゾート気分です…", 3, 2352, 1, 4, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふい～、泳ぎで冷えた\n身体を暖めましょう～", 3, 2353, 1, 5, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいひ～です～\nこれ、海水浴にも\n持っていきたいですね", 3, 2355, 1, 7, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("南国のフルーツ図鑑\n…じゅるり…", 3, 2356, 1, 8, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わ～♪　おいしそ…\nか、かわいいですね～", 3, 2358, 1, 10, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これくらい大きな貝…\n食べたいな～\n食べたいな～～", 3, 2359, 1, 11, 1, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好で\n部屋をうろつくのは\n不思議な感じがします", 1, 2360, 1, 1, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("南国の果実を使って\n主さまにデザートを\nお作りしましょう", 1, 2361, 1, 2, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくの水着ですし\nこれから定期的に\n海水浴に行きたいです", 1, 2362, 1, 3, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の生き物も、\n森の生き物に負けず\n可愛かったです…", 1, 2363, 1, 4, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クロールの練習なら、\n部屋でもできそうです", 1, 2364, 1, 5, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまに、水着姿を\n褒めていただけた…\nえへへ♪", 1, 2365, 1, 101, 4, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着で主さまの\nお世話をしたら、\n喜びますでしょうか…", 1, 2366, 1, 102, 8, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お疲れでしたら\nわたくしの膝を\nお使いくださいね", 2, 2367, 1, 1, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さま、海の家で\nつかうおこづかいを\n渡しておきますね", 2, 2368, 1, 2, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の美しさは、\n森とはちがう\n魅力がありました", 2, 2369, 1, 3, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この髪飾りですか？\n造花ですから\n水の中も平気です", 2, 2370, 1, 4, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着でくっついて\n眠ると、いつもより\n密着して暖かいです", 2, 2371, 1, 101, 4, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はじめての海が、\n主さまと一緒で\n幸せです♪", 2, 2372, 1, 102, 8, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます。\n泳ぎに行く準備は\n万端です", 2, 2373, 1, 1, 1, 107601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("午後は泳ぐのをやめて\nスイカ割りなど\nいかがでしょう？", 2, 2374, 1, 2, 1, 107601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜も更けてきました…\n波の音を聞きながら\n少しお話しませんか？", 2, 2375, 1, 3, 1, 107601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あぅ…この家具には、\n人をダメにする魔法が\nかけられています…", 3, 2377, 1, 2, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ♪\nあなたも、海水浴に\n行きますか？", 3, 2378, 1, 3, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り…\nきっと主さまも\n気に入ります", 3, 2379, 1, 4, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは暖かいです…\n後ほど主さまと一緒に\nあたりましょう", 3, 2380, 1, 5, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳いだ後の食事は\n一段と美味しく\n感じます", 3, 2382, 1, 7, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("深海魚の生態…\nこれは主さまにも\nお伝えしなくては…", 3, 2383, 1, 8, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("顔立ちが、主さまに\n似ております…\nかわいらしい♪", 3, 2385, 1, 10, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかですね\n主さまのようです♪", 3, 2386, 1, 11, 1, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お掃除、お掃除\nふんふふ～ん☆\nあ、聞かれてました？", 1, 2387, 1, 1, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日焼けには回復魔法が\n効きますよ。どうして\n逃げるんですか～！", 1, 2388, 1, 2, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はドジを\nしませんように！", 1, 2389, 1, 3, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("接客業を極めれば\nメイドとして\n成長できるかも？", 1, 2390, 1, 4, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着って\n動きやすいんですけど\n人の目が気になります", 1, 2391, 1, 5, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人の気持ちを知る\n魔法とかあれば…\nな、なんでもないです", 1, 2392, 1, 101, 4, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着でご奉仕したら、\nあの人は喜ぶかな？", 1, 2393, 1, 102, 8, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑いのでしたら、\n私が魔法で涼しく…\nえ？　いらない？", 2, 2394, 1, 1, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何か御用ですか？\n特にないのでしたら、\nお話ししましょう♪", 2, 2395, 1, 2, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着姿でも\nメイドはメイドです\nご奉仕しますよ！", 2, 2396, 1, 3, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃっ！　あ、危うく\n転ぶところでした…\n…きゃうっ！", 2, 2397, 1, 4, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうかしましたか？\nあなたの御用なら、\n喜んでお受けしますよ", 2, 2398, 1, 101, 4, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着姿をあなたに\n見られると、\nドキドキしちゃいます", 2, 2399, 1, 102, 8, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝は暑くてやる気が\n出ない？　でしたら、\nえぇい、元気になぁれ", 2, 2400, 1, 1, 1, 107701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹がぺこぺこなら、\nお昼は海の家で\n食べましょう♪", 2, 2401, 1, 2, 1, 107701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の浜辺でお散歩も\nいいですね。たくさん\n転びそうですけど…", 2, 2402, 1, 3, 1, 107701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休憩しながら、\nお掃除すれば\n一石二鳥です！", 3, 2404, 1, 2, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きれいにすれば\nかわいさも倍増\nですよ～♪", 3, 2405, 1, 3, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵な香りです～\n救護院に置けば、\nみんな喜ぶかも～", 3, 2406, 1, 4, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいですね…\nはっ！　いけません！\nメイドがサボるなんて", 3, 2407, 1, 5, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("料理のできない\nメイドなんて…\nはぐはぐ、おいしい♪", 3, 2409, 1, 7, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着姿で接客をすると\n売り上げが倍になる\n…本当ですか、これ", 3, 2410, 1, 8, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ♪\n南の島まで\n乗せてください！", 3, 2412, 1, 10, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだか、\n人魚姫に\nなった気分です♪", 3, 2413, 1, 11, 1, 107701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなで過ごす\n休日っていいわよね…\nずっと続かないかな", 1, 2414, 1, 1, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に浮輪でぷかぷか\n浮かぶのって\n癖になりそう", 1, 2415, 1, 2, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビーチにいると\n日焼けが心配だわ", 1, 2416, 1, 3, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着姿って楽よね。\n室内だとちょっと\n落ち着かないけど…", 1, 2417, 1, 4, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、泳ぎの練習なんて\nしないからね！", 1, 2418, 1, 5, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("楽しすぎて立場を\n忘れそう…あんたの\nせいなんだから！", 1, 2419, 1, 101, 4, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなで遊んで\n美味しいもの食べて\nほんっとに楽しいっ♪", 1, 2420, 1, 102, 8, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マジであっついわね…\nよっし！　海に入って\n涼みましょ！", 2, 2421, 1, 1, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シャワー浴びたばかり\nなのに…また、遊び\nたくなってきたわ！", 2, 2422, 1, 2, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("遊び足りないって？\nしょうがないわね…\n付き合ってあげるわ♪", 2, 2423, 1, 3, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一応伝えておくけど\n猫って水が苦手なの！\nわかった！？", 2, 2424, 1, 4, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしと話したいの？\nふふ。\nまぁ、いいわよ。\nほら隣に座りなさい", 2, 2425, 1, 101, 4, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなに楽しいの\n初めてかも…\nずっと続けばいいのに", 2, 2426, 1, 102, 8, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("は、早起きしたのは、\n楽しみで眠れなかった\nからじゃないわよ！", 2, 2427, 1, 1, 1, 107801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食後のストレッチ\n終わり！　さあ、\nビーチが待ってるわ！", 2, 2428, 1, 2, 1, 107801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の海に散歩に\n行こうかな～\nあんたも来なさいよ☆", 2, 2429, 1, 3, 1, 107801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海ではしゃぎすぎて\n疲れたわ…ちょっと\n休もうかしら？", 3, 2431, 1, 2, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな魔物がいたら\n操るのも楽しいかも", 3, 2432, 1, 3, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃう～♪\nまるで南国にいる\n気分ね♪", 3, 2433, 1, 4, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかぁい♪\n身体が冷えてきたから\n丁度いいわ！", 3, 2434, 1, 5, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("運動後のご飯って\nなんでこんなに\n美味しいんだろ♪", 3, 2436, 1, 7, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんなカナヅチでも、\n絶対必ず泳げる方法、\n書いてないかしら？", 3, 2437, 1, 8, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたもあたしが\n操ってあげる！\nなんてね～♪", 3, 2439, 1, 10, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リゾートリゾートっ\nのんびりしましょ♪", 3, 2440, 1, 11, 1, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここなら思う存分\nデスクワークに\n励めるわね！", 1, 2441, 1, 1, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("武器のメンテナンスも\nしっかりしないと\n最高効率は望めないわ", 1, 2442, 1, 2, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("準備をしっかり整えて\nもっともっと\n稼がなくちゃね！", 1, 2443, 1, 3, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し休んだら\n次のバイトに\n行ってくるわね！", 1, 2444, 1, 4, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好でここに\nいるのって\n気恥ずかしいわね…", 1, 2445, 1, 5, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミが望むなら\n今日のバイト\n休んでもいいわよ？", 1, 2446, 1, 101, 4, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミだけね…\n私のことをここまで\n理解してくれるのは", 1, 2447, 1, 102, 8, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("普段と違う格好\nだからって\nそんなに見ないでよ…", 2, 2448, 1, 1, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミを立派な\nバイト戦士にするのが\n師匠としての役目よね", 2, 2449, 1, 2, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ次のバイトに\n行かないと…\nキミも一緒に来る？", 2, 2450, 1, 3, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("効率は大事だけど\nゆっくりするのも\n悪くないわね", 2, 2451, 1, 4, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒の時間が楽しくて\nバイトのことを\n忘れちゃいそうね", 2, 2452, 1, 101, 4, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミと一緒なら\nどんなミッションも\n楽勝ね！", 2, 2453, 1, 102, 8, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう、いい朝ね！\n今日もめいっぱい\n稼ぐわよ！", 2, 2454, 1, 1, 1, 108001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうお昼だったのね…\n内職のバイトに\n集中しすぎちゃったわ", 2, 2455, 1, 2, 1, 108001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スケジュールは、と…\nこういう管理の徹底が\n効率を生み出すのよ♪", 2, 2456, 1, 3, 1, 108001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しっかり働いて休む…\n最高効率にまた一歩\n近づいたわね", 3, 2458, 1, 2, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なごんじゃうわね…\nよぉし、次のバイトも\n頑張らないと！", 3, 2459, 1, 3, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りね…\n働く意欲が\n湧いてくるわ", 3, 2460, 1, 4, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身体が冷えたから\n助かるわ…冷えは\n女の天敵だもの", 3, 2461, 1, 5, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海のバイトは\n体力勝負よ\nエネルギーはしっかり\n摂取しないとね！", 3, 2463, 1, 7, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("座学も大切ね\nもっと知識を\n身につけないと…", 3, 2464, 1, 8, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の楽園みたいね…\n今だけは効率を\n忘れちゃいそう…", 3, 2466, 1, 10, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("落ち着くわ…\n海とひとつになった\n気分ね！", 3, 2467, 1, 11, 1, 108001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと休憩にゃ～\n潮風は体に\n良くないにゃ～", 1, 2468, 1, 1, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("猫グッズで\n海の家を飾りたいにゃ", 1, 2469, 1, 2, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の幸は美味しいけど\n水はイヤだにゃ…", 1, 2470, 1, 3, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("開店にゃ！\nこのたい焼きなら\nきっと大繁盛にゃ！", 1, 2471, 1, 4, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海と言えば水着にゃ\n似合ってるかにゃ？", 1, 2472, 1, 5, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミが頼むなら\n手伝ってあげても\nいいにゃ", 1, 2473, 1, 101, 4, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしの宝は\nここにあるにゃ～", 1, 2474, 1, 102, 8, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃ？\nそんなに見つめても\n何も出ないにゃ", 2, 2475, 1, 1, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今からキミを\nあたしの相棒に\n任命するにゃ！", 2, 2476, 1, 2, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これから\n開店の準備にゃ\nキミも手伝って\nくれるのかにゃ？", 2, 2477, 1, 3, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の家で出す\n新しいメニューを\n考え中なのにゃ～", 2, 2478, 1, 4, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミと一緒なら\n売上げナンバーワンに\nなれるにゃ！", 2, 2479, 1, 101, 4, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミと一緒にいると\n楽しくて、もっと\nいたくなるにゃ", 2, 2480, 1, 102, 8, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようにゃ！\n今日も頑張って\nいくにゃー！", 2, 2481, 1, 1, 1, 107901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹すいたにゃ～…\nお魚、ちょっとだけ、\nつまみ食いするにゃ", 2, 2482, 1, 2, 1, 107901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日の準備は万端にゃ\nいつでも\n出発できるにゃ", 2, 2483, 1, 3, 1, 107901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このふかふか具合\nまるで子猫の\n毛並みのようにゃ～", 3, 2485, 1, 2, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃにゃ～\nなんてかわいさにゃ～", 3, 2486, 1, 3, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この匂い…\nもう少し香ばしいと\nいいかもしれないにゃ", 3, 2487, 1, 4, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃ～…\nあったかくて\nぬくぬくだにゃ～", 3, 2488, 1, 5, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("働くにはまず体力にゃ\nしっかり食べて\nスタミナアップ\nだにゃ!", 3, 2490, 1, 7, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\nここにお宝が\n眠ってるんだにゃ", 3, 2491, 1, 8, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シードレイクにゃ！\n本物は怖かったけど、\nぬいぐるみなら\nかわいいにゃ～", 3, 2493, 1, 10, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貝なのにふかふかの\nクッションにゃ！\n屋台の前にも\n置いてみたいにゃあ", 3, 2494, 1, 11, 1, 107901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人の家って、道場とは\n違った香りがするね", 1, 2495, 1, 1, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと退屈だね…\nあの人をからかいに\n行こうかな♪", 1, 2496, 1, 2, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("普通の女の子みたいに\n遊びたいって思う\nこともあるんだよね", 1, 2497, 1, 3, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("剣の手入れを怠らない\nようにしないと。\nいざという時、困るし", 1, 2498, 1, 4, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もっと\n上手く立ち回って\n出世したいな", 1, 2499, 1, 5, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おかえりなさい！\nふふ、なんだか奥さん\nになった気分だよ♪", 1, 2500, 1, 101, 4, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("恥ずかしくて、あなた\nを見られないよ…\n私らしくないなぁ…", 1, 2501, 1, 102, 8, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私、お話好きなんだ。\nどうせなら楽しい話を\nしたいな♪", 2, 2502, 1, 1, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("女の子っぽい子と、\n男勝りな子、あなたは\nどっちが好き？", 2, 2503, 1, 2, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ見回りの\n時間かな。あなたも\n一緒に行く？", 2, 2504, 1, 3, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("構って欲しいのかな？\nそれじゃ一緒に\nランニングに行こうか", 2, 2505, 1, 4, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("二人で出かけるなら、\n手を繋がないとね。\nあはは、冗談冗談♪", 2, 2506, 1, 101, 4, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、あなた♪\nおや、顔が真っ赤だ！\n…ふふ、私も、かな？", 2, 2507, 1, 102, 8, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私は朝から鍛錬だよ。\n慣れてるけど大変だ。\nお互いに頑張ろうね", 2, 2508, 1, 1, 1, 103701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鍛錬でお腹ぺこぺこ。\nお昼ごはんが\n楽しみだね", 2, 2509, 1, 2, 1, 103701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も一日見回りと\n鍛錬を頑張ったよ。\nあなたもお疲れさま", 2, 2510, 1, 3, 1, 103701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いざという時のため\nにも、休憩は大事だね", 3, 2512, 1, 2, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうものには\n今まで\n縁がなかったけど。\nうん、可愛いね♪", 3, 2513, 1, 3, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("精神統一に通じる\nものがあるね。\nふぅ、癒されるなぁ", 3, 2514, 1, 4, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいなぁ。\nたまにはのんびり\nしようか", 3, 2515, 1, 5, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鍛錬後はすごくお腹が\n空くんだよね。\nう～ん、おいしい♪", 3, 2517, 1, 7, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("剣術書だけで強くなる\nには飛びぬけた才能と\n努力が必要だよね", 3, 2518, 1, 8, 1, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正義の刃で\n悪を挫く！\n…キマったッス♪", 1, 2520, 1, 1, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒーローの\n秘密特訓を\n始めるッスよ～！", 1, 2521, 1, 2, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正義の味方目指して\n今日も明日も\n全力ッスよ♪", 1, 2522, 1, 3, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一日一善！\nヒーローだったら\n当たり前ッス♪", 1, 2523, 1, 4, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうッスか\nこのポーズ！\nイイ感じッスか？", 1, 2524, 1, 5, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("た、たまには\nよく頑張ったねって\n褒めてほしいッス…", 1, 2525, 1, 101, 4, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自分を信じてくれる\nあんたと一緒なら\n何でもやれるッス！", 1, 2526, 1, 102, 8, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おつかれッス♪\n冒険の準備は\nばっちりッスよ！", 2, 2527, 1, 1, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたんッスか？\n…はっ！　もしや敵が\n迫ってるんスかっ！？", 2, 2528, 1, 2, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("べ、別に\n頭を撫でてほしいとか\n思ってないッスよ？", 2, 2529, 1, 3, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スーパーヒーロー\nトラタイガーは\n絶対無敵ッス！", 2, 2530, 1, 4, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたと自分で\n正義の心を燃やして\n悪を一網打尽ッス！", 2, 2531, 1, 101, 4, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたと一緒だと\n幸せな気持ちに\nなるんッス…♪", 2, 2532, 1, 102, 8, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、早いッスね～♪\n今日も一日一善\nよろしくッス！", 2, 2533, 1, 1, 1, 100501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一休みしながら\nヒーローについて\n語り合うッスよ～！", 2, 2534, 1, 2, 1, 100501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜のパトロールで\n一緒に平和を\n守るッス！", 2, 2535, 1, 3, 1, 100501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅぅ…\n落ち着くッスね\n戦士の休息ッス♪", 3, 2537, 1, 2, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くぅぅ、可愛いッス…\nヒーローが守るべき\n愛らしさッスね！", 3, 2538, 1, 3, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんスかこの香り？\nすぅぅ…ふぅぅ…\n力がみなぎるッス！", 3, 2539, 1, 4, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("優しい光ッスね…\nヒーローの優しさ\nそのものッス！", 3, 2540, 1, 5, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あむあむあむ…\nんぅう、元気が溢れて\n止まらないッス！", 3, 2542, 1, 7, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トラタイガーのお話は\n笑いあり涙ありで\n超おすすめッス！", 3, 2543, 1, 8, 1, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハッピーハロウィン\nお父さん、お菓子は…\n食べられないね", 1, 2545, 1, 1, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トリックオアトリート\nお菓子をくれないと\n不吉な占いをします", 1, 2546, 1, 2, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、あなたの後ろで\n霊のみなさんが\n踊り始めました", 1, 2547, 1, 3, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("霊感がいつも以上に\n冴えているので\n占いの調子も良好です", 1, 2548, 1, 4, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("父はハロウィンが\n大好きだそうです\n大胆な格好をする子が\n多いので…", 1, 2549, 1, 5, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたは霊たちにも\n大人気ですよね\n私も見てほしいな…", 1, 2550, 1, 101, 4, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンの賑やかさ\n今は好きです…\nあなたといられるので", 1, 2551, 1, 102, 8, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("霊のみなさんとの\nダンスパーティー…\n楽しみです", 2, 2552, 1, 1, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さん、元気だね\nえ？　ここは色んな\n女の子に会えて幸せ？", 2, 2553, 1, 2, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンのお菓子\n食べすぎちゃったな…\nでも、美味しかった…", 2, 2554, 1, 3, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの女難の相…\n悪化していますね\nお祓いが必要かも", 2, 2555, 1, 4, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの、霊のみなさんが\nあなたと踊りたいと…\nえっと、私も…", 2, 2556, 1, 101, 4, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと手を繋ぐと\n胸が苦しくなります\nでも、繋ぎたいな…", 2, 2557, 1, 102, 8, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハッピーハロウィン…\n父が元気なので\n今日の運気は良好です", 2, 2558, 1, 1, 1, 108101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("父はお昼寝中です\n本当に寝ているかは\n私にも分かりませんが", 2, 2559, 1, 2, 1, 108101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さん、\nもう眠っちゃったの？\n…眠れるんだったっけ", 2, 2560, 1, 3, 1, 108101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("落ち着きますね…\n霊のみなさんも\n喜んでいます", 3, 2562, 1, 2, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("つん、つん。ふふっ♪\n癒やされます…", 3, 2563, 1, 3, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("精神が研ぎ澄まされる\n香りですね…\n占いが捗ります", 3, 2564, 1, 4, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいね\nお父さん…\nえ？　分からない？", 3, 2565, 1, 5, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("霊のみなさんは\n食べられないので…\n私がいただきます", 3, 2567, 1, 7, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さんを元に戻す\n手掛かり…\n書かれていないかな？", 3, 2568, 1, 8, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁ、お菓子が沢山…", 3, 2570, 1, 12, 1, 108101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("無料でプリンが\nもらえるなんて、\nハロウィンはすごいの", 1, 2572, 1, 1, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("生きてるときも、\nミヤコはハロウィンが\n好きだった気がするの", 1, 2573, 1, 2, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなに仮装を\n見せつけて、\nプリンをもらうの～", 1, 2574, 1, 3, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この仮装で、\nみんなに恐怖を\n教えてやるの！", 1, 2575, 1, 4, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アオーン、アオーン！\nミヤコ、狼女に\nなりきってるの～", 1, 2576, 1, 5, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイツに秘密で、\nパーティーの\n飾り付けをするの♪", 1, 2577, 1, 101, 4, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイツが狼男の\n仮装をすれば、\nおそろいなの～", 1, 2578, 1, 102, 8, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プリンをくれなきゃ、\nオマエをカボチャに\nしてやるの～", 2, 2579, 1, 1, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンは幽霊でも\n参加できるから\n楽しいの～！", 2, 2580, 1, 2, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プリンがないなら\nカボチャプリンを\n食べればいいの！", 2, 2581, 1, 3, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プリンの可能性は\n無限大なの～", 2, 2582, 1, 4, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オマエの隣で\nプリンを食べると、\nいつもより美味しいの", 2, 2583, 1, 101, 4, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オマエが死んでも、\nミヤコはずーっと\n一緒にいてやるの～", 2, 2584, 1, 102, 8, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝ごはんは\nカボチャプリンなの！\nハロウィンっぽいの～", 2, 2585, 1, 1, 1, 108201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランチは豪華に\nプリンアラモードなの", 2, 2586, 1, 2, 1, 108201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜は幽霊たちと\nハロウィンするの！\nオマエも来るの！", 2, 2587, 1, 3, 1, 108201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("幽霊にも休息は\n必要なの！\nプリンもってこいなの", 3, 2589, 1, 2, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オマエもミヤコの\nパーティーに\n招待してあげるの～", 3, 2590, 1, 3, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("癒されるの～\nまるで天国なの～", 3, 2591, 1, 4, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここでなら、\n焼きプリンが\n作れるの！", 3, 2592, 1, 5, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腹が減っては\nハロウィンは\nできぬなの！", 3, 2594, 1, 7, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("丸ごとカボチャ\nプリン特集！？\n美味しそうなの～♪", 3, 2595, 1, 8, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子がたくさんで、\nミヤコはとっても\nハッピーなの♪", 3, 2597, 1, 12, 1, 108201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔女以外にも、\n色々な仮装を\nしてみたいわね", 1, 2599, 1, 1, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("チョコやアメよりも、\nアタシに相応しい\nスイーツがあるはず…", 1, 2600, 1, 2, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子の食べ過ぎは、\nお母さんに\n怒られるかも…", 1, 2601, 1, 3, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好で学院に\n行ったら、\nみんな驚くかしら", 1, 2602, 1, 4, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大人のレディは、\nどういうハロウィンを\n過ごすべきかしら…？", 1, 2603, 1, 5, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子、アイツの分も\nとっといてあげよ！\n大人の余裕ってやつね", 1, 2604, 1, 101, 4, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイツを魅了する\n魔法とかないかしら？", 1, 2605, 1, 102, 8, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おしゃれスイーツを\nくれなきゃ\nイタズラするわよ！", 2, 2606, 1, 1, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アタシの大人センスで\nアンタに似合う仮装を\n選んであげるわ！", 2, 2607, 1, 2, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("不気味よねぇ…\nジャックオーランタン\nこ、怖くないわよ？", 2, 2608, 1, 3, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンが楽しくて\n宿題やり忘れてたわ…\nて、手伝って～！", 2, 2609, 1, 4, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子をもらうのも\nアンタと一緒なら\n恥ずかしくないわ！", 2, 2610, 1, 101, 4, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アタシのエスコートを\n任せられるのは、\nアンタだけなんだから", 2, 2611, 1, 102, 8, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝食はオシャレに\nグリーンスムージー！\n…に、にがぁ", 2, 2612, 1, 1, 1, 108301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼下がりはカフェで\n優雅なティータイム\n…憧れるわ～", 2, 2613, 1, 2, 1, 108301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンナイトの\nはじまりよ！\n街に繰り出しましょ！", 2, 2614, 1, 3, 1, 108301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あう～、お菓子の\n食べすぎで\n動けな～い", 3, 2616, 1, 2, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンタも仮装する？\nいまよりもーっと\nかわいくなるわよ！", 3, 2617, 1, 3, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大人な香りに\n包まれてる～♪", 3, 2618, 1, 4, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ポカポカね～♪\n…ああー！\nチョコが溶けてる！", 3, 2619, 1, 5, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしい～♪\n…じゃなくて！\nび、美味ですわ～", 3, 2621, 1, 7, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服かわい～♪\nって、なにこの値段！\nお小遣い何年分よ！？", 3, 2622, 1, 8, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、お菓子なんかで\n喜ぶほど、子供じゃ…", 3, 2624, 1, 12, 1, 108301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はどんな策で団長を\nからかってみようか…", 1, 2626, 1, 1, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("む？\n血の臭いがするな\n祭りの時間か☆", 1, 2627, 1, 2, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("平和に飼い殺される\n前に、混沌の愛を\n育みたいね", 1, 2628, 1, 3, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本気を出した団長と\nいつか手加減なしに\n殺り合いたいな", 1, 2629, 1, 4, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おばさん呼ばわりする\n新米騎士の小娘を\n懲らしめてやろうか", 1, 2630, 1, 5, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("胸を触られるまで\n誓約のことなど\nすっかり忘れていたな", 1, 2631, 1, 101, 4, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まさかこのワタシが\nプロポーズするとはな\n…笑えるじゃないか", 1, 2632, 1, 102, 8, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("面白い暇つぶしを\n思いついたんだ\n戯れに付き合え☆", 2, 2633, 1, 1, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("退屈で死にそうだ\n愉しい話題を\nワタシに提供してくれ", 2, 2634, 1, 2, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだ、暇なのか？\n心躍ることでも探しに\n出かけようではないか", 2, 2635, 1, 3, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このワタシを愉快に\nさせてくれる事でも\nあったのか？", 2, 2636, 1, 4, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワタシに求婚した男の\n数だと？\nいちいち覚えてないな", 2, 2637, 1, 101, 4, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最強無敵の女と\n結婚できるんだ\n誇りに思えよ☆", 2, 2638, 1, 102, 8, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なにか愉快なことが\n起こりそうな朝だ☆\nワクワクするね", 2, 2639, 1, 1, 1, 107101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーむ、腹がすいたな\n愉快なことで\nこの空腹を満たしたい", 2, 2640, 1, 2, 1, 107101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これからは大人の\n時間だ。愉しみ方を\n知りたいのかい？", 2, 2641, 1, 3, 1, 107101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このワタシとした事が\n穏やかな気分に\nなってしまうとは…", 3, 2643, 1, 2, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("可愛い姿をしたものが\n惨たらしい\n醜態を晒すのを\n想像してしまう", 3, 2644, 1, 3, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪くはない香りだ\nだが、ワタシは血の\n臭いを嗅ぎたいぞ☆", 3, 2645, 1, 4, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬるい、ぬるすぎる！\n地獄の業火には\nほど遠い熱さだ！", 3, 2646, 1, 5, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワタシの腕前に\n勝るとも劣らない\nなかなかの味だ", 3, 2648, 1, 7, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("意中の男性を絶対に\n落とす方法…？\nく、下らんっ！", 3, 2649, 1, 8, 1, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日はあの釣り場に\n行くとしようかな\nあの子も誘ってみるか", 1, 2651, 1, 1, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷはーっ！\n体を動かしたあとの\n一杯は格別だね", 1, 2652, 1, 2, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("天気が良いと\n昼寝か釣りかで\n迷っちまうな…", 1, 2653, 1, 3, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大物が釣れたときの\n快感は、他じゃ\n味わえないね", 1, 2654, 1, 4, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふあぁ～…\n昼寝でもするか", 1, 2655, 1, 5, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ…\nあの子、見た目より\n根性あるんだね", 1, 2656, 1, 101, 4, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの子が強くなるには\nどんな魚を食べさせて\nあげればいいのやら…", 1, 2657, 1, 102, 8, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("姉御って呼ぶんじゃ\nないよ。からかうと\nタダじゃおかないよ", 2, 2658, 1, 1, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("釣りのコツ？\n何事も経験が大事だ\n今から行くかい？", 2, 2659, 1, 2, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたのさ？\n助太刀が必要かい？\nアタシにまかせときな", 2, 2660, 1, 3, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("困ってる人がいたら\nまた力を貸しておくれ\n頼りにしてるよ", 2, 2661, 1, 4, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なにか困りごとかい？\nどうやら昼寝は\nまた今度だね", 2, 2662, 1, 101, 4, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よしよし！\nお人好しのお前さんを\n労ってあげるよ", 2, 2663, 1, 102, 8, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう、お前さん\n魚屋は早起きでなきゃ\nつとまらないよ？", 2, 2664, 1, 1, 1, 105601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼飯かい？　今朝\n仕入れた魚があるんだ\n食べてみるかい？", 2, 2665, 1, 2, 1, 105601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜釣りにぴったりの\n月が出てるよ\nいい釣りが出来そうだ", 2, 2666, 1, 3, 1, 105601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コイツに座って\nのんびり釣りが\nできりゃいいのにな", 3, 2668, 1, 2, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よしよし…♪\nおっと、かわいい物も\nつい抱きしめちまうな", 3, 2669, 1, 3, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これで魚の臭いを\n消せれば、猫も\n寄らなくなるのかね", 3, 2670, 1, 4, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冬場の釣りも\nこれくらい暖かけりゃ\nいいんだけどね", 3, 2671, 1, 5, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腹が減っては\n釣りもできぬ、ってな\nまずは腹ごしらえだ", 3, 2673, 1, 7, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へぇ…こんな魚が\nいたとは…いつか\n釣りたいもんだね", 3, 2674, 1, 8, 1, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("流石に室内で\n魔法ぶっぱしたら\n怒られるよねぇ", 1, 2676, 1, 1, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("可愛い女の子が\nたくさんいる！\nここは楽園か！？", 1, 2677, 1, 2, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなに漫画とか\n勧めてみようかな！\n布教用のがあるし！", 1, 2678, 1, 3, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わ、私一人の\n部屋じゃないから\n色々自重せねば！", 1, 2679, 1, 4, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「ぬるぽ」\n…くっ、\n誰も反応なしか！", 1, 2680, 1, 5, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はどの漫画を\n貸そうかなー♪", 1, 2681, 1, 101, 4, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次の定期巡回で\nとっておきの店に\n連れてってあげよう！", 1, 2682, 1, 102, 8, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君に似合いそうな\n衣装を買ったよ！\n君もいざ魔法少女に！", 2, 2683, 1, 1, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さあ！\n暇なら定期巡回に\nレッツラゴー！", 2, 2684, 1, 2, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦闘だけじゃなくて、\n日常にも役立つ\n魔法を習得したいね！", 2, 2685, 1, 3, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新魔法思いついた！\n私って天才！？", 2, 2686, 1, 4, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("決め台詞は超大事！\n君の決め台詞も\n私が考えてあげよう！", 2, 2687, 1, 101, 4, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私ってもしやリア充？\n…そんなバカな！\n非リア代表のはずが！", 2, 2688, 1, 102, 8, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよー…\n徹夜で本読んでたから\nまだ眠い～", 2, 2689, 1, 1, 1, 101301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼飯食べて、\n午後の定期巡回も\n頑張りましょー！", 2, 2690, 1, 2, 1, 101301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜からが、\nオタ活本番でしょ！", 2, 2691, 1, 3, 1, 101301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふいー！\nくつろいで本を読む！\n最高だねー！", 3, 2693, 1, 2, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君、可愛いね～♪\n魔法少女の\n使い魔みたい！", 3, 2694, 1, 3, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("良い匂いに\n釣られてしまった…\nまさか、孔明の罠！？", 3, 2695, 1, 4, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かいけど、\nここで本を読むのは\nちょっち危ないかな", 3, 2696, 1, 5, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ウマ―！\nこれの詳細きぼんぬ！", 3, 2698, 1, 7, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こ、古代語の本！？\n現代語でおk…", 3, 2699, 1, 8, 1, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふふっ♪\n次はどんな悪戯を\nしてやろうかしら♪", 1, 2701, 1, 1, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("幻影湖の霧を吸った\n人間たちの\nリアクションって、\nサイコーよねぇ～♪", 1, 2702, 1, 2, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("室内だけとはいえ…\n自由に動けるって、\nやっぱりいいわ～♪", 1, 2703, 1, 3, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("改めて見ると良い\n部屋ね…悪戯とか\nしやすそうだしぃ♪", 1, 2704, 1, 4, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私を封じていた部屋\nなのに…急に居心地が\n良くなったわね♪", 1, 2705, 1, 5, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたの頭、座り心地\n良いわね…私専用の\n椅子にしてあげる♪", 2, 2706, 1, 1, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外は大変みたいねぇ…\nまあ、私は好き勝手に\nやらせてもらうわ♪", 2, 2707, 1, 2, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("顔に落書された？\n誰か知らないけど、\n悪いことする奴も\nいるものねぇ～♪", 2, 2708, 1, 3, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フィオのやつ…\nどこをウロチョロ\nしてるのかしら？", 2, 2709, 1, 4, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人間の朝は大変ねぇ…\n私はその様を見ながら\nゆっくりするわね♪", 2, 2710, 1, 1, 1, 190901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("う～私も、お日様を\n浴びながら、お外を\nお散歩したーい！", 2, 2711, 1, 2, 1, 190901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この暗さ…閉じ込め\nられていた時を\n思い出すわね…", 2, 2712, 1, 3, 1, 190901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪戯しすぎて\n疲れたから、ちょっと\n休憩しよっと♪", 3, 2714, 1, 2, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ガイド妖精たる私が、\nこんな造形物に\n惹かれる…わけが……\nかわいい♪", 3, 2715, 1, 3, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香りを囮にして、\n周りに悪戯を仕込む…\n完璧ね♪", 3, 2716, 1, 4, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("不思議ねぇ…私は\n温度とか関係ないのに\n離れられないわ", 3, 2717, 1, 5, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食事の必要がない体…\nつまり、食べたければ\n食べていいのよね～♪", 3, 2719, 1, 7, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へぇ…最近はこんな\n悪戯もあるのねぇ…\nあいつで試さないと♪", 3, 2720, 1, 8, 1, 190901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリークリスマス！\n歌で幸せを\n届けます…！", 1, 2722, 1, 1, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと出会えたのは\n偶然ではなくて…\nクリスマスの奇跡だと\n思うんです", 1, 2723, 1, 2, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスは華やかで\nつい子供のように\nはしゃいでしまいます", 1, 2724, 1, 3, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("曲が書けるのは\nあなたが側に\nいてくれるからです…", 1, 2725, 1, 4, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("感動を与えられる歌…\nあなたと一緒になら\n生み出せるはず…", 1, 2726, 1, 5, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスの幸せを\nあなたと\n感じ合えたらな…", 1, 2727, 1, 101, 4, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの幸せを願った\nクリスマスソング…\nいつか披露しますね", 1, 2728, 1, 102, 8, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みなさんの笑顔を\n守りたいから…\n私は歌い続けます", 2, 2729, 1, 1, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歌を届ける\nサンタさんに\nなりたいな…", 2, 2730, 1, 2, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お暇でしたら\nクリスマスのお祝いを\nしませんか？", 2, 2731, 1, 3, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ステージに立つ前に\n喉を整えないと…\n発声練習は念入りに…", 2, 2732, 1, 4, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まわりはかわいい子\nばっかりだけど…\nこの服なら\nアピールになるかな？", 2, 2733, 1, 101, 4, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歌でならいくらでも\nあの人への気持ちを\n込められるのに…", 2, 2734, 1, 102, 8, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も一日\n幸せな歌で世界が\n包まれますように…", 2, 2735, 1, 1, 1, 108401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お茶を飲みながら\n好きな音楽を\n語り合いませんか？", 2, 2736, 1, 2, 1, 108401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、寝かしつけの\n子守唄を\nお望みですか？", 2, 2737, 1, 3, 1, 108401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかですね\n心地良すぎて\n眠ってしまいそう…", 3, 2739, 1, 2, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵…\n優しい歌みたいに\n気持ちが落ち着く…", 3, 2740, 1, 3, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("インスピレーションが\n溢れてくる…\nいい曲が書けそう…", 3, 2741, 1, 4, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この光みたいに\n灯火になるような\n歌を歌いたい…", 3, 2742, 1, 5, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("喉の健康のためにも\n食事はしっかり\nとるようにしています", 3, 2744, 1, 7, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("物語には\n曲作りのヒントが\n詰まっているんです", 3, 2745, 1, 8, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("絵が飛び出してくる\nなんて…精霊が宿って\nいるのでしょうか？", 3, 2747, 1, 14, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、可愛い…♪\nちょっとだけ触っても\nいいですよね…？", 3, 2748, 1, 15, 1, 108401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスでも、\n演劇の練習は\nしっかりやらないと！", 1, 2749, 1, 1, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あうぅ…\nクリスマスの準備が\n終わらないよぅ…", 1, 2750, 1, 2, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アヤネちゃんが\n摘み食いしないように\n見ておかないと…", 1, 2751, 1, 3, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サンタさんみたいに、\n皆に笑顔で接する…\nうぅ…私には無理ぃ…", 1, 2752, 1, 4, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しいお洋服～♪\nスズメお姉ちゃんに\nお礼をいわないと♪", 1, 2753, 1, 5, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんの為に、\nプレゼントを\n用意しないと♪", 1, 2754, 1, 101, 4, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマス…\n恋人の日…ひゃわっ！\nわ、私ってば何を…！", 1, 2755, 1, 102, 8, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリー\nクリスマスです、\nお兄ちゃん♪", 2, 2756, 1, 1, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そ、そんなに\n見られると…\n恥ずかしいよぉ…", 2, 2757, 1, 2, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃわぁっ！？\n急に触られると、\n驚くからやめてぇ…", 2, 2758, 1, 3, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ…クリスマスの\n準備を手伝って\nくれるんですか？", 2, 2759, 1, 4, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんと\n過ごすクリスマス、\n楽しみですぅ…♪", 2, 2760, 1, 101, 4, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスはその…\n二人で…あうぅ…\nなんでもないですぅ…", 2, 2761, 1, 102, 8, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うう…パーティーが\n楽しみで、あんまり\n眠れなかったよぅ…", 2, 2762, 1, 1, 1, 108501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ケーキを食べられなく\nなっちゃうから、\nお昼は軽めにしないと", 2, 2763, 1, 2, 1, 108501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと眠いけど…\n今日は少しだけ\n夜更かししたいです♪", 2, 2764, 1, 3, 1, 108501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかぁ…\nクリスマスの準備中に\n眠くなっちゃいますぅ", 3, 2766, 1, 2, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子と一緒に\nおままごとしたいな♪", 3, 2767, 1, 3, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい匂い…♪\nみんなで\nアロマパーティー\nしたいなぁ…♪", 3, 2768, 1, 4, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬっくぬく…♪\nもう、ここから\n離れたくないよぉ…♪", 3, 2769, 1, 5, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はむはむ…♪\nクリスマスのお料理\nより美味しいかも～♪", 3, 2771, 1, 7, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すごい…\nクリスマスの\n演劇って、\nこんなにあるんだ…", 3, 2772, 1, 8, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すごい…まるで、\nクリスマスの演劇を\n観てるようですぅ…♪", 3, 2774, 1, 14, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とっても可愛いです♪\nお芝居の相手役に\nしたいなぁ…♪", 3, 2775, 1, 15, 1, 108501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("甘ぁいケーキも、\nデッカイ七面鳥も、\nぜーんぶ私のだー♪", 1, 2776, 1, 1, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("毎日が\nクリスマスだったら\nいいのにな～♪", 1, 2777, 1, 2, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プレゼントはあるし、\n料理は美味しいし、\nクリスマス最高ー♪", 1, 2778, 1, 3, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここでぷうきちの\nクリスマス一発芸♪\n『無茶ぶりするな！』", 1, 2779, 1, 4, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷうきちがいつもより\n重いかも…太ったの？\n『衣装の重さだよ！』", 1, 2780, 1, 5, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんが\n一緒にいてくれると\nクリスマス楽しいね♪", 1, 2781, 1, 101, 4, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんに抱きつく\nと、なんだかドキドキ\nする…なんでかな？", 1, 2782, 1, 102, 8, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリークリスマス♪\nプレゼントは、\nいつでも受付中だよ♪", 2, 2783, 1, 1, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このクマさん耳\n可愛いでしょ♪\nぷうきちと\nお揃いなんだー♪", 2, 2784, 1, 2, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃん…私、\n甘ぁいケーキが\n食べたいなぁ…♪", 2, 2785, 1, 3, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスぷうきちは\nぬくぬく感が凄いよ！\nお兄ちゃんもさわる？", 2, 2786, 1, 4, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ…お兄ちゃんの\n手は、大きくて、\n暖かくて大好き～♪", 2, 2787, 1, 101, 4, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("来年のクリスマスも、\nこうやって\nお兄ちゃんに\n甘えていたいな～♪", 2, 2788, 1, 102, 8, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あれぇ…\n私のケーキはぁ…？\n『ちゃんと起きろ』", 2, 2789, 1, 1, 1, 108601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼はデッカイ\n七面鳥が食べたーい♪\n『夜まで我慢しろ』", 2, 2790, 1, 2, 1, 108601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『もう寝る時間だぞ』\nサンタさんが来る\nまで起きてるぅ…", 2, 2791, 1, 3, 1, 108601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このふかふか具合…\nぷうきち！\n負けてられないよ！", 3, 2793, 1, 2, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子、\nすっごくかわいい～♪\n『ライバル登場か！』", 3, 2794, 1, 3, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("良い匂い…あっ！\nぷうきちにこの\n匂いを移せば…！\n『匂い袋にするな』", 3, 2795, 1, 4, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったか～い♪\nえへへ、ぷうきちも\nあっためてあげる♪", 3, 2796, 1, 5, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷうきち！　これ、\nとってもおいしいよ♪\n『食べすぎるなよ』", 3, 2798, 1, 7, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、大人の私なら、\nこれぐらい…読め…\n『無理するな…』", 3, 2799, 1, 8, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("絵が飛び出す…\nぷうきちに絵本を\n入れれば、イタズラに\n使えるかも…♪", 3, 2801, 1, 14, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、可愛いけど…\nぷうきちサンタの方が\n可愛いんだからぁ…！", 3, 2802, 1, 15, 1, 108601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("着物も慣れると\n動きやすいものさ", 1, 2803, 1, 1, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鼻緒が緩んでしまった\n下駄で修業は\n無理があったかな…", 1, 2804, 1, 2, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("小腹が空いた…\nユイが作った餅、\nまだ食べられるかな？", 1, 2805, 1, 3, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("服装も変わったし\nいつもと違う戦い方を\n想定しないと…", 1, 2806, 1, 4, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…ヒヨリは動きすぎて\n着崩れしてないか\n心配だ", 1, 2807, 1, 5, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これからもずっと\n仲間と、彼と\n一緒に…", 1, 2808, 1, 101, 4, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("願いを叶えるために\nもっと自分を\n鍛えていかないと！", 1, 2809, 1, 102, 8, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("頭の飾りがずれてた？\nそうか、直してくれて\nありがとう", 2, 2810, 1, 1, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("着物がそんなに\n珍しい？\nキミも着てみる？\n…冗談だよ", 2, 2811, 1, 2, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("肩掛けの触り心地が\n気に入った？\nならもっと触る？", 2, 2812, 1, 3, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ、この刀？\n釣り仲間に見繕って\nもらったんだ", 2, 2813, 1, 4, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミといると\n気持ちが段々と\n安らいでいくよ", 2, 2814, 1, 101, 4, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミは私の行く先を\n照らしてくれる\n光のような存在だよ", 2, 2815, 1, 102, 8, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう\n朝の修行を始めるけど\nキミもどう？", 2, 2816, 1, 1, 1, 108901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この時間に軽く\n休憩をとるといい\n能率がよくなるよ", 2, 2817, 1, 2, 1, 108901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう夜か…\n明日もまた頑張ろう\nそれじゃ、おやすみ", 2, 2818, 1, 3, 1, 108901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…疲れていたのかな\nもう少しで眠る\nところだった…", 3, 2820, 1, 2, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ、正月衣装を\n着せてやるのも\nよさそうだ", 3, 2821, 1, 3, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…いい香りだ\n慌ただしい日々から\n心が解放される", 3, 2822, 1, 4, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この心地よさ…\n寝てしまわないよう\n気をつけないと", 3, 2823, 1, 5, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしいけど\n帯がきつくなる前に\n手を止めよう…", 3, 2825, 1, 7, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外を出歩くのも\nいいけど、中で\n読書もありだな", 3, 2826, 1, 8, 1, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…騎士クンって\nおせち料理で\n何が好きなんだろう？", 1, 2828, 1, 1, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("着物でお掃除や\nお洗濯するの\n慣れてきた♪", 1, 2829, 1, 2, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年は\nどんな福袋を\n買おうかな…♪", 1, 2830, 1, 3, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お餅に使う調味料\nみんなで違うから\n色々用意しなきゃ", 1, 2831, 1, 4, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほっぺがお餅みたいに\nぷにぷに…\n食べ過ぎちゃった…", 1, 2832, 1, 5, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("来年も、再来年も\nみんなで一緒に\n新年を迎えたいな", 1, 2833, 1, 101, 4, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お願いです…\nいつかこの気持ちが\n伝わりますように…", 1, 2834, 1, 102, 8, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("髪飾りが落ちそう？\nじゃあ…騎士クン\nつけ直してくれる？", 2, 2835, 1, 1, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("着物が着たいの？\nじゃあ今度一緒に\n買いに…行く？", 2, 2836, 1, 2, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、騎士クン\nお雑煮のお餅\nいくつ入れたい？", 2, 2837, 1, 3, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外、寒かったよね？\nはいこれ。熱い甘粥\n飲むと温まるよ", 2, 2838, 1, 4, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年は騎士クンと…\nえっ？　騎士クン！？\nな、なんでもないよ！", 2, 2839, 1, 101, 4, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンの願い事\nわたしが\n叶えてあげたいな…", 2, 2840, 1, 102, 8, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう\n太陽の光に当たると\n元気が出るよ", 2, 2841, 1, 1, 1, 108801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ごはん\n作らなきゃ…\n騎士クンも食べる？", 2, 2842, 1, 2, 1, 108801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一日が終わるのは\nあっという間だよね\n一年も同じなのかな？", 2, 2843, 1, 3, 1, 108801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…\n帯も少し\nゆるめちゃおう…", 3, 2845, 1, 2, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月用に\n着物を縫って\nあげたいな", 3, 2846, 1, 3, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これでお肌が\n保湿出来たら\nいいのになぁ", 3, 2847, 1, 4, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～…\nぬくぬくしてて\n動きたくないよ～", 3, 2848, 1, 5, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…冬眠しないのに\n熊さんみたいに\n食べちゃいそう", 3, 2850, 1, 7, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("年末年始は\n告白のチャンス…\nむ、無理無理！", 3, 2851, 1, 8, 1, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんな忙しそう…\n待っててね、\nすぐ助けるから！", 1, 2853, 1, 1, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ユイちゃんと\nレイさん…よし！\nどっちも手伝おう！", 1, 2854, 1, 2, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、着崩れてる！\nわわっ、どうしよ！\n帯が結べないよー！", 1, 2855, 1, 3, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("初詣楽しみー！\n出店はどこから\n行こうかな？", 1, 2856, 1, 4, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月だし\nみんなで楽しく\n遊んじゃおー！", 1, 2857, 1, 5, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん…\n騎士くんはお正月\n何してるんだろ…", 1, 2858, 1, 101, 4, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ううぅー…\n騎士くんを見てると\nドキってなっちゃう…", 1, 2859, 1, 102, 8, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしから\nおいしそうな匂い？\nくんくん…ソースだ！", 2, 2860, 1, 1, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヘアピンが…\n拾ってくれたんだ！\nありがとう騎士くん！", 2, 2861, 1, 2, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("髪飾りがかわいい？\n耳の近く触りたい？\n…優しくね？　", 2, 2862, 1, 3, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("グローブで食べるの\n大変そう？　特訓して\n今はお箸も使えるよ！", 2, 2863, 1, 4, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えっ、ほっぺが赤い？\nそうかな…？\n気のせい気のせい！", 2, 2864, 1, 101, 4, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士くんといるとね…\nなんでもない！\nまだ内緒っ！", 2, 2865, 1, 102, 8, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよー！\n今日も明るく元気に\nがんばろー！", 2, 2866, 1, 1, 1, 108701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹すいてない？\n一緒にご飯食べよ！\n何にしようかなー♪", 2, 2867, 1, 2, 1, 108701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もいっぱい\nがんばったー！\nいつも？　…そう？", 2, 2868, 1, 3, 1, 108701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休憩休憩♪\nちょっと休んで\nガンガン動くぞー！", 3, 2870, 1, 2, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい♪\nでも、壊しそうで\nちょっと怖い…", 3, 2871, 1, 3, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁー♪\nいい香りー…\n気分スッキリ♪", 3, 2872, 1, 4, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほっこりしてて\nぬくぬく…\n丸まりたい…", 3, 2873, 1, 5, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ど、どうしよう…！\n手が、止まんないよ！", 3, 2875, 1, 7, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へー…お年玉って\n昔はお餅だったんだ\n…今のほうがいいね", 3, 2876, 1, 8, 1, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("甘いチョコの香りを\n漂わせて…ふふっ\nこれで準備万端ですわ", 1, 2878, 1, 1, 1, 109001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここを私のチョコで\n埋め尽くしますわ", 1, 2879, 1, 2, 1, 109001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エプロンを着て\nあの方を待つ私…\nまるで…クスクス", 1, 2880, 1, 3, 1, 109001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キッチンはどこかしら\n今のうちに作って\nおきたいものが…", 1, 2881, 1, 4, 1, 109001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのお方を私のチョコ\nなしでは生きられない\n体に…ふふっ\n冗談ですわ…", 1, 2882, 1, 5, 1, 109001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このチョコは運命の味\n一口食べれば私の虜…\nそれも運命ですわ…", 1, 2883, 1, 101, 4, 109001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私ともあろうものが\nなんだかドキドキして\nきましたわ…", 1, 2884, 1, 102, 8, 109001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなた様。私に\n隠しているものなど\nありませんよね…？", 2, 2885, 1, 1, 1, 109001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の手作りチョコです\n味の方にも自信\nありますのよ？", 2, 2886, 1, 2, 1, 109001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し苦いのは\nチョコがビターなだけ\nお気になさらず…", 2, 2887, 1, 3, 1, 109001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("解毒薬はどこに\nいれたかしら…？", 2, 2888, 1, 4, 1, 109001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("運命で結ばれている\nあなた様と私…\nチョコも特別でないと\nいけませんわ", 2, 2889, 1, 101, 4, 109001, 0, 0);
