INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せ、先輩のそばに\n居られて、私\n今、とっても\n幸せです…", 2, 2990, 1, 102, 8, 105501, 0, 0);
