INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいし～\nこれは\n先輩も好きな味かな", 3, 3000, 1, 7, 1, 105501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("す、好きな人に\n近づく方法…", 3, 3001, 1, 8, 1, 105501, 0, 0);
