INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ピアノ…\nどこかにないかな？", 1, 3053, 1, 1, 1, 109401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…\n落ち着くな…", 1, 3054, 1, 2, 1, 109401, 0, 0);
