INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一番得意なのは、\nやっぱり炎魔法かな…\n加減は難しいけど…", 2, 3061, 1, 2, 1, 109401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の故郷は竜の国…\n険しい山脈を\n越えた先にあるんだ", 2, 3062, 1, 3, 1, 109401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アン…？\nあっ、ご、ごめんね！\n間違えちゃった…", 2, 3063, 1, 4, 1, 109401, 0, 0);
