INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろベッドに\n行かないとだね\n…寝相、今夜こそ\n気を付けよう…！", 2, 3068, 1, 3, 1, 109401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("羽を伸ばしたく\nなっちゃうね…ふふ", 3, 3070, 1, 2, 1, 109401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わ、私が持つには\nかわいすぎるかな…\nでも、素敵だね", 3, 3071, 1, 3, 1, 109401, 0, 0);
