INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("火を見ていると\n少し落ち着くんだ…\nへ、変かな？", 3, 3073, 1, 5, 1, 109401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わ、美味しい…！\nこれ、どうやって\n作ったのかな…？", 3, 3075, 1, 7, 1, 109401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本…アンにも\n見せてあげたら\n喜ぶかな、ふふっ", 3, 3076, 1, 8, 1, 109401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("着物はきれいですが\n歩きにくいです…\nいっそ脱いで…ぐふふ", 1, 3078, 1, 1, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、いけません\n着物がはだけて…はっ\nもしやドＳさんが…！", 1, 3079, 1, 2, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この部屋は妄想する\nのにうってつけです…\nぐふふ…じゅるり", 1, 3080, 1, 3, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("扇をゆっくりと開く\nこの感触…なぜだか\n艶めかしさを感じます", 1, 3081, 1, 4, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「マッサージをすると\n言いながらドＳさんの\n手は次第に」…ぐふふ", 1, 3082, 1, 5, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…ドＳさんの視線を\n思い出しながら踊りの\n練習です…イイ！", 1, 3083, 1, 101, 4, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よいではないか\nよいではないか～\nいけませんご堪忍を～", 1, 3084, 1, 102, 8, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ～れ～～～！\nドＳさんもお好きな人\nですねぇ…ぐふふ", 2, 3085, 1, 1, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どこにいてもドＳさん\nの気配を感じ取れる\nようになりました…", 2, 3086, 1, 2, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな場所で\nなんというプレイを！\n…妄想でした", 2, 3087, 1, 3, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クウカを押し倒して\nそのまま…じゅるり\nああっ、着物が…！", 2, 3088, 1, 4, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんは優しいです\n優しいのにドＳとは\nさすが人格破綻者…！", 2, 3089, 1, 101, 4, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんの考えている\nことが伝わってきます\nはい…クウカ脱ぎます", 2, 3090, 1, 102, 8, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眩しい朝日がクウカの\n体を焦がします\n…それもイイ！", 2, 3091, 1, 1, 1, 109501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼のランチは\nクウカがいいだなんて\n大胆過ぎです…じゅる", 2, 3092, 1, 2, 1, 109501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…今夜のドＳさんは\n大胆です…ぐふふ…\nはっ、視線が…！？", 2, 3093, 1, 3, 1, 109501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この心地良さ、\n心が休まりすぎて\n体が疼いてきます…！", 3, 3095, 1, 2, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すごく愛らしいです…\n妄想も出てこない\nくらい…じゅるり", 3, 3096, 1, 3, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香りに包まれて\nいると、いい気持ちに\nなって…いきますぅ…", 3, 3097, 1, 4, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「熱を帯びた体は\nどうしようもなく\n誰かを求め…」ぐふふ", 3, 3098, 1, 5, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹が膨らんで\nいきます…それは\nまるで…ぐふふ", 3, 3100, 1, 7, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クウカの探している\nジャンルはどこに\nありますかね？", 3, 3101, 1, 8, 1, 109501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カチョーフーゲツは\nトーゴクの心を\n表した言葉デスね", 1, 3103, 1, 1, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オー！　新しい忍法を\n思いついたデス！\nさっそく試すデス！", 1, 3104, 1, 2, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トーゴクの天気には\n槍が降る日も\nあるそうデス…", 1, 3105, 1, 3, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("我がショーグンは\n永遠にフメツデース\nいざ出陣デース！", 1, 3106, 1, 4, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("壁に耳あり\n障子に…ん？\nメアリーって誰デス？", 1, 3107, 1, 5, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグンがいれば\nワタシはどんな\n忍法も使いこなせマス", 1, 3108, 1, 101, 4, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("不届き者はどこで\nゴザルデス？　忍法で\n退治してくれヨウ！", 1, 3109, 1, 102, 8, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグン！　新しい\n忍法を覚えたデス！\n見てほしいデース！", 2, 3110, 1, 1, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッツ手裏剣道デス！\n投げてソウロウで\nゴザルデース！", 2, 3111, 1, 2, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふりかかる火の粉は\nワタシが払うデス！\nバンバン！", 2, 3112, 1, 3, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とっておきの忍法が\n吹き荒れるデス！\nよそ見はダメデスヨ？", 2, 3113, 1, 4, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグンは\n何階建てのお城を\n建てたいデスか？", 2, 3114, 1, 101, 4, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("テンシュカクから\n平和な城下町を\n眺めてみたいデス…", 2, 3115, 1, 102, 8, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございマス！\n本日はオヒガラモヨク\n良い日になりそうデス", 2, 3116, 1, 1, 1, 109601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹すいたデース…\nショーグンもご飯に\nしまショウ！", 2, 3117, 1, 2, 1, 109601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("闇討ちに遭わぬよう\n夜は気を付けて\n歩くデスよー？", 2, 3118, 1, 3, 1, 109601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("天下分け目の\n戦いに備えて…\nマッタリデース", 3, 3120, 1, 2, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("口寄せの術で\n召喚したいくらい\nかわいいデース", 3, 3121, 1, 3, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい匂いデ～ス\n香り玉の開発の\n参考になりそうデスね", 3, 3122, 1, 4, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワタシの懐よりも\nゾーリが暖まりマス…\nライバル出現デス…！", 3, 3123, 1, 5, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腹が減っては\n戦はできぬデース！\n天下統一に向けて\n腹ごしらえデス！", 3, 3125, 1, 7, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ムム、暗号文デス！？\n解読には時間が\nかかりそうデース…", 3, 3126, 1, 8, 1, 109601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("掃除も終わりましたし\nそろそろ、食事の\n準備をしなくては", 1, 3128, 1, 1, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("異世界の演劇…\n許されるならば、\n観てみたいです", 1, 3129, 1, 2, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こちらの世界には、\nマヨネーズが普通に\n存在するのですね…", 1, 3130, 1, 3, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こちらの世界は食材も\n面白い物が多いですね\nなにかレシピを\n考えてみましょうか", 1, 3131, 1, 4, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みょんみょんみょん…\n魔法の練習は\nこれぐらいですね", 1, 3132, 1, 5, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("倒木の撤去で思わぬ\n収入となりました\nサレン様に\nお渡ししておかないと", 1, 3133, 1, 101, 4, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("料理を美味しく\n召し上がって頂けると\nメイド冥利につきます", 1, 3134, 1, 102, 8, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お出かけでしたら、\nレムも同行\nさせてくださいね", 2, 3135, 1, 1, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レムにできること\nでしたら、なんでも\nお申し付けください", 2, 3136, 1, 2, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じーー。いえ、\nその髪の長さが少し、\nとても少し、かなり\n少し気になったもので", 2, 3137, 1, 3, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鉄球ですか？\nあれは護身用ですので\n問題はありませんよ？", 2, 3138, 1, 4, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("計算の勉強は\n進んでおりますか？\nレムでよろしければ、\nいつでもお教えします", 2, 3139, 1, 101, 4, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はもっと、大きな\n魔物料理に挑戦します\nワイバーンの姿焼き\nなんてどうでしょうか", 2, 3140, 1, 102, 8, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n朝食の準備が\nできておりますので、\n食卓におこしください", 2, 3141, 1, 1, 1, 109701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食の時間ですね\n何か食べたいものは\nありますか？", 2, 3142, 1, 2, 1, 109701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寝ないのか、ですか？\nメイドの就寝は、\n屋敷で最後と\n決まっておりますので", 2, 3143, 1, 3, 1, 109701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふんわり…\nこのふんわりさは、\n鬼をも黙らせます…", 3, 3145, 1, 2, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ…異世界でも\nかわいいものは\n共通なのですね", 3, 3146, 1, 3, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よい香りですね\n魔女教の悪臭とは\n大違いです", 3, 3147, 1, 4, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬくぬくです…はっ！\nこれはいけません！\n人を…いえ、\n鬼をだめにします！", 3, 3148, 1, 5, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はむはむ…美味しい！\nこの味を再現できたら\n褒めてもらえる\nかもしれません…！", 3, 3150, 1, 7, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("絵がいっぱい…\n異世界の本は\nとても面白いですね", 3, 3151, 1, 8, 1, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("異世界であろうと、\nラムのやるべきことは\n変わらないわ\nまずは休憩するわよ", 1, 3153, 1, 1, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マヨネーズがある\nということは、\nバルスの故郷が近い\nのかもしれないわね", 1, 3154, 1, 2, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この世界では、バルス\nの言う言葉が使われる\nときがあるのね\n忌々しいかぎりだわ", 1, 3155, 1, 3, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ラムたち以外にも\nメイドが居るのね\nラムが…いえ、\n仕事を押しつけるわ", 1, 3156, 1, 4, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…千里眼で視るかぎり\n周囲に異変はないわね\n危険がないなら、\nあとはレムに任せるわ", 1, 3157, 1, 5, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…ラムもまた、\n「お姉ちゃん」って\n呼ばれる日が\nくるのかしらね", 1, 3158, 1, 101, 4, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハッ！　ラムが作る\n蒸かし芋は完璧ね\n…気が向いたら、また\n作ってやろうかしら", 1, 3159, 1, 102, 8, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ラムに構う暇が\nあるなら働きなさい\nそうすれば、\nラムが楽をできるわ", 2, 3160, 1, 1, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ラムに何かを\n期待しても無駄よ\nラムに命令できるのは\nロズワール様だけだわ", 2, 3161, 1, 2, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇なら買い物に\n付き合いなさい\n荷物を\n持たせてあげるわ", 2, 3162, 1, 3, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ラムになんの用？\nふざけた内容なら\nねじ切るわよ", 2, 3163, 1, 4, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そういえば、あなたは\n記憶喪失だったわね…\n思い出す努力をなさい\n…家族が悲しむわよ", 2, 3164, 1, 101, 4, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("蒸かし芋が欲しい？\n随分と厚かましいわね\n…まだ残りがあるから\n好きに食べなさい", 2, 3165, 1, 102, 8, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("だらしない顔ね\n顔を洗って\nしゃんとなさい", 2, 3166, 1, 1, 1, 109801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹が空く時間ね\nラムの昼食を\n用意させてあげるわ", 2, 3167, 1, 2, 1, 109801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メイドが寝るのは\n屋敷で最後…\nラムが寝るために、\nさっさと寝なさい", 2, 3168, 1, 3, 1, 109801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…ここから動かない\nという、誓いを\n立てたくなるわね", 3, 3170, 1, 2, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは…かわいいわね\nもちろん、\nラムほどではないけど", 3, 3171, 1, 3, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…香炉かしら？\nこちらの世界にも\n質のよい物があるのね", 3, 3172, 1, 4, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見つけてしまったの\nかもしれないわ…\nラムの楽園を！", 3, 3173, 1, 5, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…はむっ\nラムの蒸かし芋ほど\nではないけど、\nなかなかいけるわね", 3, 3175, 1, 7, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("異世界ならではの\n面白い内容もあるわね\nとても興味深いわ", 3, 3176, 1, 8, 1, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえパック、\nにゃんにゃか\nにゃかにゃんしよっか", 1, 3178, 1, 1, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時間もあるし、\nこっちの世界の石で\n石積みしようかな", 1, 3179, 1, 2, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私もお姉さんだし、\nサレンさんを\n見習わないと…うん！\n私、すごーく頑張る！", 1, 3180, 1, 3, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この世界は、銀髪で\nハーフエルフでも受け\n入れてくれるのね…\nなんだか嬉しいな", 1, 3181, 1, 4, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のご飯…\nピーマルは\n入ってないわよね…？", 1, 3182, 1, 5, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("また、みんなで\n一緒に買い物に\n行きたいな", 1, 3183, 1, 101, 4, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パック以外から\n家族って呼ばれたの\n初めて…ふふっ♪\nちょっと嬉しいかも！", 1, 3184, 1, 102, 8, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今からパックの\n毛繕いをするけど…\n一緒にする？", 2, 3185, 1, 1, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私も何かお手伝いを…\nあ、そうだ！\n料理とかどうかな！", 2, 3186, 1, 2, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、ここで\n歌の練習って、\nしてもいいかな？", 2, 3187, 1, 3, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…あ、ごめんなさい！\n話しかけられるのって\nあまり慣れてなくて…", 2, 3188, 1, 4, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すごーく頑張るから、\nこれからも勉強を\n手伝ってね", 2, 3189, 1, 101, 4, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せーの、びくとりー！\nふふっ…また、一緒に\nラジーオタイソー\nしようね♪", 2, 3190, 1, 102, 8, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちゃんと起きてる？\nふふっ…よかった。\nあ、べ、別に心配した\nわけじゃないからね？", 2, 3191, 1, 1, 1, 109901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯が楽しみね♪\nあ、こっちの世界って\nまよねーずはあるの？", 2, 3192, 1, 2, 1, 109901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ寝る時間よ。\n夜更かししたら、\nめっ！　だからね！", 2, 3193, 1, 3, 1, 109901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("勉強も終わったし…\nちょっ、ちょっとだけ\n休んでもいいよね…？", 3, 3195, 1, 2, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、かわいい…！\nパックのかわいさに\n匹敵するかも…！", 3, 3196, 1, 3, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("良い香り…\nロズワールの屋敷にも\nこういうのって\nあるのかな？", 3, 3197, 1, 4, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかい…\nずっとここに…はっ！\nダメダメ！　王選の\nために勉強しないと！", 3, 3198, 1, 5, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ…これ美味しい！\nこっちの世界は色んな\n食べ物があるのね。", 3, 3200, 1, 7, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("知らないことが\nいっぱい書いてある…\n異世界の本って、\n面白いのね", 3, 3201, 1, 8, 1, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海ってマジ最高！\nビーチの撮影も\n超楽しいしー♪", 1, 3203, 1, 1, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("20パーって何パ？\n今度ヒデサイに\n聞いてみよっ！", 1, 3204, 1, 2, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の思い出を\nヒデサイと一緒に\n作りたいな～", 1, 3205, 1, 3, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("テンションあがる\n水着ゲットして\n超ラッキーだよ～♪", 1, 3206, 1, 4, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休憩が終わったら\n撮影にもどらないと！\n気合入れてこ♪", 1, 3207, 1, 5, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイとビーチで\nパーティーしたいな～\n超楽しそうだよね！", 1, 3208, 1, 101, 4, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイといると\n楽しくてうれしくて…\nカレシってこんな感じ\nなのかなぁ？", 1, 3209, 1, 102, 8, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見て見て～！\n夏らしいネイルに\nしてみたんだ～♪", 2, 3210, 1, 1, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイ～\nこの水着どうかな？\nイケてるっしょ♪", 2, 3211, 1, 2, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着姿の写真？\nもちいいよ！\nかわいく撮ってね！", 2, 3212, 1, 3, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちだって\n夏の海みたいに\nキラキラしちゃうよ！", 2, 3213, 1, 4, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイとうちの\nフィーリングって\nめっちゃエモいよね♪", 2, 3214, 1, 101, 4, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねーねーヒデサイ！\n一緒に泳ぎにいこっ！\nほら、手繋いで♪", 2, 3215, 1, 102, 8, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着オッケー！\nネイルもばっちり！\n朝から遊んじゃおー♪", 2, 3216, 1, 1, 1, 110001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼食べたら\n昼寝して\nリフレッシュしよー♪", 2, 3217, 1, 2, 1, 110001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着ってマジで\n最強かも…このまま\nお風呂にも入れるし♪", 2, 3218, 1, 3, 1, 110001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マジ気持ちいいー♪\nおに癒やされるん\nですけど～！", 3, 3220, 1, 2, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やばばばばー！\nかわいすぎだってば！\nマジらぶだよ～♪", 3, 3221, 1, 3, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、この香り超好き！\nモデル仲間に\n教えたげよ～♪", 3, 3222, 1, 4, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったか～い♪\n夏の太陽みたい！", 3, 3223, 1, 5, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マジ美味しいねこれ♪\nビーチで\n流行っちゃうかも！", 3, 3225, 1, 7, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏のために\n最新ファッションを\n勉強ちう！", 3, 3226, 1, 8, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なにコレもにカワ～♪\nなんて生き物？\nヒデサイ知ってる？", 3, 3228, 1, 10, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うわっ超フカフカ～\nなんかうち眠く\nなってきちゃった…", 3, 3229, 1, 11, 1, 110001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の家でのんびり\n過ごしましょう\n熱中症には注意してね", 1, 3230, 1, 1, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ、どうやったら\n泳げるように\nなれるのかしら～", 1, 3231, 1, 2, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海で日焼け止めを\n塗らないと、あとで\n大変なことになるわよ", 1, 3232, 1, 3, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("久しぶりに水着を\n着たんだけど\n変じゃなかったかな…", 1, 3233, 1, 4, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("波の音って落ち着くわ\n授業中に聞いたら\nみんな寝ちゃうかも？", 1, 3234, 1, 5, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海が楽しいって\n思えたのも\nあの子のおかげね", 1, 3235, 1, 101, 4, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの子と二人で海に\n来られてよかったわ\n一日があっという間ね", 1, 3236, 1, 102, 8, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("男の子と海だなんて\n少女漫画みたいで\n憧れてたの～", 2, 3237, 1, 1, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏休みの宿題は\nちゃんとやった？\n遊んでばかりではダメ", 2, 3238, 1, 2, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼の海と夜の海\nどっちが好き？　私は\n君といる海が一番よ", 2, 3239, 1, 3, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふう、疲れたわ～\n冷たいジュースで\n元気回復ね！", 2, 3240, 1, 4, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海で見た君の背中\nすごく大きく見えたわ\nやっぱり男の子なのね", 2, 3241, 1, 101, 4, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君と一緒に見た\n夜の海…\n忘れられそうにないわ", 2, 3242, 1, 102, 8, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("準備ができたら\n海に出かけようよ\n今日も楽しみましょう", 2, 3243, 1, 1, 1, 110101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら、もうお昼？\n海の家でランチに\nしましょ♪", 2, 3244, 1, 2, 1, 110101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の海岸についてきて\nくれる？　暗がりは\n一人じゃ怖くて…", 2, 3245, 1, 3, 1, 110101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぐ練習をしたら\n疲れちゃったわ～\nちょっと一休み…", 3, 3247, 1, 2, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいわね～\n浮き輪に乗せて\n海に浮かべたいわ～", 3, 3248, 1, 3, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この匂い…\nなんだか夏の海を\n思い出すわ～", 3, 3249, 1, 4, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の海風で冷えない\nように、しっかりと\n身体を暖めましょうね", 3, 3250, 1, 5, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海で遊ぶ前に\nしっかり食べて\n体力つけましょう", 3, 3252, 1, 7, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏休み中でも\nしっかりお勉強\nしないと！", 3, 3253, 1, 8, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子に乗れば\n海の上でも\nすいすい進めるかしら", 3, 3255, 1, 10, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビーナスの誕生！\n…なんちゃって\nはしゃぎすぎかしら？", 3, 3256, 1, 11, 1, 110101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の海には商機が\nあるはず…\nのがす手はないわね♪", 1, 3257, 1, 1, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしが作った\n日焼け止め…\nこれは売れそうね！", 1, 3258, 1, 2, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("子どもたちのために\n浮き輪を用意して\nおかないと…", 1, 3259, 1, 3, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海っていいわよね！\nみんなで羽を伸ばしに\n行きたいわ！", 1, 3260, 1, 4, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("波の音を聞いて\nのんびりするのも\n悪くないわね…", 1, 3261, 1, 5, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ただの砂遊びも\nあんたと一緒なら\n楽しいから不思議ね…", 1, 3262, 1, 101, 4, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたがあたしの\nなんであれ、大切な\n存在ではあるのよね…", 1, 3263, 1, 102, 8, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の海って\nすごい人よね…\n迷子にならないでよ？", 2, 3264, 1, 1, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼんやり海に浮かんで\n波に揺られるのも\n悪くないわよ？", 2, 3265, 1, 2, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビーチで子どもたちと\n一緒に砂のお城を\n作りたいわ♪", 2, 3266, 1, 3, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海で食べる\n焼きそばパン…\nいいかもしれないわね", 2, 3267, 1, 4, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしの水着\n似合ってる？\nそう、ありがとう♪", 2, 3268, 1, 101, 4, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたが居ると\nうれしい…って、\n子どもたちが\n言ってたわ！", 2, 3269, 1, 102, 8, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝の浜辺って\nいいわよね\n散歩しに行きたいわ", 2, 3270, 1, 1, 1, 110301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の家のご飯って\nなんであんなに\nおいしいのかしら♪", 2, 3271, 1, 2, 1, 110301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の海って、\nロマンチックよね。\nずっと眺めてたいわ…", 2, 3272, 1, 3, 1, 110301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やわらかくて\n気持ちいい…\nこのまま寝ちゃいそう", 3, 3274, 1, 2, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に一緒に入れる\nぬいぐるみとか\nないかしら？", 3, 3275, 1, 3, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏らしい\nいい香りね…\nなんの香りかしら？", 3, 3276, 1, 4, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかい…\n濡れた体を乾かすには\nちょうどいいわね♪", 3, 3277, 1, 5, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳いだ後の食事は\n普段の何倍も\nおいしく感じるわね！", 3, 3279, 1, 7, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に行く前にいろいろ\n調べなきゃね。備え\nあれば憂いなしよ！", 3, 3280, 1, 8, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の守り神？\nずいぶんかわいらしい\n神様ね♪", 3, 3282, 1, 10, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このぐらい\n大きな貝があったら\n食費も浮くかしら？", 3, 3283, 1, 11, 1, 110301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("浜辺で食うものって\nなんであんなに\nうまいのかな～", 1, 3284, 1, 1, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いてて…\nちょっと日焼け\nしすぎたかな", 1, 3285, 1, 2, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("砂浜で走ると\nいいトレーニングに\nなるんだぜ", 1, 3286, 1, 3, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏ならではの\n料理…か\n何がいいかな…", 1, 3287, 1, 4, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱりここは\n涼しくて快適だな", 1, 3288, 1, 5, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぎの練習だったら\nいつでも付き合って\nやるからな！", 1, 3289, 1, 101, 4, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着で部屋の中に\nいるのって\n変な感じだな…", 1, 3290, 1, 102, 8, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うおっ！\nきゅ、急に\n触るなって…\nびっくりした", 2, 3291, 1, 1, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え、砂がついてた？\n払ってくれたのか\nありがとよ", 2, 3292, 1, 2, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏バテしてないか？\nここで休んでけよ", 2, 3293, 1, 3, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…そう見られると\n照れるっていうか…", 2, 3294, 1, 4, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カキ氷とか\n食いたくないか？\n氷、削ってやるよ", 2, 3295, 1, 101, 4, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おまえと\n夏の思い出ができて\nよかったよ", 2, 3296, 1, 102, 8, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふう…\n朝一番で泳ぐの\nやっぱ気持ちいいな", 2, 3297, 1, 1, 1, 110401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一番あちぃ時間だ\n水分補給は\nこまめにな！", 2, 3298, 1, 2, 1, 110401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もお疲れ\n明日のパトロールも\nよろしくな", 2, 3299, 1, 3, 1, 110401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぎ疲れたからな\n少し休憩だ…", 3, 3301, 1, 2, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、かわいい…\nいや、なんでもねぇ！", 3, 3302, 1, 3, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り落ち着くな\nこういうのも\n悪くねーかも…", 3, 3303, 1, 4, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったけえ…！\n泳ぎ終わった後って\nけっこう体冷えてよ…", 3, 3304, 1, 5, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海で食べると\nまた一味違うよな", 3, 3306, 1, 7, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏のサバイバル特集…\nちょっと読んでみるか", 3, 3307, 1, 8, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へー！　こいつ、\nよくできてんな！\nいいなあ、実物も\n乗れたらいいのに", 3, 3309, 1, 10, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、かわ…！\nいや、じゃなくて\nあ、あたしがここに\n寝ていいのか…？", 3, 3310, 1, 11, 1, 110401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("故郷の花を飾っても\nいいかな～？\n部屋が楽しくなるよ～", 1, 3311, 1, 1, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着で歩いてると\n泳ぎたくなるさ～\n我慢できないさ～！", 1, 3312, 1, 2, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏が眩しいのは\nてぃーだがにこにこ\n笑ってるからさ～！", 1, 3313, 1, 3, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぎ疲れたら\n涼しい木陰で\nお昼寝するさ～", 1, 3314, 1, 4, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クロールも\n犬かきも\n大得意さ～！", 1, 3315, 1, 5, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだか歌いたい\n気分さ～\nキミもどう～？", 1, 3316, 1, 101, 4, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の近くに住んで\nキミと歌って踊って\nそれが理想さ～！", 1, 3317, 1, 102, 8, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私とキミ\nどっちがたくさん\n泳げるか\n競争するさ～！", 2, 3318, 1, 1, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミも三線に興味が\nあるのかな～？\n私が教えるさ～！", 2, 3319, 1, 2, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("嫌なことがあっても\n私と歌って踊れば\nなんくるないさー！", 2, 3320, 1, 3, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまには時間を忘れて\n私とのーんびり\n海を眺めるさ～", 2, 3321, 1, 4, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぶるぶるぶるっ！\n毛が濡れちゃっても\nへっちゃらさ～！", 2, 3322, 1, 101, 4, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぐ前は準備体操～！\n背中押してあげるから\nしっかりやるさ～！", 2, 3323, 1, 102, 8, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝の浜辺は\nちゅらさんよ～\n一緒に歩こうよー！", 2, 3324, 1, 1, 1, 110501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯は\n決まったかな～？\n私はタコライスさ～！", 2, 3325, 1, 2, 1, 110501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("星と波音の中で\n三線鳴らすのも\nオツなものさ～", 2, 3326, 1, 3, 1, 110501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょうどよかったさー\nゆっくり休んだら\nまた泳ぎに行くさ～！", 3, 3328, 1, 2, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("砂浜に飾って\nおきたいさ～\nきっとかわいいさ～！", 3, 3329, 1, 3, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん…はあ\n癒されるさ…\n故郷の夏の匂いさ～", 3, 3330, 1, 4, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おおー…！\n濡れた髪が\nみるみる乾いてくさ～", 3, 3331, 1, 5, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～！　これ、\n海で食べたら\nもっとおいしいさ～", 3, 3333, 1, 7, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の生物図鑑ね～\nこの前みかけた魚も\n載ってるかな～？", 3, 3334, 1, 8, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁ～！　みてみて！\n背中に乗れるさー！\nキミと一緒に\n乗りたいさ～！", 3, 3336, 1, 10, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかさ～\n海の底の\n人魚になった気分さ～", 3, 3337, 1, 11, 1, 110501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人が\nわたしの騎士だったら\nいいのにな…", 1, 3338, 1, 103, 12, 105801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたのおかげで\nわたしの心はいつも\nお腹いっぱいです♪", 2, 3339, 1, 103, 12, 105801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("許されるのならば、\n今すぐにでも、\n主さまのおそばに\n行きたいです…", 1, 3340, 1, 103, 12, 105901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さま…\nお慕いしております…\nいつまでも、おそばに\n居させてください…", 2, 3341, 1, 103, 12, 105901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんか最近、\nあいつのことしか\n考えてない…\nあたし…どうしよう…", 1, 3342, 1, 103, 12, 106001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そ、外に行くなら、\n連れていきなさいよね\nその…あたしが\n守ってあげるから…", 2, 3343, 1, 103, 12, 106001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋の中は涼しくて\n気持ちええどすなぁ\n天国やわぁ", 1, 3344, 1, 1, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クラゲはんって\nフリルいっぱいの\nドレスみたいやねぇ", 1, 3345, 1, 2, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外でセミはんが\n元気に鳴いてはるねぇ\n今日もええ天気やわぁ", 1, 3346, 1, 3, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こないに暑いと\n海に入って\n涼みたくなるわぁ", 1, 3347, 1, 4, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか\nマホマホ王国にも\n海の家作りまひょ♪", 1, 3348, 1, 5, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちも\n付き合いますえ\n泳ぎの練習しまひょ♪", 1, 3349, 1, 101, 4, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちの里帰り\n王子はんも一緒に\n来まへんか？", 1, 3350, 1, 102, 8, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんは日焼けより\n色白美人の方が\n好きでっしゃろか？", 2, 3351, 1, 1, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちと一緒に\n浮き輪で海、\nプカプカしまへん？", 2, 3352, 1, 2, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日が落ちたら\n線香花火\nやりたいわぁ♪", 2, 3353, 1, 3, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("木陰でのんびり\nお昼寝…\n最高やね～", 2, 3354, 1, 4, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お祭ではぐれても\n王子はんなら見つけて\nくれはります？", 2, 3355, 1, 101, 4, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("楽しい夏やわぁ\nずっとこんな日が\nつづくとええね", 2, 3356, 1, 102, 8, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちにしては早起き？\n暑くて目が早う\n覚めてもうたんどす", 2, 3357, 1, 1, 1, 110601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼は冷たい\nおそうめんとか\nどうでっしゃろ", 2, 3358, 1, 2, 1, 110601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜は星がきれいやね\n二人で浜辺でも\n行きまへんか？", 2, 3359, 1, 3, 1, 110601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん、遊び疲れた\n身体にちょうどええ\nほっこり具合やわぁ", 3, 3361, 1, 2, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かいらしい子は\nみーんな\nマホマホ王国の\n住人どすえ♪", 3, 3362, 1, 3, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り…\n南国にいる気分やねぇ\n癒されるわぁ～", 3, 3363, 1, 4, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これで\n冷えた身体も\nポカポカやねぇ", 3, 3364, 1, 5, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外はまだ暑いやろうし\nバテんよう\nしっかり食べんとね", 3, 3366, 1, 7, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の中にもお城が\nあるんやねぇ\n行ってみたいわぁ", 3, 3367, 1, 8, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子、ふかふかやね\nこのままマホマホ王国\n乗せてってくれはる？", 3, 3369, 1, 10, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人魚姫になっても\n最後は王子はんと\nハッピーエンド\nどすえ～", 3, 3370, 1, 11, 1, 110601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("真似したくなる\n人がここには\n大勢いますね", 1, 3371, 1, 1, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("偽物を一人\n紛れこませました\n…冗談です", 1, 3372, 1, 2, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("動物に変身して\nその辺りを\n散歩してきます", 1, 3373, 1, 3, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("失った記憶は\nどの程度回復するの\nでしょうね", 1, 3374, 1, 4, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人や物だけでなく\nいずれは世界すら\n真似てみせます", 1, 3375, 1, 5, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次は彼に\nどんなことを\n教えましょうか…", 1, 3376, 1, 101, 4, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("知識はともかく\n私の力はまだ\n必要なようですね", 1, 3377, 1, 102, 8, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしました？\n…何でもない？\n…そうですか", 2, 3378, 1, 1, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("退屈しています\n芸でもして\n楽しませなさい", 2, 3379, 1, 2, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("研究のためです\n少し話し相手に\nなりなさい", 2, 3380, 1, 3, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何か真似して欲しい？\n私の能力を何だと\n思っているのですか", 2, 3381, 1, 4, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴方にはまだ色々と\n教えるべきことが\nありますね", 2, 3382, 1, 101, 4, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("随分多くの女性と\n知り合いなのですね\n驚きました", 2, 3383, 1, 102, 8, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…\nおはようございます\n…まだ朝ですよ", 2, 3384, 1, 1, 1, 107001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食事にします\n…どうしました？\n早く持ってきなさい", 2, 3385, 1, 2, 1, 107001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早く寝なさい\n夜更かしすると\n背が伸びませんよ？", 2, 3386, 1, 3, 1, 107001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マサキより\n座り心地は\nいいですね", 3, 3388, 1, 2, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("意外に複雑な\n構造ですね", 3, 3389, 1, 3, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("真似るなら\n香りまで\n再現しなくては", 3, 3390, 1, 4, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("発火現象の\n模倣…なかなか\n難しいものです", 3, 3391, 1, 5, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("偽物や分身を作るには\nエネルギーが\n必要不可欠なのです", 3, 3393, 1, 7, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇つぶしには\nちょうどよさそうです\n…", 3, 3394, 1, 8, 1, 107001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("学院かぁ…\n友達の作り方の\n授業はないかな？", 1, 3396, 1, 1, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("学院でぼっちに\nなったときのために、\n避難場所を\n探しておかないと…", 1, 3397, 1, 2, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼっちの私が学院…\nな、なんだか\n目まいがしてきました", 1, 3398, 1, 3, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クラスメイトに\n話しかける練習…\nむ、難しすぎます…！", 1, 3399, 1, 4, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("目指せ友達100人…\n無理かな…10人…\nや、やっぱり一人！", 1, 3400, 1, 5, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと学院生活が\n送れるなんて、\nとっても\nうれしいです！", 1, 3401, 1, 101, 4, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ…\n学院でも、\nあなたと一緒に\n居られてうれしいな♪", 1, 3402, 1, 102, 8, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("が、学院ってあんなに\n人が居るんですね…\n友達作りのイメトレを\nやり直さないと！", 2, 3403, 1, 1, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私にとって\n部活動とはＢＢ団！\n今日もたくさん\n活動しましょうね！", 2, 3404, 1, 2, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休み時間は寝たふり…\nご飯はおトイレ…\nぼっち対策は完璧です", 2, 3405, 1, 3, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("学院で友達を作る\n勉強は完璧ですよ！\n購買部でパンを買って\n渡すんですよね！", 2, 3406, 1, 4, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("学院でも、\nＢＢ団の活動を\nしていきましょうね♪", 2, 3407, 1, 101, 4, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼっちに学院生活は\n厳しいですね…でも、\nあなたと一緒なら\n乗りこえられそうです", 2, 3408, 1, 102, 8, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間…\nあの…一緒に学院に\n行ってくれませんか？", 2, 3409, 1, 1, 1, 110701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ですね！\n言ってくれれば、\nパンでもお握りでも\n買ってきますよ！", 2, 3410, 1, 2, 1, 110701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もぼっち…\nいつか友達と一緒に、\nパジャマパーティー\nしたいなぁ…", 2, 3411, 1, 3, 1, 110701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("森とは違う\n心地良さが…このまま\n眠っちゃいそうです…", 3, 3413, 1, 2, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい…この子を、\n話す練習の相手役に\nしてみようかな？", 3, 3414, 1, 3, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…\nいつ友達ができても\nいいように、私の\n部屋にも置こうかな", 3, 3415, 1, 4, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こ、これは…\nぼっちで\n日陰者の私には\n暖かすぎます！", 3, 3416, 1, 5, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしい…！\nお弁当にして、学院に\n持っていけないかな？", 3, 3418, 1, 7, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("学院の授業に\nついていくためにも、\n勉強しておこうかな…", 3, 3419, 1, 8, 1, 110701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんた、何してんの。\nいいけど、なんでも", 1, 3421, 1, 1, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("邪魔。どいて。\nいや怒ってないし。\nコレがフツーだから", 1, 3422, 1, 2, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいけど、\n散らかしめの部屋だと\n片付けたくなるよね…", 1, 3423, 1, 3, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇なときは明日の\nコーデ考えてるよ。\n考えるのはタダだし", 1, 3424, 1, 4, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昔よくシオリン\n構いすぎてハツネに\n文句言われたなァ…", 1, 3425, 1, 5, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんかさ。あんたって\n謎に女子トモ多いよね\n…いいけど、べつに", 1, 3426, 1, 101, 4, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ。あのさあ。\nあんた弁当で好きな\n具とかってあんの", 1, 3427, 1, 102, 8, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ？　何。なんか用。\nや、ないならないで\nいいけど、べつに", 2, 3428, 1, 1, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ごめ、ちょっと\n黙っててくんない。\n明日の試験ヤバだから", 2, 3429, 1, 2, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歩き方が静か？\n癖になってるんだよね\n足音を殺すの", 2, 3430, 1, 3, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちの血液型？\n大雑把のОだけど。\nなんか文句あんの", 2, 3431, 1, 4, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃんっ！\nや、だからさ…急に\n話しかけんなっての", 2, 3432, 1, 101, 4, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("な、何…あんまジッと\n見ないでくんない…\nなんか、その、ハズい", 2, 3433, 1, 102, 8, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早起きは得意な方だと\n思うけど。昔から\nそれがデフォだったし", 2, 3434, 1, 1, 1, 110801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな時間か…\n昼ごはん\nサクッと作っちゃお", 2, 3435, 1, 2, 1, 110801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ？　夜遊び？\nはッ…そんなん\n５歳で卒業したっての", 2, 3436, 1, 3, 1, 110801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あーヤバじゃんコレ…\nふかついてる場合\nじゃないっつーのに…", 3, 3438, 1, 2, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだこれ\nかわいいかよ", 3, 3439, 1, 3, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふーん。\nこの匂い…\nなんかいいじゃん", 3, 3440, 1, 4, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖炉はアドじゃん。\n煮物、焼き物、蒸し物\nいろいろ作れそう", 3, 3441, 1, 5, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何コレ\n食べ物困んないじゃん\nうちにも一台くんない", 3, 3443, 1, 7, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本かァー…んー\n学校の勉強だけで\nいいかなァ…", 3, 3444, 1, 8, 1, 110801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イタズラってなにを\nしたらいいのかな？", 1, 3446, 1, 1, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カップケーキ\n上手に作れました\n食べてくれるかな…", 1, 3447, 1, 2, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人、\nお菓子くれるかな？\nくれなかったら…ふふ", 1, 3448, 1, 3, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オバケ…いないよね？\n怖くなんてないけど！", 1, 3449, 1, 4, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンは\n楽しいけどオバケの\nお祭りなんだよね…", 1, 3450, 1, 5, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃ～、にゃお～！\nちゃんと怖いかな？\n早く帰ってこないかな", 1, 3451, 1, 101, 4, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人のことだから\nお菓子欲しがるよね…\n準備はバッチリです♪", 1, 3452, 1, 102, 8, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ。猫さんのお耳\nよく出来てるでしょ？", 2, 3453, 1, 1, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("触りましたね？\nイタズラしましたね？\nへんた～い！", 2, 3454, 1, 2, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フー！　頭を撫でたら\n怒りますよ！　あれ？\n猫みたいでした？", 2, 3455, 1, 3, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きゃっ！　も、もう、\n脅かさないでください\n怖くありませんけど！", 2, 3456, 1, 4, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子ですか？\nありがとうございます\nハッピーハロウィン♪", 2, 3457, 1, 101, 4, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ゴロゴロ…\nね、猫さんの真似です\n…似てましたか？", 2, 3458, 1, 102, 8, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さぁ、お菓子作りを\n始めますよ。下準備は\n大事ですからね！", 2, 3459, 1, 1, 1, 111101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今、つまみ食い\nしましたね！？　あっ\nおやつの時間でしたか", 2, 3460, 1, 2, 1, 111101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さぁ、ハロウィンの\n始まりです…ふぁ…\nね、眠くありません！", 2, 3461, 1, 3, 1, 111101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと疲れたかも…\nパーティの時間まで\nひと休みしなきゃ", 3, 3463, 1, 2, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私も今、こんな感じ\nなのかな？　こんなに\nかわいいといいなぁ", 3, 3464, 1, 3, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("甘い匂いがいっぱい…\nお菓子の香りかな？", 3, 3465, 1, 4, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("温かくなると、\n丸まりたくなって…\n…猫になっちゃう！？", 3, 3466, 1, 5, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ニンジンもこれくらい\nおいしければ\nいいのに…", 3, 3468, 1, 7, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンの本、\nオバケがたくさん\n載ってて怖いかも…", 3, 3469, 1, 8, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美味しそうなお菓子が\nいっぱい…これなら\nイタズラされませんね", 3, 3471, 1, 12, 1, 111101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たくさんいたずら\nできるから\nハロウィン大好き！", 1, 3473, 1, 1, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンだから\nいつもよりすごい\nいたずらしたいな～！", 1, 3474, 1, 2, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カボチャを綺麗に\nくり抜いてすごく怖い\nランタン作っちゃお！", 1, 3475, 1, 3, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子がたくさんで\nどれから食べるか\n迷っちゃうな～！", 1, 3476, 1, 4, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうすればみんなを\nびっくりさせられる\nかな～？", 1, 3477, 1, 5, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カボチャ見てたら\nお腹空いて来たな～\nお菓子食べちゃお♪", 1, 3478, 1, 101, 4, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんには\n特別ないたずらを\n用意してあげるね！", 1, 3479, 1, 102, 8, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カボチャにクラッカー\nを仕掛けて…わっ！？\nみ、見ちゃダメだよ！", 2, 3480, 1, 1, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん？　なぁに？\nお菓子ほしいの？\nもう、しかたないな～", 2, 3481, 1, 2, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんの\n面白い仮装が\n見てみたいな～！", 2, 3482, 1, 3, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子くれたお礼に\nとびっきりの\nいたずらしちゃうね！", 2, 3483, 1, 4, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんは\nハロウィンでも最高の\nいたずら相手だよ！", 2, 3484, 1, 101, 4, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんと一緒に\nハロウィンパレード\n歩きたいな～！", 2, 3485, 1, 102, 8, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようにいちゃん！\n仮装して出かける\n準備しなきゃ！", 2, 3486, 1, 1, 1, 111201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹すいたな～\nもらったお菓子\n食べちゃだめかな？", 2, 3487, 1, 2, 1, 111201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たくさんいたずらして\nもうクタクタ～\nミソギもう寝るね…", 2, 3488, 1, 3, 1, 111201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やわらか～い…\nここでひと休みして\nまたいたずらしよう！", 3, 3490, 1, 2, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいもので\n油断させてわっ！\nってするのどうかな？", 3, 3491, 1, 3, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいにお～い！\nいたずらのアイデアが\nわいてくるよ！", 3, 3492, 1, 4, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もらったお菓子\nあったかくしたら\nおいしいかな～？", 3, 3493, 1, 5, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子ばっかりじゃ\n飽きちゃうもんね！\nご飯も食べよう！", 3, 3495, 1, 7, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本のなかに\nいたずらのヒント\nないかな～？", 3, 3496, 1, 8, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子がたくさん！\n一人で食べていいの？\nやっぱりだめか～！", 3, 3498, 1, 12, 1, 111201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お勉強は順調ですよ\nやっぱりお兄ちゃんの\nおかげなんでしょうか", 1, 3500, 1, 103, 12, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんとの\n思い出の場所\nまた行きましょうね", 2, 3501, 1, 103, 12, 101101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ～♪\nハロウィンの\nミイラさんうさぎさん\nぴょんぴょ～ん！", 1, 3502, 1, 1, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("るんたった～\nハロウィンハロウィン\n楽しいな～♪", 1, 3503, 1, 2, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンって\nどんなお菓子を\nもらえるのかな～？", 1, 3504, 1, 3, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子をもらう\n練習をしなくちゃ！\nトリックオア\nトリート～♪", 1, 3505, 1, 4, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃんと\nハロウィンするの\nミミ楽しみだな～♪", 1, 3506, 1, 5, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃんと\nいっしょにお菓子を\n食べたいな～", 1, 3507, 1, 101, 4, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃんと\n毎日ハロウィン\nできたらいいな～♪", 1, 3508, 1, 102, 8, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ～\nおにいちゃん！\nハッピーハロウィン♪", 2, 3509, 1, 1, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃんも\nいっしょに\nハロウィンパレード\nしようね～！", 2, 3510, 1, 2, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミイラさんうさぎさん\nだぞ～…えへへ\nミミこわかったかな？", 2, 3511, 1, 3, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃん！\nハロウィンのお菓子\nおいしいね～♪", 2, 3512, 1, 4, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃんと\nいっしょなら\nおばけさんも\nこわくないよ！", 2, 3513, 1, 101, 4, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミね\nハロウィンも\nおにいちゃんも\nだ～いすき♪", 2, 3514, 1, 102, 8, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おひさまさんも\nハロウィンの\nおようふく\n着たいかな～？", 2, 3515, 1, 1, 1, 111301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえねえおにいちゃん\nお昼ごはんはもらった\nお菓子でもい～い？", 2, 3516, 1, 2, 1, 111301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだハロウィン…？\nうぅん…眠くないよぅ\nでもちょっと…ふぁ～", 2, 3517, 1, 3, 1, 111301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふか～♪\nおばけさんが\n中にいるのかな～？", 3, 3519, 1, 2, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁ、かわいい～♪\nミミといっしょに\nあそぼ～！", 3, 3520, 1, 3, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ～\nミミ、このにおい\nだ～いすき♪", 3, 3521, 1, 4, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいね～♪\nおばけさんも\nポカポカしてるかな？", 3, 3522, 1, 5, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしい～♪\nおにいちゃんも\n食べようよー！", 3, 3524, 1, 7, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本\nおにいちゃんと\nいっしょに\n読みたいな～", 3, 3525, 1, 8, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハッピーハロウィン♪\nえへへ、お菓子が\nいっぱいだね～！", 3, 3527, 1, 12, 1, 111301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここ、好きだよ。\nみんな優しいから…", 1, 3529, 1, 1, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんかさみしいな", 1, 3530, 1, 2, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("知らない人怖いな", 1, 3531, 1, 3, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お部屋おっきいねー", 1, 3532, 1, 4, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ルナね…\nお昼寝したいかも", 1, 3533, 1, 5, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいさん！\n今日は何して遊ぶの？", 1, 3534, 1, 101, 4, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのね、\nお料理教えてほしい！", 1, 3535, 1, 102, 8, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、おにいさんだ！", 2, 3536, 1, 1, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ルナは元気だよ！\nいいこだもん！", 2, 3537, 1, 2, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は何しようかな", 2, 3538, 1, 3, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ルナと遊んでよ！", 2, 3539, 1, 4, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねーねー、\nルナとお出かけして！", 2, 3540, 1, 101, 4, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいさんと、\n遊びたいなー！", 2, 3541, 1, 102, 8, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ！\nなんかまぶしいね！", 2, 3542, 1, 1, 1, 111401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ルナ、お腹空いたな", 2, 3543, 1, 2, 1, 111401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どこに行こうかな？", 2, 3544, 1, 3, 1, 111401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ルナ、これ好きだな", 3, 3546, 1, 2, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい！　好き！", 3, 3547, 1, 3, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんかいい匂い！", 3, 3548, 1, 4, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいねー", 3, 3549, 1, 5, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ\nおいしいね", 3, 3551, 1, 7, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ルナ、\n眠くなっちゃう…", 3, 3552, 1, 8, 1, 111401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ。あの人と\nランドソルでデート\nできたらうれしいな♪", 1, 3554, 1, 103, 12, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたとなら\nどんなことだって\nできる気がするわ♪", 2, 3555, 1, 103, 12, 105201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あーあ、退屈だな\nカレでも探しに\nいこうかな", 1, 3556, 1, 1, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この前のケンカは\n最高に燃えたなぁ\n…拳が疼いてきたぜ", 1, 3557, 1, 2, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一体、この世界は\nどうなっちまったって\nいうんだ…？", 1, 3558, 1, 3, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう仕事の時間か\nボスも人使いが荒いぜ\n…ま、いいけどさ！", 1, 3559, 1, 4, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オレたち以外に\nドラゴン族はあと何人\nいるんだろうな…", 1, 3560, 1, 5, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カレの真剣な顔\n面白かったな\nまた遊びたいぜ", 1, 3561, 1, 101, 4, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしてカレがそばに\nいると、腹の底から\n力が湧いてくるんだ？", 1, 3562, 1, 102, 8, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よっす！\nなんかオイシイ話でも\nあったりしない？", 2, 3563, 1, 1, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なあ、オレと遊ぼうぜ\n心配すんなよ。危ない\nことはよしとくからさ", 2, 3564, 1, 2, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうした。オレに\nケンカ売ろうってか？\n…ははは、冗談だよ！", 2, 3565, 1, 3, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょうど退屈してた\nところだ、特訓に\n付き合ってくれよ", 2, 3566, 1, 4, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ったくよぉ…\nオレがかわいいなんて\n冗談はもうよせよ？", 2, 3567, 1, 101, 4, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次の仕事も一緒に\n来るだろ？　断っても\n連れて行くけどな！", 2, 3568, 1, 102, 8, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！　今日の\n予定はまずケンカして\nで、その後もケンカだ", 2, 3569, 1, 1, 1, 106501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よっす！\n腹ごしらえが済んだら\nオレと遊ぼうぜ！", 2, 3570, 1, 2, 1, 106501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜は危ないから\nあんま出歩くな？\n…だから面白えんだろ", 2, 3571, 1, 3, 1, 106501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次のケンカに備えて\n今は休んでおくか…\n全力で暴れたいからな", 3, 3573, 1, 2, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボスの飼ってる\nラーゴが、中に\n入ってるんじゃ？", 3, 3574, 1, 3, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ、たぎる匂いが\nする…ひと暴れ\nしたくなってきた！", 3, 3575, 1, 4, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おおぉ…\nオレの拳もなんだか\n熱くなってきたぜ…！", 3, 3576, 1, 5, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつでも全力で\nケンカするために\n力を蓄えないとな", 3, 3578, 1, 7, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱりな…オレが\n知ってる地図とは\nまるで違ってやがる", 3, 3579, 1, 8, 1, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さぁプレゼントで\n埋め尽くしてやろう！\n大いに喜ぶがいいよ！", 1, 3581, 1, 1, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリークリスマス☆\n聖夜の宴だ\n派手に楽しむとしよう", 1, 3582, 1, 2, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("煙突から入る？\nいいや、ワタシは\nいつでも正面からさ♪", 1, 3583, 1, 3, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サンタクロースの\nお出ましだ！\n歓迎するがいいよ♪", 1, 3584, 1, 4, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("飾り付けが足りん！\nワタシが演出して\nやろうじゃないか！", 1, 3585, 1, 5, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人の喜ぶ顔を見るのも\n悪くはないな…おっと\nワタシらしくないな☆", 1, 3586, 1, 101, 4, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プレゼントはまだか？\nワタシを喜ばせたら\nお返しは弾むぞ♪", 1, 3587, 1, 102, 8, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワタシを呼んだか？\n退屈な要件だったら\n覚悟しておくことだ", 2, 3588, 1, 1, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだ？\nワタシへの挑戦か？\nよし、受けた♪", 2, 3589, 1, 2, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっと、当たらんよ\nワタシの乱数聖域は\n絶対だからな…♪", 2, 3590, 1, 3, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだ、オマエも\n暇なのか？\n奇遇だな、ワタシもさ", 2, 3591, 1, 4, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なにか愉しいことでも\nしようじゃないか\nさぁ、何をする？", 2, 3592, 1, 101, 4, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こうもワタシに\n気安く触れるのは\nオマエくらいだよ…♪", 2, 3593, 1, 102, 8, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝だろうと関係ない！\nさぁ愉しく苛烈に\n騒ごうじゃないか♪", 2, 3594, 1, 1, 1, 111501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("調子の出てくる時間だ\nしっかりワタシを\n愉しませてくれよ♪", 2, 3595, 1, 2, 1, 111501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眠いなどと言わせんぞ\nまだまだ一日は\n終わらんからな！", 2, 3596, 1, 3, 1, 111501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい具合じゃないか\nこのまま持って帰って\nしまおうか…♪", 3, 3598, 1, 2, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なかなか愛らしい\n造形をしているな？\nワタシには負けるがな", 3, 3599, 1, 3, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほう、悪くない香りだ\n戦いの匂いをうまく\n隠してくれそうだ…♪", 3, 3600, 1, 4, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体が温まってくると\nひと暴れしたくなるな", 3, 3601, 1, 5, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワタシの舌は厳しいぞ\n…ふーむ、なるほど\n認めざるをえんな", 3, 3603, 1, 7, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスティーナさんは\n知識の収集も\n欠かさないんだよ", 3, 3604, 1, 8, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは驚いたな\nだがもっと、もっとだ\nワタシを退屈させるな", 3, 3606, 1, 14, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな戯れだって\n軽くこなしてしまう\nクリスティーナさんさ", 3, 3607, 1, 15, 1, 111501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリークリスマス！\nさあ、パーティーを\n盛り上げるよ！", 1, 3608, 1, 1, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("衣装一つで全然\n気分が違うね！\n最高のクリスマスに\nなりそうだよ！", 1, 3609, 1, 2, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ツリーのてっぺんの\n星って、なんだか\n欲しくなるんだよね", 1, 3610, 1, 3, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("めいっぱい\nクリスマスを楽しむよ\n遊びだって本気\nなんだからね！", 1, 3611, 1, 4, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("赤、白、緑、金\nクリスマスカラー\nってお洒落だよね", 1, 3612, 1, 5, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("雪、降らないかな？\nホワイトクリスマス\nってちょっと\n憧れるなぁ", 1, 3613, 1, 101, 4, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミと過ごすこの\n楽しい時間がずーっと\n続けばいいのにな", 1, 3614, 1, 102, 8, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスライブ\nチケット用意するから\n絶対来てよね！", 2, 3615, 1, 1, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カンパーイ！\nジュースだけど\nちょっと大人の\n気分だね", 2, 3616, 1, 2, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマス衣装どう？\nかわいいでしょ\nあっ、どこ見てるの！", 2, 3617, 1, 3, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、後で街に\n行こうよ\n大きなツリーを\n一緒に見たいんだ♪", 2, 3618, 1, 4, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、ダンスの練習に\n付き合ってくれない？\n大丈夫、手取り足取り\n教えてあげるから♪", 2, 3619, 1, 101, 4, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("来年のクリスマスも\n隣にキミが\nいてくれたら\nうれしいのにな", 2, 3620, 1, 102, 8, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスって朝から\nドキドキしちゃうね\nなんだか子どもみたい", 2, 3621, 1, 1, 1, 111601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パーティーの準備も\n大分進んだね\n一息ついて\nランチにしよっか", 2, 3622, 1, 2, 1, 111601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("静かな夜だね\n心臓の音まで\n聞こえちゃいそう…", 2, 3623, 1, 3, 1, 111601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ～、この絶妙な\n柔らかさ…\nいい仕事してるなぁ…", 3, 3625, 1, 2, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイドル顔負けの\nかわいさ、ズルい！\nでもかわいい！", 3, 3626, 1, 3, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～、落ち着くなぁ\n今日はゆっくり\n眠れそうだよ", 3, 3627, 1, 4, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬくぬく～\nどうしよう、ここから\n動きたくないなぁ", 3, 3628, 1, 5, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ダンスの練習もしたし\nちょっとくらいなら\nいいよね！", 3, 3630, 1, 7, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイドルといえど\nかわいいだけじゃダメ\n知識も必要だよね", 3, 3631, 1, 8, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("面白ーい！\nこの演出、ライブでも\nできないかな？", 3, 3633, 1, 14, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もふもふ～♪\n寒い日には最高の\n抱き心地だね！", 3, 3634, 1, 15, 1, 111601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼ともっとお話し\nしたいな…もう少し\n補習を増やそうかしら", 1, 3635, 1, 103, 12, 101801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君のこともっともっと\n教えて欲しいな。私に\n補習授業してくれる？", 2, 3636, 1, 103, 12, 101801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この姿ならあやつも\n子ども扱いできまい！\n…じゃがなぜか、少し\n物足りないような…", 1, 3637, 1, 1, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時間もあるし、\n聖夜の宴の\n準備をするかのう♪", 1, 3638, 1, 2, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…わらわの知る聖夜と\n随分違うが、宴は宴\n楽しませて\nもらおうかのう♪", 1, 3639, 1, 3, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大人の姿で\nできること…ふむ\n少しあやつを\nからかってやるか♪", 1, 3640, 1, 4, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…クリスマスは\n恋人たちの夜！？\nち、近頃の若いもんは\n破廉恥なのじゃ！", 1, 3641, 1, 5, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…あやつがおらんと、\n宴も物足りぬな\n…馬鹿者が\n早く帰ってこい…", 1, 3642, 1, 101, 4, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誰も見ておらぬな…？\n…よし、あやつへの\nプレゼントを\n準備するとしようか！", 1, 3643, 1, 102, 8, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスの\nチキンにケーキ…\nべ、別に楽しみになど\nしておらぬぞ！", 2, 3644, 1, 1, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この姿では、わらわの\n頭をなでるのは\n難しかろう…べ、\n別に残念ではないわ！", 2, 3645, 1, 2, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリー\nクリスマスじゃ！\nさあ、わらわのために\n宴の準備をするのじゃ", 2, 3646, 1, 3, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そんなにこの衣装が\n気になるのか？\n…だったら、直に\n触ってみるがよい♪", 2, 3647, 1, 4, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもと逆に、お主を\n子ども扱いしてやるか\nほれ、膝枕をしてやる\nからそばに来い♪", 2, 3648, 1, 101, 4, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…せ、聖夜の予定は\n空けておくのじゃぞ？\nなんでって…\nな、なんでもじゃ！", 2, 3649, 1, 102, 8, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう朝か…聖夜の宴が\n楽しみで…ではなく！\n準備のせいで、\nあまり眠れんかったぞ", 2, 3650, 1, 1, 1, 111701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…ずっと雪が\n降っておれば、\n陽光が強いこの時間も\n怯えずにすむのにのう", 2, 3651, 1, 2, 1, 111701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時は来た…\nさあ眷属よ！\nわらわと共に、\n聖夜の宴を楽しもうぞ", 2, 3652, 1, 3, 1, 111701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("良い椅子ではないか\nここから聖夜の宴を\n眺めるのもよいかもな", 3, 3654, 1, 2, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、かわい…こほん\nなかなか良い\nデザインをしておるな", 3, 3655, 1, 3, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ、良い香りじゃ\n聖夜の宴でも\nこれを使うとしよう", 3, 3656, 1, 4, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これが癒し…はっ！\nあやうく浄化される\nところであった…", 3, 3657, 1, 5, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ニ、ニンニクは\n入っておらぬよな？\n…うむ、美味じゃ♪", 3, 3659, 1, 7, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("聖夜は恋人たちの夜…\n…き、気になるわけ\nではないが、\n少し調べてみるか", 3, 3660, 1, 8, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほう…これは面白い\n魔法の使い方じゃな\nまるで本物の\n演劇のようじゃ", 3, 3662, 1, 14, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こ、この程度の\nかわいさに誘惑される\nわらわでは…\nふわもこなのじゃ～♪", 3, 3663, 1, 15, 1, 111701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おせち料理も\n魔物尽くしだったり\nしないわよね！", 1, 3664, 1, 1, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("初詣で何をお祈り\nしようかしら…\n定番でいいわよね？", 1, 3665, 1, 2, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("初日の出って\n特別な感じがして\nいいわよね…", 1, 3666, 1, 3, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寒い中並んで飲む\n甘酒って不思議なほど\nおいしいわよね", 1, 3667, 1, 4, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("羽根つきで勝負…\nあいつにだったら\n勝てるかしら？", 1, 3668, 1, 5, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("年賀状になんて書こう\n…いろいろと\n恥ずかしくなるのよね", 1, 3669, 1, 101, 4, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年もあいつと\n居られること…\n結構うれしいわ", 1, 3670, 1, 102, 8, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何じっと\n見てんのよ？\nお年玉はあげないわよ", 2, 3671, 1, 1, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おせち料理一緒に\n食べる？\n結構おいしいわよ", 2, 3672, 1, 2, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("羽根つきで負けたら\n顔に墨塗られるのよ\n覚悟しなさい！", 2, 3673, 1, 3, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("門松飾るから\nちょっと手伝って\nくれる？", 2, 3674, 1, 4, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたと一緒に\n初詣行くのも悪くない\n…かも", 2, 3675, 1, 101, 4, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("初詣で何をお祈り\nしたか？　うっさい！\n内緒よ！内緒！", 2, 3676, 1, 102, 8, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう朝なの…\n正月くらいゆっくり\n寝ていたいわよね…", 2, 3677, 1, 1, 1, 112001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おせちに飽きたら\n次は何を食べよう\nかしら…", 2, 3678, 1, 2, 1, 112001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ寝ましょ\nいい初夢が見られると\nいいわね", 2, 3679, 1, 3, 1, 112001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好でいるのも\nなかなか疲れるわね\n休憩～", 3, 3681, 1, 2, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、かわいい…う～ん\n鏡餅も顔を描けば\nかわいくなるかしら？", 3, 3682, 1, 3, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい匂いね\n落ち着いて\n眠れそう…", 3, 3683, 1, 4, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここでお餅焼いたら\n一段とおいしく\nなりそうね", 3, 3684, 1, 5, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月に食べるものは\nなんでもおいしく\n感じちゃうわね！", 3, 3686, 1, 7, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔物を使わない\nおせちを\n調べておかなきゃ…", 3, 3687, 1, 8, 1, 112001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新年を気持ちよく\n過ごせるように\nお掃除がんばります！", 1, 3689, 1, 1, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("神殿に通っていたら\nいつの間にか足腰が\n鍛えられたような…", 1, 3690, 1, 2, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("神殿付近は屋台も\nあるので、良い香りが\n漂ってくるんですよ～", 1, 3691, 1, 3, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おせちを作れるように\nなれば、子どもたちも\n喜んでくれるかな…？", 1, 3692, 1, 4, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コホォォォォォ…！\nふぅ、深呼吸すると\n落ち着きますね♪", 1, 3693, 1, 5, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お仕事以外の時も\nあなたと…い、いえ！\nなんでもないです！", 1, 3694, 1, 101, 4, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと一緒だと\nなんだかポカポカ\nしてくるんです…", 1, 3695, 1, 102, 8, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好をしていると\nなんだか神殿にいる\n気分になりますね", 2, 3696, 1, 1, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そういえば神殿で\n甘酒をもらったんです\nあなたも飲みますか？", 2, 3697, 1, 2, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、髪飾りが\nズレちゃってました！\nいけないいけない…", 2, 3698, 1, 3, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃわっ！？\nく、くすぐったり\nしないでください～", 2, 3699, 1, 4, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そ、そんなに\n見つめられると\nて、照れちゃいます…", 2, 3700, 1, 101, 4, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度、私が考えた\n運気上昇のおまじない\nかけてあげますね♪", 2, 3701, 1, 102, 8, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n神殿のお手伝いに行く\n準備もしなきゃですね", 2, 3702, 1, 1, 1, 112101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼になりましたし\nご飯は私が作…\nえっ、ダメですか！？", 2, 3703, 1, 2, 1, 112101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日も早いですし\nそろそろ寝る支度を…\nふわぁ…", 2, 3704, 1, 3, 1, 112101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お掃除も終わったので\n少し休憩を…ふわぁ…\n急に眠気が…", 3, 3706, 1, 2, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新年を気持ちよく\n過ごせるようこの子も\nきれいにしましょう♪", 3, 3707, 1, 3, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("神殿のお香のような\n香りだと落ち着いて\n過ごせそうですよね", 3, 3708, 1, 4, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽかぽかですね～…\n甘酒も飲んで体の\n芯から温めましょう", 3, 3709, 1, 5, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年こそ\n料理も上手に…\nもぐもぐもぐもぐ…", 3, 3711, 1, 7, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("失敗続きだと\n逆に運が良くなる…\nほ、本当ですかぁ…？", 3, 3712, 1, 8, 1, 112101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミにならもう\nどんな私を見られても\n大丈夫かな…♪", 1, 3714, 1, 103, 12, 103401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なになにどしたのぉ？\nお姉さんが撫でたげる\nこっちにきなさぁい♪", 2, 3715, 1, 103, 12, 103401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたくしの舞を\n主さまは喜んで\nくださるでしょうか…", 1, 3716, 1, 1, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("年を越したあとに\n食べるおそばも\nおいしいです", 1, 3717, 1, 2, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("甘酒を飲むと\n心まで温まる\n気がいたします", 1, 3718, 1, 3, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまのために\n真心を込めたおせちを\nご用意しなくては", 1, 3719, 1, 4, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おみくじを引くのは\nドキドキしつつも\n楽しいものです", 1, 3720, 1, 5, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまの温もりは\n心まで温めてくれる\nようです", 1, 3721, 1, 101, 4, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うまくできなくとも\n心を込めて精いっぱい\n舞いましょう", 1, 3722, 1, 102, 8, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さま、この晴れ着は\n似合っている\nでしょうか？", 2, 3723, 1, 1, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お餅はゆっくりと\n召し上がって\nくださいまし", 2, 3724, 1, 2, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまのお顔の\n福笑いなら、完璧に\nできる気がいたします", 2, 3725, 1, 3, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまはどのような\n初夢をご覧になった\nのでしょう？", 2, 3726, 1, 4, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("甘酒の飲み過ぎは\nいけませんよ？\nめっ、でございます", 2, 3727, 1, 101, 4, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("二人羽織とは\nあんなにも暖かい\nものなのですね…", 2, 3728, 1, 102, 8, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n寒い季節の朝日は\nとても美しいですね", 2, 3729, 1, 1, 1, 111901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしくとも\n食べ過ぎは正月太りの\nもとでございます", 2, 3730, 1, 2, 1, 111901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい夢が見られるよう\n暖かくして\n眠るといたしましょう", 2, 3731, 1, 3, 1, 111901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふか…\nこのまま\n寝てしまいそうです", 3, 3733, 1, 2, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと一緒に\nお正月遊びを\n楽しんでみたいです", 3, 3734, 1, 3, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("神殿の独特な香りを\nおうちに持ち込むのは\nどうでしょうか", 3, 3735, 1, 4, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("風邪をひきませんよう\n暖かくいたしましょう", 3, 3736, 1, 5, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べ過ぎは\n正月太りの\nもとだというのに…", 3, 3738, 1, 7, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまのために\n参拝の作法を\n予習しておきましょう", 3, 3739, 1, 8, 1, 111901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…この杖、変身前には\n無いパーツがあるけど\nこれはどこから…うん\n考えないようにしよう", 1, 3741, 1, 1, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フ、フリフリの\nかわいい衣装…はっ！\n素に戻ってはダメだ！", 1, 3742, 1, 2, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法探偵\nミスティ★カスミ！\n魔法の力で捜査開始！\n…練習終わりっと", 1, 3743, 1, 3, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("怪しい視線を感じる…\nまさか、近くに\n闇の力を持つ人が！？", 1, 3744, 1, 4, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時間もあるし、\n魔法少女の修行を…\nじゃ、じゃなくて！\n探偵の仕事をしよう！", 1, 3745, 1, 5, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("助手くんとずっと\n一緒に居られるし、\n魔法少女も\n案外悪くないかも♪", 1, 3746, 1, 101, 4, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女の訓練のため\n助手くんの所に行こう\nかな…あ、あくまで\n訓練のためにね！", 1, 3747, 1, 102, 8, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…髪型が急に\n変わって驚いた？\nき、気になるなら…\n少し触ってみるかい？", 2, 3748, 1, 1, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("助手くんは魔法少女に\nなりたいのかい？\nその場合は魔法騎士…\nいや、魔法助手とか？", 2, 3749, 1, 2, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("頭に浮かぶ呪文…\n強制変身…助手くん\n魔法少女とは\n呪いか何かなのかな？", 2, 3750, 1, 3, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、あまり触らないで\nくれ…魔法少女になる\nと感覚が鋭くなって、\n耳も敏感に…ひゃう！", 2, 3751, 1, 4, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("や、やっぱりこの\n格好は変かな…え、\nかわいい？　じゃあ…\nいや、でも、う～ん", 2, 3752, 1, 101, 4, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…この変身は助手くん\nのせいでもあるんだよ\nだから…せ、責任を\n取ってもらうからね！", 2, 3753, 1, 102, 8, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう助手くん\nさあ、そろそろ\n街のパトロールに\n行こうじゃないか！", 2, 3754, 1, 1, 1, 112201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうお昼…助手くん、\nそろそろ本業に戻ろう\n…その顔は何かな？\n私の本業は探偵だぞ！", 2, 3755, 1, 2, 1, 112201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜だけど、私は\nもう少し仕事をするよ\n魔法少女の強い体は\nこんなときに便利だね", 2, 3756, 1, 3, 1, 112201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちいい…\nこの癒しを、魔法と\n論理の二つの観点から\n解明したいね…", 3, 3758, 1, 2, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ダ、ダメ！！\nここで感情のままに\n飛びついたら、私の\nイメージがぁ～！", 3, 3759, 1, 3, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("心が安らぐ香りだね…\n…今なら、魔法少女も\nすんなりと受け入れ…\nてはダメだっ！", 3, 3760, 1, 4, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかい…\n魔法少女だろうと\n休息は必要だし、少し\n休んでいこうかな", 3, 3761, 1, 5, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女も探偵も、\nやっぱり体が資本！\n食べられるときに\n食べておかないとね♪", 3, 3763, 1, 7, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…魔法少女\nセリイちゃんの本は\nどこにあるのかな？", 3, 3764, 1, 8, 1, 112201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女かぁ…\nせっかくだし思う存分\n体を動かしてみたいな", 1, 3766, 1, 1, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ニャットちゃん…\nこの格好を見て\n私って気づくかな？", 1, 3767, 1, 2, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ…\n今日はなんだか\n調子がいいかも", 1, 3768, 1, 3, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法は便利だけど\nあまり頼りすぎちゃ\nダメだよね", 1, 3769, 1, 4, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さっき街で小さな子に\n声かけられちゃった\n照れるけどうれしいな", 1, 3770, 1, 5, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人がいると\nなんだかホッとする\n不思議…", 1, 3771, 1, 101, 4, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女になっても\nあの人への気持ちは\nずっと同じ…", 1, 3772, 1, 102, 8, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日の私…ですか？\nはいとっても元気です\n…あなたのおかげかも", 2, 3773, 1, 1, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よかったら魔法の\n練習に付き合って\nくれませんか？", 2, 3774, 1, 2, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの…\nこの格好どうですか？\n似合ってると…いいな", 2, 3775, 1, 3, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…な、なんですか？\nあまり見られると\n恥ずかしいです…", 2, 3776, 1, 4, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私、あなたのそばに\nいられたら、それで…", 2, 3777, 1, 101, 4, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("想い人と結ばれる\n魔法は…ひゃっ！？\n今の聞いてましたか？", 2, 3778, 1, 102, 8, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n今日も街の平和の\nために頑張らなきゃ", 2, 3779, 1, 1, 1, 112301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹すきましたね。\nあの…一緒にランチは\nいかがですか？", 2, 3780, 1, 2, 1, 112301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、もうこんな時間…\nふふ、まだこんなに\n体力が余ってるのに", 2, 3781, 1, 3, 1, 112301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちいい…\nこの気持ち良さは\nどんな魔法も勝てない", 3, 3783, 1, 2, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何これ、かわいい…\nお姉ちゃんにも\n見せてあげたいな", 3, 3784, 1, 3, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～、いい香り\n…これ、魔法で\n出せたりしないかな？", 3, 3785, 1, 4, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったか～い\nえへへ…なんだか\nお姉ちゃんみたい", 3, 3786, 1, 5, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしいなぁ、これ\n魔法少女になってから\n食欲旺盛かも…", 3, 3788, 1, 7, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ…\n魔法少女になっても\n読書はやめられないな", 3, 3789, 1, 8, 1, 112301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みらくるまほりん\nくるりんぱ～♪\n王子はんのために\n花嫁修業や～♪", 1, 3791, 1, 103, 12, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、あのな王子はん\nできたらその…\nお姫さまだっこを\nお願いしてもええ…？", 2, 3792, 1, 103, 12, 101001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱりわたしたちの\nギルドハウスの\n居心地は最高ですね☆", 1, 3793, 1, 1, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王宮じゃできないこと\nやっちゃいましょう♪\n例えば、えっと～…", 1, 3794, 1, 2, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうだ、隠しておいた\nおやつがありました！\nまだ食べられますね☆", 1, 3795, 1, 3, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ごはんはみんなで\n楽しく食べましょう！\nそれが一番の\n調味料です♪", 1, 3796, 1, 4, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱりここが、\nわたしの帰る場所です\n…ただいま☆", 1, 3797, 1, 5, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだか物足りません\nきっと、あの人が隣に\nいないからですね…", 1, 3798, 1, 101, 4, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どこを見ても、大切な\n思い出がたくさん\n詰まっていますね♪", 1, 3799, 1, 102, 8, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("無礼者～、なんて\n冗談です♪　どんどん\n触っちゃってください", 2, 3800, 1, 1, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷにぷにでしょう～？\nい～っぱい食べるのが\nぷにぷにの秘訣です！", 2, 3801, 1, 2, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("握手したいんですか？\nはい、にぎにぎ～！\nもう離しませんよ♪", 2, 3802, 1, 3, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうかしましたか？\n退屈してるんでしたら\nお散歩に行きましょう", 2, 3803, 1, 4, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ごはん王子♪\nわたしは王女ですから\nこれでピッタリですね", 2, 3804, 1, 101, 4, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大好きです～\n愛してます～\n…ほんと、ですよ♪", 2, 3805, 1, 102, 8, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝ごはんは大事です！\n山盛りごはんを食べて\n元気いっぱいですよ☆", 2, 3806, 1, 1, 1, 180401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹ぺこぺこになる\n時間ですね～！\nごはん特盛、一つ！", 2, 3807, 1, 2, 1, 180401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹いっぱい、今日は\nよく眠れそうですね♪\n明日もおいしい一日を", 2, 3808, 1, 3, 1, 180401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休憩休憩～♪\nお腹を休めて、次の\nごはんに挑みます…☆", 3, 3810, 1, 2, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいらしい\nぬいぐるみですね～\nキャルちゃんみたい☆", 3, 3811, 1, 3, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すんすん…この匂い\n食欲増進の効果が\nありそうですね…？", 3, 3812, 1, 4, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体温が上がってくると\n眠くなっちゃいます…\nほわぁ～", 3, 3813, 1, 5, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐもぐもぐもぐ\nむぐむぐむぐむぐむぐ\nはぐはぐはぐはぐはぐ", 3, 3815, 1, 7, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("教養を身に着けるには\n読書が一番です！\nえっと次のレシピは～", 3, 3816, 1, 8, 1, 180401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイドルらしくなる\nコツって、何か\nあるんでしょうか？", 1, 3818, 1, 1, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("色んな人と話すのが\n好きなんです。つい\n長くなっちゃって…", 1, 3819, 1, 2, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイドルを目指すって\n決めてから、毎日が\nワクワクなんです♪", 1, 3820, 1, 3, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちゃんとストレッチ\nしておかなくっちゃ\nよいしょ、よいしょ…", 1, 3821, 1, 4, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リンちゃんミオちゃん\n二人に負けないように\n私、頑張ります！", 1, 3822, 1, 5, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の笑顔は素敵だって\n誰かに褒められた…\nそんな気がするんです", 1, 3823, 1, 101, 4, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私たちを支えてくれる\n誰かが、ずっと一緒に\nいてくれたような…", 1, 3824, 1, 102, 8, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうかしましたか？\n何か困ってるのなら\nお手伝いしますよ！", 2, 3825, 1, 1, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みなさん個性的で\n普通じゃない人ばかり\nいるような気が…", 2, 3826, 1, 2, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はポカポカした\nいい天気ですね～\nお散歩日和です！", 2, 3827, 1, 3, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今、ミルクティーを\n淹れてたんです♪\nあなたも飲みますか？", 2, 3828, 1, 4, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の得意なこと？\nうーんなんでしょう…\nあっ、肩たたきです！", 2, 3829, 1, 101, 4, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("生・ハム・メローン！\nあ、ライブの掛け声を\n練習してたんですよ♪", 2, 3830, 1, 102, 8, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます！\n今日も一日\n頑張りましょうね！", 2, 3831, 1, 1, 1, 112401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しっかりお昼を食べて\n午後からも張り切って\nいきましょうね♪", 2, 3832, 1, 2, 1, 112401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぐっすり眠れるよう\n早めに用事を済ませて\nお休みしましょうね", 2, 3833, 1, 3, 1, 112401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと休んだら\nレッスンの続きも\n頑張ります！", 3, 3835, 1, 2, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ～\nふわふわもこもこで\nかわいいです～♪", 3, 3836, 1, 3, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リラックスできる\nいい香りですね～♪", 3, 3837, 1, 4, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁ、ポカポカです♪\n温かい飲み物も\nほしくなりますね", 3, 3838, 1, 5, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッスンしたら\nお腹が空いちゃって…\nぱくぱくもぐもぐ…", 3, 3840, 1, 7, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッスンに役立つ\n運動の情報とか\n載ってるでしょうか…", 3, 3841, 1, 8, 1, 112401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きらきらーん☆\nよし、次のステージは\nこれで行けるかも！", 1, 3843, 1, 1, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の元気でみんなも\n元気になってくれたら\nうれしいな～", 1, 3844, 1, 2, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっとレッスンで\n疲れちゃったかも…\nでも頑張るぞっ！", 1, 3845, 1, 3, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("晩ごはん何にしよう？\nそーだ、しぶりんにも\n聞いてみよっと！", 1, 3846, 1, 4, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("元気だから笑顔になる\nじゃなくて\n笑顔だから\n元気になるんだよね～", 1, 3847, 1, 5, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("声援を聞いてる時ね\nすごく懐かしいって\n思うことがあるんだ", 1, 3848, 1, 101, 4, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私を応援してくれる\n一番大事な人が\n隣にいた気がする…", 1, 3849, 1, 102, 8, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なになにー？\nミオちゃんに\n何か用かな～？", 2, 3850, 1, 1, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっ、やっほー！\n元気そうだね～、キミ\n私？\nもちろん元気～！", 2, 3851, 1, 2, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇねぇ、ちょっと\n遊びに行かない？\nたまには息抜きで！", 2, 3852, 1, 3, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ね、この魔物料理さ\nプリンって言い張れば\n食べてもらえそうかな", 2, 3853, 1, 4, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ\nいつもありがとねっ！\nパワーもらってるよ～", 2, 3854, 1, 101, 4, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたどうした～\nミオちゃんの魅力に\nメロメロなのかい？", 2, 3855, 1, 102, 8, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっはよ～！\n一日の始まりだし\nテンション上げてこ！", 2, 3856, 1, 1, 1, 112601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹空いた～…\nねぇねぇ、一緒に\nお昼食べようよ～", 2, 3857, 1, 2, 1, 112601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ～…\n眠くなってきちゃった\nそろそろ休もっかなぁ", 2, 3858, 1, 3, 1, 112601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁ、ふっかふか～！\nレッスンの疲れも\n吹っ飛んじゃうね☆", 3, 3860, 1, 2, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何これ…かわいーっ！\n早くしまむーに\n教えてあげなきゃ！", 3, 3861, 1, 3, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すぅ～…\nうんっ、これ私の\n好きな香りだな～♪", 3, 3862, 1, 4, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ポッカポカだね～♪\n…あ～ん、ここから\n動きたくないーっ！", 3, 3863, 1, 5, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ、おーいしー！\nこれはテンション\n上がっちゃうね♪", 3, 3865, 1, 7, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\nふむふむふむ…！\n勉強になった、ブイ☆", 3, 3866, 1, 8, 1, 112601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんでドキドキが\n止まらないの…？\n騎士くんのせいだー！", 1, 3868, 1, 103, 12, 100101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドキドキしてるの\nあたしだけ、かな…\n騎士くんはどう…？", 2, 3869, 1, 103, 12, 100101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンの前で\n好きって言えるように\n練習しないと…", 1, 3870, 1, 103, 12, 100201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クン…大好き\n…き、騎士クン！？\nなんでここに！？", 2, 3871, 1, 103, 12, 100201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("困ったな…\n彼が居ないだけで、\nここまで\n寂しいと思うなんて…", 1, 3872, 1, 103, 12, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えっと…\n今日は訓練じゃなくて\nその…二人でゆっくり\n過ごしたいな…", 2, 3873, 1, 103, 12, 100301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイドルの心構え…\nどういう風に考えると\nしっくりくるのかな", 1, 3874, 1, 1, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何か始めるのって\nドキドキするよね\nだから最近楽しいんだ", 1, 3875, 1, 2, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冒険者の時って毎日\nバタバタしてたけど…\n目標ができると違うね", 1, 3876, 1, 3, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少しお腹が空いた…\nチョコレート一粒だけ\n食べようかな", 1, 3877, 1, 4, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ウヅキもミオも\n頑張ってるし\n私も負けられないね", 1, 3878, 1, 5, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッスンしてる時さ\n何か、誰かが足りない\nそう思うことがあるの", 1, 3879, 1, 101, 4, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大事なのは笑顔…\n誰か、大切な人から\n言われた気がするんだ", 1, 3880, 1, 102, 8, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたの、何か用？\n手伝えることがあれば\nすぐに言ってね", 2, 3881, 1, 1, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("姿勢がいい？\n普段から鍛えてるし\n自然とそうなるのかも", 2, 3882, 1, 2, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さっき散歩してたら\n犬を見かけたんだ\n人懐っこい子だったよ", 2, 3883, 1, 3, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今から冒険？\nなら私も一緒に行くよ\n前衛は任せておいて", 2, 3884, 1, 4, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今からレッスンに\n行くつもりだったんだ\n少し手伝ってくれる？", 2, 3885, 1, 101, 4, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("蒼の剣を受けよ！\nえ、何してるのって？\nただの発声練習だけど", 2, 3886, 1, 102, 8, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう、早いね\n今日は依頼もないし\nゆっくりしようかな", 2, 3887, 1, 1, 1, 112501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろお昼だね\nうーん、今日は\n何を食べよう…", 2, 3888, 1, 2, 1, 112501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間…\n明日も早いし\nそろそろ寝なくちゃ", 2, 3889, 1, 3, 1, 112501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッスンで疲れたし\nちょっとだけ\n休んでおこうかな", 3, 3891, 1, 2, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ、かわいい\nふわふわしたものって\n撫でたくなるんだよね", 3, 3892, 1, 3, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うん、いい香り…\nこういうものがあると\n落ち着くからいいよね", 3, 3893, 1, 4, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("温かい場所って\n居心地がいいから\nのんびりしちゃうよ", 3, 3894, 1, 5, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッスン頑張ったら\nすぐお腹が空くし\n食べておかないと…！", 3, 3896, 1, 7, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイドルのことを\nもっと勉強して\n成長しなくちゃ", 3, 3897, 1, 8, 1, 112501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ、知りたい…\nなんでもかんでも\nとにかく知りたい…", 1, 3899, 1, 1, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ、眠い…\nいつでもどこでも\nとにかく眠い…", 1, 3900, 1, 2, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君、気を付けたまえ\nぼーっと歩いていると\nほわっ！　転んだ…", 1, 3901, 1, 3, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミツキ師にいただいた\n新作サプリ…丁度よい\n被験体はいないものか", 1, 3902, 1, 4, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サレンディア救護院に\nユニちゃん８歳として\n潜入済みだが何か？", 1, 3903, 1, 5, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君がユニちゃんズの\n同志であること、\nぼくは誇りに思うぞ", 1, 3904, 1, 101, 4, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼくは青春がしたい\nおい、君\nぼくと青春しないか", 1, 3905, 1, 102, 8, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ、そうだな。\nぼくもそう思う。\n……えっ、何が？", 2, 3906, 1, 1, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("待て、話しかけるな。\n今の閃きをメモに…\n…ああっ、忘れた！", 2, 3907, 1, 2, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歩き方が綺麗？\n何を今更なこと\n言っとるんだ君は", 2, 3908, 1, 3, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼくの血液型？\n大らかのОだ。\n何か異論あるかね", 2, 3909, 1, 4, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君の声は精神に\n高揚をもたらすな…\n波形を分析したいぞ", 2, 3910, 1, 101, 4, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("妙だな…最近\n君に話しかけられると\n心拍に乱れを覚える", 2, 3911, 1, 102, 8, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっと、朝だな。\nそろそろ寝るか、\n朝更かしは体に悪い", 2, 3912, 1, 1, 1, 111001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ、昼餉時か…\n今日のランチは\nサプリ定食にしよう", 2, 3913, 1, 2, 1, 111001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう夜だな、\nそろそろ起きるか。\n最高の一日にするぞ！", 2, 3914, 1, 3, 1, 111001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほわぁ～\n副交感神経が…\n優位に…ふふっひ", 3, 3916, 1, 2, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいすぎるな…\nセクシーユニには\nミスマッチか…", 3, 3917, 1, 3, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほぁあアあァぁー…\nいい香りー…\nあアァあ…イイ…", 3, 3918, 1, 4, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("炎はいいぞ\nそこには人類発展の\nドラマがある", 3, 3919, 1, 5, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フオオー！\n次から次へと固形食物\n原理気になるー！", 3, 3921, 1, 7, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("良書は時間を忘れる\n…ふむ、今度\n布団を持ってこよう", 3, 3922, 1, 8, 1, 111001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きらーん☆\nハツネちゃんに\n不可能はないのだ☆", 1, 3924, 1, 103, 12, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミと一緒だと\n寝ちゃうのが\nもったいないよ～", 2, 3925, 1, 103, 12, 101201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちぇるーん☆", 2, 3933, 1, 1, 1, 192101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちぇる～ん☆\n今日もチエルは\nかわいいですよね～？", 1, 3951, 1, 1, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どこかに楽しいもの\n落ちてないかにゃー", 1, 3952, 1, 2, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("チエルのオキニは\n甘々カフェラテ！\nシクヨロでぇ～す☆", 1, 3953, 1, 3, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩、ひまですよね？\nチエル遊んであげても\nいいですけど？", 1, 3954, 1, 4, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁー…しゅき…\nカルミナ尊い…\n一生すこれる…", 1, 3955, 1, 5, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩、ひまー\nちょっとは構えよーう\nデュクシ！デュクシ！", 1, 3956, 1, 101, 4, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩なんか\nおごって～！\nてか…おごらなくても\nいいから遊んでよ…", 1, 3957, 1, 102, 8, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え、なんですか？\n告白だったら\n間に合ってますけど", 2, 3958, 1, 1, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと静かに！\n今ヤバかわポーズの\nイメトレ中なんです！", 2, 3959, 1, 2, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("足取りが軽やか？\nあー…ダンスとか\n習ってるからですかね", 2, 3960, 1, 3, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("チエルの血液型？\n大型新人のОです\n何か問題でも？", 2, 3961, 1, 4, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩って何気に\nいい声してますよね\n言うことは変だけど", 2, 3962, 1, 101, 4, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え、なんですか？\nたまにだったら\n告白してもいいですよ", 2, 3963, 1, 102, 8, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはちぇる～ん☆\nハイ、ご一緒に～？", 2, 3964, 1, 1, 1, 110901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のランチは\nどこで\n映えよっかにゃー", 2, 3965, 1, 2, 1, 110901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんばんちぇるるん☆\nハイ、ご一緒に～？", 2, 3966, 1, 3, 1, 110901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかチエルン\n略して、ふかルン♪", 3, 3968, 1, 2, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいこの子と\nかわいいチエル！\n映ぁ～え～る～！", 3, 3969, 1, 3, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい香り～！\n持って帰ろっと！\nすぅーっ…", 3, 3970, 1, 4, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マシュマロは\n焼かない方のが\nかわいくないです？", 3, 3971, 1, 5, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("チエル食べても\n太らない体質\nなんでぇ～！", 3, 3973, 1, 7, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("読書は好きですよ\nシンプルに楽しいし\nギャップ萌えでしょ？", 3, 3974, 1, 8, 1, 110901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなのあたしを\n見る目が違うね\nま、気にしないけどね", 1, 3976, 1, 1, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も疲れた～\nやる気ゼロだし\nもう寝ちゃおうかな", 1, 3977, 1, 2, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしの代わりに誰か\n働いてくれないかね", 1, 3978, 1, 3, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("労働の後に食べる\nあんパン最高～", 1, 3979, 1, 4, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕事の合間に\nちょっと一息いれよ\nあ～ドングリ美味し～", 1, 3980, 1, 5, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("報酬も入ったことだし\nあいつに何か\n買ってあげようかな", 1, 3981, 1, 101, 4, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次の休みはあいつと\n一日中だらだら\nしたいな～", 1, 3982, 1, 102, 8, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしは褒められて\n伸びるタイプなんだ\nだから褒めて褒めて", 2, 3983, 1, 1, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、差し入れ？\n気が利くねぇ\nあんがと", 2, 3984, 1, 2, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しい依頼？\n今日はもう無理～\n閉店で～す", 2, 3985, 1, 3, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サ、サボってないよ！\nちょっと休憩してた\nだけだから！", 2, 3986, 1, 4, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、一緒に\nサボろうよ？\n働き過ぎはよくないよ", 2, 3987, 1, 101, 4, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたが近くにいると\n仕事の疲れも\n和らぐんだよね～", 2, 3988, 1, 102, 8, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…もう起きなきゃ\nつらい労働の\nはじまりだ～", 2, 3989, 1, 1, 1, 112701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うぅ、お昼に\nあんパン食べ過ぎた…\n苦しい…眠い…", 2, 3990, 1, 2, 1, 112701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日は仕事ないし\nガッツリ夜ふかし\nしちゃうよ～", 2, 3991, 1, 3, 1, 112701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("猫みたいに\n丸くなっちゃうよ～\nあたしリスだけどね", 3, 3993, 1, 2, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふか～\nあたしの尻尾と\n互角とはやるね～", 3, 3994, 1, 3, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんパンの香りの\nアロマとか\nあればいいのにな～", 3, 3995, 1, 4, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは危険な\nあたたかさだね～\n労働意欲が\nなくなるよ～", 3, 3996, 1, 5, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いっぱい働いたから\nいっぱい食べても\nカロリー０だよ", 3, 3998, 1, 7, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしだってたまには\n本くらい読むって\n全然似合わないけどね", 3, 3999, 1, 8, 1, 112701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしの作った\nオリジナルたい焼き…\nあいつ、\n喜んでくれるかにゃ？", 1, 4001, 1, 103, 12, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、お帰りにゃー♪\nえへへ…キミに\nお帰りって言えるのが\nなんかうれしいにゃ♪", 2, 4002, 1, 103, 12, 104601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フロンティア\nスピリッツを\nお見せするべ！", 1, 4003, 1, 1, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この鎧を着ると\n気が引き締まる\n感じがするべ", 1, 4004, 1, 2, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("搾りたての牛乳飲んで\n今日も一日\nがんばるべ！", 1, 4005, 1, 3, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなに牧場の\n乳製品を\n味わってもらいてぇべ", 1, 4006, 1, 4, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここはいいとこだべ\nうちの動物たちも\n連れてきてやりてぇな", 1, 4007, 1, 5, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなオラより\n若ぇのに働いてて\n立派だべな", 1, 4008, 1, 101, 4, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("牧場もギルドの\nみんなもオラが\nまとめて面倒見るべ！", 1, 4009, 1, 102, 8, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さあ、今日も\n忙しくなるべよ\n気合入れてくべ！", 2, 4010, 1, 1, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、あんちゃん\n丁度いいとこに！\n一緒に街に\n行商しに行くべ！", 2, 4011, 1, 2, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("牧場仕事で培った力が\n戦いでも役立つなら\n一石二鳥だべさ！", 2, 4012, 1, 3, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("疲れた時は牧場産の\nミルク菓子で\n糖分補給だべ", 2, 4013, 1, 4, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ、牧場の\n新製品だべ\n一番最初に味見\nしてほしいべさ", 2, 4014, 1, 101, 4, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("働きづめはよくねぇベ\n膝枕してやっから\nこっち来るべさ", 2, 4015, 1, 102, 8, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁあ…\n酪農家の朝は\n早ぇんだべ…", 2, 4016, 1, 1, 1, 112801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ごはんの時間だべ！\n腹が減っては酪農も\n戦いもできねえべ！", 2, 4017, 1, 2, 1, 112801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ寝るべ！\n健全なお笑いは\n健全な肉体に宿るべ！", 2, 4018, 1, 3, 1, 112801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("牧草みたいに\nふっかふかだべ～", 3, 4020, 1, 2, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子、目の感じが\nエリザベスに似てるべ", 3, 4021, 1, 3, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい匂いだべ～\n疲れた体に\nしみるべな～", 3, 4022, 1, 4, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったけぇな～\n牧場にも\n置いてみっかな～", 3, 4023, 1, 5, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うまいべ！\n生産者のこだわりを\n感じるべさ", 3, 4025, 1, 7, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("酪農も戦いも\nまずは知識だべ！", 3, 4026, 1, 8, 1, 112801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぴょん、ぴょん♪\nこの服のおかげで、\n体が軽いなぁ…♪", 1, 4028, 1, 1, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今の内に部屋の\n掃除をしておこっと…\nみんな喜んで\nくれるといいなぁ", 1, 4029, 1, 2, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("耳と尻尾…この服、\n本当にウサギさん\nみたいだなぁ", 1, 4030, 1, 3, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだか先輩の\n気配がするような…\n気のせいかな？", 1, 4031, 1, 4, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ウサギさんの真似を\nしたら、存在感が薄い\nとか言われないかな？\nア、アユミだぴょん♪", 1, 4032, 1, 5, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ…\nいつもとは違う先輩が\nたくさん見られて、\nうれしいな♪", 1, 4033, 1, 101, 4, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本の中の世界で先輩と\n旅をするなんて…\n幸せすぎて、罰が\n当たりそうだよぉ…", 1, 4034, 1, 102, 8, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じ～…はっ！？\nす、すみません！\n話しかけてもらえる\nなんて思ってなくて！", 2, 4035, 1, 1, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩がすぐそばに…\nし、幸せすぎて\n倒れそうですぅ！", 2, 4036, 1, 2, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え、えっと…あの…！\nうう…いざ先輩と\n向き合うと\n緊張しちゃうよぉ…", 2, 4037, 1, 3, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はうっ！？\nしょ、正面から見る\n先輩は、私にとって\n神々しすぎますぅ…！", 2, 4038, 1, 4, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩…その…\nい、一緒にご飯でも\nどうでひゅか！\nうう…またかんだぁ…", 2, 4039, 1, 101, 4, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せ、先輩…\nハーブティーを\n入れたんですが、\n一緒にどうですか…？", 2, 4040, 1, 102, 8, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せ、先輩！\nおはようございます！\nえへへ、練習通りに\nバッチリ言えたぁ♪", 2, 4041, 1, 1, 1, 113001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、もうお昼ですね\n時計を持ってて\n良かったです", 2, 4042, 1, 2, 1, 113001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間…\nお休みする\n準備をしちゃいますね", 2, 4043, 1, 3, 1, 113001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ…ちょっとだけ\n先輩の匂いがする…\nえへへ、幸せだなぁ♪", 3, 4045, 1, 2, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…私もウサギさんの\nぬいぐるみとして、\n先輩のそばに…はっ！\n私ったら何を…！", 3, 4046, 1, 3, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、いい香り…\n先輩もこういうのが\n好きなのかな？", 3, 4047, 1, 4, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩が隣に\n居たら、もっと\n暖かいのになぁ…♪", 3, 4048, 1, 5, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしい…でも、\n先輩と一緒に\n食べたら、もっと\nおいしいだろうな…", 3, 4050, 1, 7, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ウサギさんって、穴を\n掘ったりするんだ…\n私も、隠れたいときに\n掘ってみようかな？", 3, 4051, 1, 8, 1, 113001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ネビアさまのように\n普段からパタパタと\n飛んでみるのも…", 1, 4053, 1, 1, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ご立派になられた\n主さまと並べるように\nもっと精進しなくては", 1, 4054, 1, 2, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("月々の食費が\n増えてしまいました\n申し訳ございません…", 1, 4055, 1, 3, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワンワンのほうの\n主さまは、この姿に\n驚くでしょうか…？", 1, 4056, 1, 4, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまと離れていても\n主さまとの絆は\n胸に感じております…", 1, 4057, 1, 5, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このギルドハウスは\nみなさまの帰る場所…\nわたくしが守ります", 1, 4058, 1, 101, 4, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんな未来が\n待ち受けようとも\n主さまと添い遂げます", 1, 4059, 1, 102, 8, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おでかけですか？\nではわたくしも\nお供いたします", 2, 4060, 1, 1, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう二度と主さまと\n離れたくはありません\nいつ何時も…", 2, 4061, 1, 2, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なにかお困りごと\nでございますか？\nわたくしに何なりと…", 2, 4062, 1, 3, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうぞゆっくりと\n心ゆくまでくつろいで\nくださいまし、主さま", 2, 4063, 1, 4, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この羽で主さまを\nどこまでも遠く…\n高くへと導きます", 2, 4064, 1, 101, 4, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さま、主さま…♪\nおそばにいられるのが\nうれしくて、つい…", 2, 4065, 1, 102, 8, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n今日も一日、主さまの\nサポートをいたします", 2, 4066, 1, 1, 1, 180501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も頑張っている\n主さまに、スタンプを\nもう一つ…ポン！", 2, 4067, 1, 2, 1, 180501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寝付けないのでしたら\nわたくしが子守唄を\n歌ってさしあげます", 2, 4068, 1, 3, 1, 180501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふか…\nまるで主さまのような\n柔らかさでございます", 3, 4070, 1, 2, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたも一緒に\n主さまと遊びますか？\n至福の時間ですよ♪", 3, 4071, 1, 3, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまの優しくて\nくすぐったい匂いが\nたまらなく恋しいです", 3, 4072, 1, 4, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまの心と\n繋がったときのような\n温もりを感じます", 3, 4073, 1, 5, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いけませんっ…！\n元の姿に戻ると、また\n食べてしまうのに…！", 3, 4075, 1, 7, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまに読み聞かせる\n絵本は…妖精が主役の\n物語にいたしましょう", 3, 4076, 1, 8, 1, 180501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…彼のこと弟みたいに\n思ってきたのに…私、\nどうしたらいいの…？", 1, 4078, 1, 103, 12, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よ、予定がなかったら\nでいいんだけど…\nその、ふ、二人で\n訓練とか…どうかな？", 2, 4079, 1, 103, 12, 104801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おめかしもしたし\nあとはお兄ちゃんを\n待つだけですね～♪", 1, 4080, 1, 1, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんの身の回り\nをお片付け～、これぞ\nデキる妹アピール！", 1, 4081, 1, 2, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、衣装がほつれてる\nこれくらいなら自分で\n繕えますね…！", 1, 4082, 1, 3, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好で歩いてると\n見慣れた景色も\n違うものに見えますね", 1, 4083, 1, 4, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("勉強もちゃんとします\n…でも、一人だと\n集中力がもちません～", 1, 4084, 1, 5, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんを大好きな\n妹が待ってますよ～\n…まだですかね～", 1, 4085, 1, 101, 4, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんのために\n掃除洗濯をする私って\nお嫁さんみたい…\n…えへへ～", 1, 4086, 1, 102, 8, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おに～いちゃん！\n縫い物、一緒に\nやりましょうよ！", 2, 4087, 1, 1, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい妹を\n愛でたくなりました？\n思う存分、どうぞ♪", 2, 4088, 1, 2, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ、ビックリした～\nもう、お兄ちゃんてば\nイタズラっ子ですね～", 2, 4089, 1, 3, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒にお買い物\n行きませんか？\n妹とデートですよっ♪", 2, 4090, 1, 4, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃん…頭を\n撫でてくれませんか？\nえへへ、これが一番♪", 2, 4091, 1, 101, 4, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃん大好き♪\n何度でも言いますよ！\nお兄ちゃん大好きっ♪", 2, 4092, 1, 102, 8, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよ～お兄ちゃん！\n妹モーニングコールの\n時間ですよっ♪", 2, 4093, 1, 1, 1, 112901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ休憩ですね！\n甘いお菓子で\n元気回復しましょ～！", 2, 4094, 1, 2, 1, 112901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜更かし厳禁！\nでも、もう少しだけ\nお話ししたいなぁ～", 2, 4095, 1, 3, 1, 112901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふっかふかですよ！\nお兄ちゃんと一緒に\n座りたいなぁ…♪", 3, 4097, 1, 2, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このぬいぐるみの\nかわいさ…う～ん\n負けられません…！", 3, 4098, 1, 3, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("香りにも気をつかって\nパーフェクトな妹に\nなっちゃいますから！", 3, 4099, 1, 4, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～ぬくぬくです～\nお兄ちゃんと一緒に\n温まりたいなぁ…♪", 3, 4100, 1, 5, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは止まりませんね\nもぐもぐ…いくらでも\n食べられちゃいます", 3, 4102, 1, 7, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ、デザインの\n参考になりそう！\n私にも作れるかなぁ", 3, 4103, 1, 8, 1, 112901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("退屈です…\nなにか楽しいことは\nないですか？", 1, 4105, 1, 1, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギャングの仕事は\n今日はお休みです\nのんびりするですよ", 1, 4106, 1, 2, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひうっ！　あたしの\n尻尾なんて食べても\nおいしくないですよ？", 1, 4107, 1, 3, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふう…どうやら\n例の件はまだボスに\nバレてないですね…", 1, 4108, 1, 4, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("下克上…いい言葉です\nって、ボスに聞かれて\nないですよね…？", 1, 4109, 1, 5, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか絶対ビッグに\nなってやるです！\nあたしを信じるです！", 1, 4110, 1, 101, 4, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしが覚醒したら\nきっと誰よりも\n強くなるはずです！", 1, 4111, 1, 102, 8, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんですか？\n貢ぎ物なら\nいつでも歓迎ですよ！", 2, 4112, 1, 1, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしだって\nやる時はやるですよ！\nその時がこないだけ！", 2, 4113, 1, 2, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しりとり勝負ですか？\nいい度胸ですね、\nかかってくるです！", 2, 4114, 1, 3, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんは\nヒマそうですね…\nうらやましいです", 2, 4115, 1, 4, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かまってほしいです？\nまったく…いいですよ\nしょうがないですね", 2, 4116, 1, 101, 4, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんのことは\nこのあたしが\n守ってやるですよ！", 2, 4117, 1, 102, 8, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("デキるギャングの\n朝は早いのです…\nふぁあ…", 2, 4118, 1, 1, 1, 106601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹がすいたですね\nなにか食べにいくです\nお兄さんのおごりで！", 2, 4119, 1, 2, 1, 106601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁあ…むにゅう…\nまだ起きてるですよぉ", 2, 4120, 1, 3, 1, 106601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～…\nもうここから一歩も\n動きたくないです", 3, 4122, 1, 2, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なかなかいいモフりを\nしてやがるです…\n舎弟にしてやるですよ", 3, 4123, 1, 3, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんかおしゃれな\n匂いがするですね…", 3, 4124, 1, 4, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふーん！\nあたしのブレスの方が\n火力は上ですね！", 3, 4125, 1, 5, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしに貢ぎ物とは\nよく分かってるですね\n食べてやるですよ", 3, 4127, 1, 7, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふーむ…\nもっと楽しい本は\nないですかね？", 3, 4128, 1, 8, 1, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に眠る秘宝…\n心躍る響きだ！\n早く見つけたい…！", 1, 4130, 1, 1, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うう～、暑いぃ…\nかき氷を食べて\nすっきりしたいぃ…", 1, 4131, 1, 2, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アターック！\nいや、もっとこう…\nアタァーック！", 1, 4132, 1, 3, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スイカ割りで\n目を回さない\nコツはなんだろうか…", 1, 4133, 1, 4, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかく海に来たのだ\n泳ぎも上手に\nなりたいものだな", 1, 4134, 1, 5, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふっふっふ…\n疼く…疼くぞ！\n日焼けの痕が…", 1, 4135, 1, 101, 4, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シグルドと私は\n来世でも共にある…\nつまり我らはずっと…\nはわわ…！", 1, 4136, 1, 102, 8, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シグルド、私と共に\n日光浴に行かないか？\n光の力を集めよう！", 2, 4137, 1, 1, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好だからできる\n必殺技を考えている\n何か案はないか？", 2, 4138, 1, 2, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シグルド～！\nスイカを貰ったから\n一緒に食べよう！", 2, 4139, 1, 3, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こう日差しが強いと\n日焼けしそうだな\n跡になってないか…？", 2, 4140, 1, 4, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("我らの夏の黙示録\nしっかりと記録\nしておかねばな", 2, 4141, 1, 101, 4, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちゃんと日焼けどめを\n塗ってもらうべき\nだったかな…？\nシ、シグルドに…！", 2, 4142, 1, 102, 8, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝だぞシグルド！\nさぁ、日光を浴びて\n光の加護を得るのだ！", 2, 4143, 1, 1, 1, 113201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう昼食の時間か…\n私の魔力も減ったし\n早く補給しなければ", 2, 4144, 1, 2, 1, 113201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜でも我らの活動は\n終わることはない！\nさぁ準備を…ふわぁ…", 2, 4145, 1, 3, 1, 113201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海で遊んでいると\n疲れてしまうからな\n少し休まるとしよう", 3, 4147, 1, 2, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ～、君の名前は\n何にしまちょうかね♪\n…はっ、見たのか！？", 3, 4148, 1, 3, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("心地よい香りで\n我が精神も安らぐ…", 3, 4149, 1, 4, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("別に寒くなどないぞ！\n寒くないが、ちょっと\n暖まりたくなってな！", 3, 4150, 1, 5, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐ…食べ過ぎた分は\n魔力に変換されるのだ\n…たぶん", 3, 4152, 1, 7, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…なな、なんだ！？\nシグルドはこういう\n趣味なのか…！？", 3, 4153, 1, 8, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むむ、この乗り心地…\nいざゆかん、\nシードラゴンよ！", 3, 4155, 1, 10, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("疾風の冥姫の名に\nふさわしき\n深海の玉座よ…\nふああ…柔らかい～", 3, 4156, 1, 11, 1, 113201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この姿でいると\nわたしもお姫様に\nなれた気がする…♪", 1, 4157, 1, 1, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹空いてきちゃった\nまずは買い出しに…\n…変身解かなくちゃ！", 1, 4158, 1, 2, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("胸のところが空いてて\nスースーするの\nまだ慣れないな…", 1, 4159, 1, 3, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("治癒魔法に使ってた\n魔力を攻撃魔法に…\n頭の中でも練習練習", 1, 4160, 1, 4, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何もできなかった\nわたしから、少しは\n変われたのかな…？", 1, 4161, 1, 5, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クン…\n今どこにいるの…？\n…会いたいな", 1, 4162, 1, 101, 4, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("離れてても分かるよ…\n温かい力で騎士クンに\n守られてるの", 1, 4163, 1, 102, 8, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたしが戦えてるのは\n騎士クンのおかげだよ\nいつもありがとう！", 2, 4164, 1, 1, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹空いてそう…？\n…内緒で作ったおやつ\n騎士クンも食べる？", 2, 4165, 1, 2, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃうっ！　え！？\nせ、背中はダメ～！\n言ってから触って～！", 2, 4166, 1, 3, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好、どうかな？\nえ？　似合ってる…？\n本当？　…うれしい！", 2, 4167, 1, 4, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい？　そうだね\nひらひらが…わたし？\nええっ、そ、そんな！", 2, 4168, 1, 101, 4, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クン、これからも\nずっと…わたしの\nそばにいてください", 2, 4169, 1, 102, 8, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝からこんなに\n食べる日が来るなんて\n思ってなかったよ…", 2, 4170, 1, 1, 1, 180201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼を作らなくちゃ\n騎士クン、一緒に\nお料理してみる？", 2, 4171, 1, 2, 1, 180201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クン、もう眠い？\n眠るまで、わたしが\nずっとそばにいるね", 2, 4172, 1, 3, 1, 180201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("攻撃参加するからこそ\n適度に体を休めるのは\n大切だよね！", 3, 4174, 1, 2, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい…騎士クンと\nシェフィちゃんにも\nプレゼントしたいな", 3, 4175, 1, 3, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り～…\nあれ？　お腹が空いて\nきちゃった…！？", 3, 4176, 1, 4, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("温かい…\n騎士クンがくれる\n力みたい…", 3, 4177, 1, 5, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぱくっ、\nあむ、はむっ…\nううぅ～…やっぱり\n手が止まらないよぉ～", 3, 4179, 1, 7, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しく覚えたいな…\nみんなで食べられる\n大皿向けの料理♪", 3, 4180, 1, 8, 1, 180201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんの愛\nこのままじゃ\nあふれちゃうよ…♪", 1, 4182, 1, 103, 12, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くん♪\n弟くんっ♪\nおっとうっとくんっ♪", 2, 4183, 1, 103, 12, 104901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぐのもいいけど\n今日は砂浜で\nのんびりしようかね", 1, 4184, 1, 1, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さてと\nちょっくらひと泳ぎ\n行ってくるかね", 1, 4185, 1, 2, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっついねぇ…\nうちわがないと\nしんどいったらないよ", 1, 4186, 1, 3, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冷たすぎる飲み物で\n体を冷やさないよう\n気をつけないと…", 1, 4187, 1, 4, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏はあっという間だし\n悔いがないように\n楽しまないとね", 1, 4188, 1, 5, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きっとこの夏は\nアタシにとって大事な\n想い出になるね…", 1, 4189, 1, 101, 4, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…前に比べたら\nアタシたちの距離も\n近づいたみたいだね", 1, 4190, 1, 102, 8, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もし暇なら\n今日も笹舟釣り\n一緒にどうだい？", 2, 4191, 1, 1, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お前さん、釣りに\n興味が湧いたなら今度\n道具を見に行こうよ", 2, 4192, 1, 2, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今から砂浜に行くんだ\nお前さんも一緒に\n散歩するかい？", 2, 4193, 1, 3, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え、日焼け跡？\nおや…本当だ\nすぐ焼けちまうねえ", 2, 4194, 1, 4, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃっ！？\nちょっと！\n日焼け跡をいきなり\n触らないでおくれ！", 2, 4195, 1, 101, 4, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お前さんは、その…\nアタシと一緒にいて\n楽しかったかい？", 2, 4196, 1, 102, 8, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようさん\n今日も砂浜に行って\nゆっくりしようか", 2, 4197, 1, 1, 1, 113101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼か…\nそうだ、よかったら\n刺身定食、作ろうか？", 2, 4198, 1, 2, 1, 113101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の空を見てるとさ\nなつかしい気持ちに\nなるんだよね", 2, 4199, 1, 3, 1, 113101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("適度に休憩して\n夏バテしないよう\n気をつけないとね", 3, 4201, 1, 2, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたたちも\n海を楽しみたいって\n思っているのかね", 3, 4202, 1, 3, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～…香りでも\nバカンスらしさを\n楽しめるもんだね", 3, 4203, 1, 4, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういう格好だと\n少し冷えちまうんだよ", 3, 4204, 1, 5, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐもぐ…\n遊んだ分、お腹が\n空いちまってねぇ", 3, 4206, 1, 7, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…ん、なんだいこの本\n催眠…うーん読めない\nナナカに聞いてみるか", 3, 4207, 1, 8, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へえ…\nなかなかいい\n乗り心地じゃないか", 3, 4209, 1, 10, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうそうハマグリって\n竿でも釣れるんだよ\n知ってたかい？", 3, 4210, 1, 11, 1, 113101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海を満喫しなきゃね\nちょっとひと泳ぎ\n行ってこようかな？", 1, 4211, 1, 1, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("う～ん…♪\nいつもと違った\n開放感～\nなんちゃって！", 1, 4212, 1, 2, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今のナナカちゃんは\nたぶん水属性！", 1, 4213, 1, 3, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着もバッチリ！\nサイカワサイツヨ\nナナカちゃ～ん☆", 1, 4214, 1, 4, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んっふっふ\nドキ！　水着だらけの\nギルドハウス！\nとかどうかな？", 1, 4215, 1, 5, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そんなに見られると\nちょ～っと\n恥ずかしいかも…\nなんてねなんてね！", 1, 4216, 1, 101, 4, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっとくらい\nドキッとしてくれても\nいいのにな～、もう…", 1, 4217, 1, 102, 8, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着魔法少女の\n相方がほしいなぁ～…\nね、君やってみない？", 2, 4218, 1, 1, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもの格好と同じ？\nも～、わかってない！\nセクスィー度が違う！", 2, 4219, 1, 2, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうかなどうかな？\nこのひらひらのとこが\nかわいーかなー\nとか思うんだけど！", 2, 4220, 1, 3, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくだから\nギャルゲーイベント\nごっことか\nやってみる？", 2, 4221, 1, 4, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ナナカちゃんの\n好感度を上げたい？\nならおでかけだー！", 2, 4222, 1, 101, 4, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おうちで水着って\nなんだかコスプレ\nみたいで楽しいかも♪", 2, 4223, 1, 102, 8, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっはよーう！\n今日はバカンス日和！\n海へゴーですぞ～♪", 2, 4224, 1, 1, 1, 113301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯どうしよ～…\nあ、ナナカちゃんと\nどっか食べに行く？", 2, 4225, 1, 2, 1, 113301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜は本を読むのが\n捗りまくりですな～！\n今日はなに読もっかな", 2, 4226, 1, 3, 1, 113301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次のイベントもあるし\nちょっと休んで体力を\n回復しなきゃね～", 3, 4228, 1, 2, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうマスコット\n私にもいたらなぁ\nいっそ作っちゃう…？", 3, 4229, 1, 3, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着魔法少女に\n似合う香りってのも\n考えてみよっかな♪", 3, 4230, 1, 4, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜になると急に冷えて\n肌寒いんだよね～…", 3, 4231, 1, 5, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんまり食べると\nお腹が出て…でも…\nうう、止まらない～！", 3, 4233, 1, 7, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この催眠魔法の本\n誰にもばれないように\n保管しとかなきゃね…", 3, 4234, 1, 8, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ゴーゴーゴーゴーゴー\nナナカちゃーん♪", 3, 4236, 1, 10, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ナナカちゃんの\n誕生～\nなんちゃって", 3, 4237, 1, 11, 1, 113301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ファイトファイト☆\n一生懸命\n応援するね！", 1, 4238, 1, 1, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんながんばってる！\n私も応援でみんなを\n盛り上げなきゃ！", 1, 4239, 1, 2, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もし元気のない人が\nいたら…応援で少し\nでも元気にしたいな！", 1, 4240, 1, 3, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("がんばれ～☆\nよし、発声練習OK！\n応援は、声も大事！", 1, 4241, 1, 4, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかく水着なんだし\n泳いだり潜ったりして\n遊びたいな～！", 1, 4242, 1, 5, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("チアリーダーとして\nキミを精一杯\n応援したいな…！", 1, 4243, 1, 101, 4, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミへの応援\nちゃんと\n届いてるかな…", 1, 4244, 1, 102, 8, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ…今ね、\nキミへの応援歌を\n考えてたのだ～♪", 2, 4245, 1, 1, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたの？\n元気がないなら\n私が応援するよ☆", 2, 4246, 1, 2, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("がんばったあとは休憩\nしなきゃね！　私と\n一緒にお昼寝する？", 2, 4247, 1, 3, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シオリンとおそろいの\n水着で応援…\nしてみたいなぁ～", 2, 4248, 1, 4, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はなにして遊ぶ？\nキミがしたいことを\n教えてよ！", 2, 4249, 1, 101, 4, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミを応援\nすることができて…\n私、すごく幸せ…", 2, 4250, 1, 102, 8, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミって早起き\nなんだね！　私も\n見習わなきゃ！", 2, 4251, 1, 1, 1, 113401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっとお疲れかな？\nそれじゃあ\n応援してあげるね♪", 2, 4252, 1, 2, 1, 113401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("遅い時間まで\nがんばってえらいね！\nでも無理はダメだよ♪", 2, 4253, 1, 3, 1, 113401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっとだけ休憩…\n…あう、座り心地が\n良すぎて…眠気が…", 3, 4255, 1, 2, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいるみんなを\n私の応援でもっと\n元気にするのだ～！", 3, 4256, 1, 3, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("元気の出る香り～♪\nこれもうまく応援に\n活かせないかな～？", 3, 4257, 1, 4, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽかぽかあったまって\n元気をチャージ\nするのだ～☆", 3, 4258, 1, 5, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いっぱい食べて、\nみんなを応援する\nパワーをつけなきゃ！", 3, 4260, 1, 7, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなを元気にする\n方法は…どこかに\n書いてないかなぁ…？", 3, 4261, 1, 8, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁ、この子\n怪獣さんみたいで\nかわいいね～♪", 3, 4263, 1, 10, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着でこれに\n乗ってると海にいる\n気分になれるね！", 3, 4264, 1, 11, 1, 113401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すごく忙しいけど\nとても充実した気分\nこれが青春なのかしら", 1, 4265, 1, 1, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("森の静かな雰囲気も\n海の開放的な空気も\nどちらも素敵ね～", 1, 4266, 1, 2, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("汚れたお洗濯物は\nみんなが頑張った証\nなんだか愛おしいわ", 1, 4267, 1, 3, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなを見てると\n何だか私も\n走りたくなっちゃうわ", 1, 4268, 1, 4, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくの水着だし\n泳ぐ練習でも\nしてみようかしら", 1, 4269, 1, 5, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんな～ファイト～！\n応援するのも大事よね\n練習しておかなきゃ♪", 1, 4270, 1, 101, 4, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先生に教えられること\nまだまだい～っぱいね\n次は何がいいかしら♪", 1, 4271, 1, 102, 8, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も暑くなりそうね\nこまめな水分補給を\n忘れないでね", 2, 4272, 1, 1, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("手伝ってくれるの？\nありがとう♪\n先生、頼りにしてるわ", 2, 4273, 1, 2, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休憩はこまめに\nとりましょうね\n無理は厳禁よ", 2, 4274, 1, 3, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の遊びって\nどんなのがあるの？\n先生に教えてね", 2, 4275, 1, 4, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着は初めてだけど\nどう？　変じゃない？\nふふ、ありがとう", 2, 4276, 1, 101, 4, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと過ごした\nこの夏は、きっと…\n忘れられない思い出ね", 2, 4277, 1, 102, 8, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう～\n朝練前にちゃんと\nごはん食べましょうね", 2, 4278, 1, 1, 1, 113501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お弁当作ってきたの\n栄養いっぱい摂って\n午後も頑張ろうね", 2, 4279, 1, 2, 1, 113501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうお休みしなきゃね\n先生が子守唄を歌って\nあげましょうか？", 2, 4280, 1, 3, 1, 113501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、いい気持ちねぇ\n先生、少しだけ\n休憩しちゃおうかしら", 3, 4282, 1, 2, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あらかわいい♪\nチームにもこういう\nマスコットが欲しいわ", 3, 4283, 1, 3, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら、海の香り？\n波の音まで聞こえて\nきちゃいそうだわ", 3, 4284, 1, 4, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うふふ\nこれなら濡れた水着を\n乾かすのも簡単ね♪", 3, 4285, 1, 5, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ、美味しいわね♪\nでも、食べ過ぎは\n禁物よ", 3, 4287, 1, 7, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先生だって日々勉強よ\n新しいことを知るのは\nとても楽しいわ♪", 3, 4288, 1, 8, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あらあら、楽しいわね\nみんなもきっと\nおおはしゃぎね", 3, 4290, 1, 10, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、これで\n夏らしい気分を\n満喫するわよ♪", 3, 4291, 1, 11, 1, 113501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サンドイッチも\n作ったし、\nお兄ちゃんのお出迎え\n準備は完璧だね♪", 1, 4292, 1, 103, 12, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ、お兄ちゃんと\nぷうきちが居てくれる\nだけで、なんだか\nうれしくなっちゃう♪", 2, 4293, 1, 103, 12, 102301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し赤くなっているな\n日焼けなんてしたのは\nいつ以来だろう", 1, 4294, 1, 1, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好で\n過ごすのは\n少し勇気がいるな…", 1, 4295, 1, 2, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑いのは平気だが\n肌が外気に触れるの\nにはまだ慣れないな…", 1, 4296, 1, 3, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好でも\n堂々としていれば\n恥ずかしくはない…\nのかな？", 1, 4297, 1, 4, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっと…鎧姿の時と\n重心が違うせいか\nちょっと不安定だな", 1, 4298, 1, 5, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この水着…\n私に似合って\nいるのだろうか…？\n少年には聞きづらいな", 1, 4299, 1, 101, 4, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年との\n海のバカンス…\nまた行きたい\nものだな", 1, 4300, 1, 102, 8, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あまり見るのは\nよしてくれ…\n恥ずかしいじゃ\nないか…", 2, 4301, 1, 1, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうかしたのかい？\n私でよければ\n話し相手くらいには\nなろうじゃないか", 2, 4302, 1, 2, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃっ！\nす、すまない\nちょっと過敏に\nなっているようだ", 2, 4303, 1, 3, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…っくしゅん！\nすまない\n薄着には慣れて\nないものでね", 2, 4304, 1, 4, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まあ、少年になら\n見られても…\nい、いや！\nなんでもない！", 2, 4305, 1, 101, 4, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私がこうして\nゆっくりできるのは\n少年がそばにいて\nくれるからだよ", 2, 4306, 1, 102, 8, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この時間なら\nビーチにも人は\n少ないだろうね…\n遊びに行くかい？", 2, 4307, 1, 1, 1, 113601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食のお誘いかい？\nいいよ、付き合おう", 2, 4308, 1, 2, 1, 113601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう夜か…\n一日が経つのは\nはやいものだね", 2, 4309, 1, 3, 1, 113601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは楽でいいな…\nいつもは鎧姿で\n家具を傷つけないか\n気を使っているからね", 3, 4311, 1, 2, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うん…ふわふわの\n感触が\nよくわかるな…", 3, 4312, 1, 3, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもは\n鎧に匂いが\n移ってしまうのが\n悩みなんだよ…", 3, 4313, 1, 4, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーむ…\n涼しいのに暖かい\nなんだか奇妙な気分だ", 3, 4314, 1, 5, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兜を気にせず\n食べられるのは\n楽でいいな…", 3, 4316, 1, 7, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ…鎧がないと\nページがめくりやすい", 3, 4317, 1, 8, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身軽でいいな…\n鎧を着ていると\n騎乗訓練の時\n馬に申し訳がなくてね", 3, 4319, 1, 10, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貝をうまく使えば\n水中でも\n守りを固められそうだ", 3, 4320, 1, 11, 1, 113601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どこをアジトと\nつなげようかな～…\nこのへんにしよっと♪", 1, 4321, 1, 1, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここってちょっと\n変わった建物だね\n妖精がいるでしょ？", 1, 4322, 1, 2, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("色んな人を観察できて\n眼福眼福…♪", 1, 4323, 1, 3, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("家具の配置変更なら\nアタシにおまかせあれ\n…家の形は変えない？", 1, 4324, 1, 4, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新メニューどうしよう\n思いついた人がいたら\nアタシに教えてね！", 1, 4325, 1, 5, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年、早く帰って\nこないかな…\nよし、迎えに行こう！", 1, 4326, 1, 101, 4, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("結局またあちこち\n移動する日々だし…\n少年に会いたいな～", 1, 4327, 1, 102, 8, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どしたの少年？\nお姉さんに何でも\n相談してみな～？", 2, 4328, 1, 1, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あれをああして…\nおや少年！　ごめんね\nすぐに気づけなくて！", 2, 4329, 1, 2, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何？　クリスが\nアタシを探してる？\n…いないって言って！", 2, 4330, 1, 3, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よければリノちゃんと\nシズルちゃんにも\n顔を見せてあげて", 2, 4331, 1, 4, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年～！\nもうヘトヘトだよ～！\nお願い癒して～！", 2, 4332, 1, 101, 4, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…アタシが素直に\n助けてって言えるのは\n少年だけだよ", 2, 4333, 1, 102, 8, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝だよ少年！\n爽やかな朝の\nクレープはいかが？", 2, 4334, 1, 1, 1, 106801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹空いたな～\nお昼のクレープ\n少年は食べる？", 2, 4335, 1, 2, 1, 106801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜までクレープは\nやめとけ？　ごめん\nそれだけは無理…！", 2, 4336, 1, 3, 1, 106801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アタシこんなに\nゆっくりしちゃって\nいいんだっけ～？", 3, 4338, 1, 2, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…これ\nネネカが変身\nしてないよね？", 3, 4339, 1, 3, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りだ…\n解析完了\n今度生成しようっと♪", 3, 4340, 1, 4, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("安心するな～…\nアジトに置けないから\n羨ましいよ", 3, 4341, 1, 5, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べ物を消化するって\n仕組み、どんなものか\n気になる…", 3, 4343, 1, 7, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("速読できるけど\n本を読む時くらい\n文字にじっくり\n浸かりたいんだよね…", 3, 4344, 1, 8, 1, 106801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エンジェルとして\nみんなを元気に…！\nアカリ、頑張ります♪", 1, 4346, 1, 1, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんと一緒に\nお兄ちゃんを…えへへ\nまだかな、お兄ちゃん", 1, 4347, 1, 2, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エンジェルの音色を\n目指して、今日も\nサックスの練習です♪", 1, 4348, 1, 3, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんとの特訓も\n頑張らないと…\n厳しくしてくださいね", 1, 4349, 1, 4, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいエンジェルの\n格好、お兄ちゃんなら\n喜んでくれますよね♪", 1, 4350, 1, 5, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エンジェルの力で\nお兄ちゃんのハートも\nイチコロですよ♪", 1, 4351, 1, 101, 4, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アカリが一番\n元気にしたいのは\nお兄ちゃんですよ♪", 1, 4352, 1, 102, 8, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃん？\n触りたいなら…\nこことかどうですか♪", 2, 4353, 1, 1, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("特訓の時間ですか？\nアカリ、楽しみに\nしてたんですよ♪", 2, 4354, 1, 2, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、お兄ちゃん！\nそろそろアカリと\n休憩…しませんか♪", 2, 4355, 1, 3, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この羽、触り心地\nいいですか？　あんっ\nくすぐったいですよぉ", 2, 4356, 1, 4, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんも元気に\nなりたいんですか？\nアカリにお任せです♪", 2, 4357, 1, 101, 4, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やんっ♪\nお兄ちゃんったら\nダイタンですね♪", 2, 4358, 1, 102, 8, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃん、朝ですよ\nすっごく気持ちのいい\nお天気ですよ…♪", 2, 4359, 1, 1, 1, 113701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼寝しませんか\nお兄ちゃん？\nアカリの膝枕で…♪", 2, 4360, 1, 2, 1, 113701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜ですね、お兄ちゃん\nアカリ、なんだか胸が\nドキドキしちゃいます", 2, 4361, 1, 3, 1, 113701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フカフカですね…\n隣にお兄ちゃんが\nいてくれたらなぁ…♪", 3, 4363, 1, 2, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ、アカリも\nこんな風にかわいく\nなりたいな～", 3, 4364, 1, 3, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんが好きな\n匂いなのかな？\n参考にしますね！", 3, 4365, 1, 4, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体が火照ってきて\nなんだかアカリ…\nクラクラしちゃう…", 3, 4366, 1, 5, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はむ、んぐ…あっ\nほっぺについちゃった\nベトベトですよぉ～", 3, 4368, 1, 7, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エンジェルって色んな\n物語に出てきますよね\nもっと調べなくちゃ！", 3, 4369, 1, 8, 1, 113701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの方の前では\n常に気高く\nありたいですわね", 1, 4371, 1, 103, 12, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんなに道に迷っても\nあなたさまの元には\n絶対に辿り着く\n自信がありますわ", 2, 4372, 1, 103, 12, 103201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたと一緒に\nいるときが一番楽しい\n一時かもしれないわ", 1, 4373, 1, 103, 12, 102801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつかあんたと一緒に\nサレンディア救護院を\n切り盛り…なんてね♪", 2, 4374, 1, 103, 12, 102801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も\nエンジェルとして、\nみんなの幸せの\nために頑張らないと", 1, 4375, 1, 1, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかく羽が\nついてるのに\n飛べないのが残念だわ", 1, 4376, 1, 2, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好、子供たちに\n妙にウケがいいわね\nま、悪くないけど", 1, 4377, 1, 3, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("や、やっぱりみんな\n注目してくるわね…\nエンジェルって珍しい\nからしかたないか", 1, 4378, 1, 4, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エンジェルになると\n人見知りがなおる！\n…わけないか", 1, 4379, 1, 5, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エンジェルの活動は\n大変だけど、自分が\n成長してるって\n実感がうれしいわね", 1, 4380, 1, 101, 4, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もし誰かの願いを\nかなえられるなら\n私はアイツの…\nって何考えてるのよ！", 1, 4381, 1, 102, 8, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何ボサっとしてるの！\nさあ、街に出て\n人助けするわよ！", 2, 4382, 1, 1, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エンジェリック\nアロー！\nなんてね…え、アンタ\nいつから見てたのよ！", 2, 4383, 1, 2, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コラ！\n羽は触らないで！\n壊れたらどうするのよ", 2, 4384, 1, 3, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エンジェルじゃなく\nても、アンタはいつも\n人助けしてるわよね\n…ちょっと尊敬するわ", 2, 4385, 1, 4, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服なら他の子より\n私を見てくれるかも…\nって、な、何\n見てるのよ！", 2, 4386, 1, 101, 4, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ね、ねえ、もし私が\n困ってたら、一番に\n駆けつけて…やっぱり\n何でもないわ！", 2, 4387, 1, 102, 8, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう…あ、あの、\nエンジェルとして\n町に行くんだけど…\n一緒に行かない？", 2, 4388, 1, 1, 1, 113801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ、いいことした\n後のランチは\nおいしいわね", 2, 4389, 1, 2, 1, 113801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間…\n夜更かししてないで\n早く寝なさいよね", 2, 4390, 1, 3, 1, 113801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい座り心地ね～\nまさに天にも昇る\n心地よさだわ～", 3, 4392, 1, 2, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、かわいい…\nあ、羽付けたら\nもっとかわいく\nなるんじゃないかな？", 3, 4393, 1, 3, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～落ち着くわ～\n回復アイテムみたいで\n癒やされちゃうわ～", 3, 4394, 1, 4, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ、とと…\n危ない、羽が\nこげちゃうところ\nだったわ", 3, 4395, 1, 5, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人の役に立つのって\nすごく大変だから、\nこれでライフ回復よ！", 3, 4397, 1, 7, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エンジェルに関する\n本はあるかしら…あ！\nこれ探してた攻略本！", 3, 4398, 1, 8, 1, 113801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふっふっふ\n吸血鬼らしく\n驚かせてあげましょう", 1, 4400, 1, 1, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("獲物はどこですか～！\nう～ん、もうちょっと\n迫力が欲しいですね", 1, 4401, 1, 2, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トリックオアトリート\n…返事がないので\nイタズラしておきます", 1, 4402, 1, 3, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンですし\nたまには騎士さんでも\n誘ってあげますかね", 1, 4403, 1, 4, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マントは動きに\nメリハリがついて\nいいですね", 1, 4404, 1, 5, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("色んな仮装が見られて\nやっぱりハロウィンは\n最高ですね", 1, 4405, 1, 101, 4, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("吸血鬼らしい行動って\n噛みついたり…いや\nそれは大胆過ぎです！", 1, 4406, 1, 102, 8, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("呼びましたか？\n手短にお願いしますよ\n忙しいんですから！", 2, 4407, 1, 1, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え？　衣装に穴が？\nありがとうございます\n…よく見てるんですね", 2, 4408, 1, 2, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわあ…吸血鬼の\n姿でも、眠い時は\n眠いんですよね…", 2, 4409, 1, 3, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンってライブ\nとは違った賑やかさが\nあってワクワクします", 2, 4410, 1, 4, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私を驚かそうとしても\n無駄ですよ！\nすぐ分かるんですから", 2, 4411, 1, 101, 4, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さん、一緒に\nハロウィンを…いいえ\nなんでもないですっ！", 2, 4412, 1, 102, 8, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕事で寝不足だから\n太陽がまぶしいです…\n私、吸血鬼っぽいかも", 2, 4413, 1, 1, 1, 113901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯は真っ赤な…\nトマト尽くしのお弁当\nにしてみました", 2, 4414, 1, 2, 1, 113901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜はハロウィンが\n盛り上がる時間…\n行きますよ騎士さん！", 2, 4415, 1, 3, 1, 113901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このフィット感\nどうにか服作りにも\n活かせれば…！", 3, 4417, 1, 2, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よく出来てますね…！\nぬいぐるみの服を作る\nのも楽しそうですね！", 3, 4418, 1, 3, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい感じですね…\n服に合わせた香りって\nいうのも、いいかも…", 3, 4419, 1, 4, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ、温まりますね…\nおっと、マントに火が\n点いちゃいそうです！", 3, 4420, 1, 5, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あぁ、美味しい～\n食べた分は、働いて\n燃焼しますからね！", 3, 4422, 1, 7, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("伝説の吸血鬼…\n夜を統べる者…\nほうほう…", 3, 4423, 1, 8, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱりハロウィンと\nいえばお菓子です！\nさぁ配りましょうか！", 3, 4425, 1, 12, 1, 113901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好…\nカッコイイのに\n動きやすくて\n着心地も最高ッス！", 1, 4427, 1, 1, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キメポーズはこう…\nいやこっちのほうが…\nなやましいッス…！", 1, 4428, 1, 2, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トリックオア\nジャスティス！\nって言ったら何か\nもらえるッスかね？", 1, 4429, 1, 3, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しい必殺技の\n特訓もしなくちゃ\nいけないッスね…\n忙しいッス！", 1, 4430, 1, 4, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自分のこの姿\nトモね～ちゃんにも\nみせてあげるッス！", 1, 4431, 1, 5, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ホワイトタイガー\n参上ッス！\n今のポーズは\nキマったッス！", 1, 4432, 1, 101, 4, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人と一緒だと\nほんとにヒーローに\nなれる気がするッス！", 1, 4433, 1, 102, 8, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうッスか？\nこの色、自分に\n似合ってるッスかね？", 2, 4434, 1, 1, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒマだったら\n必殺技の特訓に\n付き合ってもらって\nいいッスか？", 2, 4435, 1, 2, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょうどいいところに\n来たッスね！\nこのキメポーズ\nどうッスか？", 2, 4436, 1, 3, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お！　この格好、\n気になるッスか？\nじっくり見ても\nいいッスよ♪", 2, 4437, 1, 4, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたも一緒に\n新しい技の練習\nどうッスか？", 2, 4438, 1, 101, 4, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もあんたと一緒に\nランドソルの平和を\n守るッスよ！", 2, 4439, 1, 102, 8, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝ッス！\n一緒に早朝特訓\nやるッスよ！", 2, 4440, 1, 1, 1, 114101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼休憩ッス！\nヒーローにも\n休息は必要ッス！", 2, 4441, 1, 2, 1, 114101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("闇夜に映える\n白い衣装で\n平和を守るッスよ！", 2, 4442, 1, 3, 1, 114101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トラも狩りの時以外は\nごろごろしてるって\n本で読んだッスよー", 3, 4444, 1, 2, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もこもこッスね♪\nこのかわいらしさを\n守ってあげるのも\nヒーローの役目ッス！", 3, 4445, 1, 3, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい匂いッスね…\nリラックスして\n瞑想するッス！", 3, 4446, 1, 4, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("燃える炎は\nヒーローの心意気ッス\nいつまでも\n見てられるッスよ", 3, 4447, 1, 5, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…\nいっぱい食べて\n強いヒーローに\nなるッスよ！", 3, 4449, 1, 7, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちゃんと勉強の本も\n読んでるッスよ…！\nヒーローには賢さも\n必要らしいッス！", 3, 4450, 1, 8, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わわっ、お菓子が\nいっぱいッス！\nみんなで\n食べるッスよ！", 3, 4452, 1, 12, 1, 114101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワタシがチューシンと\nなった今、天下統一は\n目の前デス！", 1, 4454, 1, 103, 12, 103001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうショーグンってば\nそれはセイシツに\nすることデ～ス…", 2, 4455, 1, 103, 12, 103001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("女幽霊…うらめしや…\nうーん、これは\nちょっと違う気が\nするな…", 1, 4456, 1, 1, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何だか寒気がする…\nま、まさか\nこの部屋にも幽霊が？", 1, 4457, 1, 2, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンは楽しいね\n童心に帰ったような\n気分だよ", 1, 4458, 1, 3, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度のハロウィンは\nユイとヒヨリを\n誘ってみようかな", 1, 4459, 1, 4, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンのお菓子は\nどれもかわいいね\n…一つくらいなら\nいいかな？", 1, 4460, 1, 5, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次は彼と\nどんなハロウィンを\n過ごそうかな…", 1, 4461, 1, 101, 4, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな賑やかさも\nいいものだね\n彼といられるのなら\nなおさら…", 1, 4462, 1, 102, 8, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…いたずらしようと\nしてない、キミ？\nふふ、お見通しだよ", 2, 4463, 1, 1, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え、私にもお菓子を？\nありがとう…ふふ\nうれしいものだね\nハッピーハロウィン！", 2, 4464, 1, 2, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたの？\n出かけるなら\n私も同行しようか", 2, 4465, 1, 3, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好、舞踏会にも\n出られそうだね\n一曲、踊ってみる？", 2, 4466, 1, 4, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やるからには本気で\nやらせてもらおう\nトリックオア\nトリート！", 2, 4467, 1, 101, 4, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("他の子に目移りする\nのも分かるが、その…\nせっかくの特別な衣装\n見てほしいな", 2, 4468, 1, 102, 8, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寝起きの体を\n慣らしておこうか\nほら、剣を取って", 2, 4469, 1, 1, 1, 114001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子もいいけど\nちゃんと昼食も\nとるんだよ", 2, 4470, 1, 2, 1, 114001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さあ、行こうか！\nハロウィンは\nこれからが本番だよ", 2, 4471, 1, 3, 1, 114001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンはまだ\nこれからだ\n一休みしようか", 3, 4473, 1, 2, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミたちも\n仮装に興味は\nあるかな？　…ふふ", 3, 4474, 1, 3, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りだけど\n幽霊が集まったり\nしないだろうか…？", 3, 4475, 1, 4, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かい…一息ついたら\nハロウィンの\nパレードを\n見に行こうかな", 3, 4476, 1, 5, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンを本気で\n楽しむなら\n食事もしっかり\nとっておかないとね", 3, 4478, 1, 7, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンの\nホラー小説か…\nけ、結構\n怖いものだね…？", 3, 4479, 1, 8, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子がいっぱいだ…\nこういうのって\n見ているだけで心が\n躍ってしまうね", 3, 4481, 1, 12, 1, 114001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなにかわいい\n武器で戦えるとは…\nすごいものだな\n魔法少女は", 1, 4483, 1, 1, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("決めポーズの訓練も\nしっかりやっておくか\n…誰も見ていないな？", 1, 4484, 1, 2, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういう格好は\nユキあたりがすごく\n似合いそうだな", 1, 4485, 1, 3, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("子どもたちにサインを\n求められてしまった…\nこれもまた私の使命！", 1, 4486, 1, 4, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好は目立つな…\nいや、提督とは人々の\n視線を集めるものだ！", 1, 4487, 1, 5, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつと作戦会議を\nしておくか。あれで\nなかなか頼れるからな", 1, 4488, 1, 101, 4, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつには私の勇姿を\nちゃんと見ていて\nほしいものだな", 1, 4489, 1, 102, 8, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一仕事終えたことだし\n一緒に甘いものでも\n食べに行くか？", 2, 4490, 1, 1, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("怪しげな気配がするな\n貴公も警戒を\n怠るなよ！", 2, 4491, 1, 2, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シオリに魔法少女の\n本を借りたんだ\n一緒に読まないか？", 2, 4492, 1, 3, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("巡回の時間まで\nお茶にでもするか\n貴公も付き合うがいい", 2, 4493, 1, 4, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴公がサポートして\nくれるのなら心強いな\n頼りにしているぞ", 2, 4494, 1, 101, 4, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("頭を撫でるな～！\n…まったく、貴公だけ\nだぞ、こんな風に私を\n撫でてくるのは…", 2, 4495, 1, 102, 8, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("起きろ貴公！\n魔法少女の朝は\n早いぞ！", 2, 4496, 1, 1, 1, 114201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほら、食後の\nデザートだ\nて、適度な糖分は\n体に必要なんだ！", 2, 4497, 1, 2, 1, 114201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ…魔法少女も…\n眠気、には…い、いや\n寝てないぞ！？", 2, 4498, 1, 3, 1, 114201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("任務や訓練で\n疲れた体に\nこれは効くなぁ…", 3, 4500, 1, 2, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うむ、かわいいな\nモーラのやつを隣に\n並べようか", 3, 4501, 1, 3, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ、身も心も\n安らぐ…\nまるで魔法だな…", 3, 4502, 1, 4, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この温かさ…\n愛と希望に\n通じるものがある…", 3, 4503, 1, 5, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食事の大切さは\n魔法少女も軍人も\n変わりない\nしっかり食べるんだ！", 3, 4505, 1, 7, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女の本を\n読んでるのだが\nわ、私もこんななのか", 3, 4506, 1, 8, 1, 114201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オラとあんちゃんは\nボケもツッコミも\nあうんの呼吸だべ♪", 1, 4508, 1, 103, 12, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんちゃんと二人で\nネタ合わせ…初めての\n共同作業だべ♪", 2, 4509, 1, 103, 12, 103301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぴっぷる！", 1, 4510, 1, 1, 1, 192501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぴっぷるぴっぷる♪", 1, 4511, 1, 2, 1, 192501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぴっ！", 1, 4512, 1, 3, 1, 192501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷっぷー", 1, 4513, 1, 4, 1, 192501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぴぃ？", 1, 4514, 1, 5, 1, 192501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぴっぷるんるん♪", 2, 4515, 1, 1, 1, 192501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷぅ！", 2, 4516, 1, 2, 1, 192501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぴぴっ♪", 2, 4517, 1, 3, 1, 192501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷぅー…", 2, 4518, 1, 4, 1, 192501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちゅ！", 2, 4519, 1, 1, 1, 192501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷはー", 2, 4520, 1, 2, 1, 192501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぴぇー", 2, 4521, 1, 3, 1, 192501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女になったら\n髪型も変わるんだね\n色々試してみようかな", 1, 4531, 1, 1, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…煌く剣技で、\n悪を断つ！\nうん、今日も\n完璧なポーズだね♪", 1, 4532, 1, 2, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミクマ流剣術で、\n魔法少女の技に使え\nそうなものは…よし、\n早速試してみよっと♪", 1, 4533, 1, 3, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女になったから\nには、サインの練習も\nしないと…\nよし、頑張るぞ！", 1, 4534, 1, 4, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女の姿はすごく\nかわいいけど…この\n姿はジュンさんたちに\n見せられないなぁ…", 1, 4535, 1, 5, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人は魔法少女\nのこと好きなのかな？\n…好きだったら\nうれしいな♪", 1, 4536, 1, 101, 4, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…やっぱり、\nあの人がいないと\n特訓に身が入らない…\n早く帰ってこないかな", 1, 4537, 1, 102, 8, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もし時間があるなら、\n私と街の見回りに\n行かない？", 2, 4538, 1, 1, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、いいところに！\n新しい魔法剣術を\n編み出したから、\n見てくれないかな？", 2, 4539, 1, 2, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女の姿が気に\nなるのは分かるけど…\nず、ずっと見られる\nのは照れるからやめて", 2, 4540, 1, 3, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変身ポーズ中の動き、\n少し変えた方が\nいいかな…\nあなたはどう思う？", 2, 4541, 1, 4, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よければ、\n魔法少女の特訓に\n付き合ってくれない？\nその…二人きりでさ…", 2, 4542, 1, 101, 4, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私…あなただけの\n魔法少女になっても…\nふふっ、な～んてね♪", 2, 4543, 1, 102, 8, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もいい朝だね\nさあ、一緒に\n街の見回りに行こうか", 2, 4544, 1, 1, 1, 114301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう昼か…なにか\n食べたいものある？\n簡単なのでいいなら、\n私が作ってあげるよ", 2, 4545, 1, 2, 1, 114301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ休もうか\n…なんなら、添い寝\nしてあげようか？\nふふっ、冗談だよ♪", 2, 4546, 1, 3, 1, 114301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは…\n心身ともに安らぐね\nなんだか\n眠くなっちゃいそう", 3, 4548, 1, 2, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、かわいい…これ、\n魔法で動かせたり\nしないかな？", 3, 4549, 1, 3, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りだね\nなんだか頭が冴えて\nきたし、新しい技でも\n考えようかな", 3, 4550, 1, 4, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいな…\nこの温もりは、\n魔法少女の魔法でも\n再現不可能だね…", 3, 4551, 1, 5, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こ、これは…\nおいしすぎて手が\n止まらないかも", 3, 4553, 1, 7, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本の\nキャラの動き、\n変身ポーズの\n参考にできるかも！", 3, 4554, 1, 8, 1, 114301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリークリスマス！\nさあ、素敵な\nパーティーを始めると\nいたしましょう！", 1, 4556, 1, 1, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ、\nいくつになっても、\nやはりクリスマスは、\nワクワクしますわね♪", 1, 4557, 1, 2, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自分で料理をしてみて\nシェフたちのすごさが\n改めて分かりましたわ", 1, 4558, 1, 3, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何事も自分で\n体験してみると\n新しい発見が\nあるものですわね♪", 1, 4559, 1, 4, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やはり、クリスマスは\n街が活発になり\nますわね…これは、\n絶好の商機ですわ♪", 1, 4560, 1, 5, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("他のクリスマス料理も\n作れるようになったら\nあのお方は食べて\nくださるかしら…？", 1, 4561, 1, 101, 4, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのお方に贈る\nプレゼント…\nこれはかなりの\n難題ですわね…", 1, 4562, 1, 102, 8, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリークリスマス！\nよろしければ、一緒に\nクリスマスの準備を\nいたしませんか？", 2, 4563, 1, 1, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まあ、クリスマスの\n飾りつけを手伝って\nいただけるのですか？\nありがとうございます", 2, 4564, 1, 2, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスに合わせて\nあつらえた自慢の衣装\nなのですが…その、\nいかがでしょうか？", 2, 4565, 1, 3, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("幼い頃はサンタさんが\nいらっしゃるのを\n待ちわびたものです\n今は…内緒ですわ♪", 2, 4566, 1, 4, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("も、もしお時間が\nあるようでしたら、\nクリスマスの街を\n一緒に歩きませんか？", 2, 4567, 1, 101, 4, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("来年のクリスマスも\nあのお方と一緒に\n迎えられたら…", 2, 4568, 1, 102, 8, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時は金なり…\nせっかくの朝ですもの\n時間を有効活用\nいたしましょう！", 2, 4569, 1, 1, 1, 114401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼になりましたわね\nさあ、\nパーティーの準備を\n進めますわよ！", 2, 4570, 1, 2, 1, 114401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("静かな夜ですわね…\nもうちょっとだけ、\nあなたさまとお話を\nしていたい気分です", 2, 4571, 1, 3, 1, 114401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("適度な休息は\n成功の秘訣ですわ！", 3, 4573, 1, 2, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このかわいらしさ…\nいつまでも見て\nいられそうですわ♪", 3, 4574, 1, 3, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人をもてなすには\nこうしたところにも\n気を配らないと\nいけませんわね", 3, 4575, 1, 4, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かい…\nこういう憩いの\nひと時こそ、大事に\nしたいものですわね", 3, 4576, 1, 5, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この奥深い味わい…\n何か隠し味など\n使われていまして？", 3, 4578, 1, 7, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマス料理の\nレシピも、\nこれだけあると\n迷ってしまいますわね", 3, 4579, 1, 8, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この絵本、とっても\n面白いつくりですわね\nうちの商品に\nしたいぐらいですわ", 3, 4581, 1, 14, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これだけ大きな\n着ぐるみ…\n職人の技術が\n光りますわね", 3, 4582, 1, 15, 1, 114401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスといえば\nパーティーよね！\nいっぱい飲むわよ～♪", 1, 4583, 1, 1, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私を麦しゅわだけの\n女と思ったら\n大間違いなんだから♪", 1, 4584, 1, 2, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスらしい\n飲み物も結構いいわね\n私も今度\n作ってみようかしら", 1, 4585, 1, 3, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かい部屋で飲む\n麦しゅわも\nまた格別なのよね…", 1, 4586, 1, 4, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はオフの日だし\n朝から飲んでも\n怒られないわよね？", 1, 4587, 1, 5, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスの\nデートスポットで\n彼と一緒に…ってなに\n考えてるのユカリ！？", 1, 4588, 1, 101, 4, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("背伸びしなくても\nありのままの自分を\n受け入れてくれるって\nすごく…幸せ…", 1, 4589, 1, 102, 8, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大丈夫よ～\n飲んでない\n飲んでないひゃら～", 2, 4590, 1, 1, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスは\n特別だもの\n特別な一杯を\n飲まないとね♪", 2, 4591, 1, 2, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリークリスマース！\nほらほらぁ\n乾杯しましょ♪", 2, 4592, 1, 3, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉さんの\n頼れるところ\n見せてあげるわね", 2, 4593, 1, 4, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何かあったら\n頼ってくれても\nいいんだからね？", 2, 4594, 1, 101, 4, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ…これからも\nキミのこと…\n頼りにしちゃうからね", 2, 4595, 1, 102, 8, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さわやかな朝ね\n…二日酔いがないと\n朝ってこんなに\n気持ちいいのね", 2, 4596, 1, 1, 1, 114601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼間から飲むのって\nまた格別よね…って\nガマン、ガマンよ…", 2, 4597, 1, 2, 1, 114601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間かあ…\nあとは寝るだけだし\nちょっとくらいは…", 2, 4598, 1, 3, 1, 114601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ゴロゴロするのって\n最高ね～\nあとは麦しゅわが\nあればなぁ", 3, 4600, 1, 2, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私だって…\nかわいいものは\n好きでいいわよね？", 3, 4601, 1, 3, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んっ～…いい香りね\n日頃の疲れが\n取れる気がするわ", 3, 4602, 1, 4, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ポカポカする～\n…なんだかのどが\nかわいてきたわね", 3, 4603, 1, 5, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…労働の\n後のご飯はやっぱり\nおいしいわぁ…", 3, 4605, 1, 7, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスデート\n完全攻略マニュアル？\n…読んでおかなくちゃ", 3, 4606, 1, 8, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら、絵が飛び出して\n見えるけど…\n酔っ払ってるせいじゃ\nないわよね…？", 3, 4608, 1, 14, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい手触りね～\nウチにもほしいけど\n麦しゅわをこぼしたら\n大変そうだわ…", 3, 4609, 1, 15, 1, 114601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイの視線\nずっと独り占め\nしてたいな～", 1, 4610, 1, 103, 12, 101601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイといるだけで\nうち、おに楽しいし！\nヒデサイもっしょ～？", 2, 4611, 1, 103, 12, 101601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリークリスマス！\nふふ、口にするだけで\n何だか楽しくなるわね", 1, 4612, 1, 1, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもは子どもたちを\n見守る方だけど\n今ははしゃいでも\nいいわよね？", 1, 4613, 1, 2, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ツリーや料理\nそしてプレゼント！\nいくつになっても\nやっぱり心躍るわね♪", 1, 4614, 1, 3, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("飾り付けも料理も\nいいセンスしてるわね\n救護院のパーティーの\n参考にさせてもらうわ", 1, 4615, 1, 4, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("焼きそばパンを\nクリスマスの定番に\nするにはどうすれば…", 1, 4616, 1, 5, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ、あいつの\n好きそうな料理だわ\n取っといて食べさせて\nあげようかしら♪", 1, 4617, 1, 101, 4, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつのプレゼント\nちょっとだけ奮発\nしたのよね…\n喜んでくれるかしら", 1, 4618, 1, 102, 8, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このドレス\n似合ってるかしら？\n今だけは見とれても\n許してあげるわ♪", 2, 4619, 1, 1, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見て、このケーキ！\nおいしそうでしょ\nたまにはこんな贅沢も\nいいわよね♪", 2, 4620, 1, 2, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("料理も飲み物も\nおいしいわね！\nいっぱい食べて\n元を取らないと♪", 2, 4621, 1, 3, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("子どもたちと一緒に\n雪遊び、楽しそうね\nあんたもどう？", 2, 4622, 1, 4, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくの\nクリスマスなんだもの\nエスコート\nよろしくね♪", 2, 4623, 1, 101, 4, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寒い？　そう…\nなら、もっとこっち\n来ていいわよ…？", 2, 4624, 1, 102, 8, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほら、早く起きて？\nパーティー用の\n買い出しに\n付き合ってちょうだい", 2, 4625, 1, 1, 1, 114501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パーティーの料理の\n準備をしながらお昼も\n作っておいたわ\n我ながらいい手際ね", 2, 4626, 1, 2, 1, 114501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にぎやかなパーティー\nもいいけど、聖夜の\n余韻を感じるのも\n結構素敵ね", 2, 4627, 1, 3, 1, 114501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい座り心地だわ～\n腕のいい職人の仕事ね\nうちでも扱いたいわ", 3, 4629, 1, 2, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい！\n子どもたちに\nプレゼントしたら\n喜んでくれるかも", 3, 4630, 1, 3, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("華やかな香りね\nクリスマスに\nピッタリだわ", 3, 4631, 1, 4, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寒い日にはやっぱり\nこれよね…\nはぁ、極楽極楽♪", 3, 4632, 1, 5, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んー、おいしいわ！\n焼きそばパン味の\nものも、作れない\nかしら？", 3, 4634, 1, 7, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまにはのんびり\n読書でも…なんだか\nラブロマンスばかりね\nクリスマスだから？", 3, 4635, 1, 8, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ、面白いわね！\n子どもたちの\nプレゼントに\nピッタリだわ", 3, 4637, 1, 14, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんないい毛並み\n初めて見るわ…\n一体どこで手に\n入るのかしら？", 3, 4638, 1, 15, 1, 114501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アタシもみんなと\n一緒に正月を\n楽しんでいいのか？", 1, 4639, 1, 1, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年こそ、もう少し\n身長が伸びます\nように…", 1, 4640, 1, 2, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("げっ！　お年玉が\n全然残ってないぞ！？\nそんな、嘘だろ…？", 1, 4641, 1, 3, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大勢で過ごす\n正月か…初めてだけど\n悪くないもんだな", 1, 4642, 1, 4, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んー…ここじゃ\n天楼覇断剣の\n出番はなさそうだな", 1, 4643, 1, 5, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイツらと作る\n戦い以外の思い出も\nもっと増やしたいな", 1, 4644, 1, 101, 4, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなに賑やかな\n正月は初めてだ\n…温かくて、いいな", 1, 4645, 1, 102, 8, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("記憶がなくったって\n楽しい思い出は\n新しく作れるよな？", 2, 4646, 1, 1, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早くでかけるぞ！\nアタシはもっと\n正月を楽しみたい！", 2, 4647, 1, 2, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なあ、オマエはもう\nノウェムって名前\n覚えてくれたよな？", 2, 4648, 1, 3, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服、アタシに\n似合ってるのか？\n…そっか。\nありがとな！", 2, 4649, 1, 4, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オマエらと見た朝日は\nきっと忘れないぞ！\n思い出ができたな！", 2, 4650, 1, 101, 4, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつかオクトーも\n一緒に、みんなで\n正月を過ごせたらな…", 2, 4651, 1, 102, 8, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝から元気だな！\nアタシもいっちょ\n見習ってみるか！", 2, 4652, 1, 1, 1, 114701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼飯は何にする？\n正月はうまいものが\n多くて迷うよな！", 2, 4653, 1, 2, 1, 114701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい夜だな！\nアタシと一緒に\n夜更かしを楽しむか？", 2, 4654, 1, 3, 1, 114701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月らしく、たまには\nゆっくりするのも\nいいかもな…", 3, 4656, 1, 2, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだ？\nオマエも初詣に\n行きたいのか？", 3, 4657, 1, 3, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すーはー…\n神殿のニオイがするな\nいい事ありそうだ！", 3, 4658, 1, 4, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コイツがあれば\nうまい魚が\n焼けそうだな…", 3, 4659, 1, 5, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ううー\n食べ過ぎて帯が\nきつくなってきたぞ…", 3, 4661, 1, 7, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おみくじって\n書いてあることが\nむずかしいんだよな…", 3, 4662, 1, 8, 1, 114701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("困ってる人は\nいないみたいだし…\nちょっとここで、\n特訓しようかな♪", 1, 4664, 1, 1, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("空が飛べるんだから\nもっとたくさんの人を\n助けにいけちゃう！\n…ここじゃ飛べないや", 1, 4665, 1, 2, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("炎の翼\nかっこいいなー！\nこれ、もっと大きく\nできないのかな？", 1, 4666, 1, 3, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱり変身すると\nお腹すくんだね…\n…今ならペコさんの\n食欲の理由が分かるよ", 1, 4667, 1, 4, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("色なんかは違うけど…\nマントがあるから\n騎士くんとお揃いに\nなったみたい♪", 1, 4668, 1, 5, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…騎士くんがいないと\nなんか調子でない…\n早く会いたいよぉ…", 1, 4669, 1, 101, 4, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この姿になると、\n騎士くんを近くに\n感じる…なんだろ\nドキドキしちゃう…", 1, 4670, 1, 102, 8, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士くん騎士くん！\n今大丈夫？\nトレーニングメニュー\n考えるの手伝って！", 2, 4671, 1, 1, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…うにゃっ！？\nこ、この姿になっても\n尻尾は触っちゃ\nダメー！", 2, 4672, 1, 2, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もしかして、この服が\n気になってるの？\nだったら、もっと\n近くで見ていいよ♪", 2, 4673, 1, 3, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、騎士くん！\n困ってる人がいないか\n見回りに行くんだけど\nついてきて欲しいな！", 2, 4674, 1, 4, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("耳に触りたいの？\nだったら頭もなでて！\nそしたら、好きなだけ\n触っていいよ♪", 2, 4675, 1, 101, 4, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…あたし、強くなって\n騎士くんを守るよ！\nだから…これからも\n一緒にいていい？", 2, 4676, 1, 102, 8, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっはよー！\nさあさあ騎士くん！\n今日も一緒に\nはりきっていこー♪", 2, 4677, 1, 1, 1, 180101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼、お昼～♪\n今日のご飯は何かな～\nあ、騎士くん！\n早くお昼食べ行こ！", 2, 4678, 1, 2, 1, 180101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もお疲れ様ー！\n騎士くん、あたしが\nマッサージしよっか？\n結構評判なんだよ！", 2, 4679, 1, 3, 1, 180101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うにゃぁ…\nこの気持ちよさ…\n溶けちゃいそう…\nにゃぁ…", 3, 4681, 1, 2, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、かわいい～\nこれ、なでなで\nしていいんだよね…？\nよしよし…♪", 3, 4682, 1, 3, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とってもいい香り！\n気分も落ち着くし、\n特訓の後なんかに\nいいかもー！", 3, 4683, 1, 4, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬくぬくだぁ…\nなんだか、\nふにゃふにゃに\nなっちゃうよぉ…", 3, 4684, 1, 5, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、おいひぃ…！\nこの姿になると\nお腹すくし、すっごく\n助かっちゃった！", 3, 4686, 1, 7, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本で勉強して、\nぶんぶりょーどーの\n超ウルトラヒヨリに\nなっちゃうぞー！", 3, 4687, 1, 8, 1, 180101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年もみんなで\nおいしいものを\nたくさん食べたいです", 1, 4689, 1, 1, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("挑戦は大切ですよね☆\nというわけで\nおせちに魔物を…", 1, 4690, 1, 2, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おせちは縁起物です！\n食べれば食べるほど\n幸せになるはずです！", 1, 4691, 1, 3, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べ物がたくさん\n入った福袋は\nないんでしょうか…？", 1, 4692, 1, 4, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("初詣で何を\nお願いしましょう…\n五穀豊穣？", 1, 4693, 1, 5, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ずっとこうして\n年の始まりを\n過ごしたいですね", 1, 4694, 1, 101, 4, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか二人きりで\n初日の出を\n見たいです", 1, 4695, 1, 102, 8, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お餅おかわりです！\nいくらでも\n食べられますよ！", 2, 4696, 1, 1, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おせちの食材を\n取りに行きませんか？\nいい運動です☆", 2, 4697, 1, 2, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("凧揚げって\n難しいですね～\n糸が絡まっちゃいます", 2, 4698, 1, 3, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一年の計は元旦にあり\n今年一年分の\n献立を作りましょう！", 2, 4699, 1, 4, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほらほら！\nもっと近くで着物を\n見ていいんですよ☆", 2, 4700, 1, 101, 4, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたはどんな\n初夢を見ましたか？\nわたしは…内緒です☆", 2, 4701, 1, 102, 8, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("年明けの朝は\n心なしか\n気持ちいいですね☆", 2, 4702, 1, 1, 1, 111801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お雑煮のあとは\nおしるこで\nおやつタイムです！", 2, 4703, 1, 2, 1, 111801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたたかくして\n幸せな初夢を\n見ましょうね", 2, 4704, 1, 3, 1, 111801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～屋台巡りを\n満喫しました☆\n一休み一休み", 3, 4706, 1, 2, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("縁起のいい\nぬいぐるみを並べて\n福を呼びましょう！", 3, 4707, 1, 3, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おしるこのアロマって\nないんでしょうか？\nそれなら作るしか…", 3, 4708, 1, 4, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここでお餅を\n焼いたらおいしく\nなりそうですね～♪", 3, 4709, 1, 5, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしすぎて\n食べる手が\n止まりません～", 3, 4711, 1, 7, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しいおせち料理の\nヒントは…なるほど…\nふむふむ…", 3, 4712, 1, 8, 1, 111801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんとあんな\n特訓やこんな特訓が\nしたいなぁ、えへへ♪", 1, 4714, 1, 103, 12, 100601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんに褒めて\nもらうと、身体が\nじぃーんと\n熱くなっちゃいます♪", 2, 4715, 1, 103, 12, 100601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見目麗しい衣装に\n身を包むのも\n悪い気分では\nありませんね", 1, 4716, 1, 1, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("縁起物で\n験を担ぐというのも\nたまにはよいでしょう", 1, 4717, 1, 2, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("非効率なので\nあまり行いませんが\n私も手料理くらいは\n作れるのですよ", 1, 4718, 1, 3, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("研究のためなら\n時に遠路を超え\n実地へ赴くことも\n必要なのです", 1, 4719, 1, 4, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トゥンヌスの\n突然変異…\n大いに興味を\nそそられますね", 1, 4720, 1, 5, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("漁師の技法も\n再現できたことで\nまた一つ、仮説が\n実証できました", 1, 4721, 1, 101, 4, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月くらいは\n私ものんびりしたい\n気持ちなのですよ\n意外ですか？", 1, 4722, 1, 102, 8, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("模倣に頼らずとも\n衣装に合わせた\n所作程度は\nできて当然です", 2, 4723, 1, 1, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お年玉の使い道は\n思いつきましたか\nゆっくり考えても\nいいのですよ", 2, 4724, 1, 2, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トランプでも花札でも\n相手をしましょう\n手心が必要なら\nいつでも言いなさい", 2, 4725, 1, 3, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("初詣でお祈りする\n内容ですか\n…ヒミツ、として\nおきましょう", 2, 4726, 1, 4, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私たちでオーマ中の\nトゥンヌスを\n釣り上げましょうか\n…冗談ですよ", 2, 4727, 1, 101, 4, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見返りを求めない願い\nそれは祈りに通じるの\nかもしれませんね", 2, 4728, 1, 102, 8, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…貴方がその眠たげな\n顔を洗ってくる間に、\n温かいお茶でも\n淹れておきましょう", 2, 4729, 1, 1, 1, 115001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さて、本格的に\n活動を再開します\n貴方も同行しなさい\n昼食は済みましたか？", 2, 4730, 1, 2, 1, 115001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私はもう少し\n作業を片付けてから\n寝ることにします\n早く眠りなさい", 2, 4731, 1, 3, 1, 115001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し休みます…\n時間が来たら\n起こすように", 3, 4733, 1, 2, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("贈り物を模倣して\n潜入…試してみる\n価値はありそうですね", 3, 4734, 1, 3, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("嗅覚から得られる\n情報量は侮れません\n動物の模倣において\n注意すべき点ですよ", 3, 4735, 1, 4, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("穏やかな炎による\nリラックス効果は\n本能によるものかも\nしれませんね", 3, 4736, 1, 5, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いかなる強者でも\n兵站、補給は\n必要なものです", 3, 4738, 1, 7, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あらゆる学問は\n完璧な模倣のための\n大きな礎となります", 3, 4739, 1, 8, 1, 115001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新たに得たこの力で\n仲間と目指す未来を\n切り拓いてみせます", 1, 4741, 1, 1, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここは、みなさまと…\nわたくしの\n帰る場所でございます", 1, 4742, 1, 2, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまも精霊の召喚を\n試してみますか？", 1, 4743, 1, 3, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さま、おこづかいは\n足りていますか？\n遠慮は無用ですよ", 1, 4744, 1, 4, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この装束をまとうと\n自然と背筋が伸びる\n思いがいたします", 1, 4745, 1, 5, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("進化した精霊に\n負けぬよう\n修行に励みます", 1, 4746, 1, 101, 4, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仲間たちといられる\nこの幸せが、末永く\n続きますように…", 1, 4747, 1, 102, 8, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまのお手手は\n大きくて温かいですね\nぎゅっぎゅっ…ふふ♪", 2, 4748, 1, 1, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度、主さまにも\n里に伝わる昔話を\nお話しいたしましょう", 2, 4749, 1, 2, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("里で採れた果物を\n持って参りました\n召し上がってください", 2, 4750, 1, 3, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("里のお土産を\nここのみなさまに\nお配りいたしましょう", 2, 4751, 1, 4, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仲間と囲む食卓…この\n温もりは、みなさまの\n心の温かさなのですね", 2, 4752, 1, 101, 4, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまに名前を\n呼んでいただくと\n心が温かくなります♪", 2, 4753, 1, 102, 8, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ…主さま\n寝癖がついて\nおりますよ？", 2, 4754, 1, 1, 1, 115501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日の昼食は\n里の伝統料理です\nお口に合うでしょうか", 2, 4755, 1, 2, 1, 115501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまが眠れるよう\n安らぎの風を…\nおやすみなさいませ", 2, 4756, 1, 3, 1, 115501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この癒し…\n主さまにも味わって\nいただきたい…", 3, 4758, 1, 2, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この愛らしさ…\n精霊たちと似たものを\n感じます…♪", 3, 4759, 1, 3, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("精霊よ…この安らぐ\n香りを、隅々まで\n届けてくださいまし", 3, 4760, 1, 4, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("瞑想するのに\nちょうどよい暖かさで\nございます", 3, 4761, 1, 5, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("進化した精霊を\n使役するためにも\nよく食べて体力を…！", 3, 4763, 1, 7, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("風の精霊について\nもっと詳しく知って\nおかなければ…", 3, 4764, 1, 8, 1, 115501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("儀式の時を思い出して\n精霊に呼びかける…\n出ておいで～♪", 1, 4766, 1, 1, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃうっ！　もう…\n急に背中を触るなんて\nいたずら好きな精霊に\n育てた覚えはないのに", 1, 4767, 1, 2, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("儀式用の衣装…\nあんまり激しい動きは\nできないよね…でも\n戦う時は気にしない！", 1, 4768, 1, 3, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうだ…精霊に\n騎士クンのそばで\n見守っていてって\n頼んでみようかな…", 1, 4769, 1, 4, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ、こうやって、\n楽しく精霊とお話し\nしていられる、平穏な\n日々が続くといいな", 1, 4770, 1, 5, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("き、きき、騎士クン！\nわたしと、あの…！\nうう…練習ですら\n上手く誘えないよぉ…", 1, 4771, 1, 101, 4, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、精霊が…\nふふ、応援ありがとう\nわたしの想い…いつか\n必ず伝えるね", 1, 4772, 1, 102, 8, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しく覚えた料理\n作ってみたんだけど\n騎士クンも食べない？", 2, 4773, 1, 1, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クン、\n疲れてない？\nわたしと精霊で\n治療するよ？", 2, 4774, 1, 2, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう、いたずらしない\n…騎士クン！？\nご、ごめんなさい！\n精霊だと思って！", 2, 4775, 1, 3, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クン！\n時間が合ったら、\n精霊と一緒に\nお話しない？", 2, 4776, 1, 4, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…こういう服着るの\n初めてなんだけど…\nえっ、かわいい…？\nあ、ありがとう…！", 2, 4777, 1, 101, 4, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("困ったことがあったら\n相談してね。わたし、\n騎士クンのためなら…\n色々できるよ、色々！", 2, 4778, 1, 102, 8, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう騎士クン！\n今からお外で\n瞑想するんだけど…\n騎士クンもどうかな？", 2, 4779, 1, 1, 1, 115601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼の時間だ\nご飯ならわたしが\n用意するから\nゆっくりしてて", 2, 4780, 1, 2, 1, 115601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間…\n騎士クン、はいどうぞ\n寝る前の温かいミルク\nぐっすり眠れるよ♪", 2, 4781, 1, 3, 1, 115601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…うん、落ち着く\n精霊との魔法で\nこんな風に誰かを\n安心させたいな", 3, 4783, 1, 2, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい…\n精霊も気に入ってる…\nそうだ、同じ物\n作ってあげようかな？", 3, 4784, 1, 3, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…これ、\nうちに置いたら、\nお母さん喜ぶかも！", 3, 4785, 1, 4, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかい…\nまるで誰かが\n抱きしめてくれた\nみたい…", 3, 4786, 1, 5, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自然の恵みに\n感謝して…\nいただきます♪", 3, 4788, 1, 7, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もっと精霊について\n勉強して、みんなを\n守れるように\nなりたいな…", 3, 4789, 1, 8, 1, 115601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイツといると胸が\nぎゅーっとなる…\nこれってもしかして…", 1, 4791, 1, 103, 12, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンタとならきっと\nどんなゲームでも…\nそ、その、たた、\n楽しいって思えるわ！", 2, 4792, 1, 103, 12, 102201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("色んな人と話したら\n記憶探しの手がかりが\n見つかるかも…？", 1, 4793, 1, 1, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイスクリームでも\n作ろうかしら？\nバニラにミントに…", 1, 4794, 1, 2, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ネビアに話しかけると\n逃げられるのよね…\nもう、襲わないのに…", 1, 4795, 1, 3, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「コッコロさん」、\n「コッコロさん」…\n…間違えないように…", 1, 4796, 1, 4, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近少し太ったかも？\nきっとおいしいもの、\n食べ過ぎね…", 1, 4797, 1, 5, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいると、\nとても落ち着くわ…\n自分の家、だものね", 1, 4798, 1, 101, 4, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなと一緒の時間、\nずっと記憶に残したい\n…そう思っているのよ", 1, 4799, 1, 102, 8, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドラゴン族って、\nそんなに珍しいの？\nあまり実感ないけど…", 2, 4800, 1, 1, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("料理、練習してるのよ\n…味見してもらえる？\n期待はしないでね", 2, 4801, 1, 2, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("頭を叩いたら、\n記憶が戻ったり\nしないかしら…？\nやらなくていいわよ？", 2, 4802, 1, 3, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("赤ちゃんみたいだった\n時のことは、忘れて…\nお願いだから…", 2, 4803, 1, 4, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃんっ！？\nし、しっぽを掴むのは\nダメよ？", 2, 4804, 1, 101, 4, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("記憶が戻っても…\n私は、あなたたちと\n一緒にいたいわ", 2, 4805, 1, 102, 8, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう。\n寝ぐせついてるわよ？\n…ふふっ、これでよし", 2, 4806, 1, 1, 1, 106401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろお昼かしら？\nおいしいごはんを、\nみんなで一緒に…ね", 2, 4807, 1, 2, 1, 106401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間ね。\nそろそろ休みましょ？\n…ふわぁ…", 2, 4808, 1, 3, 1, 106401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふか、ぎゅう～…\n…あっ、これはその…\nストレッチしててっ…", 3, 4810, 1, 2, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あまり、興味ないわ。\nけど…けど…\n…か、かわいい…", 3, 4811, 1, 3, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りね。\nとっても落ち着くわ…\n…っくしゅっ", 3, 4812, 1, 4, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冷やす方が得意だけど\nあったかいのも、\nキライじゃないのよ", 3, 4813, 1, 5, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("別に、食いしん坊\nじゃないのよ？\nでも、もう一口だけ…", 3, 4815, 1, 7, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん…なるほどね。\n勉強になるわ…", 3, 4816, 1, 8, 1, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着の探偵か…\nちょっと恥ずかしい\n気がしてきたよ…", 1, 4818, 1, 1, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("依頼があれば\n海でも山でも\n赴くさ！", 1, 4819, 1, 2, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今のうちに\n助手くんの秘密を…\nわ…私はなにをっ！？", 1, 4820, 1, 3, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休暇も時には必要さ\n海でゆっくりと…\nむっ？　事件の気配！", 1, 4821, 1, 4, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("探偵の秘密道具…\n水着だと隠す\n場所がない…！", 1, 4822, 1, 5, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ助手くんが\n現れる時間かな？\nふふっ、楽しみだね", 1, 4823, 1, 101, 4, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("真実は私と助手くん\n二人だからこそ\n解き明かせるのさ", 1, 4824, 1, 102, 8, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃああっ！？\nわ、私の不意を突く\nとは…やるね助手くん", 2, 4825, 1, 1, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さて、なにか気づいた\nことはあるかな？\n言ってごらん♪", 2, 4826, 1, 2, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この感触…分かった！\n助手くんだね！\nふふっ、やっぱり♪", 2, 4827, 1, 3, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着…どうかな？\n探偵らしさは\n残してるつもりだけど", 2, 4828, 1, 4, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん？　依頼かな？\n助手くんの頼みなら\nなんでもお安い御用さ", 2, 4829, 1, 101, 4, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("助手くん、私と海に\n行かないかな\n…事件じゃないよ？", 2, 4830, 1, 102, 8, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("珈琲でも淹れて\n目を覚ますとしよう\n一緒に飲むかい？", 2, 4831, 1, 1, 1, 115701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食は済ませた？\nなにを食べたか\n当ててあげよう！", 2, 4832, 1, 2, 1, 115701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜は謎が深まる時間…\n闇に覆い隠された真実\n必ず暴いてみせる！", 2, 4833, 1, 3, 1, 115701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さて、推理の時間だ\n…サボってないよ？\n考えてるんだからね？", 3, 4835, 1, 2, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これはもしや、中に\n秘密のメッセージが？\n…かわいいだけだね", 3, 4836, 1, 3, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ、なんだか\n頭がスッキリするね\n…閃いた！", 3, 4837, 1, 4, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ポカポカするね…\n助手くん\n君もおいでよ", 3, 4838, 1, 5, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はむ、はむ…んぐっ\nた、食べてるところを\n見つめられると～…", 3, 4840, 1, 7, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("秘密の依頼とか\nこういう場所に\n隠したりするよね…♪", 3, 4841, 1, 8, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これはいい乗り心地だ\n事件現場にこれで登場\n…は、やめておこう", 3, 4843, 1, 10, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("不思議な感触だね…\nでも、いい発想が\n生まれてきそうだ…♪", 3, 4844, 1, 11, 1, 115701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これはあたしが\n前へ進むために\nあいつがくれた\n大切な力…！", 1, 4845, 1, 1, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("チェンジ・\nプリンセスフォーム！\n練習練習、っと", 1, 4846, 1, 2, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうあいつに助けて\nもらいっぱなしの\nあたしは…\n卒業しなきゃね", 1, 4847, 1, 3, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気ままに、お気楽に\nあいつと冒険する…\nそれって幸せよね", 1, 4848, 1, 4, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プリンセスフォーム…\nお姫様みたいね\nあたしがお姫様か…\nそっかぁ…ふふ♪", 1, 4849, 1, 5, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつと繋がって\n生まれたこの絆は\nあたしの宝物だわ", 1, 4850, 1, 101, 4, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしの命の使い方…\n全て受け止めてくれた\nあいつにだったら…", 1, 4851, 1, 102, 8, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ～ん♪\nプリンセスフォームの\n天才魔法使い\nキャル様に用かしら？", 2, 4852, 1, 1, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これからは\nあたしの力で\nなんでもパパっと\n解決してあげるわね！", 2, 4853, 1, 2, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔力がみなぎってる…\nねえ、もしかして\n今のあたしって本気で\nすごいんじゃない？", 2, 4854, 1, 3, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変身の反動で\nお腹が空いても\n魔物料理だけは\nいやだからね！？", 2, 4855, 1, 4, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇ、あんたになら\nあたしの心…\n全部預けていいかも", 2, 4856, 1, 101, 4, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつと一緒に\nいられたら、他には\n何も…って、あああ\nあんたいつの間に！？", 2, 4857, 1, 102, 8, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早起きも悪くないわね\n読みかけの魔導書\n今のうちに\n読んじゃおうかしら", 2, 4858, 1, 1, 1, 180601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇ～お腹すいたー\nあんたなんか\n作りなさいよ\n魔物料理以外でね！", 2, 4859, 1, 2, 1, 180601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁぁ…眠すぎて\n今なら変身しても\nお腹が減らない\n自信があるわ…", 2, 4860, 1, 3, 1, 180601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あー♪　最っ高！\n休んで魔力を高めて…\nあいつの役に\n立ってあげなきゃね", 3, 4862, 1, 2, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なにこれかわいい…！\nコレクションにしたく\nなっちゃうじゃない", 3, 4863, 1, 3, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り…すごく\nリラックスできるわ…\nあ、いい感じの魔法\n思いついちゃったかも", 3, 4864, 1, 4, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかい…\n落ち着くわ…\nあいつの手の\nぬくもりみたいね", 3, 4865, 1, 5, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プリンセスフォーム…\nこ、こんなに\nお腹が減るのね\n甘く見てたわ…！", 3, 4867, 1, 7, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ま、魔物料理の本！？\n誰よこんな本\n買ったの！　って…\n一人しかいないか", 3, 4868, 1, 8, 1, 180601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("憧れの舞踏会…\n私、きちんと\n踊れるかしら", 1, 4870, 1, 1, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アン・ドゥ・トロワ\nアン・ドゥ・トロワ\n練習はばっちりね♪", 1, 4871, 1, 2, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなにすてきな\nドレスを着られて\n本当に夢みたいだわ♪", 1, 4872, 1, 3, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法はいつか解ける…\nでも、その時間は心に\n残り続けるわ♪", 1, 4873, 1, 4, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ガラスの靴は夢へ\n踏み出す魔法の道具…\n私、がんばっちゃう！", 1, 4874, 1, 5, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("舞踏会であなたと\n一緒に踊れたら\nいいのにな", 1, 4875, 1, 101, 4, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("舞踏会に行く前に\n運命の王子様には\n出会ってるのよね", 1, 4876, 1, 102, 8, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうかしら？\n私、きちんとドレス\n着られてる？", 2, 4877, 1, 1, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたも一緒に\n踊ってみる？\nしゃなりしゃなり♪", 2, 4878, 1, 2, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたにエスコート\nされてきれいなお城を\n歩いてみたいわ♪", 2, 4879, 1, 3, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どう？　レッスンの\n成果はきちんと\n出てるかしら？", 2, 4880, 1, 4, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたが隣にいれば\n私も立派なお姫様に\n見えるかしら♪", 2, 4881, 1, 101, 4, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私にとって\n一番の魔法はあなたが\nくれる勇気よ♪", 2, 4882, 1, 102, 8, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さぁ！　今日も一日\n立派な淑女を目指して\nいきましょう♪", 2, 4883, 1, 1, 1, 115801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ごはん代わりに\nメタモルアップルを\n食べておきましょう", 2, 4884, 1, 2, 1, 115801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ魔法が解ける\n時間…でも淑女の\n心得は忘れないわ♪", 2, 4885, 1, 3, 1, 115801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("淑女にも休息は\n必要よね…少しだけ\n休ませてもらおっと", 3, 4887, 1, 2, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいものに\n囲まれた部屋も\n女の子の夢よね…", 3, 4888, 1, 3, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すてきな香り…\nお花かしら？\n森で探してみようかな", 3, 4889, 1, 4, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かい…暖炉のそばで\nおとぎ話を聞くのも\nいいわよね♪", 3, 4890, 1, 5, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッスンのために\n栄養補給して\nおかないと！", 3, 4892, 1, 7, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("教養を身に着ける\nことも大切よね！\nなになに…", 3, 4893, 1, 8, 1, 115801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("や、やっぱスカートは\n落ち着かねえな…\nなんか、\nスースーするしよ…", 1, 4895, 1, 1, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくこんな格好\nしてるし、いつもとは\n違う剣術の訓練を\nしてみるかな", 1, 4896, 1, 2, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さて、他の連中が\n帰ってくる前に、\nなんか料理でも\n作っといてやるか", 1, 4897, 1, 3, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こ、こんな服着てる\nわけだし、紅茶とか\n楽しんじゃっても\n変じゃないよな！", 1, 4898, 1, 4, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇だし運動でも…\nあ、あぶねえ！\nスカートなの忘れてた\n…誰も見てねえよな？", 1, 4899, 1, 5, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("紅茶が切れてるな…\nよし、あいつと一緒に\n買い物にでも行くか♪", 1, 4900, 1, 101, 4, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…あいつがいねえと、\nつまんねえな…ったく\n飯用意してやるから、\n早く帰ってこいよな…", 1, 4901, 1, 102, 8, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、あんまり\nジロジロ見んなよ\n…結構、\n恥ずかしいんだからな", 2, 4902, 1, 1, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ダンスの相手は\n無理だが、\n剣の訓練なら\nいつでも付き合うぜ！", 2, 4903, 1, 2, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服に\n触りたいのか？\nすごい作りだし、\n気持ちは分かるぜ", 2, 4904, 1, 3, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、いいところに！\nクッキーを焼く\nところだったんだが、\nおまえも食うか？", 2, 4905, 1, 4, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おまえにもこういう服\n似合うんじゃねえか？\n今度あたしが\n選んでやるよ♪", 2, 4906, 1, 101, 4, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…おまえの前でなら、\nこういう格好を\nすんのも…\nな、なんでもねえよ！", 2, 4907, 1, 102, 8, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝の訓練を始めるか\n時間あるなら、\nおまえも付き合えよな", 2, 4908, 1, 1, 1, 115901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間か…\n昼飯作るけど、\nなんか\n食いたいものあるか？", 2, 4909, 1, 2, 1, 115901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眠れないなら、\nホットミルク飲むか？\n体あったまって、\n眠くなると思うぜ", 2, 4910, 1, 3, 1, 115901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと休憩して…\nおっと、服にしわが\nできないように\nしねえとな", 3, 4912, 1, 2, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("だ、誰も\n見てねえよな？\n…よ～しよしよし、\nかわいいなおまえー♪", 3, 4913, 1, 3, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すげぇいい香りだな\nうちの居酒屋にも…\nいや、合わねえか", 3, 4914, 1, 4, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったけぇ…\nちょっとだけなら、\n寝ちまっても\nいいよな…？", 3, 4915, 1, 5, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これうめえな！\nたぶん材料は…よし！\nあたしも作ってみるか", 3, 4917, 1, 7, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本は…\n誰でも分かる作法…か\n最低限このぐらいは\n勉強しとくか…", 3, 4918, 1, 8, 1, 115901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミがおとなに\nなっても\nおにいちゃんとは\nずーっといっしょ♪", 1, 4920, 1, 103, 12, 102001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミとくべつなだっこ\nしてほしいな…うん！\nおひめさまだっこ～♪", 2, 4921, 1, 103, 12, 102001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はにいちゃんに\nどんなイタズラしよう\n早く会いたいな～", 1, 4922, 1, 103, 12, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミソギの特別な\nイタズラ見てくれる？\nいいよねっ♪", 2, 4923, 1, 103, 12, 100401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大人になったら、\nあの人と何しようかな\n…楽しみだなぁ", 1, 4924, 1, 103, 12, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("頭を撫でないで\nください！　もう、\n少しだけ、ですからね", 2, 4925, 1, 103, 12, 103601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くるくる〜♪\nうちのドレス\nかわええなぁ", 1, 4926, 1, 1, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日差しは苦手やけど\nたまにはひなたの下で\nぽかぽかしたいわぁ", 1, 4927, 1, 2, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外はお花が咲いてる\n久しぶりにお花を\n活けたいなぁ", 1, 4928, 1, 3, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お花をたくさん集めて\nギルドハウスに飾れば\n喜んでくれはるかな", 1, 4929, 1, 4, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたたかい日は\n紅茶を飲みながら\nゆっくりしたいなぁ", 1, 4930, 1, 5, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お稽古事を始めるなら\nうちに言ってな\nどんなことも教えたる", 1, 4931, 1, 101, 4, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちにいろんな夢を\n見せてくれはって\nほんま、おおきにな♪", 1, 4932, 1, 102, 8, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はん\n一緒におとぎの国へ\nお散歩にいきまひょ♪", 2, 4933, 1, 1, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふんふんふ〜ん♪\n今な、王子はんに\n花冠を作ってるんよ", 2, 4934, 1, 2, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんは\nお菓子好きどす？\nうち、作りますわ", 2, 4935, 1, 3, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん。ドレスの柄は\nお花とお星さま\nどっちにしまひょか", 2, 4936, 1, 4, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんとの\n思い出が増えるたび\nうちの宝物も増えます", 2, 4937, 1, 101, 4, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんと一緒なら\nどんな場所でも\n夢の国になりますわ", 2, 4938, 1, 102, 8, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夢の中におりたいけど\n王子はんに会いたくて\n起きてもうたわ♪", 2, 4939, 1, 1, 1, 116001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はん一緒に\nアフタヌーンティー\nいかがやろか？", 2, 4940, 1, 2, 1, 116001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の舞踏会…\n夢が広がるわぁ\nもちろんお相手は…♪", 2, 4941, 1, 3, 1, 116001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわふわや〜\nなんや心地よぉて\n眠ってしまいそうや…", 3, 4943, 1, 2, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かいらしいなぁ\n新しいお洋服でも\n作ってあげまひょか♪", 3, 4944, 1, 3, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お花やろうか…\nリラックスできて\nええ香りやねぇ", 3, 4945, 1, 4, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういう場所で\n絵本を読むと\n気分が出てええなぁ♪", 3, 4946, 1, 5, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("舞踏会を楽しむなら\nたくさん食べて\nたくさん踊りまひょ", 3, 4948, 1, 7, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うち、この本好きや\n王子さまと結ばれる\nお姫さまのお話なんよ", 3, 4949, 1, 8, 1, 116001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ、宿題めんどい…\nこれは楽しくない…\nこんな青春いらない…", 1, 4951, 1, 1, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("奨学金の道は遠いなぁ\nメルクリちゃんたちが\nお金くれればいいのに", 1, 4952, 1, 2, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アオイちゃん元気かな\nチエルに会いたくて\n泣いてるんだろうな…", 1, 4953, 1, 3, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇だし鏡でも見るか…\nうわ、顔良っ！\nえ誰この超絶美少女！", 1, 4954, 1, 4, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワンツーワンツー♪\nうーん…カルミナの\n振りコピ難しいにゃー", 1, 4955, 1, 5, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩も運動してます？\nチエルが一緒に走って\nあげてもいいですよ？", 1, 4956, 1, 101, 4, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("来年のテレフェスも\n今から楽しみだなあ…\nまた一緒にお化け屋敷\n入ってくださいね", 1, 4957, 1, 102, 8, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちぇる～ん☆\nフェス仕様でも\nかわいいちえるん！", 2, 4958, 1, 1, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いま話しかけないで！\n来年の聖学祭ライブの\nイメトレ中なんです！", 2, 4959, 1, 2, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クロエ先輩のウェア姿\nめっちゃカッコよ！\n思わずおへそ触ったら\nぶたれましたけど", 2, 4960, 1, 3, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ユニ先輩の体操着姿…\nあれはあれで実に良き\n一生見てられますよね", 2, 4961, 1, 4, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩って体操着持って\nないんですか？　ハ？\nチエルのを貸せと…？\nえっ…変態かな？", 2, 4962, 1, 101, 4, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("テレフェスでは先輩も\n地味に頑張ってました\nね。まあ格好よかった\nんじゃないですか…", 2, 4963, 1, 102, 8, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはちぇる～ん☆\nさあ今日も楽しいを\n探しに行きますよー！", 2, 4964, 1, 1, 1, 116301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩ビッグニュース！\n今からお昼ごはん\nおごらせてあげます！", 2, 4965, 1, 2, 1, 116301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんばんちぇるるん☆\nさあ朝まで楽しいを\n探しに行きますよー！", 2, 4966, 1, 3, 1, 116301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…ふかふか～…\n運動の後は…眠たく…\nなり…ま…", 3, 4968, 1, 2, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ユニ先輩に似合いそ！\nいやクロエ先輩かな？\nチエルは当然すぎて…", 3, 4969, 1, 3, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やん、いい香り～！\nまるでチエルのために\n存在するみたい！", 3, 4970, 1, 4, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この火を使って\n聖火リレーしましょう\n先輩、一本抜いて！", 3, 4971, 1, 5, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あむあむ…ちゃんと\n食べないとユニ先輩\nみたいになっちゃう！", 3, 4973, 1, 7, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…ちゃんと\n読まないとクロエ先輩\nみたいになっちゃう！", 3, 4974, 1, 8, 1, 116301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今なら書ける気がする\n私の本当の\n想いを込めた\nラブソングを！", 1, 4976, 1, 103, 12, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("輝きを増した私を\nいっぱい見てね！\n…ちょ、ちょっと\n見つめすぎだよ！", 2, 4977, 1, 103, 12, 102901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("テレフェスかぁー…\nあんまいい記憶ないな\nよし、忘れとこ", 1, 4978, 1, 1, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇だし鏡でも見るか…\nふふ～ん…いいじゃん\nあ？　何見てんだコラ", 1, 4979, 1, 2, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワンツー、ワンツー♪\nああクソ、難しいな…\nあ？　何見てんだコラ", 1, 4980, 1, 3, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アオイ元気してるかな\nまた絶叫したり白目\n剥いたりしてんのかな", 1, 4981, 1, 4, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミフユねえさんが\nバイトリーダーしてる\n工場…うちも行くか…", 1, 4982, 1, 5, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん…今日の晩御飯\n何にすっかなァ…\nあんたも食べてく？", 1, 4983, 1, 101, 4, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("来年のテレフェスは\nどーなンだかねえ？\nま、一緒にまた弟の\n相手してやってよ", 1, 4984, 1, 102, 8, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体操着なんてフツーに\n着てもつまんないし？\nその辺センス出るよね", 2, 4985, 1, 1, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("奨学金の道、遠くね？\nアキノ先輩と仲良く\nなった方が早いかも…", 2, 4986, 1, 2, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんた体操着は持って\nないの。ハ？　うちの\n貸せって？　いいけど\n…いや、よくねえよ", 2, 4987, 1, 3, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃんっ！\nや、だからさ…急に\n話しかけんなっての", 2, 4988, 1, 4, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え、なに？　この服？\nハ？　似合ってる？\n…え、聞こえなかった\nちょ、もっかい言って", 2, 4989, 1, 101, 4, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたもテレフェスで\n一応は頑張ってたよね\nま格好よかったんじゃ\nないの。知んないけど", 2, 4990, 1, 102, 8, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁ～あ…おはーす\n昨日も寝たの遅くて\nまだ目がショボだよ…", 2, 4991, 1, 1, 1, 116201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なに。あんた昼御飯\nまだなの。じゃ、うち\n適当になんか作ろうか", 2, 4992, 1, 2, 1, 116201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜っていいよね。色々\n見えすぎない感じとか\n…この話したっけ？", 2, 4993, 1, 3, 1, 116201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、ヤバ…運動の後に\nこのフカついたのは…\n秒でスヤれる…すやぁ", 3, 4995, 1, 2, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へーこんなんチエルに\n似合いそうじゃん。\n…いやユニ先輩かな？", 3, 4996, 1, 3, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、なんか良さげな\n香りじゃん。これは\n何の…いや分かんね", 3, 4997, 1, 4, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("熱ッ！　この野郎なに\n爆ぜてンだコラァ！\n濡らすぞ木、てめえ！", 3, 4998, 1, 5, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何コレよく分かんない\nけど、今日モヤシしか\n食ってないから助かる", 3, 5000, 1, 7, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日、体操着だしね。\n読書には逆アドかな。\nうん帰ろ。いやあ残念", 3, 5001, 1, 8, 1, 116201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビッグボス・イノリ様\nふっふっふ…\nしびれる響きです！", 1, 5003, 1, 1, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつかお兄さんを\nあたしの側近に\nしてやるですよ！", 1, 5004, 1, 2, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビッグボスになったら\nみんなからたくさん\nお菓子をもらうです！", 1, 5005, 1, 3, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふん！\nこの服はあたしにしか\n着こなせませんよ！", 1, 5006, 1, 4, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ばーんと立って\nどーんと腕を組む！\nこれがボスのポーズ！", 1, 5007, 1, 5, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イノリ様の側近に\n選ばれるなんて\n名誉なことですよ！", 1, 5008, 1, 101, 4, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("未来の側近として\nあたしをしっかり\n甘やかすですよ！", 1, 5009, 1, 102, 8, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしがお兄さんを\n立派なギャングに\nしてあげますからね！", 2, 5010, 1, 1, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("側近たるもの\nボスを甘やかなさいと\nだめですよ！", 2, 5011, 1, 2, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なに見てやがるです…\nくぅ、分かりました！\nお菓子は半分こです！", 2, 5012, 1, 3, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんも\nあたしがボスなら\nうれしいですよね！", 2, 5013, 1, 4, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんが側近なら\nあたしも安心して\n夜眠れるですよ！", 2, 5014, 1, 101, 4, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビッグボスになったら\nお兄さんにいい思い\nさせてあげますから！", 2, 5015, 1, 102, 8, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボスたるもの\n早起きは鉄則ですよ！\nふぁあ…", 2, 5016, 1, 1, 1, 116501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹が空きました…\nご飯食べにいきますよ", 2, 5017, 1, 2, 1, 116501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボスたるものぉ〜…\n夜更かしぐらい当然…\nぐー…", 2, 5018, 1, 3, 1, 116501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("は〜これは人をだめに\nしやがるやつですね\nあたし専用です", 3, 5020, 1, 2, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これはけしからん\nかわいらしさですね\nあたしにぴったりです", 3, 5021, 1, 3, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("高級な香りがするです\nボスになったら\n部屋に置いてやるです", 3, 5022, 1, 4, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいですねぇ\nちょっとこのまま\n一休憩です…", 3, 5023, 1, 5, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はむはむ♪\nボスたるもの食べねば\n戦はできませんよ！", 3, 5025, 1, 7, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボスなら経済書ぐらい\n…う。難しくて\n読めねーです…", 3, 5026, 1, 8, 1, 116501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたはドジな私を\n受け入れてくれる…\nだから、頑張れます！", 1, 5028, 1, 103, 12, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何でも仰ってください\nちょっぴり大胆な\nことでも…な～んて♪", 2, 5029, 1, 103, 12, 102501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あーあー、よし\nのどの調子もいいし\nはりきってガイド\nしてくるか！", 1, 5030, 1, 1, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さあ、そろそろ行くか\nガイドが\n遅刻したんじゃ\n話になんないからな", 1, 5031, 1, 2, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しれっとドラゴン族が\n旅行に来たり\nしてくれないかな", 1, 5032, 1, 3, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たぎるガイド先…\n火山、魔物の巣…\nダメだ、そんなとこ\nオレしか行けないや", 1, 5033, 1, 4, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この前行った絶景\nスポットよかったな\nキレイな景色を見る\nのもいいもんだぜ", 1, 5034, 1, 5, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、今日はカレと\n一緒か。なんだか\nやる気出てきたぜ！", 1, 5035, 1, 101, 4, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カレにガイドして\nもらったら\nどこに行っても\n楽しいだろうな", 1, 5036, 1, 102, 8, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よっしゃあ！\nどっちが上手く\nガイドできるか\n勝負しようぜ！", 2, 5037, 1, 1, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("飯でも食いがてら\nおススメの店の\n下調べでもしようぜ！", 2, 5038, 1, 2, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なかなかいいだろ？\nこの格好。キミも\n作ってもらったら\nどうだ？", 2, 5039, 1, 3, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("普通は行けない\n場所とか行きたいよな\nキミならどんな\nとこがいい？", 2, 5040, 1, 4, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ガイドの仕事は\nキミの方が得意そうだ\n参考にさせてもらうぜ\nよろしくな！", 2, 5041, 1, 101, 4, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミの探してきた店\n結構よさそうじゃん\nそうだ、今度二人で\n下見に行こうぜ！", 2, 5042, 1, 102, 8, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい朝だな。絶好の\n仕事日和だぜ！\n今日もよろしくな！", 2, 5043, 1, 1, 1, 116601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よし、昼飯にしよう\nこの後も激務だし\n飯抜きじゃあ\nぶっ倒れちまうからな", 2, 5044, 1, 2, 1, 116601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お疲れさん！　さーて\n次はオレと遊んで\nくれよ。まだまだ\nいけるだろ？", 2, 5045, 1, 3, 1, 116601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ガイドは一日\n歩きっぱなしだからな\nゆっくり休ませて\nもらうぜ", 3, 5047, 1, 2, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ、どこで\n売ってるんだろ？\n土産の情報も\n仕入れとかなきゃな", 3, 5048, 1, 3, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アロマとかよく\n分かんねえけど\n土産にはいいかもな\n覚えておくぜ", 3, 5049, 1, 4, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体が温まると心も\n熱くなるんだよな\nいい仕事が\nできそうだぜ", 3, 5050, 1, 5, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べ放題か\nこれはお客さんも\n喜んでくれそうだな！", 3, 5052, 1, 7, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へえ、こんなスポット\nあったんだ。やっぱ\nたまには勉強も\nしとくもんだな", 3, 5053, 1, 8, 1, 116601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("バイト先になじめる\nように笑顔の練習を！\nに、にへぇ〜…", 1, 5055, 1, 1, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("働いて働いて働いて\n…いつかその先に\nぼっちの出口が\n見えるのかも…！", 1, 5056, 1, 2, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("バイトのイメトレを\n始めます。ポーズを\n決めて…よし！\n角度を変えて…よし！", 1, 5057, 1, 3, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("バイト仲間に入る\nためには厳しい修業が\n必須と聞きました…！", 1, 5058, 1, 4, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんどん技術を磨いて\nバイト仲間として\n認めてもらうんです！\n目指せ職人技…！", 1, 5059, 1, 5, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人が応援して\nくれる…だから必ず\nバイト仲間の輪に\n入ってみせます…！", 1, 5060, 1, 101, 4, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人がいてくれると\n勇気が湧いてきます…\nぼっち卒業を夢見ても\nいいんだ、って…♪", 1, 5061, 1, 102, 8, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("緊張するけど\n思い切って声をかけて\nみます…バイト仲間に\n入るために…！", 2, 5062, 1, 1, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼっちの私が\nおもちゃ作りで\n人と共同作業…！\nか、感動です…！", 2, 5063, 1, 2, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("好きなおもちゃって\nありますか？　私は\nもちろんマイフレンド\nくんです！", 2, 5064, 1, 3, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私が作ったおもちゃも\n誰かの友達に\nなってたら\nいいなぁ…♪", 2, 5065, 1, 4, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も明日もバイト\nですね！　バイト\n仲間ができる日が\n楽しみです…♪", 2, 5066, 1, 101, 4, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("脱ぼっちを目指して\nこれからも一緒に\n頑張りましょう！\n目指せ、バイト仲間！", 2, 5067, 1, 102, 8, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n今日も気合いを入れて\nおもちゃ作りします！", 2, 5068, 1, 1, 1, 116701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランチの時間です…♪\nもちろん工場の隅で\nぼっち飯です…！", 2, 5069, 1, 2, 1, 116701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ…今日も\nお疲れさまでした\n明日も働きます～！", 2, 5070, 1, 3, 1, 116701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("バイトで頑張った日は\nふわふわの誘惑に\n勝てません…", 3, 5072, 1, 2, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうおもちゃの\nアイデアも\n素敵かも…♪", 3, 5073, 1, 3, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りがする\nおもちゃはどうかな…\n森の薬草を使って…", 3, 5074, 1, 4, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽかぽか…\n幸せなひとときですね", 3, 5075, 1, 5, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…たくさん\n食べて厳しいバイトを\n乗り切ります…！", 3, 5077, 1, 7, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…おもちゃの\n設計図を見るのも\n勉強になりますね！", 3, 5078, 1, 8, 1, 116701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("う～ん\n次はどんなたい焼きを\n作ろうかにゃぁ…", 1, 5080, 1, 1, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしが売る\nたい焼きには\n夢が詰まってるにゃ！", 1, 5081, 1, 2, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか絶対に\nたい焼き工場を\n建て直してみせるにゃ", 1, 5082, 1, 3, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまにたい焼き以外の\nおやつも食べるにゃ\nたとえば煮干しとか！", 1, 5083, 1, 4, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪い商売人がいたら\nファントムキャッツに\n知らせるにゃ！", 1, 5084, 1, 5, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミと一緒にいると\nたい焼きのアイデアが\n次々出てくるにゃ♪", 1, 5085, 1, 101, 4, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("出来ないことも\nキミと一緒にいれば\n出来る気がするにゃ♪", 1, 5086, 1, 102, 8, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんにゃ～？\nお姉さんにかまって\nほしいのかにゃ♪", 2, 5087, 1, 1, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミ、いいところに！\nあたしとライバル店へ\n視察にいくにゃ！", 2, 5088, 1, 2, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん…この匂い！\nたい焼き持ってるなら\nちょうだいにゃ♪", 2, 5089, 1, 3, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はどんなたい焼きを\n売ろうかにゃ～\nキミの案も欲しいにゃ", 2, 5090, 1, 4, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ファントムキャッツに\n相棒が必要にゃ\nたとえばキミとか…", 2, 5091, 1, 101, 4, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("相棒！\n…ってキミのこと\n呼んでいいかにゃ？", 2, 5092, 1, 102, 8, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早起きは三文の徳にゃ\n今日もたい焼き\n売れますよーににゃ！", 2, 5093, 1, 1, 1, 116801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹空いたにゃ…\n賄いのたい焼きを\nいただくにゃ！", 2, 5094, 1, 2, 1, 116801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("猫は夜が本番にゃ\nでもあたしは…\nふわぁ～眠いにゃ…", 2, 5095, 1, 3, 1, 116801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかにゃ～\nここで体を丸めて\n一眠りしたいにゃ", 3, 5097, 1, 2, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは…！\n猫にも負けない\nかわいさだにゃ…！", 3, 5098, 1, 3, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りにゃ～\nゴロゴロのどが\n鳴りそうだにゃ～", 3, 5099, 1, 4, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふにゃ～…\nこのまま働かずに\nまるまってたいにゃ…", 3, 5100, 1, 5, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("商売は戦いにゃ\nたくさん食べて\nたくさん働くにゃ！", 3, 5102, 1, 7, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ。たい焼きの\nアレンジレシピ集…\nためになるにゃ…", 3, 5103, 1, 8, 1, 116801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お芝居の前に\nお兄ちゃんの顔を\n見ると、とっても\n落ち着きますぅ…♪", 1, 5105, 1, 103, 12, 102101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんにもっと\n見てもらいたい…\nだから私…\n強くなりたいです…！", 2, 5106, 1, 103, 12, 102101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さらなる効率化で\nみんなといい仕事を\nしたいわね！", 1, 5107, 1, 1, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("他のバイトとの\nスケジュールを\n調整しないと…", 1, 5108, 1, 2, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時給がアップしたわ！\n働きが認められると\nやる気が出るわね", 1, 5109, 1, 3, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("効率的に動ければ\n業務を追加できる…\n燃えてきたわ！", 1, 5110, 1, 4, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("帳簿付けのコツ…\nユカリさんに教わって\nみようかしら", 1, 5111, 1, 5, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("バイトリーダーとして\nみんなをビシバシ\n鍛えていくわ！", 1, 5112, 1, 101, 4, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦いでもバイトでも\nキミなら安心して\n背中を預けられるわね", 1, 5113, 1, 102, 8, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたの？\n仕事のことなら\nなんでも相談してね！", 2, 5114, 1, 1, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さすがは私の弟子ね\nこれなら安心して\n仕事を任せられるわ", 2, 5115, 1, 2, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなのお手本になる\n働きぶりを見せないと\nいけないわね！", 2, 5116, 1, 3, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミのこと…もっと\n頼りにしちゃっても\nいいのかしら…？", 2, 5117, 1, 4, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、キミも一人前の\nバイト戦士として\n立派に成長したわね！", 2, 5118, 1, 101, 4, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しいおもちゃの\n企画書を作ってみたの\nちょっと見てくれる？", 2, 5119, 1, 102, 8, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝は一番効率がいい\n時間帯よ！\nバリバリ働くわよ！", 2, 5120, 1, 1, 1, 116901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さ、お昼に行きましょ\n今日の日替わり定食は\n何かしら…楽しみね♪", 2, 5121, 1, 2, 1, 116901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間…\nちゃんと寝て明日に\n備えなくちゃね", 2, 5122, 1, 3, 1, 116901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("適度な労働と休息の\nサイクルが最大効率を\n生み出すのよ…ふぅ…", 3, 5124, 1, 2, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～なんて素敵な\n抱き心地なのかしら…\n最高効率の癒やしね♪", 3, 5125, 1, 3, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("落ち着く香りね…\nなんだか集中力が\nアップした気がするわ", 3, 5126, 1, 4, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…癒されるわね…\n仕事のオンオフの\n切り替えは重要よね", 3, 5127, 1, 5, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("働くためには\nエネルギーをちゃんと\n摂っておかないと", 3, 5129, 1, 7, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("効率を上げるため\n生産管理の勉強も\nしておきたいわね", 3, 5130, 1, 8, 1, 116901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変身している間に\n色々と試しておこう\nまずは…", 1, 5132, 1, 1, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("飛べるというのは\n便利だな。料理が\n暖かいうちに\n持ち帰れる", 1, 5133, 1, 2, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プリンセスか…\n柄ではないけれど\n嫌な気はしないな", 1, 5134, 1, 3, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この力で\n何を成すべきなのか…\n剣に聞いてみよう", 1, 5135, 1, 4, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変身したとて私は私\n一時的に強くなろうと\n元が弱くてはだめだ", 1, 5136, 1, 5, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変身していない時でも\n彼がそばにいると\n力が湧いてくる…", 1, 5137, 1, 101, 4, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の思い…\nいつか伝えてみせるよ\n…きっといつか！", 1, 5138, 1, 102, 8, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何者かと戦うの？\nそれとも修行？\nどちらだとしても\n付き合うよ", 2, 5139, 1, 1, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変身し続けたら\nどれだけ空腹に…\n私は試さないからね？", 2, 5140, 1, 2, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本物のプリンセスに\nなるのは御免だが\nナイトがいて\nくれるのは頼もしいよ", 2, 5141, 1, 3, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつかこの力を\n誰かを救うために…\n戦い以外に使える時が\nくることを願うよ", 2, 5142, 1, 4, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミに感じてほしいな\n私に流れてくる\nキミからの力を…\nその…私の、思いも…", 2, 5143, 1, 101, 4, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("思いを告げる…\nそれがこんなにも\n難しいなんて…\nでも、いつか必ず…！", 2, 5144, 1, 102, 8, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！\nいい変身日和だ！\n…ふふっ、冗談だよ", 2, 5145, 1, 1, 1, 180301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもより多く\n昼食を用意しよう\n変身が解けたら大変だ", 2, 5146, 1, 2, 1, 180301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一日お疲れ様\n私もそろそろ変身を\n解いて休むとするよ", 2, 5147, 1, 3, 1, 180301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変身してしまうと\n動かずにいても\n空腹になるのかな…？", 3, 5149, 1, 2, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私もキミたちくらい\n可愛げがある姿に\nなっているかな？", 3, 5150, 1, 3, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("香りに対する感覚も\nいつもより鋭く\nなっているみたいだ…", 3, 5151, 1, 4, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ありがたいな\n少し足元が\n冷えていたところだ", 3, 5152, 1, 5, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは…！\n持ち運べるように\n改良できないかな？", 3, 5154, 1, 7, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("祖父に貰った\n技法書を読んで\n初心に帰ろう", 3, 5155, 1, 8, 1, 180301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最強の惚れ薬を作って\nあのおかたの心を\n私の思いのままに…", 1, 5157, 1, 1, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏といえば海にスイカ\n花火に水着…\nそして惚れ薬ですわ…", 1, 5158, 1, 2, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのおかたの心を\n手に入れるための\n準備を進めましょう\nこの夏こそ確実に…", 1, 5159, 1, 3, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのおかたに近づく\n虫どもを、どうやって\n片付けようかしら…\nまったく忌々しいこと", 1, 5160, 1, 4, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…クスクス\n薬の調合を考えるのは\n至福の時間ですわ…", 1, 5161, 1, 5, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのおかたの全てが\n早く私のものに\nなりますように…", 1, 5162, 1, 101, 4, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かき氷も花火も海も…\nあなた様がいてこそ…\nそう、あなた様は\n私の全てなのですわ", 1, 5163, 1, 102, 8, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("二人だけの夏を\n楽しみましょう…？\n…クスクス", 2, 5164, 1, 1, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら、あなた様\n私に秘密でどこに\n行こうとして\nいますの…？", 2, 5165, 1, 2, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に行きませんか？\nあなた様と一緒に\n過ごすには\n最高の場所ですから…", 2, 5166, 1, 3, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょうどいいところに\nいらっしゃいました\nできたての薬を…\nさぁどうぞ…クスクス", 2, 5167, 1, 4, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の海のきらめきも\nあなた様の存在が\nなければ色あせて\nしまいますわ…", 2, 5168, 1, 101, 4, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私とあなた様は\n結ばれる運命に\nあるのです…\n逃がしませんわ…", 2, 5169, 1, 102, 8, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("起きてすぐに会いに\n来てくださるなんて\nようやく私の伴侶たる\n自覚が…クスクス", 2, 5170, 1, 1, 1, 117001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お食事はまだですか？\n特製の薬草ランチを\n召し上がれ…クスクス", 2, 5171, 1, 2, 1, 117001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の夢を見られる薬を\n差し上げますわ…\nおやすみなさいませ\nあなた様…クスクス", 2, 5172, 1, 3, 1, 117001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい肌触りですわ…\n考え事にもぴったり\n眠くなるのが\n玉に瑕ですが…", 3, 5174, 1, 2, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういったものに\n揮発性の薬を仕込む\nのも一つの手ですわね", 3, 5175, 1, 3, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り…開発中の\n薬に使えそうな気が\nしますわ…クスクス", 3, 5176, 1, 4, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのおかたの\nぬくもりを\n思い出しますわ…", 3, 5177, 1, 5, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美味しい…この味なら\n薬を混ぜても違和感は\nなさそうですわ…", 3, 5179, 1, 7, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この薬の調合法…\n今度試してみましょう\nもちろんあのおかたに\n飲んでいただいて…", 3, 5180, 1, 8, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("二人乗りができると\nいいですわね…", 3, 5182, 1, 10, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかですわ…\nあのおかたの分も\n欲しくなります…", 3, 5183, 1, 11, 1, 117001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はキミと\nいつまでも歌って\n踊りたい気分さ～♪", 1, 5184, 1, 103, 12, 101701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あは～♪\nキミの隣は、故郷より\n落ち着くかも～…♪", 2, 5185, 1, 103, 12, 101701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この水着…\n一番に弟くんに\n見せたいな♪", 1, 5186, 1, 1, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんをこっそり\n海に運んで…\nサプライズしちゃお♪", 1, 5187, 1, 2, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもと違う髪型に\nしてみたけど…\n気に入ってくれるかな", 1, 5188, 1, 3, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海は楽しみだけど\n日焼けしないように\n気を付けなきゃね", 1, 5189, 1, 4, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだかな、弟くん\n水着のお姉ちゃんが\nお出迎えだよっ♪", 1, 5190, 1, 5, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海が見えるおうちで\n弟くんと一緒に\n暮らしたいなぁ～", 1, 5191, 1, 101, 4, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんの水着…\nどんな感じかなぁ\n…あ、想像してたら\nドキドキして…えへへ", 1, 5192, 1, 102, 8, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こーら、水着の\nお姉ちゃんは\nおさわり禁止♪\n…なんてね？", 2, 5193, 1, 1, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なぁに？\nふふっ、何回でも\n呼んでいいんだよ♪", 2, 5194, 1, 2, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海で迷子に\nならないように\n手を繋ごうね♪", 2, 5195, 1, 3, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんが\n海の楽しみ方を\n教えてあげるねっ！", 2, 5196, 1, 4, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ、弟くん\nどこ触ってるの？\nも～驚いちゃったぞ♪", 2, 5197, 1, 101, 4, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃん、海でも\nずっとキミを見てるよ\n…安心してね", 2, 5198, 1, 102, 8, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだ眠そうだね？\nほら、海が待ってるよ\n早く起きて起きて♪", 2, 5199, 1, 1, 1, 117101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大丈夫、疲れてない？\n海で遊び疲れた時は\n素直に休憩しようね", 2, 5200, 1, 2, 1, 117101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほら、早く寝ないと\n明日もお姉ちゃんと\n遊べないぞ♪", 2, 5201, 1, 3, 1, 117101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("だらけたお姉ちゃんは\n弟くんには\n見せられないな～", 3, 5203, 1, 2, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ、かわいいね♪\n弟くんが持つと\nもっとかわいいよっ♪", 3, 5204, 1, 3, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りだね…\n一味違うお姉ちゃんに\nなれそう…♪", 3, 5205, 1, 4, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったか～い♪\nほら、弟くんも\nおいでよ♪", 3, 5206, 1, 5, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よく食べて、いつでも\n弟くんの呼び声に\n応える準備を…！", 3, 5208, 1, 7, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんの水着の写真\nこの辺りに隠して\nおこうかな", 3, 5209, 1, 8, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子の背に乗って\nお姉ちゃんと弟くんの\n楽園へ…な～んて♪", 3, 5211, 1, 10, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海を感じる感触だね\n弟くんとの楽しい夏を\n思い出しちゃうな…♪", 3, 5212, 1, 11, 1, 117101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この夏、誰よりも\nキラキラしてみせる！\nだって私は\nアイドルだから！", 1, 5213, 1, 1, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日傘にアームカバー\n帽子にサングラス…\n紫外線対策は完璧！", 1, 5214, 1, 2, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とっておきの\nサマーソングを\nみんなに届けるよ！", 1, 5215, 1, 3, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんにもしないのって\n苦手かも…\n彼、早く来ないかな？", 1, 5216, 1, 4, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ラムネって\n夏って感じするよね\n後で彼と飲もっと♪", 1, 5217, 1, 5, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏は恋の季節！\n燃えるような恋…\nいつかしたいな", 1, 5218, 1, 101, 4, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年の夏の目標は\n…彼との思い出を\nいっぱい作ること！", 1, 5219, 1, 102, 8, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の水着写真集\n見てくれたんだ！\nどう、かわいかった？", 2, 5220, 1, 1, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スイカ割りしたいの？\nいいね、楽しそう！\nみんなも誘おうよ♪", 2, 5221, 1, 2, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇ、見て見て！\n水着の映える\nポーズ考えたんだ！", 2, 5222, 1, 3, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ライブ中に\n花火を打ち上げたら\n絶対盛り上がるよね！", 2, 5223, 1, 4, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近、忙しいけど…\nキミの顔見たら\n疲れなんて\n消えちゃった！", 2, 5224, 1, 101, 4, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この夏もいーっぱい\nドキドキさせるから！\n覚悟しててよね♪", 2, 5225, 1, 102, 8, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外は朝から暑いね\nけど、負けないから！\nお仕事、頑張るぞー！", 2, 5226, 1, 1, 1, 117201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自分へのご褒美に、\nアイス食べちゃお♪\nキミも一緒に食べよ！", 2, 5227, 1, 2, 1, 117201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の夜って\nワクワクするね♪\nホタル見に行こうよ！", 2, 5228, 1, 3, 1, 117201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ…眠い…\n仕事とかの疲れ、\nたまってるのかな…？", 3, 5230, 1, 2, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私のぬいぐるみが\nグッズになったら…\n彼にかわいがって\nもらえるかな？", 3, 5231, 1, 3, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り…\n夏限定のやつでしょ？\nいいセンスしてるね♪", 3, 5232, 1, 4, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑～い！\nけど…汗かいて\n気持ちいいかも！", 3, 5233, 1, 5, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッスンの後のご飯は\n特別おいしい♪\n…もうひとつだけ\n食べちゃおっかな", 3, 5235, 1, 7, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、この前撮影した\n水着グラビアだ\nうんうん、いい感じ！", 3, 5236, 1, 8, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子、もふもふだね\n触るのクセになりそう\nもふもふもふもふ…", 3, 5238, 1, 10, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わ、かわいい♪\n今度のグラビア撮影で\nこれ使ってもいい？", 3, 5239, 1, 11, 1, 117201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着っていいですよね\n海に浮かぶ一輪の花\nって感じがして！", 1, 5240, 1, 1, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自分の水着を作るのも\n誰かの水着を作るのも\n楽しいですね♪", 1, 5241, 1, 2, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着の最終チェック！\n伸縮性や動きやすさは\n…いい感じですね！", 1, 5242, 1, 3, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("振り付けや衣装作りに\n歌や踊りの練習…\n…やることがいっぱい", 1, 5243, 1, 4, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…レイ様の水着…\n私に作らせて\nもらえないかなぁ～…", 1, 5244, 1, 5, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんのことは\n気に入らないですけど\n別に嫌いという\nわけじゃなくて…", 1, 5245, 1, 101, 4, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さん暇そうですね\nに、荷物持ちとして\n誘ってみようかな…", 1, 5246, 1, 102, 8, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんいいところに\nこの衣装\nどう思います？", 2, 5247, 1, 1, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何見てるんですか？\nもしかしてこの水着の\n良さが分かります！？", 2, 5248, 1, 2, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("真夏でも涼しい…\nそれも水着の良さの\n一つですね", 2, 5249, 1, 3, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕立て屋も\nアイドルも\n諦めません！", 2, 5250, 1, 4, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏と言えば\nバカンスですけど…\n予定、あるんですか？", 2, 5251, 1, 101, 4, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("う～ん…騎士さんを\n海へ誘うには…って\nなんでもないですよ！", 2, 5252, 1, 102, 8, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふー…夏はやっぱり\n朝が一番過ごしやすい\nですね～！", 2, 5253, 1, 1, 1, 117401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑い時こそ海です！\n体力づくりのためにも\n泳ぎにいきますよ！", 2, 5254, 1, 2, 1, 117401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外で虫が鳴いてる…\n夏って感じがして\n風流ですねぇ…", 2, 5255, 1, 3, 1, 117401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し休憩です…\nこのまま寝ないよう\n気をつけないと…", 3, 5257, 1, 2, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、かわいい…！\nこの感動を次の\nステージ衣装にも…！", 3, 5258, 1, 3, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りですね～\n波の音が聞こえて\nきそうです…", 3, 5259, 1, 4, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳いだ後は\n少し寒いので\nちょうどいいですね", 3, 5260, 1, 5, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏バテしないように\n栄養はしっかり\n取らないと！", 3, 5262, 1, 7, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次のトレンドは…\nふむふむ、やっぱり\nこう来ましたか…", 3, 5263, 1, 8, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("デザインはもちろん\n触り心地も\n最高ですね♪", 3, 5265, 1, 10, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の撮影スポットに\n活用できそうですね\nさっそく衣装考えて…", 3, 5266, 1, 11, 1, 117401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ…♪\n団長さんが初めての\n友達で本当に良かった", 1, 5267, 1, 103, 12, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、団長さん！\n今日のＢＢ団の活動\nなんですけど…二人で\n大縄跳びしませんか！", 2, 5268, 1, 103, 12, 104001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この衣装で\nライブするのは\n恥ずかしいな…", 1, 5269, 1, 1, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくの夏だし\n肝試しに\n行ってみたいかも…", 1, 5270, 1, 2, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歌もダンスも\nより上を目指すために\n夏合宿をしよう…！", 1, 5271, 1, 3, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の暑さにも負けない\n熱いライブに\nしてみせる…！", 1, 5272, 1, 4, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新曲のアイデア\nまとめたいな…\n少し海辺を散歩しよう", 1, 5273, 1, 5, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かき氷、食べたいな\n…あの人は何味が\n好きなんだろう？", 1, 5274, 1, 101, 4, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着、似合ってるって\n言ってもらえるかな…", 1, 5275, 1, 102, 8, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サインして、ですか？\nいいですけど…\n少し照れますね…", 2, 5276, 1, 1, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し待ってください\n今、新曲の楽譜を\n書いているので…", 2, 5277, 1, 2, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんでしょう？\nもしかして…\nボイトレに興味が？", 2, 5278, 1, 3, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度のライブでは\n夏らしい爽やかな歌を\nファンにお届けします", 2, 5279, 1, 4, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…水鉄砲で遊ぼう？\nふふ。楽しそうですね\nお手柔らかに…♪", 2, 5280, 1, 101, 4, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの声を\n聴いていると、\n何だか落ち着きます…", 2, 5281, 1, 102, 8, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も暑くなりそう…\nお互いしっかりと\n水分補給しましょうね", 2, 5282, 1, 1, 1, 117301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹空きましたよね\n海の家で、\nなにか買ってきます", 2, 5283, 1, 2, 1, 117301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の海で月明かりと\n波の音を楽しもうかと\n…一緒に行きますか？", 2, 5284, 1, 3, 1, 117301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッスンだけでなく\nリラックスすることも\n大事、ですよね", 3, 5286, 1, 2, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、かわいい\n精霊も負けないくらい\nかわいいですけどね", 3, 5287, 1, 3, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏らしい爽やかで\nいい匂い…あなたに\nピッタリな香りですね", 3, 5288, 1, 4, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に入った後は、\n体が冷えてしまいます\n一緒に温まりましょう", 3, 5289, 1, 5, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイドルとして、\n食べすぎには\n気をつけないと…", 3, 5291, 1, 7, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏は恋の季節…\nガンガン攻めるべし…\nなるほど…", 3, 5292, 1, 8, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子に乗りながら\nライブをする…\nというのはどうですか", 3, 5294, 1, 10, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まるで人魚になった\n気分…なんて、ふふ", 3, 5295, 1, 11, 1, 117301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんとして\nシオリンにかっこいい\nとこ見せなくっちゃ☆", 1, 5296, 1, 1, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつかシオリンと\n一緒に空を飛んで\n空中散歩してみたいな", 1, 5297, 1, 2, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すこし眠くなってきた\nかも…シオリンと\nお昼寝しようかな", 1, 5298, 1, 3, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お散歩してこよっと！\nシオリンとお出かけ\nするのにいい場所\n探さなくっちゃ！", 1, 5299, 1, 4, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シオリンに過保護って\n言われちゃった…♪\nそれでも心配しちゃう\nのが姉心…だよね？", 1, 5300, 1, 5, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちいい日差し！\nシオリンと彼と、\nお昼寝したら\n気持ちよさそ～♪", 1, 5301, 1, 101, 4, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度天気がいい日には\nシオリンと彼を誘って\n一緒にお出かけ\nしたいな～♪", 1, 5302, 1, 102, 8, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はご機嫌なんだ♪\nだって、シオリンの\n調子がいいんだもん☆", 2, 5303, 1, 1, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今からシオリンと\nピクニックに\n行くんだ♪　そうだ！\nキミも一緒にどう？", 2, 5304, 1, 2, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ、びっくりした！\nシオリンから借りた本\n読むのに集中\nしてたから…", 2, 5305, 1, 3, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うん？　どうしたの？\nあっ、もしかして\nこの服、気になる？", 2, 5306, 1, 4, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シオリンもキミも元気\nいっぱいだと、私も\n元気になっちゃうよ☆", 2, 5307, 1, 101, 4, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シオリンの前だけ\nじゃなくて、キミにも\nかっこいい私の姿を\n見てほしいな☆", 2, 5308, 1, 102, 8, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！　えへへっ\n今日は早起きなんだ♪\nシオリンにかっこ悪い\nとこ見せたくないから", 2, 5309, 1, 1, 1, 118301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おなかすいたなぁ～…\nシオリンと一緒に\nおいしいもの食べに\n行こうかな！", 2, 5310, 1, 2, 1, 118301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間！？\nシオリンと一緒だと\n時間が早く\n過ぎていっちゃうね！", 2, 5311, 1, 3, 1, 118301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この快適な寝心地…！\nシオリンにもおすすめ\nしなきゃ…！", 3, 5313, 1, 2, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わあ、かわいい！\nそれにさわり心地も\nいいし、抱き枕に\nちょうどいいかも！", 3, 5314, 1, 3, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいにおい…♪\nなんだかリラックス\nできて…すやぁ…", 3, 5315, 1, 4, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽかぽか～☆\nシオリンと一緒に\nぬくぬくしたら\n気持ちよさそう♪", 3, 5316, 1, 5, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仲のいい人が一緒だと\nつい食が進んじゃうね\nえへへ…♪", 3, 5318, 1, 7, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…この本…\nシオリンが好きかも！\n今度おすすめしよっと", 3, 5319, 1, 8, 1, 118301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃん、\n私のために無理は\nしてないかな…？", 1, 5322, 1, 1, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しく買った絵本…\nこういうのなら\nお姉ちゃんと楽しく\n読めるよね", 1, 5323, 1, 2, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ニャットちゃんを\nここに連れてきて\nみんなで遊べないかな", 1, 5324, 1, 3, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本屋さんに行こうかな\nみんなで読める\n面白い本が\nあるといいなぁ", 1, 5325, 1, 4, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまには…読むだけ\nじゃなくて、自分で\nお話を書いて\nみようかな…？", 1, 5326, 1, 5, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時々…お姉ちゃんと\nあの人が似てるって\n思うことがあります…", 1, 5327, 1, 101, 4, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんとあの人…\n優しくて頼もしい\n二人に囲まれて…\n私、幸せ者だなぁ…", 1, 5328, 1, 102, 8, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうかしましたか？\nもしかして…あなたも\n一緒にこの本を\n読みたい…とか？", 2, 5329, 1, 1, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("けほっ…けほっ…\nあっ、心配いりません\n飲み物を飲んで\nむせただけですから", 2, 5330, 1, 2, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好…\n似合ってますか…？\nえへへ、照れますね…", 2, 5331, 1, 3, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なぁに、お姉ちゃん？\n…あっ、すみません\n読書に集中していて…\n間違えちゃいました…", 2, 5332, 1, 4, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃん、時々無理\nしちゃうから…\nあなたも一緒だと\n安心できます", 2, 5333, 1, 101, 4, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんとあなたと\n頼れる人に囲まれて\n私は幸せものですね", 2, 5334, 1, 102, 8, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだか朝から\n調子がいい…今日は\nいい日になりそうです", 2, 5335, 1, 1, 1, 118401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくだから、\nお姉ちゃんを誘って\nお外でランチも\nいいかも", 2, 5336, 1, 2, 1, 118401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんに心配\nかけないように…もう\nちょっと本を読んだら\n寝なくちゃね", 2, 5337, 1, 3, 1, 118401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふんわり柔らかくて\n気持ちいい手触り…\nお姉ちゃんが寝るのに\nちょうどよさそう", 3, 5339, 1, 2, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ、かわいい♪\n絵本の物語みたいに\nおしゃべりできない\nかな…？", 3, 5340, 1, 3, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵な落ち着く香り♪\nなんだかお姉ちゃん\nみたい、ふふっ", 3, 5341, 1, 4, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかくてほっと\nするなぁ\nここでゆっくり\n読書しようかな", 3, 5342, 1, 5, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この味…\nお姉ちゃんが好きそう\n少しもらって、\n持って行こうかな…？", 3, 5344, 1, 7, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本みたいな、\n心躍る大冒険も\nお姉ちゃんと一緒なら\nできちゃいそう", 3, 5345, 1, 8, 1, 118401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい部屋ね\nここを私の分院に\nするのもいいかも\nしれないわね…♪", 1, 5348, 1, 1, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("珍しいカンポーが\n手に入ったから\n色々試してみたいわ\n色々と、ね♪", 1, 5349, 1, 2, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服を着ると\n自分が医者だって\nより実感するわね\nまあ、闇医者だけどね", 1, 5350, 1, 3, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新薬開発のために\n薬草を採取して\nおこうかしら", 1, 5351, 1, 4, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつ急患が来ても\n対応できるように\nしておきましょうか", 1, 5352, 1, 5, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの子の研究資料も\nだいぶ増えてきたわね\nちゃんとまとめて\nおかないと♪", 1, 5353, 1, 101, 4, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの子は大事な\n研究対象。だから\nいつまでも健康で\nいてもらわないとね♪", 1, 5354, 1, 102, 8, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("薬に興味があるの？\nなら、今度ゆっくりと\n教えてあげるわね", 2, 5355, 1, 1, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し時間があいたから\n一緒に新薬の実験を\nしましょうか♪", 2, 5356, 1, 2, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたの？\nまさか急患…！？\nあら、違うのね\nならよかったわ", 2, 5357, 1, 3, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("具合が悪い時はすぐに\n言うのよ。君には\nいつでも健康でいて\nほしいから", 2, 5358, 1, 4, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し仮眠したいわね\n肩…いいえ、膝を\n貸してもらえる？", 2, 5359, 1, 101, 4, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまには…君の隣なら\n闇医者も悪い研究者も\nお休みにするのも\n悪くないわね♪", 2, 5360, 1, 102, 8, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまには朝の陽ざしを\n浴びるのも…\n悪くないわね", 2, 5361, 1, 1, 1, 117501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("天気がいい日は\nいい薬草が採れるの\n君も集めるの、\n手伝ってくれる？", 2, 5362, 1, 2, 1, 117501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いけない、もうこんな\n時間なのね\n診察に没頭すると\n時間感覚がなくなるわ", 2, 5363, 1, 3, 1, 117501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう少し固い方が\n私好みだけど…\n悪くない寝心地ね", 3, 5365, 1, 2, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このぬいぐるみ…\n闇医者として\n興味深いわね…", 3, 5366, 1, 3, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("落ち着く香りね\n私も診察室で\n使ってみようかしら", 3, 5367, 1, 4, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冷えは病につながるわ\nしっかり温めて\n体をいたわりましょ", 3, 5368, 1, 5, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしい♪\n研究のお供に\nもってこいの\n味だわ", 3, 5370, 1, 7, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("医学は日進月歩…\n闇医者とはいえ\n最新の論文には\n目を通しておかないと", 3, 5371, 1, 8, 1, 117501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("白衣の天使かあ\nまさにボクのための\n呼び方だね", 1, 5400, 1, 1, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美しさとは\n日々の努力が\n作るものなんだよ", 1, 5401, 1, 2, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大変だ…\nボクは美しく\nなりすぎたかも", 1, 5402, 1, 3, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクのかわいさで\n癒やされて\nみんな健康に\nなっちゃうね", 1, 5403, 1, 4, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんな服装をしても\nボクの美しさは\n変わらないね", 1, 5404, 1, 5, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これからはボクも\n美の伝道師として\nがんばらないとね♪", 1, 5405, 1, 101, 4, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクのかわいい笑顔を\n近くで見る以上の\n癒やしはないよね♪", 1, 5406, 1, 102, 8, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どう？　看護師姿の\nボクもかわいいでしょ\nもっと近くで見る？", 2, 5407, 1, 1, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほら！　美しいボクの\n看護師姿を見たら\n元気でちゃうでしょ？", 2, 5408, 1, 2, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("白衣の天使のボクも\n最高に美しいね\n存分に癒されてよ♪", 2, 5409, 1, 3, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("具合が悪いの？\nならボクの美しい顔を\n処方してあげる♪", 2, 5410, 1, 4, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さあ今日もボクと\n一緒に美の追求に\n付き合ってもらうよ♪", 2, 5411, 1, 101, 4, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい天使のボクが\nいつもそばにいるんだ\nキミって幸せ者だね♪", 2, 5412, 1, 102, 8, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さすがボク\n目が覚めるような\n美しさでしょ？", 2, 5413, 1, 1, 1, 117601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美は食で作られる\n美容にいいものを\n食べようよ！", 2, 5414, 1, 2, 1, 117601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふああ…早く寝よ？\n夜更かしは美容の\n大敵だからね", 2, 5415, 1, 3, 1, 117601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふう～…\nリラックスする\nボクも美しい", 3, 5417, 1, 2, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクが抱きしめると\n普段よりかわいく\n見えちゃうね♪", 3, 5418, 1, 3, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美しいボクは\n常にいい香りを\nしていなくちゃね", 3, 5419, 1, 4, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("光がボクを照らしてる\nんじゃなくて、ボクが\n光を輝かせてるのさ", 3, 5420, 1, 5, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("バランスのいい食事が\n美しいボクを\n作るのさ", 3, 5422, 1, 7, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…なるほど\nこうすればより美しく\nなれるかもしれない", 3, 5423, 1, 8, 1, 117601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仲間のためなら\nきっと…どこまでも\n強くなれるよね", 1, 5425, 1, 103, 12, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プリンセスフォーム？\n私と同じような力を\n持ってる人がいるの？\n会ってみたいな～！", 2, 5426, 1, 103, 12, 105701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここの空気は、\nどうもゆるすぎて…\n落ち着きませんわね", 1, 5427, 1, 1, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("陛下のお越しになる\n別宅としては、\n少し警備が\n甘すぎでは？", 1, 5428, 1, 2, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あらあら？\nサッシにホコリが！\nちょっとネコ助！\n掃除は念入りに！", 1, 5429, 1, 3, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつまで入り浸って\nいるのかと、\n秘書に叱られて\nしまいましたわ…", 1, 5430, 1, 4, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もういっそ、\nここに間借りして\n仕事しようかしら…？", 1, 5431, 1, 5, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("邪魔している身ですし\n家事くらい\nお手伝いさせなさいな", 1, 5432, 1, 101, 4, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本当は、意外と\n居心地が良いのかも…\n陛下の気持ち、\n少し分かりましたわ", 1, 5433, 1, 102, 8, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっ…わたくしを\n叩いても、ホコリなど\nあまり出ませんわよ！", 2, 5434, 1, 1, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("陛下っ？\nなんだ…貴方でしたの\n用件は手短にお願いね", 2, 5435, 1, 2, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("別に、好き嫌いは\nありませんけれど…\n魔物料理って、意外と\n美味なものですわね", 2, 5436, 1, 3, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("言っておきますけれど\nわたくしは商売人です\n荒事は専門外ですわよ", 2, 5437, 1, 4, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プリンセスナイトの\n能力…なにか儲け話に\n使えませんかしらね", 2, 5438, 1, 101, 4, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴方がたのことも、\n少しくらいは\n信用してないことも\nありませんでしてよ", 2, 5439, 1, 102, 8, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\nさ、今日もバリバリ\n働きますわよ！", 2, 5440, 1, 1, 1, 118001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ですわね\n栄養補給をしつつ\n働きますわよ！", 2, 5441, 1, 2, 1, 118001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("定時ですって？\n関係ありません！\nわたくし、まだまだ\n働きますわよ～っ！", 2, 5442, 1, 3, 1, 118001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うっ…いけませんわ\n日頃の疲れが…\nふわぁ…", 3, 5444, 1, 2, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もふもふ…ふふっ♪\n…なんですのっ、\nなにかおかしくて！？", 3, 5445, 1, 3, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りですわね\nわたくしの執務室にも\n置きたいくらいですわ", 3, 5446, 1, 4, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いけませんわ…\nこんなに暖かいと\n日頃の疲れが…ふわぁ", 3, 5447, 1, 5, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう一つ食べたら\n仕事に戻りますわよ？\nあと一つだけ…", 3, 5449, 1, 7, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("商人にとって\n知識は武器ですわ\n陛下のため、貴方も\nもっと勉強なさい？", 3, 5450, 1, 8, 1, 118001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("故郷のお菓子を\nいろいろ作ったんだ～\nみんなに\n配ってくるさ～♪", 1, 5452, 1, 1, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼ってどんな仮装が\n似合うかな～？\nシーサーとか？", 1, 5453, 1, 2, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カボチャチャンプルー\n作ってみよっと！\nきっとおいしいさ～♪", 1, 5454, 1, 3, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("視線を感じるさ～\nもしかして幽霊？\nおしゃべりするさ～♪", 1, 5455, 1, 4, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さっき作った\nサーターアンダギー、\n早く彼に\n食べてほしいさ～♪", 1, 5456, 1, 5, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼のために、\n特別なイタズラを\n考えとくさ～♪", 1, 5457, 1, 101, 4, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか彼と、\n故郷のハロウィンを\n楽しみたいさ～♪", 1, 5458, 1, 102, 8, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンは\n私たちが守るさ～♪\nさ、見回りに行こ！", 2, 5459, 1, 1, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この制服、\nハロウィンらしくて\n大好きさ～♪", 2, 5460, 1, 2, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イタズラする気ね～？\nどんなことされるのか\n楽しみさ～♪", 2, 5461, 1, 3, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カボチャのランタン、\n一緒に作ろ！\n絶対楽しいよ～♪", 2, 5462, 1, 4, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子くれるの？\nあは～、ありがとー♪\nもぐもぐ…\n優しい味がするさ～♪", 2, 5463, 1, 101, 4, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミと一緒に過ごす\nハロウィンは、\nドキドキとワクワクが\n止まらないさ～♪", 2, 5464, 1, 102, 8, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンは\n朝から大忙しさ～！\nお菓子作り、\n手伝ってほしいさ～", 2, 5465, 1, 1, 1, 117701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お化け屋敷に行こ！\n一緒にいっぱい\nドキドキしようね～♪", 2, 5466, 1, 2, 1, 117701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここからが\nハロウィン本番さ～！\n幽霊たちと\nいっぱい遊ぶさ～♪", 2, 5467, 1, 3, 1, 117701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと休んだら、\nお菓子作りを\n再開するさ～♪", 3, 5469, 1, 2, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("でーじかわいいね～♪\nこの子に仮装させたら\nきっと似合うさ～♪", 3, 5470, 1, 3, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子みたいに\n甘い匂い…\nハロウィンらしい\nいい香りさ～♪", 3, 5471, 1, 4, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルの秋って\n冷えるけど…\nこれがあれば\n体も心もぽかぽかさ～", 3, 5472, 1, 5, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("故郷のご飯も\nおいしいけど、\nこっちのご飯も\nでーじおいしいさ～♪", 3, 5474, 1, 7, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パンプキンパイの\nレシピは…なるほど～\n勉強になるさ～♪", 3, 5475, 1, 8, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("全部おいしそうで\nどれから食べるか\n迷っちゃうさ～♪", 3, 5477, 1, 12, 1, 117701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ムっ！　幽霊の気配を\n感じるデス！\nさあ姿を現すデス！", 1, 5479, 1, 1, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ムムム…\n妖魔の力を忍法に\n使えないでショウか…", 1, 5480, 1, 2, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("怪しい妖魔を\n成敗するデス！\nハロウィンの平和は\nワタシが守りマスよ！", 1, 5481, 1, 3, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワタシの祭囃子が\n聞こえマスかー？\nさあ集まるデース！\n陽気に踊りまショウ！", 1, 5482, 1, 4, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お祭りは\n楽しんだ者勝ちデス！\n踊らにゃ\nソンソンデス！", 1, 5483, 1, 5, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("幽霊になる前に\n天下統一を\n果たしたいデスね", 1, 5484, 1, 101, 4, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの世に行っても\nショーグンは\nワタシの大事な\nショーグンデス！", 1, 5485, 1, 102, 8, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグン！\n悪霊退治に\n出かけるデース！", 2, 5486, 1, 1, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("妖魔を家来に\nしてみるのは\nどうデス？", 2, 5487, 1, 2, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マントを使って\nウツセミの術の精度を\n高めるデス！", 2, 5488, 1, 3, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンにちなんだ\n新しい忍法…\nすなわち妖忍法の\n開発を急ぐデス！", 2, 5489, 1, 4, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの世でも\nショーグンに\nお仕えしマスよー！", 2, 5490, 1, 101, 4, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグンもワタシと\nハロウィンパレードを\n踊り明かしまセンか？", 2, 5491, 1, 102, 8, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございマス！\n天下統一に向けて\n急いで準備するデス！", 2, 5492, 1, 1, 1, 117801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹減ってまセンか？\nハロウィンスイーツで\n休憩するデ〜ス", 2, 5493, 1, 2, 1, 117801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜更かしすると幽霊が\nでるかもしれまセン…\nヒュ〜ドロロロ〜…", 2, 5494, 1, 3, 1, 117801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もふもふなところが\nわたあめちゃんに\n似ていマス。わんっ！", 3, 5496, 1, 2, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬいぐるみや人形には\n魂が宿るという\n言い伝えがありマス…\nマカフシギデ〜ス", 3, 5497, 1, 3, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ウ〜ム…\nなんとも怪しい\n香りがしマスね！", 3, 5498, 1, 4, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パレードの熱気に\n負けないくらい\n熱いデス！", 3, 5499, 1, 5, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ついつい食べすぎて\nしまうのは\n妖魔のせいデスか！？", 3, 5501, 1, 7, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トーゴク妖怪の\n図鑑デス！　個性的な\n妖怪ばかりデスね！", 3, 5502, 1, 8, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンの甘味を\n集めまシタよ！\nショーグンへの\n貢ぎ物デス！", 3, 5504, 1, 12, 1, 117801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼と二人で\n買い物に…って…\nこれってデートに\nなっちゃうのかな！？", 1, 5531, 1, 103, 12, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とうっ！　どうどう？\n今の決めポーズ！\nかっこいいよね♪", 2, 5532, 1, 103, 12, 101301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイとおそろの\nハロウィンコスとか\nしてみたいな～", 1, 5533, 1, 1, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カボチャ料理かぁ…\n作ったらヒデサイ\n食べてくれるかな～", 1, 5534, 1, 2, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンスイーツ…\nどれもおいしすぎて\n激ヤバなんですけど！", 1, 5535, 1, 3, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("霊界ってどんなとこ\nなんだろ～\nわりと近所だったり？", 1, 5536, 1, 4, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("服をハロウィンっぽく\nアレンジするのも\nたのしーよね♪", 1, 5537, 1, 5, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイと一緒に\nハロウィンパーティー\n…えへへ、楽しみ～", 1, 5538, 1, 101, 4, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイといると\nドキドキする…\nなんでだろ～？", 1, 5539, 1, 102, 8, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねねね、うちらも\nハロウィンパレード\n見に行こー？", 2, 5540, 1, 1, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンセイバーズ\nしゅつどーう！\nヒデサイも行こ～♪", 2, 5541, 1, 2, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マントのロゴ\nかっこいいっしょ～？\nカボきちってゆーんだ", 2, 5542, 1, 3, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トリックオア\nトリート！\nねえねえヒデサイ\nお菓子ちょうだい♪", 2, 5543, 1, 4, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイも\nメイクしてみる？\nハロウィンぽいやつ♪", 2, 5544, 1, 101, 4, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイのこと\nうちがいつでも\nあっためたげるね！\n…あ！　手、手の話！", 2, 5545, 1, 102, 8, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンのイベント\n朝からでも\nやってるかな～？", 2, 5546, 1, 1, 1, 117901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カボチャでおやつ\n作ってみたんだ～\nヒデサイ食べてみて！", 2, 5547, 1, 2, 1, 117901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンの夜って\nやっぱテンション\n上がるよね～♪", 2, 5548, 1, 3, 1, 117901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("超ふかふかしてる～\nちょっと休憩させて\nもらっちゃお", 3, 5550, 1, 2, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…\nもにカワすぎて\nつらいんですけど～！", 3, 5551, 1, 3, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィン限定の\nフレグランスじゃん！\nいい匂いする～♪", 3, 5552, 1, 4, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やばばば…\nあったかくて\n眠くなっちゃう～", 3, 5553, 1, 5, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ食べて\nもうひとがんばり\nしよーっと！", 3, 5555, 1, 7, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンっぽい\nファッションとか\n載ってないかなぁ？", 3, 5556, 1, 8, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子いっぱいだ～！\nあとでヒデサイにも\n持ってってあげよ～", 3, 5558, 1, 12, 1, 117901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お掃除が終わったら\n次は書類を片付けて…\nその次は…", 1, 5560, 1, 1, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("皆さんが冒険している\n間の留守は私に\nお任せください♪", 1, 5561, 1, 2, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美食殿の皆さんが\n持ってきてくれる\nお土産が楽しみです♪", 1, 5562, 1, 3, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ネビアさんとは\nときどき一緒にお茶\nする仲なんです", 1, 5563, 1, 4, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギルドハウスの乱れは\nギルドの乱れ\n整理整頓が大切です", 1, 5564, 1, 5, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵なギルドハウスの\n管理人ができて\nとっても幸せです♪", 1, 5565, 1, 101, 4, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("皆さんをほんの少し\n特別扱いしちゃう\n私がいます", 1, 5566, 1, 102, 8, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何かわからないことが\nあるときは私に\n聞いてくださいね", 2, 5567, 1, 1, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("書類を書いていると\n落ち着きます…\n一緒にどうですか？", 2, 5568, 1, 2, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたのまわりは\nいつも賑やかで\n楽しいですね♪", 2, 5569, 1, 3, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ！　お頼みしたい\nことがあって\n探してたんです♪", 2, 5570, 1, 4, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギブアンドテイクは\n大切です。たまには\nお礼させてください♪", 2, 5571, 1, 101, 4, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("陰に日向にあなたを\n支えていきます♪\n期待していてください", 2, 5572, 1, 102, 8, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も一日\n管理人として\nがんばります♪", 2, 5573, 1, 1, 1, 118501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹がすきました…\nそろそろお昼に\nしませんか？", 2, 5574, 1, 2, 1, 118501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間…\n皆さんといると一日が\nあっという間です", 2, 5575, 1, 3, 1, 118501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("良質なお仕事は\n良質な休憩から\nです♪", 3, 5577, 1, 2, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいものに\n囲まれてお仕事できる\nのは幸せですね♪", 3, 5578, 1, 3, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お仕事に集中できる\nアロマを設置するのも\nよさそうですね♪", 3, 5579, 1, 4, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ポカポカ温まりながら\n書類仕事をするのも\nいいものですね…", 3, 5580, 1, 5, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("栄養補給しないと\n頭が回りませんからね\nきちんと食べましょう", 3, 5582, 1, 7, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新条例はこのように\n活用されている、と…\nふむふむ…", 3, 5583, 1, 8, 1, 118501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("会合用の資料と\n連載のネーム…\nどっちを片付けよう？", 1, 5585, 1, 1, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イノリちゃん、また\nお金くすねてる…\n帰ってきたら\nお尻ペンペンだ♪", 1, 5586, 1, 2, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カヤちゃんの装備\n傷むの早いなぁ〜\nメンテしてあげないと", 1, 5587, 1, 3, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうだ、ラーゴのご飯\n買いに行かないと\n今日は何がいいかな？", 1, 5588, 1, 4, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここの人たちは見てて\n飽きない人ばっかり♪\n漫画の参考にしよ〜", 1, 5589, 1, 5, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("また一緒に買い物にも\n行きたいし、冒険も\nしたいな〜…♪", 1, 5590, 1, 101, 4, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…君は見てるだけで\n満足なの？ ちゃんと\n触って欲しいな…♪", 1, 5591, 1, 102, 8, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の目が見たいの？\nいいけど…魅了されて\n魂が壊れちゃうよ…？\n…冗談で〜す☆", 2, 5592, 1, 1, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ラーゴがね、君に\n遊んで欲しいって☆\n仲良くしてあげてね", 2, 5593, 1, 2, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アシスタントの仕事\n気に入ってくれたなら\nまたお願いしていい？", 2, 5594, 1, 3, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私が覚醒できるか？\n見せてあげたいけど…\nすごいことになるから\nまた今度で♪", 2, 5595, 1, 4, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("楽しいトラブルが\nあったら、とりあえず\n声はかけて欲しいな♪", 2, 5596, 1, 101, 4, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マッサージお願い♪\n変なところは…\n少しだけなら☆", 2, 5597, 1, 102, 8, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう〜♪\n今日も一日、一緒に\nがんばっていこうね", 2, 5598, 1, 1, 1, 106701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹空いちゃった…\n一緒にお昼行かない？\nいいお店があるんだ〜", 2, 5599, 1, 2, 1, 106701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君、眠れないの？\n誰かに見られてる？\n…きっと気のせいだよ", 2, 5600, 1, 3, 1, 106701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと休憩〜…\nこのまま原稿すれば\n疲れなくなるのかな？", 3, 5602, 1, 2, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい〜♪\nラーゴのお友達に\nなってくれる？", 3, 5603, 1, 3, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り〜♪\nこの目でどう見えるか\n伝えられたらいいのに", 3, 5604, 1, 4, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほどほどなのが\nちょうどいい時も\nあるよね…♪", 3, 5605, 1, 5, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この味付け…\nあっちでも再現\nできるかな？", 3, 5607, 1, 7, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ、面白い♪\nイノリちゃんの買う\n漫画にハズレなし☆", 3, 5608, 1, 8, 1, 106701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私…23歳だもん\n魔法少女だなんて\n名乗れないわ…", 1, 5610, 1, 1, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あん、どぅ、とろわ〜\nみんなイイ子に\nな〜る♪", 1, 5611, 1, 2, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ！　イケナイ子の\n気配がするわ！\n風紀の乱れは\n先生が許しませんっ！", 1, 5612, 1, 3, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここで闇の力が\n発動したら大変だわ！\nやだっ…そう思ったら\n緊張して…ダメぇ〜！", 1, 5613, 1, 4, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オイタした子はみんな\nどうしてうれしそうに\n私の愛のムチを\n欲しがるのかしら…？", 1, 5614, 1, 5, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの子に次は何を\n教えてあげようかしら\n愛？　希望？\nそれとも…♪", 1, 5615, 1, 101, 4, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの子のことを\n考えると、愛と希望で\n胸がいっぱいになるの", 1, 5616, 1, 102, 8, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先生なのに闇の力を\n持ってるのは秘密よ？\n他の子には\n知られたくないから…", 2, 5617, 1, 1, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("秘密の授業の内容？\nそれは…あんなことや\nこんなことよ♪\nそれから、それから…", 2, 5618, 1, 2, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しーっ！　私の正体が\nルーセント学院の\n先生だって、ここでは\n秘密にしててね？", 2, 5619, 1, 3, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら？　補習して\nほしいの？　いいわよ\n君のお願いなら\nなんでも聞いちゃう♪", 2, 5620, 1, 4, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イイ子にはごほうびを\nあげなくちゃ！\n君はなにが欲しい？\n遠慮しちゃダメよ？", 2, 5621, 1, 101, 4, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君との秘密が\nまた一つ\n増えちゃったね♪", 2, 5622, 1, 102, 8, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も一日\n元気に過ごしましょう\n先生が指導してあげる", 2, 5623, 1, 1, 1, 119001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜まで頑張れるように\nお昼ご飯はしっかり\n食べましょう〜！", 2, 5624, 1, 2, 1, 119001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜更かしはダメよ？\nイケナイ子が\nすることです！", 2, 5625, 1, 3, 1, 119001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("闇の力に振り回されて\nもうヘトヘトよ〜\n心も体も\n癒されたいわ〜", 3, 5627, 1, 2, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『秘密の学び舎』に\nこっそり連れて\n行っちゃおうかしら♪", 3, 5628, 1, 3, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イケナイ甘い香り…\nなんだか胸の奥が\n熱くなってきたわ…♪", 3, 5629, 1, 4, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やんっ♪\n燃え上がる愛みたい♪\n火照ってきちゃった♪", 3, 5630, 1, 5, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("生徒の見本に\nなれるように\n好き嫌いはしないの", 3, 5632, 1, 7, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『学び舎に咲く禁断の\n愛』？　気になるわ…\nううん、ダメよっ！\nでも…ちょっとだけ…", 3, 5633, 1, 8, 1, 119001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次に会う時は、\nまたあそこに一緒に…\nえへへ…！", 1, 5635, 1, 103, 12, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("横顔見てるの、\nバレてないよね…？\n…ちらっ", 2, 5636, 1, 103, 12, 106301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("背が少し伸びたか！？\nあ、あいつのところへ\n報告に行かねばっ！", 1, 5637, 1, 103, 12, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私も貴公の隣に\n立っていられるよう\n日々精進していくぞ！", 2, 5638, 1, 103, 12, 105301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ～\nドＭミストが\nあふれてしまいます～", 1, 5639, 1, 1, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女として\nクウカ頑張ります～！\n愛と希望の妄想を…！", 1, 5640, 1, 2, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("決めポーズの練習より\nやられポーズの練習を\nしておきます…♪", 1, 5641, 1, 3, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("快感を溜めに溜めて\n放つドＭビームは\n最高ですよ～", 1, 5642, 1, 4, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はっ！\nこれは闇の気配！\n…クウカ自身でした", 1, 5643, 1, 5, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさん…ぐふふ…\nクウカを縛りあげ…\nじゅるりぃ～♪", 1, 5644, 1, 101, 4, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんに攻められる\nことで、クウカは進化\nしてゆくのです～！", 1, 5645, 1, 102, 8, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぅっ！\nもっと激しく…！\n情熱的に～～～！", 2, 5646, 1, 1, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クウカの変身シーンを\nじっくり眺めたい！？\nは、恥ずかしいです～", 2, 5647, 1, 2, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「本当に魔法少女か\n確かめてやるよ…！」\nドＳさんはそう言って\nクウカを…ぐふふ…♪", 2, 5648, 1, 3, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛と希望の力が\nクウカの中に…\nこの胸の高鳴りが…？", 2, 5649, 1, 4, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃあんっ！\nそこです～っ！\nもっと、もっと～♪", 2, 5650, 1, 101, 4, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クウカをこんなに\n悦ばせるのは\nドＳさんだけです…♪", 2, 5651, 1, 102, 8, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明るい時間に出歩くと\n目立ちますね\n魔法少女の衣装…", 2, 5652, 1, 1, 1, 119101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼の見回りです～♪\nああ～うっかりドＭを\n増やしてしまいました", 2, 5653, 1, 2, 1, 119101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜！　それはクウカが\n活性化する時間です！\n闇の活動開始です～♪", 2, 5654, 1, 3, 1, 119101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気の緩んだクウカを\nドＳさんの鋭い牙が\n狙っています～♪", 3, 5656, 1, 2, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女のマスコット\nにいいかもしれません\nもっと鎖とか飾りを…", 3, 5657, 1, 3, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魅惑的な香りです～\nドＭミストの香りに\n似て…いや違いますね", 3, 5658, 1, 4, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("火照る体…紅潮した\nクウカの肢体を熱く\n見つめるドＳさん…", 3, 5659, 1, 5, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食欲を満たした次は\n何を満たせば\nいいですかねぇ～♪", 3, 5661, 1, 7, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女がひどい目に\n遭う物語は…\nなさそうですね…", 3, 5662, 1, 8, 1, 119101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ケーキも悪くないけど\nプリンが一番なの\nでもせっかくだから\n両方もらってやるの！", 1, 5664, 1, 1, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスって聞くと\nなんだかあったかい\n気分になるの～", 1, 5665, 1, 2, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("煙突がなくても\nミヤコはどこからでも\nおうちに入れるの♪", 1, 5666, 1, 3, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イブもプリン！\nクリスマスもプリン！\nプレゼントもプリン！", 1, 5667, 1, 4, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスツリーの\n高いところの\n飾りつけは、ミヤコに\nまかせろなの～！", 1, 5668, 1, 5, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイツのプレゼント\n楽しみなの～\nきっと最っ高に特別な\nプリンなの～♪", 1, 5669, 1, 101, 4, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミヤコがサンタなら\nアイツはトナカイなの\nつまりお似合いって\nことなの～♪", 1, 5670, 1, 102, 8, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミヤコ、プレゼントを\n配りにいくの～♪\nオマエも手伝えなの！", 2, 5671, 1, 1, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オマエにも飾りつけ\nしてやるの！\n頭にプリンを乗せると\nかわいいの♪", 2, 5672, 1, 2, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("幽霊のミヤコが\nいるなら、サンタも\nいて当たり前なの～！", 2, 5673, 1, 3, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("靴下にプリンを\n入れたらつぶれるの\nだからプリンは直接\nミヤコによこすの～！", 2, 5674, 1, 4, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はプリンだけじゃ\n満足してやらないの！\nミヤコをたくさん\n甘やかせなの！", 2, 5675, 1, 101, 4, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミヤコのプリン\nオマエになら一個…\nうう～、一口だけ\nあげてもいいの！", 2, 5676, 1, 102, 8, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サンタの朝は早いの～\nミヤコも早起きして\nプレゼント準備したの\nとってもえらいの♪", 2, 5677, 1, 1, 1, 119901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は一日中\nみんなと遊ぶの～！\nオマエも来いなの！", 2, 5678, 1, 2, 1, 119901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなが寝たら\nチャンスなの～\nこっそりプレゼント\n配りにいくの♪", 2, 5679, 1, 3, 1, 119901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むふー、気持ちいいの\nこういうプレゼントも\nいいかもしれないの", 3, 5681, 1, 2, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ気に入ったの～\nプリンとアイツの\n次くらいなの♪", 3, 5682, 1, 3, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいにおいなの～\nうっかり成仏\nしちゃいそうなの…", 3, 5683, 1, 4, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここに飾っといた\n雪だるま\nなくなっちゃったの\nきっと成仏したの～", 3, 5684, 1, 5, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これはオマエがくれる\nプリンとは\n別腹なの～", 3, 5686, 1, 7, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プリンケーキ…\nこれならミヤコにも\n作れそうなの！\nさっそく作るの！", 3, 5687, 1, 8, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("びっくりしたの～！\n幽霊のミヤコを\n驚かすなんて…\nなかなかやるの！", 3, 5689, 1, 14, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コイツの中…\nあったかいの～♪\n昼寝にぴったりなの～", 3, 5690, 1, 15, 1, 119901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリークリスマス！\n聖夜に笑顔を\nお届けするべ♪", 1, 5691, 1, 1, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマス前は\n乳製品がよく売れて\nありがてぇけんど…\n目が回る忙しさだ～", 1, 5692, 1, 2, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("牧場で売る\nクリスマスリースを\n作っておかねぇと…", 1, 5693, 1, 3, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちの動物たちにも\nクリスマスプレゼント\n用意しなきゃなぁ", 1, 5694, 1, 4, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスに向けた\n限定商品とか\n作ってみるべか？", 1, 5695, 1, 5, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんちゃんへの\nプレゼント選び…\nここでボケるか…？\nやめておくべか…？", 1, 5696, 1, 101, 4, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オラ、あんちゃんから\n本当にたくさんの物を\nもらってんなぁ…", 1, 5697, 1, 102, 8, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("雪遊びがしたいべか？\nへへっ、あんちゃん\nには負けねぇど！", 2, 5698, 1, 1, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ディナーと一緒に\n聖夜のお笑いライブを\nすんのはどうだべか？\nツッコミは任せたべ！", 2, 5699, 1, 2, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寒くなってくると\n鍋が食べたくなるべや\nあんちゃんはどうだ？", 2, 5700, 1, 3, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんちゃんは\nサンタさんのこと\n信じてるだか？", 2, 5701, 1, 4, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どでかいクリスマス\nケーキをこさえるべ\nあんちゃんも作るの\n手伝ってくんろ♪", 2, 5702, 1, 101, 4, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんちゃんが\nオラの旦那だったら…\nって、あんちゃん！\n今の聞いてただか！？", 2, 5703, 1, 102, 8, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("牧場の朝は早いど！\nさぁてと、まずは\n雪かきしに行くべや", 2, 5704, 1, 1, 1, 119201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんちゃんも一緒に\nお昼食べてくか？\n採れたての冬野菜は\nうんまいど～♪", 2, 5705, 1, 2, 1, 119201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よい子は早く寝ねぇと\nサンタさんが\n来てくれねぇべよ？", 2, 5706, 1, 3, 1, 119201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうのリンリンが\n好きそうだな…\nプレゼント候補に\n入れておくべ！", 3, 5708, 1, 2, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もふもふしてて\nなまらめんこくて…\nあぁ…癒されるべや…", 3, 5709, 1, 3, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この匂い…\n気持ちが和むべや\n夢心地になっちまうな", 3, 5710, 1, 4, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったけぇところは\n落ち着くなぁ…\nつい眠くなっちまう", 3, 5711, 1, 5, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こ、この味は…！\n…うーん、もっと\nリアクション芸も\n練習しねぇとな", 3, 5713, 1, 7, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シオシオって\nどんな本読んでんだ？\n…難しい字が\nぎっしりだべや…", 3, 5714, 1, 8, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この仕掛け…\nオラのコントに\n活かせるかも\nしんねぇな", 3, 5716, 1, 14, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この着ぐるみで\nリマリマのモノマネを\n練習してみるべか…？", 3, 5717, 1, 15, 1, 119201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もっとキレイになって\nアイツにぎゃふんと\n言わせてやるんだから", 1, 5718, 1, 103, 12, 105001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アタシのこと\nどう思う？\nかわいいって…そこは\nキレイって言ってよね", 2, 5719, 1, 103, 12, 105001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハートマークの刺繍…\nは、やりすぎですかね\nいやちょっとくらい\nアピールしてみても…", 1, 5720, 1, 1, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("雪降らないかな～\nそしたらお兄ちゃんと\n雪だるま作ったり\nできるのに～", 1, 5721, 1, 2, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プレゼントを入れる\n靴下…いくつ編んでも\n足りません～！", 1, 5722, 1, 3, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんとの\nクリスマスデートは\n早い者勝ちですからね\n負けませんよ～！", 1, 5723, 1, 4, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスだし…\n受験勉強は今日だけ\nお休みです♪", 1, 5724, 1, 5, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんと\nおそろいのコーデで\nクリスマスデート…\nしたいなぁ～！", 1, 5725, 1, 101, 4, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんに\nプレゼントする編み物\nこれで３着目～と♪\nあれ、作りすぎ？", 1, 5726, 1, 102, 8, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ、もっと近くで\n見たくありませんか？\n私のとっておきの\nクリスマスコーデ♪", 2, 5727, 1, 1, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんが風邪を\n引いたら一大事です！\n私の編み物で暖かく\nしてあげます♪", 2, 5728, 1, 2, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃん、ほっぺに\nケーキのクリームが\nついちゃってますよ♪\n私がとってあげます！", 2, 5729, 1, 3, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃん！\nケーキ、あーんって\nしてあげます！\nほら、あーん♪", 2, 5730, 1, 4, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスは大切な\n人と過ごすものっ！\nお兄ちゃん…妹の予定\n空いてますよっ！", 2, 5731, 1, 101, 4, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスはずっと、\nお兄ちゃんと一緒に\nいたい…って言ったら\n欲張り…すぎですか？", 2, 5732, 1, 102, 8, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早起きは３本お得！\n…クリスマスなら\n追加で10本ぐらい\nもらえちゃうかも！？", 2, 5733, 1, 1, 1, 119301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼はケーキ？\nそれとも七面鳥？\nごちそういっぱいで\n迷っちゃいますね～♪", 2, 5734, 1, 2, 1, 119301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんと\nクリスマスに夜更かし\n…えへへ、ちょっぴり\nドキドキしちゃう♪", 2, 5735, 1, 3, 1, 119301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("編み物をするには\n絶好のくつろぎ空間\nですね～♪", 3, 5737, 1, 2, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんというかわいさ…\nクリスマス\nプレゼントに\nもってこいですね！", 3, 5738, 1, 3, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これがお兄ちゃんの\nお部屋の香り…？\nんん～！　ずっと\nかいでいたいです～♪", 3, 5739, 1, 4, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁ、あったか～い…\n冬場はこういうのが\nありがたいですね～♪", 3, 5740, 1, 5, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ごちそうだぁ～♪\nほら、お兄ちゃんも\n食べて食べてっ！", 3, 5742, 1, 7, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスデートの\n必勝法…こ、これは\n読むしかないです！", 3, 5743, 1, 8, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ、すごいです～！\nこれを飾っておけば\nクリスマスが一層\n賑やかになりますね♪", 3, 5745, 1, 14, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さぷらーいずっ！\nリマちゃんじゃなくて\nリノちゃんでした～！", 3, 5746, 1, 15, 1, 119301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミにもミソギにも\nあの人にも頼りに\nしてもらえるように\nしっかりしなきゃ！", 1, 5747, 1, 1, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミはにんじんを\n食べられてすごいな…\n私も見習わなきゃ\nがんばろう…！", 1, 5748, 1, 2, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミソギから怖い話\n聞いちゃった…\nうぅ…誰か一緒に\nいてくれないかな", 1, 5749, 1, 3, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("立派な大人に\nなれるように\nいっぱい勉強\nしておかなくっちゃ！", 1, 5750, 1, 4, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだか…あの人の\nあやしい視線を\n感じるような…？", 1, 5751, 1, 5, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人に勉強を\n教えられるように\nしっかり予習を\nしておこうっと…！", 1, 5752, 1, 101, 4, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はあの人と\n一緒に冒険できる…\nなんだかワクワク\nしてきちゃった…！", 1, 5753, 1, 102, 8, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、いいとこに来て\nくれましたね！\nあなたに頼みたい\nことがあるんです！", 2, 5754, 1, 1, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きゃあっ！？\nへ、変なところを\n触らないでください！", 2, 5755, 1, 2, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうですかこの格好？\nかわいい、ですか…？\nそ、そうですか…\nありがとうございます", 2, 5756, 1, 3, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃあっ…！\nすみません、勉強に\n集中してたので\n驚いちゃいました", 2, 5757, 1, 4, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒に勉強して立派な\n大人になりましょうね\n私がそばで見張ってて\nあげます", 2, 5758, 1, 101, 4, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだ立派ではないかも\nですけど、私よりも\n大人なあなたのことは\n頼りにしてますからね", 2, 5759, 1, 102, 8, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("立派な大人は\n朝の時間の使い方が\n上手だと聞きました\nあなたはどうですか？", 2, 5760, 1, 1, 1, 120601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミとミソギと\nあなたと…大事な人と\n一緒のお昼ごはんは\nやさしい味がしますね", 2, 5761, 1, 2, 1, 120601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うぅ…怖い話を\n思い出しちゃいました\n寝るまで一緒に\nいてくれますか…？", 2, 5762, 1, 3, 1, 120601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すごい座り心地…！\nとっても勉強が\nはかどりそう…！", 3, 5764, 1, 2, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子…なんだか\nミミに似てるような\n気がする…ふふっ♪", 3, 5765, 1, 3, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…♪\n勉強で疲れた\n頭がリフレッシュ\nできそうです", 3, 5766, 1, 4, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽかぽかだ…♪\nミミとミソギと\nあの人と一緒に\nいるときみたい", 3, 5767, 1, 5, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いっぱい食べたら\n早く大人になれたり\nしないかな…？", 3, 5769, 1, 7, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あう…\n知らない単語が…\nちゃんと調べて\n覚えなくっちゃ…！", 3, 5770, 1, 8, 1, 120601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うさぎさんが\nぴょ～んぴょん♪\nみんなえがおで\nるんたった～♪", 1, 5773, 1, 1, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キョウカちゃんも\nいつかにんじんさんを\n好きになってくれたら\nうれしいな～♪", 1, 5774, 1, 2, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のミソギちゃんの\nイタズラ、びっくり\nしちゃったけど\nおもしろかったな～♪", 1, 5775, 1, 3, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このおうち、いつも\nいろんな人がいて\nドキドキぴょんぴょん\nって楽しいな～♪", 1, 5776, 1, 4, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいお天気～♪\nお外でみんなと\nいっぱい遊びたいな♪", 1, 5777, 1, 5, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミソギちゃんも\nキョウカちゃんも\nおにいちゃんがいると\nずっと笑顔だね～♪", 1, 5778, 1, 101, 4, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃんにはやく\nあいたいな～♪\nまだかな、まだかな♪", 1, 5779, 1, 102, 8, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ♪\nおにいちゃんに\nなでなでされると\nぽかぽかするね♪", 2, 5780, 1, 1, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("聞いて、おにいちゃん\nさっきね、かわいい\nちょうちょさんに\n会ったんだよ～♪", 2, 5781, 1, 2, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわっ…！\nおにいちゃんの顔を\nお絵かきしてたから\nびっくりしちゃった♪", 2, 5782, 1, 3, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃんも\n遊びたいの？\nそれじゃあ二人も\n呼んで遊ぼう♪", 2, 5783, 1, 4, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃんも\nみんなも、優しい人\nばっかりで\nミミ幸せ～♪", 2, 5784, 1, 101, 4, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃん♪\n高い高いしてほしいな\nすっごくぴょんぴょん\nできて、好きなんだ♪", 2, 5785, 1, 102, 8, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう～♪\nおにいちゃん、今日は\nおひさまみたいに\nきらきら元気だね～♪", 2, 5786, 1, 1, 1, 120401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おひるごはんだね～♪\nにんじんさんを\nいっぱい食べて\n元気いっぱい♪", 2, 5787, 1, 2, 1, 120401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわあ…\n眠くなってきちゃった\nおにいちゃん、\n一緒に寝よう～？", 2, 5788, 1, 3, 1, 120401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ、気持ちいい♪\nずっとこうやって\n座ってたくなるね～♪", 3, 5790, 1, 2, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わあ、かわいい～\nぎゅ～っ、ぎゅ～っ♪\nこれで仲よしだね\nえへへ♪", 3, 5791, 1, 3, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちいいにおい～♪\nぴょんぴょんしたく\nなってきちゃった♪", 3, 5792, 1, 4, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかぽかぽか♪\nおにいちゃんも\nきてくれたら、もっと\nあったかくなりそう♪", 3, 5793, 1, 5, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…ごっくん♪\nおっきくなりたいから\nいっぱい食べるよ～♪", 3, 5795, 1, 7, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ、おもしろ～い\nこの絵本ね、\nキョウカちゃんから\n教えてもらったんだ♪", 3, 5796, 1, 8, 1, 120401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この部屋…探索の\nしがいがありそう！\nついでにイタズラも\nしかけちゃお♪", 1, 5799, 1, 1, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミってああ見えて\n実は大胆で度胸も\nあるよね…ちょっと\nかっこいいな…！", 1, 5800, 1, 2, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("怖い話を聞いた時の\nキョウカって\n面白いんだよね～♪", 1, 5801, 1, 3, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんが\n慣れちゃわないように\nまた新しいイタズラを\n考えなきゃ！", 1, 5802, 1, 4, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イタズラもいいけど\nミミとキョウカと\nにいちゃんと、普通に\n遊ぶのも楽しいなぁ♪", 1, 5803, 1, 5, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミにキョウカ、\nそれににいちゃん！\nみんなそろえば愉快な\n冒険が始まりそう！", 1, 5804, 1, 101, 4, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はどんなイタズラを\nしたら、にいちゃんは\n喜んでくれるかな？", 1, 5805, 1, 102, 8, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今ミソギに触ったね？\nヤバいよにいちゃん…\n逃げないとトラップが\n発動しちゃうよ…！", 2, 5806, 1, 1, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わわっ！？　びっくり\nしたあ…！　新しい\nトラップを作ってて\n気づかなかったよ～", 2, 5807, 1, 2, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お？　にいちゃん、\nイタズラする側にも\n興味があるの？", 2, 5808, 1, 3, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんなにか用？\nあ、もしかして…\nミソギと遊びたく\nなっちゃった？", 2, 5809, 1, 4, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ベストタイミングだよ\nにいちゃん！\n今からみんなで探検に\n行くところなんだ！", 2, 5810, 1, 101, 4, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんってさ\nホントに優しいよね\nなにしても怒らないし\n…ありがとね♪", 2, 5811, 1, 102, 8, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんおはよー！\n景気づけに本日\n一発目のイタズラ、\nやっちゃうよ～♪", 2, 5812, 1, 1, 1, 120501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ごはんはロシアン\nサンドイッチだよ！\nさあ、にいちゃん！\n好きなの選んでよ！", 2, 5813, 1, 2, 1, 120501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜ってなんだか\nワクワクしてなかなか\n眠れないんだよね\nにいちゃんはどう？", 2, 5814, 1, 3, 1, 120501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この座り心地のよさ…\nなにかのトラップに\nうまく使えないかな？", 3, 5816, 1, 2, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうのに細工して\nミミやキョウカを\n驚かせると、いい反応\nするんだよね♪", 3, 5817, 1, 3, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("においをうまく使った\nイタズラって…\nなにかないかな？", 3, 5818, 1, 4, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったまりながら\n新しいイタズラを\n考えると、いい案が\n出て来たりするんだ♪", 3, 5819, 1, 5, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしくてついつい\n食べ過ぎちゃうなぁ…\nはっ…！？　これって\nまさかトラップ…！？", 3, 5821, 1, 7, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このキョウカから\n借りた冒険物語\nすっごく\nおもしろいんだよね！", 3, 5822, 1, 8, 1, 120501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("晴れ着を着ると\nなんだか心が躍るね\n足取りも軽く\nなるってもんさ", 1, 5825, 1, 1, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月の食べ物ってのは\n美味いもんだね\nいくらでも\n食べれちまうよ", 1, 5826, 1, 2, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("普段は好き勝手してる\nアタシらも\n正月くらいは\n大人しくするさ", 1, 5827, 1, 3, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("年越しそばに雑煮\nこの季節は\n温かいものが\n体に沁みるね", 1, 5828, 1, 4, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月だからって\nのんびりしすぎたね\nちょっと釣りにでも\n行こうかね", 1, 5829, 1, 5, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい正月だね\nいつかあの子と\n一杯やりたいもんだよ", 1, 5830, 1, 101, 4, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大事な人と過ごす\n正月ってのがこんなに\n楽しいもんだとはね", 1, 5831, 1, 102, 8, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋があったかくて\n顔が火照っちまったよ\nちょいと外に涼みに\n行かないか？", 2, 5832, 1, 1, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("餅ってのは\n何をつけてもうまいね\nお前さんは\nどの味が好きだい？", 2, 5833, 1, 2, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お祝いの鯛が\n足りないって？\nそれじゃあアタシが\n釣ってきてやるよ", 2, 5834, 1, 3, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おせちが美味いのは\n分かるけど\n食べ過ぎには\n気を付けるんだよ", 2, 5835, 1, 4, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お前さんのおかげで\nいい正月を\n迎えられたよ\nありがとさん！", 2, 5836, 1, 101, 4, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("慣れない晴れ着も\nお前さんに見て\nもらえたなら\n着たかいがあったね", 2, 5837, 1, 102, 8, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようさん\n寒いのは分かるけど\nいい加減布団から\n出て顔洗ってきな", 2, 5838, 1, 1, 1, 120801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日の昼飯は雑煮だ\nアタシの郷土の味\nしっかり味わって\nおくれよ", 2, 5839, 1, 2, 1, 120801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おや、お前さんも\n夜ふかしかい？\n退屈してたところさ\n付き合っておくれよ", 2, 5840, 1, 3, 1, 120801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("晴れ着だと座り方にも\n気を遣うね\nしわになったら大変さ", 3, 5842, 1, 2, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくだし\nこの子にも晴れ着を\n着せてあげたいね", 3, 5843, 1, 3, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは冬の花の香り…\n風情があって\nいいじゃないか", 3, 5844, 1, 4, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいねぇ…\nこんな寒い日には\nまさに天国だよ", 3, 5845, 1, 5, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつも食べてる\nものでも正月に\n食べると\n新鮮な気がするね", 3, 5847, 1, 7, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくの正月休みだ\nたまにはゆっくりと\n本でも読もうかね", 3, 5848, 1, 8, 1, 120801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新年のあいさつ…\n私も街のみんなに\nしてみようかしら…", 1, 5850, 1, 1, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月はゆっくり過ごす\nのよね…ゆっくりって\n何したらいいのかしら", 1, 5851, 1, 2, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好も\n慣れてくれば\n動きやすいわ", 1, 5852, 1, 3, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("う～ん、今年の抱負…\nやりたいことが\nたくさんあるのよね", 1, 5853, 1, 4, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おせち料理\nネビアの分も\n用意しなくちゃね", 1, 5854, 1, 5, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ\n正月っていいわね\nみんな楽しそうだもの", 1, 5855, 1, 101, 4, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新年の思い出…\nこれからもっと作るわ\nそれが私の抱負よ", 1, 5856, 1, 102, 8, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は家で過ごすの？\nあなたと一緒なら\nきっと楽しいわね", 2, 5857, 1, 1, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どう？　この格好？\nコッコロさんは\n褒めてくれたけど…", 2, 5858, 1, 2, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょうど良かったわ\nあなたも大掃除\n手伝ってくれる？", 2, 5859, 1, 3, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これから料理するけど\nお雑煮と焼き餅\nどっちが好きかしら？", 2, 5860, 1, 4, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『今の私』にとって\n初めての正月だもの\nあなたと楽しまないと", 2, 5861, 1, 101, 4, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("去年よりも今年…\nもっと成長するからね\n…お兄ちゃん♪", 2, 5862, 1, 102, 8, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう\nせっかくの正月だもの\n朝から楽しまないとね", 2, 5863, 1, 1, 1, 120701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇ…\n良かったら正月の遊び\n教えてくれるかしら？", 2, 5864, 1, 2, 1, 120701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ～…今日が\n終わっちゃうのが…\nもったいないわね…", 2, 5865, 1, 3, 1, 120701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…お参り後だから\n心地よすぎて眠って\nしまいそうだわ…", 3, 5867, 1, 2, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ\nかわいいものって\n癒されるわね…", 3, 5868, 1, 3, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…ん\nこれが梅の香り？\n…いい匂いね", 3, 5869, 1, 4, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キャルじゃないけど…\nこのまま丸く\nなりたいところね…", 3, 5870, 1, 5, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はむはむっ…♪\nせっかくの正月だもの\n堪能しなくちゃね♪", 3, 5872, 1, 7, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…ふんふん\n帯の結び方って\nこんなにあるのね…", 3, 5873, 1, 8, 1, 120701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今の私が作れる\n最高の一曲…\nあの人に届くといいな", 1, 5875, 1, 103, 12, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの、歌を…\n聞いてくれませんか？\nあなたに贈る\n特別な歌を", 2, 5876, 1, 103, 12, 104201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひい、ふう…\nむむ、みなに配る\nお年玉のポチ袋が\n残りわずかなのじゃ…", 1, 5877, 1, 1, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("宴の準備はわらわに\n任せておくのじゃ！\n支配者の手腕、\n見せつけてくれる！", 1, 5878, 1, 2, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新年の願掛けなら\nわらわにすればよい\n支配者に頼むほうが\n確実じゃろう？", 1, 5879, 1, 3, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みなからもらった\nこの年賀状とやら…\nわらわも\n書いてみようかの♪", 1, 5880, 1, 4, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月飾りにもいろいろ\n種類があるんじゃの～\nどれも華々しくて\nわらわ好みじゃ♪", 1, 5881, 1, 5, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あやつへのお年玉は\nちと多めにしておくか\n…日ごろの感謝も\n込めてのう", 1, 5882, 1, 101, 4, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あやつのことを想うと\nそれだけで行く年\n来る年が楽しみになる\nふふ、愉快なやつじゃ", 1, 5883, 1, 102, 8, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みなに晴れ着を\n褒められて、とても\nよい気分なのじゃ♪\n次はお主の番じゃぞ？", 2, 5884, 1, 1, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お主へのお年玉は\nいちばん最後じゃ！\n残り物には福が宿る\nそうじゃからのう", 2, 5885, 1, 2, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この季節は手が\nかじかむのう…ほれ、\nお主！　わらわの手を\nあたためるのじゃ！", 2, 5886, 1, 3, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お主のために雑煮を\n手作りしてみたのじゃ\n食べていくがよい♪", 2, 5887, 1, 4, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眷属のお主に\n正月休みはまだ早い！\nずっとわらわのそばに\n控えておくのじゃ♪", 2, 5888, 1, 101, 4, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、これほど楽しい\n正月は初めてじゃ…\nお主と過ごす時間は\nいつだって特別じゃな", 2, 5889, 1, 102, 8, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早起きしてわらわを\n待っておったのか？\nさすがはわらわの眷属\n殊勝な心がけじゃな♪", 2, 5890, 1, 1, 1, 120901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食事どきじゃな\n正月の宴会料理が\nわらわたちを\n待っておるぞ♪", 2, 5891, 1, 2, 1, 120901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜も更けてきたのう\n冬の夜は長い…\n心ゆくまでお主と\n過ごせるわけじゃな♪", 2, 5892, 1, 3, 1, 120901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("実に心地がよい♪\nこのまま寝正月も\n悪くないかも\nしれぬのう", 3, 5894, 1, 2, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛いやつじゃのう\nわらわのそばに置いて\nやってもよいぞ♪", 3, 5895, 1, 3, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("品のある香りじゃのう\n寝室に置いておけば\nなにかご利益に\nあずかれそうじゃな", 3, 5896, 1, 4, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("心地よい…\nわらわはしばらく\nここから動かぬぞ\nお主も付き合うがよい", 3, 5897, 1, 5, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("舌鼓が鳴るのう♪\n正月の宴には\n持ってこいの品じゃ！", 3, 5899, 1, 7, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほう、新春にはそんな\n習わしが…正月を\n制するには、まだまだ\n勉強が必要じゃのう", 3, 5900, 1, 8, 1, 120901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("久しぶりの我が家って\n感じです！　やっぱり\nここが一番ですね〜！", 1, 5902, 1, 1, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さあ食べましょう！\nみんなで囲める食卓を\n心から味わいますよ☆", 1, 5903, 1, 2, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルに\n帰ってきた途端に\nお腹が空きました〜！", 1, 5904, 1, 3, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ただいま☆\n幸せ特盛りの\nわたしの日常！", 1, 5905, 1, 4, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ようやくランドソルに\n帰ってきたことですし\nやっぱり魔物料理を\nいただきましょう☆", 1, 5906, 1, 5, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人との絆を\n守るために\nもっともっと食べて\n強くならなくちゃ☆", 1, 5907, 1, 101, 4, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもありがとうって\nあの人を思いっきり\n抱きしめたいです☆", 1, 5908, 1, 102, 8, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの想いは\nこの身をかけて\n全力で受け止めます！", 2, 5909, 1, 1, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おかえりなさい☆\nここにいるみんなも\nあなたの帰りをずっと\n待っていましたよ！", 2, 5910, 1, 2, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このギルドハウスで\n冒険の疲れを\n癒しましょう〜！", 2, 5911, 1, 3, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの想いが\n全力全開を超える\n力をくれました！", 2, 5912, 1, 4, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日常が続く幸せを\nあなたと一緒に\nかみしめたいです☆", 2, 5913, 1, 101, 4, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぎゅ〜っ！\nわたしたちは\nどんなことがあっても\nずっと一緒ですよ？", 2, 5914, 1, 102, 8, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます！\nあなたと過ごせる\n幸せを、今日も\n味わいますよ〜！", 2, 5915, 1, 1, 1, 121001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ご飯の時間ですよー！\nあなたも一緒に\n食べましょうね！", 2, 5916, 1, 2, 1, 121001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日もあなたが隣に\nいてくれることを\n心から願ってますよ\nおやすみなさい☆", 2, 5917, 1, 3, 1, 121001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふい〜…\n安心できる場所で\nくつろげるって\n幸せですね〜…", 3, 5919, 1, 2, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じゅるり…\n食べたくなっちゃう\nくらい、かわいい☆", 3, 5920, 1, 3, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん…おおー！\nステーキの香り！\nやばいですね☆", 3, 5921, 1, 4, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体がぽかぽかしてきて\nわたしの食欲も\n燃えてきましたよー！", 3, 5922, 1, 5, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたしの食欲に\nついてこられますか？\nまだまだ食べますよ！", 3, 5924, 1, 7, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これがキャルちゃんの\n言っていた、キスで\n目覚める王子様の\nおとぎ話ですか〜☆", 3, 5925, 1, 8, 1, 121001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自分で自分を\n分析するのも、これは\nこれで面白い…♪", 1, 5927, 1, 1, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("強過ぎる力の扱いには\n注意しないと…\n七冠がいい例だね", 1, 5928, 1, 2, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年の交友関係は\n計り知れないな…\nアタシも含むのか！", 1, 5929, 1, 3, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("原理を徹底解明して\n再発を防ぐぞー！\n…誰か手伝って～！", 1, 5930, 1, 4, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは祝福にも\n呪いにもなる…\n忘れずにいよう", 1, 5931, 1, 5, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年が\n目を覚ましてくれて\n本当によかった…", 1, 5932, 1, 101, 4, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼以外を選んでいたら\n今回の事態は\n乗り切れなかったな…\nさすがだよ、少年", 1, 5933, 1, 102, 8, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年！　調子はどう？\nクレープ食べられる？\nっていうか食べて？", 2, 5934, 1, 1, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("元気そうで何よりだ\nまた店を手伝いに\nきてよ。二人もキミに\n会いたがってたしさ", 2, 5935, 1, 2, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミの診察もあるし\n今はなるべくそばに\nいるよ。迷惑じゃ\nなければだけど", 2, 5936, 1, 3, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱり少年は\nあちこちで人を\n助けてる時が\n一番輝いてるよ", 2, 5937, 1, 4, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アタシは大したこと\nしてないけど\nみんなのことは\n褒めてあげてね", 2, 5938, 1, 101, 4, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなを笑顔に\nできるのは\nやっぱり少年だね", 2, 5939, 1, 102, 8, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やあ少年\n朝寝坊はしてない？\nそれじゃ、よい１日を", 2, 5940, 1, 1, 1, 121201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おや、少年！\nまかないのクレープ\n作ったけど、食べる？", 2, 5941, 1, 2, 1, 121201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ…もう夜か…\n研究してたら\nあっという間だね…\nおやすみ、少年", 2, 5942, 1, 3, 1, 121201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体がなまってたのか\n前線に出ると疲れる…\nまさか…年のせい！？", 3, 5944, 1, 2, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミたちも今の\nアタシと同じ感じに\nアレンジしてあげよう", 3, 5945, 1, 3, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誰が置いたんだろう？\nいい香りだねぇ…\nうん、気に入った♪", 3, 5946, 1, 4, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何も考えてない時間も\n実は思考にとって\n大事なんだよね～…", 3, 5947, 1, 5, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食の大切さは\nいつの食事からも\n感じられるね♪", 3, 5949, 1, 7, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ…面白い！\n今度全巻\n借りにこようっと", 3, 5950, 1, 8, 1, 121201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("聖学祭か…\n良い記憶はないな\nよし忘れよう", 1, 5952, 1, 1, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("健全なる精神は\n健全なる肉体に宿る…\nはっ、知ったことかよ", 1, 5953, 1, 2, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇だし鏡でも見るか…\nえへへ、ユニだよ♪\nよし子供料金いけるな", 1, 5954, 1, 3, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アオイ君は元気に\nしているだろうか…\n彼女は人一倍ぼくに\n懐いていたからな…", 1, 5955, 1, 4, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろシズル君は\n姉という幻想から\n目覚めただろうか…", 1, 5956, 1, 5, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼくは来年も聖学祭に\n行くさ…卒業しても\n君らとは永遠だ", 1, 5957, 1, 101, 4, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近同志の登校率が\n減少傾向だな…\nまあ仕方ないのだが…\nないのだが…", 1, 5958, 1, 102, 8, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほわあああ！\nおい急に話しかけるな\n学びがこぼれる", 2, 5959, 1, 1, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この体操着、周囲から\n大層評判が良いのだよ\nたいそうだけにな\nどやっ！", 2, 5960, 1, 2, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何を着ていようと\nぼくはぼくさ\n外見など所詮は\n魂の識別符に過ぎん", 2, 5961, 1, 3, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("救護院のアヤネ君が\n最近ぼくの自称年齢に\n疑念を持ち始めてな…\nあの熊…殺るか…", 2, 5962, 1, 4, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うん？　なんだね？\nなに、用は無い？\n用も無いのに呼ぶとは\nもしや…これが友達！", 2, 5963, 1, 101, 4, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服が似合ってる？\nな、なんだね突然…\nやめたまえよでゅふふ", 2, 5964, 1, 102, 8, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁ～あ…\n朝も更けてきたな…\nそろそろ寝るか…", 2, 5965, 1, 1, 1, 116401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁ～あ…もう昼だ…\n人間の起きている\n時間ではないな…\n早く寝なくては…", 2, 5966, 1, 2, 1, 116401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん、よく寝た！\n気持ちのいい夜だな\n今日も一日がんばるぞ", 2, 5967, 1, 3, 1, 116401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほわぁ～…\nもしやこれは都で噂の\n人を駄目にするやつ…", 3, 5969, 1, 2, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ、愛くるしいな\nだが似合い過ぎる…\nぼくが持つと我ながら\n子供にしか見えん", 3, 5970, 1, 3, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アロマか、興味深いな\nミツキ印ポーションも\n気化させて鼻腔から\n吸入してみるか…", 3, 5971, 1, 4, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んふ、んふふ…\n火ってイイよね…\nずっと見てられるね…", 3, 5972, 1, 5, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("や、やめろ…\nとめどなく固形食物を\n生産するのはやめろ…", 3, 5974, 1, 7, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この可愛げのない筆致\nやはり作者は理系か！\nぐああ目が理系になる", 3, 5975, 1, 8, 1, 116401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…あいつのためなら\n無理くらいいくらでも\nしてやるわよ", 1, 5977, 1, 1, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この姿、\n魔力の制御ムズ過ぎ…\nま、あたしは優秀だし\nどうとでもなるけど！", 1, 5978, 1, 2, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつのこと、\n全部受け入れるって\n決めたから！", 1, 5979, 1, 3, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今なら誰だろうと\n負ける気がしないわ\nドラゴンでもなんでも\nかかってこいっての！", 1, 5980, 1, 4, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("散々助けられた分、\n今度はあたしが\nあいつのこと助けるわ", 1, 5981, 1, 5, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつとの\nこれまでの冒険は\nどれも、あたしの\n大切な思い出…", 1, 5982, 1, 101, 4, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もしまたあいつが\n寝たままになったら\nなんだってするわ\nキ…キスでも…", 1, 5983, 1, 102, 8, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なに、お腹空いたの？\nなら、おいしいご飯を\n食べに行きましょ♪", 2, 5984, 1, 1, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱ、\nあんたのアホ面見ると\n安心するわ♪", 2, 5985, 1, 2, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("【美食殿】はあんたと\nぺコリーヌがいなきゃ\n始まんないっての", 2, 5986, 1, 3, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃあっ！？\n急に声かけないで！？\n魔力が暴発しても\n知らないわよ！", 2, 5987, 1, 4, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…あんたとこうして\nぼーっと過ごす時間、\nまあ…嫌いじゃないわ", 2, 5988, 1, 101, 4, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたが信じて\n見守っててくれれば…\nあたし、\nなんだってできるわ", 2, 5989, 1, 102, 8, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよ\n早く顔洗いなさいよ、\nこのねぼすけ♪", 2, 5990, 1, 1, 1, 121101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のお昼は\nどこで食べる？\nあんたが\n決めていいわよ", 2, 5991, 1, 2, 1, 121101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もしあんたがまた\n夢に囚われても\nあたしが助けるわ\n安心して寝なさいよ", 2, 5992, 1, 3, 1, 121101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちいい～…♪\nあいつもたまには\nこうして休ませなきゃ", 3, 5994, 1, 2, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一目惚れしたかも…！\nこの子、\n部屋に飾りたいわー♪", 3, 5995, 1, 3, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へぇ、あいつって\nこういう匂いが\n好きなのかしら…？", 3, 5996, 1, 4, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かくて最高…♪\n丸くなっちゃいそう…\nうにゃあ…♪", 3, 5997, 1, 5, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イケるわね、これ！\nやっぱり食べるって\n大事よねー♪", 3, 5999, 1, 7, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ファーストキスは\nどんな味、ね…\nふ、ふ～ん…？\nなるほど…", 3, 6000, 1, 8, 1, 121101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お友だち…\nできるかしら…？\nこんなわたしでも…", 1, 6002, 1, 1, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あまり、きょろきょろ\nしちゃダメよね…\n変な子だと、\n思われてしまうわ…", 1, 6003, 1, 2, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("広い場所、\n落ち着かない…\nはぅ…どこにいれば…", 1, 6004, 1, 3, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("～♪", 1, 6005, 1, 4, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("【レイジ・レギオン】\n…またいつか、\nみんなと…", 1, 6006, 1, 5, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…一度でいいから、\nわたしもママって…\nあっ、その…\n…な、なんでもないわ", 1, 6007, 1, 101, 4, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここが、今のわたしに\nとっての帰る場所…\n…そう思っても、\nいいのかしら…？", 1, 6008, 1, 102, 8, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ええと…\nお腹、空いてる？\nおねむじゃない？", 2, 6009, 1, 1, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいると\n邪魔かしら…？\nならもっと隅っこに…", 2, 6010, 1, 2, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お喋り…？\nわたしでいいの…？\nうれしい…", 2, 6011, 1, 3, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの好きな歌…\n教えて…？\n練習、するから…", 2, 6012, 1, 4, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここは賑やかだけど…\nうるさいとは感じない\nむしろ、心地いい…", 2, 6013, 1, 101, 4, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("安心、して…\nわたしの歌で、\nあなたを守るから…", 2, 6014, 1, 102, 8, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっとだけ…\n朝は、苦手…\n…ふぁ…", 2, 6015, 1, 1, 1, 118101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼は、食べた？\n良かったら、一緒に…\n少し…焦げてるけど…", 2, 6016, 1, 2, 1, 118101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眠れないのかしら…\nじゃ、じゃあ…\n子守歌…聴く？", 2, 6017, 1, 3, 1, 118101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな特等席…\n恐縮、です…", 3, 6019, 1, 2, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("い、今のうちに、\nこの子でお世話の\n練習を…", 3, 6020, 1, 3, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…\n…つらい気持ちも\n癒してくれる", 3, 6021, 1, 4, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかい…\nいつまでも、\nこうしていられそう…", 3, 6022, 1, 5, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしく出来てる…\nすごいわ…\n見習わなくっちゃ…", 3, 6024, 1, 7, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『赤ちゃんとママの\nスキンシップ入門』…\n…べ、勉強になるわ…", 3, 6025, 1, 8, 1, 118101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きれいなお部屋…！\n立派な舞台の\nセットみたい…♪", 1, 6027, 1, 1, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お芝居では私が先輩\nなんだから、しっかり\n私がミサキちゃんを\nエスコートしなきゃ", 1, 6028, 1, 2, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("～～♪\n歌うお芝居も多いから\nもっと上手く\nなりたいな…！", 1, 6029, 1, 3, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいる人たちと\n仲良くなりたいな…\nそしたらきっと演技の\n幅も広げられるよね", 1, 6030, 1, 4, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("機会があったら\nアヤネちゃんとも\nお芝居してみたいな♪", 1, 6031, 1, 5, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんに褒めて\nもらえるように\nお芝居の練習\nいっぱいしなきゃ…♪", 1, 6032, 1, 101, 4, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あう…お兄ちゃんを\n意識したら、台詞が\n飛んじゃったよぅ…！", 1, 6033, 1, 102, 8, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、お兄ちゃん…♪\nお芝居の練習を\n見てくれませんか…？", 2, 6034, 1, 1, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いまの発声練習\nどうでしたか？\nひゃん…！？\n頭は撫でないでぇ～", 2, 6035, 1, 2, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミサキちゃんも\nお芝居、とっても\n上達してるんですよ\n私も負けられません♪", 2, 6036, 1, 3, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("また物語を聞かせて\nほしい、ですか…？\n私なんかでよければ\nもちろんよろこんで♪", 2, 6037, 1, 4, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しいお話を\n考えてみました\n聞いてくれますか…？\nよかった…♪", 2, 6038, 1, 101, 4, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか…舞台上じゃ\nなくても、照れずに\nお兄ちゃんに気持ちを\n伝えてみせますね…♪", 2, 6039, 1, 102, 8, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます♪\nマヒルさんにもらった\nミルク、一緒に\n飲みませんか？", 2, 6040, 1, 1, 1, 121301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("牧場のみなさんに\nドングリパンを\nいただきました～\nおひとつどうぞ♪", 2, 6041, 1, 2, 1, 121301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寝る前にまたココアを\n飲みながら、お話を\n聞いてもらえますか？\nえへへ、うれしいな♪", 2, 6042, 1, 3, 1, 121301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お芝居の練習の\nあとは、ここで\nお兄ちゃんと\nゆっくりしたいな♪", 3, 6044, 1, 2, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も演技の\n練習に付き合ってね♪", 3, 6045, 1, 3, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵な香り…\nこのイメージも\nお芝居に\n活かせないかな…？", 3, 6046, 1, 4, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私もお芝居で\nみんなの心を\nぽかぽか温められる\nようになりたいな…♪", 3, 6047, 1, 5, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("舞台に立つんだから\n食べ過ぎないように\n気をつけないと。\nでも…おいしいなぁ♪", 3, 6049, 1, 7, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このお話、面白い…\n脚本を書く\n参考にもなりそう…♪", 3, 6050, 1, 8, 1, 121301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ…♪\n二人で見た夕日…\nキレイでしたね…", 1, 6052, 1, 103, 12, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これから泳ぎの\n練習ですか？\n付き合いますよ♪", 2, 6053, 1, 103, 12, 107501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまを導くことで\nわたくしも未知なる\n領域へと辿り着けます", 1, 6054, 1, 103, 12, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまとなら\n海よりも深く\n空よりも高い場所へも\n目指せそうです", 2, 6055, 1, 103, 12, 107601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつと二人で\n夏の遠い海に…って\nあたしってば\nなに考えてるのよ！", 1, 6056, 1, 103, 12, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしが楽しく\n過ごせるのはあんたが\nいてくれたからよ\nか、感謝してるわ", 2, 6057, 1, 103, 12, 107801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…アタシってば\nこんなにかわいくって\nキレイなんて罪よね～", 1, 6058, 1, 1, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("舞台の衣装を\nクリーニング\nしとかなくちゃ…", 1, 6059, 1, 2, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("舞台映えするメイク…\nスズナなら\n知ってるかしら？", 1, 6060, 1, 3, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("物産展の会計係と\n山盛りの算数の宿題…\nどっちが簡単かしら…", 1, 6061, 1, 4, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("牧場と温泉の仕事に\nお芝居の練習に…\nちょ、ちょっと休憩～", 1, 6062, 1, 5, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お客さんの視線も\nうれしいけど…\nあいつも見てて\nくれてるかしら？", 1, 6063, 1, 101, 4, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もっともっと\nセクシーになって\nあいつをビックリ\nさせてやるわ♪", 1, 6064, 1, 102, 8, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンタも休憩？\nしっかり働くために\n休むのも大事よね", 2, 6065, 1, 1, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふん♪　アタシも\n料理ができるように\nなったんだから！\n簡単なのだけだけど…", 2, 6066, 1, 2, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("温泉ってお肌に\nいいのよね？\nもっとキレイに\nなったらどうしよう〜", 2, 6067, 1, 3, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("物産展の荷物は\nこれでよし…っと\nそれじゃアンタも\n運ぶの手伝ってよね♪", 2, 6068, 1, 4, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもと違うアタシに\n見とれちゃった？\n仕方ないわね～♪", 2, 6069, 1, 101, 4, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お花見って風流で\n大人って感じ♪\n…でもお団子も\n忘れないでよね！", 2, 6070, 1, 102, 8, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなに朝ごはんを\n作ってみたら\n喜んでくれるかしら？", 2, 6071, 1, 1, 1, 121401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お客さんがいっぱい\n来る時間帯ね！\n元気出していくわ！", 2, 6072, 1, 2, 1, 121401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ寝ないと…\n睡眠不足はお肌の\n大敵なんだから", 2, 6073, 1, 3, 1, 121401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかしてて\n気持ちいい～♪\n疲れが癒されるぅ…", 3, 6075, 1, 2, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子もアタシと\nおそろいの衣装に\nしてあげようかしら♪", 3, 6076, 1, 3, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵な衣装で\nいい香りを\n身にまとう…ふふ、\n大人のたしなみよね♪", 3, 6077, 1, 4, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったか～い♪\nここでお昼寝したら\n気持ちよさそう…", 3, 6078, 1, 5, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お仕事がんばると\nいつもよりお腹\n空いちゃう～！", 3, 6080, 1, 7, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最新のトレンド\n載ってないかしら？\n物産展の売り物に\n取り入れなくちゃ！", 3, 6081, 1, 8, 1, 121401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("怪盗のこと…\nお父さんお母さんに\nもし知られたら\nなんて説明しよう…", 1, 6083, 1, 1, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たとえ怪盗でも、人の\n家にお邪魔するときは\n身だしなみをしっかり\nしないと…", 1, 6084, 1, 2, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鍵開けって難しい…\nうーん、もっと\n練習しておかなくちゃ", 1, 6085, 1, 3, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("姿が見えない\n怪盗の噂…？\nわ、私のことじゃ\nありませんように…！", 1, 6086, 1, 4, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("予告状って…\n切手はどこに貼れば\nいいんだろう…？", 1, 6087, 1, 5, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("怪盗活動にも\n慣れてきたけど…\nやっぱり先輩が\nいないと心細いなぁ…", 1, 6088, 1, 101, 4, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せ、先輩の心も\nいつか盗めるかな…？\n…わわわ、私ってば\nなに言ってるんだろ…", 1, 6089, 1, 102, 8, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("怪盗が大活躍って\n新聞で読んだ…？\nだっ、誰のこと\nでしょうね…あはは", 2, 6090, 1, 1, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("尾行に潜入…\n存在感がないのって\n意外と役立つことも\nあるんですね", 2, 6091, 1, 2, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せせせ、先輩っ！\n帽子をぎゅーって\nかぶったら、抜けなく\nなっちゃいました…！", 2, 6092, 1, 3, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬ、盗み聞きなんて\nしてませんよ？\nみんなが私に気づかず\n話し始めるだけで…", 2, 6093, 1, 4, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("秘密道具が見たい？\nそ、それは内緒です！\n秘密道具ですから…\nで、でも先輩になら…", 2, 6094, 1, 101, 4, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ\n見つかっちゃいました\n先輩はいつも私を\n見つけてくれますね…", 2, 6095, 1, 102, 8, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございまふ…\n秘密道具のお手入れで\n夜更かししちゃって…\nちょっと眠たいです～", 2, 6096, 1, 1, 1, 121501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("怪盗が昼に活動する…\n案外そのほうが\n意外性が\nあるのかも…？", 2, 6097, 1, 2, 1, 121501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外が暗くなりましたね\n…そろそろ怪盗の活動\n始めましょうか？", 2, 6098, 1, 3, 1, 121501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここでくつろぐと\n疲れが取れます～\n…今日も怪盗\nがんばろっと", 3, 6100, 1, 2, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁ、かわいい…！\n心を盗まれるって\nこういうことかな…？", 3, 6101, 1, 3, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵な香り…でも\n服に香りがついたら\n隠れてるときに\n見つかっちゃうかな…", 3, 6102, 1, 4, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽかぽかで\nいい気持ち…\n夜道を歩く前に\n温まっておこうっと…", 3, 6103, 1, 5, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("怪盗活動に備えて\n今のうちにしっかり\n食べておかなきゃ…！", 3, 6105, 1, 7, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("女の子は秘密が\n多いほうが魅力的…？\nそ、そうなんだ…", 3, 6106, 1, 8, 1, 121501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんはいつも\nクウカの妄想の中に…\nぐふふ、じゅるり～♪", 1, 6108, 1, 103, 12, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やさしい触り方も\n嫌いじゃありません…\nは…恥ずかしいですが", 2, 6109, 1, 103, 12, 104501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この大怪盗さまに\n盗めないものなんて\nないです！　たぶん！", 1, 6110, 1, 1, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしにふさわしい\nビッグなお宝は\nどこにあるですかね～", 1, 6111, 1, 2, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろーりそろーり…\n気配を消せばお菓子も\n食べ放題…にやり", 1, 6112, 1, 3, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("またサボってたのが\nバレたです…\nボスの地獄耳～！", 1, 6113, 1, 4, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギャングで大怪盗…！\nこの肩書の多さ！\nまさに有能の証です！", 1, 6114, 1, 5, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんだったら…\nお宝を山分けして\nあげてもいいですよ", 1, 6115, 1, 101, 4, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんはアレですよ\n大怪盗イノリさまの\n相棒みたいなものです", 1, 6116, 1, 102, 8, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何事も用心深さが\n大切ですよ。ビ…\nビビりじゃないです！", 2, 6117, 1, 1, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬ、盗み聞き？\nしてないですよっ？\nぴゅーぴゅーぴゅー", 2, 6118, 1, 2, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("情報が欲しければ\nお菓子と交換ですよ\nさぁ、交換交換っ♪", 2, 6119, 1, 3, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しーっ！\n今、尾行中なんです\n話はあとで…", 2, 6120, 1, 4, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんと話してると\n時間が速いような…？\nこの時間泥棒！", 2, 6121, 1, 101, 4, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょうどよかった！\nいい話があるんです\n一口乗りませんか？", 2, 6122, 1, 102, 8, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おてんとうさまが\n出てやがるですね…\n悪事がやりにくいです", 2, 6123, 1, 1, 1, 121601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間ですか\nご飯にお昼寝…\nいやー忙しいです♪", 2, 6124, 1, 2, 1, 121601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふっふっふ！　夜こそ\n大怪盗の時間です！\n……ふぁあ", 2, 6125, 1, 3, 1, 121601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん…\n警備の目がないと\n気楽でいいですねぇ", 3, 6127, 1, 2, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くう…！\nこのかわいさは\n盗めないです…♪", 3, 6128, 1, 3, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("犯行現場に残ったのは\n香水の匂いだけ…\nふふ、おしゃれ大怪盗", 3, 6129, 1, 4, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("意外とこういう場所に\n隠し扉があったり…\nしないです？", 3, 6130, 1, 5, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…\nこの美味しさ…\nとんでもない罠ですね", 3, 6132, 1, 7, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むむむ…ちっとも\n分からないです…\nほとんど暗号ですよ", 3, 6133, 1, 8, 1, 121601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら、サレンさんは\nどこに行かれた\nのかしら？", 1, 6135, 1, 1, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふんふんふーん♪\nなんだか華やいだ\n気分ですわ♪", 1, 6136, 1, 2, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さて…次の事業は\nどうしましょう\n何か面白いことは…", 1, 6137, 1, 3, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おーっほっほっほ！\nあら…楽しくて、つい\n笑ってしまいましたわ", 1, 6138, 1, 4, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("センスがあって\nいいお部屋ですわね\n私も見習いたいですわ", 1, 6139, 1, 5, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サレンさんとあのお方\n仲がいいですわね\nも、もちろん仲がいい\nのはよいことですわ！", 1, 6140, 1, 101, 4, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんなときでも\n正々堂々！\nそれが私の\n誇りですわ！", 1, 6141, 1, 102, 8, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、ごきげんよう\n私、絶好調でしてよ", 2, 6142, 1, 1, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうかされましたか？\n何かお困りごと\nでしたら\n是非力になりますわよ", 2, 6143, 1, 2, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまにはこうして\nゆっくりと\nお話しするのも\nいいものですわね", 2, 6144, 1, 3, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次の事業に関して\n考え事をしてましたの\nよければ相談に乗って\nくださるかしら？", 2, 6145, 1, 4, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よろしければ\nお話しませんこと？\nサレンさんのお話を\n聞かせてほしいですわ", 2, 6146, 1, 101, 4, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ…\n先ほどサレンさんと\nあなたさまのお話を\nしていたところですわ", 2, 6147, 1, 102, 8, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さあ！\n今日も一日\n全力で参りますわ！", 2, 6148, 1, 1, 1, 121701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼はどうしましょう\nサレンさんをお誘い\nしてみようかしら", 2, 6149, 1, 2, 1, 121701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう少しだけ…\n明日の準備をして\nおかないと…", 2, 6150, 1, 3, 1, 121701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～…いいですわね\nはっ、私としたことが\nはしたないですわね", 3, 6152, 1, 2, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいらしいですわ\nいくつになっても\nぎゅっと\nしたくなりますわね", 3, 6153, 1, 3, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("落ち着きますわね\nサレンさんはどんな\n香りが好きなのかしら", 3, 6154, 1, 4, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ、燃え盛る\n情熱の炎…\nいいですわね", 3, 6155, 1, 5, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このおいしさで\n元手がゼロ…\nすばらしい\n商品ですわ！", 3, 6157, 1, 7, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは…ふむふむ\n新しい事業のヒントに\nなりそうですわ", 3, 6158, 1, 8, 1, 121701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さて、と…\n今日は何をしなくちゃ\nいけないんだっけ？", 1, 6161, 1, 1, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やることは山積み\nだけど、手を動かす\nのは嫌いじゃないわ♪", 1, 6162, 1, 2, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら？　アキノさんの\n声が聞こえたような\n気がしたんだけど…", 1, 6163, 1, 3, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アキノさんといると\nついこっちまで笑顔に\nなっちゃうのよね", 1, 6164, 1, 4, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弱音なんか\nはいてられないわ\nアキノさんに\n笑われちゃうもの", 1, 6165, 1, 5, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気が付けばアキノさん\nのペースだけど…\n不思議と嫌では\nないのよね", 1, 6166, 1, 101, 4, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしを好敵手って\n言ってくれる\nアキノさんのためにも\nしっかりしなくちゃ", 1, 6167, 1, 102, 8, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたの？\nアキノさんなら\nさっきそこに\nいなかった？", 2, 6168, 1, 1, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしなら大丈夫\n救護院だって\nみんなが助けて\nくれるからね", 2, 6169, 1, 2, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さっきアキノさんが\nあんたを探してたわよ\nなにかしたの？", 2, 6170, 1, 3, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こう見えてヒマじゃ\nないんだけど…\n少しくらいなら\n付き合ってあげるわ", 2, 6171, 1, 4, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、あんたと\nアキノさんって…\nううん、やっぱり\nなんでもないわ…", 2, 6172, 1, 101, 4, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アキノさんも誘って\nお茶でもしない？\n話したいことが\nたくさんあるの♪", 2, 6173, 1, 102, 8, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早起きは三文の得よ\nいい一日を迎えるため\n目を覚まさなきゃ", 2, 6174, 1, 1, 1, 121801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のお昼は…\nアキノさんと同席する\n予定だったわね\nあんたもどう？", 2, 6175, 1, 2, 1, 121801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁ…っと、だめね\nたるんだところを\nアキノさんに\n見せるわけには", 2, 6176, 1, 3, 1, 121801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～…\n落ち着くわね\nこのまま\n寝ちゃいそう…", 3, 6178, 1, 2, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("救護院の皆も\nぬいぐるみが\n大好きなのよ", 3, 6179, 1, 3, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りね…\nこれはアキノさんの\n趣味かしら？", 3, 6180, 1, 4, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなに激しく\n燃えているのに\nあったかくて落ち着く\nまるでアキノさんね", 3, 6181, 1, 5, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんどん出てくる…\nこれ、救護院にも\nほしいわね…", 3, 6183, 1, 7, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\n前にアキノさんが\n言ってたのは\nこのことかしら？", 3, 6184, 1, 8, 1, 121801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この衣装、私には\nちょっとかわい過ぎて\n恥ずかしいな…", 1, 6187, 1, 1, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一部の人からは\n海賊より海賊らしいと\n評判の父です", 1, 6188, 1, 2, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("潮風で錆びないよう\n武器の手入れを\nしておきましょうか", 1, 6189, 1, 3, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("宝探しのお手伝いなら\n力になれると思います\n父のやる気次第ですが", 1, 6190, 1, 4, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("除霊は気を遣います\n一歩間違えると父まで\n成仏させてしまうので", 1, 6191, 1, 5, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人と見た\n海の景色を…ずっと\n忘れずにいたいな", 1, 6192, 1, 101, 4, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("幽霊になっても\n一目会えるなら…\n私はきっとあの人に…", 1, 6193, 1, 102, 8, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボートを漕ぐの、少し\n上手になったんですよ\n今度お見せしますね", 2, 6194, 1, 1, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("航海に向けた\n買い出しが必要ですね\n予定は空いていますか", 2, 6195, 1, 2, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("呪われた財宝の\n解呪依頼が多くて…\nふぅ…えっと次は…", 2, 6196, 1, 3, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の航海では\n父が明かり代わりに\nなってくれるんです", 2, 6197, 1, 4, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("船の上では食材が\n限られるので料理の\nいい練習になります", 2, 6198, 1, 101, 4, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この先もずっと\nあなたと一緒に\nたくさんの思い出を\n作っていきたいです", 2, 6199, 1, 102, 8, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人の寝顔…\nもう少しだけ\n眺めていたいな…", 2, 6200, 1, 1, 1, 122001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("船の上では\n規則正しい生活が\n重要ですから", 2, 6201, 1, 2, 1, 122001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の海は幽霊が\n見分けやすいんです\n青白く光るので", 2, 6202, 1, 3, 1, 122001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に揺られるような\n心地よさですね\n気が休まります…", 3, 6204, 1, 2, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたも一緒に\n海を見に行きますか？\n…なんて。ふふっ", 3, 6205, 1, 3, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("爽やかな香りですね…\n一面の青い海が\n目に浮かぶようです", 3, 6206, 1, 4, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("温かい…\n潮風で冷えた体に\n沁みますね", 3, 6207, 1, 5, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、おいしい…\n日持ちするなら船旅に\n持っていこうかな…", 3, 6209, 1, 7, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンナさんに教えて\nもらった小説は…\nあ、これですね", 3, 6210, 1, 8, 1, 122001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なにもしないを\nしてるんだよ\nあ～いそがしいそがし", 1, 6212, 1, 103, 12, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～あんたといると\nどこまでも気持ちよく\nダラダラできるね～", 2, 6213, 1, 103, 12, 102601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暗黒騎士にして、\n伝説の海賊でもある\n私に不可能はないっ！", 1, 6214, 1, 1, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海賊団の船員、\n随時募集中です…と\nこれで新たな盟友が\n増えるはずだ…！", 1, 6215, 1, 2, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("肩に乗せるペットが\nほしいな。今のうちに\nペット用品を買いに\n行かなくては…！", 1, 6216, 1, 3, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("財宝の地図はどこで\n売っているのだろう…\n古本屋？　古物商？", 1, 6217, 1, 4, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この海賊衣装に\n身を包んでいると\n前世の新たな記憶が\nよみがえってくるな！", 1, 6218, 1, 5, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いずれはシグルドと\n海原への冒険に\n繰り出したいな…\nきっと楽しいぞ！", 1, 6219, 1, 101, 4, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("待ちわびたぞ盟友よ！\n私と貴様あっての\n海賊団…だからその…\n今日はそばにいてくれ", 1, 6220, 1, 102, 8, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シグルド！　港町で\nお魚のおすそ分けを\nもらったんだ！\n一緒に食べよう！", 2, 6221, 1, 1, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シグルドもこのコート\n羽織ってみないか？\nふふっ、きっとすごく\n似合うと思うぞ！", 2, 6222, 1, 2, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海賊船の新たな\n秘密兵器を作ったぞ！\nシグルド、これから\n見に来ないか！？", 2, 6223, 1, 3, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私は伝説の海賊だから\n泳ぐのだって得意だ！\nふ、深いところは\n少し怖いが…", 2, 6224, 1, 4, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、いつ無人島に\n漂着してもいいように\n非常食は準備済みだ\nシグルドの分もある！", 2, 6225, 1, 101, 4, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冥風戦記の新章が\n完成したぞ…！\nシグルド、まずは\n貴様に読んでほしい！", 2, 6226, 1, 102, 8, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふっ、天気明朗\n絶好の航海日和だ！\n早速海に繰り出そう！", 2, 6227, 1, 1, 1, 121901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食用に魚を\n釣っておいたぞ！\nふふ、いかにも\n海賊っぽいだろう？", 2, 6228, 1, 2, 1, 121901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の海は真っ黒で\n少しだけ怖いな…\nシグルド、私の\nそばを離れるなよ…！", 2, 6229, 1, 3, 1, 121901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大海賊がくつろぐのに\n相応しい逸品だ…！\nえっと…これ、どこの\nお店で買えますか？", 3, 6231, 1, 2, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わわ、かわいい…！\n船室のベッドに\n置いておきたいな…\n連れてってはダメか？", 3, 6232, 1, 3, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おぉ、この香りは…！\n集中力が上がりそうだ\n海賊船の船長室に\nぜひ置きたいな！", 3, 6233, 1, 4, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これが船乗りの\n伝承に聞く、海原を\nさまよう神秘の火か！\n…暖まるな！", 3, 6234, 1, 5, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腹が減っては\n海賊はできぬ！\n…小説も書けぬ！", 3, 6236, 1, 7, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("女海賊と騎士はその後\n恋に落ち…？　恋愛\nモノではないかっ！？\nき、興味深くはあるが", 3, 6237, 1, 8, 1, 121901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもの山籠もりが\nブームになるなんて…\n人生、なにが起きるか\n分からないなぁ", 1, 6239, 1, 1, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キャンプ道具…\nいえ、キャンプギア！\nカッコいい響き…♪", 1, 6240, 1, 2, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッツ、ＢＢキャン！\nこのフレーズ\n流行るかも…？", 1, 6241, 1, 3, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キャンプ仲間…\n募集してみようかな？\n友達も兼任で…", 1, 6242, 1, 4, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ユカリさんと\nジュンさん…元気かな\nまた一緒に\nキャンプしたいなぁ…", 1, 6243, 1, 5, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の取材が載った本…\n【フォレスティエ】に\n送らなくちゃ…♪", 1, 6244, 1, 101, 4, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もし、あの人が\n落ち込むことが\nあったら…その時は\n私が力になりたいな", 1, 6245, 1, 102, 8, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ブッシュクラフトは\nマイフレンドくんの\nカスタムにも\n活かせる技術です！", 2, 6246, 1, 1, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("会話に花が咲く…\nって言いますよね\n私の場合、会話相手が\nお花そのものですけど", 2, 6247, 1, 2, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服、実は…\n昔ミサト先生に\nこしらえてもらった\n物なんです！", 2, 6248, 1, 3, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昔はやまびこで会話の\n練習をしてたんです\nほとんどオウム返しで\n気まずかったなぁ～", 2, 6249, 1, 4, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうもマイスターです\n…あ、すみません\nみなさんの期待に\n応えようと練習中で…", 2, 6250, 1, 101, 4, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たとえぼっちを\n卒業しても…\n私は一生ＢＢ団です！", 2, 6251, 1, 102, 8, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("小鳥さんのさえずりで\n目が覚める…\n心地いいものですね", 2, 6252, 1, 1, 1, 122101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キャンプといえば\nおいしいご飯です！\n腕を振るいますよ！", 2, 6253, 1, 2, 1, 122101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すっかり夜ですね…\nおやすみの前に\n星でも見ませんか？", 2, 6254, 1, 3, 1, 122101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("都会でくつろぎ…\n自然の中でくつろぐ…\nくつろぎ無限ループ…", 3, 6256, 1, 2, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しっかり観察すれば\nブッシュクラフトで\n再現できるかも…？", 3, 6257, 1, 3, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～…やっぱり\n木の香りを嗅ぐと\n肩の力が抜けますねぇ", 3, 6258, 1, 4, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ…あったまります\nなんだか心に\nゆとりがでますね…", 3, 6259, 1, 5, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このおいしさ…！\n今度はキャンプに\n持っていこうかな…", 3, 6261, 1, 7, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\nいろんな知識があると\nキャンプはもっと\n楽しくなりますよね", 3, 6262, 1, 8, 1, 122101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋がキャンプ用品で\n埋まっていく…\nキャンプ…なんて\n恐ろしい趣味なの…？", 1, 6264, 1, 1, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕事でも\nアウトドアでも\n頼れるお姉さんに\nなれたらいいなぁ…", 1, 6265, 1, 2, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服、かわいい上に\n本当に快適ね～♪\nおしゃれにキャンプを\n楽しめて最高だわ！", 1, 6266, 1, 3, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん〜次はどんな\nキャンプ飯を\n作ろうかしら？\n彼の好物は、っと…", 1, 6267, 1, 4, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早く週末が\n来ないかしら…\n仕事を忘れてパーっと\nキャンプ飲みを…！", 1, 6268, 1, 5, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しいキャンプ飯の\nレシピを覚えたわ！\n彼も喜んで\nくれるはず…よね♪", 1, 6269, 1, 101, 4, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼の分の食器も\nこっそり買い揃えちゃ\nおうかな…そ、それは\nさすがにまだ早いか…", 1, 6270, 1, 102, 8, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度、財団主催で\n大規模なキャンプを\nやってみるのも\nいいかもしれないわね", 2, 6271, 1, 1, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ソロキャンプも\n悪くはないけど\n私はやっぱりキミと…\nな、なんでもない！", 2, 6272, 1, 2, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キャンプのことなら\n私に聞いて。なんでも\n教えてあげるから！\n…調べた上でね！", 2, 6273, 1, 3, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キャンプ場で飲む\n最高の一杯は\n他じゃ味わえないわ！\nさあ、乾杯っ！", 2, 6274, 1, 4, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うん、決めた！　次は\n禁しゅわキャンプ！\nだってキミとゆっくり\n話したいんだもん♪", 2, 6275, 1, 101, 4, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミのおかげで\n本当の最高の一杯が\n味わえたわ…\nありがとう♪", 2, 6276, 1, 102, 8, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んー、気持ちいい！\nキャンプが趣味に\nなってから、寝覚めが\nよくなったわ♪", 2, 6277, 1, 1, 1, 122201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼は私がごちそう\nするわ。キャンプ飯で\n鍛えた料理の腕前を\n披露しちゃうわよ～！", 2, 6278, 1, 2, 1, 122201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ寝ましょ？\n明日も朝日を眺める\nためにね。もちろん\nコーヒー付きで♪", 2, 6279, 1, 3, 1, 122201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くつろぐのに\n持ってこいね～\nテントの中に置いても\nよさそうだわ！", 3, 6281, 1, 2, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、かわいいわね～\n…今度キャンプ場に\n連れていこうかしら？", 3, 6282, 1, 3, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うん、いい匂い…♪\nキャンプ場を思い出す\n自然の香りだわ〜", 3, 6283, 1, 4, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ、温まるぅ～\n冬のキャンプで\n使ってみたいわね", 3, 6284, 1, 5, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしい～♪\nキャンプ飲みの\nおつまみに\nぴったりね！", 3, 6286, 1, 7, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へえ…こんなキャンプ\n飯もあるんだ？\n彼、好きだったり\nするかな…", 3, 6287, 1, 8, 1, 122201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一生ついててやるの\n幽霊の一生は\nなっが～～～いの！", 1, 6289, 1, 103, 12, 100701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("む～…あんまり触ると\nすり抜けてやるの！\nウソなの。むふふ♪", 2, 6290, 1, 103, 12, 100701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んー…\n今日はベスちゃんと\nなにして遊ぼーかなー", 1, 6291, 1, 1, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヴァンピィちゃんも\nけんぞくの友だちと\n仲良くなりたいな♪", 1, 6292, 1, 2, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("けんぞくのお部屋は\nヴァンピィちゃんが\n守ってあげなくちゃ！", 1, 6293, 1, 3, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お掃除するなら\nヴァンピィちゃんも\n手伝ってあげよー♪", 1, 6294, 1, 4, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふーん、ふーん♪\nけんぞくってこーゆー\nお部屋が好きなんだー", 1, 6295, 1, 5, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひまだなー\nけんぞくをさそって\nお散歩いこっかな♪", 1, 6296, 1, 101, 4, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のスープに\nけんぞくの大好物を\n入れてあげよっと♪", 1, 6297, 1, 102, 8, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("けんぞくー！\nヴァンピィちゃんと\nお出かけしよ♪", 2, 6298, 1, 1, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よしよし！\n今日のけんぞくも\nいい子だね♪", 2, 6299, 1, 2, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んんー…\nやっぱりけんぞくと\nベスちゃんは似てる？", 2, 6300, 1, 3, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いーい？\nヴァンピィちゃんの\nいうこと聞くのよ？", 2, 6301, 1, 4, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヴァンピィちゃんの\nけんぞくだもん！\n大切にするからね！", 2, 6302, 1, 101, 4, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへっ！\nやっぱりけんぞくって\nやさしー匂いがする♪", 2, 6303, 1, 102, 8, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよー…\nヴァンピィちゃんは\nもうちょっと眠るねー", 2, 6304, 1, 1, 1, 122301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヴァンピィちゃん\nひなたぼっこ\nだーいすき！", 2, 6305, 1, 2, 1, 122301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んー！　夜だ♪\nヴァンピィちゃん\n絶好調だよ！", 2, 6306, 1, 3, 1, 122301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わー！\nふかふかだ！\nきもちぃー♪", 3, 6308, 1, 2, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいー♪\nベスちゃんに負けない\n抱き心地！", 3, 6309, 1, 3, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り…なんだろ？\nヴァンピィちゃん\n気に入っちゃった♪", 3, 6310, 1, 4, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいねー…\nヴァンピィちゃん\nずっとここにいるー…", 3, 6311, 1, 5, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はむはむ…\nんー！\nおいしー♪", 3, 6313, 1, 7, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヴァンピィちゃん\nこの本\n好きなんだよねー♪", 3, 6314, 1, 8, 1, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏といえば\nかき氷だよね\n近くにお店は…", 1, 6316, 1, 1, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好でいるのも\nなじんできたし\nちょっと鍛錬でも…", 1, 6317, 1, 2, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("動きやすいけれど…\nいつもと違う服装は\n少し落ち着かないな", 1, 6318, 1, 3, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の空気に\n当てられると思わず\n気が緩んでしまうね", 1, 6319, 1, 4, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("砂浜で走ると\nいい具合に体幹を\n鍛えられそうだ", 1, 6320, 1, 5, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("終わらない夏は\nないけれど…\nつい願ってしまうな", 1, 6321, 1, 101, 4, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("胸を張って彼と\n並び立てるよう\n私も、もっと強く…！", 1, 6322, 1, 102, 8, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたの？\n行きたい場所が\nあるなら付き合おうか", 2, 6323, 1, 1, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("快晴で風は穏やか…\n絶好の釣り日和だね\nさあ、出かけようか", 2, 6324, 1, 2, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日の予定を\n立ててるんだけど…\nキミの希望も\n聞きたいな", 2, 6325, 1, 3, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビーチスポーツか…\nキミとなら\nいい勝負ができそうだ", 2, 6326, 1, 4, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私たちの夏に\n遠慮は無用だよ\n思いきり楽しもう！", 2, 6327, 1, 101, 4, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつかまた一緒に\n花火を見に行こう\n…約束だよ？", 2, 6328, 1, 102, 8, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("潮騒の音で\n目覚めるのも\nいいものだね", 2, 6329, 1, 1, 1, 122501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今朝釣ってきた魚が\nあるんだ。これで\nお昼ご飯にしようか", 2, 6330, 1, 2, 1, 122501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜にもイベントが\nあるみたいなんだ\n一緒に見に行かない？", 2, 6331, 1, 3, 1, 122501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちが安らぐね…\nうっかり眠って…\nしまい…そうだ…", 3, 6333, 1, 2, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("肌触りのよさが\nこの格好だと\nよく分かるよ", 3, 6334, 1, 3, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海をイメージさせる\n香りだね…\n爽やかで落ち着くよ", 3, 6335, 1, 4, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("濡れたままだと\n風邪を引いてしまうよ\nほら、キミもおいで", 3, 6336, 1, 5, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏を楽しみきるには\nエネルギーが\n必要だからね", 3, 6338, 1, 7, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大切な人と過ごせる\n観光スポット紹介…\n…こ、このページは\nもういいかな！", 3, 6339, 1, 8, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("濡らしてもいいなら\n海に持っていって\n乗るのもよさそうだ", 3, 6341, 1, 10, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういう名画を\n見た気がするな…\nこんな視点なんだね", 3, 6342, 1, 11, 1, 122501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着って\n動きやすくて\nいいよねー♪\nいっちにーさんしー♪", 1, 6343, 1, 1, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ユイちゃんにもらった\n日焼け止め\n塗っておいて\nよかった～", 1, 6344, 1, 2, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだか暑いなあ…\nせっかくだし\nプールで泳いで\nこようかな？", 1, 6345, 1, 3, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好で\n出かけようとしたら\nレイさんに\n怒られちゃった…", 1, 6346, 1, 4, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たとえ水着姿でも\n困ってる人を見たら\n助けに行くからね！", 1, 6347, 1, 5, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("バカンス楽しかった～\nまた騎士くんと\n一緒に行きたいな♪", 1, 6348, 1, 101, 4, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この水着、あたしに\n似合ってるかなあ？\n騎士くんはどう\n思ってるんだろ…", 1, 6349, 1, 102, 8, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士くん！\n海に行くなら\n準備運動\n忘れずにね！", 2, 6350, 1, 1, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぐ練習がしたいの？\nいいよ！　水着だから\nなにかあったらすぐに\n助けてあげるね！", 2, 6351, 1, 2, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士くんの水着姿も\nかっこよかったよ！\nまた遊びに行こ！\n約束ね！", 2, 6352, 1, 3, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このグローブの向日葵\nかわいいでしょ？\nユイちゃんが\n選んでくれたんだ♪", 2, 6353, 1, 4, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("実はこの水着\nいつも着てる\n服とおなじなんだ…\nって、冗談だよ？", 2, 6354, 1, 101, 4, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変な日焼けしてないか\n見てもらってもいい？\n…なし！　今のなし！\nやっぱりなしー！", 2, 6355, 1, 102, 8, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏のお日様に\n負けないよう\n今日も元気いっぱい\nがんばるぞー！", 2, 6356, 1, 1, 1, 122401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹減ってきちゃった\n騎士くんはお腹\n空いてない？\n…聞こえちゃった♪", 2, 6357, 1, 2, 1, 122401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も一日\n楽しかったー！\n明日もまた\n楽しもうね！", 2, 6358, 1, 3, 1, 122401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわあ…\nふわふわなのが\nいつもより\nよくわかるよー…", 3, 6360, 1, 2, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうだ！　水着なら\n濡れてもいいし\n今度洗ってあげるね♪", 3, 6361, 1, 3, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んー…いい匂い♪\nなんだか\n身体がぽかぽか\nしてきちゃった！", 3, 6362, 1, 4, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着だから、えっと…\n暖か涼しい…！\n不思議な感じー", 3, 6363, 1, 5, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("思いっきり身体を\n動かした後だから\nいくらでも\n食べちゃえるよー！", 3, 6365, 1, 7, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\nなるほどー\n水着の種類って\nそんなにあるんだぁ…", 3, 6366, 1, 8, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("乗り心地バッチリだね\nしゅっぱつしんこー！\nなんちゃって♪", 3, 6368, 1, 10, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ、ぽよんぽよん！\nトランポリンみたいで\nた～のし～！", 3, 6369, 1, 11, 1, 122401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼のことを考えてると\n幸せで胸が温かくなる\n…私ったら、もう", 1, 6370, 1, 103, 12, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うふふふふ\nくすぐったいわ～♪\nもう、イタズラっ子ね\n次は先生の番よ～♪", 2, 6371, 1, 103, 12, 101501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンの汗\n拭いてあげたいな…\n余計なお世話かな…？", 1, 6372, 1, 1, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏バテ気味かも…\nそうだ、今夜は\nかば焼きにしよう♪", 1, 6373, 1, 2, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("青い空、白い雲\n眩しい日差し…！\n夏って好きだな…", 1, 6374, 1, 3, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒリヒリする…？\n日に焼けちゃったかな\nふー…ふー…", 1, 6375, 1, 4, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("花火大会があるんだ…\n夜、浜辺…2人きり…\nむ、無理だよ〜！", 1, 6376, 1, 5, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着って不思議…\n引っ込み思案が少し\nおさまる…気がする", 1, 6377, 1, 101, 4, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンとまた\n海に行きたいな…\nまた、一緒に…", 1, 6378, 1, 102, 8, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ダ、ダイエット！？\nしてないよ！？\n元々これ位だよ…？", 2, 6379, 1, 1, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スイカ割りのコツ？\nわたしは、騎士クンに\n教わりたいな…", 2, 6380, 1, 2, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クン。うちわで\n扇いであげるね\nどこに置いたかな…", 2, 6381, 1, 3, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うぅ…暑いね…\n騎士クン、温度計は\n見ない方がいいよ～", 2, 6382, 1, 4, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じ、じっと見ないで…\nええっと…ちょっと！\nちょっとならいいよ…", 2, 6383, 1, 101, 4, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え、肝試し？\nう〜ん、うう〜ん…\n…騎士クンとなら！", 2, 6384, 1, 102, 8, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう騎士クン\n見て、あっちの空\nもう入道雲が出てる", 2, 6385, 1, 1, 1, 122601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夕立、来るかなぁ…\nもし雷が鳴ったら\nそばにいてくれる…？", 2, 6386, 1, 2, 1, 122601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しー。…ほら、虫の声\n…わ、わたしの心臓の\n音は気にしないで…！", 2, 6387, 1, 3, 1, 122601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、水着でゴロゴロ\nするのってなんだか…\nいけないことみたい", 3, 6389, 1, 2, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい～♪\n日光浴させて\nあげたいな♪", 3, 6390, 1, 3, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほんのり潮の香りが…\n香ばしくて塩辛くて…\nあ…おなか鳴っちゃう", 3, 6391, 1, 4, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着、乾かせるかも…\nそうだ、みんなの分も\n持ってこよう！", 3, 6392, 1, 5, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏バテなんてしてたら\nみんなの足を\n引っ張っちゃうよね\nいただきます！", 3, 6394, 1, 7, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンの、どうして\n海はしょっぱいの？\nって質問の答えは…\n分かんないよぉ～", 3, 6395, 1, 8, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("顔は怒ってるのに\nなんだかかわいい…\n誰かに似てる…？", 3, 6397, 1, 10, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これを枕に、ビーチで\n騎士クンと…なんて…\nなんて…なんて…！", 3, 6398, 1, 11, 1, 122601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏休み、\n毎日たのしいな～♪\nつぎはなにしよう？", 1, 6399, 1, 1, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自由研究、\nなににしよっかな～？\nプチグリフォンさんの\nかんさつにっきとか？", 1, 6400, 1, 2, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏休みって、\n給食ないから…\nそれはちょっぴり\nさみしいかも…？", 1, 6401, 1, 3, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("砂浜をはだしで歩くの\nきもちいいよね♪\nくすぐったいけど\nミミ、好きなんだ～♪", 1, 6402, 1, 4, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きれいな貝がら\n見つけちゃった♪\nミミのたからもの！", 1, 6403, 1, 5, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミ、浴衣を\n買ってもらったんだ♪\n今度、おにいちゃんに\n見せてあげたいな！", 1, 6404, 1, 101, 4, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミ、おにいちゃんと\nいっぱい夏休みの\n思い出つくりたいな♪", 1, 6405, 1, 102, 8, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、おにいちゃん…\n夏休みの宿題、\nわかんないとこ\nおしえてくれる…？", 2, 6406, 1, 1, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おかあさんにね、\n麦茶つくるの上手って\nほめられたんだ～♪\n飲んでみて♪", 2, 6407, 1, 2, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏休みの宿題で\nポスターかくんだ～♪\nおにいちゃんを\nかいてもいい？", 2, 6408, 1, 3, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("線香花火やりたいな♪\nミミ、長持ちさせるの\n上手なんだよ♪", 2, 6409, 1, 4, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにいちゃんの\n好きな本ってなあに？\nその本で読書感想文\n書こうかな♪", 2, 6410, 1, 101, 4, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海であそんだ後ね、\nおにいちゃんに\n髪を拭いてもらうの\nすきなんだ～♪", 2, 6411, 1, 102, 8, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏休みって、\nワクワクして\n早起きしちゃうよね♪", 2, 6412, 1, 1, 1, 122901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁ♪　お昼は、\n流しそうめんなんだ？\nミミ、流してみたい♪", 2, 6413, 1, 2, 1, 122901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こわい話聞いて、\nねむれないの…\nねえ、おにいちゃん、\nいっしょに寝ていい？", 2, 6414, 1, 3, 1, 122901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっぴりやすんだら\nまた、いっしょに\n海であそぼうね♪", 3, 6416, 1, 2, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すっごくかわいいね♪\nこの子のこと、\n絵日記にかこうっと♪", 3, 6417, 1, 3, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん…\nスイカのにおいだね♪\nこのにおいだいすき！", 3, 6418, 1, 4, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("およいだあとは、\nちゃんと体を\nあっためなくちゃね！", 3, 6419, 1, 5, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏休みのご飯って\nなんだかとくべつ\nおいしい気がするね♪", 3, 6421, 1, 7, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の星座って\nすっごくきれいだね♪\nいつかみんなと\nいっしょに見たいな♪", 3, 6422, 1, 8, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁ♪　この子、\nとってもかわいいね！\nおともだちに\nなりたいな♪", 3, 6424, 1, 10, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミ、人魚姫に\nなったみたい！\nおにいちゃん、\nとなりにすわって♪", 3, 6425, 1, 11, 1, 122901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着姿になると\nバカンス気分を\n味わえちゃうね！", 1, 6426, 1, 1, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に行くの待ちきれ\nなくて、もう水着に\n着替えちゃった！", 1, 6427, 1, 2, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に行ったら\nずぶぬれ系のイタズラ\nたくさんしかけよう！", 1, 6428, 1, 3, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋の中で泳ぎの練習\nしよう！　にいちゃん\nも水着に着替えて！", 1, 6429, 1, 4, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お日さまとお揃いの\n水着なんだ～♪\n似合ってるかなぁ？", 1, 6430, 1, 5, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海といえば冒険！\n海底に眠る財宝を\n見つけちゃおう！", 1, 6431, 1, 101, 4, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんと一緒だと\n部屋にいても海気分♪\nスイカわりしよっか！", 1, 6432, 1, 102, 8, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃん！\n早く海に行く準備\nしなよ～！", 2, 6433, 1, 1, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねーにいちゃん\n何秒息止められるか\n勝負しよーよ！", 2, 6434, 1, 2, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんはアイスと\nかき氷どっちが好き？\nミソギは…どっちも！", 2, 6435, 1, 3, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日焼け止めクリーム\nキョウカに\nもらったんだ～", 2, 6436, 1, 4, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水中メガネがあれば\n水鉄砲くらっても\n平気だね！", 2, 6437, 1, 101, 4, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着なら、毎日夏休み\n気分！　にいちゃんも\n着てみなよ～！", 2, 6438, 1, 102, 8, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんおはよー！\n早く顔洗って、\nいっぱい遊んじゃお！", 2, 6439, 1, 1, 1, 122801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にいちゃんデザートは\nイチゴのかき氷だよ！\n…激辛ってバレた？", 2, 6440, 1, 2, 1, 122801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は楽しかった～！\n明日もイタズラ日和に\nなるといいな！", 2, 6441, 1, 3, 1, 122801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("落とし穴の下に\nやわらかいの置けば\nケガしないよね！", 3, 6443, 1, 2, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいね～！\nこの子も海に\n連れてっちゃおうよ！", 3, 6444, 1, 3, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このにおいを利用して\nイタズラするには…\nにいちゃんどう思う？", 3, 6445, 1, 4, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着を着て暖炉で\nあったまるのって、\n変でおもしろいね～！", 3, 6446, 1, 5, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海辺で食べる\nお昼ごはんって最高♪\nってことで海行こう！", 3, 6448, 1, 7, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか海を越えて、\n地図にも載ってない\n場所を見つけたいな！", 3, 6449, 1, 8, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この口から水が出たら\nみんな驚くよね！\nぷぷ…細工しちゃお！", 3, 6451, 1, 10, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変な音がするイタズラ\nを仕込んどいて…\n誰か座らないかな～♪", 3, 6452, 1, 11, 1, 122801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなた様と私の愛を\n周りに見せつけて\n差し上げましょう♪", 1, 6453, 1, 103, 12, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("呼びましたか？\n呼びましたね？\nでは愛を語りましょう\nそうしましょう", 2, 6454, 1, 103, 12, 102701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着で歩き回るのは\n恥ずかしいな…\n誰も見てないよね？", 1, 6455, 1, 1, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏はやっぱり\nかき氷ですよね\n何色がいいかなぁ…♪", 1, 6456, 1, 2, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人、泳げないって\n聞きました！\n私が教えてあげないと", 1, 6457, 1, 3, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏休みの宿題は\n計画的に進めましょう\n当たり前のことです！", 1, 6458, 1, 4, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("防犯魔石、どこに\n着けておこうかなぁ\n…ここにしようかな", 1, 6459, 1, 5, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の楽しみ方は\n予習済みです！\nあとは実践ですね♪", 1, 6460, 1, 101, 4, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着…きっとあの人に\n見られちゃいますよね\n…褒めてくれるかな…", 1, 6461, 1, 102, 8, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("触りたいんですか？\n…いいですよ\n帽子くらいなら", 2, 6462, 1, 1, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏は体調管理に\n気をつけましょう\n私が管理してあげます", 2, 6463, 1, 2, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に行くのが楽しみで\nたまらないんですか？\n私はそこまで…嘘です", 2, 6464, 1, 3, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもより薄着だから\nなんだか恥ずかしい…\nみ、見ないでください", 2, 6465, 1, 4, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へんたいふしんしゃ～\nえっ？　ああ、これは\n海に叫ぶ練習です", 2, 6466, 1, 101, 4, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと一緒に\n海に行くなんて…\nなんだか大人…えへへ", 2, 6467, 1, 102, 8, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\nさぁ、海に行って\n私と運動しましょう", 2, 6468, 1, 1, 1, 122701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっつ～い…\nはっ！？　ダメですよ\nシャキッとしないと！", 2, 6469, 1, 2, 1, 122701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日も海で\n遊ぶために、しっかり\nお休みしましょうね", 2, 6470, 1, 3, 1, 122701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏を楽しむときは\n休憩も大事ですよね\n計画的に、計画的に！", 3, 6472, 1, 2, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいなぁ～\n海のお土産屋さんに\n売ってるかなぁ？", 3, 6473, 1, 3, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大人な香りがします\n私も違いが分かる\n素敵な女性になります", 3, 6474, 1, 4, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("濡れた体を\n乾かしましょう\nタオル、タオル…", 3, 6475, 1, 5, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳いだ後は\n栄養補給…だけど\n…おなか膨らんじゃう", 3, 6477, 1, 7, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("遊ぶだけじゃなくて\nお勉強もしてますよ\nあなたもどうですか？", 3, 6478, 1, 8, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミが喜びそう…♪\nわ、私ははしゃいだり\nしませんけど…っ！", 3, 6480, 1, 10, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミソギがいたずらに\n使いそう…しっかりと\n試しておかないと！", 3, 6481, 1, 11, 1, 122701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしがまさか\nここにいるなんて…\n自分でも不思議だわ", 1, 6482, 1, 1, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昔みたいにあちこち\n飛び回れないのって\nちょっと不便かも", 1, 6483, 1, 2, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こうして誰かと一緒に\n暮らせるのもあいつや\nみんなのおかげね", 1, 6484, 1, 3, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここで厄介になるなら\nあたしも家事とか\n手伝わないと…", 1, 6485, 1, 4, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…だめ！　誰かの\n世話をせずには\nいられないわ！", 1, 6486, 1, 5, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつたちが\n帰ってくるところだし\n綺麗にしないと…", 1, 6487, 1, 101, 4, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくあたしが\nいるっていうのに\n少しは構いなさいよ…", 1, 6488, 1, 102, 8, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしい店とか\n知らないの？\n食べに行きましょ", 2, 6489, 1, 1, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんた暇でしょ？\nあたしのやること\n手伝いなさい", 2, 6490, 1, 2, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コッコロたんと\n遊んでくるから\n留守番よろしく♪", 2, 6491, 1, 3, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あらおかえり…って\nボロボロじゃない！\nまた人助けしてたの？", 2, 6492, 1, 4, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱりあたしは\nあんたのそばが\n一番落ち着くみたい", 2, 6493, 1, 101, 4, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どこまでだって\nあんたと一緒に\nいてやるんだから", 2, 6494, 1, 102, 8, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ…おはよう\n…大きくなったせいか\n朝は特に体が重いわ", 2, 6495, 1, 1, 1, 123001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯が食べたい？\nしょうがないわね…\nなんか作って\nあげるから", 2, 6496, 1, 2, 1, 123001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたまだ成長期だし\nさっさと寝なさい\n大きくなれないわよ？", 2, 6497, 1, 3, 1, 123001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまにはあたしも\nゆっくりしないと\nもたないのよ…", 3, 6499, 1, 2, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいじゃな～い♪\nコッコロたんに\nプレゼントしたいわ", 3, 6500, 1, 3, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りね\n塔にもこういうの\n置いておこうかしら", 3, 6501, 1, 4, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("炎か…前は\n羽が焼けそうで\n怖かったっけ", 3, 6502, 1, 5, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あむ…妖精に\n体重増減の設定って\nあったっけ…？", 3, 6504, 1, 7, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("記憶のデータと違って\n物語はいいわね\n結末が読めなくて", 3, 6505, 1, 8, 1, 123001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冒険のお土産\nみんなにおすそわけ\nせなあきまへんな", 1, 6507, 1, 1, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おとぎ話よりも\n不思議なことが\nあるもんやねぇ", 1, 6508, 1, 2, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冒険しに出かけるなら\n動きやすい服装に\nせななぁ", 1, 6509, 1, 3, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("地図に水筒に…\n他に忘れもんは\nあらへんやろか？", 1, 6510, 1, 4, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これまでの冒険のこと\nノートに書いて\nまとめてますんよ", 1, 6511, 1, 5, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんとの冒険は\nどれもマホマホ王国の\n大事な歴史や♪", 1, 6512, 1, 101, 4, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どこへ冒険するときも\nうちと王子はんは\n一緒どす♪", 1, 6513, 1, 102, 8, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法で火ぃつける\n練習してますんよ～\nよう爆発しますけど…", 2, 6514, 1, 1, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちと王子はんで\n冒険道具をお揃いに\nするんもええなぁ♪", 2, 6515, 1, 2, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("テント張りも随分\n上達したんよ\n王子はんのおかげやね", 2, 6516, 1, 3, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランスロットたちの\n新しい冒険衣装\n思いついたんよ♪", 2, 6517, 1, 4, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("迷子になっても\n王子はんと一緒なら\nきっと大丈夫やね♪", 2, 6518, 1, 101, 4, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんのこと、\nきっちり守れるように\nなってみせますえ", 2, 6519, 1, 102, 8, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お寝坊さんは\n布団めくって\n起こしにいきますえ～", 2, 6520, 1, 1, 1, 123101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("支度が終わったら\n今日の冒険に\n出かけまひょか", 2, 6521, 1, 2, 1, 123101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうちょっと\nおしゃべりしたいん？\nあと少しだけやで♪", 2, 6522, 1, 3, 1, 123101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冒険で疲れた体に\nこの癒しぱわーは\nあきまへん…すや…", 3, 6524, 1, 2, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、あんさんも\nうちと一緒に\n冒険します？", 3, 6525, 1, 3, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("虫除けのアロマは\n冒険の必需品どす\n忘れんようにせんと", 3, 6526, 1, 4, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちも魔法使わんでも\n火ぃ起こせるよう\n練習せんとあかんなぁ", 3, 6527, 1, 5, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この料理…\n冒険するときに\n作ってみまひょか", 3, 6529, 1, 7, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんとの\n愛と冒険のおとぎ話…\nはぁ…素敵やわぁ♪", 3, 6530, 1, 8, 1, 123101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人との\n最良の未来のために\n占いも霊能力ももっと\n精進しなきゃ", 1, 6532, 1, 103, 12, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたともっと深く\nつながりたいです\n絆も、そして魂までも", 2, 6533, 1, 103, 12, 103101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("絆の契約…\nあやつが望むのなら\n考えぬでもないがのう", 1, 6534, 1, 103, 12, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんじゃ？\nわらわの姿に\n見惚れたかの？", 2, 6535, 1, 103, 12, 104401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("旅の荷物って多いな…\nねぇぷうきち～\nすこしは持ってよぉ～", 1, 6536, 1, 1, 1, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("傘はなくてもいっか\nぷうきちがいるし♪\n『おいなんだと…？』", 1, 6537, 1, 2, 1, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("旅先で人見知りなんか\nしてちゃだめだよね…\nまずはあいさつだ…！", 1, 6538, 1, 3, 1, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おみやげはやっぱり\nご当地ぬいぐるみ\nだよね♪　ワクワク…", 1, 6539, 1, 4, 1, 123201, 0, 0);
