INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("野宿するってことは…\nお兄ちゃんのマントで\n寝るチャンスかも…！", 1, 6541, 1, 101, 4, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんなに危険な冒険も\nお兄ちゃんと一緒なら\n大丈夫！　…だよね？", 1, 6542, 1, 102, 8, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぷうきちのアイマスク\nも腹巻も持ってくの！\n旅の必需品なの～！", 2, 6543, 1, 1, 1, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ全部背負うのって\nけっこうむずかしいの\n順番まちがえると大変", 2, 6544, 1, 2, 1, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ～\nなでなでして？　帽子\nの上からでもいいよ♪", 2, 6545, 1, 3, 1, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『悪いが絆創膏の部分\nはアンタッチャブルだ\n綿が飛び出ちまう』", 2, 6546, 1, 4, 1, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんと一緒に\nもっともっといろんな\n景色が見たいな！", 2, 6547, 1, 101, 4, 123201, 0, 0);
