INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("出発が楽しみすぎて\n寝られなかった…\n『旅行のお約束だな』", 2, 6549, 1, 1, 1, 123201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁ　いいお天気！\n旅の間もずーっと\nぴーかんだといいな♪", 2, 6550, 1, 2, 1, 123201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("知らない場所で寝るの\n怖いな…寝る時だけ\n帰ってこようかな…", 2, 6551, 1, 3, 1, 123201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("旅先にはクッションも\nソファもないよね…\n『俺でいいだろ』", 3, 6553, 1, 2, 1, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬいぐるみのみんな\n旅の無事を\n祈ってて…！", 3, 6554, 1, 3, 1, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("旅先の香りも\n思い出に持って\n帰れたらいいのにな～", 3, 6555, 1, 4, 1, 123201, 0, 0);
