INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("世界ってこんなに広い\nんだ…！　はやく自分\nの目で見てみたいな～", 3, 6559, 1, 8, 1, 123201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はちゃめちゃヒマ～\nなーんか楽し～コト\nないかなー", 1, 6561, 1, 1, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここ、いートコだねー\nこんどカリザきゅんも\nつれてこよー", 1, 6562, 1, 2, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわゆいショタが\n見た～い♪\n触りた～～～い♪", 1, 6563, 1, 3, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんか服きっついなー\nちょい太ったかー？\nん～\nま・気のせーっしょ♪", 1, 6564, 1, 4, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ～やべ\nおねえちゃんに\nメッセすんの忘れたー\nまいっかー", 1, 6565, 1, 5, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パンケーキ食いてー\n騎士きゅん\n誘ってみよーっと♪", 1, 6566, 1, 101, 4, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きょーも～\n好きぴに囲まれて～\nシ・ア・ワ・セ♪", 1, 6567, 1, 102, 8, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アタシと遊ばな～い？\nってなんか\nナンパみスゴー\nウケる～", 2, 6568, 1, 1, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んー？\n今はだるいからパース\nあとでねー", 2, 6569, 1, 2, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カリザきゅん\n見なかった～？\nおねえちゃんから\n逃げるとかオシオキー", 2, 6570, 1, 3, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ネイルしたいけど\n無理なんよねー\n爪の間にめっちゃ\nスライム入っからさー", 2, 6571, 1, 4, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おねえちゃんに\nかまってほし～の？\nかわゆ～い♪", 2, 6572, 1, 101, 4, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("な～に騎士きゅん♪\nここでイチャイチャ～\nし・ちゃ・う～？", 2, 6573, 1, 102, 8, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねんむ～\nけど外から\nショタの声したんで～\nつい起きちった～", 2, 6574, 1, 1, 1, 123301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランチの後はやっぱ\nデザートっしょー\nベツバラってヤツ～♪", 2, 6575, 1, 2, 1, 123301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな時間まで\n起きてるコは～\n食べちゃうぞ～♪", 2, 6576, 1, 3, 1, 123301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あーラクー\nいっしょーここで\nキューケーできるわー", 3, 6578, 1, 2, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なにこれ～\nかわいいじゃ～ん\nショタの次くらいに～", 3, 6579, 1, 3, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いーニオイする～\nなんのニオイとかー\nよくわかんないけどー", 3, 6580, 1, 4, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったか～♪\n溶けてスライム\n戻りそ～", 3, 6581, 1, 5, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ン・ン・ン～♪\nお・い・し～♪\nも～っと食べるぅ～♪", 3, 6583, 1, 7, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わ～なんかムズー\n読めなー\nウケるー", 3, 6584, 1, 8, 1, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんパンって\nお菓子に入るのかな？\nハロウィンで\nもらえたりしない？", 1, 6586, 1, 1, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子をくれなきゃ\nぐうたらするぞ～！\nハロウィン以外でも！", 1, 6587, 1, 2, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お化けになったら\n仕事しないで\nゴロゴロし放題\nなのかな？", 1, 6588, 1, 3, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっと…この仮装\n袖がすごく長いからさ\n引っ掛けないように\n気を付けないとね～", 1, 6589, 1, 4, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イタズラするのも\n体力がいるよね～\n楽にできそうなの\n何かないかな？", 1, 6590, 1, 5, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつって\n仮装とかするのかな？\n似合いそうなのは\nどんなお化けだろ？", 1, 6591, 1, 101, 4, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ずっとハロウィンなら\nあいつと遊び放題\nなんだけどな～", 1, 6592, 1, 102, 8, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今の街はハロウィン\n一色だからね～\n人混みが大変だよ", 2, 6593, 1, 1, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この仮装、どうかな？\n気に入ったなら\n来年もしてあげるよ～", 2, 6594, 1, 2, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("実はこの長い袖\nドングリとかを\nため込めるんだよね…", 2, 6595, 1, 3, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カボチャランタンが\nあるんなら\nドングリランタンも\nあっていいよね～♪", 2, 6596, 1, 4, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンでも\nやる気があれば\nぐうたらできる…\nうん、いいこと言った", 2, 6597, 1, 101, 4, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒にお菓子食べよ？\n寝転びながら堪能する\nハロウィンスイーツは\n最高だからね～", 2, 6598, 1, 102, 8, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お化けは寝る時間…\n今のあたしはお化け…\nだから、おやすみ～…", 2, 6599, 1, 1, 1, 123501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼か～…\n食後のデザートは\nハロウィンのお菓子で\n決まりだね～♪", 2, 6600, 1, 2, 1, 123501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁ～、寝よ…\nお化けは夜に\n出るものだけど\nあたしはリスだからね", 2, 6601, 1, 3, 1, 123501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンを楽しむ\nためにも、ぐっすり\n寝とかないとね～", 3, 6603, 1, 2, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…袖から手が\n出せないから\nこのまま撫でよう\nよしよし", 3, 6604, 1, 3, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リラックスできる\n素敵な香りだね～\n成仏しそうだよ～", 3, 6605, 1, 4, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいね～\nここで寝てもいい？\n…着替えないとダメか", 3, 6606, 1, 5, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…\nお化けもリスも\nお腹は空くんだよ", 3, 6608, 1, 7, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キョンシーって\nどんなお化けなのか\n本で調べようかな？", 3, 6609, 1, 8, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("より取り見取りだね～\nとりあえず、これと\nこのお菓子はキープで", 3, 6611, 1, 12, 1, 123501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よし、衣装もばっちり\nハロウィンパレードへ\n出かけよう♪", 1, 6613, 1, 1, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仮装してても\n剣は手放せないね\nほとんど体の一部だよ", 1, 6614, 1, 2, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見回りに誘うふりして\n二人でパレードに\n参加しちゃおうかな♪", 1, 6615, 1, 3, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…あれ？　手錠の鍵\n落としちゃった…？\nやば、出かける前に\n見つけないと…！", 1, 6616, 1, 4, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お家でコスプレも\nこれはこれで楽しいな\n決めポーズの練習\nたくさんしておこう！", 1, 6617, 1, 5, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("他にも、お姫様に\nメイドさんに学生服…\nやりたいコスプレが\n多すぎるよ～", 1, 6618, 1, 101, 4, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("漫画もゲームも好き！\n仮装するのも大好き！\n…好きを言葉にすると\nもっと好きになる♪", 1, 6619, 1, 102, 8, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ずっと目が合ってるね\n見つめてくれるのは\nいいんだけど、今日は\n衣装を見てほしいな♪", 2, 6620, 1, 1, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トリックオアトリート\nお菓子をくれなきゃ\n逮捕しちゃうぞ♪", 2, 6621, 1, 2, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたにだけはこの姿\nいつでも見せてあげる\nふふ、なんちゃって♪", 2, 6622, 1, 3, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたの？\nイタズラするなら\n隙を突かなきゃ\nこんなふうに、ね♪", 2, 6623, 1, 4, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コスプレしてても\n剣の稽古は休まないよ\nちょっと相手になって\nくれるかな？", 2, 6624, 1, 101, 4, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃっ、びっくりした\n急に触らないでよ～\nハロウィンだからって\nイタズラしないでね？", 2, 6625, 1, 102, 8, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！\n今日も朝から\nパトロールに行こう！", 2, 6626, 1, 1, 1, 123601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カボチャのケーキを\n用意してるよ！\nデザートを食べて\n午後も頑張ろう！", 2, 6627, 1, 2, 1, 123601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暗くなってきたね\nカボチャのランタンに\n火を灯そうよ♪", 2, 6628, 1, 3, 1, 123601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふか気持ちいい～\nあっでも衣装がシワに\nなっちゃうかも…？\n…でも気持ちいい～", 3, 6630, 1, 2, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…かわいい\nこの子もパレードに\n連れて行きたいな", 3, 6631, 1, 3, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～癒される♪\nハロウィンの見回りが\n終わった後は、\nまったりくつろごう", 3, 6632, 1, 4, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここで二人寄り添って\nカボチャスープ飲もう\n…なんて想像したら\nポカポカしてきた…", 3, 6633, 1, 5, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パレードに参加すると\n体力を使うから、\nいっぱい食べておこう", 3, 6635, 1, 7, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この絵本のお姫様\nかわいいね\nこの仮装もいいな♪", 3, 6636, 1, 8, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わあ、おいしそう！\n見回りに行く前に\n少しつまんじゃおう♪", 3, 6638, 1, 12, 1, 123601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日こそは、あの人に\n気持ちを打ち明けて…\nそのあとは…うう\nど、どうしよう？", 1, 6640, 1, 103, 12, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私が剣なら、あなたは\nさしずめ私の鞘…\nふふ、私の帰る\n場所ってことだよ♪", 2, 6641, 1, 103, 12, 103701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱり\nコスプレしてると\nテンションあがる～♪", 1, 6642, 1, 1, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キャラコスにも\n興味あるけど…\nマジカル、ラブリー\nどっちにしよっかな～", 1, 6643, 1, 2, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キャラコスといえば\nミスティーシャイニー\nもいいんだよねえ…\nうはー！　悩むー！", 1, 6644, 1, 3, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギルドハウスで\n宅コスしてる人\n実は結構\nいるんじゃないかな～", 1, 6645, 1, 4, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コスプレだけど普段着\nって言いはれそう…\nって、ダメダメ！\nオタクは節度が大事！", 1, 6646, 1, 5, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フェスで買ってきた\n薄い本～♪\nギルドハウスに持って\nきちゃおっかな～", 1, 6647, 1, 101, 4, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ようこそ\nコスプレ沼へ～\nなんちゃって♪", 1, 6648, 1, 102, 8, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうどう？\nナナカちゃんの\nハロウィンコスプレ\n似合ってる？", 2, 6649, 1, 1, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィン魔法少女\n参上カボ～！\n…やっぱ今の語尾\nナシで！", 2, 6650, 1, 2, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハロウィンといえば\nトリックオア～…\nコスプレ！\nなんちゃって", 2, 6651, 1, 3, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランフェスの\n戦利品～♪\nねえねえ\n見たい？　見たい？", 2, 6652, 1, 4, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私にしてほしい\nコスプレがあったら\n教えて♪　君のために\nや～ってやるぜぇ！", 2, 6653, 1, 101, 4, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒にコスプレしたい\nならナナカちゃんは\nいつでも大歓迎だよ♪", 2, 6654, 1, 102, 8, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁあ…ねむ\nって、ありゃりゃ　\n昨日コスプレしたまま\n寝ちゃってたかあ…", 2, 6655, 1, 1, 1, 123701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のお昼は\nなんにしよ？\nカボチャ料理に\nしよっかな～", 2, 6656, 1, 2, 1, 123701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間かあ\nそういえばオタクって\n夜行性の人が多い\n気がするぜぇ…", 2, 6657, 1, 3, 1, 123701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふっふっふ\nこのパニエは\n座るときはちゃんと\nふにゃってなるのさ！", 3, 6659, 1, 2, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いや～\nかわいいものをみると\n癒されますな～", 3, 6660, 1, 3, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しい薄い本の匂いの\nアロマとか…ダメ？\n私はあの匂い、なんか\n好きなんだよね～", 3, 6661, 1, 4, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖か～い…\nけど近づきすぎて\n衣装が燃えないように\n気を付けなきゃ", 3, 6662, 1, 5, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コス衣装のために\n体型維持は必須だけど\nついつい\n食べちゃうんだよね～", 3, 6664, 1, 7, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっ、次はこの本に\nのってるキャラのコス\nしてみよっかな？", 3, 6665, 1, 8, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おおっ！\nお菓子がいっぱい！\nベルルちゃんチョコ\n入ってないかな～？", 3, 6667, 1, 12, 1, 123701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むっ…\nこの耳の手触り…\n驚嘆に値する…！", 1, 6669, 1, 1, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("獲物を狩りまくる…\nそんなウサギがいても\nいいだろう？", 1, 6670, 1, 2, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワナなど怖くないぞ？\nむしろ積極的に\n踏んでいく性分だ", 1, 6671, 1, 3, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一匹狼ならぬ\n一匹ウサギか\nどっちでもかまわん♪", 1, 6672, 1, 4, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人間とて本を正せば獣\n本能に従えばよいのだ\n遠慮は無用さ☆", 1, 6673, 1, 5, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("脱兎のごとく…\n逃げるものか\n坊やを追い回すのさ♪", 1, 6674, 1, 101, 4, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("獣の道は険しいが…\n坊やめ、音を上げずに\nちゃんとついてきたな\n褒めてやるとしよう♪", 1, 6675, 1, 102, 8, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ニンジンはいらん\n好物は好敵手だ\nさぁどんどんおくれ♪", 2, 6676, 1, 1, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("尻尾に触りたいだと？\nワタシの乱数聖域を\n崩せたらな…☆", 2, 6677, 1, 2, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("頭で考えるな\n体に率直になれ\n己を野放しにするのさ", 2, 6678, 1, 3, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうさモコフワさ♪\nなで心地は最高だが\n意外にどう猛だぞ…？", 2, 6679, 1, 4, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワタシにピョンピョン\n跳ねてほしいのか？\nあとでじっくり、な♪", 2, 6680, 1, 101, 4, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワタシと番になるか？\nオマエさえよければ\nいつでもかまわんぞ☆", 2, 6681, 1, 102, 8, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("太陽と共に目覚め\n活動する\nそれが獣の生き方さ☆", 2, 6682, 1, 1, 1, 123801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼寝をすればいい\nワタシが周囲を\n警戒していてやる", 2, 6683, 1, 2, 1, 123801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暗くなれば眠るだけさ\nそうすれば余計な\nストレスなどたまらん", 2, 6684, 1, 3, 1, 123801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むむっ！？\n尻尾がつっかえて\nうまく座れんな…", 3, 6686, 1, 2, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛らしさでワタシに\n張り合おうというのか\n５億年後に出直せ☆", 3, 6687, 1, 3, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("野生の芳香か…\n本能が呼び覚まされる\nいいセンスだ♪", 3, 6688, 1, 4, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寒さも野生のうちだ\n…とはいえ\n温まっていくか♪", 3, 6689, 1, 5, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪くはないが物足りん\nこう見えて肉食なのだ\n肉はないのか肉は☆", 3, 6691, 1, 7, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ウサギ族は地獄耳？\nワタシとの共通点だな", 3, 6692, 1, 8, 1, 123801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここが私の家…\nそれはこれからも\nずっと変わらないわ…", 1, 6694, 1, 103, 12, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ええと、その…今から\nデート…じゃなくって\n散歩でもどうかしら？\n…ふ、二人きりで…", 2, 6695, 1, 103, 12, 106401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギルドハウスに\nヒーロー参上！\nみんな仲良くッスよ！", 1, 6696, 1, 1, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("料理もできて\n鎧も作れる！\nお母さんはすごいッス", 1, 6697, 1, 2, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ううう…\nまたマントをドアに\n挟んじゃったッス…", 1, 6698, 1, 3, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ずっと鎧を着ていれば\nジュンさんに近づける\nかも？　燃えるッス！", 1, 6699, 1, 4, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サインの練習…\nもっとしておいた\nほうがいいッスかね～", 1, 6700, 1, 5, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("半人前でも\n胸を張るッス！\nそのうち似合う日が\nくるッスから！", 1, 6701, 1, 101, 4, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("種族の違いも\n強い魂があれば\n超えられるッス！\n信じてるッスよ！", 1, 6702, 1, 102, 8, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("困ったときは\n自分を呼ぶッス！\nあと楽しいときにも\n呼んでほしいッス！", 2, 6703, 1, 1, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("特訓でも行くッスか？\n望むところッス！\n目指せ、一人前！", 2, 6704, 1, 2, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しいショーの台本を\n読みこんでるッス！\nところで…この言葉の\n意味、分かるッスか？", 2, 6705, 1, 3, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒミツがなくなると\nなんか恥ずかしいッス\nあんたはどうッスか？", 2, 6706, 1, 4, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒーローは遅れて\nやってくる…\nあんたもそうッスね♪", 2, 6707, 1, 101, 4, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誰よりも早く\nあんたに見せたいッス\n一人前になった自分！", 2, 6708, 1, 102, 8, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん、今日も\nよく眠れたッス～！\n絶好調、間違いなし！", 2, 6709, 1, 1, 1, 123901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おお、もうお昼ッスか\nどうりでお腹が空くと\n思ったッス～えへへ", 2, 6710, 1, 2, 1, 123901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パトロールのあとは\n歯みがきに宿題に…\n大忙しッスね、夜！", 2, 6711, 1, 3, 1, 123901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなにリラックス\nできるなんて…\n平和な証拠ッスね～", 3, 6713, 1, 2, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("か、かわいい…♪\nさあ、自分と握手…\nううん、抱っこッス♪", 3, 6714, 1, 3, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("優しい匂いッスね…♪\nこれくらいみんなを\n包み込めるように\nなりたいッス～", 3, 6715, 1, 4, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひっくちゅ！　うー…\nちょっと冷えるッスね\nぬくぬくするッス～♪", 3, 6716, 1, 5, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("特訓した分、\nいっぱい食べるッス！\nでっかくなるッス！", 3, 6718, 1, 7, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか自分の\nヒミツ図鑑が出たり\nして…いやいやいや", 3, 6719, 1, 8, 1, 123901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("牢獄よりは\nマシな環境ね\n我慢してあげるわ", 1, 6721, 1, 1, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("退屈ね…\nキャルでもいじって\n暇をつぶそうかしら", 1, 6722, 1, 2, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいる連中\n私を天気予報士と\n勘違いしてない？", 1, 6723, 1, 3, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("音波情報が多いわね…\nここ、もう少し静かに\nならないの…？", 1, 6724, 1, 4, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("共同生活なんて\n久しぶりだわ\n…懐かしいわね", 1, 6725, 1, 5, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの子たちのギルド\n経営が雑すぎるわ…！\n教育が必要みたいね", 1, 6726, 1, 101, 4, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とどめを刺される\n準備はできているのに\nまだなのかしら…？", 1, 6727, 1, 102, 8, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私と戦う気になった？\nあら、まだなのね…\nその時を待ってるわよ", 2, 6728, 1, 1, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私というリソースは\n有効活用しなさい\n子守なんてごめんだわ", 2, 6729, 1, 2, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしてそんなに\n頭がいいか？\n生まれつきよ", 2, 6730, 1, 3, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("視力は権能に\n影響しないわよ\n当たり前じゃない", 2, 6731, 1, 4, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたまで天気を\n教えろですって…？\nぶっ殺すわよ？", 2, 6732, 1, 101, 4, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇なら付き合いなさい\n好きなゲームでいいわ\nどうせ私が勝つもの", 2, 6733, 1, 102, 8, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人生朝露…\n悔いのない一日を\n過ごしなさい", 2, 6734, 1, 1, 1, 106901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("午睡はいいわよ…\nふわぁ…眠りは思考に\n必要不可欠なの…", 2, 6735, 1, 2, 1, 106901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夙興夜寝なんて\nやめておきなさい\n休息は大切よ", 2, 6736, 1, 3, 1, 106901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私を満足させるなんて\n大したものね…晶に\n大量生産させるわ", 3, 6738, 1, 2, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キャルの代わりに\nズタズタにする物が\n欲しかったの…♪", 3, 6739, 1, 3, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りじゃない\n見たことのない調合ね\n誰が用意したの？", 3, 6740, 1, 4, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パワーが足りないわね\nもっとよ、もっと私を\n寛がせなさい", 3, 6741, 1, 5, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("栄養価はともかく\n味のバランスは\n悪くないわね", 3, 6743, 1, 7, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("つまらない本は\n私が書き直すわ\nこれはどうかしら？", 3, 6744, 1, 8, 1, 106901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年はアカリと\nお姉ちゃんでサンタが\n二人…つまり幸せも\n二倍ですね♪", 1, 6746, 1, 1, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスに向けての\nサックス練習…\nお兄ちゃんと一緒に\n猛特訓です！", 1, 6747, 1, 2, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスツリーの\n飾りつけ、完璧です♪\nお兄ちゃんお姉ちゃん\n喜んでくれるかな？", 1, 6748, 1, 3, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わあ、お外が真っ白！\n生クリームが\nいーっぱいの\nケーキみたいです♪", 1, 6749, 1, 4, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("煙突から入ると\nお洋服が汚れちゃう…\n玄関からじゃ\nダメなのかなぁ？", 1, 6750, 1, 5, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんが来たら\nサンタのお洋服\nいっぱい褒めて\nもらおっと♪", 1, 6751, 1, 101, 4, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("聖夜をお兄ちゃんと\n過ごせたら…\nアカリもちょっぴり\n大人になれるかも♪", 1, 6752, 1, 102, 8, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今のアカリは\nサンタさんですから♪\nなんでもお願いして\nくださいね？", 2, 6753, 1, 1, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お外は寒いですから\nアカリとくっついて\nお出かけしましょ♪", 2, 6754, 1, 2, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんは\nアカリのトナカイさん\nですから、ずーっと\nそばにいてください♪", 2, 6755, 1, 3, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃん、助けて！\nアカリのカラダで\nラッピング練習したら\n絡まっちゃいました…", 2, 6756, 1, 4, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プレゼント、いっぱい\n準備できました♪\nお兄ちゃんの分は…\nまだヒミツでーす♪", 2, 6757, 1, 101, 4, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アカリ、プレゼントは\n大人っぽいのがいいな\n早くお兄ちゃんに\n追いつきたいから♪", 2, 6758, 1, 102, 8, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます♪\nふふ、アカリサンタは\nいい子のお手本なので\n早寝早起きなんです♪", 2, 6759, 1, 1, 1, 124001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あれ、もうお昼？\nクリスマスナンバーの\n練習してたら\nもうこんな時間…", 2, 6760, 1, 2, 1, 124001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冬の夜空は星が\nキレイですね～\nお兄ちゃん、一緒に\n見に行きませんか？", 2, 6761, 1, 3, 1, 124001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ、快適すぎて\nとろけちゃいそう…\nこういうプレゼントも\nいいかもです…", 3, 6763, 1, 2, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やん、かわいいです♪\nえへへ、お兄ちゃんは\nどんなプレゼントが\n欲しいですか～？", 3, 6764, 1, 3, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わわ、大人な香り…\nロマンチックな\nクリスマスが\n過ごせそうです♪", 3, 6765, 1, 4, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これでカラダを温めて\nアカリの温もり…\nお兄ちゃんに\nおすそ分けしよっと♪", 3, 6766, 1, 5, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹がパンパンです…\nでもこれで\nちょっとサンタさんに\n近づけたかも…？", 3, 6768, 1, 7, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスイブの\n恋人との過ごし方…？\nはわわ、アカリには\nまだ早いかもです…！", 3, 6769, 1, 8, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ、すごいすごい！\n不思議な絵本ですね♪\nこの本でお兄ちゃんに\nイタズラしちゃお♪", 3, 6771, 1, 14, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アカリ、ホカホカに\nなっちゃいました～♪\n…ぎゅってしても\nいいですよ？", 3, 6772, 1, 15, 1, 124001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("またエンジェルになる\nかもとは思ってたけど\n…サンタさん要素の\n追加は想定外だったわ", 1, 6773, 1, 1, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ラフィたちがいない\nときは私がなんとか\nしないとね\n一応…エンジェルだし", 1, 6774, 1, 2, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋の飾りつけとか\nするのも…あり？\nふふ、浮かれすぎかな", 1, 6775, 1, 3, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パーティーだったら\nみんなで大人数向けの\nボードゲームもできる\nかも…やったっ", 1, 6776, 1, 4, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服のモコモコ…\n気づいたら触っちゃう\n…やるわね、ラフィ", 1, 6777, 1, 5, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイツと一緒にいると\n人見知りとは違う\n緊張があるのよね…\nって今の聞いてたっ？", 1, 6778, 1, 101, 4, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬいぐるみ…\nいじめてないわよね？\n…大事にしてるって？\nそれはそれで…あうぅ", 1, 6779, 1, 102, 8, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい子と悪い子って\nどう見分けるのかしら\n…まさか素直さとか？\nだったら困る！", 2, 6780, 1, 1, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プレゼントといえば\nやっぱりゲーム！\n年末商戦サイコー♪", 2, 6781, 1, 2, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サンタさんはお仕事を\n見られちゃ\nいけないのよね？\n…天職？", 2, 6782, 1, 3, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服は汚れ対策も\nバッチリなのよね\n煙突に入れるように\n…いや私はNGよ！？", 2, 6783, 1, 4, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンタのお願い…\n今なら一つくらい\n聞いてあげるわよ？\nほら、サンタ衣装だし", 2, 6784, 1, 101, 4, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私たちって\nなぜかぬいぐるみと\n縁があるわよね\n…ふふ", 2, 6785, 1, 102, 8, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、おはよっ\n…ふぅ、寝ぐせを\n直すのが間に合って\nよかったぁ", 2, 6786, 1, 1, 1, 124101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え…一緒にごはん？\nそ、そう…うん。OK\nまあ、せっかくだし？", 2, 6787, 1, 2, 1, 124101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この時間のゲームって\n妙に楽しいのよね\n…ということで、\nちょっと遊ばない？", 2, 6788, 1, 3, 1, 124101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ～ダメになるぅ…\nもうここでずっと\nゲームしてた～い", 3, 6790, 1, 2, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プレゼントのために\n研究は必要よね、うん\n…はぁ、かわいい～♪", 3, 6791, 1, 3, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("集中力を高める香りも\nあるのよね…\n勝負をするときには\n持ち歩こうかしら", 3, 6792, 1, 4, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだかまったり\nしちゃうわね…\n時間が溶けるわ…", 3, 6793, 1, 5, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹いっぱい\n食べられるのも\n幸せなことよね", 3, 6795, 1, 7, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちっちゃいときは\nアカリと一緒に絵本を\n読んだなぁ…懐かしい", 3, 6796, 1, 8, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("飛び出す絵本…\nこれでゲームブックを\n作ったらおもしろく\nなる気がするわ…", 3, 6798, 1, 14, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったまる…\nモフモフ…ふわふわ…\nちょっと休憩しても…\nいいよね…？", 3, 6799, 1, 15, 1, 124101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら、どうしたの？\nもしかして、私と\n新しい実験を\n始めたくなった？", 1, 6800, 1, 103, 12, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("調子が悪いときは\n診療所に来て\n君は特別に、じっくり\n診察してあげるわ♪", 2, 6801, 1, 103, 12, 105101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("特別じゃなくても\nまったり過ごす\nクリスマスも\nいいものだね", 1, 6802, 1, 1, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ニットの帽子に\nマフラーに耳当て…\n素顔用の防寒対策を\n整えなければ", 1, 6803, 1, 2, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("靴下が\n見当たらなかったから\n枕元にはかわりに\n鎧を置いておこう", 1, 6804, 1, 3, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("聖女なんて言われる程\n素晴らしくはないけど\n心は聖くいたいものだ\n日々精進だね", 1, 6805, 1, 4, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兜がないから\nイルミネーションが\nいつもよりまぶしく\n感じるよ", 1, 6806, 1, 5, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("皆の幸福を\n祈願して\nクリスマスリースを\n飾ろうか", 1, 6807, 1, 101, 4, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私にはかわいすぎる\n衣装だが…開き直って\nクリスマス気分を\n楽しんでしまおう", 1, 6808, 1, 102, 8, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ツリーの飾りつけ\n手伝ってくれるかい？\nセンスは少年に\nお任せするよ", 2, 6809, 1, 1, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パーティーは\n用意してる時も楽しい\nねえ少年、この気持ち\n分かってくれるかい？", 2, 6810, 1, 2, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんでトナカイの鼻は\n赤いのかって？\n無灯ソリ運転は違反で\n取り締まられるからだ", 2, 6811, 1, 3, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トモちゃんや\nマツリちゃんは\nいい子だから、きっと\nサンタさんに会えるね", 2, 6812, 1, 4, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒイラギの髪飾り\n実は気にいってるんだ\n少年にも\n褒めてもらいたいな", 2, 6813, 1, 101, 4, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ少年…そろそろ\n見慣れてほしい\nそんなにまじまじ\n見つめられると照れる", 2, 6814, 1, 102, 8, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝日に照らされて\n街がキラキラ白銀に\n輝いてるよ", 2, 6815, 1, 1, 1, 124201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯を食べて\nちょっと散歩しようか\n祝祭に沸く街は\nとてもきれいだよ", 2, 6816, 1, 2, 1, 124201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱりクリスマスは\n夜が本番って感じだね\nキャンドルを灯して\n厳かに過ごそうか", 2, 6817, 1, 3, 1, 124201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鎧姿では無縁だったが\nふかふかしていて\n気持ちいいな…\nふかふか…ふかふか…", 3, 6819, 1, 2, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、かわいいね\n抱きしめると\nあの雪の日に産まれた\n赤ちゃんを思い出す", 3, 6820, 1, 3, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兜を脱いだおかげで\nこの香りに出会えた\n…クリスマスの魔法も\n悪くないかもね", 3, 6821, 1, 4, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("指先から体の芯まで\n暖まるね\nこれなら雪の日でも\n安心だよ", 3, 6822, 1, 5, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐ、もぐ…\nあまり食べるところ\n見ないでほしい", 3, 6824, 1, 7, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵なレストランの\n特集記事が載ってる\n聖夜に予約が取れたら\n最高に幸せだろうね", 3, 6825, 1, 8, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ！\n…………いや\n驚いてなどいない", 3, 6827, 1, 14, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ…頬に直接\nふかふかを感じられる\n温かくて気持ちいいよ", 3, 6828, 1, 15, 1, 124201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ピアノに読書…\nグレアと一緒に\nなにをしようかな～♪", 1, 6829, 1, 1, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("元の世界へ戻った時\n授業に遅れないよう\nグレアと勉強しとこう", 1, 6830, 1, 2, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("街に魔物料理屋さんが\nあるんだ！　グレアと\n食べに行ってみよう♪", 1, 6831, 1, 3, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかく新しい魔法を\n覚えたし、グレアにも\n見てもらいたいな！", 1, 6832, 1, 4, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("グレアも誘って\nランドソルをもっと\n探索したい！", 1, 6833, 1, 5, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私たちも\nあの人を見習って\nバイトとかしよう！", 1, 6834, 1, 101, 4, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつかあの人を\n私たちの学院に\n招待したいな！", 1, 6835, 1, 102, 8, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのね！\nこれからグレアと\n魔法愛好会に\n行くんだ！", 2, 6836, 1, 1, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これからなにするの？\n私たちもついて行って\nいいかな！？", 2, 6837, 1, 2, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("グレアと一緒に\nあなたも魔法の練習\nしてみない？", 2, 6838, 1, 3, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("グレアとよく話すの\nマナリアの制服\nあなたに着せたいって", 2, 6839, 1, 4, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("グレアのそばって\n温かいんだ～！\nぬくぬくだよ～♪", 2, 6840, 1, 101, 4, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたは\nグレアと私の友達！\nこれからもずっと！", 2, 6841, 1, 102, 8, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！\n今朝はグレアと一緒に\n外を散歩してきたよ！", 2, 6842, 1, 1, 1, 124301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹空いたな…\nよし、グレアと一緒に\n魔物料理を作ろう！", 2, 6843, 1, 2, 1, 124301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間だね\n明日のために\nそろそろ寝ようかな！", 2, 6844, 1, 3, 1, 124301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～この感触…\nグレアの尻尾みたいで\n安らぐ～", 3, 6846, 1, 2, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬいぐるみって\nいいよね…私もよく\nグレアに抱き付くんだ", 3, 6847, 1, 3, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り～…\nグレアもこういうの\n好きなんだよ！", 3, 6848, 1, 4, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいね～…\nグレアにくっついてる\n時を思い出すよ～…", 3, 6849, 1, 5, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この世界にしかない\nおいしいものが\nたくさんあるよね！", 3, 6851, 1, 7, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("世界を繋ぐ魔法の\nヒント…本に書いて\nないかなぁ…", 3, 6852, 1, 8, 1, 124301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ピアノに読書…\n今日のアンは\nなにをするのかな…", 1, 6855, 1, 1, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私はアンほど\n勉強はできないから\nちゃんと自習しないと", 1, 6856, 1, 2, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一度始めたら\nとことん追求するのが\nアンなんだよね…", 1, 6857, 1, 3, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ…夢中になってる\nアンを眺めてるだけで\n一日があっという間…", 1, 6858, 1, 4, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルは広いね…\nアンと一緒にいろんな\n場所へ行ってみたい", 1, 6859, 1, 5, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンやあの人の笑顔を\n見てると、すごく\n安心するんだ…", 1, 6860, 1, 101, 4, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もしあの人が私たちの\n学院に編入したら…\nふふ、楽しそうだね", 1, 6861, 1, 102, 8, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンもあなたも\nすごいな…\nみんなとすぐに\n仲良くなっちゃうから", 2, 6862, 1, 1, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたはこれから\nなにをするの？\nその…アンと一緒に\nついていってもいい？", 2, 6863, 1, 2, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンから魔法の練習に\n誘われた？　実は私も\n…一緒にどうかな？", 2, 6864, 1, 3, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたがマナリアに\n編入したら\n楽しいのになって\nアンとよく話すんだ…", 2, 6865, 1, 4, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっちの世界にも\nアンのように\n私を受け入れてくれる\n人たちがいるんだね…", 2, 6866, 1, 101, 4, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("元の世界へ帰る日が\n来たとしても私たちは\n「さよなら」より\n「またね」がいいよね", 2, 6867, 1, 102, 8, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう。さっき\nランドソルの朝日を\nアンと見てきたんだ", 2, 6868, 1, 1, 1, 124401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私たちは\nこれからなんだけど\nあなたはお昼ごはん\n何を食べたの？", 2, 6869, 1, 2, 1, 124401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ\nアンが眠る時間だ…\nあなたもおやすみ", 2, 6870, 1, 3, 1, 124401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ、疲れが取れる…\nこの尻尾…\nちょっと重いんだよね", 3, 6872, 1, 2, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ…\nアンに見せたら\n喜ぶだろうな…", 3, 6873, 1, 3, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…\nアンの感想も\n聞いてみたいな", 3, 6874, 1, 4, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかい…\nアンがここにいたら\n本を読みながら\n寝ちゃうんだろうな", 3, 6875, 1, 5, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしいからたくさん\n食べれちゃうけど\nまた尻尾…\n大きくなっちゃうかな", 3, 6877, 1, 7, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンがおススメ\nしてくれた本は\nこれかな…？", 3, 6878, 1, 8, 1, 124401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("凶、凶、凶…大凶？\nなによこのおみくじ\n自宅用だからって\n排出率が適当すぎよ…", 1, 6881, 1, 1, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年こそ最高の新薬が\nもはや偶然に近い\n最小限の手間で\n作れますように", 1, 6882, 1, 2, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("喉に詰まる前に\n溶けてなくなるお餅…\n最優先の研究課題だわ", 1, 6883, 1, 3, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よし、完成♪\nミツキ特製…\n「新解釈おせち料理」\n医学的根拠が満載よ", 1, 6884, 1, 4, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お年玉を彼に…\nあげるべき…？\n色んな意味で微妙ね…", 1, 6885, 1, 5, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、今年もまた一年\n彼のバイタルを\n記録できるのね♪", 1, 6886, 1, 101, 4, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年こそ\n私の薬で彼を魔改造…\nううん、大人の男に！", 1, 6887, 1, 102, 8, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コマ回しのコマを\n見てたら目が回った？\nそう…手当は不要よ…", 2, 6888, 1, 1, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の顔で\n福笑いを作った？\nあら…隻眼まで\n再現度が高いわね♪", 2, 6889, 1, 2, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("門松よし、しめ縄よし\nこんなギルドでもね\n一応縁起を担ぐのよ", 2, 6890, 1, 3, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本気の薬草を煮込んだ\n本気の七草粥よ\n色は気にしちゃダメ", 2, 6891, 1, 4, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君が今年も健康で\nつつがなく…実験台を\n務められますように", 2, 6892, 1, 101, 4, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いくつ新年を迎えても\n俗世の垢にまみれない\nそんな君こそが…\n私には最高のお薬よ", 2, 6893, 1, 102, 8, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月なんだから\nいつまでも寝てないで\nさぁ、実験開始よ♪", 2, 6894, 1, 1, 1, 124701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カルタも双六もしたし\nあとは実験くらいしか\nやることがないわね", 2, 6895, 1, 2, 1, 124701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日頃からたいがい\n意味深な夢を見るけど\n初夢はまた別かしら…", 2, 6896, 1, 3, 1, 124701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さすがにこの格好で\n寝正月を敢行するのは\nためらわれるわね", 3, 6898, 1, 2, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("や、闇医者たる者\nこんな愛くるしい物に\n心奪われるわけには…", 3, 6899, 1, 3, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お雑煮のいい香り…\n食欲が増進されるわ\nアロマも立派なお薬ね", 3, 6900, 1, 4, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("胸元は閉じないわよ？\nでも時々ここで\nこっそり暖まるの…", 3, 6901, 1, 5, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("無から有が生まれてる\n新年早々物理の法則を\n無視してくるのね…", 3, 6903, 1, 7, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どれもこれも読んだわ\n新しい婚活本の\n入荷はまだかしら…", 3, 6904, 1, 8, 1, 124701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼が一生懸命\n書いてくれた年賀状\n気持ちがこもっていて\nすごくうれしいわ♪", 1, 6906, 1, 1, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しっかり丁寧に\n大掃除したから\nとってもいい気持ちで\n新年を迎えられたわ♪", 1, 6907, 1, 2, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼の着物姿\nきっと凛々しいわよね\n想像しただけで\n笑顔になるわ～♪", 1, 6908, 1, 3, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お雑煮は地域によって\n違いがあるけれど\n愛情が隠し味なのは\nどこも一緒よね♪", 1, 6909, 1, 4, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼と凧揚げして\n遊びたいけど\n森では引っかかって\nできないかしら…？", 1, 6910, 1, 5, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年も彼が素直に\n成長できるように\nたくさんいい子いい子\nしてあげましょう…♪", 1, 6911, 1, 101, 4, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("絵馬に彼と\n書いた通り\n今年もみんなが笑って\n過ごせますように", 1, 6912, 1, 102, 8, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先生と初詣に\n行きましょう〜♪\n迷子にならないように\n手を繋いで、ね？", 2, 6913, 1, 1, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("初売りセールいいわね\nでも気を付けないと\nあれこれ欲しくなって\n買い過ぎちゃうかも…", 2, 6914, 1, 2, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("風邪をひかないように\n温かくするんですよ～\nえ？　先生、温めて？\nふふ、甘えん坊さんね", 2, 6915, 1, 3, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたのために\nちょっと豪華なおせち\n用意したのよ\nお口に合うかしら？", 2, 6916, 1, 4, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたも着物着たい？\nふふ、貫禄出ちゃって\n先生ドキドキ\nしちゃうかも…♪", 2, 6917, 1, 101, 4, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの成長は\nとってもうれしいけど\n今年もまだ、あなたの\n先生でいたいな…♪", 2, 6918, 1, 102, 8, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら、起きたの？\nお雑煮できてるから\nちゃんとお顔\n洗ってらっしゃいね", 2, 6919, 1, 1, 1, 124601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯を\nしっかり食べて\nみんなでかるた大会\nしましょう〜♪", 2, 6920, 1, 2, 1, 124601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("は～い、良い子は\nもう寝る時間ですよ\n素敵な初夢が\n見られますように♪", 2, 6921, 1, 3, 1, 124601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このフカフカちゃんも\n天日干ししたいけど…\nその前にちょっと\n休憩しちゃおうかしら", 3, 6923, 1, 2, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うふふ、かわいい～\nアオイちゃんや\nハツネちゃんも\nきっと気に入るわね♪", 3, 6924, 1, 3, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月は空気も\n透き通ってるから\nいつも以上に\n素敵な香りに感じるわ", 3, 6925, 1, 4, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("火のぬくもりに\n抱かれていると\n不思議と眠気が…\nふああ…", 3, 6926, 1, 5, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛情のこもった料理は\nおいしいだけじゃなく\n心も満たされちゃう♪", 3, 6928, 1, 7, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月のお作法も\nたくさんあるのね～\n先生も日々勉強だわ～", 3, 6929, 1, 8, 1, 124601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年への感謝をどんな\n形で伝えるべきか…\n言葉よりも物の方が\n良いのだろうか？", 1, 6931, 1, 103, 12, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("話し相手になって\nもらってもいいかな？\n少年と一緒にいると\nとても楽しいんだ", 2, 6932, 1, 103, 12, 104701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月だからって\nギャングのボスは\n油断できないよ～？", 1, 6933, 1, 1, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イノリちゃんがお年玉\n欲しいんだって♪\n悪い子だったし\n10ルピでいいかな☆", 1, 6934, 1, 2, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月だからお雑煮を\n作ったんだけど\nカヤちゃんには\n大好評だったよ♪", 1, 6935, 1, 3, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ラーゴがお餅を\n食べたがってるけど…\nこの子にあげるのは\nちょっと心配かな～？", 1, 6936, 1, 4, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月は晴れ着の子が\nやっぱり多いよね～\n今度、私の漫画でも\n出してみようかな？", 1, 6937, 1, 5, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君と二人っきりで\n神殿に初詣…\n行ってみたいな～♪", 1, 6938, 1, 101, 4, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君とお正月を\n過ごしていると\n面倒なことも\n全部忘れられそう…", 1, 6939, 1, 102, 8, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この着物、どう思う？\n似合ってたら\nうれしいけどな～♪", 2, 6940, 1, 1, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("袖を引っ張ったり\nしないでね？\n着崩れしちゃうから♪", 2, 6941, 1, 2, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月ならではの\n漫画ネタってある？\n参考にしたいんだよね", 2, 6942, 1, 3, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昔は凧あげとか\n駒回しとかしてたけど\n大人になるとそういう\n機会も減るよね…", 2, 6943, 1, 4, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君にもお年玉を\nあげようか？\n好きな額を言ってね☆", 2, 6944, 1, 101, 4, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("来年も、再来年も…\nこうしてみんなで\n新年がお祝いできると\n素敵だね～♪", 2, 6945, 1, 102, 8, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよ～♪\n朝ごはんは\n焼いたお餅とか\nどうかな？", 2, 6946, 1, 1, 1, 124501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼だね～\nおせちを用意したから\nみんなで食べよっか", 2, 6947, 1, 2, 1, 124501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間だね～\n一日中着物だったから\n肩が凝っちゃったよ", 2, 6948, 1, 3, 1, 124501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このまま寝たら\nしわになるかな？\n着替えた方がいい？", 3, 6950, 1, 2, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうのって\nラーゴのおもちゃに\nちょうどいいかも♪", 3, 6951, 1, 3, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りだけど\n着物に移らないように\n気をつけないとね", 3, 6952, 1, 4, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょうどいい\n火加減だね♪\nぽかぽかするよ～♪", 3, 6953, 1, 5, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("着物の時は\nほどほどにしないと…\n欲張ったら、お腹が\n苦しくなるからね～", 3, 6955, 1, 7, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふーん\nイノリちゃんは最近\nこんな漫画を\n読んでるんだ～♪", 3, 6956, 1, 8, 1, 124501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("楽園の気配は…ナシ！\nみんな前を向いてるね\nそうこなくっちゃ！", 1, 6958, 1, 1, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッスンの成果も\nこの格好くらい\n目に見えたら\n分かりやすいのになぁ", 1, 6959, 1, 2, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次の曲はワイルドで\n悪い感じもいいなぁ…\nカヤとムイミちゃん\nみたいなイメージで！", 1, 6960, 1, 3, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私…服、着てるよね？\nうんうん、着てる！\nあんまり体が軽いと\n急に焦る瞬間あるな～", 1, 6961, 1, 4, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近ファンの年齢層が\n幅広くなってきたかも\nこれって私…国民的\nアイドルに近づいた？", 1, 6962, 1, 5, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パティスリーとコラボ\nしたらどんな感じかな\n…ノゾミンマカロン♪\nとか？　…いけるかも", 1, 6963, 1, 101, 4, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼と一緒にいると…\nうれしくって苦しいな\nでも両方諦められない\n…アイドルらしいや", 1, 6964, 1, 102, 8, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好、チカと\nツムギも似合うと\n思うんだけどな～\nキミもそう思うよね？", 2, 6965, 1, 1, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("街を歩いてたらね？\nライブとか写真集の\n告知イベントだって\n思われちゃった！", 2, 6966, 1, 2, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私が持ってた剣に\n結んであったリボン…\n何か気づいてくれた？\nヒントは…色だよ♪", 2, 6967, 1, 3, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミの気配ってすごく\n分かりやすいんだよ\n近くにいたらすぐに\nピンとくるんだ♪", 2, 6968, 1, 4, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、それ…はじめて\nキミにあげた音響盤！\nね、一緒に聴こうよ", 2, 6969, 1, 101, 4, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼうっとしてたら\nイタズラしちゃうよ♪\nもっともっと私のこと\n見てないとダーメ！", 2, 6970, 1, 102, 8, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝は今日のはじまり！\n昨日よりももっと\nいい一日にしようね♪", 2, 6971, 1, 1, 1, 124801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レッスンがんばったし\nまだお昼だし…\nランチ大盛りにしても\nセーフだよね！", 2, 6972, 1, 2, 1, 124801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寝る前に明日の予定を\n確認しておかないと！\nえっと、集合場所は…", 2, 6973, 1, 3, 1, 124801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一休みのつもりが\nなが～い休憩になるの\nあるあるだよね～", 3, 6975, 1, 2, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ノゾミンの熱烈ハグ♪\n…ここだけ聞いたら\nスクープになっちゃう\nかも？　なーんて！", 3, 6976, 1, 3, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("香りってなんだか\n記憶に残るよねー\n…こういうの私だけ？\nみんなも同じだよね？", 3, 6977, 1, 4, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだかライブの\n熱気を思い出して\nきちゃった…！\nレッスンしよっと！", 3, 6978, 1, 5, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹が減ってたら\nいいパフォーマンスは\nできないもんね！\n…んー、おいし～♪", 3, 6980, 1, 7, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい歌詞を書くには\nしっくりくる言葉を\n知っておかないと！", 3, 6981, 1, 8, 1, 124801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うだうだ悩んでる\nヤツがいたら\nオレのとこ連れてこい\n背中押してやるからさ", 1, 6983, 1, 1, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近どことなく\nファミリーの連中が\n浮き足立ってんだよな\n…なんでだ？", 1, 6984, 1, 2, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イノリのヤツ\nやたらと脇腹\nつついてきやがって…\nくすぐったいっての", 1, 6985, 1, 3, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身軽になったのは\nいいが…くそっ\nどこもかしこも\nスースーする…", 1, 6986, 1, 4, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("思い出に浸るのも\n悪くはないが\nやっぱ人間\n未来に生きないとな！", 1, 6987, 1, 5, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("またムイミやノゾミと\nツルむのもいいな\nそこにカレもいたら\nなおいいぜ", 1, 6988, 1, 101, 4, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("未来のことを考えると\nなぜかいつもカレが\n頭に浮かんじまう…\nええい、やめだやめ！", 1, 6989, 1, 102, 8, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっくらオレと\n腕相撲しねえか？\nこの新しい力\n試させてくれ！", 2, 6990, 1, 1, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なあ、悪いが上着\n貸してくれないか？\nこのカッコ、割と\n肌寒いんだよ…", 2, 6991, 1, 2, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっ、生まれ変わった\n喧嘩屋にご用命か？\nいいぜ、キミの\n依頼なら二つ返事だ！", 2, 6992, 1, 3, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんか悩みごとが\nあるなら、なんでも\n話してくれよな\nオレとキミの仲だろ？", 2, 6993, 1, 4, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このカッコが\nきれいだって？\nや、やめろよ…\n照れくさいだろ…", 2, 6994, 1, 101, 4, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミがいると、なにを\nするにも退屈しないぜ\nだから今日も\n付き合ってくれよな！", 2, 6995, 1, 102, 8, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！　新しい\n未来がやってきたぜ！\n一秒だって時間は\n無駄にするなよ？", 2, 6996, 1, 1, 1, 124901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ昼飯に\nしないか？\n穴場のうまい店に\n案内してやるからさ", 2, 6997, 1, 2, 1, 124901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜更かしは\n未来の前借りだ\n体壊さないように\nほどほどにしとけよ？", 2, 6998, 1, 3, 1, 124901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、いいなこれ\nファミリーの\nアジトにも\n置いときたいぜ", 3, 7000, 1, 2, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("べ、別にかわいいもん\nなんて、そんなに\n好きじゃないし…\n嫌いでもないけどさ", 3, 7001, 1, 3, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("嗅いだことない\n香りだな\nなかなか気に入った！", 3, 7002, 1, 4, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("薄着で暖を取るのって\n最高にぜいたくだよな\nへへっ、堪能させて\nもらうとするか", 3, 7003, 1, 5, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こいつはいいや\nこのカッコだと\n消耗が激しくて\nやたら腹が減るからな", 3, 7005, 1, 7, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("甘辛コーデ…\nへぇ、そんなのが\nあるのか…\nわ、悪くねえかもな", 3, 7006, 1, 8, 1, 124901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…\nもっともっと長い時間\n先輩と過ごせたらなぁ", 1, 7008, 1, 103, 12, 105501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ…♪\n先輩が、すぐそばに\nいてくれるなんて…\n幸せだなぁ…♪", 2, 7009, 1, 103, 12, 105501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はーっはっは！\n強くてカッコいい\n大悪党、ここに参上！", 1, 7010, 1, 1, 1, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなおしゃれで\nカッコいいけど\n今のアタシも\n負けてないぞ！", 1, 7011, 1, 2, 1, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギャングのアジトも\nよかったけど\nここも賑やかで\n悪くないな！", 1, 7012, 1, 3, 1, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪党にも休息は必要だ\nここならゆっくり\n休めそうだ！\n邪魔するぞ！", 1, 7013, 1, 4, 1, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いっぱい人がいるな…\nアタシの悪党っぷりを\n広めるチャンスだ！", 1, 7014, 1, 5, 1, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいれば\nいい思い出がたくさん\n作れそうだな！", 1, 7015, 1, 101, 4, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつかアタシも\nオクトーと一緒に\nこんなアジトを手に\n入れてやるからな！", 1, 7016, 1, 102, 8, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん？　アタシの格好が\n気になるのか？\nならもっと近くで\n見てもいいぞ！", 2, 7017, 1, 1, 1, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おい、暇だから\nアタシと遊べ！\nカヤとノゾミも呼んで\n大騒ぎするぞ！", 2, 7018, 1, 2, 1, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オマエ、前より強く\nなってないか！？\nくっそー！　アタシも\n負けてらんないぞー！", 2, 7019, 1, 3, 1, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は特別にアタシの\n思い出話を聞かせて\nやる！　さーて、どの\n悪事から話そうか…", 2, 7020, 1, 4, 1, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オマエとの付き合いも\n結構長くなったよな？\nこれからも\nよろしく頼むぞ！", 2, 7021, 1, 101, 4, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オマエまでいなく\nなったらアタシが困る\n勝手にどっか\n行くんじゃないぞ！", 2, 7022, 1, 102, 8, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("起きろ、起きろー！\n大悪党の朝は早いんだ\nさっさと\n顔洗ってこい！", 2, 7023, 1, 1, 1, 125001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼飯どうしようか…\nそうだ！　オマエの\nおススメに連れてけ！\nいい店期待してるぞ！", 2, 7024, 1, 2, 1, 125001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日を思い切り\n楽しむためにも\n早く寝とけよ！\nまた明日な！", 2, 7025, 1, 3, 1, 125001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こうやって座ると…\nおお！　すっごく悪党\nっぽいぞ！", 3, 7027, 1, 2, 1, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オマエ、仲間に\nなりたそうな目を\nしてるな！", 3, 7028, 1, 3, 1, 125001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うん、いい匂いだ！\n何の匂いかは全然\n分かんないけどな！", 3, 7029, 1, 4, 1, 125001, 0, 0);
