INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("女の子をすぐ家に\nあげちゃうなんて…\nふふ、やっぱり隅に\n置けないですねー★", 2, 7044, 1, 3, 1, 118201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さん騎士さーん★\nウザ絡みしても\nいいですかー？\n騎士さんってばー★", 2, 7045, 1, 4, 1, 118201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒にゴロゴロ\nしませんかー？\nコイビトっぽくて\n楽しそうですし♪", 2, 7046, 1, 101, 4, 118201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うふふ★\nこーやってあなたに\n優しくされると…\nときめいちゃいます♪", 2, 7047, 1, 102, 8, 118201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます★\nあれれー？\nまだおねむですかー？", 2, 7048, 1, 1, 1, 118201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さん、お昼は\nもう食べましたー？\nわたし、ラーメンが\n食べたいでーす★", 2, 7049, 1, 2, 1, 118201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、夜更かししてちゃ\nダメですよー？\nほらほら、お布団に\nごーごー★", 2, 7050, 1, 3, 1, 118201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかのふわふわー\nついついまーったり\nしちゃいます★", 3, 7052, 1, 2, 1, 118201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かっわいー★\n名前はー、んー…\nぱんぱかぷんで★", 3, 7053, 1, 3, 1, 118201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん★\nうーん…\nたぶん素敵な香り♪", 3, 7054, 1, 4, 1, 118201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかーい★\n心も体も\nぽっかぽかですねー★", 3, 7055, 1, 5, 1, 118201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ★\nんー、おいしくって\n止まらないですねー★", 3, 7057, 1, 7, 1, 118201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へー★\nほほー★\nふんふーん★", 3, 7058, 1, 8, 1, 118201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さ～て時間もあるし\nラテアートの練習でも\nするかにゃ～♪", 1, 7060, 1, 1, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カフェの猫たちも\n元気に働いてくれて\nお客さんからの評判も\n上々にゃ～♪", 1, 7061, 1, 2, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カフェのカウンターに\nファントムキャッツの\n目安箱を置こうかにゃ", 1, 7062, 1, 3, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんこもコーヒーも\n原料は豆にゃ～\nそりゃ相性いいに\n決まってるにゃ♪", 1, 7063, 1, 4, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつの為に\nタマキ特製ブレンドを\n開発したいにゃ♪", 1, 7064, 1, 5, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつと働いてると\nなぜかあっという間に\n閉店時間が\n来ちゃうのにゃ～", 1, 7065, 1, 101, 4, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつといると\n新しいアイデアが\n溢れるほど\n出てきちゃうのにゃ♪", 1, 7066, 1, 102, 8, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミがコーヒーを\n淹れてくれたのにゃ？\nにゃはは、常温で\n猫舌にも優しいにゃ♪", 2, 7067, 1, 1, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("料理が上手くなったら\nカフェご飯メニューも\n充実させたいにゃ～", 2, 7068, 1, 2, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お店の経営は大変\nだけど、キミとなら\n乗り越えられるって\n確信してるにゃ！", 2, 7069, 1, 3, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん？　この制服\n似合ってるにゃ？\nにゃはは！　褒めても\n１ルピも出ないにゃ♪", 2, 7070, 1, 4, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしが好きなのは\n猫に好かれる人にゃ♪\n…ん、キミ猫に懐かれ\nまくってるにゃ…", 2, 7071, 1, 101, 4, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミの制服姿\nけっこーイケてるにゃ\nあたしがお客さんなら\n通いつめちゃうにゃ♪", 2, 7072, 1, 102, 8, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝は一杯の\nコーヒーから始まる…\nにゃふふん♪\nシャレた朝だにゃ～♪", 2, 7073, 1, 1, 1, 125101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼はたい焼きと\nコーヒーのセットで\nまったり休憩\nしようにゃ～♪", 2, 7074, 1, 2, 1, 125101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コーヒー淹れたにゃ\n星空を見ながら\n二人で飲もうにゃ…♪", 2, 7075, 1, 3, 1, 125101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふにゃ～ん…ゴロゴロ\nコーヒーと同じくらい\n癒されるにゃ～…♪", 3, 7077, 1, 2, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こいつかわいいにゃ～\nうちの猫たちとも\nいい勝負なのにゃ！", 3, 7078, 1, 3, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～いい香りだにゃ～\nコーヒーもそうだけど\n香りの癒し効果は\n抜群にゃ～♪", 3, 7079, 1, 4, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("猫に暖かいものは\nまるまれと言ってる\nようなもんにゃ…♪\nまるまる…", 3, 7080, 1, 5, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃは～うまいにゃ♪\nカフェの新メニューに\n採用しちゃおう\nかにゃ～♪", 3, 7082, 1, 7, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃるほど…\n調べれば調べるほど\nコーヒーは\n奥が深いのにゃ…", 3, 7083, 1, 8, 1, 125101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワタシの手料理は\n坊やの口に合うらしい\n胃袋は討ち取ったぞ♪", 1, 7085, 1, 103, 12, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("胸に再度触れると\n誓約は無効になるのか\n…だと？　鋭い質問だ\n安心しろ。ならん☆", 2, 7086, 1, 103, 12, 107101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ようやくこの服にも\n慣れてきたかな？\nふふっ、たまには\nこういう服も悪くない", 1, 7087, 1, 1, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も店は好調だが、\n私は軍人だからな\n当初の目的も\n忘れないようにしよう", 1, 7088, 1, 2, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("猫が近くに来ると\nついつい見てしまうな\n仕事が終わったら\n遊んでやるかな♪", 1, 7089, 1, 3, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コーヒーの淹れ方が\nうまくなってきたな♪\nどうせならお菓子も\n研究してみるか！", 1, 7090, 1, 4, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("利益を考えると\n価格をあげるべきか？\n…いや、利益よりも\n皆の笑顔の方が大事だ", 1, 7091, 1, 5, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("またあいつを\n呼んでしまったな…\n今度、コーヒーでも\n淹れて労ってやるか♪", 1, 7092, 1, 101, 4, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次に入荷するお菓子は\nあいつの意見を聞くか\nどんな味が好きか\n気になるしな", 1, 7093, 1, 102, 8, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なに、コーヒーを\n淹れてほしい？\nふふっ♪\n仕方のない奴だな！", 2, 7094, 1, 1, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…そうだ。\nコーヒーと乾パンは\n合うのではないか？\n今度試してみよう！", 2, 7095, 1, 2, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コーヒーもいいが、\nココアも悪くないぞ♪\n貴公も一緒にどうだ？", 2, 7096, 1, 3, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女に比べれば\n大人しい服だろう？\nだが、カフェには\nこの服でバッチリだ！", 2, 7097, 1, 4, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴公はコーヒーを\n飲めるのかっ？それは\nうらやましいな…", 2, 7098, 1, 101, 4, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴公の働きぶりには\n目を見張るものがある\nその姿は、その…\n結構かっこいいぞっ！", 2, 7099, 1, 102, 8, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さぁ、今日も一日、\n頑張るぞっ！\n気合いを入れて\n開店準備だっ！", 2, 7100, 1, 1, 1, 125201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼は稼ぎ時だからな！\n荒波を乗り切るため\n貴公も一緒に\n頑張ってくれるか？", 2, 7101, 1, 2, 1, 125201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふあぁ…もう夜か\n今日は頑張ったからな\nはやめに休むとしよう", 2, 7102, 1, 3, 1, 125201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はふぅ～…\nたまにはこうして\nゆったりするのも\n悪くないな…", 3, 7104, 1, 2, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("猫もかわいいが、\nこいつもなかなか…\n見ていると、\n撫でたくなるな♪", 3, 7105, 1, 3, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは良い香りだな\nふむ、コーヒーも\nより香り高いものが\n作れるよう試すか！", 3, 7106, 1, 4, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ～…\n体を温めなければ、\nすぐに動けないからな", 3, 7107, 1, 5, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これもうまいが、\n私はお菓子も…\nいや、食べすぎは\n体に良くないな", 3, 7109, 1, 7, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…書物は参考になるな\n次はこのやり方を\n試してみるかな", 3, 7110, 1, 8, 1, 125201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛と希望の魔法少女！\n弟くんの平和は\nお姉ちゃんが守るよ♪", 1, 7112, 1, 1, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女の戦い方を\n見せてあげる！\nお姉ちゃんチョップ♪", 1, 7113, 1, 2, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("闇の力が高まってる…\n早く弟くんを\nギュ～ってしないと！", 1, 7114, 1, 3, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミニ弟くんを\n部屋中に呼び出して\n弟くんハウスに～♪", 1, 7115, 1, 4, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("決めポーズの練習でも\nしよっかな…\nはい、ポーズ♪", 1, 7116, 1, 5, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女の力で\n弟くんのそばに\n瞬間移動したいなぁ", 1, 7117, 1, 101, 4, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("禁じられた必殺技\nその名も──\n闇のお姉ちゃん頭突き", 1, 7118, 1, 102, 8, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女な\nお姉ちゃんに\n興味津々だねっ？\n全部教えてあげるね♪", 2, 7119, 1, 1, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("闇のお姉ちゃんとして\n世界を弟くんのものに\n…な～んて冗談冗談♪", 2, 7120, 1, 2, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんって魔法少女に\nなりたがってたよね？\n…うん。応援するね！", 2, 7121, 1, 3, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サインが欲しいの？\nふふっ、任せて！\n愛する弟くんへ、と♪", 2, 7122, 1, 4, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふんふふ～ん♪\n魔法少女お姉ちゃんの\nテーマソング完成っ♪", 2, 7123, 1, 101, 4, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ、弟くんからの\n愛と希望を感じるよ…\n更に変身しちゃうぞ♪", 2, 7124, 1, 102, 8, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんの朝を魔法で\n守りに来たよ！\n希望の朝だねっ♪", 2, 7125, 1, 1, 1, 120001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんのお昼を魔法で\n守りに来たよ！\n愛のお弁当をどうぞ♪", 2, 7126, 1, 2, 1, 120001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんの夜を魔法で\n守りに来たよ！\nここからは闇の時間♪", 2, 7127, 1, 3, 1, 120001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法少女の一休み♪\n愛と希望と…闇の力が\n回復していくね～♪", 3, 7129, 1, 2, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいかわいい♪\nお姉ちゃんの魔法で\n増やしちゃうぞ…♪", 3, 7130, 1, 3, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り…\n弟くんと同じ…\nくんくん、くんくん…", 3, 7131, 1, 4, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体を温めておいて…\nこの熱を、ぜ～んぶ\n弟くんに伝えるよ…！", 3, 7132, 1, 5, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミニ弟くんを呼ぶには\nいっぱい食べないと…\n魔法ってお腹減るから", 3, 7134, 1, 7, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんの平和を守る…\nそのためには\nチェックチェック…♪", 3, 7135, 1, 8, 1, 120001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服も、最初は\n慣れなかったのですが\n今ではすっかり\n体に馴染んでおります", 1, 7137, 1, 1, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自然を守るためにも\nお勉強は欠かせません\n日々精進でございます", 1, 7138, 1, 2, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("採取した薬草を\n調合しておきましょう\nいつ必要になるか\n分かりませんからね", 1, 7139, 1, 3, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("合宿は過酷でしたが\nおかげでちょっと\n力持ちになったような\n気がいたします…♪", 1, 7140, 1, 4, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わんわんのほうの\n主さまに、ごはんを\nあげる時間ですね…", 1, 7141, 1, 5, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もっともっと訓練や\nお勉強を重ねて\n主さまのお役に\n立たなくては…", 1, 7142, 1, 101, 4, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おや、そろそろ\nわんわんのほうの\n主さまをお散歩に\n連れていく時間です", 1, 7143, 1, 102, 8, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さま、よろしければ\nお散歩に行きませんか\n今日の森は穏やかで\n過ごしやすいかと", 2, 7144, 1, 1, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わんわんのほうの\n主さまも、今では\n【美食殿】の大切な\n仲間でございます", 2, 7145, 1, 2, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("森には危険が\nいっぱいでございます\nケガをなさらないよう\nお気をつけください", 2, 7146, 1, 3, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もし森や動物のことで\n気になることがあれば\n気軽にお尋ねください", 2, 7147, 1, 4, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("森へ行く前には\n必ず装備の点検を\nお願いいたします\n約束ですよ、主さま？", 2, 7148, 1, 101, 4, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("森の中で主さまたちと\nゆったり過ごす時間は\nわたくしにとって\n大切なひとときです", 2, 7149, 1, 102, 8, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n朝ごはんをしっかり\n食べて、お勤めに\n備えましょう", 2, 7150, 1, 1, 1, 125301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わんわんのほうの\n主さまにおやつを\nあげる時間です\nどうぞ、召し上がれ", 2, 7151, 1, 2, 1, 125301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どれだけ野営に\n慣れたとしても\nベッドで眠れるなら\nそうしたいところです", 2, 7152, 1, 3, 1, 125301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こちらなのですが\nわんわんのほうの\n主さまもお気に入りの\nようです", 3, 7154, 1, 2, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わんわんのほうの\n主さまにも、こうした\n玩具を与えるべき\nでしょうか…？", 3, 7155, 1, 3, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("心地よい香りです\n次は、自然由来の\n香料も試しましょう", 3, 7156, 1, 4, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖をとるのは\n野営の時などに\nとても大事なことで\nございますね", 3, 7157, 1, 5, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べられる時に食べて\nおくのも、大自然では\n重要でございます", 3, 7159, 1, 7, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("より知識を蓄え\n自然の力を活用できる\nようにいたしましょう", 3, 7160, 1, 8, 1, 125301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今回の「冥風戦記」も\nなかなかよく書けたぞ\nふふっ、シグルドも\n喜んでくれるかな？", 1, 7162, 1, 103, 12, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴様のためならば\n我が真なる魔力\nいつでも\n解き放とうぞ！", 2, 7163, 1, 103, 12, 100901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ニャットちゃんに\nブラッシングを\nしてあげようかな", 1, 7164, 1, 1, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ…\nこれがレンジャーの\n制服ですか", 1, 7165, 1, 2, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ\nパトロールの\n時間だ…", 1, 7166, 1, 3, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔物について\nもっと知りたいな\n本を探しに行こう", 1, 7167, 1, 4, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レンジャーになって\n体調を崩す日が\n減った気がします…", 1, 7168, 1, 5, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本だけじゃわからない\n世界のことを、\nもっと知りたいです…", 1, 7169, 1, 101, 4, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな私にも\nできることはある…\nそう信じています", 1, 7170, 1, 102, 8, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの…良かったら\n一緒に見回りへ\n行きませんか？", 2, 7171, 1, 1, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("またあなたと一緒に\nレンジャーの仕事が\nできたらうれしいです", 2, 7172, 1, 2, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("けほっこほっ\n…だ、大丈夫です\nたまに出るだけなので", 2, 7173, 1, 3, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ニャットちゃん\nあなたにも\n懐いてきましたね", 2, 7174, 1, 4, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ニャットちゃんと\n散歩に出かけようかな\n…あの人も誘って", 2, 7175, 1, 101, 4, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと肩を並べて\nレンジャーの仕事が\nできてうれしいです…", 2, 7176, 1, 102, 8, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\nレンジャー・シオリ\n元気に出勤します", 2, 7177, 1, 1, 1, 125401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ニャットちゃんにも\nお昼ごはんを\n用意しなくちゃ", 2, 7178, 1, 2, 1, 125401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日は仕事だから\n早起きしなくちゃ\nおやすみなさい", 2, 7179, 1, 3, 1, 125401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…仕事で\n走り回ったので\n少し休憩します", 3, 7181, 1, 2, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕事が終わった後に\nこうして触れていると\n癒されますね…", 3, 7182, 1, 3, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("森の香りがします…\n今日はよく\n眠れそうです…", 3, 7183, 1, 4, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ニャットちゃんと\n同じぐらい\n暖かいです…", 3, 7184, 1, 5, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レンジャーの仕事を\nしていると\nお腹が空きます", 3, 7186, 1, 7, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんなに忙しくても\n読書だけは\nやめられませんね", 3, 7187, 1, 8, 1, 125401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兄様のお留守の間\nわたくしが、兄様の\n御家を守ります！", 1, 7189, 1, 1, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("に、に、兄様の御家…\n招待いただいた以上は\n失礼のないよう\n振る舞わなくては…！", 1, 7190, 1, 2, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ…兄様の素敵な\nお人柄が、家中から\nにじみ出ています…♪", 1, 7191, 1, 3, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("靴を脱がずに\n御家に上がるのに\n慣れていなくて…あ！\n飛べばいいのでは…！", 1, 7192, 1, 4, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここに花を生けたら\n華やぎそうですね\n兄様はお花…\n好きでしょうか…？", 1, 7193, 1, 5, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ずっとここにいたい…\nなどと言ったら\n兄様を困らせて\nしまいますよね…", 1, 7194, 1, 101, 4, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お料理などを作って\n兄様を出迎えられたら\nいいのに…料理の腕も\n磨かなくては…！", 1, 7195, 1, 102, 8, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このような姿で\n失礼しております…！\nネ、ネズミがいたので\nつい本気を…！", 2, 7196, 1, 1, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おかえりなさいませ\nお忙しい御身をどうぞ\n癒してくださいね", 2, 7197, 1, 2, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兄様の話し相手…！？\nど、どうしましょう…\nわたくしには面白い\n話なんて…はうぅ…！", 2, 7198, 1, 3, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なぜか、動物などに\n好かれる体質で…\n迷い猫捜しのバイトの\nお役に立てますか？", 2, 7199, 1, 4, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("に、兄様の家に来たら\n『添い寝』をするのが\n礼儀とリアさんが…\n本当…でしょうか？", 2, 7200, 1, 101, 4, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたくしはここに\nいて…よいのですね？\n『仲間』として…", 2, 7201, 1, 102, 8, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝は得意なんです\nもし兄様が苦手なら\nわたくしが起こして\n差し上げますよ", 2, 7202, 1, 1, 1, 125801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兄様…昼餉を作って\nみたのですが、失敗\nしてしまいました…", 2, 7203, 1, 2, 1, 125801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふあぁ…\nはっ！　お…\nお恥ずかしい所を…！", 2, 7204, 1, 3, 1, 125801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こ、これは…！\n人様の御家なのに\nつい…駄目になって…\nしまいますぅ…！", 3, 7206, 1, 2, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("と、飛びかかっては\nこない…ですよね…？", 3, 7207, 1, 3, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すぅ…はぁ…\nこのかぐわしさ\n心が洗われます…", 3, 7208, 1, 4, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんて暖かい…\n兄様の優しくお広い\n御心のようです…♪", 3, 7209, 1, 5, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなに食べていたら\nはしたない…\nでしょうか？", 3, 7211, 1, 7, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兄様の本棚はまるで\n知識の宝庫ですね\n己の世間知らずぶりを\n実感してしまいます", 3, 7212, 1, 8, 1, 125801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次の冒険に向けて\n騎空士弁当を作ろっと\nまずはおにぎりから！", 1, 7214, 1, 1, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法の修行しなくちゃ\nもっともっと頼れる\n団長になりたいから！", 1, 7215, 1, 2, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビカラちゃんを\n遊びに誘いたいけど…\nどういう場所が\n好きなんだろう？", 1, 7216, 1, 3, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕事を真面目に\nしっかりこなすことが\n騎空艇への\n一番の近道だよね", 1, 7217, 1, 4, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいる人の中で\n騎空団に興味ある人\nいたりしないかな…？", 1, 7218, 1, 5, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これまでも想い出は\nいっぱいできたけど…\nこれからもたくさん\n想い出を作りたいな！", 1, 7219, 1, 101, 4, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仲間がいるから\n騎空士は限界だって\n超えられるんだね", 1, 7220, 1, 102, 8, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この衣装\n魔法使いらしいでしょ\n服に着られないよう\n頑張らなくちゃね！", 2, 7221, 1, 1, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたとなら\nどんな相手だって\n怖くなんてないよ！", 2, 7222, 1, 2, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カリンさんから\n新しい依頼が来たよ！\n一緒に頑張ろ！", 2, 7223, 1, 3, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("操舵士になるのは\nずいぶん難しそう…\nいつか頼れる仲間が\n見つかるといいな", 2, 7224, 1, 4, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("手合わせしたいの？\nいいよ、たまには\n団長らしいところ\n見せてあげるね！", 2, 7225, 1, 101, 4, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだ二人きりだけど…\nこの騎空団は\n私の宝物だよ！", 2, 7226, 1, 102, 8, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう～…\n昨日は遅くまで\n魔法の研究してて…\nふわぁ…眠いなぁ…", 2, 7227, 1, 1, 1, 125501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さてと、お昼休み！\n紅茶淹れてくるから\n一緒に飲もうよ！", 2, 7228, 1, 2, 1, 125501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("遅くまでお疲れさま！\n無理しない程度に\nお互い頑張ろう！", 2, 7229, 1, 3, 1, 125501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法の研究は\n一旦、休憩！\n頭を休めなくちゃ", 3, 7231, 1, 2, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法みたいに\nかわいい！\n騎空団に入る？\nなんてね！", 3, 7232, 1, 3, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい匂い…\nそれになんだか\n集中力が増したかも", 3, 7233, 1, 4, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体だけじゃなくて\n心までポカポカする…\nなんだか魔法みたい", 3, 7234, 1, 5, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いろいろ考え事したら\nお腹が空いちゃった！\nいただきまーす！", 3, 7236, 1, 7, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『摂理の彼方へ\n至るには…』\n…この魔導書\n勉強になるなあ", 3, 7237, 1, 8, 1, 125501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こちらの服を着ると\n冒険に出かけたく\nなっちゃいますね", 1, 7239, 1, 1, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冒険者の心得その一\n準備はできる限り\nしっかりとこなすべし\nなんてどうでしょう？", 1, 7240, 1, 2, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("調合に必要な素材は\nあれとこれとそれと…\n時間があるとついつい\n考えちゃいますね", 1, 7241, 1, 3, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくですから\nより良い素材を\n自分で集めたいですね", 1, 7242, 1, 4, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このポーションが\nみなさんの役に立つと\nうれしいですね", 1, 7243, 1, 5, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冒険者の心得その二\n危なくなった時は\nまず逃げるべし！\n大事なことですね", 1, 7244, 1, 101, 4, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人の冒険は\nいつも楽しそうで\n元気がもらえます", 1, 7245, 1, 102, 8, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぜひおすすめしたい\n依頼があるんです\nこちらをどうぞ♪", 2, 7246, 1, 1, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほしいお薬があれば\n錬金術で作って\nさしあげますよ", 2, 7247, 1, 2, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("依頼で気になる\nところがあれば\n何でもご確認ください", 2, 7248, 1, 3, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このギルドハウスに\n錬金術の実験設備を…\nえ？　だめですか？", 2, 7249, 1, 4, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ポーションをどうぞ\n大丈夫、効果は\n確認済みですので♪", 2, 7250, 1, 101, 4, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はどんな冒険に\n行かれるんですか？\nいつでもお供しますよ", 2, 7251, 1, 102, 8, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もいい一日に\nなりそうですね\n冒険日和といった\nところでしょうか", 2, 7252, 1, 1, 1, 125701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい時間ですし\nランチにしませんか？\n次の冒険の\n作戦会議も兼ねて♪", 2, 7253, 1, 2, 1, 125701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜も遅いですし\n明日の冒険のため\n今日は早く寝ましょう", 2, 7254, 1, 3, 1, 125701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふう…やはり冒険は\n事務仕事と違いますね\n少し休憩を…", 3, 7256, 1, 2, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冒険は緊張の連続です\nかわいい物で\n心を癒しましょう", 3, 7257, 1, 3, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ、この香りは…\n素晴らしいバランスで\n調合されていますね", 3, 7258, 1, 4, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この火力…\n錬金術の調合に\n使えそうですね", 3, 7259, 1, 5, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冒険の際は食べられる\n時に食べておく！\n…とペコリーヌさんも\nおっしゃってましたね", 3, 7261, 1, 7, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…なるほど\nこんな調合も\nあるのですね…\n奥が深いです", 3, 7262, 1, 8, 1, 125701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイツどこ行った…？\n戦うならアタシも\n連れてけよなー！", 1, 7264, 1, 103, 12, 106101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も悪いヤツ退治…\nの前に腹ごしらえだ！\nなんか食べに行くぞ！", 2, 7265, 1, 103, 12, 106101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなー！\nギルドハウスで\nぼくと握手！", 1, 7266, 1, 1, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("種族も年齢も違うけど\nみんな楽しそうだね！\nやっぱりここはぼくの\nゆ～とぴあさ！", 1, 7267, 1, 2, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハハッ！　まるで\nパーティー会場だね！\nこれは楽しませがいが\nあるってものだよ！", 1, 7268, 1, 3, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やぁみんな！\nご利益満点のネズ耳は\nいかがかな？\nひとつ３ルピだよ！", 1, 7269, 1, 4, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいれば\n遊び相手に困らないね\nかしこみかしこみ～！", 1, 7270, 1, 5, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どこか遊びに\n行こうかな♪\nそうだ、あの人にも\n声をかけてみよう！", 1, 7271, 1, 101, 4, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人といると\nぼくまで楽しくなって\nくるんだよね！\n毎日パレード気分さ！", 1, 7272, 1, 102, 8, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ネズ耳の在庫が\n切れたんだ！\n作るのを\n手伝ってくれるかい？", 2, 7273, 1, 1, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん？　握手かい？\nいいとも！\nいつでも何度でも\nしてあげるよ！", 2, 7274, 1, 2, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この衣装に興味が\nあるのかい？\nきみ、なかなか\n見る目があるね！", 2, 7275, 1, 3, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しばらくここに厄介に\nなるつもりなんだ\nあとで街を案内\nしてくれるかい？", 2, 7276, 1, 4, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とっておきのチーズ\nきみと半分こだ！\nみんなには内緒だよ？", 2, 7277, 1, 101, 4, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きみはいてほしい時に\nいつもそばに\nいてくれるね\n本当にかしこみだよ！", 2, 7278, 1, 102, 8, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やぁ、おはよう！\n気持ちのいい朝だね\n今日も楽しくネズ耳\n売りにはげもうか！", 2, 7279, 1, 1, 1, 125601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼だね！\nおいしいチーズを\n持ってきたから\nぼくと半分こだ！", 2, 7280, 1, 2, 1, 125601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も一日\n楽しかったね！\nいい夢が見られること\n間違いなしさ！", 2, 7281, 1, 3, 1, 125601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼくにも休息は\n必要さ！\nリラックス〜\nリラックス〜♪", 3, 7283, 1, 2, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼくのぬいぐるみも\n作って売ろうかな…\n修繕費も一気に\n集まるかもね！", 3, 7284, 1, 3, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りだね！\nトーゴクのお香に\nよく似てるよ", 3, 7285, 1, 4, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…温まるねぇ…\nそうだ、この火で\nチーズでも炙って\nみようかな", 3, 7286, 1, 5, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん、この味…\nトーゴクを思い出すよ\nどれ、もう一つ\nいただこうか！", 3, 7288, 1, 7, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これはランドソルの\nガイド本だね！\nありがたく参考に\nさせてもらうよ！", 3, 7289, 1, 8, 1, 125601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まさか、わらわが\nこのような装束を\n纏う日がくるとはな…\n感慨深いものじゃ", 1, 7291, 1, 1, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わらわの美貌で\nこのギルドハウスも\nより華やかに\nなったようじゃな", 1, 7292, 1, 2, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("つまらぬ戦いで\n晴れ着を汚しとうない\n今日は一日\nゆっくりするかの", 1, 7293, 1, 3, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はわらわが食事の\n準備をして、あやつの\n帰りを待ってやろう\n献立は何がよいかの…", 1, 7294, 1, 4, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ユキといったか…\n掴みどころのない\nやつじゃが、根性は\n認めてやるかの", 1, 7295, 1, 5, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こうして、仲間と\nのんびり過ごす時間も\n悪くないのう♪", 1, 7296, 1, 101, 4, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あやつを誘って\n月を見に行こうかの\n夜が楽しみじゃ♪", 1, 7297, 1, 102, 8, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いかなる衣装で\nあろうとも、わらわは\n完璧に着こなして\nしまうのじゃ♪", 2, 7298, 1, 1, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんじゃ？\nわらわの姿に\n見惚れておったとな？\nす、素直でよいのじゃ", 2, 7299, 1, 2, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("吸血鬼であるわらわに\n相応しい装束じゃろう\nあとは真っ赤な血を\n添えたいのう…", 2, 7300, 1, 3, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お主、疲れておるな？\nわらわが癒してやろう\nほれ、近う寄るのじゃ", 2, 7301, 1, 4, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お主がおるだけで\nギルドハウスが\n賑やかになるのう\nある種の才能じゃな♪", 2, 7302, 1, 101, 4, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眷属よ、風呂にするか\nご飯にするか\nそれとも、わらわに…\nいや、忘れるのじゃ", 2, 7303, 1, 102, 8, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝一番、わらわに\n会いたかったとな…\n眷属よ\n褒めてつかわすぞ♪", 2, 7304, 1, 1, 1, 126201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眷属よ、わらわが\n食事を用意したぞ\n忌々しい太陽に負けず\n頑張るのじゃ", 2, 7305, 1, 2, 1, 126201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眠るには惜しい夜じゃ\n眷属よ、もうしばらく\nわらわの傍に\nおるがよい", 2, 7306, 1, 3, 1, 126201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかじゃの♪\n今度あやつにも\n座らせてやろう", 3, 7308, 1, 2, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛いやつじゃ\n少しばかり、わらわが\n遊んでやろうかの", 3, 7309, 1, 3, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気品ある香りじゃのう\nわらわの古城にも\n一つ欲しいところじゃ", 3, 7310, 1, 4, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よいぬくもりじゃ…\n忌々しい太陽とは\n大違いじゃの", 3, 7311, 1, 5, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("味付けの参考に\nあと、もう一つだけ…\n止まらんのじゃ…", 3, 7313, 1, 7, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("吸血鬼の弱点について\n記されておるのか…\nふむ、眠気が\nさめてしもうたぞ", 3, 7314, 1, 8, 1, 126201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このままボクが美しく\nなり続けても、彼なら\nきっと隣にいてくれる\nはずだよね！", 1, 7316, 1, 103, 12, 100801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もっとそばに来なよ\nボクの隣は\nキミのための\n特等席なんだから", 2, 7317, 1, 103, 12, 100801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドレスの影響かな…\n前より黒や赤が\n好きになったかも", 1, 7318, 1, 1, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクがいるだけで\nここがぐんっと\n華やかになったね♪", 1, 7319, 1, 2, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクを描いた絵画\n今度持ってきて\n飾ってあげようかな", 1, 7320, 1, 3, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクはボクに\n魅了されっぱなしさ♪\nまさに魔性の存在だよ", 1, 7321, 1, 4, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美のアドバイスを\n聞きたい人いるかい？\nボクがもっともっと\n輝かせてあげるよ♪", 1, 7322, 1, 5, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人、今度はボクを\nどう褒めるだろう？\nもし語彙が尽きても\n許してあげよっと♪", 1, 7323, 1, 101, 4, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人に似合うコーデ\n考えてあげよっと\n案外、なんでも\n着こなしそうだよね♪", 1, 7324, 1, 102, 8, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("吸血鬼になるなんて\nやっぱりゴメンだね！\n永遠の美よりも\n大事なことがあるのさ", 2, 7325, 1, 1, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お肌にいいものは\n大体好きだよ\nトマトジュースとかね", 2, 7326, 1, 2, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("銀のアクセサリーが\nボクは大好きでね\nいつでもプレゼント\n待ってるよ♪", 2, 7327, 1, 3, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イリヤみたいにお城に\n住んでみたいんだ♪\n美を統べる者に\n相応しいでしょ？", 2, 7328, 1, 4, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今のボクがカップを\n触ると壊しちゃうんだ\nだからほら、キミが\nボクに紅茶を飲ませて", 2, 7329, 1, 101, 4, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミも美を磨けば\nもっと輝けるはずさ！\nボクがメイクとか\nしてあげようか？", 2, 7330, 1, 102, 8, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んん、まだ眠い…\n美のためにも、\nもうひと眠りするよ…", 2, 7331, 1, 1, 1, 126301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクにぴったりな\n日傘を買ったんだ♪\n散歩にでも行こうよ！", 2, 7332, 1, 2, 1, 126301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜こそボクの時間！\nさぁ、あまねく人々へ\nボクの美を広めよう！", 2, 7333, 1, 3, 1, 126301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リラックスは大事だよ\n心の余裕こそが\n美の秘訣だからね♪", 3, 7335, 1, 2, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミもボクの\n美の虜にしてあげる♪\nうれしいでしょ？", 3, 7336, 1, 3, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人々を魅了するほどの\n魔性の香り…\nボクにふさわしいね♪", 3, 7337, 1, 4, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冷えは美の大敵さ\nボクのように\n美しくなりたいなら\n体を温めるべきだよ", 3, 7338, 1, 5, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食事をするボクの\nなまめかしさ…♪\n吸血鬼すらも\nドキッとするだろうね", 3, 7340, 1, 7, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("吸血鬼って\n美しい存在だよね…\nボクほどではないけど", 3, 7341, 1, 8, 1, 126301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここがナイトさんの\nお家なんですねーっ！\n雰囲気そっくりっ！", 1, 7343, 1, 1, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドアも壁もお菓子じゃ\nないんですよねっ？\n不思議ですねーっ♪", 1, 7344, 1, 2, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("失礼のないように\n気をつけないとっ！\nライラエルさまとも\n約束してますからっ！", 1, 7345, 1, 3, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("向こうに帰るころには\nお土産話がいっぱい\nできてるといいな～♪", 1, 7346, 1, 4, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦闘用のアームの他に\n観光用のアームも\nあったらいいのにな～", 1, 7347, 1, 5, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ナイトさんの充填と\nライラエルさまの充填\nどっちも違って\nどっちも大好きです♪", 1, 7348, 1, 101, 4, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…ナイトさんが\nマスターになって\nくれたら…えへへっ\nなんでもないですっ！", 1, 7349, 1, 102, 8, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お手伝いだったら\n任せてくださいっ！\nお家の移転とか\nしちゃいますかっ？", 2, 7350, 1, 1, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっちに来るときは\nポポおじいさんが\nしっかりメンテして\nくれるんですよっ♪", 2, 7351, 1, 2, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お家の中にいるのも\nいいですけど、お外も\n気になります～っ！\nお出かけしましょう♪", 2, 7352, 1, 3, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヴォルガーノさんに\nそっくりの子猫さんを\n見かけたんですっ！\nご親戚ですかねっ？", 2, 7353, 1, 4, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここだけの話ですよ？\n…実はケーブルって\n触られると、ちょっと\nくすぐったいんですっ", 2, 7354, 1, 101, 4, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このお家の持ち主は\nナイトさんですよね？\nそれじゃここでは\nご主人さまですねっ", 2, 7355, 1, 102, 8, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございますっ\n今日もフルパワーで\nがんばりましょうっ♪", 2, 7356, 1, 1, 1, 126401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼の時間ですねっ！\nランチの充填、\nお願いしまーすっ♪", 2, 7357, 1, 2, 1, 126401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ眠らなくて\n大丈夫ですかっ？\n夜ふかしさんなら\nお付き合いしますよ♪", 2, 7358, 1, 3, 1, 126401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エネルギーの消費を\n抑えるのも大切\nですよね～っ", 3, 7360, 1, 2, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたしが触っても\n平気なんて…！\nかわいくて頑丈っ！\n好きですっ！", 3, 7361, 1, 3, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("センサーによると…\nこの香りはいい香りに\n該当するみたいですっ\nなるほどーっ！", 3, 7362, 1, 4, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいのって\nいいですよねっ！\nみなさんうれしそう\nですしっ♪", 3, 7363, 1, 5, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これがこっちの世界の\nごはんなんですねっ\nおいしい気がします！", 3, 7365, 1, 7, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そーっとそーっと…\n本を破かないように…\n書いてある内容より\n難しいです～っ！", 3, 7366, 1, 8, 1, 126401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ウィスタリア家の\nプライベートビーチも\nご案内しますわね♪", 1, 7368, 1, 1, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("世界を巡る\nリゾートクルーズも\nご用意できますわよ", 1, 7369, 1, 2, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("避暑地に専用の\n別荘がありますの\n今度ご招待しますわね", 1, 7370, 1, 3, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日焼けは乙女の\n天敵ですわね\n備えはしっかりと…", 1, 7371, 1, 4, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("線香花火だけでは\n物足りませんわね\nもっとドカーンと…", 1, 7372, 1, 5, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギルド活動も全力で！\nバカンスも全力で！\nそれが私ですわ！", 1, 7373, 1, 101, 4, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私のセンスで選んだ\n特注の水着ですもの\n似合って当然ですわ♪", 1, 7374, 1, 102, 8, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ご希望ならすぐにでも\n夏の飛空艇遊覧ツアー\nへご招待しますわ♪", 2, 7375, 1, 1, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の賑やかな\n雰囲気は好きですが…\n暑さには参りますわね", 2, 7376, 1, 2, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日の光を浴びるほどに\n輝きを増す夏の私！\n今日も絶好調ですわ♪", 2, 7377, 1, 3, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏祭りに協力するなら\n資金と人材、どちらも\n用意しないとですわね", 2, 7378, 1, 4, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたさま…その…\nそうも見つめられると\n照れてしまいます…", 2, 7379, 1, 101, 4, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("タマキさんの働く\n海の家も訪れて\nみたいですわね♪", 2, 7380, 1, 102, 8, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("港の市場が\n賑わう頃ですわね！\n私たちも参りますわよ", 2, 7381, 1, 1, 1, 126701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冷たい飲み物でも\nご一緒にいかが？\nうちのシェフに用意\nさせてありますの", 2, 7382, 1, 2, 1, 126701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだもう少し…\nこの夏の夜を\nあなたさまと…", 2, 7383, 1, 3, 1, 126701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたさまも\n良ければこちらへ\nいらっしゃいな♪", 3, 7385, 1, 2, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏に合わせた装いに\n替えてみるのも\n楽しそうですわね♪", 3, 7386, 1, 3, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この夏めいた爽やかな\n香り…期間限定で\n売り出したいですわ", 3, 7387, 1, 4, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("く…我慢です…\nこの暑さに耐えてこそ\n美しさにも磨きが…", 3, 7388, 1, 5, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑い季節に働く\nみなさまへ差し入れも\n必要ですわね", 3, 7390, 1, 7, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏のトレンドを\n押さえておくのも\n大事ですわね", 3, 7391, 1, 8, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("上手くいけば\nヒット商品になる\nポテンシャルを\n感じますわね…！", 3, 7393, 1, 10, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この極上の肌触り…\n言い値で買いますわ\n一体おいくらですの？", 3, 7394, 1, 11, 1, 126701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくのバカンス…\n自由に羽を\n伸ばすとしましょう", 1, 7395, 1, 1, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たとえどのような\n秘密を持とうとも\n私には筒抜けですよ", 1, 7396, 1, 2, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("子供だましの怪談に\n関心はありませんが…\n霊には興味があります\n観察対象として、ね", 1, 7397, 1, 3, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼の絵日記…\nあとでゆっくりと\n読ませてもらいます", 1, 7398, 1, 4, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("セミの鳴き声に入道雲\nそしてクリームソーダ\nこれでこそ夏ですね", 1, 7399, 1, 5, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏休みの宿題でも\n作るとしましょうか\n彼の限界を少し超えた\n負荷を与えるには…", 1, 7400, 1, 101, 4, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼と過ごす夏を\n特別なものにしたい…\nそれが私の望みです", 1, 7401, 1, 102, 8, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏だからといって\n浮かれすぎないように\n節度を持って\n楽しみなさい？", 2, 7402, 1, 1, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ見えてもマサキは\n私のプリンセスナイト\nあまり侮られては\n困りますよ？", 2, 7403, 1, 2, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の秘密ですか？\nまんじゅうが怖い…\nというのはどうです？", 2, 7404, 1, 3, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここは誰かの秘密を\n盗み聞くのに\n最適な場所ですね\n…ジョークですよ", 2, 7405, 1, 4, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒に風鈴の音を\nのんびり楽しもう…？\n…別に構いませんよ\n貴方とならば", 2, 7406, 1, 101, 4, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴方に約束しましょう\n決して忘れられない\n夏にしてあげますよ", 2, 7407, 1, 102, 8, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("早起きとは感心ですね\nでは一緒に\n体操でもしましょうか", 2, 7408, 1, 1, 1, 126601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食は流しそうめん？\n非効率的ですね\n…食べないとは\n一言も言っていません", 2, 7409, 1, 2, 1, 126601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…貴方が望むならば\nいくらでも怖い話を\nしてあげますが…\nいかがですか？", 2, 7410, 1, 3, 1, 126601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("七冠にも休息は\n必要なのです\nしばらくここで\n休ませてもらいますよ", 3, 7412, 1, 2, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なかなか気に入った…\nというのは\n誰にも秘密です", 3, 7413, 1, 3, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("薫風を思わせる\nこのさわやかな香り…\n悪くないセンスですね", 3, 7414, 1, 4, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏だからこそ\n冷え対策は\n重要なのです\n…とはいえ暑いですね", 3, 7415, 1, 5, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私がどのような味が\n好きなのかは…\n当然秘密です", 3, 7417, 1, 7, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏を舞台にした\n小説は数多くあります\n彼が好きそうな本を\n何冊か見繕いましょう", 3, 7418, 1, 8, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見た目も手触りも\n完璧に覚えました\nいつでも模倣できます", 3, 7420, 1, 10, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ…夏らしい\nクッションですね\nナイトプールに\n映えそうです", 3, 7421, 1, 11, 1, 126601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レイ様も格好良いけど\n騎士さんもなかなか…\nって、今の聞こえて\nませんよねっ？", 1, 7422, 1, 103, 12, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんはシンプルな\n服が似合いそうです！\n今度、一緒に\n見に行きましょう♪", 2, 7423, 1, 103, 12, 105401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最初はどうかな～って\n思ったけど…\n水着姿でも案外\n問題ないのよね…", 1, 7424, 1, 1, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着で飲みすぎると\nお腹が冷える、って\n言うけど…麦しゅわ\nなら問題ないわね！", 1, 7425, 1, 2, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑ければ暑いほど\nその後の麦しゅわは\nおいしくなるのよ…", 1, 7426, 1, 3, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しっかりと仕事を\nこなしてから、\nしっかりと麦しゅわ！\nやっぱりこれね！", 1, 7427, 1, 4, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ、デザインも\n着心地も最高ね\n奮発して用意して\n正解だったわ♪", 1, 7428, 1, 5, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("伝説の麦しゅわ、\n飲めるものなら\nまた飲みたいわね…", 1, 7429, 1, 101, 4, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("二つ名に恥じない\n聖騎士として\n私…飲むわ！", 1, 7430, 1, 102, 8, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好なら水に\n濡れても大丈夫！\nなんだけど、さすがに\n書類は濡らせないわね", 2, 7431, 1, 1, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうやってじっと\n見られると…ちょっと\n恥ずかしいわ…", 2, 7432, 1, 2, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もいい天気ね\nふふっ、あとで\nビーチに遊びに\n行きましょ♪", 2, 7433, 1, 3, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着姿も慣れると\n案外快適ね\nそうだ、キミも\n水着になっちゃう？", 2, 7434, 1, 4, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("例え水着姿であろうと\n聖騎士としての誇りは\n忘れてないわ！", 2, 7435, 1, 101, 4, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミとだったら\n麦しゅわなしでも\n最高の夏のバカンスに\nなると思うわ♪", 2, 7436, 1, 102, 8, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仕事終わりの\n麦しゅわのために\n今日も一日\n頑張るわよ♪", 2, 7437, 1, 1, 1, 126801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のお昼は\nどうしようかしら…\nさ、さすがに昼からは\n自重してるわよ？", 2, 7438, 1, 2, 1, 126801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さ、一日の疲れを\n洗い流すために…\n軽～く飲むわよ！", 2, 7439, 1, 3, 1, 126801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こうやって\n直に触れると\n肌触りの良さが\nよく分かるわ♪", 3, 7441, 1, 2, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もかわいいわね～\nどう？　今度\nお姉さんの一人飲みに\n付き合わない？", 3, 7442, 1, 3, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りね～…はっ！\n麦しゅわの匂いの\nアロマポットなんて\nあったらよくない？", 3, 7443, 1, 4, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな格好で火に\n当たってると焙られる\nスルメの気分が\nちょっと分かるわ…", 3, 7444, 1, 5, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…うん、\n結構おつまみにも\nむいてそうね～♪", 3, 7446, 1, 7, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("試験に使った参考書、\nたまには読み返して\nおかないとね", 3, 7447, 1, 8, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ♪\nいい手触りね～", 3, 7449, 1, 10, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…はふう～…\nゴロゴロするのって\n最高ね～", 3, 7450, 1, 11, 1, 126801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん…やっぱり\nこの水着…\n大胆、なんじゃ…？", 1, 7451, 1, 1, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海でもお世話って、\nできるのかしら…？\n浮き輪代わりになる、\nとか…？", 1, 7452, 1, 2, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("～♪\nふふ…海に行く\n準備も、楽しい…かも", 1, 7453, 1, 3, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あうぅ…水着で\n歩いてると…お尻…\nすぐ食い込んじゃう…", 1, 7454, 1, 4, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海では、はしゃいだ\nほうがいいのよね…\nわ、わー、い…♪\n…こうかしら？", 1, 7455, 1, 5, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたとなら…\n楽しい夏の思い出、\n作れる…気がするの…", 1, 7456, 1, 101, 4, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("また来年も…\n再来年も…\nあなたと海へ\n行けますように…", 1, 7457, 1, 102, 8, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着の着方を\n練習してるの…\n後ろ、変じゃない…？", 2, 7458, 1, 1, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に行く支度…\n進んでるかしら…？\nお手伝い、する…？", 2, 7459, 1, 2, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひ、日除けの準備は\n万全よ…\nずっと太陽の下に\nいたら…溶けちゃう…", 2, 7460, 1, 3, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぐ練習…\nこ、ここでするのは\n…さすがに変？", 2, 7461, 1, 4, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人混みに入るのは\nまだ不安で…\nでも、あなたといれば\nきっと…大丈夫…", 2, 7462, 1, 101, 4, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたのおかげで\n海の楽しいところを\nたくさん知ったわ…\nありがとう…♪", 2, 7463, 1, 102, 8, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お出かけの日の朝は\n早い、のよね…？\nだから、ずっと\n起きていたわ…", 2, 7464, 1, 1, 1, 126901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今頃ビーチの日差しは\n強いんでしょうね…\nそ、想像しただけで…\nめまいが…", 2, 7465, 1, 2, 1, 126901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビーチの夜といえば\n花火って、聞いたわ…\nバン、って言わない\n花火…ある…？", 2, 7466, 1, 3, 1, 126901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素肌にふわふわが…\n気持ちいい…♪", 3, 7468, 1, 2, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うふふ…\n一緒に海…行く？", 3, 7469, 1, 3, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…♪\n気分まで…\n晴れやかになるわ…", 3, 7470, 1, 4, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑いような…\n寒いような…\n不思議な気持ちに\nなるわ…ね？", 3, 7471, 1, 5, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳いだ後には\nいっぱい食べたほうが\n体によさそう、ね…", 3, 7473, 1, 7, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビーチの日陰で\n読書するのも…\n気持ちよさそう…♪", 3, 7474, 1, 8, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これで合ってる…？\n遊び方わからなくて…", 3, 7476, 1, 10, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわふわ…♪\n海の底にいるみたい…", 3, 7477, 1, 11, 1, 126901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("恥ずかしい格好で\n室内を歩くこの快感\nクセになりそうです…", 1, 7478, 1, 1, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この水着…\nどうしてかポーズを\n決めたくなりますね…", 1, 7479, 1, 2, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海にはどんな生き物が\nいるのでしょう～\n胸が高鳴ります～♪", 1, 7480, 1, 3, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏は暑いですね…\nクウカの体が熱いのも\n夏のせい…ぐふふ…♪", 1, 7481, 1, 4, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんと無人島に\n取り残されて…という\n妄想はかなりイイです", 1, 7482, 1, 5, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんの\n欲望に満ちた眼差し…\nクウカ、受け止めます", 1, 7483, 1, 101, 4, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に行くのが\n楽しみです…\nドＳさんと…ぐふふ♪", 1, 7484, 1, 102, 8, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「もっと過激な水着を\n見せてみろよ」なんて\nいけませんドＳさん…", 2, 7485, 1, 1, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着のままで\n踊ればいいのですね…\nドＳさんの望みなら！", 2, 7486, 1, 2, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさんの熱い視線を\n感じます…じゅるり…\nもっと見てください…", 2, 7487, 1, 3, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな格好のクウカを\n放っておくなんて…\nさすがですドＳさん！", 2, 7488, 1, 4, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海で水着といえば\n何かが起きる予感…！\nドＳさんの新たな攻め\n期待していますね…！", 2, 7489, 1, 101, 4, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("恥ずかしいですけど\n頑張っちゃいました\nドＳさん…こういう\n水着、好きですか？", 2, 7490, 1, 102, 8, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな朝からクウカを\n水着に着替えさせて…\n本当にドＳさんは\n欲望に正直ですね！", 2, 7491, 1, 1, 1, 127001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな昼間から\nドＳさんがヌルヌルの\n液体をクウカに～！\nえっ…日焼け止め？", 2, 7492, 1, 2, 1, 127001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドＳさん…これから\nクウカと夜の海を\n見に行きませんか？\nきっと綺麗ですよ…♪", 2, 7493, 1, 3, 1, 127001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここなら妄想に\n集中できます～♪\nじゅるり～♪", 3, 7495, 1, 2, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こうもかわいいと\n妄想に登場させるのも\n気が引けます…", 3, 7496, 1, 3, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クウカを昂らせる\nこの香り…！\nは！　ドＳさんの罠！", 3, 7497, 1, 4, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体を熱くさせて\n水着を脱がそうと！？\nテクニカルです…！", 3, 7498, 1, 5, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クウカの口の中に\nたくさん…♪\n止まりません…！", 3, 7500, 1, 7, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("読書は心が穏やかに\nなりますね…！\nぐふふ…穏やかに…", 3, 7501, 1, 8, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい乗り心地です…♪\nあっ…普通に楽しんで\nしまいました…", 3, 7503, 1, 10, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは…\n妄想に役立ちそうな\n感触です…！", 3, 7504, 1, 11, 1, 127001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("成長した自分に\nあわせて、もっと\nかっこいいポーズを\n研究するッス！", 1, 7505, 1, 103, 12, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これからも一緒に\n最高のヒーローを\n目指していくッスよ♪", 2, 7506, 1, 103, 12, 100501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さん、娘の\n水着姿がそんなに\nうれしいの？", 1, 7507, 1, 1, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("怖い話を子どもたちに\n聞かせたら泣かれて\nしまいました…\n加減が難しいです…", 1, 7508, 1, 2, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に行くと父が\n水着の女性ばかり\n追いかけて困ります…", 1, 7509, 1, 3, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("拾った貝殻で\n新しい占いでも\nはじめてみようかな", 1, 7510, 1, 4, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貝殻を耳に当てると\n波の音が…あっ\nこれはダメです\nよくない声がします", 1, 7511, 1, 5, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この飲み物、スーッと\n体に沁み込んでくる…\nあの人にも\n教えてあげたいです", 1, 7512, 1, 101, 4, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("強い日差しも騒がしい\n海も苦手なのに\nあの人となら不思議と\n楽しく思えるんです", 1, 7513, 1, 102, 8, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏限定、水と氷を\n使った特別な占いは\nいかがですか？", 2, 7514, 1, 1, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑い日々にはやはり\n怪談ですね\n厳選フルコースで\nお聞かせします", 2, 7515, 1, 2, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寒気がする？　それは\n霊ではなくかき氷の\n食べ過ぎですよ", 2, 7516, 1, 3, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日の占い、あなたの\nラッキーパーソンは…\n白い水着の女性です", 2, 7517, 1, 4, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの、よければ\n日焼け止めを塗って\nもらえませんか？\n背中は届かなくて…", 2, 7518, 1, 101, 4, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に行きませんか？\n二人きりで静かな\n砂浜を散歩したいです", 2, 7519, 1, 102, 8, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("潮騒だけが響く朝の海\n心が落ち着きます\nこれから一緒に散歩に\n行ってみませんか？", 2, 7520, 1, 1, 1, 127101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("不思議です。どうして\n普通のご飯でも、海で\n食べると特別おいしく\n感じるのでしょう…", 2, 7521, 1, 2, 1, 127101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の海に行きませんか\n今なら夜光虫が\n見られるかも\nしれませんよ", 2, 7522, 1, 3, 1, 127101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏は知らぬ間に体力を\n消耗しています\n適度に休息して\nいきましょう", 3, 7524, 1, 2, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このぬいぐるみ…\n大丈夫です\n何も憑いては\nいませんよ", 3, 7525, 1, 3, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほのかにお線香\nみたいな香り…\nなんだか\n落ち着きます", 3, 7526, 1, 4, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人魂、鬼火\nセントエルモの火…\n炎を見ていると色々と\n連想してしまいます", 3, 7527, 1, 5, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹を壊さぬよう\n食い合わせには\nご注意ください", 3, 7529, 1, 7, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これはいい\n怪談集ですね…\nつい読みふけって\nしまいます", 3, 7530, 1, 8, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、こういうのに\n乗るとなんだか\n子どもに戻った\nみたいですね", 3, 7532, 1, 10, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こ、これは…\nちょっとメルヘン\n過ぎて恥ずかしい\nですね…", 3, 7533, 1, 11, 1, 127101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本当に素敵なお家…♪\n騎士たちの人柄を\n感じられるようで…\n不思議と落ち着きます", 1, 7534, 1, 1, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("調度品をつい間食…\nという習慣がこちらの\n世界にはないのですね\n…気をつけないと", 1, 7535, 1, 2, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("手土産のお菓子は\nどちらに置けば\nよいでしょうか？", 1, 7536, 1, 3, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まるでおとぎ話の中に\n入ってしまったかの\nよう…別世界とは\nよく言ったものです", 1, 7537, 1, 4, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お忍び…ふふっ♪\nときめく響きです\nなんだかお茶目で…\n密やかな印象が", 1, 7538, 1, 5, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわ…\nああ、ついあくびが…\n居心地がよすぎるのも\n困り物ですね…ふふ♪", 1, 7539, 1, 101, 4, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士には不思議な力が\nあるだけでなく\n何者かの加護が\nあるようですね…", 1, 7540, 1, 102, 8, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この『王家の装備』は\n少し気難しいのです\nわたし以外が触れると\nその…ビリビリっと", 2, 7541, 1, 1, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("子どもたちに新しい\n遊びを教わりました♪\nにーらめっこしましょ\nあっぷっ…ぷ～っ！", 2, 7542, 1, 2, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("実は憧れていたのです\n友人の家を訪ねると\nいう経験に…ふふっ", 2, 7543, 1, 3, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぎるどはうす…\nぎるど活動の拠点だと\n管理協会？　の方に\nうかがいました", 2, 7544, 1, 4, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたは運命を\n信じますか？\nわたしは…信じます\nよい運命だけですが♪", 2, 7545, 1, 101, 4, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もしわたしが本当に\n天使だったとしたら…\nどうされますか？\n…ふふ、冗談です♪", 2, 7546, 1, 102, 8, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パンケーキの香りで\n目覚める朝は\nとても良いものですよ\nぜひともお試しを♪", 2, 7547, 1, 1, 1, 126501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひと休みの時間ですね\n食事にお昼寝…\nすべきことを行って\n英気を養いましょう", 2, 7548, 1, 2, 1, 126501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ休まれては？\n眠れないようであれば\n寝物語か子守歌でも\nふふ、遠慮は無用です", 2, 7549, 1, 3, 1, 126501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すう………はっ！\n眠ってはいませんよ？\nいくら居心地が良い\nからといって…ふわぁ", 3, 7551, 1, 2, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まあ、あいらしい…♪\nぜひわたしの寝室に\n招待させてください", 3, 7552, 1, 3, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんて、かぐわしい…\nオーブンからただよう\n焼き菓子の香りとは\nまた異なる魅力が…", 3, 7553, 1, 4, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みなで暖をとりながら\n互いに語り笑い合う\n…心休まる時間ですね", 3, 7554, 1, 5, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食は心と体に\nゆとりを生みます\n…辛い食べ物の場合？\nそれは、その…", 3, 7556, 1, 7, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こちらの世界の知識を\n蓄えておかなければ\nテーブルマナーに\nついてのページは…", 3, 7557, 1, 8, 1, 126501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しい色の蛍光ペン\n買ったのよね\nこれで勉強が\n楽しくなるわ～♪", 1, 7559, 1, 1, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("学食のランチ、結構\nおいしいのよね～\n今度ペコリーヌに\n教えてやろうかしら？", 1, 7560, 1, 2, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふふ…扉に黒板消し\n仕掛けてるの…あいつ\n引っかかるかしら？", 1, 7561, 1, 3, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部活するなら運動部も\n悪くないかもね～\n夕日に向かって\n突っ走ってやるわ！", 1, 7562, 1, 4, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("毎日窮屈な制服着て\n学生も大変ね～\n…ま、かわいいけど", 1, 7563, 1, 5, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつに貸したノート\n変な落書きとか\nしてなかったよね…？\n…その、相合傘とか…", 1, 7564, 1, 101, 4, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昨日の家庭科で\n作ったクッキー…\nあいつにどうやって\n渡そうかな…？", 1, 7565, 1, 102, 8, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("宿題教えてって？\nしょうがないわね～\nじゃあ一緒に\nやりましょ", 2, 7566, 1, 1, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、明日あたしたち\n日直当番よね？\nめんどい仕事は\nあんたに任せるわ～", 2, 7567, 1, 2, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寮生活は楽しいけど\n就寝時間が早すぎよね\nいきなり消灯されると\nビックリするわ", 2, 7568, 1, 3, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("校則で禁止だけど、\nにけつでほうき通学\nとか青春っぽくない？", 2, 7569, 1, 4, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("制服って好きな人とも\n自然にお揃いになれて\nいいわよね…って別に\nあんたとって訳じゃ…", 2, 7570, 1, 101, 4, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたネクタイ\n曲がってるわよ～？\nほら直したげるから\nこっち向いて？", 2, 7571, 1, 102, 8, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよ～！\n今日も元気に登校よ！\n忘れ物ないようにね！", 2, 7572, 1, 1, 1, 127201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("午前の授業疲れたわ～\nしっかりお昼を食べて\n午後も頑張るわよ！", 2, 7573, 1, 2, 1, 127201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うう…学校の怪談\n思い出しちゃった…\n…別に怖くないけど！", 2, 7574, 1, 3, 1, 127201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふか～\n…気持ち良すぎて\n制服のまま\n寝ちゃいそうね…", 3, 7576, 1, 2, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいくて癒されるわ\n寮に持ち込んでも\n大丈夫かしら…？", 3, 7577, 1, 3, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("集中力の高まる香りで\n勉強の効率爆上がりね\n次のテストで\nいい点取るわよ～！", 3, 7578, 1, 4, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うう、ちょっと冷えて\n来たわね…\nスカートの下に\nジャージ穿こうかしら", 3, 7579, 1, 5, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐっ…もぐっ…\n食べとかないと教室で\nお腹なっちゃうわ～", 3, 7581, 1, 7, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("図書室で借りた本\n明日返却日なのよね…\n今日中に読むわよ！", 3, 7582, 1, 8, 1, 127201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつに背中を\n預けるのもいい気分だ\nいつかは、全部…", 1, 7584, 1, 103, 12, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("な、なんだよ？\nじっと見るんじゃねぇ\n尻尾が揺れちまうだろ", 2, 7585, 1, 103, 12, 104301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法の練習！\nむむむ～…\nそれっ…！", 1, 7586, 1, 1, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そだ！　これ着て\nルー学行こっかな？　\n制服自慢しちゃお♪", 1, 7587, 1, 2, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("赤点回避の魔法とか\nあったら最高じゃね？\n誰かうちに教えて～", 1, 7588, 1, 3, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("制服が一番映える\n場所ってどこだろ？\n教室？　遊園地？", 1, 7589, 1, 4, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ベンキョーつらたん…\n今度キャルっちに\n助けてもらお", 1, 7590, 1, 5, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部活か…\nヒデサイと一緒に\nやったら楽し～かも♪", 1, 7591, 1, 101, 4, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("男子の制服\nもにカワだった…\n今度ヒデサイに\n借りよっかな？", 1, 7592, 1, 102, 8, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょすー、うちの\nさいきょー魔法で\nテンアゲしてあげる～", 2, 7593, 1, 1, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("九九って呪文ぽくね？\nほら、例えばヒチシ…\nヒチシ、なんだっけ？", 2, 7594, 1, 2, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイセンセー\nうちにベンキョー\n教えて！", 2, 7595, 1, 3, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("学割マジ助かるー\nヒデサイ、一緒に\nどんどん使ってこー♪", 2, 7596, 1, 4, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度ヒデサイに\nお弁当作ったげる\n屋上で一緒に食べよ♪", 2, 7597, 1, 101, 4, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒデサイのバイブス\n上がる言葉教えてよ\nつらたんな時、うちが\nいっぱい言ったげるよ", 2, 7598, 1, 102, 8, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょすちょす～\n今日も朝から\nバイブス十分♪", 2, 7599, 1, 1, 1, 127301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼どうしよっかな\nたまにはガッツリ\nいっちゃう系？", 2, 7600, 1, 2, 1, 127301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やべ、宿題まだ\nできてないし…\nヒデサイ助けて～", 2, 7601, 1, 3, 1, 127301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("充電ちう～\n…ガッコーのイスも\nこれにして～", 3, 7603, 1, 2, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいし、\n癒されるし、キュン死\nしちゃうじゃん…！", 3, 7604, 1, 3, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リフレッシュの\n魔法発見！\nいい香り～♪", 3, 7605, 1, 4, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽかぽかサイコー♪\n今日はもーずーっと\nここにいたいかも～", 3, 7606, 1, 5, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("超おいし～♪\n学食にあったら\n毎日リピする～", 3, 7608, 1, 7, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\nねむみパない…\n続きはまた今度～", 3, 7609, 1, 8, 1, 127301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度は子どもたちも\nサラサリアに連れて\n行ってあげたいわ", 1, 7611, 1, 1, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("子どもたちから\nお姫さまみたいって\n言われちゃった♪", 1, 7612, 1, 2, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この剣…火を点けたり\nするのに便利なのよ\nコントロールも効くし", 1, 7613, 1, 3, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのサラサリアの\nカラっとした暑さが\nちょっと恋しいわ…", 1, 7614, 1, 4, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("買ってきたお土産、\nお世話になってる\nみんなに配りましょ♪", 1, 7615, 1, 5, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたと一緒なら\nどこの国でだって\n暮らしていけそうね♪", 1, 7616, 1, 101, 4, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今の事業を大きくして\nあんたと世界中の国を\n飛び回ったり…なんて\nすてきじゃない？", 1, 7617, 1, 102, 8, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サラサリアで食べた\n料理が恋しい…？\nもう…また今度\n作ってあげるわよ", 2, 7618, 1, 1, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度旅行するなら\nどこに行こうかしら？\n希望があれば教えてね", 2, 7619, 1, 2, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サラサリアの香辛料、\nランドソルでも\n人気が出そうよね\nいいビジネスの予感！", 2, 7620, 1, 3, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そんなにじっと\n見られるとさすがに\n恥ずかしいってば…", 2, 7621, 1, 4, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お嫁さんは憧れるけど\nお婿さんになって\nもらうのもありよね…\nあんたはどう思う？", 2, 7622, 1, 101, 4, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱり、あんたには\nいつもあたしの隣に\n居てほしいな…", 2, 7623, 1, 102, 8, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("陽射しが強くなる前に\n雑多な用事は\n片付けちゃいましょ", 2, 7624, 1, 1, 1, 127501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サラサリアで食べた\n料理を再現してみたの\n味見してくれる？", 2, 7625, 1, 2, 1, 127501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑さに負けないように\n睡眠はちゃんと\n取っておかないと", 2, 7626, 1, 3, 1, 127501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっちでもあっちでも\n忙しいのは変わらない\nわね…ちょっと休憩～", 3, 7628, 1, 2, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サラサリアで見た\nぬいぐるみも\nかわいかったわね", 3, 7629, 1, 3, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お香って地域ごとの\n特色が出るわよね\nこの香りは…\nちょっと神秘的？", 3, 7630, 1, 4, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("砂漠地方も夜は冷える\nのよね。温かいものが\nあると安心するわ…♪", 3, 7631, 1, 5, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べ慣れた味って\nどうしてほっと\nするのかしら…", 3, 7633, 1, 7, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今後の取引相手に\nなるかもしれないし\n向こうの文化も\n勉強しておかないと…", 3, 7634, 1, 8, 1, 127501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("犯人はこの中にいる！\n探偵として一度は\n言ってみたいセリフさ", 1, 7636, 1, 103, 12, 101401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("助手くんの情報を\n仕入れておかないと…\n理想の私を、ずっと\n見ていてほしいからね", 2, 7637, 1, 103, 12, 101401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("久々の長旅で\n里心がついちまったね\nしばらくランドソルで\nのんびりしようか", 1, 7638, 1, 1, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまには違う服装\n違う得物を使うのも\n悪くないね", 1, 7639, 1, 2, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サラサリアにいた時は\n砂まみれで大丈夫かと\n思ってたけど、今じゃ\n懐かしく感じるよ", 1, 7640, 1, 3, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法の絨毯、あれは\n楽だし速いし便利\nだったねえ…土産に\n一枚欲しかったな", 1, 7641, 1, 4, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("砂上での戦いは\nなかなかいい鍛錬に\nなったね…今度は\n修行しに行くとしよう", 1, 7642, 1, 5, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サラサリアの人たちも\n気のいい連中だったが\n元気にやってるかねえ", 1, 7643, 1, 101, 4, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("旅の恥はかき捨てって\nいうけど、悪い旅じゃ\nなかったね。次は\nアイツとどこに行こう", 1, 7644, 1, 102, 8, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好を冷やかしに\n来たのかい？\n生憎、もうすっかり\n慣れちまったよ", 2, 7645, 1, 1, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギルドの連中に\n土産をわたしに\n行くところなんだ\n付き合っておくれよ", 2, 7646, 1, 2, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("久々に水場で\n釣りがしたいねえ…\nもちろんお前さんも\nくるんだろう？", 2, 7647, 1, 3, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっと\nサラサリアの連中から\n便りが来てるよ\nさ、一緒に読もうか", 2, 7648, 1, 4, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近サラサリアの踊り\nを練習してるんだ\nあとで振付けを\n見ておくれよ", 2, 7649, 1, 101, 4, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだいお前さん？\n…なんだか若奥さん\nっぽいって？　まあ、\nそりゃあ、ねえ…", 2, 7650, 1, 102, 8, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい時間だね\n日が昇りきる前に\nやることをすませ\nとかないと", 2, 7651, 1, 1, 1, 127601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼はどうしようかね\nサラサリア風の\n食事でもつくろうか", 2, 7652, 1, 2, 1, 127601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さて、早めに寝ようか\n砂漠の夜は冷えるから\n…っと、まだ旅行中の\n気分でいたよ", 2, 7653, 1, 3, 1, 127601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("良い座り心地だ\nサラサリア宮殿の\n応接間を\n思い出すねえ…", 3, 7655, 1, 2, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランプの魔神に\nあげたら喜ぶかねえ？\n次に会う時までに\n見繕ってみようか", 3, 7656, 1, 3, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り…\nサラサリア土産の\n香木かい？", 3, 7657, 1, 4, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("旅先での焚火を\n思い出すよ\nなんだかほっとするね", 3, 7658, 1, 5, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、慣れてる味も\nいいけど、むこうの\n味付けが懐かしく\nなっちまうね", 3, 7660, 1, 7, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\n千夜一夜物語か\nおもしろいもんだねえ", 3, 7661, 1, 8, 1, 127601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("立派なギルドハウス♪\n帰る場所が素敵だと\n冒険に出るのも\n楽しくなりそうです♪", 1, 7663, 1, 1, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お掃除でも…と\n思いましたけど、\nさすがお兄さんのお家\nきれいにしてますね♪", 1, 7664, 1, 2, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたしたちもいつか\n立派なギルドハウスが\n持てる冒険者に\nなりたいです…♪", 1, 7665, 1, 3, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたし冒険者ですけど\n家を守ってお兄さんの\n帰りを待つのも\n悪くない…かも？", 1, 7666, 1, 4, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子焼こうかな…♪\nちょっと多めに作って\nお兄さんにも\n食べてもらおうっと♪", 1, 7667, 1, 5, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このお家、とっても\n大好きになりました♪\nだからその…もう少し\nいてもいいですか…？", 1, 7668, 1, 101, 4, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんに\n感謝の手紙を書いて\n枕元に隠して\nおこうかな…♪", 1, 7669, 1, 102, 8, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…お兄さん\nお暇なんですか？\nじゃあ一緒に冒険へ\n出かけましょう♪", 2, 7670, 1, 1, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんは苦手な食材\nとかありますか？\nあの、もしよければ\n今から手料理を…♪", 2, 7671, 1, 2, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まったり過ごす\nお家時間もいいですね\n冒険者には羽休めも\n大事ですから♪", 2, 7672, 1, 3, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつでもお兄さんを\n守れるように\nこの姿でいることに\n慣れておきますね…！", 2, 7673, 1, 4, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さん眠そうです…\nちょっとお昼寝\nしちゃいましょうか♪\nはい、膝枕…♪", 2, 7674, 1, 101, 4, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さん怪我を…！？\nわたしが治療を…\nふー…ふー…", 2, 7675, 1, 102, 8, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます♪\n朝、元気に挨拶すれば\n幸せな一日が過ごせる\nそうですよ♪", 2, 7676, 1, 1, 1, 126001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ごはんの時間です\n…手がふさがってる？\nわかりました、じゃあ\nあ～んしますね♪", 2, 7677, 1, 2, 1, 126001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ…眠くなって\nきちゃいました…\nお兄さん…お泊りして\nいいですか…？", 2, 7678, 1, 3, 1, 126001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふにゃ～～…♪\nこんな姿、他の人には\n見せられません…♪\nもふもふ～～…♪", 3, 7680, 1, 2, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんこういうの\n好きなのかな～…\nふふっ、わたしも♪\nぎゅ～～～っ♪", 3, 7681, 1, 3, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アロマの癒し効果…\n上手くアレンジして\nみなさんの治療に\n活かせないかな～？", 3, 7682, 1, 4, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("は～気持ちいい～♪\n身体が暖まると\n心もぽかぽかです♪", 3, 7683, 1, 5, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うふふ、おいしい♪\nプレシアちゃんなら\n無限にぱくぱく～って\nしちゃいそうです…♪", 3, 7685, 1, 7, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本はわたしを\n知らない世界に\n連れていってくれる…\nまるでお兄さんです♪", 3, 7686, 1, 8, 1, 126001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("話題の新刊…\nあの人も読んでるかな\n今度会う時、感想\n聞いてみたいな…♪", 1, 7688, 1, 103, 12, 103801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うにゃっ…あ、熱を\n測ってくれたんですか\nありがとうございます\nバッチリ元気ですよ♪", 2, 7689, 1, 103, 12, 103801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄の、けはい…\nん、みつけた\nぎゅ", 1, 7690, 1, 1, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きょろきょろ\nここも\nぱとろる、するよ", 1, 7691, 1, 2, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おうち\nにぎやか\nさみしく、ない", 1, 7692, 1, 3, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きょだい、おにぎり\nきょだい、肉まん\nきょだい…お兄？", 1, 7693, 1, 4, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はっぴーちゃん\nどこ？\nお兄、たべた？", 1, 7694, 1, 5, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん…この、へや\nお兄の、におい\nすんでる\nすめる？", 1, 7695, 1, 101, 4, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おそうじ、にがて\nでも\nれんしゅう\nきゅっきゅ", 1, 7696, 1, 102, 8, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みみ、さわり、たい？\nんー…だめ…\nむずむず\nなので", 2, 7697, 1, 1, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くろぷれしあ\nかっこいい？\nん…あざます", 2, 7698, 1, 2, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄の、おうち\nきょうみ、ましまし\nたんけん\nするね", 2, 7699, 1, 3, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なでなで、される…と\nねむ…く…\nぶぅ…ぶぅ…ぶぅ…", 2, 7700, 1, 4, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かみ、りぼん\nおてつだい\nよろ\nです", 2, 7701, 1, 101, 4, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここ\nすむ\nね？\nまいにち、いっしょ", 2, 7702, 1, 102, 8, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぐっもにん\nあさごはん\nあさごはん", 2, 7703, 1, 1, 1, 126101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄\nおつかれ？\nれっつ、まいぺーす", 2, 7704, 1, 2, 1, 126101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひとりで、ねれる\nでも\nひとりじゃ、なくても\nねれる、よ…？", 2, 7705, 1, 3, 1, 126101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふか\nパパの、おなか\nみたい", 3, 7707, 1, 2, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんにちは\nぷれしあ、です\nおともだち、なろ？", 3, 7708, 1, 3, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい、におい\nでも、お兄\nもっと、いい、におい", 3, 7709, 1, 4, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とりま\nお肉、やこ", 3, 7710, 1, 5, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…\nむげん肉まん、も\nきぼう", 3, 7712, 1, 7, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぜんぶ、よんだ\nもっと、ぶあついほん\nでも、いーよ？", 3, 7713, 1, 8, 1, 126101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("幸せなクリスマスを\n過ごすため\nギルドハウスを\nきれいにしなくちゃ♪", 1, 7715, 1, 1, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ♪\n彼へのプレゼント…\n枕元にそっと\nおいておきましょう☆", 1, 7716, 1, 2, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスといえば\n七面鳥の丸焼き…☆\nよだれを拭いて\nいざ準備です♪", 1, 7717, 1, 3, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼に用意した\nプレゼント…\n大きすぎて\nくつ下に入りません…", 1, 7718, 1, 4, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プレゼントは\n貰う方も、贈る方も\nどちらも幸せを\n感じますね…☆", 1, 7719, 1, 5, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜景が見える\nレストランであの人と\nクリスマスデート…\n憧れちゃいますね☆", 1, 7720, 1, 101, 4, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プレゼントはわたし…\n恥ずかしいですけど\nこの贈り物、彼に\n喜んでほしいです…☆", 1, 7721, 1, 102, 8, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オーナメントを\nたくさん用意したので\n二人でツリーに\n飾りつけましょう☆", 2, 7722, 1, 1, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あはは、お腹\n空いちゃいました？\nパーティーまで\n我慢してください♪", 2, 7723, 1, 2, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ジングルベ～ル♪\nあなたも一緒に\nクリスマスソング\n歌っちゃいましょう♪", 2, 7724, 1, 3, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サプライズプレゼント\nの用意をして…って\nあなた！？　い、今の\n聞いてませんよね…？", 2, 7725, 1, 4, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスの夜は\nパーティーしましょう\nできれば…その…\n二人っきりで…☆", 2, 7726, 1, 101, 4, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと過ごした\n最高のクリスマス…\nずっとずっと心の奥に\nしまっておきますね", 2, 7727, 1, 102, 8, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます！\n皆の願いが叶うような\n素敵な一日に\nしましょうね☆", 2, 7728, 1, 1, 1, 127901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ですね！\nディナーの買い出しが\n済んだら、少しお昼寝\nしちゃいましょうか☆", 2, 7729, 1, 2, 1, 127901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ就寝の\n時間ですね～\n枕元にくつ下の準備を\nお忘れなく～☆", 2, 7730, 1, 3, 1, 127901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふ～気持ちいい…☆\nお家でまったり過ごす\nクリスマスも\nいいですよね…♪", 3, 7732, 1, 2, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいですね～♪\nサンタさんからの\n贈り物でしょうか～？", 3, 7733, 1, 3, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すう～…はあ～…\nすごく素敵な香り…\n炊き立てのご飯と\nいい勝負です…♪", 3, 7734, 1, 4, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かいですけど…\nあの日の山小屋を\n思い出して\n恥ずかしいですね…☆", 3, 7735, 1, 5, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むしゃむしゃもぐもぐ\n止まりませんよ\nクリスマスですから\nむしゃむしゃもぐもぐ", 3, 7737, 1, 7, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("物語に出てくる\nサンタさんみたいに\nわたしも幸せを\n運びたいです…☆", 3, 7738, 1, 8, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ！\nこ…これは素敵な\nサプライズプレゼント\nですね…☆", 3, 7740, 1, 14, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これを着ればわたしも\n立派なサンタさんに\nなれますかね…？", 3, 7741, 1, 15, 1, 127901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここが今のあたしの\n居場所ってやつです\nふふっ、なかなか\n悪くねー気分ですよ", 1, 7742, 1, 103, 12, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これからはボス代行\nとしてブイブイ\nいわせてやるです\nついてくるですよ！", 2, 7743, 1, 103, 12, 106601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("陛下～♪\n貴女のクレジッタが\nおめかしして\nはせ参じましたわ～♪", 1, 7744, 1, 1, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パーティーとは景気の\n良さを見せつける場…\n倹約などは\nもっての外でしてよ！", 1, 7745, 1, 2, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この天井の高さなら\n搬入できそうですわね\n陛下用の特注ケーキ♪", 1, 7746, 1, 3, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…ぶぇっくしゅ！\nふう…少し背中を\n開けすぎたかしら…？", 1, 7747, 1, 4, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここは秘書の目も\n届きませんから\nチクりメモの心配も\nありませんのよね～♪", 1, 7748, 1, 5, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いくらでも二度見して\nよろしくてよ？\n本当にわたくしだと\n心から納得できるまで", 1, 7749, 1, 101, 4, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("袖の下以外の贈り物も\nなかなかどうして…\n悪くないものですのね", 1, 7750, 1, 102, 8, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こう見えてダンスの\nたしなみはありますの\nお相手してあげても\nよろしくってよ", 2, 7751, 1, 1, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ドレスはもちろん\n特注品ですわ♪\nもしや貸衣装だと\n思いまして？", 2, 7752, 1, 2, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("バッグの中身？\n仕事に必要なものと…\n心を潤わせるための\n宝石がいくつか♪", 2, 7753, 1, 3, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やる気というものは\n仕事に必要な条件です\nいわばドレスコードの\nようなものですわね", 2, 7754, 1, 4, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("全ての仕事は自分の\n血となり肉となり\nお金にもなるもの\nなのです。経験談です", 2, 7755, 1, 101, 4, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年の教訓を活かして\n来年は更に素晴らしい\nクリスマスにして\n差し上げますわ！", 2, 7756, 1, 102, 8, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n今日という稼ぎ時の\nはじまりですわよ！", 2, 7757, 1, 1, 1, 128001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("安くて早くておいしい\nそれがランチに必須の\n栄養素ですわ！", 2, 7758, 1, 2, 1, 128001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("宵越しの仕事は\n安眠の敵！\n熟睡したいのであれば\n今が勝負時ですわよ！", 2, 7759, 1, 3, 1, 128001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまにはこうして\n休息を取ることも…\n…はっ！？\nドレスにシワが～っ！", 3, 7761, 1, 2, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…わたくしの勘が\n言っていますわ\nこの愛らしさ！\n爆売れ確・定！", 3, 7762, 1, 3, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りですわね…\nお金の匂いには\n敵いませんけれども♪", 3, 7763, 1, 4, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("……ハッ！？\n完全にボーッとして\nしまいましたわ…！\nぬくもり…恐ろしい！", 3, 7764, 1, 5, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("考えませんわ…\n考えませんわよ！\nカロリーのことはっ！", 3, 7766, 1, 7, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビジネス本以外の本を\n読むのも、たまには\n悪くありませんわね…", 3, 7767, 1, 8, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よくできていますわね\nこの絵本！\n子ども向けだと甘く\n見ていましたわ…！", 3, 7769, 1, 14, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この視界の狭さ…\n思い出しますわね\nティッシュ配りの\nアルバイト時代を…", 3, 7770, 1, 15, 1, 128001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふふ…こっそり\nスイーツを食べる\nリノちゃん見～っけ♪", 1, 7771, 1, 1, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんの抜き打ち\nお部屋チェック～♪\n…ケーキの食べこぼし\nこれはリノちゃんだね", 1, 7772, 1, 2, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この衣装は目立つから\nどこにいても弟くんに\n気付いてもらえるね！", 1, 7773, 1, 3, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くん、協力して！\nリノちゃんにお勉強\nしなさいって圧を\nかけるんだよっ…♪", 1, 7774, 1, 4, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("絆の力を感じるよ\nこれならもっと万全な\n弟くんのお世話が\nできそうだねっ！", 1, 7775, 1, 5, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんもたまには\nリノちゃんみたいに\n甘えてみようかな…", 1, 7776, 1, 101, 4, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんとリノちゃん\nどっちも大切な\n私のきょうだいだよ", 1, 7777, 1, 102, 8, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("分かってるよ♪\nお姉ちゃんの膝枕を\nご所望だねっ？　え？\n違う？　違わないよ？", 2, 7778, 1, 1, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リノちゃんがね\nお姉ちゃんチョップを\n防ぐ妹白刃取りを\n訓練してるんだよね", 2, 7779, 1, 2, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃん頭突きは\n封印しないとね…\nだって、今使うと\n頭飾りで威力が…ね", 2, 7780, 1, 3, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ♪\n目をつぶってても\n弟くんは見えてるよ\n…そこでしょ？", 2, 7781, 1, 4, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんも\nリノちゃんみたいに\nかわいさいっぱいに\n振舞っちゃうぞ♪", 2, 7782, 1, 101, 4, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんっ♪\nいつもお姉ちゃんの\n声が届く範囲にいてね\n…絶対だよ", 2, 7783, 1, 102, 8, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう、弟くん！\nリノちゃんが起こして\nくれたんだね♪\n…先を越されちゃった", 2, 7784, 1, 1, 1, 128101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんランチの\n時間だぞ♪\nさ、食べさせてあげる\nお口を開けて…♪", 2, 7785, 1, 2, 1, 128101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おやすみの時間だよ\n…弟くんは真ん中ね\n左右には私たち姉妹が\nいるから安心だよ♪", 2, 7786, 1, 3, 1, 128101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんは全力で\nリラックスしてても\n弟くんの声一つで\nすぐにでも動けるよ♪", 3, 7788, 1, 2, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リノちゃんこういうの\n好きそうだよね\n今度プレゼントして\nみようかな？", 3, 7789, 1, 3, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい匂いがするね～\nあれ？\nリノちゃんのケーキの\n甘い匂いも混ざってる", 3, 7790, 1, 4, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんの\n弟くんへの愛も\n熱く燃えあがるね…！", 3, 7791, 1, 5, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たくさん食べて\n栄養を補給して\nお姉ちゃん力に\n全て変換するよっ！", 3, 7793, 1, 7, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ことわざ辞典…\nリノちゃんにこれを\n読ませようかな", 3, 7794, 1, 8, 1, 128101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろ～り、そろり…\nお姉ちゃんが居ぬ間に\nスイーツを～…♪", 1, 7797, 1, 1, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか\nお姉ちゃんに似合う服\n作ってみたいですね", 1, 7798, 1, 2, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいたっ！？\nひらひらしたとこ\n踏んづけちゃいました", 1, 7799, 1, 3, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんと\nお兄ちゃんの二人から\n勉強しろって圧力が～", 1, 7800, 1, 4, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の中にも秘めた力が\n眠っているはず…\nそう、妹パワーが", 1, 7801, 1, 5, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私もお兄ちゃんを\n甘やかしてみたいです\n…お姉ちゃんみたいに", 1, 7802, 1, 101, 4, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんの部屋を\nこっそり拝見～♪\nはっ！？　これは\nお姉ちゃんの視線…！", 1, 7803, 1, 102, 8, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃん頭突きは\n大地を揺らす威力です\n私とお兄ちゃんは\n挨拶感覚で喰らいます", 2, 7804, 1, 1, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんチョップは\n雲を裂く切れ味です\n早く妹白刃取りを\n完成させないと…", 2, 7805, 1, 2, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんみたいに\n大人っぽく着こなす\nには一体どうしたら…", 2, 7806, 1, 3, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弓のデザインも\nかわいいんですよっ♪\n常に持ち歩きたいです\nけど…危ないですよね", 2, 7807, 1, 4, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きれいな服を着てると\nお姫さま気分に\nなれますね…あとは\n王子さまがいれば…♪", 2, 7808, 1, 101, 4, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんっ！\n私は褒められて伸びる\nタイプなのでもっと\nナデナデしてください", 2, 7809, 1, 102, 8, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("妹モーニングコール♪\nお姉ちゃんより先に\n起こしに来れました！", 2, 7810, 1, 1, 1, 128201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああっ、お姉ちゃん！\nお兄ちゃんにアーン\nするなんてずるいです\n私もしたいですっ！", 2, 7811, 1, 2, 1, 128201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おやすみの時間ですね\nえへへ、きょうだいで\n並んで寝るのって\n楽しいですよね！", 2, 7812, 1, 3, 1, 128201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スイーツを食べた後は\nお腹を休めましょう～\n平気平気…ちゃぁんと\n運動もしますからぁ…", 3, 7814, 1, 2, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんも\nこういうかわいいもの\n好きなんですかね", 3, 7815, 1, 3, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん…\nなんの匂いでしょうか\n新しいスイーツ？", 3, 7816, 1, 4, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きょうだい３人\n肩を寄せて暖まるとか\nよくないですかっ？", 3, 7817, 1, 5, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつも元気な妹で\nいるためには\nよく食べるのが大事！", 3, 7819, 1, 7, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんか姉に関する本が\nちらほらと混ざって…\nこれお姉ちゃんの\n仕業ですね！？", 3, 7820, 1, 8, 1, 128201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふんふんふ～ん\nお正月で世間は\n浮かれてるですねえ\nま、いいですけど♪", 1, 7823, 1, 1, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("は～、お正月は\nだらだらできて\n最高ですね\n…いつも通りですけど", 1, 7824, 1, 2, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ビッグな幹部は\nビッグなお年玉が\nもらえるはずです\n楽しみですね", 1, 7825, 1, 3, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度ドラちゃんに\nお年玉を持っていって\nやりたいですね", 1, 7826, 1, 4, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そういえばアユアユと\n約束してたですよ…\nそろそろ出かける\nですかね", 1, 7827, 1, 5, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お年玉がもらえたら\n何に使うか…\n今のうちに\n考えとくです", 1, 7828, 1, 101, 4, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("年神の報酬の駄菓子が\nたまってきたですね…\nガキどもにでも\n配っちまうですよ", 1, 7829, 1, 102, 8, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしのレアな\n晴れ着姿、今のうちに\nしっかり目に焼き付け\nとくがいいですよ", 2, 7830, 1, 1, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんは今日も\nヒマそうですねぇ…\nしょうがないから\nかまってやるですよ", 2, 7831, 1, 2, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そういえばカヤぴぃ\n見なかったですか？\n喧嘩屋初売りセール\nとか言ってたですけど", 2, 7832, 1, 3, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月ならではの\n大きなシノギ…\nなにかないですかね？", 2, 7833, 1, 4, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいとこに来たですよ\nさっき走ったら帯が\n曲がっちゃったです\n直すの手伝うです！", 2, 7834, 1, 101, 4, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("年神の仕事ですか？\nこれからいくとこです\nお兄さんも一緒に\n来やがるですよ！", 2, 7835, 1, 102, 8, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁあ…\nどうしたですか？\nお正月に早起きなんて\n無粋ってヤツですよ…", 2, 7836, 1, 1, 1, 128301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("小腹が減ったですね\n一緒におせちでも\nつつきにいくですよ！", 2, 7837, 1, 2, 1, 128301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜はあたしの時間\nと言いたいとこですが\n初夢のために早く\n寝とくですかね…", 2, 7838, 1, 3, 1, 128301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月は食っちゃ寝\nするのが仕事…\nって聞いたこと\nあるですよ", 3, 7840, 1, 2, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ、晴れ着の\nあたしの次くらいには\nかわいいですね", 3, 7841, 1, 3, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんかいい匂い…？\nよく知らんですけど\n晴れ着からも同じ\n匂いがしてるですね…", 3, 7842, 1, 4, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふ～あったまるです…\nお正月の唯一の弱点は\n寒いことですからね…", 3, 7843, 1, 5, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…正月太り？\nあたしには関係ない\n言葉ですね", 3, 7845, 1, 7, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったあった…\nトーゴクには\nドラゴンの神宮も\nあるんですね", 3, 7846, 1, 8, 1, 128301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月のトラブルも\nハツネちゃんが\nめでたく解決\nしてみせるのだ～！", 1, 7848, 1, 1, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうだ、新年会に\nサプライズ大作戦を\nしかけちゃおう！", 1, 7849, 1, 2, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イノリちゃんも\nカスミンも振袖姿が\nかわいかったな～", 1, 7850, 1, 3, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シオリンに\nお年玉あげたいし\n彼にバイトを紹介\nしてもらおうかな？", 1, 7851, 1, 4, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度はどんな凧を\n飛ばそうかな？\nみんなが驚くような\n凧がいいよね～", 1, 7852, 1, 5, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひらめいた！\n彼への年賀状は\nきらーんっ☆って\n感じにしよう！", 1, 7853, 1, 101, 4, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("来年も彼の隣で\n初日の出が\n見られるといいな～", 1, 7854, 1, 102, 8, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はキミが\nギルドハウスに来る\n予知夢を見たんだよ～\nふふ、正夢になったね", 2, 7855, 1, 1, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この振袖どうかな？\nすっごくかわいいよね\nえへへ、ありがとう～", 2, 7856, 1, 2, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハツネちゃんおみくじ\n開始！　きらーんっ☆\nキミは大吉なのだ～\nどう元気出たかな？", 2, 7857, 1, 3, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度エルフの森にある\n薬草を使って七草粥を\n作ろうと思うんだ～\nぜひ食べてほしいな♪", 2, 7858, 1, 4, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月っぽい遊びを\n色々と用意したのだ～\nたまにはギルドハウス\nでゆっくり過ごそうよ", 2, 7859, 1, 101, 4, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もしかして眠たいの？\n…じゃあ、また膝枕\nしてあげてもいいよ？", 2, 7860, 1, 102, 8, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いっぱい寝たから\n元気いっぱいだよ～\n今日もがんばろう！", 2, 7861, 1, 1, 1, 128401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼だね～\nおせちがあるから\nキミも食べるでしょ？", 2, 7862, 1, 2, 1, 128401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ寝る時間だね\n今日はどんな夢を\n見られるかな～", 2, 7863, 1, 3, 1, 128401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい座り心地～\n寝正月で過ごすのも\n最高なのだ～", 3, 7865, 1, 2, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいな～\n癒されてぐっすり\n眠れそうだよ～", 3, 7866, 1, 3, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り～\nリラックスすると\n眠たくなっちゃうよ…", 3, 7867, 1, 4, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ポカポカいい気持ち～\n初日の出の温もりを\n思い出しちゃうな～♪", 3, 7868, 1, 5, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ、おいし～\nでもいっぱい食べたら\n眠くなっちゃった…", 3, 7870, 1, 7, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ\nお正月料理も\n色々あるんだね～\n今度作ってみようかな", 3, 7871, 1, 8, 1, 128401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近カレを見てたら\n何故かおいしそうに\n思えてくるんだよな…", 1, 7873, 1, 103, 12, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("手握っててくれるか？\nじゃないとオレ…\n力が抑えきれない…", 2, 7874, 1, 103, 12, 106501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("つかの間の平和を享受\nしながらぬくぬくと\n読書に耽る…\nふふ、最高だね", 1, 7875, 1, 1, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月飾りなんて\n置いたらはしゃいでる\nように見えるかな…？", 1, 7876, 1, 2, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ま、まずい…\n一人遊びしすぎて\nお正月遊びをほぼ\n極めつつある…", 1, 7877, 1, 3, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミステリーは\n時と場所を選ばない\nつまり…新年でも\n探偵は休まないよ！", 1, 7878, 1, 4, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お世話になった人に\n年賀状でも書こうかな\n助手くん、喜んで\nくれるかな…えへへっ", 1, 7879, 1, 5, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("絵馬に願い事を書こう\n助手くんと一緒に\nいられますように…♪\n…は、恥ずかしいな", 1, 7880, 1, 101, 4, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("助手くんはもっと\n派手な着物のほうが\n好みだったかな…？\nき、気になる…", 1, 7881, 1, 102, 8, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やあ。助手くんも\nお正月休みを\n持て余してるのかい？\nふふ、似た者同士だね", 2, 7882, 1, 1, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("助手くん助手くん！\n凧あげしにいこう！\n…そ、捜査の一環で", 2, 7883, 1, 2, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("着物は転びそうで\n怖いんだよなあ…\nお、押さないでね？\nフリじゃないよ！？", 2, 7884, 1, 3, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひ、人目を憚る\n本を読むなら\nみんなが帰省中の今！\nはっ！　助手くん！？", 2, 7885, 1, 4, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ね、ねえ…助手くん…\n一緒に初詣いかない？\nあ、いや！　深い\n意味はないんだけど！", 2, 7886, 1, 101, 4, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あはは…助手くんと\n一緒だと家でごろごろ\nしてるだけでも\n楽しいや…♪", 2, 7887, 1, 102, 8, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁ～…\nお正月休みのおかげで\n昼夜逆転中だよ…", 2, 7888, 1, 1, 1, 128501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月も依頼が\nひっきりなしだね\nさあ、街へ出よう！\nもちろん君も一緒にね", 2, 7889, 1, 2, 1, 128501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("も、もっと\n近くにきてもいいよ？\n冬の夜は…寒いからね", 2, 7890, 1, 3, 1, 128501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ううぅ～…！\nこのままじゃ\n寝正月だぁ…！", 3, 7892, 1, 2, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなが帰省中でも\nこれがあれば\n寂しくない…かな", 3, 7893, 1, 3, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん…♪\nお正月休みの\nリフレッシュに\nちょうどいいや♪", 3, 7894, 1, 4, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…あったまるな\n冬は寒いから\n助かるよ…", 3, 7895, 1, 5, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん、おいしい♪\n読書のお供に\nちょうどいい", 3, 7897, 1, 7, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時間に余裕があると\n読書が進むよ\nいざ、本棚読破だ♪", 3, 7898, 1, 8, 1, 128501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この新しい力…\nさらに使いこなせる\nようになるには…", 1, 7900, 1, 1, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私に眠る属性の力…\n風の力以外には\nどんな力があるのかな", 1, 7901, 1, 2, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今の私なら\nどこまでいけるのか…\nやれるだけ\nやってみよう", 1, 7902, 1, 3, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("風の力の制御…\n段々とコツが\n掴めてきたな", 1, 7903, 1, 4, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("風の力か…\n応用の幅は広そうだ\n何ができそうか\n色々試してみよう", 1, 7904, 1, 5, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度、私とキミで\n料理対決でもする？\n簡単には負けないよ", 1, 7905, 1, 101, 4, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この胸に溢れる\n温かな気持ちは…\nきっと彼への…", 1, 7906, 1, 102, 8, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一段と剣技が\n冴えてきたような…\nいや…油断禁物だ", 2, 7907, 1, 1, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かっこいいって？\nありがとう…そんなに\n真っすぐ褒められると\n照れてしまうな…", 2, 7908, 1, 2, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どれほど厚い壁が\n立ち塞がろうと\n打ち破ってみせる", 2, 7909, 1, 3, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("手が空いてるなら\n剣の稽古に少し\n付き合ってくれるかな", 2, 7910, 1, 4, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("試練を乗り越えて…\n私の中にあるものが\nはっきりと分かったよ", 2, 7911, 1, 101, 4, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キミから流れてくる\n力の温かさ…これが\n私たちの絆なんだ", 2, 7912, 1, 102, 8, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝だよ、そろそろ\n起きる時間だ\nそれとも私に起こして\nほしいのかな？", 2, 7913, 1, 1, 1, 128801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食は私が作るよ\nリクエストはある？\nできる範囲で応えるよ", 2, 7914, 1, 2, 1, 128801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おやすみ。また明日も\n一緒に冒険しよう\n約束だよ？", 2, 7915, 1, 3, 1, 128801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休める時は休む…\n戦い続けるには\n必要なことだからね", 3, 7917, 1, 2, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("心の安らぎの大切さ…\nそれを知れたのは\nキミたちのおかげだね", 3, 7918, 1, 3, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちが落ち着くな…\nこの香り、風の力で\n纏えたりしないかな", 3, 7919, 1, 4, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖まった空気の流れ…\n以前より風の変化に\n気づくようになったな", 3, 7920, 1, 5, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この味付け…\n今度試してみようか\n味見は任せたからね", 3, 7922, 1, 7, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("心技体、すべてを\n鍛えるには座学も\n必要だからね", 3, 7923, 1, 8, 1, 128801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("瞑想するのに\nいいところはあるかな\n集中できて…お昼寝は\n我慢できるところ", 1, 7925, 1, 1, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにはあったかい\n空気が流れてるなぁ…\nみんなが受け入れて\nくれるおかげだね", 1, 7926, 1, 2, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まるで心の中に\n光が満ちてるみたい…\nこの気持ち、みんなに\nおすそ分けしたいな♪", 1, 7927, 1, 3, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この衣装は属性の力を\n反映しやすいんだよね\nキラキラしてるのも\n納得だよ", 1, 7928, 1, 4, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エルフの里のみなさん\n元気かなぁ…\nまた会いに行きたいな", 1, 7929, 1, 5, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだ変身できてる…\nわたしと騎士クンの\n修行の成果\n出てるなぁ…ふふっ♪", 1, 7930, 1, 101, 4, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服を脱いだら\nどうなるのかな…\nた、試す勇気は\nないけど…", 1, 7931, 1, 102, 8, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…あ、騎士クン\nちょうど瞑想してたの\n一緒に…する？", 2, 7932, 1, 1, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("不思議だけど\nいつの間にか\n出たり消えたりするの\n…背中の輪っか！", 2, 7933, 1, 2, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服って肌触りが\nとってもいいんだよ\nさ、触ってみる？\nスベスベだよ？", 2, 7934, 1, 3, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アストラルの力…\nすごく持続できてるね\n修行の成果が出てるよ", 2, 7935, 1, 4, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この力があれば\n暗いところで\n落とし物をしても\n見つけやすいかも…？", 2, 7936, 1, 101, 4, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冒険の準備なら\nできてるよ\nいつでも声をかけてね\n…楽しみにしてる！", 2, 7937, 1, 102, 8, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう騎士クン\n一緒にお散歩とか…\nどうかな？", 2, 7938, 1, 1, 1, 128901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯のあとの\n瞑想って難しいんだよ\n眠くなっちゃって…", 2, 7939, 1, 2, 1, 128901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜ふかしさんは\nほどほどにね？\n一日頑張った自分を\n休ませてあげないと", 2, 7940, 1, 3, 1, 128901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("のんびりしてたら\nケーキが食べたく\nなっちゃうなぁ…\nでも太る…よね…？", 3, 7942, 1, 2, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わあ、かわいい…！\n見てるだけで\nにやけちゃう…♪", 3, 7943, 1, 3, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは…花の香りかな\n知ってる花かも…？\n当ててみようっ", 3, 7944, 1, 4, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいと\nどうしてこんなに\n落ち着くんだろう…", 3, 7945, 1, 5, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べ過ぎたらお腹が\n目立っちゃうかもって\n分かってるのに…！\n止められないよ～っ！", 3, 7947, 1, 7, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こ、恋の精霊とか\nいたりするのかな…？\nはっ！　ダメダメっ！\n実力で頑張らないと", 3, 7948, 1, 8, 1, 128901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お部屋の中でも\n修行、修行っ♪\nでも燃やさないように\n注意しなきゃだね", 1, 7950, 1, 1, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん…この衣装\n厚着か薄着か\nどっちなんだろう…？", 1, 7951, 1, 2, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもの肉球がない分\nお片付けしやすいな♪\n騎士くんのお部屋\nピカピカにしとこー！", 1, 7952, 1, 3, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お休みは騎士くんと\nＢＢＱに行きたいなー\nあたしと一緒なら\n火の心配はいらないよ", 1, 7953, 1, 4, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この姿ならもっと\n人を助けられる…！\nえへへっ！\n燃えてきたーーっ！", 1, 7954, 1, 5, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士くんが帰ったら\nアイラみたいな笑顔で\nお疲れさまさまって\nお出迎えしよっと…♪", 1, 7955, 1, 101, 4, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この姿の時、いつも\n胸が熱く燃えてるのは\nずっと騎士くんのこと\n考えてるからかな…？", 1, 7956, 1, 102, 8, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士くん騎士くん！\nあたしに触れると\nやけどしちゃうよ…？\nなんちゃってー♪", 2, 7957, 1, 1, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっ、騎士くん\n修行に行きたいの？\nえへへっ、いいねー♪\n二人で燃えちゃおー！", 2, 7958, 1, 2, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうだ騎士くん\nじゃんけんしよっか？\nグローブ外してるから\nチョキも出せるよっ♪", 2, 7959, 1, 3, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この姿でいられる時間\nすごく増えてきた…！\nえへへ！　あたしたち\n修行の成果出てるね！", 2, 7960, 1, 4, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じっと見つめないでよ\n顔が真っ赤に…やば！\nほんとに顔から\n火噴いちゃいそう…！", 2, 7961, 1, 101, 4, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("火には強くなれても\n騎士くんに触られた\nほっぺはずーっと\n熱くてたまんないや…", 2, 7962, 1, 102, 8, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよー騎士くん！\n今日も一日\n燃え滾っていくよー！\nファイヤーッ！！", 2, 7963, 1, 1, 1, 128701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士くんお昼だよ！\nちゃんとご飯食べて\n午後からの修行も\n乗り切ろうねー！", 2, 7964, 1, 2, 1, 128701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もお疲れさま！\nそうだ、寝る前に\nキャンプファイヤー\n囲んじゃおっか♪", 2, 7965, 1, 3, 1, 128701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼふーんっ！\nえへへ、気持ちいい…\n修行の前に\nちょっと休憩ー♪", 3, 7967, 1, 2, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいな～♪\nなでなでなでなでなで\nなでなでなでなでっ！\nあははっ、摩擦熱！", 3, 7968, 1, 3, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～いい香り♪\n少し熱したほうが\n香りが広がるね…って\n蒸発しちゃった！！！", 3, 7969, 1, 4, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外でも自分の火で\nあったまれるけど\nお部屋でぬくぬく\nするのが一番だよね♪", 3, 7970, 1, 5, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐっ！\nお腹が減っては\n人助けはできずっ！\nもぐもぐもぐっ！", 3, 7972, 1, 7, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\nなるほどなるほど…\n…これが上手な\nＢＢＱのやり方か…", 3, 7973, 1, 8, 1, 128701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…壁も扉も柱も\n全て記録で見たまま\n本当に…来ているのね", 1, 7975, 1, 1, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…騒がしい場所\n騎士クンが受け入れて\nくれるのをいいことに", 1, 7976, 1, 2, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここが…騎士クンの\n守りたかった場所\n騎士クンの思い出が\n詰まった場所…ね", 1, 7977, 1, 3, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("視線を感じる…\nこちらの様子を\n探るような…心の動き\n取るに足らないけれど", 1, 7978, 1, 4, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…そこかしこで…\n言葉にもしたくない\n相手が過ごしていた\n記録を思い出す…", 1, 7979, 1, 5, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人は多いけれど…\n雪深い山中よりは\n過ごしやすい…か", 1, 7980, 1, 101, 4, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自覚したことは\nあまりなかったけれど\nひどく…諦めの悪い女\nなのかもしれない", 1, 7981, 1, 102, 8, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お招きありがとう\nそれで…何をして\nいればいい…かな？", 2, 7982, 1, 1, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここは…明るいね\nわたしの城と比べると\nなんだか眩しいくらい", 2, 7983, 1, 2, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仮面はもう必要ないよ\nだって…わたしの顔を\n騎士クンに見て\nもらえなくなるから", 2, 7984, 1, 3, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンさえよければ\nわたしの城に専用の\n部屋を用意するよ\n…いつでも", 2, 7985, 1, 4, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…騎士クンのマント\nまた貸してほしいな\nきれいに使うから\n…だめ？", 2, 7986, 1, 101, 4, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか二人の願いが\n重なり合えるって…\n信じているね\n…いつまでだって…", 2, 7987, 1, 102, 8, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう、騎士クン\n…昨日は夢の中で\nお話ししすぎちゃって\nごめんね。ふふっ", 2, 7988, 1, 1, 1, 129001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹は…空いてない？\n食べ物はないけれど\n空腹を忘れる魔法なら\nかけてあげられるよ", 2, 7989, 1, 2, 1, 129001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クン…\nまだ、眠らないの？\n…そう。それなら…\nわたしも起きているね", 2, 7990, 1, 3, 1, 129001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("肩の力を抜くには…\nまだ時間がかかりそう\nきっと…騎士クンと\n二人きりなら別なのに", 3, 7992, 1, 2, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぺんぽこりん…\nそう、確かあれも\nこんな感じだった…", 3, 7993, 1, 3, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("花の香りは…好き\nつかの間\n心を穏やかに\nしてくれるから", 3, 7994, 1, 4, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたたかい…けれど\n騎士クンの優しさに\n比べれば、まだまだ", 3, 7995, 1, 5, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おい、しい…？\nこの感覚が、それ？\nなぜか…納得できる", 3, 7997, 1, 7, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("情報を入手するには\nわざわざ本を開く\n必要があるだなんて…\nプレイヤーは面倒ね", 3, 7998, 1, 8, 1, 129001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メルクリゾートか…\n良い記憶はないな\nよし忘れよう", 1, 8000, 1, 1, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("知性の戦士ユニ！\nその恐るべき筋力！\nふおお！　うにゃー！", 1, 8001, 1, 2, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽーん！\n石用の水着ください！\nセクシーロゼッタが、\n渚の視線を独占です！", 1, 8002, 1, 3, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("学院から奨学金を\n勝ち取るより某財団を\nだまくらかした方が\n早い気がしてきたな…", 1, 8003, 1, 4, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わんつぅ、わんつぅ…\nんぎゃあ足攣ったー！\nおのれカルミナとやら\n絶対に許さん！", 1, 8004, 1, 5, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ところで…なぜぼくは\nプールでもないのに\n水着のままなんだ…\nおのれ世界め！", 1, 8005, 1, 101, 4, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼と二人で撮った動画\nうう、凝視に耐えん…\nなんだこのムズ痒さは", 1, 8006, 1, 102, 8, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なに？　水着姿で\n寒くないのかだと？\n普段からもっと薄着の\n娘が沢山いるだろう", 2, 8007, 1, 1, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シノブ君にメリゾの\n招待状を送ったのだが\n御尊父の暴走を\n心配していたな…", 2, 8008, 1, 2, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミミ君らにメリゾの\n招待状を送ったのだよ\n迎える準備をせねば…\nおしゃぶり持ってる？", 2, 8009, 1, 3, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本質の賢者…？\nいや元気にしているが\nなぜ君がぼくの身内を\n知っているんだ…？", 2, 8010, 1, 4, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着が似合ってる？\nな、なんだね突然…\nやめたまえよふひひ…", 2, 8011, 1, 101, 4, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度は夏にメリゾへ\n行きたいものだ\nむろん君も一緒だぞ", 2, 8012, 1, 102, 8, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぐああっ、朝陽が…！\n朝陽が昇っている…！\n夜行性ユニ死んじゃう", 2, 8013, 1, 1, 1, 129301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…もう昼か…\nそろそろ寝ないとな\n規則正しい生活を\nしないと不健康だ…", 2, 8014, 1, 2, 1, 129301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃっはー、夜だー！\nオレたちの時間だぜ！\nふおおブチ上がり～！", 2, 8015, 1, 3, 1, 129301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは…ぼくにここで\n寝ろということか？\n一向に構わんが…", 3, 8017, 1, 2, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きゃっきゃっ！\nこれかわい～！\n…よし、今日も\n子供の擬態完璧だな", 3, 8018, 1, 3, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ、良い香りだ\nだがそれだけか…\nとくに精神高揚効果は\nないのか…ちぇー", 3, 8019, 1, 4, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("火を見ていると…\n魔導罐を思いだすな…\nかに座、元気かな…", 3, 8020, 1, 5, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ええい、\n固形食物はいらん！　\nポーションを出せ！", 3, 8022, 1, 7, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やはり書は文系に限る\nなんと心地よい筆致…\nぐああ突然理系文が！\nひぃ目が理系になる！", 3, 8023, 1, 8, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほああ～！\n知性の海上騎士ユニ！\nこれは新たな可能性！", 3, 8025, 1, 10, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは…なんだ？\n何が面白いんだ？\n難しいな…", 3, 8026, 1, 11, 1, 129301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大切な人と過ごす\n正月の思い出、か…\n昔の私だったら\n考えられなかったな", 1, 8027, 1, 103, 12, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("叶えたい願いなら\nたくさんあるよ\nそれでも一番を選ぶ\nなら、やはりキミと…", 2, 8028, 1, 103, 12, 108901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("神殿にあった\n恋愛おみくじ…\n引いてみようかな…", 1, 8029, 1, 103, 12, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クン。来年も\nまた一緒におみくじ\n結ぼうね。約束だよ", 2, 8030, 1, 103, 12, 108801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度は騎士くんと\n一緒にうつった写真、\nおばあちゃんに\n送ろうっと♪", 1, 8031, 1, 103, 12, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、騎士くん！\n今年も…ううん\nこれからも、よろしく\nおねがいします♪", 2, 8032, 1, 103, 12, 108701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("旧校舎の地下牢…\n真冬のサマー計画…\n等身大のＰＲ…\nうッ、頭が…！", 1, 8033, 1, 1, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇だし鏡でも見るか。\nお、いい腹筋育って…\nあ？　何見てんだコラ", 1, 8034, 1, 2, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オレは金色の疾風！\nんん…なんか違うな。\n我が名は金色の…\nあ？　何見てんだコラ", 1, 8035, 1, 3, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("モニカとユニ先輩って\n口調と身長似てるけど\n子供扱いに対する\n反応は真逆だよね…", 1, 8036, 1, 4, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シオリン元気かな…\n昔くちゃくちゃに\n撫でくり回して\n嫌がられたっけなァ…", 1, 8037, 1, 5, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("べつにいんだけどさ…\nあんたの知り合いって\n普段から水着みたいな\nカッコの女多くない？", 1, 8038, 1, 101, 4, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そだ、弟らがあんたに\n会いたがってたンだ。\n暇だったらいつでも\nウチ来てやってよ", 1, 8039, 1, 102, 8, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("特別講座は色々あった\nけど…メリゾ自体は\nまあ悪くなかったよね", 2, 8040, 1, 1, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着と合わせる小物に\nセンス出るよね、\nって話をミィコ先輩が\nしててマジわかりみ", 2, 8041, 1, 2, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着のミフユねえさん\nやっぱ仕上がってたね\nあれが竜殺しの体か…\nバリかっけーな…", 2, 8042, 1, 3, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はにょんっ！？\nや、だからさ…\n後ろから声かけんな、\nつってンじゃん…", 2, 8043, 1, 4, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリゾの特別講座が\n上手くいったのも\n敏腕カメラマンがいた\nお陰だよ。ありがとね", 2, 8044, 1, 101, 4, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ？　この水着が？\n似合っ…え、なんて？\nごめ、聞こえんくて。\nもっかい言ってみて", 2, 8045, 1, 102, 8, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう朝とかマジないわ\n昨日二人に付き合って\nオールでカラオケだよ", 2, 8046, 1, 1, 1, 129401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ授業行かなきゃ…\n真っ昼間から勉強とか\nマジつらたん過ぎ…", 2, 8047, 1, 2, 1, 129401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日これから夜勤で…\nいやバイトちゃーくて\nボランティアの話よ？\n校則違反よくない", 2, 8048, 1, 3, 1, 129401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うわ、ふっかふか…\nオニほど安らぐわ…\nやば、ユニってくる…", 3, 8050, 1, 2, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちも妹いりゃ\nこーゆーのもなァ…\nま自分用でもいいか", 3, 8051, 1, 3, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふーん…\nいいじゃんこの香り\n抜群に嗅げるわ", 3, 8052, 1, 4, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちン家のルーツの森\n大火災でなくなった\nらしンだよね…\n生まれる前の話だけど", 3, 8053, 1, 5, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何コレありがてぇー\n食料ほくほく過ぎて草\n米ガチで尊いわァ…", 3, 8055, 1, 7, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいけど、なんでうち\n水着で本読んでンだよ\nどーゆープレイだよ", 3, 8056, 1, 8, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("金色の海上騎士クロエ\n推して参る！　覇ァ！\nあ？　何見てんだコラ", 3, 8058, 1, 10, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何コレ、貝の椅子？\nどーやって遊ぶんだ…\nいや座って終わりか…\nまァそりゃそーか…", 3, 8059, 1, 11, 1, 129401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さてと…\n明日の訓練メニュー\n考えねえとな", 1, 8060, 1, 1, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("また新入りの女子に\n弁当もらっちまった…\nありがたく食うけどよ", 1, 8061, 1, 2, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("種族なんて関係なく\nみんなが力を合わせて\nランドソルを守る…\nいい時代になったよな", 1, 8062, 1, 3, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誰にだって長所はある\n新入りのいいところを\n見つけてやるのも\n教官の仕事だ", 1, 8063, 1, 4, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("厳し過ぎても\n甘過ぎてもダメ…\n教官ってのは難しいぜ", 1, 8064, 1, 5, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦いが苦手な新入りを\nどうフォローするか…\n後であいつと\n相談してみるか", 1, 8065, 1, 101, 4, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつは優し過ぎて\n戦いに向いてねえ\n…そういう甘さ\n嫌いじゃねえけどな", 1, 8066, 1, 102, 8, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("強くなる近道はねえ\n地道な鍛錬あるのみだ\nさ、訓練始めるぞ！", 2, 8067, 1, 1, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新入りにも\nいつも言ってるが…\n装備の手入れは\n念入りにしろよな？", 2, 8068, 1, 2, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("座学も受けてえのか？\nいい心がけだな！\nなんでも教えてやるよ\n…魔法以外ならな", 2, 8069, 1, 3, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新入りたちがよく\n恋バナしててな…\nお、おまえは…誰か\n気になるやついるか？", 2, 8070, 1, 4, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なあ、ストレッチ\n手伝ってくれねえか？\n訓練前にしっかり\n筋肉ほぐさねえと…", 2, 8071, 1, 101, 4, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ずいぶん頑張って\n鍛えたよな、おまえ\nよし！　ご褒美に\nお菓子作ってやるよ♪", 2, 8072, 1, 102, 8, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("訓練日和だな！\nさぁて…まずは\n走り込みといくか！", 2, 8073, 1, 1, 1, 129801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼飯はしっかり食えよ\nでなきゃ、\nこの後もたねえぜ？", 2, 8074, 1, 2, 1, 129801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とっくに消灯時間だ\nさっさと寝な？\n明日も早いんだからよ", 2, 8075, 1, 3, 1, 129801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休むのも訓練のうちだ\n今はのんびり\nさせてもらうぜ", 3, 8077, 1, 2, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい面構えだ\n気に入ったぜ！\nあたしの班に入るか？\n…なんてな♪", 3, 8078, 1, 3, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…いやされる匂いだな\n新入りたちにも\nすすめてみるか…", 3, 8079, 1, 4, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったけえからって\n寝ないようにしねえと\n教官としての\n威厳に関わるからな…", 3, 8080, 1, 5, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食事も訓練の一環だ\nとはいえ食い過ぎには\n気をつけねえと…", 3, 8082, 1, 7, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トーゴクの剣術…か\nなにか訓練に\n活かせるかもしれねえ", 3, 8083, 1, 8, 1, 129801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのおかたに近付く\n不埒な輩には、特別な\n訓練で地獄を見て\nいただきましょう", 1, 8085, 1, 1, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これだけ広ければ\n多少派手に\n動き回っても\n問題なさそうですね", 1, 8086, 1, 2, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…今誰か私を\n「鬼」教官と\n呼びませんでしたか？", 1, 8087, 1, 3, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しく開発したこの薬\n誰か試してくれる人は\nいませんか？", 1, 8088, 1, 4, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("厳しくすれば投げ出し\n優しくすればサボる\n人というのはどこまで\n度し難いのでしょう", 1, 8089, 1, 5, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はじめましょう\nあのおかたの心を\n射貫くための\nシミュレーションを", 1, 8090, 1, 101, 4, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あらゆる苦難と\n忌々しい女から守る\nためにも、私自身も\n鍛えておかねば", 1, 8091, 1, 102, 8, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなた様、そんなに\n見つめられると…え？\nエリコはカッコいい？\nええ、当然ですとも", 2, 8092, 1, 1, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("不調があればすぐ\n報告してください\n体のケアも教官の\n大事な役目ですので", 2, 8093, 1, 2, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しい訓練器具の\n使い心地はどう…え？\n重すぎる？　これでも\n軽くしたのですが…", 2, 8094, 1, 3, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("運動後には特製の\n栄養ドリンクをどうぞ\nクスクス、何も\n入れたりしてませんわ", 2, 8095, 1, 4, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よくがんばりました\nあなた様。あぁ…\nお疲れになったお顔も\n素敵ですわ", 2, 8096, 1, 101, 4, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなた様、二人だけの\n遠征訓練へ\nまいりましょう。\n既に準備万端ですわ", 2, 8097, 1, 102, 8, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだ眠いですか？\nならばストレッチで\n体を痛めつ…ではなく\nほぐしていきましょう", 2, 8098, 1, 1, 1, 129901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼はお弁当をご用意\nいたしました。量も\nスタミナも増し増し\n残さず食べてください", 2, 8099, 1, 2, 1, 129901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よい睡眠こそ健やかな\n体に不可欠。ですので\n私が寝ずの番をさせて\nいただきますわ", 2, 8100, 1, 3, 1, 129901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休憩用に使おうと思い\nましたが、心地よくて\n立てなくなって\nしまいますわ…", 3, 8102, 1, 2, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("中に重しを詰めれば\n愛でながら運動が\n可能ですわ", 3, 8103, 1, 3, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("香りでリラックスさせ\n同時に暗示を\nかけてみましょうか", 3, 8104, 1, 4, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…くっ、眠気を誘う\nこの暖かさ…\n油断も隙もありません", 3, 8105, 1, 5, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主食はこちらで十分\nまかなえますわね\nそれでは私はおかずを\n作りましょう", 3, 8107, 1, 7, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まあ、実用書の類も\n揃っているのですね\nとても助かりますわ", 3, 8108, 1, 8, 1, 129901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("……（そわそわ）", 1, 8110, 1, 1, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここに寄らずの花陣…\n作ったらダメですよね", 1, 8111, 1, 2, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋の隅が\n落ち着きます\nそれか、陽の当たる所", 1, 8112, 1, 3, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身を隠せる場所が\nあると…\n助かるんですけど", 1, 8113, 1, 4, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("複雑な造りの家ですね\n触って壊れたり─\nしませんか？", 1, 8114, 1, 5, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("出入りするひと\nみんな、笑顔…\n…変わった家ですね", 1, 8115, 1, 101, 4, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この家なら安全─\nかもしれません\n魔物が出ないので", 1, 8116, 1, 102, 8, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これも、視察の一環\n遊びに来たわけじゃ\nないです", 2, 8117, 1, 1, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("長話─苦手です\n疲れるので…\nふぅ…", 2, 8118, 1, 2, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここで友達を作れと\nネアさんが…\nそう、言われても…", 2, 8119, 1, 3, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("世話をするのは\n得意です\n…花の、ですよ？", 2, 8120, 1, 4, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("媛へのお土産を\n探してるんですけど…\n…貴方のおすすめ、\n聞いておきます", 2, 8121, 1, 101, 4, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("平和でのんきで…\n貴方らしい家です\n一応、褒めてます", 2, 8122, 1, 102, 8, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("花に、お水─？\n…いりません", 2, 8123, 1, 1, 1, 129601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日が高いうちは\nむやみに外へ出ません\n面倒事、多いので…", 2, 8124, 1, 2, 1, 129601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜番。私がします\nあまり眠らない\n性質なので…", 2, 8125, 1, 3, 1, 129601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここなら根を張れる\nかもしれません\n…張りませんけど", 3, 8127, 1, 2, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなにやわな体じゃ\n身を守れませんよ─\n…あ。生き物じゃ\nないんですね", 3, 8128, 1, 3, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("花みたいに─\nいい匂い、です", 3, 8129, 1, 4, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("火を見てると、\nジオ・ゲヘナを\n思い出します…ふぅ", 3, 8130, 1, 5, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食事も立派な戦支度\n媛が言ってました", 3, 8132, 1, 7, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("知識も武器の一つだと\n媛が…でも、\nこれでどうやって…？", 3, 8133, 1, 8, 1, 129601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("天気もいいしお花畑に\nピクニックでも\n行こうかな♪", 1, 8135, 1, 1, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、どこからか\nお花の匂いが…\nいい香りですね", 1, 8136, 1, 2, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しいシャベルとか\nじょうろもほしいなぁ\nお小遣いしっかり\nためないとね", 1, 8137, 1, 3, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お花飾りたいけど\n花瓶はどこかな…\nあとであの人に\n聞いてみよっと", 1, 8138, 1, 4, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お花の観察日記\n書かなきゃ\n日々勉強は\n欠かせませんよ", 1, 8139, 1, 5, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("衣装にお花を足して\nみたけど、あの人\n気付いてくれるかな？", 1, 8140, 1, 101, 4, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この花冠、上手に\n作れたかも…\n日頃のお礼にあの人に\nあげようかな…", 1, 8141, 1, 102, 8, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたは何のお花が\n好きですか？　ほら、\n一応知っておいたら\n役に立つかもですし", 2, 8142, 1, 1, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そのお花、乱暴に\n扱っちゃダメですよ\n花粉が服について\nとれなくなりますから", 2, 8143, 1, 2, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("土いじりしたから\n服が汚れてますよ\nはたいてあげますから\nじっとしててください", 2, 8144, 1, 3, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そんなにすぐに芽は\n出ませんよ\nまあ、楽しみなのは\n私も同じですけど…", 2, 8145, 1, 4, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この衣装、そんなに\n気になります？　なら\nこうしてお花を\n着ければおそろいです", 2, 8146, 1, 101, 4, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お花の種を私に？\nありがとうございます\nせっかくなので一緒に\nお世話しませんか？", 2, 8147, 1, 102, 8, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お花にお水をあげるの\n手伝ってもらえます？\nお水は朝にあげるのが\nいいんですよ", 2, 8148, 1, 1, 1, 130701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とっておきのお花見\nスポットに\nご案内しますよ\nお弁当も忘れずに！", 2, 8149, 1, 2, 1, 130701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間\n早く寝ましょう\n草木も眠るなんとか\nって言いますからね", 2, 8150, 1, 3, 1, 130701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お花のお手入れって\nけっこう疲れますね…\nここでちょっと一息\nしちゃおっと", 3, 8152, 1, 2, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("耳にお花を着ければ…\nえへへ、すっごく\nかわいくなったね！", 3, 8153, 1, 3, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これはラベンダー\nこっちはミモザ\nフローラル系の香り\nっていいですねぇ", 3, 8154, 1, 4, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ポカポカしますね～\nまるで春の陽気\nみたいです～", 3, 8155, 1, 5, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お花を一輪さすだけで\nご飯の時間がとても\n華やかになりますね", 3, 8157, 1, 7, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お花の本が\nいっぱいある！\n今日はこれで\nお勉強です！", 3, 8158, 1, 8, 1, 130701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふんふ～ん♪\n華やかな服を着ると\n心がウキウキします♪", 1, 8160, 1, 1, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("花祭りで出会った\nみなさん…\nお元気でしょうか？\nまたお会いしたいです", 1, 8161, 1, 2, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はっ！　そうでした\nこの服の時は\nメイドのお仕事は\nお休みでした…", 1, 8162, 1, 3, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服は替えが\nありませんから\n大きなドジには\n気を付けないと…", 1, 8163, 1, 4, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("目立ったほつれもなし\n…うん、いい感じに\n補修できました♪", 1, 8164, 1, 5, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メイド姿でなくても\n心はいつでも\nお嬢さまの\nメイドです♪", 1, 8165, 1, 101, 4, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服を着ると心が\n浮き立つのはあのかた\nと一緒にいる気持ちに\nなるからでしょうか？", 1, 8166, 1, 102, 8, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はい、今日は一日\nこの服で過ごそうと\n思います\n変じゃないですよね？", 2, 8167, 1, 1, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("花祭りのおかげで\n少しだけお花に\n詳しくなった…\nような気がします！", 2, 8168, 1, 2, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("花祭り、今度は\nお嬢さまと救護院の\nみんなと一緒に\n行ってみたいですね", 2, 8169, 1, 3, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度キョウカちゃんと\n花祭りの服でお花を\n見にお出かけ\nするんです", 2, 8170, 1, 4, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メイド服を全部洗濯\nしちゃうなんて…\nドジっちゃいましたぁ", 2, 8171, 1, 101, 4, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("花祭りの服は私たちの\n思い出の服ですから…\nこれからも\n大切にします♪", 2, 8172, 1, 102, 8, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はう、そうでした\nお花にお水を\nあげる時間です！", 2, 8173, 1, 1, 1, 130801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯は\nバスケットを持って\nお花畑に食べ\nに行きませんか？", 2, 8174, 1, 2, 1, 130801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁあ…繕い物を\nしていたらこんな時間\nになってしまいました\n早く寝ないと…", 2, 8175, 1, 3, 1, 130801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわふわしてて\nきもちいいです～\nどんな生地を\nつかってるんだろ～？", 3, 8177, 1, 2, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいですね～\nぬいぐるみさんにも\n服をつくって\nあげたいです♪", 3, 8178, 1, 3, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りです～\nあれ？　もしかして\n私の服についてる花と\n同じ香りが…？", 3, 8179, 1, 4, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かいですけど\nあまり近づいちゃうと\n頭の花飾りが乾燥\nしちゃいそうですね…", 3, 8180, 1, 5, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…\nいい花を咲かせるには\nしっかりとした栄養が\n必要だそうです！", 3, 8182, 1, 7, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なるほどなるほど…\nお花のお手入れは\n奥が深いですね…", 3, 8183, 1, 8, 1, 130801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マホマホ王国にも\nサーカス団設立や\n夢と希望を届けますえ", 1, 8185, 1, 1, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくの晴れ舞台や\nかっこいいポーズも\nできるようにしたいわ", 1, 8186, 1, 2, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むむむむ～っ。うーん\nクルルはんみたいに\n胸から宝石を出すんは\n難しいみたいやわ", 1, 8187, 1, 3, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あむっ…んん～♪\nやっぱり練習のあとは\n甘いものに限るわぁ", 1, 8188, 1, 4, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アーサーたちの衣装も\n今のうちに考えんと…\n生地、足りるやろか", 1, 8189, 1, 5, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はんとなら\nどんなアイデアも\n見つけられます♪", 1, 8190, 1, 101, 4, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちの晴れ姿が\n王子はんの目に一等\n輝いて見えますように", 1, 8191, 1, 102, 8, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キリっとしたうちも\nかっこいい？\nもう、上手やなぁ", 2, 8192, 1, 1, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しい演目考えたんよ\nなぁ王子はん、意見\n聞かせてもらえます？", 2, 8193, 1, 2, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("聞いてや王子はん\n動物さんたちとさらに\n息が合うてきたんよ\nみんな頑張り屋さんや", 2, 8194, 1, 3, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("演技の感想なら\n大歓迎どすえ♪\nたんと聞かせてや～", 2, 8195, 1, 4, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子はん、本番当日は\n最前席で見たってな\nそしたらうち、もっと\n頑張れますさかい♪", 2, 8196, 1, 101, 4, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この技をあなたに\n捧げます…なんて♪\n驚いたやろ？\nどっきり作戦成功や♪", 2, 8197, 1, 102, 8, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵なショーのためや\n今日も焦らず一歩ずつ\n成長していきまひょ\nな、王子はん♪", 2, 8198, 1, 1, 1, 131001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お弁当、王子はんも\n一緒にいかがどす？\nみんなで食べて団結や", 2, 8199, 1, 2, 1, 131001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜のサーカスも\n幻想的でとっても\n魅力的なんよ\n一緒にいきまひょか♪", 2, 8200, 1, 3, 1, 131001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("練習が終わったあとは\nの～んびりして\n体力を回復せな…", 3, 8202, 1, 2, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子たちとなら\n空中ブランコや\n玉乗りもええなぁ", 3, 8203, 1, 3, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りやなぁ\n本番前の緊張も\n和らげてくれそうやわ", 3, 8204, 1, 4, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このあったかい感じ…\nスポットライトの熱を\n思い出すわぁ", 3, 8205, 1, 5, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちゃんと食べへんと\nいい演技はできまへん\n団長はんも言うてたわ", 3, 8207, 1, 7, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("動物さんたちのことも\nもっと勉強せな\n大事な仲間やさかい", 3, 8208, 1, 8, 1, 131001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("器用じゃないが、\n情には厚いよ\nこういう女を「一途」\nってそう言うんだろ？", 1, 8210, 1, 103, 12, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("斬れないものはないと\n思ってきたさ。だけど\n…この気持ちだけは\n斬れないね、絶対に", 2, 8211, 1, 103, 12, 105601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んしょ、んしょっ…！\n日頃の感謝を込めて\nヒーローさんのお家を\nきれいにしますです♪", 1, 8212, 1, 1, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\n新アトラクションは\nこのギルドハウスを\nモチーフに…", 1, 8213, 1, 2, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ごそごそ、こそこそ…\nヒーローさんに内緒で\nどこかにお礼の宝石を\n隠しておきましょう…", 1, 8214, 1, 3, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パークの運営が\n落ち着いたら\nわたしもギルド活動？\nしてみたいですます♪", 1, 8215, 1, 4, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなすてきな\nおうちに住めたら…\nいえ！　うさぎ小屋で\n十分です～っ", 1, 8216, 1, 5, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒーローさんのおうち\nだって意識したら\nアトラクションよりも\nドキドキしてきます…", 1, 8217, 1, 101, 4, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒーローさんのことを\n考えると顔が赤く…\nこれってもしかして\nひょっとして…？", 1, 8218, 1, 102, 8, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、ヒーローさん！\n話しかけてくれた記念\nということで、宝石\n受け取ってください♪", 2, 8219, 1, 1, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("元気がない時は\n語尾にぴょんですっ！\nさあヒーローさんも\nやってみるぴょん♪", 2, 8220, 1, 2, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒーローさんへのご恩\nおばあちゃんうさぎに\nなるまでに、お返し\nできるでしょうか…？", 2, 8221, 1, 3, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒーローさん！\n二人で一緒に\nパレードの練習\nしませんか～♪", 2, 8222, 1, 4, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あはは♪\nヒーローさんは\n人を笑顔にする力が\nありますです♪", 2, 8223, 1, 101, 4, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒーローさんに\n一日一恩返しですっ！\n返し終わるまで\nやめませんですます♪", 2, 8224, 1, 102, 8, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます♪\nんしょ、んしょっ…！\n気持ちよく起きられた\n記念に宝石どうぞ♪", 2, 8225, 1, 1, 1, 130901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼にフードコートで\nかばばん君バーガー\n買ってきましたよ！\n一緒に食べますです♪", 2, 8226, 1, 2, 1, 130901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も一日\nお疲れさまですっ♪\nマッサージしますから\n寝そべってください♪", 2, 8227, 1, 3, 1, 130901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はふぅ～…♪\nお仕事の疲れも\nぴょんぴょ～んって\n飛んでっちゃいます♪", 3, 8229, 1, 2, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁっ、とっても\nかわいいですますっ！\nギルドハウスの\nマスコットですね♪", 3, 8230, 1, 3, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒーローさんの好きな\n香り…これを宝石に\nつければ、受け取って\nもらえるでしょうか？", 3, 8231, 1, 4, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はあ、気持ちいい♪\nヒーローさんの\n好きな温度に\n調整しときますです♪", 3, 8232, 1, 5, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("支配人は体が資本っ！\nたくさん食べ…すぎて\n動けなくなっちゃい\nましたぁ～…！", 3, 8234, 1, 7, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パークの\nガイドブックとか\nあったらいいですね♪", 3, 8235, 1, 8, 1, 130901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外あつすぎ溶けるわ～\nやっぱ部屋ん中で\n水着がラクだねー", 1, 8237, 1, 1, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ン～\nカリザきゅんどこー？\nもしかして逃げた？", 1, 8238, 1, 2, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ミソラちゃんと\nリリちゃん誘って\nそろそろイイコト\nしよっかなー？", 1, 8239, 1, 3, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おねえちゃんに\n頼まれたシゴトは\nまた今度にすっかー\n夏休みだしー♪", 1, 8240, 1, 4, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士きゅんの\nプリンセスフォームも\n見てみたいんだよなー\nンフ♡", 1, 8241, 1, 5, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スライムを\nこーしてあーしたら\n騎士きゅんの泳ぐ\n練習に使えるっぽ？", 1, 8242, 1, 101, 4, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おかえり～♡\nって水着で迎えたら\n騎士きゅん喜んで\nくれるかなー？", 1, 8243, 1, 102, 8, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士きゅん\nこのサングラス\nかけてみる？\nぜってー似合うよー", 2, 8244, 1, 1, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日焼け痛かったら\nいつでも言ってねー\nスライムでひんやり\nしてあげるよ～♪", 2, 8245, 1, 2, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今から外で\n焼いてこっかなー\n騎士きゅんもどー？", 2, 8246, 1, 3, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スライムマッサージ\nしてあげよっかー\nほーれ、もみもみ～♡", 2, 8247, 1, 4, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士きゅんが選んだ\n水着も着てみたーい\nネアおねえちゃんに\nどんなの着てほしい？", 2, 8248, 1, 101, 4, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士きゅ～ん\n尻相撲しよっかー♪\nおねえちゃんに\n勝てたらご褒美だぞ～", 2, 8249, 1, 102, 8, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑すぎてムダに\n早起きしちった～\n二度寝すっか～\n…ふぁあ…", 2, 8250, 1, 1, 1, 131101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏バテしても\nスイカとかかき氷なら\n全然ウェルカム\nなんだよなー", 2, 8251, 1, 2, 1, 131101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はこのまま\n水着で寝るかー\n夢ん中で泳ごー", 2, 8252, 1, 3, 1, 131101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いったんキューケイ…\nンー…よし\n充電カンリョ～♪", 3, 8254, 1, 2, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仲間になりたそうに\nこっち見てんねー\nきゃわいいしおっけ～", 3, 8255, 1, 3, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ン～いいニオーイ\nお日様あたった\n騎士きゅんの\n次くらいかな～", 3, 8256, 1, 4, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カラダ冷えてきたから\nたすかるーおかげで\nまだまだ水着イケるわ", 3, 8257, 1, 5, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うめ～\nとまんねぇ～\n夏バテどこいった～？", 3, 8259, 1, 7, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\nこれは意外と\nぬるっと読めるっぽー", 3, 8260, 1, 8, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ンフフ～\n海の戦士ってカンジ？\nアリよりのアリだね～", 3, 8262, 1, 10, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あーやべ\n一瞬で寝そー\nヤバだわ～", 3, 8263, 1, 11, 1, 131101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("服や紙が易々と\n燃えぬとは\nランドソルとはまこと\n住み易き国で候", 1, 8264, 1, 1, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どの世界にあっても\n民は活力に溢れ\n街は賑わうもの…\n善哉、善哉", 1, 8265, 1, 2, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べ歩きに世界征服…\nギルドとはかくも\n自由気儘な徒党に\nありんすなぁ", 1, 8266, 1, 3, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("連絡は…今日もなし\n我が妹子は相変わらず\n放埓なことよ喃", 1, 8267, 1, 4, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("モネは相変わらず\n警戒しきりなれど…\nそのようなところも\n愛らしくあり申す", 1, 8268, 1, 5, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんと長閑な世にや\nありけむ…この平和は\n騎士殿たちの努力の\n賜物にありんす喃", 1, 8269, 1, 101, 4, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『王家の装備』は\n使わぬのかと？\n…フフ。すでに\n用いており申す", 1, 8270, 1, 102, 8, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今ばかりは媛という\n立場は置いて\nこの地の者らと\n歓談したく候", 2, 8271, 1, 1, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("強さの秘密？　…フフ\n女子の秘密を暴くのは\n野暮にござんす\nご寛恕いただきたく候", 2, 8272, 1, 2, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("此方の家屋、\n見目以上に\n堅牢であり申す\n何ぞ仕掛けがありや？", 2, 8273, 1, 3, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("心地よい時間とは\n疾く過ぎ去りゆくもの\n此処で過ごすと改めて\n実感できる喃", 2, 8274, 1, 4, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("視線が気になる？\nこれはすみませぬ\nなにぶん、お前さまは\n見ていて飽きませぬ故", 2, 8275, 1, 101, 4, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お前さまの前では\n誰もが心を開く…\nなんとまぁ罪作りな\n色男にありんすな？", 2, 8276, 1, 102, 8, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よく眠れましたかの？\n寝る子は良く育つ、と\n古くより申します由", 2, 8277, 1, 1, 1, 129701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美食殿の作法に倣い\n皆で共に昼餉を頂くと\n致しんしょう", 2, 8278, 1, 2, 1, 129701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("逢魔ヶ時は望まぬ客も\n参るもの…お前さまも\n気をつけなんし", 2, 8279, 1, 3, 1, 129701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっちの蛇に\n勝るとも劣らぬ\n座り心地で候", 3, 8281, 1, 2, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魂、万物に宿る\nとの云いあらば\n情愛を注いでやるのが\nよかろうの", 3, 8282, 1, 3, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いと香しき哉…\n騎士殿は香の道にも\n詳しくあられるか", 3, 8283, 1, 4, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ジオ・ゲヘナの\n灼熱と比ぶれば\nそよ風と変わり\nござんせん", 3, 8284, 1, 5, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美味なる哉…この味\nぺコリーヌ姫が好むも\n道理にありんす", 3, 8286, 1, 7, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("トーゴクに、オーマ…\n書で見るだけでも\n心惹かれる土地よの", 3, 8287, 1, 8, 1, 129701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑い日には\n冷たいものですよねー\nかき氷とか食べて\nすっきりしたいです★", 1, 8289, 1, 1, 1, 131201, 0, 0);
