INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("家事ニガテなのよね～\nコッコロたちには\n感謝しないとね", 1, 8373, 1, 4, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私も魔物料理に\n慣れてきちゃった…\n毒されてるわね…", 1, 8374, 1, 5, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつに仕掛ける\n次の悪戯は～…♪\nこれ…ううん…\nやっぱこっちかしら？", 1, 8375, 1, 101, 4, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("結局ギルドハウスが\n一番落ち着くわね\n…私たちの家だもの", 1, 8376, 1, 102, 8, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪戯のコツでも\n教えてあげよっか？\n…え～興味ないの？", 2, 8377, 1, 1, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これからもずーっと\n退屈しない毎日に\nしてあげる♪\n私の悪戯でね♪", 2, 8378, 1, 2, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょうど退屈してたの\nたーっぷりと\n構ってもらうわよ♪", 2, 8379, 1, 3, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("案内が必要なら\n頼ってくれていいわよ\n一応は私だって\nガイド妖精だし！", 2, 8380, 1, 4, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冒険のガイドなら\n私に任せなさい♪\nある意味忘れられない\n旅にしてあげる♪", 2, 8381, 1, 101, 4, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("妖精がいる家は\n栄えるのよ♪　だから\nずっといてあげる\nあんたのそばにね♪", 2, 8382, 1, 102, 8, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きゃははっ！\n寝ぐせついてるわよ？\nこのままにしましょ！\nだって面白いし！", 2, 8383, 1, 1, 1, 118601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自由に外へ行けるって\nすっごく幸せなことよ\nさ、散歩行きましょ♪", 2, 8384, 1, 2, 1, 118601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("安心していいわ\n寝てるあんたに\n悪戯しないから\n…あんたにはね♪", 2, 8385, 1, 3, 1, 118601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪くはないけど…\nあいつの頭の方が\n座り心地いいかも", 3, 8387, 1, 2, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子を使った\n悪戯は…\n…止めとこっと\nこんなにかわいいし♪", 3, 8388, 1, 3, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このギルドハウスに\nピッタリな匂いね♪\n一言で言えば…\nカオスって感じ？", 3, 8389, 1, 4, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんていうか…\n心があたたかいわ\n…変な感じ！", 3, 8390, 1, 5, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ガイド妖精にも\n食事の機能があって\nよかったのかも\nしれないわね…もぐ…", 3, 8392, 1, 7, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じれったい物語ね…\nこんなの霧を使えば\n一瞬で終わるのに！", 3, 8393, 1, 8, 1, 118601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わる～い子は\nトゥンヌス漁船に\n乗ってもらおうかな～", 1, 8395, 1, 1, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たまにはファミリーの\nみんなにもお休みを\nあげないとね～☆", 1, 8396, 1, 2, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海辺に素敵な\nバーがあるんだ～\n彼が大人になったら\n一緒に行きたいな♪", 1, 8397, 1, 3, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の風を肌で\n感じるの好きかも～\nラーゴはどう？", 1, 8398, 1, 4, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海岸線を\nのんびり散歩もいいね\n砂や貝殻に紛れた\nお宝探しの旅だよ～☆", 1, 8399, 1, 5, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなで集まって\nビーチパーティーでも\n開いちゃおっかな～♪", 1, 8400, 1, 101, 4, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さて、この水着…\n彼は気に入って\nくれてるかな～？", 1, 8401, 1, 102, 8, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("心ゆくまで夏を\n楽しんじゃお～☆\nほら君も♪", 2, 8402, 1, 1, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着似合ってるって？\nふふ♪　うれしいこと\n言ってくれるね～☆", 2, 8403, 1, 2, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("熱中症には\n気を付けないと\nだめだよ～？", 2, 8404, 1, 3, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の家ならうちの\nファミリーでやってる\nとこにしよっか☆\n豪遊しちゃお～♪", 2, 8405, 1, 4, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君と一緒なら\nどんな夏になるのか\n楽しみだね～♪", 2, 8406, 1, 101, 4, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君といると子供心を\nくすぐられちゃうな～\n大人だって思いっきり\n遊んでいいんだよね♪", 2, 8407, 1, 102, 8, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さ、今日は何をして\n過ごそっかな～…\nねえ、君は何したい？", 2, 8408, 1, 1, 1, 131801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ♪\n波音が心地良い\n時間だね～☆", 2, 8409, 1, 2, 1, 131801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今夜は星空の下で\n乾杯しよっか～☆\n飲み物取ってくるね♪", 2, 8410, 1, 3, 1, 131801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここ涼しい～♪\nちょっと一休み\nしていこっか☆", 3, 8412, 1, 2, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうのも良いけど\nやっぱりラーゴの方が\nかわいいかな～♪", 3, 8413, 1, 3, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("爽やかな香りだね～\nこういう感覚も絵で\n表現してみたいな～", 3, 8414, 1, 4, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("続きを描く前に\n原稿を乾かさないとね\nインクがにじむと\n直すの大変なんだよ～", 3, 8415, 1, 5, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は水着だし…\n食べるのは控えめに\nしておこっかな", 3, 8417, 1, 7, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("話題の作品は\nチェックしないとね～\nあっ、この作家さん\n新刊出すんだ～", 3, 8418, 1, 8, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちの出店の客引きに\nこういう乗り物系を\n使うのもアリかな～☆", 3, 8420, 1, 10, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ、背景用の\n参考資料に\n一つ欲しいかも♪", 3, 8421, 1, 11, 1, 131801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここに帰るのも\n久しぶり…あれから\n変わったところは\nあるかしら？", 1, 8422, 1, 1, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("バイトも復帰しなきゃ\nうちのギルドにとって\n食費は重要だもの…！", 1, 8423, 1, 2, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コッコロマ…っ\n…うぅ…\nこの癖は\n直らないのね…", 1, 8424, 1, 3, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この世界はまだまだ\n知らないことだらけね\n『裏世界』とか…", 1, 8425, 1, 4, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("必ずみんなを\n助け出してみせるわ\n…もちろん、兄さんも", 1, 8426, 1, 5, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("またみんなと\n暮らせるなんて…\n夢じゃ、ないのよね", 1, 8427, 1, 101, 4, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たくさんの人が\n私に優しくしてくれる\n…だからこそ、私も\n頼れる人になりたいわ", 1, 8428, 1, 102, 8, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はランドソルの\n街の外にも行きたいわ\nあの…よかったらまた\n一緒に回ってくれる？", 2, 8429, 1, 1, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("独りぼっちで眠るのは\nやっぱり寂しかったわ\n…みんなで雑魚寝？\nそんなの…絶対やるわ", 2, 8430, 1, 2, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ネビアってば大泣きで\n私を出迎えてくれたの\n…すごく嬉しかったわ", 2, 8431, 1, 3, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この翼、陽に当たると\n本当に綺麗よね…\n自分のだけれど、つい\nずっと見ちゃうもの", 2, 8432, 1, 4, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにーたんっ♪\n…呼びたくなっただけ\n本当にそれだけよっ？", 2, 8433, 1, 101, 4, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしたの？\n…ふふっ、安心して\nこれからもずっと\n私はここにいるわ", 2, 8434, 1, 102, 8, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんな起きだす時間ね\n街が活気づいてく感じ\n嫌いじゃないわ", 2, 8435, 1, 1, 1, 181201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("【美食殿】のお昼は\nいつも美味しいから\nまた太っちゃいそうね", 2, 8436, 1, 2, 1, 181201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おやすみなさい\n明日も、その先も\n一緒に冒険しましょう", 2, 8437, 1, 3, 1, 181201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休憩も大事…よね\nじゃあ遠慮なく…\nふぅ～…♪", 3, 8439, 1, 2, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…ふわふわ…♪\nこのかわいさには\nもう抗えないわ…", 3, 8440, 1, 3, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("落ち着く香り…\nこの匂いを嗅いでると\n帰ってきたなって\n思うわね", 3, 8441, 1, 4, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなで野宿した時も\n焚火の明かりを見て\nすごく安心したのよね", 3, 8442, 1, 5, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ペコリーヌさんには\n負けるけど…\n美味しくって手が\n止まらないわ…！", 3, 8444, 1, 7, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プリンセスフォーム…\n一体どういう仕組みで\n発動するのか、文献に\n書いてないかしら…", 3, 8445, 1, 8, 1, 181201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すごーく暑いけど、\nこの暑さをどうやって\n乗り越えるかって\n考えるのも楽しいかも", 1, 8447, 1, 1, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("氷で彫刻を作るの？\nそれは楽しそうだけど\nすぐに溶けちゃわ\nないかしら？", 1, 8448, 1, 2, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お日様の下で遊ぶのも\n部屋の中で涼むのも\nどっちも夏ならではの\n楽しみ方なのね", 1, 8449, 1, 3, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("生き物の観察日記、\n私も書いてみたいな\nパックのお昼寝日記\nなんてどうかしら？", 1, 8450, 1, 4, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さまぁばけぇしょんは\n計画を立てるもの\nなんだって\n私も挑戦してみるわね", 1, 8451, 1, 5, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この世界のことを\nもっと知って\nアーラム村のみんなに\nお話ししてあげるの", 1, 8452, 1, 101, 4, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつルグニカに帰るか\nわからないからこそ\n毎日頑張らなきゃね", 1, 8453, 1, 102, 8, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はどこに行くの？\n私は、えーと…\nかき氷が食べたいわ！", 2, 8454, 1, 1, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにも精霊が\n住んでたりするの？\n…精霊じゃなくて\nがいど妖精？", 2, 8455, 1, 2, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パックったら、\n近所の子にいっぱい\nなでなでされてたわ\nすごーく人気者ね！", 2, 8456, 1, 3, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("実は…線香花火の\n特訓をしてたの！\n次は負けないんだから", 2, 8457, 1, 4, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昨日、みんなの\n似顔絵も絵日記に\n描いてみたんだけど…\n笑っちゃダメよ？", 2, 8458, 1, 101, 4, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何気ない時間だって\n後で思い返せば\nずっと忘れない\n素敵な思い出になるの", 2, 8459, 1, 102, 8, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちよく起きて、\nいい一日を過ごしたい\nそんなときには\nラジーオタイソーね！", 2, 8460, 1, 1, 1, 131901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ごはんの時間ね\n暑さに負けないように\nしっかり食べましょう", 2, 8461, 1, 2, 1, 131901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外は涼しいみたいだし\n夜の散歩に行ってみる\nのはどうかしら？", 2, 8462, 1, 3, 1, 131901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("遊び疲れたら\nここでひとやすみ…\nふわぁ…\n眠くなっちゃった…", 3, 8464, 1, 2, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("細かいところまで\nすごーく丁寧に\n作られてる…", 3, 8465, 1, 3, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ、なんだか\nすーっとする香りね\nちょっぴり涼しく\nなったみたい", 3, 8466, 1, 4, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海で遊ぶと\n体が冷えるから\nあったかいのも\nすごーく嬉しい…", 3, 8467, 1, 5, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これも美味しい…！\nペコリーヌが\nどんどん食べちゃう\n気持ちが分かるかも", 3, 8469, 1, 7, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このお話も面白い…！\nあっという間に時間が\n過ぎちゃったわ…\n…ね、寝てません！", 3, 8470, 1, 8, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子と一緒に海に\nいったら楽しそうね！\nどこに行けば\n会えるのかしら？", 3, 8472, 1, 10, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふかね！\nこうしてると波の音が\n聞こえてきそう…", 3, 8473, 1, 11, 1, 131901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こちらでは水着姿で\n過ごすのも\n珍しくないようですね", 1, 8474, 1, 1, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メイド服ではなく\n姉様と色違いの水着…\nレムは嬉しいです", 1, 8475, 1, 2, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し室温が高いかも\nしれませんね…\nいくつか氷を配置して\nおきましょうか", 1, 8476, 1, 3, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("清涼感があるとはいえ\n鉄球をビーチバレーの\nボールに代用するのは\n危ないでしょうか…", 1, 8477, 1, 4, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅー…ふぅー…\nようやく浮輪が\n膨らみました\n姉様にお渡ししないと", 1, 8478, 1, 5, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海のことをもっと\n教えていただけますか\n…スバルくんと海の\n話をしたいんです", 1, 8479, 1, 101, 4, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もし海に行く機会が\nあればレムにも…\nお声がけくださいね\nぜひ、お願いします", 1, 8480, 1, 102, 8, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何を着ていても\nメイドはメイド\n掃除も料理も\nなんでもござれです", 2, 8481, 1, 1, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スバルくんとあなたは\n兄弟のように\n仲がいいですね\n姉様とレムと一緒です", 2, 8482, 1, 2, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この姿で子どもたちと\n遊ぶのは…さすがに\nはばかられますね\nやはり着替えてきます", 2, 8483, 1, 3, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ナンパ…というものが\n海にはあるそうです\nスバルくんがとても\n警戒していました", 2, 8484, 1, 4, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魚釣りでしたら\nレムもご一緒します\n氷漬けの魚の備蓄を\n補充したかったので", 2, 8485, 1, 101, 4, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("子どもたちと砂遊びの\n約束をしているんです\nあなたもご一緒に\nいかがですか？", 2, 8486, 1, 102, 8, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ラジーオタイソーは\nもうされましたか？\n体がほぐれますよ", 2, 8487, 1, 1, 1, 132101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ですね。では\n姉様に焼きそばを…\nもちろん皆様の分も\n用意してありますよ", 2, 8488, 1, 2, 1, 132101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("熱帯夜であっても\nお休みの際はお腹を\n冷やさないように\n気をつけてくださいね", 2, 8489, 1, 3, 1, 132101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とても気持ちよさそう\nです…！\nさっそく姉様に\nお教えしないと", 3, 8491, 1, 2, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("季節に合わせた\n着せ替えができれば\n子どもたちも\n楽しめそうです", 3, 8492, 1, 3, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…この香りは\n疲れを癒やしてくれ\nますね。エミリア様に\nお持ちします", 3, 8493, 1, 4, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身も心もほぐれます\n思っていたよりも\n体が冷えていたみたい\nですね…ふう…", 3, 8494, 1, 5, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…んうっ！？\nこのすっぱさは…\n梅干し、ですか…\nくせになりますね…！", 3, 8496, 1, 7, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に関する詩文なども\nあるのでしょうか…\n気になります", 3, 8497, 1, 8, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("地竜とは違った\n乗り心地です…\n本物にも乗ってみたい\nものですね", 3, 8499, 1, 10, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この大きさで\n本物の貝であれば…\nどんな料理にするか\n想像が膨らみます", 3, 8500, 1, 11, 1, 132101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これがこの世界の\n居住環境か…\n面白い構造だね", 1, 8501, 1, 1, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇を持て余していてね\n誰か話し相手に\nなってくれないかな", 1, 8502, 1, 2, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("目新しいものが\nたくさんあるね\n胸が躍るよ", 1, 8503, 1, 3, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("頑丈そうな建物だ\nここなら彼女たちが\n暴れても大丈夫かな？", 1, 8504, 1, 4, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("力が制限されていて\n良かった面もある\n君も吐かずにすんだし", 1, 8505, 1, 5, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪さなんてするわけ\nないじゃないか\n傷つくなぁ", 1, 8506, 1, 101, 4, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("普段と違う格好で\n歩き回るのも\n悪くない経験だ", 1, 8507, 1, 102, 8, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクに聞きたいことが\nあるなら遠慮なく\n質問するといい", 2, 8508, 1, 1, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気軽に魔女に\n話しかけるなんて\n君は物好きだね", 2, 8509, 1, 2, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この世界においては\nボクは異物だからね\n大人しくしているさ", 2, 8510, 1, 3, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクの反応を\n見たいのかい？\n君の好奇心には\n恐れ入るよ", 2, 8511, 1, 4, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクの手を借りたい？\nもちろん構わないさ\n対価はいただくけどね", 2, 8512, 1, 101, 4, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボクと海を見たい？\nふふ、魅力的な\nお誘いだね", 2, 8513, 1, 102, 8, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お目覚めかな？\nさて、君の見た夢を\n教えてくれないかな？", 2, 8514, 1, 1, 1, 132001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食後のお茶を\n一緒にどうだろうか？\nさあ、席に座ってよ", 2, 8515, 1, 2, 1, 132001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おや、お休みかな？\n魔女の前で無防備だね\n…無論、何もしないさ", 2, 8516, 1, 3, 1, 132001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういう椅子は\n茶会には向かないね\nつい気が緩んでしまう", 3, 8518, 1, 2, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうものを好きな\n女の子がいいのかな？\n君の嗜好を知りたいな", 3, 8519, 1, 3, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りだ\nこれにはどんな\n効能があるんだろう？", 3, 8520, 1, 4, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("火の点け方に\nボクのいた世界との\n違いはないのかな？", 3, 8521, 1, 5, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これもまた未知の味だ\n存分に味わわせて\nもらうとしよう", 3, 8523, 1, 7, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素晴らしいね\nここには叡智が\n詰まっている", 3, 8524, 1, 8, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔物を模倣した\nぬいぐるみか…\n実物を見たくなるね", 3, 8526, 1, 10, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい気持ちだ…ボクと\nしたことが、何も考え\nられなくなりそうだ", 3, 8527, 1, 11, 1, 132001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("願わずにいられません\nどうかこちらの\n世界には…悲劇が\n生まれませんようにと", 1, 8528, 1, 103, 12, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食事のご希望があれば\nなんなりと。お腹が\nいっぱいになるまで\n沢山ご用意しますね", 2, 8529, 1, 103, 12, 109701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの男、これからも\n観察が必要ね\nラムの目の届く範囲に\n置く必要があるわ", 1, 8530, 1, 103, 12, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素直なところは\nあの男の美点ね\n癪だけど、偶然にも\nラムと同じだわ", 2, 8531, 1, 103, 12, 109801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("迷惑かけちゃったけど\n雪遊びは楽しかったわ\nまたやりたい…なんて\n言ったら怒られるかも", 1, 8532, 1, 103, 12, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("数えきれないくらいの\n思い出を、みんなで\n作りましょう！", 2, 8533, 1, 103, 12, 109901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わわっ、今すごく\nいい香りがしたけど…\n誰の香水かな\n教えてほしいな…♪", 1, 8534, 1, 1, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("錬金術用の釜、\n置くならどこかな？\n自分専用の錬金釜、\n憧れちゃうよね♪", 1, 8535, 1, 2, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この匂い…誰か\n唐揚げ食べたみたい\nうぅ…お腹空いて\nきちゃうよ", 1, 8536, 1, 3, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次の新曲のタイトルは\n『恋の錬金術』！\nうーん、ちょっと\nベタ過ぎるかな…", 1, 8537, 1, 4, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、錬金の素材\n切らしてたんだ…\n彼を誘って採集に\n行ってこようかな", 1, 8538, 1, 5, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("瞬時に着替えができる\n薬とかできないかな？\n舞台で衣装チェンジ！\nなーんて、楽しそう♪", 1, 8539, 1, 101, 4, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("彼が遊びに来た後は\n部屋の空気がほんのり\n彼の匂いなんだ…\nなんだか幸せだな♪", 1, 8540, 1, 102, 8, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もバイト？\nそれならこれ飲んで\n私のお手製ポーション\nがんばってきてね！", 2, 8541, 1, 1, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しくできたカレー屋\n行ってみない？\n時々スパイスの香りが\n流れてくるんだよ", 2, 8542, 1, 2, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私のフィギュア\nそっくりでしょ！\nルイちゃんが作って\nくれたんだ", 2, 8543, 1, 3, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あれ、シャンプー\n変えた？　私と同じの\nだよ！　どうしよう\nドキドキしちゃう…", 2, 8544, 1, 4, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いらっしゃいませ♪\n何を作りますか？\nなーんてね。錬金堂で\nまた一日店長したいな", 2, 8545, 1, 101, 4, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クンクン…彼の\nハンカチ…いい匂い♪\n私だけの秘密のお守り\nにしてるんだ", 2, 8546, 1, 102, 8, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえねえ、天気も\nいいし一緒に錬金の\n素材集めに行こうよ！", 2, 8547, 1, 1, 1, 132201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯、用意したよ\nあはは、さすがに\nランチは錬成しないよ\n私の手作りだよ♪", 2, 8548, 1, 2, 1, 132201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も一日お疲れさま\nこれ飲んでゆっくり\n休んで。薬じゃないよ\nホットミルクだよ？", 2, 8549, 1, 3, 1, 132201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昨日、遅くまで\n錬金術の勉強してた\nから眠くって…\nちょっと一休みっと", 3, 8551, 1, 2, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子にちょっとだけ\n香水かけて、と…\nんー！　だっこした時\nすっごくいい匂い♪", 3, 8552, 1, 3, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("花みたいな、\nお菓子みたいな\nいい香り。気持ちが\n穏やかになるね♪", 3, 8553, 1, 4, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外でもこの暖かさを\n感じられる道具、\n作れたりしないかな？", 3, 8554, 1, 5, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素材集めに行くと\nお腹が空くんだよね\nイロハちゃんも\nこの味好きそう", 3, 8556, 1, 7, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("錬金術にはたくさんの\n知識が必要だからね\nさあ、今日も調合書を\n読まなくちゃ", 3, 8557, 1, 8, 1, 132201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここが騎士さんたちの\n住んでる場所…！\n粗相がないように\n気をつけなきゃ", 1, 8559, 1, 1, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ジオ・テオゴニアの\nみんな、私がいない間\nちゃんとお仕事\nしてればいいけど…", 1, 8560, 1, 2, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コッコロさんも\n従者として長いって\n聞いたような…\nあの年ですごい…！", 1, 8561, 1, 3, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自分がもてなされる\n側になるのって\nやっぱりちょっと\n落ち着かないかも…", 1, 8562, 1, 4, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度のお休みの日は\n何しよう…？\nあっ、最近できたお店\nヴルムと行こうかな？", 1, 8563, 1, 5, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お買い物したら\nかわいいからって\nたくさんおまけして\nもらっちゃった…♪", 1, 8564, 1, 101, 4, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいると、つい\nぼんやりしちゃう…\nこれも騎士さんの力…\nなのかな", 1, 8565, 1, 102, 8, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お手伝いできることは\nありませんか？\nお世話でもなんでも\n任せてくださいっ", 2, 8566, 1, 1, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルに初めて\n来たときは驚きました\n砂糖の山と思ったら…\nあんなに寒いなんて！", 2, 8567, 1, 2, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの、ヴルムを\n見ませんでしたか？\nもう…あの子ってば\nまた仕事をサボって…", 2, 8568, 1, 3, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("家具や家が壊れても\n食べられないなんて\nなんだかもったいない\nですね", 2, 8569, 1, 4, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("とっておきの紅茶を\n手に入れたんです\n一杯いかがですか？\nその、日頃のお礼です", 2, 8570, 1, 101, 4, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("頑張ってて偉いって…\nほ、褒めてもなんにも\n出ませんからね！？\n…えへへ♪", 2, 8571, 1, 102, 8, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます！\nモーニングティーは\nいかがですか？\n私、準備しますねっ", 2, 8572, 1, 1, 1, 127701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ライラエルさまも\nお昼寝はお好きです\nけど…だからって\n寝すぎはダメですよ！", 2, 8573, 1, 2, 1, 127701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おやすみなさい\nくれぐれも寝不足には\n気をつけてくださいね", 2, 8574, 1, 3, 1, 127701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しっかりしないと…\nメイドの私が\n気を抜くなんて…\nそんな…ふぅ…", 3, 8576, 1, 2, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わぁ、かわいい…♪\nってダメダメ！\nメイドなんだから\n落ち着かないと…！", 3, 8577, 1, 3, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい匂い…♪\nこの香り、\nライラエルさまも\n好きそうです！", 3, 8578, 1, 4, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルの環境に\n触れると、この光の\nありがたみが\n身に沁みますね…", 3, 8579, 1, 5, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("甘くない食べ物が\n一般的なのも\n慣れてきました\nあむ…おいひぃ…♪", 3, 8581, 1, 7, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルの文字、\n私たちのところと\nちょっと違いますね…\n覚えられるかなぁ", 3, 8582, 1, 8, 1, 127701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("甘い匂いがしない…\nジオ・テオゴニアとは\n別の世界なんですね", 1, 8584, 1, 1, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("掃除めんど…\nん…このくらいで\nまー十分でしょ", 1, 8585, 1, 2, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ食事の\n用意もしなきゃ…\nあーやる事多い…", 1, 8586, 1, 3, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("秘密の隠れ場所、\nまた姉さんにバレた…\n次のを探さないと", 1, 8587, 1, 4, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("知らない間に仕事が\n終わったり…しないか\nしてくれたらいいのに", 1, 8588, 1, 5, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きちんともてなすには\n騎士さんの好みも\n覚えてかないと…", 1, 8589, 1, 101, 4, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ご主人サマに\nご奉仕します～♪\n…キャラじゃないか\nやめやめ、恥ずかし…", 1, 8590, 1, 102, 8, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("居心地いいっすね…\n今日からここに\n住んでもいいですか", 2, 8591, 1, 1, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの、ちょっと姉さん\n怒らせちゃったんで\n匿ってくれません？", 2, 8592, 1, 2, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("羽と尻尾が格好いい？\n意外と邪魔ですよ\n仰向けで寝にくいし", 2, 8593, 1, 3, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワークライフバランス\nっていい言葉ですね\nぜひライフ多めで", 2, 8594, 1, 4, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんって\n働き者ですね\nそのままあたしの\n仕事も…いえなんでも", 2, 8595, 1, 101, 4, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("熱心に見てても\n尻尾は触らせて\nあげませんってば\n角？　角なら…まぁ", 2, 8596, 1, 102, 8, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寝ても寝ても\n寝足りない…ふぁ…\nあー…眠たい…", 2, 8597, 1, 1, 1, 127801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アフタヌーンティーの\n準備は得意ですよ\nつまみ食いとか\n…つまみ食いとか", 2, 8598, 1, 2, 1, 127801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よく休んでください\n布団は干しといたんで\n…姉さんが", 2, 8599, 1, 3, 1, 127801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふー…\nこのままずーっと\nここに居たい…", 3, 8601, 1, 2, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたも一緒に\nサボっちゃうか～\n…なんて", 3, 8602, 1, 3, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("落ち着く匂い…\n騎士さんの好み\nなんですかね", 3, 8603, 1, 4, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうとこの\n掃除って面倒だし…\n今度でいっか", 3, 8604, 1, 5, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ご飯の前に\nこんな食べたら\n姉さんきっと怒るな…", 3, 8606, 1, 7, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食に関する本が\nやけに多い…\nお国柄ですかね", 3, 8607, 1, 8, 1, 127801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すんすん…\nお兄さんの匂いが\nぷんぷんする～♡\nザコくっさぁ♡", 1, 8609, 1, 1, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぴこーん！\nいひひっ、新作メカの\n面白いアイデア、\n思いついちった～♡", 1, 8610, 1, 2, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メカもいじりたいし\n服もアクセもほしー…\nあ～、おこづかい\n足んないよ～！", 1, 8611, 1, 3, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お勉強でもしよっかな\nザコお兄さんには\n絶対わかんない\nよーなやつ♡", 1, 8612, 1, 4, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんの部屋って\nどこどこぉ？\nメカの実験室に\n使えそうだよね～♡", 1, 8613, 1, 5, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次のデートコースは\nどんなのかなー？\n…いや、むしろ次は\nぼくが決めちゃうっ？", 1, 8614, 1, 101, 4, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("強奪計画は念入りに♡\nお兄さんのハートも\n全力でザコザコにする\n計画、立てないとね♡", 1, 8615, 1, 102, 8, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねー、ヒマヒマヒマ～\nかまってかまってー♡\nどっか連れてけー♡", 2, 8616, 1, 1, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はこっちで\nご飯食べたいなー♡\n…帰っても５日連続の\nバカナ姉カレーだし…", 2, 8617, 1, 2, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("依頼行くならぼくも\n連れてってよー♡\nお兄さんのザコっぷり\n見ててあげる～♡", 2, 8618, 1, 3, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんはぼくより\nオトナだもんね～♡\nじゃあオモテナシ、\n期待してるから～♡", 2, 8619, 1, 4, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヤマ姉になんかお土産\n持って帰ろうかなー？\nザコお兄さん、選ぶの\n付きあって～♡", 2, 8620, 1, 101, 4, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("遊びにいくときは\nザコお兄さんも\n誘ってあげるよ♡\nどうせヒマでしょ～？", 2, 8621, 1, 102, 8, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁ～、ねむぅ～…\n夜更かしぶん寝るから\nあとで起こして～♡\nあ、変なこと禁止～♡", 2, 8622, 1, 1, 1, 130201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おなかすいたぁ～\nなんか食べ行こ♡\n甘いのおごって～♡", 2, 8623, 1, 2, 1, 130201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えー、もう寝る時間？\nじゃあ…添い寝して\nあげよっか？\nなーんて、ウッソー♡", 2, 8624, 1, 3, 1, 130201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おお～ふわっふわ～♪\nバンディシャーク号の\n座席に使いたーい！", 3, 8626, 1, 2, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カワイイ～♡\n改造したらもっと\nカワイくなるかな～？", 3, 8627, 1, 3, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん…いい匂い♡\nザコお兄さんって\nこーゆー香りが\n好きなのかなぁ～", 3, 8628, 1, 4, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はー、あったかーい♡\nバンディシャーク号\nにも欲しいかもー♪", 3, 8629, 1, 5, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べれるときに\n食べるのが大事って\nヤマ姉言ってたしね～", 3, 8631, 1, 7, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、この本読んだよ♡\n参考文献リストが\nしっかりしてて\n勉強になったなー♪", 3, 8632, 1, 8, 1, 130201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋は多少ゴチャつい\nてる方が落ち着くのさ\nバンディシャーク号\nみたいにね♪", 1, 8634, 1, 1, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("呆けてるのもいいが\nちいと物足りないねぇ\n麦しゅわもブドウ朱も\n無いなんてさ", 1, 8635, 1, 2, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この家セキュリティが\nなってないねぇ…\n盗賊目線でちょっくら\n指南でもしてやるか", 1, 8636, 1, 3, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("不思議だねぇ\nここで飲むと、酔いが\n回るのが早い気が\nするよ…ヒック", 1, 8637, 1, 4, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ…\nクルマが壊れた時は\nアジト代わりに\n使えそうだ♪", 1, 8638, 1, 5, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カカッ、いい部屋だ！\n妹を迎える準備は\nできてるみたいだねぇ", 1, 8639, 1, 101, 4, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…っと、油断したら\n落ち着いちまうね\nボーヤの甘っちょろい\n雰囲気のせいだよ", 1, 8640, 1, 102, 8, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さすがにこの家から\n盗みはしないさ\nいずれは妹たちの\n共有財産になるからね", 2, 8641, 1, 1, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボーヤ、暇なら\n博打でもやるかい？\nアタシが負けたら\n掃除でもしてやるよ", 2, 8642, 1, 2, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("立派な家じゃないか！\n一国一城の主とは\nちょっとボーヤのこと\n見くびってたかもねぇ", 2, 8643, 1, 3, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいい義弟のためだ\nアタシが盗ってきた\nお宝をくれてやるよ\n好きな場所に飾りな！", 2, 8644, 1, 4, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("妹と結ばれる前に\n他の女との関係は\n清算しとくように\nわかったね、ボーヤ？", 2, 8645, 1, 101, 4, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、ヤシオーリかい？\nフフン、義弟からの\nお酌とあっちゃあ\n断れないねぇ♪", 2, 8646, 1, 102, 8, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うう…清々しい朝だが\n頭がいてぇ…\nちっと昨日は\n飲みすぎたか…？", 2, 8647, 1, 1, 1, 130001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほらこれ、ワカナに\n作らせた弁当だ\nこれで昼からも\nバリバリやりな！", 2, 8648, 1, 2, 1, 130001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだまだ夜はこれから\n…と言いたいとこだが\n早寝して立派に育ちな\nそれが妹たちの為だよ", 2, 8649, 1, 3, 1, 130001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("中々いい座り心地だが\n盗賊が腑抜ける訳には\nいかないね…が…\nもう少しだけ座るか…", 3, 8651, 1, 2, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうのの中に\n実はレアなブツが\n隠されてるとか\nありがちだねぇ", 3, 8652, 1, 3, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふうん、ボーヤは\nこういう匂いが\n好きなのかい？\n妹たちに教えてやろう", 3, 8653, 1, 4, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体を温めんにゃ\n酵露をカッとやるのが\n一番だが、これも存外\n悪くないねぇ…♪", 3, 8654, 1, 5, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ガツガツ…\nん、悪くねェ味だ\nこれにヤシオーリでも\nありゃ文句はないね", 3, 8656, 1, 7, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本にも載ってない\nレアもんのお宝か…\nフッ、想像しただけで\n血沸き肉躍るねぇ…！", 3, 8657, 1, 8, 1, 130001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日の買い物は\nいつものお野菜と…\nあっ、確か特売が\nあったはず…！", 1, 8659, 1, 1, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お掃除、お掃除…♪\nきゅっきゅっ…\nよいしょ、っと…", 1, 8660, 1, 2, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("洗濯ものも\nたまらないうちに\nやっちゃわないと…", 1, 8661, 1, 3, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夕飯のメニュー…\n何にしよう？\n期限の早い食材は…", 1, 8662, 1, 4, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("色々お菓子も\n作ってみたいけど…\n予算…足りるかなぁ…", 1, 8663, 1, 5, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さん…どんな\n料理が好きなんだろ？\n前に作ったコロッケは\n評判よかったけど…", 1, 8664, 1, 101, 4, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんと\nおしゃべりすると、\n胸があたたかくなる…\nなんでだろ…？", 1, 8665, 1, 102, 8, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、騎士さん\nどうかしましたか？\n御用ならいつでも…♪", 2, 8666, 1, 1, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("削っても削っても\n家計簿は赤字…\n騎士さ～ん…\n助けてください～！", 2, 8667, 1, 2, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("手が空いてたら\n日用品の買い出し、\n手伝ってもらっても\nいいですか…？", 2, 8668, 1, 3, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっと一息つけそう…\nあっ、わたし\nお茶を淹れてきますね", 2, 8669, 1, 4, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("困りごとがあったら\n言ってくださいね\nわたし…騎士さんの\n力になりたいです", 2, 8670, 1, 101, 4, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("助けてもらった分は\n必ず返しますから…\nそれまでわたしのこと\n見ててくださいね…♪", 2, 8671, 1, 102, 8, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("忘れ物はないですか？\n今日のお仕事も\n頑張りましょうね…！", 2, 8672, 1, 1, 1, 130101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯できてますよ\n大したものじゃなくて\n恐縮ですけど…", 2, 8673, 1, 2, 1, 130101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜更かしはだめですよ\nわたしも家事を\n終わらせたら寝ないと", 2, 8674, 1, 3, 1, 130101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これ…割れ物防止の\nクッションに\n使えるかも…？", 3, 8676, 1, 2, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうのいいなぁ…\nけど…フブキちゃんに\n絶対改造されちゃう…", 3, 8677, 1, 3, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい匂い…でも\n切れかけてるかも？\nえっと補充するには…", 3, 8678, 1, 4, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかい…\nちょっとだけなら\n休んでも…いいよね", 3, 8679, 1, 5, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これがあったら\nもうお料理を\n作らなくて済むかも？", 3, 8681, 1, 7, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しい節約レシピは…\nあ、この草って\n食べられるんだ…", 3, 8682, 1, 8, 1, 130101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛溢れるランドソルの\nクリスマス…ですか\nいけませんね、つい\n胸が躍ってしまいます", 1, 8684, 1, 1, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ツリーの飾りと\nわたしの髪…\nくるくるしていて\n似ているかも…くすっ", 1, 8685, 1, 2, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この姿で傲慢な\nわたしになったら…\nいつもより怖がらせて\nしまうでしょうね…", 1, 8686, 1, 3, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪魔として、人を\nドキドキさせなくては\nい、イオから教わった\n…投げキスの練習を…", 1, 8687, 1, 4, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ジオ・テオゴニアの\nお菓子は、ツリーの\n飾りに向いていそう\nですね…ふふっ", 1, 8688, 1, 5, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士のギルドハウス…\nクリスマスの時期も\n暖かいのですね…", 1, 8689, 1, 101, 4, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("城の皆と過ごす宴も\n楽しいですが…\n騎士と二人の宴も\n幸せです…", 1, 8690, 1, 102, 8, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士、あなたの\nもてなしに感謝します\nクリスマスの何たるか\n教えてくださいね", 2, 8691, 1, 1, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この黒い羽は\nどう手入れすれば？\nイオなら知っている\nでしょうか…", 2, 8692, 1, 2, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("城の皆も連れてきたい\nほど、クリスマスは\n楽しい行事ですね\nお土産も迷います", 2, 8693, 1, 3, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスの晩餐に\n招待されたのですが…\nその…辛いものは\nありませんよね…？", 2, 8694, 1, 4, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスと言わず…\nいつでも星に祈って\nいますよ？　騎士達に\n幸せがあるように、と", 2, 8695, 1, 101, 4, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪魔として騎士を\nドキドキさせる…？\nそ、そのようなこと\nわたしには…うぅ…", 2, 8696, 1, 102, 8, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝は寒いですね…\n雪…積もっている\nでしょうか？", 2, 8697, 1, 1, 1, 132801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふあぁ…いけません\n公務の滞在先で\nお昼寝など…", 2, 8698, 1, 2, 1, 132801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜は悪魔として\n夢を見せましょう\n騎士はどんな夢が\n見たいですか？", 2, 8699, 1, 3, 1, 132801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…落ち着きます…\n家でゆっくりと過ごす\nクリスマスも\n良いものですね", 3, 8701, 1, 2, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リンドのプレゼントに\nぬいぐるみは…？\n…子ども扱いすると\n落ち込むでしょうか…", 3, 8702, 1, 3, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かいお部屋に\nこの香りを漂わせたら\nふふっ…素敵な時間を\n過ごせそうです", 3, 8703, 1, 4, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これがあれば、\n寒い冬も安心ですね\n暖かくて…このまま\n眠ってしまいそうです", 3, 8704, 1, 5, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪魔の力を使ったら\nお腹が空いてきて\nしまって…\n恥ずかしいです…", 3, 8706, 1, 7, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスには多くの\n伝承があるのですね…\n天使の伝承まで\nありましたし…", 3, 8707, 1, 8, 1, 132801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まぁ…！\nよくできていますね\nサプライズプレゼント\n…でしょうか。ふふ♪", 3, 8709, 1, 14, 1, 132803, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ど、どうでしょう…？\n親善交流の催しに\nなりそうでしょうか…", 3, 8710, 1, 15, 1, 132804, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギルドハウスって\nあったかぁ～い♪\n心がぽかぽかするの！", 1, 8711, 1, 1, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスの悪魔の\nお仕事はないわね！\nだってここのみんな\nいい子なんですもの♪", 1, 8712, 1, 2, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなちゃんと\n寝られてるかしら？\n夜更かしせずに、\nいい夢見てね♪", 1, 8713, 1, 3, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("毎回、来年が\n楽しみになるような\n素敵なクリスマスを\n過ごしたいわね♪", 1, 8714, 1, 4, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("訳ありケーキを見ると\n刑務作業を思い出すわ\n…あれも貴重な体験\nだったのかしら…？", 1, 8715, 1, 5, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ロマンチックな\nクリスマスに備えて\n今のうちに少女漫画で\n予習しておかないと！", 1, 8716, 1, 101, 4, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほっぺにチューなら\nもう一回しても…\nや、やっぱり無理！\n恥ずかしいわ～！", 1, 8717, 1, 102, 8, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("またみんなで\nセッションしたいわね\nカラーベルの練習した\n成果を見せたいの♪", 2, 8718, 1, 1, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("君はサンタさんに\nどんなプレゼントを\n頼んでいたのかしら？\n気になるわ～！", 2, 8719, 1, 2, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛が壊れても、\n何度でも治してあげる\n私たちの間に、\n愛の尽きる日はないわ", 2, 8720, 1, 3, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冬休みって短いようで\n長く感じちゃうわよね\n学校のみんなと\n早く会いたいな～♪", 2, 8721, 1, 4, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛をテーマにした\n冬休みの作文の宿題、\n君の分を読むのが\n今から楽しみね♪", 2, 8722, 1, 101, 4, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よかったらまた\n私をハニーって呼んで\nほしいの。ダーリン♪", 2, 8723, 1, 102, 8, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！\n冬の朝は冷えるから\n風邪を引かないように\n対策しましょうね", 2, 8724, 1, 1, 1, 132901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯は一緒に\n食べに行きましょう！\nクリスマス限定の\nランチコースよ♪", 2, 8725, 1, 2, 1, 132901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえねえ、キャンドル\nイルミネーションを\n見に行きましょうよ！\nロマンチックよ～♪", 2, 8726, 1, 3, 1, 132901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かいクリスマスを\n過ごすのに必須よね♪\nふふ、柔らかぁい！", 3, 8728, 1, 2, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どの子もかわいい～♪\nクリスマスツリーの\n下で、一緒にお祝い\nしてもらいたいな♪", 3, 8729, 1, 3, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだか胸の奥が\n温かくなる匂いね～\nリラックスしちゃう♪", 3, 8730, 1, 4, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかぁい♪\nあ、でも夜になったら\nサンタさんが入れる\nように、火を消すのよ", 3, 8731, 1, 5, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寒い冬だからこそ\nしっかり食べて\n備えておかなきゃ！", 3, 8733, 1, 7, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『聖夜の６時間』…？\n気になる小説だけど…\n勝手に読んじゃ悪い\nわよね…ガマンよ…！", 3, 8734, 1, 8, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きゃっ…！\nこんな不思議な本が\nあったのね～\nちょっと面白いかも♪", 3, 8736, 1, 14, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もふもふ、ふわふわで\nあったかくて\n気持ちいい～…♪", 3, 8737, 1, 15, 1, 132901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冬といえばサマー！\n…って言うけど夏は\n何をＰＲするんだろ\nメルクリゾート…", 1, 8738, 1, 1, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("奨学金の道は遠いな…\nあまりに遠すぎて\n最近忘れてたまである", 1, 8739, 1, 2, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暇だし鏡でも見よっと\nはー、今日も顔が良…\nげ、若干むくんでる？\nはー、今日終わった", 1, 8740, 1, 3, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着…お姉ちゃんと\n貸し借りするんだけど\nこれって少数派姉妹？", 1, 8741, 1, 4, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちゅむ、ツムギちゃん\n今日も可愛いねデュフ\n…なんで推し語りの声\nキモくなるんだろ私…", 1, 8742, 1, 5, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あれ…なんで私\n水着のまま部屋の中\nうろついてるんだっけ\n…こわ！　てか寒っ！", 1, 8743, 1, 101, 4, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩よく友達と海に\n行くって言ってたけど\n…え、誰とだろ？\nまあ誰でもいいけどさ", 1, 8744, 1, 102, 8, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("始まる…\nチエルの夏が始まる…\nあ冬でしたっけ？\nまどっちでもいいです", 2, 8745, 1, 1, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こないだトミヱ先輩\n壁に喧嘩売ってました\n相変わらず元気ですね", 2, 8746, 1, 2, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ユニ先輩にお芝居の\n出来を聞かれたんで\n可愛いって答えました\n嘘は言ってません", 2, 8747, 1, 3, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クロエ先輩の腹筋\nかっちょいーですよね\nさりげ触りたいけど\nあいつ隙ないんですよ", 2, 8748, 1, 4, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩もうカメラ係は\nやらないんです？\nチエルはやってますよ\n最高の被写体を常に", 2, 8749, 1, 101, 4, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メリゾでカップル割の\n企画あるらしいんです\nちなみに先輩は…\nあ、いえ、何でも…", 2, 8750, 1, 102, 8, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝ごはんは抜いても\n朝ちぇるだけは\n抜いちゃ駄目ですよ", 2, 8751, 1, 1, 1, 129501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼なに食べるか\n悩んでます？\nおごってくれるなら\nいい店教えますけど", 2, 8752, 1, 2, 1, 129501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この時間帯になると\nユニ先輩がごそごそ\n蠢きだすんですよね…", 2, 8753, 1, 3, 1, 129501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("世界の美少女が…\nこんな格好で\nくつろいでたら…\nまずい…事案になる", 3, 8755, 1, 2, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え、この子って\nウォータープルーフ？\nメリゾにも連れて\nいけちゃうカンジ？", 3, 8756, 1, 3, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～、いい香り…\nそういえばメリゾの\nスタッフルームも\n『贅』な匂いしてた…", 3, 8757, 1, 4, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("薄着で暖まるとか…\n冷静になっちゃ\n駄目なやつですよね\nこれ…", 3, 8758, 1, 5, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにぎり１個は\nちぇるに換算すると…\n２５ちぇるくらい？", 3, 8760, 1, 7, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あれー？　この辞書\nまだちぇるの項目\n載ってないんだ？", 3, 8761, 1, 8, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何これ…地味に楽しい\nあとたぶん\nクロエ先輩が好きそう", 3, 8763, 1, 10, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは良きですねー\n自宅でメリゾ気分とか\nユニ先輩もにっこり", 3, 8764, 1, 11, 1, 129501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここが騎士氏の\nお住まいですか\nふむ…地縛霊は\nいなさそうですね", 1, 8765, 1, 1, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここは土足厳禁では\nないみたいですね\nま、私には関係ないか\n足、透っけ透けなので", 1, 8766, 1, 2, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルの裏路地\nあそこは最高ですね\n暗くてじめじめしてて\n癒されるー", 1, 8767, 1, 3, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("っ！\n今ラップ音が…？\nまさか幽霊？\nやだ、怖い", 1, 8768, 1, 4, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("獣人族にエルフ族…\nなるほど騎士氏が\n幽霊程度では驚かない\n訳です…ちぇ", 1, 8769, 1, 5, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日の深夜\n騎士氏が起きるまで\n枕元でずーっと\n立っててみようかな", 1, 8770, 1, 101, 4, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士氏の驚く顔を\n見ると胸が高鳴る…\n変ですね、心臓なんて\n動いてないのに", 1, 8771, 1, 102, 8, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("安心して下さい\n勝手にすり抜けて\n騎士氏の部屋は\n覗きませんよ…多分", 2, 8772, 1, 1, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんですか騎士氏\n怖い話でも聞きます？\nじゃあいきますね…\n今貴方の前に幽霊がっ", 2, 8773, 1, 2, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この家…幽霊が\n寄ってくる間取りに\nなってますね\nまあ、嘘ですけど", 2, 8774, 1, 3, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("料理はしませんよ\n指きったら痛いので\nえ…透ければいい？\n……天才ですか？", 2, 8775, 1, 4, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お散歩ですか？\n深夜なら付き合います\nあ、やっぱり断ります\n幽霊出たら怖いので", 2, 8776, 1, 101, 4, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士氏の部屋のセンス\n好きですよ…もっと\nじめじめしていれば\nなおよし、ですが", 2, 8777, 1, 102, 8, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("レイスになってから\nあまり言わなくなった\n挨拶第一位はこちら…\nおはようございます", 2, 8778, 1, 1, 1, 133001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士氏。午後からも\n頑張って下さいね\n私は日陰で休みます\nでは、おつです", 2, 8779, 1, 2, 1, 133001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜も更けてきましたね\nここからがレイスの\n本領発揮…では早速\nう　ら　め　し　や～", 2, 8780, 1, 3, 1, 133001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("中々座り心地が\nよろしいですね\nブロッケンに跨る方が\n安心はしますが", 3, 8782, 1, 2, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("知ってますよ\nどうせ貴方も\n夜中になったら\n動き回るんでしょ？", 3, 8783, 1, 3, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すう…はあ…\nすごく落ち着く香り\n…落ち着き過ぎて\n成仏しそうでした", 3, 8784, 1, 4, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("温度は感じませんが\nなぜかほっこり\n温かい気持ちです\nなんででしょうね？", 3, 8785, 1, 5, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…\n食べ物は基本好きです\n消化の方法は…\n企業秘密で", 3, 8787, 1, 7, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("苦手なんですよね\nホラー小説\nだって幽霊とか\n怖いじゃないですか", 3, 8788, 1, 8, 1, 133001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この得も言われぬ\n高揚感…やはり\n正月はいいものだな！", 1, 8790, 1, 1, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("む、いかんな\n気付くと黒豆と\n栗きんとんばかり\n食べてしまう…", 1, 8791, 1, 2, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギルドの連中にも\nお年玉を渡してみるか\n少しは士気が上がる\nかもしれないな！", 1, 8792, 1, 3, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月くらいはのんびり\n羽を伸ばすとしよう\n適切な休暇も軍人の\n大事な責務だからな", 1, 8793, 1, 4, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月で浮かれすぎた\n者も多いはずだ\n念のため街を見回りに\n行くとしよう", 1, 8794, 1, 5, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("む、このおせち料理は\n絶品だな！\nあいつの分も\nとっておいてやろう", 1, 8795, 1, 101, 4, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年の抱負は…\nそうだな、あいつと\nさらに高みを目指す\nこれでいこう", 1, 8796, 1, 102, 8, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えっ、お年玉！\n…い、いや、私は\n子どもではないからな\nえ、遠慮させてもらう", 2, 8797, 1, 1, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("凧あげすごろく\nこま回し、たとえ遊び\nでも手は抜かんぞ\nさあ、勝負だ！", 2, 8798, 1, 2, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そのきな粉餅も\nうまそうだな…\n私のあんこと交換\nしないか？", 2, 8799, 1, 3, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴公、正月料理を\n食べ過ぎてないか？\nじ、実は私も少々、な", 2, 8800, 1, 4, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴公、お参りに行くぞ\n何？　外が寒いだと？\n仕方ない、手ぐらいは\nつないでやろう", 2, 8801, 1, 101, 4, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴公と新たな年を\n迎えられてうれしいぞ\n今年も一つ\nよろしくたのむ！", 2, 8802, 1, 102, 8, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("起きろ貴公。早朝なら\n参拝客も少ないはず\n今のうちにお参りを\n済ませよう", 2, 8803, 1, 1, 1, 133201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食に餅を焼いたぞ\nのどに詰まらせない\nようにゆっくり噛んで\n食べるんだ", 2, 8804, 1, 2, 1, 133201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜ふかしはあまり\n褒められたものでは\nないが…正月くらいは\n目をつむろう", 2, 8805, 1, 3, 1, 133201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これに座って飲む\n甘酒は格別だな", 3, 8807, 1, 2, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくの正月だし\nこいつにも着物を\n着せてやりたいな", 3, 8808, 1, 3, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは梅の香り…？\nふふ、なかなか\n風流ではないか", 3, 8809, 1, 4, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冬の寒さが堪えるな…\nここでしっかりと\n暖をとるとしよう", 3, 8810, 1, 5, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月はのんびり\nしたいからな、勝手に\n食事が出てくるのは\n本当に助かる", 3, 8812, 1, 7, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ、これが世界の\n新年のお祝いか\nなかなか興味深いな", 3, 8813, 1, 8, 1, 133201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一年の計は元旦にあり\n計画を立てて、\n有意義な一年を\n過ごしましょ", 1, 8815, 1, 1, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("年末年始はどうしても\n出費が増えちゃうし\nしばらくはきっちり\n節約しなきゃ…！", 1, 8816, 1, 2, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("タタミにフトン、\nトーゴク文化の内装…\nランドソルでももっと\n流行らないかしら", 1, 8817, 1, 3, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("子どもたちが凧を\n手作りして遊んでたの\n偉いわよね、みんな…", 1, 8818, 1, 4, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お年玉をあげる側に\nなって、分かる苦労…\n大人になるって\nこういうことかしら", 1, 8819, 1, 5, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一応実家にも\n顔を出さないと…\nよかったらだけど、\nあんたも来る？", 1, 8820, 1, 101, 4, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("毎日一緒にいて、\nささやかな幸せを\n同じように感じて…\nそれだけで十分ね", 1, 8821, 1, 102, 8, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("着物姿、もっと\nじっくり見たいの？\nさすがに照れるわよ、\nもう…", 2, 8822, 1, 1, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("整理整頓、できてる？\nもし散らかってるなら\nお正月休みのうちに\n片づけちゃいましょ", 2, 8823, 1, 2, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年もみんなが無事に\n過ごせますように…\nほら、一緒に\nお祈りしましょ", 2, 8824, 1, 3, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんな、あんたと\n遊ぶのが楽しみだって\n子どもに好かれる\nタイプなのよね", 2, 8825, 1, 4, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたの運勢は大吉！\nラッキーパーソンは\n金髪の幼なじみよ\n…なんてねっ", 2, 8826, 1, 101, 4, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("初夢は実現するのよね\nそれじゃ、あたしは\nあんたと…んんっ\nなんでもないわ", 2, 8827, 1, 102, 8, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外が寒いと、その分\n目も冴えるわよね\nこのまま朝の散歩に\n行こうかしら", 2, 8828, 1, 1, 1, 133501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月休みでも、\n食べてばっかじゃダメ\nしっかり動いて\n体を引き締めましょ", 2, 8829, 1, 2, 1, 133501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちゃんとあったかく\nして寝るのよ\nお正月から\n風邪ひかないようにね", 2, 8830, 1, 3, 1, 133501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("着物、しわに\nなっちゃいそう…\nでもそれ以上に、\n心地よくって…はぁ", 3, 8832, 1, 2, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("門松みたいに\nこの子も飾ってみる？\n運勢がよくなるかも♪", 3, 8833, 1, 3, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この匂い、もしかして\nトーゴクのお香？\nワビサビを感じるわ", 3, 8834, 1, 4, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ、あったかい…\n冷えた体に\n染み渡ってくるわ…", 3, 8835, 1, 5, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んっ、おいしい！\nおせちばっかじゃ\nやっぱり飽きちゃう\nものね…", 3, 8837, 1, 7, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("験担ぎとか縁起物とか\n調べてみると\nいろいろあって\n面白いのよね～", 3, 8838, 1, 8, 1, 133501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふーん、いい家ね\nアタシの巣に\nしちゃおうかしら？", 1, 8840, 1, 1, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃん…\n早く会いたいなぁ…", 1, 8841, 1, 2, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("メドゥシアナも\n気に入るかしら？\n今度連れてこよっと！", 1, 8842, 1, 3, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お邪魔してるだけ\nなのも悪いわよね…\nお返しはしないとね\n…ネズミ退治とか？", 1, 8843, 1, 4, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何か平和よね\nランドソルって…\nアタシ的にはもう少し\n荒っぽくてもいいわ", 1, 8844, 1, 5, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルも\n楽しい街よね…\n案内してくれる\nアイツのおかげ？", 1, 8845, 1, 101, 4, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アタシ、アイツに\n頼りすぎてるかも…？\nで、でも！　断らない\nアイツも問題だわ！", 1, 8846, 1, 102, 8, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇ、つまんなーい！\nもっとアタシを\n楽しませなさいよねー", 2, 8847, 1, 1, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この家悪くないけど…\nもっとムシムシ\nジメジメにできない？", 2, 8848, 1, 2, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何よ？\n用もないのに声掛けた\n…とか言ったら\n容赦しないわよ？", 2, 8849, 1, 3, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し部屋が寂しいわね\nそうだ、アンタを\n石にして家具に…\n冗談よ、ふふんっ♪", 2, 8850, 1, 4, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇ、もう少し\n話していかない？\nアンタの話なら…\n特別に聞いてあげるわ", 2, 8851, 1, 101, 4, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("い、いつも\nあ、あ、ありが…\nうぅ、何でもないー！", 2, 8852, 1, 102, 8, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっと起きたわね？\n寝ぼすけなんだから！\n尻尾でひっぱたいて\n起こそうかと思ったわ", 2, 8853, 1, 1, 1, 133601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人捜しは日の高い\nうちに限るわ！\nさぁ、メドゥシアナ！\n全速力で出発進行よ!", 2, 8854, 1, 2, 1, 133601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アタシ…\n子どもじゃないもん…\n眠くなんか…\nないんだからぁ…", 2, 8855, 1, 3, 1, 133601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわふわであったかい\nつい、とぐろを\n巻きたくなるわね…", 3, 8857, 1, 2, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アンタ、こんな\nヤワな体じゃ駄目よ\nウロコくらい\n生やしたらどうなの？", 3, 8858, 1, 3, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん…\n…ふん\n悪くないじゃない\n…くんくんくんくん…", 3, 8859, 1, 4, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかいの大好き！\nジオ・ゲヘナでも\nよく日向ぼっこ\nしたもんだわ…ふわぁ", 3, 8860, 1, 5, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんを捜すなら\n…もぐ\n体力つけないとね\n…もぐもぐ", 3, 8862, 1, 7, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何よ？　たまには\n勉強くらいするわよ\nお姉ちゃんに\n笑われちゃうもの", 3, 8863, 1, 8, 1, 133601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この装いと力…\n今の世界との\n整合性を上手いこと\n合わせておかないとだ", 1, 8865, 1, 1, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好…開発してた\n当時のまんまだ\nサイズもそのまま♪\n体型維持も完璧っ！", 1, 8866, 1, 2, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あとで装備の手入れも\nやっとかないと\n…剣なら研ぐだけで\n終わるんだけどなぁ", 1, 8867, 1, 3, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("自分の原点を\n振り返ってみるのも\nたまには必要だね", 1, 8868, 1, 4, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("完璧じゃなくても\n今できる全力を尽くす\nその事に意味がある…\nそうだよね、少年", 1, 8869, 1, 5, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("始まりのあの日、\nそして向かうべき道…\nいつも忘れずにいよう", 1, 8870, 1, 101, 4, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誰かを救うために\n許容される犠牲なんて\nあっちゃいけない…\n全部、助けてやる", 1, 8871, 1, 102, 8, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっと少年、\n何か御用かな？\nキミに関わる事なら\n最優先で対応するよ", 2, 8872, 1, 1, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("困った事があれば\n頼ってもらって\n構わないからね！\nむしろもっと頼って！", 2, 8873, 1, 2, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そうだ、時間あるなら\n武器のメンテを\n手伝ってくれないかな\n数が多くてさ～", 2, 8874, 1, 3, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("遠距離戦の心得、\n少年にもレクチャー\nしてあげよっか？", 2, 8875, 1, 4, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("無茶しないで、って\n言ってもするだろうし\nせめてアタシの手が\n届く範囲で頼むよ", 2, 8876, 1, 101, 4, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("虚実入り混じる\nこの世界でキミが…\n進むべきルートを\n照らしてくれたんだ", 2, 8877, 1, 102, 8, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("グッモーニン！\n朝だよ少年、今日も\n張り切っていこう！", 2, 8878, 1, 1, 1, 133701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クレープの代わりに\nガレットを焼いたんだ\nこの味で少年を\n唸らせてみせよう！", 2, 8879, 1, 2, 1, 133701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうこんな時間だ\n遅くならないうちに\n作業を切り上げようか\n少年も早く寝なよ？", 2, 8880, 1, 3, 1, 133701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あえて緊張を解くのも\n戦いには必要だし…\nそうそう…大事大事…", 3, 8882, 1, 2, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛着を抱かせる事を\n意図したデザインだね\n心理的効果の観点から\n分析してみようか…", 3, 8883, 1, 3, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("香りは記憶と密接に\n結びつく事がある…\n懐かしい匂いだね…", 3, 8884, 1, 4, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("癒されるな…\n何がこの感情変化を\n引き起こすんだろう？", 3, 8885, 1, 5, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食の偉大さを感じるな\n戦闘糧食ってやっぱり\n味気ないしなぁ…", 3, 8887, 1, 7, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("実用ばかりじゃなく\n詩や物語ってのも\n人には必要だよね", 3, 8888, 1, 8, 1, 133701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この場所の開発版も\n探せばあるかもな\nさて、どんなデザイン\nだったのやら…", 1, 8890, 1, 1, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今まで数々の波乱に\n身を投じたが…やはり\n波乱にはこの姿が一番\n似合いだよ☆", 1, 8891, 1, 2, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むっ…この角に羽と\n尻尾は家具とぶつかり\nやすいな。兎の時は\n気にならなかったが…", 1, 8892, 1, 3, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつもより闘争を\n求める気分になるな\n初心に帰るとは\nこのことか…？", 1, 8893, 1, 4, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("未調整上等☆\nそれを上手く使い\nこなしてこその\nワタシだろう？", 1, 8894, 1, 5, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("坊やとできそうな\n愉しいことは…\nふむ、多すぎて迷うな", 1, 8895, 1, 101, 4, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時折、坊やの居心地の\nよさに絆されそうに\nなってしまうな\nワタシらしくもない…", 1, 8896, 1, 102, 8, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうだ、おろした\n髪型も艶やかだろう？\nそんじょそこらの\n賞賛では満足せんぞ☆", 2, 8897, 1, 1, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外に出るぞ！\n共に退屈を殺しに\n行こうじゃないか☆", 2, 8898, 1, 2, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("角と翼も触りたい？\nワタシの虚数魔境に\n挑むというなら\n止めはせんよ☆", 2, 8899, 1, 3, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだ、困りごとか？\nクリスティーナさんが\n何でも聞いてやろう☆\n解決するかは別だがな", 2, 8900, 1, 4, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("力が欲しいか？\nならば呼ぶがいい！\nワタシの名を☆", 2, 8901, 1, 101, 4, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪魔との契約は絶対\nなのだそうだが…\nどうだ、坊や\n一つ契ってみるか？", 2, 8902, 1, 102, 8, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだ眠い？　甘えるな\n寝首を掻かれたく\nなければ飛び起きて\nこい…☆", 2, 8903, 1, 1, 1, 133901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食の準備を\nしてやろう。\n毒見はいらんぞ？\n安心するといい！", 2, 8904, 1, 2, 1, 133901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("坊やは寝る時間だ\n寝ないのならば…\n大人の時間に\n付き合ってもらうか☆", 2, 8905, 1, 3, 1, 133901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("角と翼、尻尾の\nコンディションまで\n完璧だな☆", 3, 8906, 1, 1, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なかなかのフワモコ\n具合だが…ううむ…\n翼と尻尾が邪魔だな", 3, 8907, 1, 2, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーむ、角と尻尾を\n追加して…さらに槍を\n持たせた方が見栄えが\nよさそうだ", 3, 8908, 1, 3, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りだな\n血と砂塵の臭いで\n上書きするまでの\n間に合わせに最適だ☆", 3, 8909, 1, 4, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("生温いな\nもっと焦がれるほどの\n熱量が欲しいところだ", 3, 8910, 1, 5, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("普段はないものが\n生えているのだから、\n運動でしっかり感覚を\n掴んでおかなければな", 3, 8911, 1, 6, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腹が減っては戦は…\nと言うからな\nしっかり食べて\nおくとしようか☆", 3, 8912, 1, 7, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『家庭を築くための\n絶対条件』…？\nふむ…興味がある\nタイトルだ", 3, 8913, 1, 8, 1, 133901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("奇妙な感覚です\nまるであの頃の自分に\n変装しているかのよう", 1, 8915, 1, 1, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("グレゴール？\nおっと、そうでした\n今は昔の姿になって\n離れていましたね", 1, 8916, 1, 2, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このアバターでいると\n妙に子どもたちからの\n視線を感じますね…", 1, 8917, 1, 3, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リソースの割り振りが\n変わっただけなのに\n随分と身体が軽く\n感じますね", 1, 8918, 1, 4, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("普段グレゴールに\n任せている分身の管理\n自分でやるには\nいささか煩雑ですね…", 1, 8919, 1, 5, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("長老に頼まれて描いた\n妖精の絵…いったい\n何に使ったのでしょう", 1, 8920, 1, 101, 4, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私自身をモデルにした\n完全なるNPCたち\nそれが私の分身です", 1, 8921, 1, 102, 8, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このアバターが\n気になるのですか？\n貴方はつくづく\n妖精に縁がありますね", 2, 8922, 1, 1, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょうどよかった\nグレゴールを見かけ\nませんでしたか？", 2, 8923, 1, 2, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの翅は飾りでは\nありません。ただ…\nグレゴールに乗って\n飛ぶ方が楽なだけです", 2, 8924, 1, 3, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("妖精とは本来神話に\nおけるトリックスター\n運命をかき回すことが\n存在意義なのです", 2, 8925, 1, 4, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変貌大妃の権能との\n相性を考えなければ\nこの姿こそが私たちの\n最強の姿です", 2, 8926, 1, 101, 4, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変化とは一種の喪失\nだからこそ得られる物\nがある…貴方のそれも\n大切にするのですよ", 2, 8927, 1, 102, 8, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マサキからの定時連絡\nが来ませんね…心配は\n不要ですが、様子を\n見に行きましょうか", 2, 8928, 1, 1, 1, 133801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食の時間ですね\nグレゴールのために\nカロリーの高い物を\n食べに行きましょう", 2, 8929, 1, 2, 1, 133801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜更かしはダメですよ\n悪いスパイが暗躍して\nいる時間帯ですからね", 2, 8930, 1, 3, 1, 133801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ、座り心地は中々\nですが…私にはやはり\n玉座の方があいますね", 3, 8932, 1, 2, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、いいでしょう\n我が配下に加えます\n存分に働きなさい", 3, 8933, 1, 3, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時折晶からしていた\nあの甘い匂いは何の\nアロマだったのか…", 3, 8934, 1, 4, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("燃え盛る炎もこうして\n暖炉の中なら安全です\nクリスもあの衝動を\n管理さえできれば…", 3, 8935, 1, 5, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そういえば真那が\n獄中で手持無沙汰に\nひたすらおにぎりを\n食べていましたね…", 3, 8937, 1, 7, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは、妖精学の本…\n長老の蔵書から借りて\n読みふけったものです", 3, 8938, 1, 8, 1, 133801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんな詩を\n作ろうかしら…？\n…大体、暗く\nなっちゃうけど…", 1, 8940, 1, 1, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("唱喚術の練習…\nここでやったら\n迷惑よね…", 1, 8941, 1, 2, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("チカちゃんとの\nデュエット…\n足をひっぱってない…\nかしら…？", 1, 8942, 1, 3, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("唱喚士の修行…\n滝に打たれるとか…\n崖を登るとか…\nなくて、よかった…", 1, 8943, 1, 4, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("精霊さん、肉じゃが\n食べる、かしら…？\n魔力だけだと…\n飽きちゃいそうだし…", 1, 8944, 1, 5, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("精霊さんのお世話に\n慣れたぶん…\nあのひとのお世話も\n上手にできる…はず？", 1, 8945, 1, 101, 4, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これからも、歌うわ…\nこの声が、彼の力に\nなる、限り──", 1, 8946, 1, 102, 8, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服…踊り子さんに\n間違われちゃって…\nあ…お、お触りしちゃ\nだめよ…？", 2, 8947, 1, 1, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたはどんな\n精霊が…好き…？\n唱喚…してみたいわ…", 2, 8948, 1, 2, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんまり白い服って…\n着ないの…その…\nこ、ころんだりして…\n汚すから…", 2, 8949, 1, 3, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じ、実はね…\nこの体の模様…筆で\n書いてもらうたび…\nくすぐったい…の…", 2, 8950, 1, 4, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("精霊さん…あなたと\n遊びたいみたい…\nや、やっぱり…\nパパ…だから…？", 2, 8951, 1, 101, 4, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたを歌にしたら…\n…ふふっ、だめね\n一曲じゃ…あなたを\n表現できない、わ…", 2, 8952, 1, 102, 8, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝の修行は…\nうとうと…し…ちゃ…\n……（かくん）\n……あぅっ？", 2, 8953, 1, 1, 1, 134301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せ、精霊さんと…\nかくれんぼ中なの…\nうぅ…見つからない…\n日が暮れちゃいそう…", 2, 8954, 1, 2, 1, 134301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("精霊さん、寝たから…\nふふっ…ここからは\nパパとふたりの時間…\n…ね？", 2, 8955, 1, 3, 1, 134301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…修行と育児は…\nちょっとだけ…\n休憩…ふぁ…", 3, 8957, 1, 2, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたとも契約…\n…できる、かしら？\nふふっ…", 3, 8958, 1, 3, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りに包まれたら\n精神統一も\nはかどりそう…♪", 3, 8959, 1, 4, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたたかい場所…\nここで作詞したら…\n穏やかな詩が\n書ける、かも…", 3, 8960, 1, 5, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("精霊さんのお世話を\nしていると…\nお腹、空いちゃって…", 3, 8962, 1, 7, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ…♪\n色んな楽譜…\n集めるの、楽しい…♪", 3, 8963, 1, 8, 1, 134301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("けんぞくまだかな？\nはやく会いたいなー\nヴァンピィちゃん\nずっと待ってるからね", 1, 8965, 1, 103, 12, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("けんぞくのこと\nずっとずっと守るよ！\nだからいつまでも\n一緒にいてね", 2, 8966, 1, 103, 12, 122301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の歌や想いを\n誰かに託せる…\nこれほどうれしい\nことはありません", 1, 8967, 1, 1, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コッコロさんの\n包容力はすごいです\nあんなふうに私も\n人を包み込めたら…", 1, 8968, 1, 2, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近のボイトレは\nランファさんと一緒に\nやるんです。お互いに\n切磋琢磨しますよ！", 1, 8969, 1, 3, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先輩として相応しい\n立ち振る舞いを\n心がけたいですね\nしっかりしなきゃ…！", 1, 8970, 1, 4, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランファさんが\n踊ったら映えるかも…\nアイドルにも興味を\n持ってもらえないかな", 1, 8971, 1, 5, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("支え導くために\n寄り添って考える…\nあの人からたくさん\n教わったことでしたね", 1, 8972, 1, 101, 4, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつだってあなたに\n恥じることのない\n姿をお見せしたいです", 1, 8973, 1, 102, 8, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの手は温かくて\n触れていると\n落ち着きますね…♪", 2, 8974, 1, 1, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("里のみんなから修行の\n差し入れを頂きました\nよろしければ、一緒に\n食べましょう♪", 2, 8975, 1, 2, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ノゾミにもお土産を\n用意したいですね\n里のお土産選び、\n付き合ってください♪", 2, 8976, 1, 3, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("精霊たちも、あなたが\n大好きみたいです♪\n優しさが伝わって\nいるんでしょうね", 2, 8977, 1, 4, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("特訓が終わったら、\n二人でどこかに\n出かけましょうか♪", 2, 8978, 1, 101, 4, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃ…す、すみません\n肌の模様を\nなぞられると、\nくすぐったくて…", 2, 8979, 1, 102, 8, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n精霊たちと一緒に、\n今日も頑張ります\n応援してくださいね♪", 2, 8980, 1, 1, 1, 134401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼の時間です\n今日も精いっぱい\n修行を頑張りましょう", 2, 8981, 1, 2, 1, 134401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうすっかり夜ですね\n眠るまで子守唄を\n歌ってあげますよ？\nふふ♪", 2, 8982, 1, 3, 1, 134401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("無理せず休憩するのも\n大切ですよね\nふかふか～…ふふっ♪", 3, 8983, 1, 2, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はこの子に\n歌の特訓を聞いて\nもらいましょう♪", 3, 8984, 1, 3, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵な香り…\nふふ、精霊たちも\n気に入ったみたいです", 3, 8985, 1, 4, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかい…\nこの衣装、やっぱり\n少し冷えやすいものね", 3, 8986, 1, 5, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("特訓の後のご飯は\n美味しいですね♪\nこれでまた頑張れます", 3, 8987, 1, 7, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("唱喚士についての\n書籍はないみたい\nいつか私がここに\n楽譜を入れたいな", 3, 8988, 1, 8, 1, 134401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギルドハウスの平和も\n任せてください\n何が来たって\n守ってみせますよ！", 1, 8992, 1, 1, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このギルドハウスも\nいつの間にか出撃台に\n改造されてたり\nするんでしょうか…？", 1, 8993, 1, 2, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦いを経験してこそ\n実感できますね\n平和はいいもの、\n友達は素晴らしいもの", 1, 8994, 1, 3, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はランドソルで\n巨大ロボットが\nブームになったり？\n…さすがにないか", 1, 8995, 1, 4, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("改めて見るとこの服…\nか、体の線とか\n結構目立ってるかも…", 1, 8996, 1, 5, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("団長さんって\n知らない人とも\n話せる系ですよね\nコツはいったい…", 1, 8997, 1, 101, 4, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ＢＢ団、世界を救う！\nまだ信じられないけど\n本当にあった出来事\nなんですよね…！", 1, 8998, 1, 102, 8, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パイロットも\n視力が大事なんです\n弓使いの経験が\n生きました！", 2, 8999, 1, 1, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ギガンティック\nマイフレンドくん、\n出撃！\nあ、ただの妄想です", 2, 9000, 1, 2, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コクピットから\n降りたあとに残る\nふわふわ感…ちょっと\n癖になりませんか？", 2, 9001, 1, 3, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひえっ、敵襲！？\nあっすみません、\nちょっと\n寝ぼけてたかも…", 2, 9002, 1, 4, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("共に戦場を駆け抜け\nＢＢ団の絆もより強く\nこれからも結束を\n強めましょうね！", 2, 9003, 1, 101, 4, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("同じコクピットに\n乗ったのに比べれば、\nスキンシップくらい…\nや、やっぱ緊張します", 2, 9004, 1, 102, 8, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます！\n今日もがんばりますっ\n…クローチェさんを\n見習ってみました…", 2, 9005, 1, 1, 1, 134601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯の時間ですね\nがんばって他の人\n誘ってみようかな…", 2, 9006, 1, 2, 1, 134601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜の見張りは\n任せてください\n一人きりの夜も\n慣れてますから！", 2, 9007, 1, 3, 1, 134601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休めるときに\n休んでおかなくちゃ\nいつ何が起こるか\n分かりませんからね", 3, 9009, 1, 2, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("師匠もこういうの\n好きだったのかな…\nなんだかしんみり\nしちゃいます", 3, 9010, 1, 3, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("香りでリラックス…\n余裕のない時でも\nこういう安らぎは\n大切ですよね", 3, 9011, 1, 4, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかい…\nこれはきっと友情と\n同じぬくもり…", 3, 9012, 1, 5, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新鮮なご飯、感動…！\n師匠たちの世界だと\nご飯は保存食ばかり\nでしたからね…", 3, 9014, 1, 7, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("操縦マニュアル、\nしっかり読んで\n性能を引き出さなきゃ", 3, 9015, 1, 8, 1, 134601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("屋内で飛べなくても\nここなら平気ですっ\n助けてくれる人が\nたくさんいますからっ", 1, 9017, 1, 1, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新ボディになってから\n人や物が前より身近に\n感じられて、わたし、\n幸せですっ♪", 1, 9018, 1, 2, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("配達以外にも何か\nお仕事したいですっ！\nハグで遊覧飛行とか、\n喜んでもらえますか？", 1, 9019, 1, 3, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むむむ～…\n文字を書くのって\n難しいですね～っ\n練習しなくちゃっ！", 1, 9020, 1, 4, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("簡易点検、よしっ！\nポポおじいさんに\n点検の仕方を教わって\n今日も絶好調ですっ", 1, 9021, 1, 5, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("明日は北の空、\n明後日は南の空っ♪\nえへへっ、見せたい\n景色がいっぱいですっ", 1, 9022, 1, 101, 4, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ついナイトさんを\n探しちゃいます…\nわたし、寂しんぼさん\nだったんでしょうかっ", 1, 9023, 1, 102, 8, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんなところでも\nひとっ飛びっ♪\nわたしに任せて\nくださいねっ！", 2, 9024, 1, 1, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだ知らない機能が\nエアリアルには\n隠されてるかもっ…\nワクワクしますねっ！", 2, 9025, 1, 2, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃんっ！　…あはは\nエアリアルになっても\nケーブルに触られると\nくすぐったいですねっ", 2, 9026, 1, 3, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヴォルガーノさんに\nそっくりの子猫さんに\n最近触れたんですっ！\nかわいかったな～っ♪", 2, 9027, 1, 4, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハグしてくれるん\nですかっ？\nえへへっ、ぎゅーっ♪", 2, 9028, 1, 101, 4, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ナイトさんと一緒に\nいるだけで、胸が\nぽかぽか～って\nあったかいですっ♪", 2, 9029, 1, 102, 8, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございますっ\n目覚まし飛行は\nいかがでしょうかっ？", 2, 9030, 1, 1, 1, 134501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ですよっ！\nいっぱい補給して\nまたフルパワーで\nがんばりましょうっ♪", 2, 9031, 1, 2, 1, 134501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眠れない夜はわたしに\n任せてくださいっ！\n充填さえあればずっと\n一緒にいられますよっ", 2, 9032, 1, 3, 1, 134501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歩きづらいので\nこういう休憩ポイント\nって助かります～っ", 3, 9034, 1, 2, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スラスターを付けたら\nこの子たちも空を\n自由に飛べたり\nするんでしょうかっ？", 3, 9035, 1, 3, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、これに似た\n香りを近くのお店で\n検知したことが\nありますっ♪", 3, 9036, 1, 4, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("高熱源反応を検知っ\nわたしのスラスターも\n熱量の高さなら\nかなりものですよっ♪", 3, 9037, 1, 5, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐもぐ…っ\n食べたぶんはあとで\n真空パックにして\nお返ししますねっ", 3, 9039, 1, 7, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本を読むのって\n楽しいですねっ♪\n前はびりびりーって\nしちゃってたのでっ", 3, 9040, 1, 8, 1, 134501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なかなかの住処ですね\nこの私の別邸にして\nあげてもいいですよ♪", 1, 9042, 1, 1, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…いつになったら\nすべての神力が\n戻るのでしょう？", 1, 9043, 1, 2, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここも悪くないですが\n昔私が作った庭園は、\nもっと良い場所でした\n焼けちゃいましたが…", 1, 9044, 1, 3, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うう…\nおなかが空きました…\nお米が食べたいです…", 1, 9045, 1, 4, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここは平和ですねえ…\nジオ・ゲヘナも\nこのくらい穏やかなら\n住みやすいのですが", 1, 9046, 1, 5, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんのおかげで\n神力が戻ってきました\n良い働きですよ♪", 1, 9047, 1, 101, 4, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんのいる場所が\n今の私がいるべき場所\nなのかもしれませんね", 1, 9048, 1, 102, 8, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("頭がたかーい！\n…ですよっ！", 2, 9049, 1, 1, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほーちゃんと呼ぶ権利\n安売りはしませんよ？\n特別ですから！", 2, 9050, 1, 2, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私とおしゃべりを？\nまあ、いいでしょう♪\n何を話しましょうか？\nこの羽の秘密とか？", 2, 9051, 1, 3, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("小鳥扱いは\nやめなさーい！\nこれでも神様ですよ？", 2, 9052, 1, 4, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("き、気安く触るのは…\n…い、いえ、\n騎士さんなら…まぁ…", 2, 9053, 1, 101, 4, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("絢爛豪華な絆！\nこの私と結べるなんて\n光栄でしょう？", 2, 9054, 1, 102, 8, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁぁ～\nおはようごじゃいます\n…んむむ", 2, 9055, 1, 1, 1, 134701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯は何を…\nえっ？　私？\nそそんな゛あ゛！", 2, 9056, 1, 2, 1, 134701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの…騎士さん？\n添い寝する権利とか…\nほしくないですか？", 2, 9057, 1, 3, 1, 134701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～ふかふか…\n…へ？\n鳥の巣にいるみたい？", 3, 9059, 1, 2, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ…\nそばに置いてあげても\nいいでしょう", 3, 9060, 1, 3, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほわぁ～\nいいかおり～", 3, 9061, 1, 4, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたたかい…\nなんだか元気が\nでてきますねっ", 3, 9062, 1, 5, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たくさん食べて力を\n取り戻さなくてはっ\n…んがぐぐっ", 3, 9064, 1, 7, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\n人の子にしては\nよく書けていますね♪", 3, 9065, 1, 8, 1, 134701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵なお家ですね\n温かみがあって\nどこか騎士様に\n似ております。ふふ", 1, 9067, 1, 1, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("賑やかな街ですね\nこれほど活気豊かだと\nつい外に出てみたく\nなってしまいます", 1, 9068, 1, 2, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("別世界の存在は知って\nおりましたが、いざ\n目の当たりにすると\n驚きの連続ですわ", 1, 9069, 1, 3, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この街は様々な種族が\nなにはばかることなく\n混在しているのですね\n…我々も、いつかは…", 1, 9070, 1, 4, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルにも香水の\nお店があるのですね\nどんな香りが揃って\nいるのでしょうか…♪", 1, 9071, 1, 5, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昨日、素敵な花園を\n見つけたのです\n今日のお茶会は\nそちらでしましょうか", 1, 9072, 1, 101, 4, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気を抜いてはいけない\nとわかっていても、\nここだとつい安心して\nしまいます…ふう…", 1, 9073, 1, 102, 8, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ごきげんよう\n街で見つけた茶葉を\n試しているんです\n騎士様も一杯どうぞ♪", 2, 9074, 1, 1, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("親切な方ばかりですね\n素敵なお友だちが\nできそうな予感で、\nワクワクしてます…♪", 2, 9075, 1, 2, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("黄泉の食卓の皆様用に\nお土産を用意しないと\n騎士様のお知恵も\n頼りにしておりますわ", 2, 9076, 1, 3, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ジオ・ニヴルヘルと\n比べると、この世界は\n本当に明るいですね\n少し眩しいくらいです", 2, 9077, 1, 4, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あまり、血の巡りが\n良くなくて…\n騎士様の手は\nとても温かいですね", 2, 9078, 1, 101, 4, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度はわたくしに\nジオ・ニヴルヘルを\n案内させてくださいね\n観光案内のお返しです", 2, 9079, 1, 102, 8, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n朝の眩しい太陽には\nなかなか慣れません…", 2, 9080, 1, 1, 1, 133101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士様、お茶は\nいかがでしょうか？\n一度一休みして、\n英気を養いましょう", 2, 9081, 1, 2, 1, 133101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眠れないのでしょうか\nまぶたが重くなるまで\nわたくしをお話し\n相手になさって下さい", 2, 9082, 1, 3, 1, 133101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("思わず気が抜けそうに\nなってしまいます…\nふふ、ふわふわ…♪", 3, 9084, 1, 2, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まあ、かわいらしい\nグレイスもきっと\n気に入りそうな\nデザインですわ", 3, 9085, 1, 3, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まあ、いい香り…\n心安らぐようですわ\n素敵なセンスを\nお持ちなのですね♪", 3, 9086, 1, 4, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("燃え移りや乾燥がある\nから近づかないほうが\nいいとわかりつつも…\nああ、温かい…♪", 3, 9087, 1, 5, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食が細いというよりは\n消化があまりうまく\nできなくて…本当は\nまだ頂きたいのですが", 3, 9089, 1, 7, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『薔薇の下の契り』？\nまあ、男性同士で…！\nそんな…こ、これ以上\nここで読むわけには！", 3, 9090, 1, 8, 1, 133101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ダーリンが帰ってくる\n前に部屋の掃除しよ♪\n…ふふ、これってもう\n新婚生活だよね…♪", 1, 9092, 1, 1, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("家具のセンスまで\n私と同じだなんて\n運命って怖いわ…♪", 1, 9093, 1, 2, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人はベッドの下に\n何か隠してるのかな…\nな、なんて全っ然\n気にならないし…っ！", 1, 9094, 1, 3, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うっかりして\n角引っかけないように\nしないとね…", 1, 9095, 1, 4, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("錬金術を使わなくても\nあなたの心を鷲掴む\n私は恋も錬金術も\n失敗しないんだから！", 1, 9096, 1, 5, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人って破廉恥なの\n興味あるのかしら…？\n基本破廉恥禁止だけど\nあの人だけは…許す…", 1, 9097, 1, 101, 4, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("手狭になれば錬金術で\n新しい部屋作るから\nいつ家族が増えても\n安心だよね…♪", 1, 9098, 1, 102, 8, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("錬金術でカレーライス\n作っちゃおっかな♪\n具材を釜でグツグツ…\nま、料理とも言うわね", 2, 9099, 1, 1, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("錬金術に興味がある？\nじゃあさっそく私が\n手取り足取り教えるわ\nって…やだ破廉恥っ！", 2, 9100, 1, 2, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イロハちゃんとの\n虫捕りは命懸けよ！\n一万匹捕れるまで\n帰れないんだから…", 2, 9101, 1, 3, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ソノさんって\n体は小さいけど\nとっても頼れる私の\nお姉さん的存在なの♪", 2, 9102, 1, 4, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はあ…部屋中に広がる\nダーリンの香り…♪\n…ってノゾミみたいに\nなっちゃってる！？", 2, 9103, 1, 101, 4, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鹿の獣人族の特徴は\nこのエッチな角…\n違っ！　叡智よ叡智！\n噛んだだけだからっ！", 2, 9104, 1, 102, 8, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、おはよう！\n寝る前に飲んだ\n目覚めすっきり秘薬の\n効果はバッチリかな？", 2, 9105, 1, 1, 1, 132301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("午後からも頑張る\nあなたのために\n愛妻弁当作ったの♪\n一緒に食べよ？", 2, 9106, 1, 2, 1, 132301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も一日お疲れさま\n眠れないなら隣で…\nじゃなかった早寝して\n明日も頑張ろうね！", 2, 9107, 1, 3, 1, 132301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい錬成をするには\n適度な休憩も必要よね\n…気持ち良くてたまに\n寝落ちしちゃうけど…", 3, 9109, 1, 2, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいぬいぐるみ\n錬成じゃなくて\n手編みで作ったら\n驚いてくれるかも♪", 3, 9110, 1, 3, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くん、くん…\nん～いい匂い♪\nノゾミの香水と\nいい勝負だわ", 3, 9111, 1, 4, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ああ、暖かい\nでもソノさんの作った\nミートパイの方が\nもっと温かいわ…♪", 3, 9112, 1, 5, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…私も\n食べても減らない秘薬\n錬成して他の食べ物も\n作れないかな？", 3, 9114, 1, 7, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…\nこのレシピ面白いわね\n今度錬成してみよっと", 3, 9115, 1, 8, 1, 132301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おー、体が軽い\n腰痛も胃もたれも\nないし、最高かよ", 1, 9117, 1, 1, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いっつも力入れてたら\nいざって時困るし\nやっぱ省エネだな", 1, 9118, 1, 2, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やば…なんか急に\nブドウ朱飲みたい…\nルイちゃんに頼むか？\nいや、でもなあ…", 1, 9119, 1, 3, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あれ、あの材料の在庫\nまだあったっけ…\nルイちゃんに確認しよ", 1, 9120, 1, 4, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イロハのやつ変な\nイタズラしてない\nといいけど…", 1, 9121, 1, 5, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のシフトは～…\nお、彼と一緒じゃん\nふふっ…", 1, 9122, 1, 101, 4, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イロハのやつ\n不用意に私の体で\n彼に抱きつくなって\nこっちが恥ずかしい…", 1, 9123, 1, 102, 8, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も元気だねえ\n若いってうらやま…\nっていや、今は私の\n方が若いじゃん", 2, 9124, 1, 1, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～？　どしたん\nヒマならうちの店で\nバイトしてく？", 2, 9125, 1, 2, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イロハ見なかった？\n今日は手伝うって約束\nしてたのにさあ…", 2, 9126, 1, 3, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ルイちゃん特製\nエナドリ（子ども用）\nこれ飲んで今日も\nお仕事頑張るかー", 2, 9127, 1, 4, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("元の体なら\n君と目線、合うのにね\n…ってドラマかよ\nごめん、今の忘れて", 2, 9128, 1, 101, 4, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんかヒマそうじゃん\n用事ないなら\nお姉さんがコーヒー\n淹れたげよっか", 2, 9129, 1, 102, 8, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわあ…おはよ\n今日もお仕事\nがんばりますかー", 2, 9130, 1, 1, 1, 132501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょうどいいや\n一緒にお昼どうよ\nお姉さんが\n奢ってあげよう", 2, 9131, 1, 2, 1, 132501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぁぁ…ふぅ\nここからは大人の時間\nなんだけどさぁ\n眠くてかなわん…", 2, 9132, 1, 3, 1, 132501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おお～なんか前より\nでっかく感じるわ～\nてそりゃそうか", 3, 9134, 1, 2, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そいえば、イロハって\nあんまこういうの\n欲しがらなかったな～\nクワガタばっかで", 3, 9135, 1, 3, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はあ…いい匂いだね\nさすがルイちゃん特製\n錬金アロマ\n次の目玉商品だな", 3, 9136, 1, 4, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ユカリっち焚火の前で\nキメる麦しゅわに\nハマってるらしいけど\n興味あるわぁ…", 3, 9137, 1, 5, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うわこれ…\n無限にいけちゃうわ\n子どもの胃袋\n恐るべし…", 3, 9139, 1, 7, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ、こんな需要が…\n次の新商品として\nルイちゃんに試作\n頼んでみるか～", 3, 9140, 1, 8, 1, 132501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("服はその人の個性です\n仕立て屋は\nその手伝いをする\nプロなんです♪", 1, 9142, 1, 1, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("糸を紡いで紡いで\n巻き巻き～♪", 1, 9143, 1, 2, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ…あの人の衣装\nなかなか斬新ですね\n後でどうなってるのか\n見せてもらおう♪", 1, 9144, 1, 3, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("動きやすさと\nファッション性\n両立させてみせますよ", 1, 9145, 1, 4, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度のコレクション\n新作にワイルドな\nルームウェアは\nどうかな…？", 1, 9146, 1, 5, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんもたまには\n衣装の感想とか言って\nくれてもいいのにな～", 1, 9147, 1, 101, 4, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ノゾミさんとチカさん\nにも、おそろいの服を\nプレゼントしてみよう\n二人とも似合いそう♪", 1, 9148, 1, 102, 8, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ジオ・ゲヘナでまた\n素材収集したいんです\n手伝ってくれますか？", 2, 9149, 1, 1, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えっ？　薄着すぎ？\nおしゃれのためなら\nこのくらいへっちゃら\nですよ…っくしゅん！", 2, 9150, 1, 2, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("穴が開いてる？\nこれはそーいう\nデザインですー！", 2, 9151, 1, 3, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっとどこ\n触ってるんですかー！\n…あ、糸くず\n取ってくれたんですね", 2, 9152, 1, 4, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんに\n新しい生地の服を…\nいや、シャレじゃ\nないですよ？", 2, 9153, 1, 101, 4, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵な着こなしには\n健康な体も大切！\n騎士さんに見られても\n恥ずかしくないように", 2, 9154, 1, 102, 8, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます！\nさあ、着替えて！\n私が見繕ってあげます", 2, 9155, 1, 1, 1, 134801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼は激辛料理です\nジオ・ゲヘナで\nハマッちゃって…\n一緒にどうですか？", 2, 9156, 1, 2, 1, 134801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("睡眠不足は美容の大敵\nていうかシンプルに…\nね、眠い…", 2, 9157, 1, 3, 1, 134801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くつろげますね～\nでももうちょっと\n生地の手触りが…\nって、職業病？", 3, 9159, 1, 2, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいものって\n心を癒してくれますね\n服もそうありたいです", 3, 9160, 1, 3, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り～♪\nこの匂いにはどんな服\nが合うかなあ…？", 3, 9161, 1, 4, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服露出が多いから\n温かいとほっとする～\nずっとこうして\nいたいかも…", 3, 9162, 1, 5, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いくらでも\n食べられちゃうから、\n自分でストップ\nかけないと…", 3, 9164, 1, 7, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しっかり勉強して\nジオ・ゲヘナに\nお洒落を伝えたいです", 3, 9165, 1, 8, 1, 134801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたくしは高貴なる\nマンティコア！\nサソリでもコウモリ\nでもありませんわよ♪", 1, 9167, 1, 1, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なかなか居心地がいい\nお部屋ですわね～\n…さてどうやって\nあたくしのものに…", 1, 9168, 1, 2, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("高貴なるお審美眼で\nあの家具の価値を\n測ってやりますわ\n…ギリ合格ですわ！", 1, 9169, 1, 3, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("高貴なる笑い声は\n一日にしてならず\nお子様の頃から練習を\n重ねてきたのですわ！", 1, 9170, 1, 4, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お美しいあたくし様と\n同じ空間にいられる…\nどうぞその喜びを\n噛みしめなさいな♪", 1, 9171, 1, 5, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アナタがお土下座して\n頼むなら、あたくしも\nもう少しここに残って\n構いませんわよ♪", 1, 9172, 1, 101, 4, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("馬ボーンをあたくしに\n振り向かせるには\nどうしたら…って、\nこの言い方は語弊が！", 1, 9173, 1, 102, 8, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少し寒いですわね…\n…この服装のせい？\nこっちだって好きで\n着てねぇですわよ！", 2, 9174, 1, 1, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのラミアが来たら\nあたくし様はお用事で\nお留守って言って\n追い返すんですのよ！", 2, 9175, 1, 2, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっちの世界にも\n闘技場がありますの？\nそこもお頂点を極めて\nしまおうかしら～♪", 2, 9176, 1, 3, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("馬ボーンって\n人畜無害そうなお面の\nわりに、時々やること\nえげつねぇですわね…", 2, 9177, 1, 4, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇ馬ボーン…\nアナタあの魔札、\nまだ持ってまして？\nとっとと捨てなさい！", 2, 9178, 1, 101, 4, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("絶対にあたくし様の\nお尻尾に触るんじゃ\nねぇですわよ…？\nいえ、振りではなく！", 2, 9179, 1, 102, 8, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ…\n打倒ネフィのお作戦を\n夜通し考え過ぎて、\n寝不足ですわぁ…", 2, 9180, 1, 1, 1, 134901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうお昼ですの？\nあたくし様に相応しい\n優雅なおランチと\n参りますわよ～♪", 2, 9181, 1, 2, 1, 134901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら馬ボーンったら\nまだ起きてますの？\n…ぐぬぬ、夜の間に\n仕掛ける作戦が…", 2, 9182, 1, 3, 1, 134901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このおフカフカ感…♪\n剣闘士宿舎の\nゴワゴワなお寝床とは\n大違いですわね！", 3, 9184, 1, 2, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんですの、この\n弱っちそうなお顔は…\nおかわいそうですし、\nお僕にしてあげますわ", 3, 9185, 1, 3, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("馬ボーンはこういう\n匂いが好みですの？\nふーん…ほーう…\nなるほどですわ…♪", 3, 9186, 1, 4, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あぁ～～…\nそうそう、これくらい\n暑い方が快適ですわ…", 3, 9187, 1, 5, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ、もぐっ…\nまぁそこそこ？\n悪くないお味では\nありますわねっ", 3, 9189, 1, 7, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんな本よりも、\n華麗なるカノン様の\n活躍録でも置いた方が\n世のためになりますわ", 3, 9190, 1, 8, 1, 134901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さっきねー、外で猫と\n木登り競争したんだよ\nなかなか手ごわい\n相手だった！", 1, 9192, 1, 1, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いっぱい食べて\n大きくなるんだ～\nあっでもこれ\nソノちゃんの体か", 1, 9193, 1, 2, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("強いおねーさんの\n気配を感じる…\nどこから？\n…そこら中から！", 1, 9194, 1, 3, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("虫捕り網の手入れは\nいつもバッチリ！\nいつ何が出るか\nわからないもんね", 1, 9195, 1, 4, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うちの中で走り回ると\nソノちゃんに\n怒られちゃうけど…\nここならいける？", 1, 9196, 1, 5, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おじちゃんも\nお部屋にいろいろ\n隠してるのかな？\nルイちゃんみたいに", 1, 9197, 1, 101, 4, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("世界一になったら\nおじちゃんにも\nいっぱい褒めて\nほしいな…約束っ♪", 1, 9198, 1, 102, 8, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("高いとこのものが\n取りたいときは\nイロハに言ってね\nイロハ得意だから！", 2, 9199, 1, 1, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうも、イロハです\n剣士たるもの、\nあいさつは大事って\n教わったんだ♪", 2, 9200, 1, 2, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イロハと勝負だね！\n受けて立つよ～！\n…あれ、違った？", 2, 9201, 1, 3, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ！　ルイちゃんに\n素材集め頼まれてたの\n忘れてた…！　やばい\nおじちゃん手伝って！", 2, 9202, 1, 4, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("実はイロハって\n褒めたら伸びる\nタイプなんだ\nだからよろしくね♪", 2, 9203, 1, 101, 4, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このお部屋、すごく\n居心地がいいんだ～\nやっぱりおじちゃんが\nいるからかな？", 2, 9204, 1, 102, 8, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昨日仕掛けた罠で\n虫捕れてるかな？\nあとで一緒に\n見に行こうね♪", 2, 9205, 1, 1, 1, 132401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もうお昼だよね？\nイロハのお腹が\n空いてきたから\n間違いないよ！", 2, 9206, 1, 2, 1, 132401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ～…\nあ、あくびじゃないよ\nイロハ大人なんだから\n眠くなんか…ふわぁ…", 2, 9207, 1, 3, 1, 132401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわふわしたものって\nつい飛び込みたく\nなっちゃうよね\n…うずうずっ", 3, 9209, 1, 2, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいのもいいけど\nカッコよさも欲しいな\nそーだ、角とかもっと\nいっぱい付けてみる？", 3, 9210, 1, 3, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おー、いい匂い♪\nこれもしかして\nルイちゃんの新作？\n爆売れ間違いなしだよ", 3, 9211, 1, 4, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬくぬくぽかぽか、\n気持ちいいー…\nでもちょっと\n暑くなってきたな", 3, 9212, 1, 5, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐもぐ…\nこれはいい食材を\n使っておりますなぁ\nうん、三ツ星！", 3, 9214, 1, 7, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむなるほど…\nこっ、これは…！\n…ごめん、適当に\n言ってみた", 3, 9215, 1, 8, 1, 132401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("また海に行く時に\n備えて…次の計画を\n練る必要がある…", 1, 9217, 1, 1, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騒がしいのも…\n以前ほど気にならない\n慣れてしまった…？", 1, 9218, 1, 2, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("眩暈がする暑さも\n騎士クンと同じ気温を\n感じられるなら…いい", 1, 9219, 1, 3, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンに\n好意を抱く者は\nみんな有罪\n…わたしは例外", 1, 9220, 1, 4, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("体も心も…外の世界に\n馴染んできた気がする\n少しずつ、だけど…", 1, 9221, 1, 5, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンの手…\n大きかった…\n…また、つなぎたいな", 1, 9222, 1, 101, 4, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏が終わっても…\nその先の季節も\n…その次の夏も\n騎士クンと一緒に…", 1, 9223, 1, 102, 8, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンといるとね\n渇いてた心が…\n潤される、気がするの", 2, 9224, 1, 1, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンは…\nしたいこと、ある？\n夏にだけ…できること\n一緒に、しようね", 2, 9225, 1, 2, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("仮想領域の夢でも\n現実の海でも…\n騎士クンと一緒なら\nそこが本物の夏、だね", 2, 9226, 1, 3, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("肝試しがしたい…？\n…うまく驚けるかな\n練習しなくちゃ…", 2, 9227, 1, 4, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンとなら\nどんな夏でも…\nきっと楽しい…♪", 2, 9228, 1, 101, 4, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着…どうかしら…？\n…よかった\nシミュレーションの\n成果ね。ふふ", 2, 9229, 1, 102, 8, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クン…眠たそう\nもうちょっと…寝る？\n後で起こしてあげるね", 2, 9230, 1, 1, 1, 135001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お出かけするなら\n水筒を用意するね…\n夏の水分補給は大事…", 2, 9231, 1, 2, 1, 135001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("また…夜の海を\n見に行きたいな\n騎士クンと一緒に\n連れていってくれる？", 2, 9232, 1, 3, 1, 135001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンを待つには\nちょうどいい…\n…落ち着く…", 3, 9234, 1, 2, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういう物を\n城に置いた方が\nかわいいって思って\nもらえる…かな…？", 3, 9235, 1, 3, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏に合わせた香りね…\n涼やかな風が胸を\n吹き抜けるような…", 3, 9236, 1, 4, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("火は落ち着く…\n身体感覚を味わえる\n作り物の…この体でも", 3, 9237, 1, 5, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『食』…騎士クンと\n話す共通の話題には\n悪くなさそう…", 3, 9239, 1, 7, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『好きな人と楽しめる\n夏デート特集』…？\n……ふむ…", 3, 9240, 1, 8, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたしの趣味では\nないけれど…\n騎士クンが望むなら\n城に置いても…？", 3, 9242, 1, 10, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("む…悪くない\nこれなら\n騎士クンと一緒に…？", 3, 9243, 1, 11, 1, 135001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一日中水着でいるって\n浮かれているみたいね\n夏は短いから、沢山\n楽しまなくちゃね", 1, 9244, 1, 1, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと暑いし\n氷の上を滑って\n涼もうかしら", 1, 9245, 1, 2, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ運送ギルドの\nアルバイトの時間だわ\n準備しなきゃ", 1, 9246, 1, 3, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エリスさん、水着が\nすごく似合ってた…\nどこで買ったのかしら", 1, 9247, 1, 4, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("未練が残らないように\nこの夏休みでやりたい\nことはやらなくちゃ", 1, 9248, 1, 5, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かき氷を作ったら\n彼も食べるかしら？\nアイスクリームの\nほうがいいかな…", 1, 9249, 1, 101, 4, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着を着ていれば\nどこにいても\nリゾート気分だわ♪", 1, 9250, 1, 102, 8, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏はおいしいものが\nたくさんあるし\n【美食殿】の活動も\n忙しくなりそうね♪", 2, 9251, 1, 1, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わ、私の尻尾…\nそんなに気になる？\nつついたらダメよ\nいいわね…？", 2, 9252, 1, 2, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏は日が長いし\nまだまだたくさん\n遊べそうね♪", 2, 9253, 1, 3, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は一緒に海に\n行かない？\nあなたも水着\n持ってきてるでしょ", 2, 9254, 1, 4, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ日焼け止めを\n塗り直さなきゃ…あの\nお願いしてもいい…？", 2, 9255, 1, 101, 4, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私たちで最高の\n夏休みにしましょう\nね、おにーたん♪", 2, 9256, 1, 102, 8, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の朝は早いわね\nもうセミも鳴いてるし\nあなたも早起きだわ…\n見習わなくちゃ", 2, 9257, 1, 1, 1, 135101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日中は暑いだろうし\nゆっくりしましょう\nお昼寝タイムはどう？", 2, 9258, 1, 2, 1, 135101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この時間のアイス\nクリームは格別よね♪\n何味にしようかしら", 2, 9259, 1, 3, 1, 135101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暑い夏はしっかり\n休むことが大切\nふぅ…いい気持ち♪", 3, 9261, 1, 2, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわふわの毛並み\n暑くないのかしら\nかわいいだけじゃなく\n忍耐強くもあるのね", 3, 9262, 1, 3, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("爽やかでいい匂い…♪\nジトジトしがちの夏に\nピッタリなアロマね", 3, 9263, 1, 4, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ずっと水着でいると\n流石に冷えるわね\nうん、いい心地だわ", 3, 9264, 1, 5, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はむっはむっ…\nしっかり食べて\n夏バテ対策しないと", 3, 9266, 1, 7, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむふむ…面白いわね\n今度プレシアちゃんと\n一緒に読もうかしら", 3, 9267, 1, 8, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私のフロートと少し\n似ている気がする\nサイズ的にはこっちが\nお兄さんかしら…ふふ", 3, 9269, 1, 10, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、きれい♪\nまるで\n海のステージね！", 3, 9270, 1, 11, 1, 135101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じゅんび、おっけー\nうみでも\nおふろでも\nおんせんでも", 1, 9271, 1, 1, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひまわり。すき\nおっきくて\nたね、うまし", 1, 9272, 1, 2, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハッピーちゃん\nいい、におい\nひやけ？\nやきぶた？", 1, 9273, 1, 3, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じーわ、じーわ…\nせみの、なきごえ\nきいてる、だけで\nあつい。かも…", 1, 9274, 1, 4, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイス、かきごおり…\nあつい、なつ\nだから\nひえひえ、ひっす", 1, 9275, 1, 5, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おっきくなるまほー\nきわめたい\nお兄を\nだっこ。するよ", 1, 9276, 1, 101, 4, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("「あなた」\n…ちょっと、ちがう？\nシェフィたち\nみたいに、ならない…", 1, 9277, 1, 102, 8, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じゃりじゃり\nべたべた\n…シャワー\nいって、きます", 2, 9278, 1, 1, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("（すんすん）\nお兄。ほんのり\nうみの、におい\nおいしそう", 2, 9279, 1, 2, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄。みて\nべろ、まっさお\nぶるーはわい\nカラー", 2, 9280, 1, 3, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あつくても\nあついもの\nおいしい\n…バーベキュー…", 2, 9281, 1, 4, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ついんて\nバランス、むずかし\nお兄\nリボン、よろ", 2, 9282, 1, 101, 4, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みずぎ\nにあってる。って\nお兄。いった\nもっと。みて？", 2, 9283, 1, 102, 8, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよ\nあさごはん\nやきざかな", 2, 9284, 1, 1, 1, 135201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おひる\nおひるね\nいっしょに、しよ？", 2, 9285, 1, 2, 1, 135201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おそと\nまっくら\nはなび\nしよ？", 2, 9286, 1, 3, 1, 135201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ…\nあそびすぎ\nおつかれ\nねむねむ", 3, 9288, 1, 2, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よしよし\nおるすばん\nおねがい。ね", 3, 9289, 1, 3, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("（くんくん）\nれもんの、におい\nじゅる", 3, 9290, 1, 4, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さかな、くしやき\nすたんばい、おっけー\nいつでも、やける。よ", 3, 9291, 1, 5, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いっぱい、あそびたい\nいっぱい、つよくなる\nいっぱい、たべる", 3, 9293, 1, 7, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おさかなの、ほん\nおもしろかった\nでも\nおなかが…", 3, 9294, 1, 8, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("れっつ、ごー\nすいへーせん\nせかい\nいっしゅー", 3, 9296, 1, 10, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("きぶんは、かいばしら\nバターやき\nおすすめ", 3, 9297, 1, 11, 1, 135201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("成長して着れなく\nなっちゃう前に\nこの水着でできること\n全部しちゃいたいな♪", 1, 9298, 1, 1, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お家で水着だと\n開放的な気分かも♪\nふふ、お兄さんにも\n教えてあげなきゃ♪", 1, 9299, 1, 2, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぎの練習しちゃお♪\nすいすい、すいすいー\n…ちょっと、\n子供っぽかったかも…", 1, 9300, 1, 3, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("インドア派だけど\n夏の屋外は好き…や…\nお兄さんと一緒なら\nどこでも…", 1, 9301, 1, 4, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏だからってちょっと\n羽目外しすぎかな…\nわたし…やっぱり\n真面目じゃない…かも", 1, 9302, 1, 5, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたしの水着姿…\n少しは大人っぽいって\n思ってくれたかな…？", 1, 9303, 1, 101, 4, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("家の中は涼しいのに\nお兄さんのこと\n考えると暑くなって…\n夏バテしちゃいそう…", 1, 9304, 1, 102, 8, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さんと一緒なら\n夏休みの日記\n書くことが多すぎて\nページが足りません♪", 2, 9305, 1, 1, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かき氷食べましょ♪\n…ふふ、お兄さん\n舌の色すごいですよ♪\nわたしも…べ～っ♪", 2, 9306, 1, 2, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は海に行きます？\nそれともお家で\nのんびりですか？\nわたしはどっちでも♪", 2, 9307, 1, 3, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏バテしないように\nスタミナ料理のレシピ\nお勉強しました♪", 2, 9308, 1, 4, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏が終わっちゃっても\nこの水着を着てたら\n夏の思い出、忘れずに\nいてくれますか…？", 2, 9309, 1, 101, 4, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…この日焼け跡\nお兄さんと\nわたしだけの\n秘密…ですよ？", 2, 9310, 1, 102, 8, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます！\n朝の体操１、２、３♪\nしゃきっと目覚めて\nいい一日にしましょ♪", 2, 9311, 1, 1, 1, 135301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼休憩ですね♪\n午後からも頑張れる様\nお兄さんのこと\n癒しますね…♪", 2, 9312, 1, 2, 1, 135301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ寝る時間…\nお兄さんが眠るまで\n一緒にいますね…\n…ふあぁ…", 2, 9313, 1, 3, 1, 135301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちいいけど、汗…\n染みちゃわないように\n気をつけないと…", 3, 9315, 1, 2, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぎゅう～♪\nなんて、ちょっと\nあざといかな…♪", 3, 9316, 1, 3, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏にぴったりの\nフルーティーな香り♪\nお兄さん、好きかな？", 3, 9317, 1, 4, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着で暖まるのって\nなんだか贅沢な気分♪\nこたつでアイス的な♪", 3, 9318, 1, 5, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹ぽっこりに\nならないよう\n気をつけないと…\nでも止まらない…", 3, 9320, 1, 7, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弾ける水着でビーチの\n視線を独り占め…かぁ\nわたしはお兄さんの\n視線だけで…なんて♪", 3, 9321, 1, 8, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これで夏の大冒険に\nしゅっぱ～つ！\n…なんちゃって♪", 3, 9323, 1, 10, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだか女神さま\nみたい…？\nふふ、わたしには\n似合わないかもです♪", 3, 9324, 1, 11, 1, 135301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("真っ白い日差し─\nジオ・ゲヘナには\nなかったものですね\n─悪くはないです", 1, 9325, 1, 1, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しばらくここで\n休んでます\n人の多い街中よりは\n落ち着くので─", 1, 9326, 1, 2, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにも─\nあるんでしょうか\n海で使う遊び道具…", 1, 9327, 1, 3, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見張りは─\nここならあまり\n必要なさそう…", 1, 9328, 1, 4, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏のバカンス─\n媛が楽しんでるなら\n私は十分です", 1, 9329, 1, 5, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("知らない相手は、\n苦手だけど─\n…少しだけ、\n話してみても…", 1, 9330, 1, 101, 4, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいると\n安心する、ような…\n土壌が─良い…？", 1, 9331, 1, 102, 8, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏の正装、水着─\n着方、間違えて\nないですよね…？", 2, 9332, 1, 1, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("相変わらず、\nおしゃべりが\n好きなんですね\n私は─普通です", 2, 9333, 1, 2, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("─喉が渇きました\n…いえ、花にお水が\n欲しいわけじゃなくて", 2, 9334, 1, 3, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("─いつもより\n花がつやつやしてる？\n…あ、褒めて\nくれたんですか", 2, 9335, 1, 4, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この部屋─\n貴方が飾りつけを？\nわかります、何となく", 2, 9336, 1, 101, 4, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すぐ傍にいると、\n暑くなりませんか？\n─私は別に\nかまいませんが", 2, 9337, 1, 102, 8, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝から元気ですね─\nおかげですっかり\n目が覚めました", 2, 9338, 1, 1, 1, 135401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外─暑そうです\n出かけるなら\n気を付けてください\n倒れたりしないよう…", 2, 9339, 1, 2, 1, 135401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("─貴方も\n夜更かしですか？\n…少しだけなら\n付き合いますよ", 2, 9340, 1, 3, 1, 135401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴方もここで\n休みたいですか？\n─ダメです\n今は私が使うので", 3, 9342, 1, 2, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ゆるい顔つきですね\nジャングルでは\n生き残れそうに\nないです─", 3, 9343, 1, 3, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("─ん…\nこれ、海の香り？\n─いい匂い…", 3, 9344, 1, 4, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…暑さには\n慣れてますよ\n寒いのよりは、ずっと", 3, 9345, 1, 5, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("栄養は、大事です\n味は─あまり\n気にしたこと、\nありませんでした", 3, 9347, 1, 7, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("適当に本を読んでいる\nだけです─\n…別に、遊びについて\n調べたりしてません", 3, 9348, 1, 8, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔物を模した\n人形─ですね\n戦闘訓練用に？", 3, 9350, 1, 10, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貝のクッションですか\n─噛みついてきたり\nしないですよね", 3, 9351, 1, 11, 1, 135401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シントーメッキャク\n火もまた涼し…\nむむむ…やっぱり夏は\n暑いデース！", 1, 9352, 1, 1, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海にも新しい忍法の\nヒントがあるはずデス\nショーグンと海底散歩\nも楽しそうデス", 1, 9353, 1, 2, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("釣りの心得は\nメイキョーシスイ…\n忍者の修行に\nうってつけデス♪", 1, 9354, 1, 3, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("天下統一の後のことも\n考えねばなりまセン\n今度はテンジョー統一\nデスかね…？", 1, 9355, 1, 4, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("デケデケデン♪\nテルテル坊主完成デス\n晴れてないとお外で\n遊べまセンからね！", 1, 9356, 1, 5, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次のオモテナシも\nショーグンをワクワク\nさせマス♪　今から\n用意しておかねばデス", 1, 9357, 1, 101, 4, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新しい忍法の開発に\n休みはないのデス！\nショーグンの天下統一\nを思えばなんのその！", 1, 9358, 1, 102, 8, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の前に準備運動デス\nまずは手を後ろに、\n素早く忍者走り！\nシュバババッ", 2, 9359, 1, 1, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夏にお祭りは\n欠かせないデスよね♪\n地域のイベント情報は\n見逃しまセン！", 2, 9360, 1, 2, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグン、団扇で\nあおいであげマス！\n忍法・扇風の術ー！\nうりゃりゃりゃー！", 2, 9361, 1, 3, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ワタシが必要な時は\n風鈴を鳴らすデス！\n風よりも早く\n駆けつけマスよ！", 2, 9362, 1, 4, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じっと見つめられると\n顔が熱くなってきて…\nはっ、ショーグンの\n新しい忍法デスか！？", 2, 9363, 1, 101, 4, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグン、日焼けは\nノン、デスよ！\nワタシがクリームぬり\nぬりしてあげマース！", 2, 9364, 1, 102, 8, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようデス！\n朝ごはんはワタシに\nお任せデス。\n毎日みそ汁作るデス！", 2, 9365, 1, 1, 1, 137101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日差しに注意デスよ\nネッチューショーに\n日焼け、どっちも\n大変デスからね！", 2, 9366, 1, 2, 1, 137101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグン、\n外で花火しまショウ！\nぱちぱちキレイで\n楽しいデスよ！", 2, 9367, 1, 3, 1, 137101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("遊びに備えて\n今は休む時…\nガシンショータンデス", 3, 9369, 1, 2, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子たちにも\n手伝ってもらって\n新しい忍法を開発\nしてみまショウ♪", 3, 9370, 1, 3, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むむっ、ここまで\n潮の香りが漂って\nきた気がしマス！", 3, 9371, 1, 4, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海に入った後は\n体を温めねば\nやはりサウナも\n必要デスね！", 3, 9372, 1, 5, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いっぱい食べて\nいっぱい遊ぶデス！\n夏バテなんかに\n負けてられまセン！", 3, 9374, 1, 7, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『BUSHIDO』の\n最新刊が待ち遠しい\nデス…マイゾーキン\n特集、読みたいデス", 3, 9375, 1, 8, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ショーグンとこの子に\n乗って、天下統一まで\nシュババババッ！\nなんてどうでショウ", 3, 9377, 1, 10, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽよんぽよ～ん♪\nショーグンと一緒に\n遊んでみたいデス♪", 3, 9378, 1, 11, 1, 137101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度はシナツちゃんの\n世界へ行ってみたいな\nエリスちゃんも誘って\n大人女子旅とか最高♪", 1, 9379, 1, 1, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっはっはー！\nよし、今日も絶好調！\nま、いつも笑ってたら\n不調なんてないけど♪", 1, 9380, 1, 2, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～あっちの世界と\nほとんど一緒だね！\n違ってるところ探しに\n出かけてみよっかな？", 1, 9381, 1, 3, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ううーん、のんびり\nするのもいいけど\nどこか行ってみたいな\n人助けとか、ね", 1, 9382, 1, 4, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、そーだ\n向こうへ帰る前に\nこっちのお土産とか\n買っとかなくちゃ", 1, 9383, 1, 5, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふ～ん、騎士くんって\nこういうのが好みか～\n後でヒヨリちゃんに\n教えてあげよ♪", 1, 9384, 1, 101, 4, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次はあたしが恩を返す\n番だね。騎士くんに\n助けが必要になったら\n絶対駆けつけるよ！", 1, 9385, 1, 102, 8, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ騎士くん！\n困ってることない？\nお姉さんがなんでも\n力になっちゃうよ！", 2, 9386, 1, 1, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("また闘技場に行こうよ\nちょっと運動不足でさ\nバーンと暴れたい気分\nなんだよね♪", 2, 9387, 1, 2, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつか大人になったら\n一緒に飲もうよ！\nあははっ、騎士くん\n指切りげんまん♪", 2, 9388, 1, 3, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒に作った麦しゅわ\nカップ、最高だね♪\n騎士くんの分もどうぞ\nちゃんとジュースだよ", 2, 9389, 1, 4, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ…ぶっちゃけ\nヒヨリちゃんのこと\nどう思ってるのかな？\nお姉さんに聞かせなよ", 2, 9390, 1, 101, 4, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士くん、うっかり\n飲みすぎたあの日の\nコトは誰にも内緒で\nお願いね。約束だよ！", 2, 9391, 1, 102, 8, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あはは、騎士くん\n新しい朝だよー！\n今日はどんな一日か\nワクワクするね～♪", 2, 9392, 1, 1, 1, 135501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("午後からも笑顔で\n元気に乗り切ろうね！\n外に行くもよし、\n部屋で麦しゅわもよし", 2, 9393, 1, 2, 1, 135501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここからは大人の時間\n騎士くんにはまだ少し\n早いかな～？\nだから、おやすみ♪", 2, 9394, 1, 3, 1, 135501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("麦しゅわ飲み過ぎた\n夜はここにダーイブ\n…なんて大人に\nなっちゃダメだよ～？", 3, 9396, 1, 2, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしの世界の子たち\nこういうの好きかな？\nお土産に探してみよう\n気に入るかも♪", 3, 9397, 1, 3, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～いいね♪\nあとでお気に入りの\nフレーバーも\n試してみよっかな？", 3, 9398, 1, 4, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほうほう…熱い！\nサラサリアは\nいつも暖かいから\nこういうの新鮮！", 3, 9399, 1, 5, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～おいしい！\nけどやっぱご飯は\nみんなで一緒に\n食べたいな～", 3, 9401, 1, 7, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("文字ばっかの本は\nちょーっと苦手かも…\n必要なら読むけどさ？", 3, 9402, 1, 8, 1, 135501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("皆思い思いに過ごして\nいるのに、不思議と\n落ち着く。いつまでも\nここにいられたら…", 1, 9406, 1, 1, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("皆に挨拶をせねば\n…いや、今は、まだ\nタイミングが悪い…\nまた今度にしよう…", 1, 9407, 1, 2, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の服装…この場で\n浮いてないだろうか\nまずい、心配に\nなってきた…！", 1, 9408, 1, 3, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイラたちとの旅行も\n楽しかったな…\nまた３人で温泉に\nいきたいものだ", 1, 9409, 1, 4, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここで剣の稽古は\nさすがによろしくない\n代わりに今日は瞑想を\nすることにしよう", 1, 9410, 1, 5, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("人とのつながりは\n大切にしなければ\n今日こそは誰かに\n話しかけるぞ…！", 1, 9411, 1, 101, 4, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("できることが増えて、\n迷うばかりの毎日…\nそれが楽しく尊いと\n今実感している…", 1, 9412, 1, 102, 8, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ええと…奇遇だな\nこんなところで\n会うなんて。いや違う\n…その、こんにちは…", 2, 9413, 1, 1, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟子たちへの土産も\n探しておかないとな\nよければキミからも\nアドバイスを頼む…", 2, 9415, 1, 3, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("剣の稽古をしたい？\nふっ…いいとも\nキミとならいくらでも\n準備をしてすぐ戻る", 2, 9416, 1, 4, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よければまた、\n街を案内してくれ\n名所旧跡もだがキミと\n歩くのは楽しいんだ", 2, 9417, 1, 101, 4, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("感謝の心を\n忘れたことはないよ\nキミたちの優しさに\n救われた一人として…", 2, 9418, 1, 102, 8, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うむ、いい顔だな\n良い一日は、\n良い目覚めから始まる\n心掛けておくといい", 2, 9419, 1, 1, 1, 135601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう昼時か\n誰かを誘って食事に…\n…いや無理だ、\nハードルが高い…！", 2, 9420, 1, 2, 1, 135601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜はいい…\n誰とも話さず\n一人きりでいても、\n不自然ではないからな", 2, 9421, 1, 3, 1, 135601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…いかんな、これは\n気を抜くとこのまま\n離れられなくなる…", 3, 9423, 1, 2, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("シナツだ、よろしく\n……ふぅ\n人形相手の練習なら\n緊張しないのだがな…", 3, 9424, 1, 3, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ…集中力が\n高まりそうな香りだな\n稽古にも役立つだろう\n皆にも教えてやろうか", 3, 9425, 1, 4, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("凍える人に寄り添い\n温もりを与える…\n私もそんな存在に\nなりたいものだ", 3, 9426, 1, 5, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食の楽しみ…\nあまり意識して\nいなかったが、\nやはりいいものだな", 3, 9428, 1, 7, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…っと、いかん\n読みふけっていたら\nいくらでも時間を\n過ごせてしまうぞ…", 3, 9429, 1, 8, 1, 135601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("また空を飛びたいな～\nふわふわ～ってなる\nあの感じが気持ちいい\nんだよね～♪", 1, 9433, 1, 1, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("またサラサリアに\n行きたいなー\n…串焼きの味が\n忘れられなくって♪", 1, 9434, 1, 2, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悩んでる人がいたら\n背中を押してあげたい\nあたしがそれで、勇気\nづけられたみたいに", 1, 9435, 1, 3, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気持ちを言葉にするの\n大事って分かってても\nいざとなると緊張して\n上手くできないなぁ…", 1, 9436, 1, 4, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっちの世界でも\nギルドハウスは\nあるのかな…？\n今度探してみよっと♪", 1, 9437, 1, 5, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイラに会って少し\n成長できたかも…！\n素敵な女の人目指して\nもっと頑張るぞーっ♪", 1, 9438, 1, 101, 4, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっちのあたしは\n騎士くんに選ばれた…\nよし、あたしも\n頑張らなくっちゃ…！", 1, 9439, 1, 102, 8, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋の模様替えする？\nサラサリア風の家具も\nあったら素敵だよね！", 2, 9440, 1, 1, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんだかお疲れ気味？\nそうだっ、サラサリア\nで教わったマッサージ\nをしてあげるっ♪", 2, 9441, 1, 2, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士くんっ！\n今からあたしとデート\nしませんかっ！", 2, 9442, 1, 3, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今ちょうど、踊りの\n練習してたとこなの\n騎士くんも\n一緒にどう？", 2, 9443, 1, 4, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("き、騎士くん！\nこの前の続き…\n手、繋いでいい…？", 2, 9444, 1, 101, 4, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへへ、騎士くんが\nあたしの背中を押して\nくれると、勇気も\n100万倍だよっ♪", 2, 9445, 1, 102, 8, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよ、騎士くん！\n今日もいい朝だよ！\nサラサリアみたいに\n太陽が輝いてるもん！", 2, 9446, 1, 1, 1, 135701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フレフレ、騎士くん！\n午後もファイトー！\nあたしは日陰でお昼寝\nタイム…なんてねっ♪", 2, 9447, 1, 2, 1, 135701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜に騎士くんといると\n空飛ぶ絨毯から見た\nサラサリアの夜景を\n思い出しちゃうな♪", 2, 9448, 1, 3, 1, 135701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休憩きゅうけ～い♪\n強い人と戦った後は\nしっかりと体を\n休ませないとね", 3, 9450, 1, 2, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("にゃ～、\nかわいいにゃ～♪\nアンブラを\n思い出しちゃうよ♪", 3, 9451, 1, 3, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わっ…すごくいい\n匂い～サラサリアの\n砂漠の匂いにちょっと\n似てるかも", 3, 9452, 1, 4, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サラサリアの太陽\nみたいに暖かい♪\n日向ぼっこしてる\nみたいでしあわせ…", 3, 9453, 1, 5, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～おいしいっ！\nアイラもきっと\n好きな味だね…！\n今度食べてもらおっ！", 3, 9455, 1, 7, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これは恋愛指南本…！\nふむ…意中の男性と\nキスするには…って\nこれはまだ早いよ～！", 3, 9456, 1, 8, 1, 135701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あてがここにいたら、\nみんな寒い思いを\nしちまうかな…\nご、ごめんな", 1, 9460, 1, 1, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あて、みんなより\n体でっけぇし…\nもうちょっと隅っこ\n行っとこうかな", 1, 9461, 1, 2, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さ、騒がしいとこは\n苦手だども…\nここはそんなに\n気になんね…", 1, 9462, 1, 3, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いろいろ勉強してぇな\nイナカもんだから、\nみんなに迷惑とか\nかけねぇように…", 1, 9463, 1, 4, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("家具とか、飾りとか、\n壊しちまったら大変…\nき、気ぃつけねぇとっ", 1, 9464, 1, 5, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、あての三味線、\n聴きたいの…？\nこ、心の準備が\nできてからで、い…？", 1, 9465, 1, 101, 4, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("っ、ぁぶね…\nあてったらまた、\n騎士さのこと見て、\n溶けそうになってた…", 1, 9466, 1, 102, 8, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、おめさ、その…\nおやつさん、いらね？\nかき氷とかなら、\nあて、作れるよ…？", 2, 9467, 1, 1, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、あてに…何か用？\n…声、聴きたかった？\nな、なら…えっと…\nおしゃべり…する？", 2, 9468, 1, 2, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっちさ来てから…\n向こうの世界の\n何年分も、おしゃべり\nしたかもしんね…", 2, 9469, 1, 3, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっちの世界には、\n氷滑りって遊びが\nあるって…？\nあてにもできっかな…", 2, 9470, 1, 4, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん…あては元気だよ\n悩みがあっても、\nおめさの声もらうと\n吹っ飛んじまうし…", 2, 9471, 1, 101, 4, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さが近くに\nいてくれる…\n今は、それだけで\nいいんだ…うん…", 2, 9472, 1, 102, 8, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お、おはよ…\nおめさのおかげで、\n昨夜もよく眠れたよ…", 2, 9473, 1, 1, 1, 135801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…あっ、もう昼飯の\n時間かぁ…\n考えごとしてたら\nあっという間だよ", 2, 9474, 1, 2, 1, 135801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("景色は似てるけど…\nこの世界の夜は、\nざわざわ音がして\n賑やかだな…", 2, 9475, 1, 3, 1, 135801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんま縮こまってると\n体硬くなっちまうし…\nたまにはのんびり…", 3, 9477, 1, 2, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ、めんこいな…\nそだ、仁太坊たちも\n並んでたら\nもっとめんこいかも…", 3, 9478, 1, 3, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この匂い…なんか、\nは、はいから…？\nあて、イナカもん\nだから…", 3, 9479, 1, 4, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、暑くて溶けそう…\nだども、我慢できたら\n修行になる…かも…？", 3, 9480, 1, 5, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん…♪　うめぇ…\nこんなうめぇもん\n毎日食べられるの、\n幸せだなぁ…", 3, 9482, 1, 7, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっちの世界にも…\n雪女が出る物語、\nあるみてぇだな…\nか、悲しい話だども…", 3, 9483, 1, 8, 1, 135801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なかなか上等な\n家じゃねェか\nちっとばかし\n軒を借りるぜ", 1, 9487, 1, 1, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("俺の棒っきれの\n置き場所は…\nま、玄関にでも\n立てかけときゃいいか", 1, 9488, 1, 2, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっちの世界は\n眩しくって敵わねェぜ\n目がチカチカしやがる", 1, 9489, 1, 3, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("建物の様式が同じでも\n世界と住人が違えば\n印象も変わるモンだな", 1, 9490, 1, 4, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("街の連中は\n戦いなんて知らねェ\nのんきなツラしてんな\n…いいトコじゃねェか", 1, 9491, 1, 5, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士公のヤツ、\nまたぞろ厄介事に\n巻き込まれや\nしてねェだろうな…", 1, 9492, 1, 101, 4, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわぁ…\nこうも居心地がいいと\n眠くなっちまうぜ", 1, 9493, 1, 102, 8, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("俺ばっかり\n見てんじゃねェよ\n赤鬼になっちまわぁ", 2, 9494, 1, 1, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("注いでくれんのか？\nあんがとよ\nんじゃ俺からも\nお返しだぜ", 2, 9495, 1, 2, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おう、暇してるなら\n鍛錬に付き合えよ\nじっとしてっと\n体がなまって仕方ねェ", 2, 9496, 1, 3, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("退屈してきたな…\n散歩にでも行くか？\n騎士公なら退屈しねェ\n場所知ってるだろ", 2, 9497, 1, 4, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("女との関係は\nきちっとしとけよ\n俺だって助けらんねぇ\nもんはあるからな", 2, 9498, 1, 101, 4, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("角に触りたいだぁ？\n…まあ、騎士公の\n頼みなら…\nあんま手荒にすんなよ", 2, 9499, 1, 102, 8, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("起きろ\n朝の鍛錬の時間だぜ\nほれ、さっさと\n身支度しちまいな", 2, 9500, 1, 1, 1, 135901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼飯ィ？\n俺の分はいらねぇよ\n気ィつかわねぇで\nくんな", 2, 9501, 1, 2, 1, 135901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まだ起きてんのか？\nさっさと寝ねェと\nこうやって鬼が来るぜ", 2, 9502, 1, 3, 1, 135901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("悪くない座り心地だな\n気ィ抜くと、ダメに\nされちまいそうだぜ", 3, 9504, 1, 2, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…今こいつ動いたか？\nグレ公あたりが\n悪さしてんじゃ\nねェだろうな", 3, 9505, 1, 3, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士公はこういう\n香りが好みか？\nお姫とユキノに\n教えてやるとすっか", 3, 9506, 1, 4, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("地獄の釜よりかは\nちとぬるいが…\nなかなか\nいい火力してやがるぜ", 3, 9507, 1, 5, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっちの世界の本にも\n鬼が出てくるのか", 3, 9510, 1, 8, 1, 135901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フランシュシュ１号、\nサクラです！　サガの\n心を、歌でみんなに\n届けにきました！", 1, 9514, 1, 1, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルはドキドキ\nいっぱいの街やけん！\nサガとどっちが\n暮らしやすかろうねっ", 1, 9515, 1, 2, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ソロ活動がんばって、\n憧れの子にもも～っと\n近づくと！　成長した\n私、早く見せたか～！", 1, 9516, 1, 3, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋におるとは、伝説\nのメンバーばかり…！\n私もこのランドソルで\n伝説ば刻むとよ！", 1, 9517, 1, 4, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あそこの修繕が気に\nなると…。…あのっ！\nあ、ついあの子を\n呼びそうに…えへへっ", 1, 9518, 1, 5, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイドルのレッスン、\n気になると？　まず、\n脚をぐい～っと広げて\n…あわわ、戻らん！？", 1, 9519, 1, 101, 4, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんのコネが\nあれば、いつか堂々と\nゾンビアイドルで\n売り出せるかもっ…！", 1, 9520, 1, 102, 8, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようござい\nまーす！　挨拶は基本\nやけん、元気よくっ！\nさ、一緒にやろう！", 2, 9521, 1, 1, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身だしなみチェック、\nよしっ。今日もいい\n天気っ♪　さあ、\nいってきまーーす！！", 2, 9522, 1, 2, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんまり引っ張ると、\nう、腕が～…！　あ、\n気にせんで。伸びても\nすぐ元に戻るけんっ♪", 2, 9523, 1, 3, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私、持っとらんって\n思ってきたけど、それ\nが何ね！　友達ば、\nいっぱい持っとるけん", 2, 9524, 1, 4, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("嚙めば噛むほど味が\n出る…騎士さんは\nサガのアタリメ\nみたいな人やねっ♪", 2, 9525, 1, 101, 4, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんにだけ教え\nますね。私の秘密…\n私の死因を。え？\nもう分かる気もする？", 2, 9526, 1, 102, 8, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぼ～っとしとかれんね\n「ぶっ殺すぞ」って\n気合入れてくれる子が\n両方の街におるけんっ", 2, 9527, 1, 1, 1, 136101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのすごか食べっぷり\nよう思い出すとよ\n元気かな…変なもん\n食べてないかな…", 2, 9528, 1, 2, 1, 136101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜、出歩くと、怖～い\nアンデッドに襲われる\nかもしれんよ！\n気をつけんと…！", 2, 9529, 1, 3, 1, 136101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リラックス！　もっと\nがんばってリラックス\nせんといかんね！\nむむむ～っ！", 3, 9531, 1, 2, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("が～ばや～らしか～♪\nあの子のお土産に\nしたいけど、同じの\n売っとらんかな…？", 3, 9532, 1, 3, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～、いい香りっ♪\nいつもこやん素敵な\n香りのする人が、私の\n友達におってね…", 3, 9533, 1, 4, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("え～と…熱いとその…\n傷んじゃいそうで、\nちょっと心配やけん…\nそ…その…私の体が", 3, 9534, 1, 5, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わあ、美味しか～っ！\nランドソルのグルメも\nなかなか手強いっ…！\nサガも負けられんね～", 3, 9536, 1, 7, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイドル雑誌はあると\nですかね？　フラン\nシュシュのランキング\nは…しょぼぼぼーん…", 3, 9537, 1, 8, 1, 136101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("名探偵から聖職者へ、\n華麗なる変装だ！\nいや、心の中まで\n敬虔に…変貌、かな♪", 1, 9541, 1, 1, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("真実の鏡で、誰の謎も\n解いてみせるよ。\n恋の謎は…私が解いて\nほしいくらいだ…", 1, 9542, 1, 2, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("歩き方も…厳かに…\n気品と高潔さが\n感じられるように\n練習しなくてはね", 1, 9543, 1, 3, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の行いはきっと、\nどこかで見られている\nかつてお別れをした\n大切なあの子にも…ね", 1, 9544, 1, 4, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("異議あり！　…う～ん\nもっと威厳をもって…\n異議あり！　はっ、\n聞いていたのかいっ！", 1, 9545, 1, 5, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("静かに心を見つめれば\n大切なものが分かる\n助手くんとの時間の\nかけがえなさも、ね", 1, 9546, 1, 101, 4, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私も、想い合う二人の\n神聖な誓約の儀と\nいうものに憧れるよ\nつまり結婚式、にね…", 1, 9547, 1, 102, 8, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("珈琲を一杯お願い\nするよ、助手くん\nこれがないと私の\n推理が冴えなくてね", 2, 9548, 1, 1, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("懺悔があるなら聞き\n届けよう。…え～っ！\n棚にある私のチョコを\n食べてしまったって！", 2, 9549, 1, 2, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("助手くん、今日の\n依頼は何件かな\nもし誰も来ないなら\n一緒にお出かけしよう", 2, 9550, 1, 3, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さあ、出かけようか\n君と私で巡礼の旅だ\n鞄の中身はただ一つ\n真実を愛する心、さ！", 2, 9551, 1, 4, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒に祈ってくれる\nかい？　ありがとう\n一人では真実が重荷に\nなるときもあってね", 2, 9552, 1, 101, 4, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何でも話してほしい\n分かち合いたいんだ\n喜びも悲しみも、君が\n背負う、なにもかも", 2, 9553, 1, 102, 8, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう！　聖職者は\n早起きなのさ♪\nふわぁ…はっ、今の\nあくびは見てないね？", 2, 9554, 1, 1, 1, 137401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日のお昼は…\n一緒に台所で\n作らないかい？\n新婚さんみたいに♪", 2, 9555, 1, 2, 1, 137401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜のお祈りをしよう\n凶悪な事件なんて、\nもう起きないように", 2, 9556, 1, 3, 1, 137401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はあ…ふかふか～…\n堕落してしまいそう…\nなんとも罪なアイテム\nだねえ、これは…", 3, 9558, 1, 2, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいな…♪\n探偵事務所の机に\n置いたら場を和ませて\nくれそうだね", 3, 9559, 1, 3, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はあ…心が落ち着く\nけして、その、小説の\n謎解きにイライラして\nいたわけではないよ？", 3, 9560, 1, 4, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…暖かいね。こんな\n暖かさをあまねく\n世に届けるのが、\n今の私の役目だよ", 3, 9561, 1, 5, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こんなにおいしい\nなんて、きっと重大な\n秘密が隠されているに\n違いないよね！", 3, 9563, 1, 7, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時には推理小説でなく\n教えを説く本もいいね\nちょっとだけ…眠く\nなっちゃうけど…", 3, 9564, 1, 8, 1, 137401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すんすん…\nなんか甘い匂いが\nするよーな？\nどこかなどこかな～", 1, 9568, 1, 1, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お部屋の中、\nいっぱい歩いたよ～\nよーし、今日の訓練\nお～しまいっ♪", 1, 9569, 1, 2, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どうしてドーナツには\n穴が開いてるんだろ？\nカスミちゃーん、\nおしえてーっ？", 1, 9570, 1, 3, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いち、に、さん、し、\nごー、ろく…ナーナ！\nえへへへへ～♪", 1, 9571, 1, 4, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("訓練しなきゃだけど…\nおやつとかゲームとか\nいろいろありすぎて…\nで、でもぉ～っ！", 1, 9572, 1, 5, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここ、騎士ちゃんの\nお部屋って感じする！\nだってすっごく\n安心するもん", 1, 9573, 1, 101, 4, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お耳を澄ませたら～…\n騎士ちゃんの声、\nどこからだって\n聞こえちゃうんだ♪", 1, 9574, 1, 102, 8, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はい、ナーナだよっ\n騎士ちゃんに\nあいさつしてもらうと\n元気が出てくるねっ", 2, 9575, 1, 1, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ナーナの頭の角、\n気になっちゃった？\nさわってもいいよ～", 2, 9576, 1, 2, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ナーナ、ずーっと\nだめだめだったけど…\nいつまでもそれじゃ\nだめだってわかったよ", 2, 9577, 1, 3, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("るんるる～、らら～♪\nあっ、一緒に歌う？\nせーの、らんらら～♪", 2, 9578, 1, 4, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねぇ騎士ちゃんっ\n今日も一緒に\nおでかけしようよ！\nどこへ行こっかな～♪", 2, 9579, 1, 101, 4, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルのごはん、\nどれもおいしいけど…\n一番はやっぱり\n騎士ちゃんのごはん！", 2, 9580, 1, 102, 8, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよ～っ！\nおっきな声で\nあいさつすると\n気持ちいいよね♪", 2, 9581, 1, 1, 1, 136201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ごはんの時間だ！\nサクサクドーナツと\nもちもちドーナツ、\nどっちにしようかな～", 2, 9582, 1, 2, 1, 136201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うーん、眠くなって\nきちゃった…\nみんなはまだまだ\n夜ふかしするの～？", 2, 9583, 1, 3, 1, 136201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("訓練の後はちゃんと\n休むのが大事だよ\n…ナーナはいつも\n休んでるけどっ…", 3, 9585, 1, 2, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたもナーナの\nお友達になっちゃお？\n「ウン、イイヨ！」\nやったぁ～♪", 3, 9586, 1, 3, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい匂～い♪\nこの匂いつけたら\nナーナもお洒落さんに\nなれるかな～", 3, 9587, 1, 4, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～、あったかーい♪\nあっでも、お耳が\n焦げないように\n気をつけなきゃ…！", 3, 9588, 1, 5, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いくら食べても\nなくならないなんて…\nすごすぎるよぉ～っ！\n絶対ふとっちゃう～！", 3, 9590, 1, 7, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("むずかしそーな本だ！\nふむふむどれどれ…\nうん、むずかしい！", 3, 9591, 1, 8, 1, 136201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスの時期は\nやりたいことが\nたくさんあって…\n忙しいけど楽しいね", 1, 9595, 1, 1, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんながウキウキ\nしてるの、\n伝わってくるな♪", 1, 9596, 1, 2, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("思い切っておしゃれ\nしてみたけど…\nちょっと照れちゃう", 1, 9597, 1, 3, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誘惑に負けて\n限定のスイーツセット\n買っちゃった…！", 1, 9598, 1, 4, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("帽子だけでも、\n印象が変わるんだよね\n新しい自分に\nなれたかな♪", 1, 9599, 1, 5, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔物のお料理…\nわたしも騎士クンに\n教えてもらおうかな…", 1, 9600, 1, 101, 4, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クンの温もりが\n恋しくなっちゃうのも\n寒い冬だから…だよね", 1, 9601, 1, 102, 8, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大人っぽいコーデで、\nちょっと背伸びした\n気分…なんてねっ♪", 2, 9602, 1, 1, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度一緒に\nお出かけしようよ\n騎士クンのお洋服\n選んであげるから", 2, 9603, 1, 2, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度はここで\nパーティーしようよ\nきっと楽しいから", 2, 9604, 1, 3, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("風邪には気をつけてね\nわたしが温めてあげ…\nな、なんでもない！", 2, 9605, 1, 4, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒にゆっくり\nおしゃべりしよう？\nいくらでも付き合うよ", 2, 9606, 1, 101, 4, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士クン、\nぎゅーってさせて？", 2, 9607, 1, 102, 8, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう♪\n昨夜はわたし、\n騎士クンと夢の中でも\nデートしちゃった", 2, 9608, 1, 1, 1, 136401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ごはんの代わりに\nケーキは\nさ、さすがに\nいけないよね？", 2, 9609, 1, 2, 1, 136401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あのね、一緒に\n夜更かし、しない？\n今夜だけ…ね？", 2, 9610, 1, 3, 1, 136401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん～、気持ちいい\nよかったら騎士クンも\n一緒に…", 3, 9612, 1, 2, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬいぐるみも\n楽しそうっ\nふふっ、かわいい♪", 3, 9613, 1, 3, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アロマオイルとかも\nプレゼントの定番\nだよね…", 3, 9614, 1, 4, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冷えた体が\nあったまって…\nね、眠くなっちゃう…\nふわぁ…", 3, 9615, 1, 5, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛情のこもった\nお料理って、\nいくらでも\n食べられちゃう…！", 3, 9617, 1, 7, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夢占いかぁ…\n昨夜の夢は、\nどんな意味なんだろ？\n…えぇっ、そんな…！", 3, 9618, 1, 8, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次のプレゼントは\nこういう本もいいかも\n騎士クンも\n喜んでくれそう…♪", 3, 9622, 1, 14, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわもこだけど、\n動くのは大変っ…", 3, 9623, 1, 15, 1, 136401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今からギルドハウスを\nクリスマス風に改造\nしちゃいます♪\nイイコトですよね★", 1, 9624, 1, 1, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ええっと…飾りつけを\nするには、まず\nテレポーテーションで\nツリーをもってきて…", 1, 9625, 1, 2, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスとはずっと\n無縁な人生でしたし\n普通にそれっぽいコト\nしてみたいですねー", 1, 9626, 1, 3, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おうちでまったりも\nイイカンジです★\nあまーいココアでも\n淹れてみましょうか", 1, 9627, 1, 4, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ケーキを食べ過ぎると\nいつかのユイさん\nみたいになっちゃう\nので要注意ですね★", 1, 9628, 1, 5, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんは他の子と\nクリスマスデート中\nなんですかねー？\n邪魔しにいこうかなー", 1, 9629, 1, 101, 4, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士さんと\nクリスマスデート…\nふふっ、考えると\nニヤニヤしちゃいます", 1, 9630, 1, 102, 8, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、騎士さん\nお邪魔してまーす★\nクリスマスも一緒に\nイイコトしましょうか", 2, 9631, 1, 1, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("外が寒すぎなので\n今日はイイコトクラブ\nも休部中ですよ★\nゆっくりしましょう♪", 2, 9632, 1, 2, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この衣装ふわふわして\nついつい触りたく\nなっちゃいますよね？\n好きなだけイイですよ", 2, 9633, 1, 3, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この白い衣装を血で\n真っ赤に染め上げる\n…なーんて事件は\n起きませんよ、多分", 2, 9634, 1, 4, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クリスマスプレゼント\nのお届けでーす★\nプレゼントはもちろん\nわ・た・し、ですよ♥", 2, 9635, 1, 101, 4, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このギルドハウスは\nキスをしないと出られ\nないみたいですねー\n騎士さんどうしましょ", 2, 9636, 1, 102, 8, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うぅ～、寒さで\n目が覚めちゃいました\n風邪引きたくないので\nぎゅっ★　しますね♪", 2, 9637, 1, 1, 1, 136301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと気分転換に\n散歩でもいきますか\n雪が積もっていたら\n雪だるま作りましょう", 2, 9638, 1, 2, 1, 136301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("サンタさんがそろそろ\n来る時間ですかね？\nやることやってベッド\nにいきましょうか★", 2, 9639, 1, 3, 1, 136301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…\n聖夜騎姫★\nチャーミングスカイも\n充電が必要なんです", 3, 9641, 1, 2, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぺんぽこりんはクビで\nこの子を戦わせるのも\nアリですね★\n壊れちゃいますけど♪", 3, 9642, 1, 3, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…イイ香り♪\nクリスマスに\nピッタリですね", 3, 9643, 1, 4, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかーい♪\nもうここから\n動けないですー", 3, 9644, 1, 5, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これだけ食べたら\n冬眠もできそうです\n春になったら\n起こしてくださーい♪", 3, 9646, 1, 7, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("へー、クリスマス\nケーキの作り方…\nランファさんにも後で\nシェアしてみますか", 3, 9647, 1, 8, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あはっ、イイですねー\nバイオレンスな展開\nはなくてもちゃんと\n面白くなるんですね★", 3, 9651, 1, 14, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こうして遊んでいると\nぺんぽこりんの\n着ぐるみもほしく\nなっちゃいます♪", 3, 9652, 1, 15, 1, 136301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お父さまのような\n威厳のある佇まいを\n心がけたいものです", 1, 9653, 1, 1, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見慣れた部屋が\n少し小さく感じます\nこの体の感覚にも\n早く慣れなければ…", 1, 9654, 1, 2, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…おや？\n以前は見えなかった\n高いところの埃が…\nすぐに対処いたします", 1, 9655, 1, 3, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わんわんの主さまも\n驚いたご様子でした\n人の成長は早いものと\n思われたでしょうか…", 1, 9656, 1, 4, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すらりとした長い足…\n自分のものと\n分かっていても、つい\n見つめてしまいます…", 1, 9657, 1, 5, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまのために\nできることも\n増えました…\nふふ、胸が躍ります", 1, 9658, 1, 101, 4, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたくしの願いは、\n主さまと共にあること\nいわば、生涯を\n添い遂げるように…", 1, 9659, 1, 102, 8, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新たな姿でも変わらず\nおはようから\nおやすみまで\nお供いたしますよ", 2, 9660, 1, 1, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("装いも、大人の体に\n相応しいものに…\nエレガントさを\n心がけてみました", 2, 9661, 1, 2, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昨日の買い出しでは\n少々買いすぎましたが\n大荷物でも平気でした\nすばらしいです…♪", 2, 9662, 1, 3, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("主さまのための\n大事な体ですからね\n長い髪の手入れも\n念入りにいたします", 2, 9663, 1, 4, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本日の添い寝は\n大人と子ども、\nどちらの姿に\nいたしましょうか", 2, 9664, 1, 101, 4, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたさま…\nあぁいえ、その…\n少し違う呼び名を\n試してみようかと", 2, 9665, 1, 102, 8, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n主さまとのご挨拶で\n始まる一日…\nワクワクいたします", 2, 9666, 1, 1, 1, 137601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おや、もうお昼時…\nお腹の空き具合が\n違うと、少々感覚が\n鈍ってしまいますね", 2, 9667, 1, 2, 1, 137601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おやすみの際には\nわたくしの子守唄を…\n安眠の力も以前より\n増しておりますよ♪", 2, 9668, 1, 3, 1, 137601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつでも主さまに\n尽くせるよう、\n体を休めることも\n大事です…ふぅ", 3, 9670, 1, 2, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("愛らしいものを\n慈しむ心は、\n大人になっても\n変わりません…", 3, 9671, 1, 3, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大人の体になると、\n匂いの感じかたも\n少し変わるような…？\n不思議なものです", 3, 9672, 1, 4, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("手足が冷えないよう\nしっかり温めて…\n冷え性は大人の悩みと\n伺いましたので", 3, 9673, 1, 5, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("胃のほうも、前より\n大きくなった模様です\n手が止まりません…\nもぐもぐ…", 3, 9675, 1, 7, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("久々に、主さまに\n本の読み聞かせを\nしましょうか\nふふ、楽しみです", 3, 9676, 1, 8, 1, 137601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんは何が好きかな\n縁起物がいっぱいの\nおせち料理を\n食べてほしいんだよね", 1, 9682, 1, 1, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと…帯がきつい\nかも…おせち料理の\n食べすぎかな？\n気を付けなくちゃ", 1, 9683, 1, 2, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("初日の出は見なくちゃ\n新しい一年の始まりを\n告げるお日さまに\n挨拶しておきたいし", 1, 9684, 1, 3, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("甘酒って不思議…\nすっごく寒い日に\n飲むと、もっと\nおいしくなるんだもん", 1, 9685, 1, 4, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("着物のお姉ちゃん♪\nいつもとは違う格好で\n弟くんをドキドキ\nさせちゃおっと♪", 1, 9686, 1, 5, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うふふ…弟くんの寝顔\nかわいかったなぁ♪\nもはや国宝級だよ！", 1, 9687, 1, 101, 4, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんの着物姿、\nかっこよかった～♪\nはぁぁ…思い出したら\nドキドキしてきた…♪", 1, 9688, 1, 102, 8, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の着物が気になる？\n触ってもいいよ\n肌触りがよくって、\n着心地も最高なんだ～", 2, 9689, 1, 1, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("初詣に行くときは手を\n繋ごうね。人混みの\n中ではぐれたりしたら\n大変だもんっ", 2, 9690, 1, 2, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("叶えたいことが\nあったら言ってね？\nお姉ちゃんが全力で\n協力するから！", 2, 9691, 1, 3, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月は一緒に\n過ごしてお買い物も\nして…ラブラブな\n時間を楽しもうねっ♪", 2, 9692, 1, 4, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…大好きだよ、弟くん\nふふっ、急にごめんね\nどうしても今、伝えた\nいって思っちゃったの", 2, 9693, 1, 101, 4, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弟くんにもらった指輪\n宝物だよ♪　だけど\nいつか本当の新婚さん\nになりたいな…♪", 2, 9694, 1, 102, 8, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月の朝は空気が\n冷たいよね。こんな\nときは、太陽の光を\n浴びながらお散歩しよ", 2, 9695, 1, 1, 1, 136501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼はお雑煮！\n出汁も具材も\nこだわったから、\n楽しみにしててね♪", 2, 9696, 1, 2, 1, 136501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ寝よっか？\nそうだ、添い寝をして\nあげる！　寒いとなか\nなか寝付けないでしょ", 2, 9697, 1, 3, 1, 136501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("座り方には気を付け\nないと。きれいな\n着物に、しわは作り\nたくないもんね", 3, 9699, 1, 2, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわふわでかわいいね\nこの子たちも、\n弟くんとの生活、\nお祝いしてくれてる？", 3, 9700, 1, 3, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん…神社のお香\nみたい♪　いいこと\nありそうな気が\nしてきたよ", 3, 9701, 1, 4, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寒い日に暖炉はありが\nたいな～♪　ここで\nお餅を焼けば、お腹も\n膨れて一石二鳥かも♪", 3, 9702, 1, 5, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹いっぱい…でも\nまだ食べたい！　う～\nこれじゃ、正月太りへ\nまっしぐらだよ～", 3, 9704, 1, 7, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ラブラブだけじゃなく\nもくもくと一緒に本を\n読むのもいいよね♪\nお正月は時間もあるし", 3, 9705, 1, 8, 1, 136501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『囲い完全』の絵馬を\n吊るしてきました！\nこれで家の中は\nもう大丈夫ですね！", 1, 9711, 1, 1, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("正月遊びも雪遊びも\n全部やりたいです！\nえへへ、ちょっぴり\n欲張りでしょうか？", 1, 9712, 1, 2, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マスターから\nお年玉貰えましたー！\n何に使おうか\n迷っちゃいますね～♪", 1, 9713, 1, 3, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ついだらっとしちゃう\nお正月だからこそ！\n楽しかったって言える\n思い出を作るんです♪", 1, 9714, 1, 4, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おせち♪　おせち♪\n中でも昆布と数の子が\n好きなんですよ～♪", 1, 9715, 1, 5, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今年の恋愛運は大吉♪\n一歩踏み出すチャンス\n絶対逃さずに\n掴み取りますよ～！", 1, 9716, 1, 101, 4, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっそりポストに\nお兄ちゃんへの\n年賀状を投入☆\nいつ気付くかな～♪", 1, 9717, 1, 102, 8, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お正月の初夢は…\n一兄二姉三マスター\nでした！　縁起が\nいいです♪", 2, 9718, 1, 1, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃん、お餅つき\nしませんか？\n兄妹のチームワークで\n沢山作りますよ！", 2, 9719, 1, 2, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さむ～い…\n…お兄ちゃん、\nポケット失礼しますね\n…えへへっ♪", 2, 9720, 1, 3, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お掃除はお任せあれ！\n頼りになる妹目指して\nお手伝いしますよー！", 2, 9721, 1, 4, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄ちゃんと過ごす\nお正月は毎年\n大大吉ですよ☆", 2, 9722, 1, 101, 4, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寒いなら\n私が妹ゆたんぽに\nなってあげますよ♪\nぎゅってして下さい☆", 2, 9723, 1, 102, 8, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("朝ごはんにお雑煮は\nどうですか？\nマスター秘伝のレシピ\nアレンジしてみました", 2, 9724, 1, 1, 1, 137901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼になっても\nお正月は冷えますね～\n一緒にこたつに入って\nぬくぬくしませんか？", 2, 9725, 1, 2, 1, 137901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もう寝る時間ですね～\nお兄ちゃんも\nいい初夢が\n見られますように♪", 2, 9726, 1, 3, 1, 137901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん…\nあ、ここちょっとだけ\nお兄ちゃんの匂いが…\nくんくんくんくん…", 3, 9728, 1, 2, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子たちにも\n初日の出を見せて\nあげたいですね～♪\n連れていけるかな？", 3, 9729, 1, 3, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これがお兄ちゃんの\n好みの香りですね\nメモしておきましょう", 3, 9730, 1, 4, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こう暖かいと\nだんだん眠く…\nふわぁ～…", 3, 9731, 1, 5, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしい～☆\nでも、着物の時は\nちゃんと抑えめに\nしておかないと…！", 3, 9733, 1, 7, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『黎明界完全攻略本』\n作って入れておいたら\n誰かの役に立つ日が\n来るかも…？", 3, 9734, 1, 8, 1, 137901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冥界ではないのに\n落ち着きますわ\n騎士様の気配が\nあるからでしょうか…", 1, 9740, 1, 1, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("普段食が細いせいか\n少し食べすぎると\nすぐ体重が…気を付け\nなくてはいけませんね", 1, 9741, 1, 2, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ジオ・テオゴニアには\nお菓子の城があるとか\n本当に童話のようです\n想像が膨らみますわ", 1, 9742, 1, 3, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("刺激的な料理の数々\nジオ・ゲヘナの強さは\nきっと食生活の影響も\n大きいのでしょうね", 1, 9743, 1, 4, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルの魚は大き\nくて活きが良いとか\n釣り…わたくしでも\nできるでしょうか？", 1, 9744, 1, 5, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("解決すべき問題は沢山\nありますが、騎士様と\n共に、乗り越えられる\nと信じておりますわ", 1, 9745, 1, 101, 4, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この装い…風が吹くと\nすぐ裾がめくれて…\n騎士様に見られたら\n大変です…！", 1, 9746, 1, 102, 8, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魚の捌き方なら\nおまかせください♪\n体が覚えるまで何度も\n練習しましたから", 2, 9747, 1, 1, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("料理の楽しさを知って\nしまいました…♪\n大切な人と食卓を共に\nする、その尊さも…", 2, 9748, 1, 2, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("手、ですか？\nばんそうこうだらけで\nお恥ずかしいですが…\nこれも勲章です", 2, 9749, 1, 3, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本日は視察の公務が\nありまして。あの…\n騎士様。一緒に来ては\nいただけませんか…？", 2, 9750, 1, 4, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べた人の服が\n弾けないように\nするにはどうしたら\n良いのでしょうか…", 2, 9751, 1, 101, 4, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("料理の道は一日にして\n成らず…日々の精進で\n騎士様に飽きられない\n味を目指します…！", 2, 9752, 1, 102, 8, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n清々しい朝ですね…♪\nっくしゅん！　肌寒い\nのは困りものですが…", 2, 9753, 1, 1, 1, 138001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼を食べたら一休み\nいたしましょう\n騎士様と共に過ごす\n時間が幸せです…♪", 2, 9754, 1, 2, 1, 138001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士様、お夜食は\n必要ですか？\n練習で作ってみたので\nその…よければ…", 2, 9755, 1, 3, 1, 138001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ…身も心も\n溶けてしまいそう…♪\nこの姿は、他の誰にも\n見せられませんね", 3, 9757, 1, 2, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なんて愛らしい…♪\n霊獣たちの仲間に\n迎えられたりしない\nでしょうか…♪", 3, 9758, 1, 3, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("落ち着きますわね…\n心を静める香りに\n今は少しだけ\n心をゆだねましょう", 3, 9759, 1, 4, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら？　一緒にいた\nあの子たちはどこに…\n…もしかして乾燥や\n蒸発が怖いのかしら", 3, 9760, 1, 5, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美味しい…♪\n作り手の真心を\n感じますわね\nもう一ついただきます", 3, 9762, 1, 7, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルの料理…\nレシピがあれば、\nわたくしにも作れる\nでしょうか…？", 3, 9763, 1, 8, 1, 138001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("万博の余韻に\n心がふわふわとして…\nいつもより浮いて\nしまっているかも…♪", 1, 9769, 1, 1, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルはまるで\nペコリーヌ姫のよう\n国民を見れば彼女の\n人柄が感じられます", 1, 9770, 1, 2, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マスコットキャラ…\nわが国でも導入すべき\nでしょうか。クルルに\n相談してみましょう", 1, 9771, 1, 3, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("後腐れのない\n公平な勝負であれば\n全力で臨みますよ\nふふ、腕が鳴ります", 1, 9772, 1, 4, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弱気になったとき、\n身近な人の存在が、\nわたしに前を向かせる\n力をくれるのです", 1, 9773, 1, 5, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お菓子を食べたときの\n笑顔が見たくて\nお菓子を作っているの\nかもしれません", 1, 9774, 1, 101, 4, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("種族も、生まれすら、\n世界が違っても、\nわたしたちはきっと\n心を通わせられます", 1, 9775, 1, 102, 8, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("信じていますからね、\n騎士？　もしめくろう\nとしたら…天罰です♪", 2, 9776, 1, 1, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("意外と力はあるんです\nよ。お菓子作りに力は\n必要なので。試しに\n腕相撲をしてみます？", 2, 9777, 1, 2, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気分転換に部屋の模様\n替えをしませんか？\nジオ・テオゴニア風に\nお菓子の家具とか♪", 2, 9778, 1, 3, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お茶にしましょうね\n先日採ったはちみつ、\n持ってきたんです♪\n何杯入れますか？", 2, 9779, 1, 4, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食べたいお菓子は\nありますか？\nいつでも作りますよ\nお礼は笑顔で十分です", 2, 9780, 1, 101, 4, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなた…ふふっ♪\nすみません、なぜだか\nそう呼んでみたく\nなったんです…♪", 2, 9781, 1, 102, 8, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわふわパンケーキに\nハチミツをたっぷり…\n朝食がまだなら一緒に\nいかがですか？　騎士", 2, 9782, 1, 1, 1, 138101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼はハニートースト\nです♪　甘いものを\nたくさん食べて、午後\nもがんばりましょう", 2, 9783, 1, 2, 1, 138101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夕飯はドーナツです\nそれも食べ放題♪\nお腹いっぱいになる\nまで食べてくださいね", 2, 9784, 1, 3, 1, 138101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腰を下ろす時間も必要\nですね。浮いていては\n大事なことを見逃す\nかもしれませんから", 3, 9786, 1, 2, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見た目のかわいらしさ\n触れたときの柔らかさ\nお菓子と同じ、調和が\n大切ですね…♪", 3, 9787, 1, 3, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("素敵な香りですね…\n今日のティータイムは\nこの香りに合う\nお菓子を出しますね", 3, 9788, 1, 4, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたたかいと、安心感\nで、つい…まだ秘密に\nするはずの気持ちも\n話してしまいそうです", 3, 9789, 1, 5, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食は人を幸せにします\n…とはいえ、食べすぎ\nには注意、ですね", 3, 9791, 1, 7, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『アストルムの珍味\n100選』？　これは\n興味深い…甘いものも\nあるでしょうか？", 3, 9792, 1, 8, 1, 138101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦を忘れ、我が家にて\n憩ふ時こそ至高也\nゆるりゆるりと…♪", 1, 9798, 1, 1, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("美食巡りし冒険\n御暇なる折にでも\nお聞きしたくありんす", 1, 9799, 1, 2, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("身丈異なれば\n見ゆるものも異にして\n趣深く候。騎士殿の\n御顔も近うなれば…♪", 1, 9800, 1, 3, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ランドソルの食の祭典\n煮炊きの技を競うとは\n新奇なる験。大変\n美味しゅう御座んした", 1, 9801, 1, 4, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("種種様様なる国の御饗\n正しく千差万別也\n腹が千切れる程味わい\nましょうぞ、騎士殿や", 1, 9802, 1, 5, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("他者に信を置くは\n思いの他に至難極みて\n難しきこと也", 1, 9803, 1, 101, 4, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士殿は只在るが侭に\nその御身体も御心も\nわっちが身命を賭して\n御守りします故", 1, 9804, 1, 102, 8, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いけませぬ、騎士殿や\n今のわっちが如何に\n『ないすばでぃ』と\nいえど戯れは程々に♪", 2, 9805, 1, 1, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食を求めし旅路\nわっちを連れ給はんや\n騎士殿や？", 2, 9806, 1, 2, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よき縁こそ\n万事に代えべからざる\n至宝なりけり", 2, 9807, 1, 3, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("此の装束の生地は\n最上の膚触りに候\n騎士殿であれば\n撫で給へど苦しからず", 2, 9808, 1, 4, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("時には媛としての\n公の事を離れ\n羽を伸ばすも一興\nさ、参ろうぞ騎士殿や", 2, 9809, 1, 101, 4, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士殿や\nもっと御傍に\n─コロコロコロ\n愛い顔でありんすの", 2, 9810, 1, 102, 8, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一日の計は朝に\nありと申しんす\n御目覚めのほどは\n如何かえ騎士殿や", 2, 9811, 1, 1, 1, 138201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はや昼時を迎え候\n共に昼餉の支度を\nしませむか", 2, 9812, 1, 2, 1, 138201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("宵の明くるまで\n起き明かすは体に毒\n我が身を労わりて疾く\nお休みくだしゃんせ", 2, 9813, 1, 3, 1, 138201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("実に優れたる座し心地\nわっちの蛇も\n僻みてしまうやも\nしれませぬ喃", 3, 9814, 1, 2, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どれ\n稚児らの土産に\n斯様が如き玩具でも\n買うて帰りましょうや", 3, 9815, 1, 3, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ…此の香り\n鬼岩城砦の薫物として\n取り入れたく候", 3, 9816, 1, 4, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暖かき心地も\nジオ・ゲヘナの地に\n住まえば清新とすら\n覚えまする", 3, 9817, 1, 5, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("斯様な佳肴も\n皆で食してこそ\n味わい際立つもので\nありんしょう", 3, 9818, 1, 7, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("異なる国々の\n『れしぴ』を蒐集し\nモネらに振る舞うも\n一興やもしれぬ喃", 3, 9819, 1, 8, 1, 138201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この国の矜持は\nユースティアナの\n矜持でもあります！", 1, 9820, 1, 1, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹も心もいっぱい！\n今なら書類も、完璧に\nこなしてみせますよ\n…たぶん…", 1, 9821, 1, 2, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("至高のおにぎり…\n考えるだけで\nお腹がペコペコに…", 1, 9822, 1, 3, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みなさんがわたしを\n想ってくれたように\nわたしの想いも\n伝えていきたいです", 1, 9823, 1, 4, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みなさんから\nお預かりした力…\n大切に使いますね", 1, 9824, 1, 5, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("えへへ☆\nお腹が空くって\n幸せなことですね！", 1, 9825, 1, 101, 4, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人がにぎって\nくれたおにぎり…\nまた食べたくなって\nきちゃいました☆", 1, 9826, 1, 102, 8, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日はどんな食卓に\nしましょうか？\n幸せなごはん、\nたくさん作りましょう", 2, 9827, 1, 1, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("料理が愛で\nできているように、\nわたしの体も愛で\nできているんですよね", 2, 9828, 1, 2, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("覚醒とは関係なく\nあなたのおにぎりを\nお腹も胸も弾けるほど\nいっぱい食べたいです", 2, 9829, 1, 3, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誰にも奪わせない…\nわたしの決意が\n女神アストライアに\n伝わったんでしょうか", 2, 9830, 1, 4, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと半分こした\nあのおにぎりは\n幸せの味がしました☆\nごちそうさまです♪", 2, 9831, 1, 101, 4, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたと食卓を囲う\n幸せ…あの日常が\nあるから、今日の\nわたしも元気です☆", 2, 9832, 1, 102, 8, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹がペコペコで\n目が覚めちゃいました\nあなたもですか？\nおそろいですね☆", 2, 9833, 1, 1, 1, 138301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("矜持だけでは\nお腹は膨れません…\nということでランチ♪\nあなたもどうですか？", 2, 9834, 1, 2, 1, 138301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ寝る準備を…\nの前に、お夜食です☆\nあなたとゆっくり、\nおしゃべりしながら…", 2, 9835, 1, 3, 1, 138301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プリンセスにも\n休憩は必要\nですよね～…", 3, 9837, 1, 2, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいくて\n食べちゃいたい…\nもちろん冗談ですよ～", 3, 9838, 1, 3, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はわわ～…\nいい香りでお腹も\nグーって言ってます…", 3, 9839, 1, 4, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～♪\nぬくぬくですね…\nあの人もいたら\nもっとぬくぬくなのに", 3, 9840, 1, 5, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はむはむはむ…♪\nお腹が空くって\n幸せですね☆", 3, 9842, 1, 7, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『この大陸には\n星の女神の名が\n与えられた』って\n書いてありますね", 3, 9843, 1, 8, 1, 138301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士きゅんのために\nスライム風呂でも\n用意しとくか～", 1, 9849, 1, 103, 12, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おねえちゃんの肌\nぷるっぷるっしょ～？\n触ってイイよ～♡", 2, 9850, 1, 103, 12, 123301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この水着どうですか？\n黒、なんて…大胆？\n背伸びしすぎたかも…", 1, 9851, 1, 1, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お尻を鍛えたせいで\nちょっとムチムチに…\n元からじゃないですっ", 1, 9852, 1, 2, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着を着てるうちに\nバンディシャーク号の\n洗車やっちゃおうかな", 1, 9853, 1, 3, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("真冬はサマー！\n…考えたひとは\n悪魔だと思ってます…\n真冬は真冬です…", 1, 9854, 1, 4, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("常夏のリゾート\nメリゾでのんびり…\nとっても楽しかったな\nまた行きましょうね", 1, 9855, 1, 5, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ずっと水着でいると\n感覚が麻痺してきて…\nお尻を突き出すのも\n慣れちゃって…はぅぅ", 1, 9856, 1, 101, 4, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("せっかくの水着だし\n今度は海にいきたいな\nもちろん騎士さんと\n一緒に…えへへ♪", 1, 9857, 1, 102, 8, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("買い物してたら\n決勝見ましたって人に\n握手をせがまれて…\nわたしって、有名人？", 2, 9858, 1, 1, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("修行したおかげで\nたくさん洗い物しても\n腰が痛くないんです！", 2, 9859, 1, 2, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("伝説の桃闘者…\nそれが、わたし？\nで、伝説のままで\nいいんじゃないかな…", 2, 9860, 1, 3, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ウォータースライダー\n一緒に滑りましょう\n泳げなくても大丈夫\nわたしが支えますから", 2, 9861, 1, 4, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたしのお尻、\n『桃尻』らしいけど…\n褒められてるのかな？\n自分じゃ見えないし…", 2, 9862, 1, 101, 4, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("尻文字であいうえお…\n特訓で繰り返したから\n今でも勝手にお尻が\n動いちゃう…", 2, 9863, 1, 102, 8, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます！\n朝ごはんできてますよ\nあまーい卵焼きです", 2, 9864, 1, 1, 1, 138701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼は何つくろう…\n朝の残りの卵を使って\nオムライスとか？", 2, 9865, 1, 2, 1, 138701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泳ぎ疲れた時は\n早めに寝るのが一番\nお布団ひきますね", 2, 9866, 1, 3, 1, 138701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こういうの\nバンディシャーク号\nにも置きたいな…", 3, 9868, 1, 2, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かわいいけど\nいざ買うってなると\nそのお金でおかずを…\nって考えちゃうなあ", 3, 9869, 1, 3, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カレーのアロマって\nないのかな…？\n食欲増進によさそう？", 3, 9870, 1, 4, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はあ…暖かい…\n雪山での特訓は\nつらかったなぁ…", 3, 9871, 1, 5, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("無限キャベツは\n作ったことあるけど\nこれは太りそう…\nでも、止まらない～", 3, 9873, 1, 7, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スポーツ選手名鑑に\nワカナって載ってる！\nミフユコーチ、\n仕事速すぎっ！", 3, 9874, 1, 8, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい乗り心地\nスパイクちゃん達より\n速いのかな…？", 3, 9876, 1, 10, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この貝の中に入って\nじっとしてたら\nいつかわたしも\n輝く真珠に…？", 3, 9877, 1, 11, 1, 138701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着を着てると、\nいつもより少し大胆に\nなれる気がする…", 1, 9880, 1, 1, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やってみたいこと、\nいろいろ増えたなぁ\nあの人もきっと\n応援してくれるよね", 1, 9881, 1, 2, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法のお尻、\nピュアリーピーチっ\n…す、すみません\n冗談です", 1, 9882, 1, 3, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("防水加工したら、\nプールでも読書できる\nよね。ぷかぷか浮いて\n読書なんて…素敵だな", 1, 9883, 1, 4, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("濡れた耳や尻尾は\nしっかり乾かして…\n毛並みが乱れちゃうと\n直すのが大変", 1, 9884, 1, 5, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人のお尻は\nどんな感じなんだろ…\nはっ、私ったら\nいったい何を…？", 1, 9885, 1, 101, 4, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("強くなればその分、\nあの人の隣で戦える\n最強の桃闘者として…\nは、やめておこう…", 1, 9886, 1, 102, 8, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昨日、買い物中に\n声をかけられたんです\nもしかして私、\n有名人になってる…？", 2, 9887, 1, 1, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着で過ごしてると\n動きやすくていいな～\nなんて思っちゃいます\n慣れって怖いですね", 2, 9888, 1, 2, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腕も脚も、前より\n力がついてると\n思うんです\n…触ってみます？", 2, 9889, 1, 3, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("特訓の成果で、感覚が\n鋭くなった気がします\nあなたの声も\n聞き逃しませんよ", 2, 9890, 1, 4, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの、その…\n私のお尻、あなたも\n魅力的だって\n思いますか…？", 2, 9891, 1, 101, 4, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたが何かに\n挑戦するときは、\n私も精いっぱい\nサポートしますっ…", 2, 9892, 1, 102, 8, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n体を動かすと質のいい\n睡眠をとれるみたい\n早起きできましたよ♪", 2, 9893, 1, 1, 1, 138801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ごはん、一緒に\nどうですか？　また\nピーチクラッシュ・\nフェアに行きたくて", 2, 9894, 1, 2, 1, 138801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("寝る前はストレッチ\n一緒にしませんか\nそれともマッサージが\nいいですか？", 2, 9895, 1, 3, 1, 138801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この感触、あの人の\nふくらはぎと同じ…？", 3, 9897, 1, 2, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぬいぐるみさんも、\nヒップレスリングの\n練習してみる？", 3, 9898, 1, 3, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り…\nはちみっさに少し\n似てるような…？\nき、気のせいだよね", 3, 9899, 1, 4, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着で冷えた体が\n温まるの、ほっとする\nこれが冬の醍醐味…？", 3, 9900, 1, 5, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("日々の食事が\n健康な体を作る…\nよく食べてよく鍛える\nそれが全ての基本♪", 3, 9902, 1, 7, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スポーツ名鑑かぁ…\n…えっ、私のことが\nもう載ってる…？", 3, 9903, 1, 8, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい乗り心地だけど…\n夢中になってたら\nニャットちゃんが\n拗ねちゃうかも", 3, 9905, 1, 10, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このクッション、\n気持ちいいなぁ\nこう、お尻にぴたっと\nフィットする感じで…", 3, 9906, 1, 11, 1, 138801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おふくろの味が恋しい\nです…まぁ、キョウカ\nお嬢様のお義母さんの\nことなんですけどね", 1, 9909, 1, 1, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あれ？　もしかして私\nここに入り浸りすぎ？\nもはや地縛霊ですね\n…それも悪くないか", 1, 9910, 1, 2, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("守護騎士をクビに\nなったときはショック\nでしたね。一人きり\nだったらグレてたかも", 1, 9911, 1, 3, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士氏へのお礼にドッ\nキリプレゼントとか\nしたいですね。心臓が\n止まるレベルのやつ", 1, 9912, 1, 4, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よっ、ふっ、はっ！\n…やはり幽霊たるもの\nポールダンスができて\nこそ一人前です", 1, 9913, 1, 5, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヒマです。騎士氏でも\n捕まえてヒマつぶしに\n付き合ってもらうしか\nないですね。騎士氏～", 1, 9914, 1, 101, 4, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士氏の好物を調査\nしておきますか。これ\nから先、まだまだお世\n話になりそうですから", 1, 9915, 1, 102, 8, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私が呪われるのって\nズルくないですか？\nこちとら当たり判定が\n曖昧な幽霊なのに", 2, 9916, 1, 1, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("油断大敵ですよ。いつ\n誰が背後に忍び寄るか\nわかりませんからね\nたとえば私みたいに", 2, 9917, 1, 2, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("立ってる棒を見ると、\nポールダンスができる\nか確かめますよね\n…あれ、私だけ？", 2, 9918, 1, 3, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はーい、ウサギちゃん\nへのお触りは禁止です\nよー。次にやったら\n首ちょんぱでーす", 2, 9919, 1, 4, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("生きる上で知識は必要\n…ということで勉強を\n教えたい気分なので、\nそこに座ってください", 2, 9920, 1, 101, 4, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やはり私を飼いたいの\nでしょう？　罪な女で\nすね私は…糸くずがつ\nいてただけ？　…ちっ", 2, 9921, 1, 102, 8, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("起きていたのですね。\n寝起きドッキリを\n仕掛けようとして\nいたのに。残念無念", 2, 9922, 1, 1, 1, 138901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食を食べずに午後を\n乗り切ろうなんて思わ\nないでくださいね。\n死にたいんですか？", 2, 9923, 1, 2, 1, 138901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここからは大人の\n時間…さっさと\n寝ないと、枕元で\nポールダンスしますよ", 2, 9924, 1, 3, 1, 138901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なかなかのふわふわ\n具合。私のお尻に\nついてるポンポンと\nいい勝負です。やるな", 3, 9926, 1, 2, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴方、ウサギ耳を\nつけてみませんか？\n実は私、仲間を増やし\nたくて暗躍中なんです", 3, 9927, 1, 3, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…キョウカ\nお嬢様たちと過ごした\n家の匂いみたい…安心\nするんですよね何故か", 3, 9928, 1, 4, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一発芸。飛んで火に\n入るウサギちゃん！\nって感じで火に飛び\n込むのウケるかな…？", 3, 9929, 1, 5, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ポールダンスは全身\n運動ですからね。しっ\nかり食べてエネルギー\nを補給しておかないと", 3, 9931, 1, 7, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『ウサギの飼い方』？\n…やはり騎士氏は私を\n飼いたいとか？　一応\n私も読んでおきますか", 3, 9932, 1, 8, 1, 138901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キレイなお洋服です\nからちゃんとお手入れ\nもしないと…よし♪", 1, 9938, 1, 1, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("怖くない幽霊さんも\nいるんですね\n…グレイスさんとか、\nグレイスさんとか…", 1, 9939, 1, 2, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなとお嬢様ごっこ\n楽しかったな\nまたみんなを誘って\nやってみようかな", 1, 9940, 1, 3, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お嬢様の練習\nもう少ししようかな\n…誰も見てないよね？\nおほほ、ほほほほっ♪", 1, 9941, 1, 4, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ネクロマンシーの本\n読んでみようかな\n怖いけど…ゾンビに\n詳しくなれるかも…？", 1, 9942, 1, 5, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの人が執事に\nなってくれたら…\nどんな感じなんだろ？", 1, 9943, 1, 101, 4, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("幽霊になっても\n一緒にいたい人…\n…な、なんで\nあの人の顔が…！", 1, 9944, 1, 102, 8, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日もお勉強手伝って\nくれますか？\nひ、一人でもできます\nけど…ダメですか？", 2, 9945, 1, 1, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("宿題が終わったら\n一緒に遊びましょう\nだからまずはお勉強！", 2, 9946, 1, 2, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度の休みは\n図書館に行きましょう\n静かでいいですよ", 2, 9947, 1, 3, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("手を繋いでください\n鎖の代わりです\n離さないでくださいね", 2, 9948, 1, 4, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鎖がなくたって\nちゃんと面倒見て\nあげます。あなたの\nこと、心配ですから", 2, 9949, 1, 101, 4, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は執事として私に\n付き合ってください\nあ、あくまで\nおままごとですから！", 2, 9950, 1, 102, 8, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい朝ですね\nじゃなかった…\nいい朝ですわね\nおほほほ♪", 2, 9951, 1, 1, 1, 139001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("執事、今日のお昼は\nなにかしら？\nなんて…えへへ♪", 2, 9952, 1, 2, 1, 139001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好なら\n夜更かしも平気…\nん…ふわぁ…", 2, 9953, 1, 3, 1, 139001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("勉強の休憩時間です\nサボりじゃないです\nちゃんと戻ります", 3, 9954, 1, 2, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お揃いのドレスを\n着たらかわいいかも♪\nそしたら一緒に\nお出かけもできそう", 3, 9955, 1, 3, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("青い薔薇の香り\nあったらいいのに…\n探してみようかな", 3, 9956, 1, 4, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぽかぽか優しい温かさ\nだけど、ゾンビは\n腐敗が進んじゃう\nのかな…？", 3, 9957, 1, 5, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…お嬢様は\nきっとにんじんも\nピーマンも優雅に\n食べるはず…っ", 3, 9958, 1, 7, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふしんしゃ取りが\nふしんしゃになる…\n気を付けないと！", 3, 9959, 1, 8, 1, 139001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("覇瞳天星…\n陛下は自在に\n使いこなしてた\nあたしも必ず…！", 1, 9960, 1, 1, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鼻血はもう慣れた…\nって言ったら\n負けな気がする…", 1, 9961, 1, 2, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スズナのメモ\nあたしが言った通りに\n書いてあるのかしら\n全然読めないけど", 1, 9962, 1, 3, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔物レース場で\n魔物が暴走するなんて\n元調教師としては\n見過ごせないわね…", 1, 9963, 1, 4, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("失敗したって凹んで\nられないわ。スズナの\n言う通りこれも一種の\nアオハルなのかもね", 1, 9964, 1, 5, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつの未来にさ\nあたしは…いるのかな\n…いたいな、ずっと", 1, 9965, 1, 101, 4, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつのこと考えると\nこの瞳がなくても\n未来が明るく視える\n…何言ってんのあたし", 1, 9966, 1, 102, 8, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ねえ、一緒におでん\n作りましょ。がんもに\nこんにゃく、大根に卵\nフーフーしてよね？", 2, 9967, 1, 1, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい？　あの水晶玉で\n視たあたしたちの未来\n二人だけの秘密よ？\n絶対よ？", 2, 9968, 1, 2, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日も訓練に行くわよ\n休んだらなまっちゃう\nかもしれないでしょ\n付き合いなさい", 2, 9969, 1, 3, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この瞳の力\nなじんできたかも\nちょっとすごくない？\n褒めていいわよ♪", 2, 9970, 1, 4, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの時は膝枕ありがと\n今度はあたしがして\nあげる。やってほしい\n時に言いなさい♪", 2, 9971, 1, 101, 4, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あんたの未来\nあたしが独占するから\n…覚悟しなさいよ", 2, 9972, 1, 102, 8, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよ\n予知しなくても分かる\n今日はいい日になるわ", 2, 9973, 1, 1, 1, 139101, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹すいたわ～\n訓練三昧でへとへと\nなんか作って…\nメニューはお任せで", 2, 9974, 1, 2, 1, 139101, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("変な夢見そうで\n寝つけないのよ…\n…別に怖くないけど\n…コラ！頭なでんな！", 2, 9975, 1, 3, 1, 139101, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～…\n頭を休ませないと\n予知がブレるのよ", 3, 9976, 1, 2, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつかあいつと一緒に\n住むなら部屋に置いて\nみたり…なんちゃって", 3, 9977, 1, 3, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…\n疲れきった頭に\nすっごく沁みるわ…", 3, 9978, 1, 4, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("温かいと落ち着くわ\n猫の本能ってやつ？\n陛下は…どうなんだろ", 3, 9979, 1, 5, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("鼻血の出し過ぎで\n貧血ぎみだわ…\nもう一個食べとこ…", 3, 9980, 1, 7, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("占い横丁ガイドブック\nランドソルの母特集…\nって、これあたし！？\nいつの間に！？", 3, 9981, 1, 8, 1, 139101, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法の勉強を、もっと\nしたいな。大切な人を\n守るためには、強さと\n知識が必要だから", 1, 9982, 1, 1, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お姉ちゃんが弓を引く\n姿、カッコいいなぁ～\n…あの耳も、すっごく\nかわいいんだよね♪", 1, 9983, 1, 2, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エリカさんはやっぱり\n頼りになるな。仲間と\nしてそばにいてくれる\nと、すごく心強いんだ", 1, 9984, 1, 3, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("学校のみんなに、\nアストルムのことを\n話したら…信じて\nもらえるかな…？", 1, 9985, 1, 4, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔物ってたくさん\n種類があるんだね\nおいしいとか、\nおいしくないとか…", 1, 9986, 1, 5, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この格好、わたしに\n似合ってるかな…？\n学校のみんなが見たら\nびっくりするかも♪", 1, 9987, 1, 101, 4, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒に過ごした時間は\n短いけれど…友だちの\nためなら、いくらでも\nがんばれますっ！", 1, 9988, 1, 102, 8, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの子　会いたや\nあの海越えて…♪\nはっ…もしかして今の\n聞いてました…！？", 2, 9989, 1, 1, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("偶然かもしれないけど\n偶然で終わらせたく\nないんだ。わたしが\nこの世界に来た意味を", 2, 9990, 1, 2, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔物を食べると健康に\nいいのかな？\nなんだか元気が\n有り余っちゃって…！", 2, 9991, 1, 3, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょっと相談に乗って\nもらっていいですか？\nこの世界だからできる\n戦術を相談したくって", 2, 9992, 1, 4, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みんなのこと、知り\nたいです。一緒に戦う\nためだけじゃなくて…\n仲良くなりたいから", 2, 9993, 1, 101, 4, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦車道をやってみませ\nんか？　あなたなら\nきっと立派な戦車道を\n歩めると思うから", 2, 9994, 1, 102, 8, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます！\n寝坊した時は最悪を\n想定しつつ、次はどう\nするかを考えましょう", 2, 9995, 1, 1, 1, 139201, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ごはんは海鮮に\nしませんか？　街を\nお散歩してたらいい\nお店を見つけたの", 2, 9996, 1, 2, 1, 139201, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ眠る時間だね\n演習があってもなく\nても、睡眠はしっかり\nとりましょうね", 2, 9997, 1, 3, 1, 139201, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふか～♪\n車内のクッションに\nこれも足したら\nみんな喜ぶかな♪", 3, 9998, 1, 2, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わ～、かわいい～♪\n戦車の中に置いておい\nたら、ピンチのときに\n落ち着かせてくれそう", 3, 9999, 1, 3, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り～♪　ふふ、\n前に見せてもらった\n生け花を思い出すなあ", 3, 10000, 1, 4, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたたまりながら干し\n芋を焼こうかな。おい\nしい匂いに人が集まっ\nてきちゃったりして♪", 3, 10001, 1, 5, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("世界は違っても、\nおいしいものはたくさ\nんあるんだ♪　いくら\nでも食べられちゃうな", 3, 10002, 1, 7, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("魔法の本は内容が難し\nいけど、ちゃんと読ん\nで、なにができるのか\nを理解しなくっちゃ！", 3, 10003, 1, 8, 1, 139201, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("弓の命中率はまだ上げ\nられる。打てば必中、\nその矜持を返上する\nつもりはないからな", 1, 10004, 1, 1, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("まさか自分に獣の耳が\nあるとはな…慣れると\n便利だが…見た目が\nかわいくて困るな…", 1, 10005, 1, 2, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("世界が変わっても\nわたしがやることは\n変わらない。西住流は\nわたしが守る", 1, 10006, 1, 3, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("積み重ねた訓練が\n裏切ることはない\n自らを信じ、一射に\n魂を込めて放つだけだ", 1, 10007, 1, 4, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("エリカにはもっと自信\nを持ってほしい。わた\nしが信頼を置き指名し\nた次期隊長なのだから", 1, 10008, 1, 5, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ほしいのは勝利のみ\n…だが負けることで\n得られるものもある\n難しいものだな", 1, 10009, 1, 101, 4, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("不確定要素が多い状況\nでなら、みほを隊長に\n推すのは必定。きっと\n力を発揮してくれる", 1, 10010, 1, 102, 8, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("【美食殿】の活動方針\nには共感を覚えるよ\nおいしい食事は、隊の\n士気を左右するからな", 2, 10011, 1, 1, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦車でなく生身で戦う\nとなるとあなたたち\nには遠く及ばない\n今後も精進せねばな", 2, 10012, 1, 2, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この足音は…やはり\nあなたか。マホ姫の\nおかげで、以前よりも\n感覚が磨かれたよ", 2, 10013, 1, 3, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お互い作戦を伝えたり\n指揮をしたり\nする身だ、\n体調には気を付けよう", 2, 10014, 1, 4, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("油断大敵だ。数的有利\nだとしても戦術次第で\n対等に戦えるのだから\n…経験から得た教訓だ", 2, 10015, 1, 101, 4, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あなたの援護には感謝\nしている。想定以上の\n動きができるのは敵に\nとっても脅威だからな", 2, 10016, 1, 102, 8, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう。朝食は\nしっかりとるように\n腹が減っては戦も\n訓練もできないからな", 2, 10017, 1, 1, 1, 139301, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("みほとエリカを誘って\n昼食にするとしよう\n午後も演習があるし…\nここはカレーにしよう", 2, 10018, 1, 2, 1, 139301, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ就寝時間だ\n健康な心身を保つため\nにも、良質な睡眠は\n欠かせない", 2, 10019, 1, 3, 1, 139301, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("休息時間はまだだぞ\nしかし…うう、この\n柔らかさの誘惑には\n抗いがたいな…", 3, 10020, 1, 2, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ…かわいいな\nボコとは違うがみほの\n好みに近い気がする", 3, 10021, 1, 3, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香りだ。戦車で\n走る草原の匂い。土の\n匂い…かすかな火薬の\n匂いもする…", 3, 10022, 1, 4, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたたかい…そして\n熱い。まるで人の心だ\n誰もが胸に炎を抱えて\nいるものだからな", 3, 10023, 1, 5, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("泊りがけの演習に持参\nしたいな…食事が質素\nだと悪い結末になるの\nは歴史が証明している", 3, 10024, 1, 7, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ…この世界にある\n戦術が書かれた本か\n興味深い。熟読させて\nもらうとしよう", 3, 10025, 1, 8, 1, 139301, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("双剣使い…いいわね♪\nわたしの戦場は後方\nではなく前線という\nことなのでしょう？", 1, 10026, 1, 1, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("本来の自分を忘れる\nなんて…不可抗力でも\nあってはならない失敗\nよ…あぁっ、もうっ！", 1, 10027, 1, 2, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("西住隊長がいる。ただ\nそれだけで安心感が\nある。…わたしもそん\nな隊長になりたいな…", 1, 10028, 1, 3, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("元副隊長には絶対に\n負けないわ！　競争\nじゃないし今は仲間\nだけど…それでも…！", 1, 10029, 1, 4, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("双剣の手入れをして\nおこうかしら。今の\nわたしの相棒は、\nこの剣なんだもの", 1, 10030, 1, 5, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハンバーグは…いいわ\n肉肉しさとジューシー\nな味わいが、わたしに\nパワーをくれるのよね", 1, 10031, 1, 101, 4, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("相手が誰だろうと\n無様な姿は見せないわ\nそれが私の果たすべき\n責務でしょう？", 1, 10032, 1, 102, 8, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたしがキャルと\n似てる…？\nそんなことないわよ！\n…そうでしょ？", 2, 10033, 1, 1, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この世界に来られて\n一応感謝してるのよ\n代え難い経験を\nさせてもらったもの", 2, 10034, 1, 2, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("士気の維持は、みんな\n苦労するのよ。でも、\nあなたはやってのける\n…すごいわ、本当に", 2, 10035, 1, 3, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クローチェさんって\n面白い人よね。また\nアイアシェッケを\n採りにいきましょ", 2, 10036, 1, 4, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誰にでも力になりたい\n人はいるわ。わたしに\nも、あなたにも。お互\nい、がんばりましょう", 2, 10037, 1, 101, 4, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("これだけ長く離れて\nいたからこそ…次に\n乗る時はもっと戦車道\nを突き詰められそうよ", 2, 10038, 1, 102, 8, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう。朝食は必ず\n食べなさいよ。食事は\n一日の基本だもの\nなにをするにもね", 2, 10039, 1, 1, 1, 139401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("昼食もだけど、休憩も\n忘れてはだめよ。少し\n眠ると訓練の質が\nあがるのよ…ふわぁ…", 2, 10040, 1, 2, 1, 139401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ寝たほうが\nいいわ。今日の疲れを\n明日に持ち越すのは\n愚者のすることよ", 2, 10041, 1, 3, 1, 139401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふかふか…たまらない\nわね…疲れてるときに\n横になったら、逃げ\nられない気がするわ", 3, 10042, 1, 2, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("守るものがあると人は\n強くなれることもある\n…あなたには我が隊に\n入る許可を与えるわ", 3, 10043, 1, 3, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はぁ～…心が落ち着く\nいい匂い…エルフの里\nに流れる空気を\n思い出す爽やかさだわ", 3, 10044, 1, 4, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見ていると心が穏やか\nになるわ…ケンカした\n相手とも素直に\nなれたりするかしら", 3, 10045, 1, 5, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしいものが無限に\n出てくる？　なんて\n恐ろしいものを置いて\nるの…？　…はむはむ", 3, 10046, 1, 7, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『おいしいカレーの作\nり方』を読んで新たな\n『エリカレー』を\n隊長に振る舞うわ…！", 3, 10047, 1, 8, 1, 139401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("掃除のしがいがある\n部屋でしゅね～\nいきましゅよ～！", 1, 10048, 1, 1, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("タコ足マッサージは\nキャンセル待ちでしゅ\nにゅるにゅるでしゅ♪", 1, 10049, 1, 2, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たっくしゃんの卵から\n生き残り大きくなった\nラッキーガールでしゅ\nエンギモノでしゅ♪", 1, 10050, 1, 3, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("姫姉しゃまのところに\n初めて来た時のこと\nかすかに覚えてましゅ", 1, 10051, 1, 4, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どこかにタコ壺を\n置きたいでしゅね\nそうしたらもっと\n快適に過ごせましゅ", 1, 10052, 1, 5, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士しゃんもお世話が\n必要でしゅ。あたち、\n姫姉しゃまの小姓と\n両方やりましゅ！", 1, 10053, 1, 101, 4, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("騎士しゃんを見てると\nお腹が空くのは\nどうちてでしょうか\nうじゅ…", 1, 10054, 1, 102, 8, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しゅけしゅけお洋服は\nおしゃれでせくちー、\n深海ファッションの\nとれんどなんでしゅよ", 2, 10055, 1, 1, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("小姓は忙ちいんでしゅ\n騎士しゃんも一緒に\nお仕事どうでしゅか？\n小姓一日入門でしゅ！", 2, 10056, 1, 2, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("部屋に体色を同化して\nカモフラージュ…♪\nうじゅ！？　なんで\n見つかったんでしゅ？", 2, 10057, 1, 3, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃ、ごめんなしゃい\nデュラ爺しゃん～\n…あれ？　違いまちた\nびっくりちまちたよ！", 2, 10058, 1, 4, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『イケてるタコには\n毒がある』んでしゅ\nあたちは…持ってない\nでしゅ…うじゅる…", 2, 10059, 1, 101, 4, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("先のほうはちょっと\nビンカンなので\nやさちく、ぎゅって\nつないでほちいでしゅ", 2, 10060, 1, 102, 8, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しゅっきりお目覚め\nくしゅぐりコースで…\nうじゅうじゅうじゅ♪\n逃がしましぇんよ～", 2, 10061, 1, 1, 1, 136901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("特製タコパスタなら\nすぐご用意できましゅ\nぶちぶちっ！\n…ちぎりすぎまちた", 2, 10062, 1, 2, 1, 136901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("子守唄を歌いましゅ\n深海の深～い眠りに\nいざなってあげるの\nでしゅ！", 2, 10063, 1, 3, 1, 136901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("じゅるじゅるじゅる…\nっと、油断すると\nお口が崩れて…\nこうちて…よち、と", 3, 10065, 1, 2, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いいこいいこ～\nみなしゃんに\nかわいがられる\nマスコットでしゅね～", 3, 10066, 1, 3, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわ～いい香りでしゅ\nお肌も、足も、\nちっとりぬるぬる、\nぷるぷるでしゅ～", 3, 10067, 1, 4, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どこからか焼きタコの\n香ばしい匂いが…♪\nうじゅ！？\nあたちからでちた！", 3, 10068, 1, 5, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここに、もうひと味…\nぱっぱっぱ、っと♪\nコショーはやっぱり\n役に立ちましゅ", 3, 10070, 1, 7, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("王子しゃまを好きに\nなった人魚しゃん…\n一緒に海に帰らな\nかったんでしゅね…", 3, 10071, 1, 8, 1, 136901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スミレ様にはお世話に\nなってばかりで…\nいつかこのご恩を\nお返ししたいです", 1, 10077, 1, 1, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兄様の周りは強いお方\nばかり。皆様について\nいくためにも、より\n強い自分になります", 1, 10078, 1, 2, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("多くの人に笑顔に\nなってもらいたい\nわたくしの力は、その\nために使いたいのです", 1, 10079, 1, 3, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『繋がりの巫女』の\n力で外出中の兄様と\n会話ができたりも…？\nもっと修業します…！", 1, 10080, 1, 4, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…今は羽を休める\nとしましょう。ギルド\nハウスでは常在戦場も\n少しだけ緩めて…", 1, 10081, 1, 5, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("妄想に似た理想は、\nいりません。等身大の\n兄様だけを、この瞳に\n映し続けたいのです", 1, 10082, 1, 101, 4, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…お帰りになるまで\nあと何分でしょう？\n一日千秋の思いで\nお待ちしております", 1, 10083, 1, 102, 8, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("白と黒だとどちらが\n好きですか？　兄様の\n好みを知りたくて…\nあ、服装の話ですよ？", 2, 10084, 1, 1, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兄様のことをもっと\n教えてくださいませ\nたとえば…味の好みや\n寝る時の格好なども", 2, 10085, 1, 2, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦場の誉れもうれしい\nものですが、兄様から\nのお言葉がなによりも\nうれしいのです", 2, 10086, 1, 3, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("抜けた羽で羽毛布団を\n作れないでしょうか？\nもちろん作った布団は\n兄様に贈ります…♪", 2, 10087, 1, 4, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("また、お手合わせを\nお願いします、兄様\n…稽古のときは二人で\nいられますから…♪", 2, 10088, 1, 101, 4, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("白は、何色にでも\n染まることができる色\nどうぞ、兄様が思う\nように染めてください", 2, 10089, 1, 102, 8, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます\n今日も兄様に朝から\nご挨拶ができて、\nわたくしは幸福です♪", 2, 10090, 1, 1, 1, 139501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ご飯を食べて、\n今は羽を休めましょう\n宜しければ、わたくし\n手料理に挑戦をっ…", 2, 10091, 1, 2, 1, 139501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そろそろ就寝の時間\nですね。成長するため\nには、修業だけでなく\n睡眠も大事です", 2, 10092, 1, 3, 1, 139501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あぁ…なんという\nふかふかさ…いくら\n修業を重ねてもこれに\n抗うことは不可能です", 3, 10094, 1, 2, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("無生物とも『繋がる』\nことはできるのでしょ\nうか…？　試して\nみたいと思います", 3, 10095, 1, 3, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…嗅いでいる\nと自然の中にいるよう\nで、集中したいときに\n重宝しそうです", 3, 10096, 1, 4, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("滝行の後は体が冷えて\nしまって…はぁ…♪\nぽかぽかで、心まで\n温かくなります…♪", 3, 10097, 1, 5, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("最近はカロリー消費が\n多いことばかりなので\nたくさん食べられます\n…もぐもぐっ♪", 3, 10099, 1, 7, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("『薔薇の下の契り』？\nだ、男性同士で…！？\nこのような観念が\n存在していたとは…っ", 3, 10100, 1, 8, 1, 139501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("かえる、ばしょ\nかえり、まつ、ばしょ\nいつでも、きれいに\nめざせ、しゅふ", 1, 10106, 1, 1, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("つばさ、おそろい\nハッピーちゃんと\nうれしみ", 1, 10107, 1, 2, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このやり、ふぉーく\nないふ、も\nひつよう、なので\nリリのやり、かりるね", 1, 10108, 1, 3, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("はね、おちる\nいつの、まにか\nたいへん、おそうじ", 1, 10109, 1, 4, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄の、かえり。まつ\nおふろ、じゅんび\nきっと、よろこぶ", 1, 10110, 1, 5, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パパ。はなし、たい\nよんでみよ\nまほうじん、かく。", 1, 10111, 1, 101, 4, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたしたち、なかよし\nまぶだち、こえてる\nじっしつ、ふうふ？", 1, 10112, 1, 102, 8, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄、おかえり\nつかれて、ない？\nまっさーじ、する？", 2, 10113, 1, 1, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("つばさ、おおきい\nうで、とどかない\nお兄。リボン、よろ", 2, 10114, 1, 2, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしいもの\nどこか、ないかな\nあ、お兄。みっけ", 2, 10115, 1, 3, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("このやり、つかって\nちーず、ふぉんでゅ\nしよう、お兄", 2, 10116, 1, 4, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄。どこにも\nいかないで\nまつの、さびしい", 2, 10117, 1, 101, 4, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄、ほめて\nそうじ、せいとん\nかんりょう", 2, 10118, 1, 102, 8, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよ\nあさごはん、べーこん\n…ハッピーちゃん？", 2, 10119, 1, 1, 1, 139701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふあ…ちょい、ねむ\nらんち、まんぷく\nお兄。おひるね、しよ", 2, 10120, 1, 2, 1, 139701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("よぞら、おさんぽ\nほし、きらきら\nきれい", 2, 10121, 1, 3, 1, 139701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("すわる、ねる\nつばさ、ぽじしょん\nなやむ。いつも", 3, 10123, 1, 2, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつも、あざます\nだっこ、させてくれて\nこんごとも、よろ", 3, 10124, 1, 3, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたしの、つばさ。も\nいいにおい、する\nおひさま、みたい", 3, 10125, 1, 4, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハッピーちゃん\nやけど、気をつけて\nちゃーしゅー、なる", 3, 10126, 1, 5, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うぷ。\nおなか、はちきれ\nしあわせと、ひきかえ", 3, 10128, 1, 7, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("パパがくれた、ほん\nちょいむず\nおとなの、かいだん", 3, 10129, 1, 8, 1, 139701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("槍のお手入れって\nお花の世話に似てます\n心を込めてこまめに…\n人の心も同じですね", 1, 10135, 1, 1, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("帰る場所があるって…\n帰りたい所があるって\n幸せなことですね…♪", 1, 10136, 1, 2, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("総長ちゃんって\n呼ばれるの、慣れない\nけど…実はちょっと\n気に入ってます♪", 1, 10137, 1, 3, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日の夕飯は\nメンチカツに\nしようかな？", 1, 10138, 1, 4, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("モネちゃんにもらった\n髪飾りつけて、一緒に\nお出かけしたいな…♪\n今度誘ってみよう", 1, 10139, 1, 5, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ホンネで話すのって\n恥ずかしいけど…\nもっと仲良くなれる\n気がします", 1, 10140, 1, 101, 4, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("聖女なんかじゃなくて\n戦乙女として、\n一緒に戦いたい\n後悔しないためにも", 1, 10141, 1, 102, 8, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誰かを癒すこと…もう\n躊躇いません。だから\n小さなケガでも教えて\nくださいね？", 2, 10142, 1, 1, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたし、悪い子です\nわたしを甘やかす\nお兄さんも共犯者\nですよ。ふふっ…", 2, 10143, 1, 2, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ヴァルキュリア…\n部屋の中だとちょっと\n窮屈ですかね…？", 2, 10144, 1, 3, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あ、お部屋に羽根が…\nわたしが居た証拠？\n…じゃなくって、\nすぐお掃除しますねっ", 2, 10145, 1, 4, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お兄さん、また\n二人でお出かけ\nしたいです…♪", 2, 10146, 1, 101, 4, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("一緒に空飛びます？\nわたしがお兄さんを\n抱っこして\nあげますよ～っ♪", 2, 10147, 1, 102, 8, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日一日、\nお兄さんのこと\n独り占めして\nいいですか？", 2, 10148, 1, 1, 1, 139601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼ですよ。ごはん\n食べに行きませんか？\n今日は、二人だけで\nあ、明日も明後日も♪", 2, 10149, 1, 2, 1, 139601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("わたしが寝かしつけて\nあげます♪\nえへへ、ひそかな夢\nだったんです、実は", 2, 10150, 1, 3, 1, 139601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふぅ…\n羽も心も\n休まります…", 3, 10152, 1, 2, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この子もちょっと\nあざといんじゃない\nかな～？\n仲間ですねっえへへ♪", 3, 10153, 1, 3, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り♪\n今度お兄さんに\n教えてあげたいな", 3, 10154, 1, 4, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったかくて\nしあわせで\nお兄さんのこと\n思い出しちゃう", 3, 10155, 1, 5, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たくさん食べて\n体力つけようっと\n恋も戦いも、\n体が資本だから", 3, 10157, 1, 7, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こ、恋占いの本\n読んじゃおっかな…\nわたしとお兄さんの\n相性は…ドキドキ", 3, 10158, 1, 8, 1, 139601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この姿だと冷凍\nトゥンヌスが素早く\n完璧に作れるみたい\n覚醒の無駄遣いかしら", 1, 10164, 1, 1, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("兄さんは私の\n赤ちゃん化のこと\nどう思ってたんだろう\n怖くて聞けないけど…", 1, 10165, 1, 2, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("コッコロマ…っ\n…いけない、また\n口が滑っちゃった…\n覚醒でもダメなのね…", 1, 10166, 1, 3, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("プレシアちゃんに\n「せんぱい」って…\nふふ、悪くないわね", 1, 10167, 1, 4, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アイス食べたいわ\nチョコミントのダブル\n特訓で頑張ったご褒美\nってことにしましょ♪", 1, 10168, 1, 5, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("甘える練習、なかなか\n難しかったわ。今度は\nどんな風に甘えよう…\nはっ、癖になってる…", 1, 10169, 1, 101, 4, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("好きって気持ち、\n抑えきれなくなってる\nこれって覚醒の副作用\nだったりしないわよね", 1, 10170, 1, 102, 8, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腕の紋章も大きくなる\nって不思議ね。成長の\n証？　あなたが言うと\n誇らしく思えるわね♪", 2, 10171, 1, 1, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今度一緒に空を飛んで\nみない？　大丈夫\n私が抱えてあげる\n大きい翼が役に立つわ", 2, 10172, 1, 2, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("覚醒するとお腹が減る\nなんて知らなかったわ\nペコリーヌさんは共感\nしてくれたけど…", 2, 10173, 1, 3, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("キャルが翼の手入れの\n仕方を教えてくれたの\nこれって猫の毛繕い\nみたいなものかしら？", 2, 10174, 1, 4, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この翼であなたを\n守りたい…でも本当は\nあなたが私を守って\nくれてるのよね…♪", 2, 10175, 1, 101, 4, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ね…、ちょっとだけ\n甘えてもいい？\n兄さんに甘えるのとは\n違う甘え方で…", 2, 10176, 1, 102, 8, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい朝ね。朝日が\n眩しくて二度寝でき\nないなら、翼で日陰を\n作ってあげるわよ？", 2, 10177, 1, 1, 1, 139801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼はお弁当を持って\nどこか行かない？\n兄さんも誘って３人で", 2, 10178, 1, 2, 1, 139801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜遅くまで起きて…\n眠れないの？\n…私が子守唄、歌う？", 2, 10179, 1, 3, 1, 139801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここでなら\n赤ちゃん化しても\n安全…よね？", 3, 10181, 1, 2, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、かわいい…\nホマレさんに見せたら\nスケッチされそうね", 3, 10182, 1, 3, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…\n…チョコミントの\nアロマとかないかしら", 3, 10183, 1, 4, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("温かくて落ち着くわ\n彼の隣にいるときと\n同じぬくもり…\nなんてね", 3, 10184, 1, 5, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("覚醒してると\n消耗が激しくて…\nホマレさんを\n見習わなきゃね", 3, 10186, 1, 7, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("恋愛の指南書、一冊\n読んでみようかな\n「甘え上手な彼女に\nなる方法」ふむふむ…", 3, 10187, 1, 8, 1, 139801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("こっちの過激な水着は\n最終兵器として、\nとっておこうっと", 1, 10193, 1, 1, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ダーリンのために特製\nトロピカルドリンクを\n錬成しておかなくちゃ\nいつでも飲めるように", 1, 10194, 1, 2, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お部屋で水着…\nもしかして私って\nすごく破廉恥！？", 1, 10195, 1, 3, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("塩飴の錬成完了！\n暑い日のお出かけも\nばっちりね", 1, 10196, 1, 4, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("イロハちゃんと\nソノさんの水着も\n錬成できたわ！", 1, 10197, 1, 5, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ダーリンの視線を\n釘付けにするポーズ…\nこ、こうかしら？", 1, 10198, 1, 101, 4, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふっ\nダーリンの帰りを\n水着姿でお出迎え♪\n刺激が強すぎるかな…", 1, 10199, 1, 102, 8, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大人の階段…\n大人の階段…\nち、違っ！階段で昇降\n運動しようと思って！", 2, 10200, 1, 1, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("バ、バナナボートって\nなんだか…ううん\n分からないならいいの", 2, 10201, 1, 2, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私、この夏が人生で\n一番楽しいわ。だって\nあなたがいるから", 2, 10202, 1, 3, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("桃色の本が落ちてた？\nわ、私のじゃないわ\nでも預かっておくわね", 2, 10203, 1, 4, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("カップルストローを\n買ってきちゃった\nまた一緒に飲まない？", 2, 10204, 1, 101, 4, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("世界で一番\n水着が似合う女の子に\nなってみせるわ\n楽しみにしてて♪", 2, 10205, 1, 102, 8, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはよう。わ、寝汗\nすごいわね！　制汗の\n秘薬を塗ってあげる", 2, 10206, 1, 1, 1, 139901, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんなに暑くても\n私はあなたと\nくっついてたいな♪", 2, 10207, 1, 2, 1, 139901, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハート型の花火を\n買ったの。まるで\n私たちの心みたいね♪", 2, 10208, 1, 3, 1, 139901, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("セクシーな\n寝ころびポーズで\nダーリンを悩殺よ♪", 3, 10210, 1, 2, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("派手な水着に\nキュートなぬいぐるみ\nいい組み合わせかも♪", 3, 10211, 1, 3, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くんくん…\n汗の匂い大丈夫かな…\nこれでいい匂いに\nなったよね？", 3, 10212, 1, 4, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あつっ！　水着で\n近づいたらお肌が\nヒリヒリしちゃう…", 3, 10213, 1, 5, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("くびれが気になるけど\n食べるときはしっかり\n食べないと…ね？", 3, 10215, 1, 7, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("マサオはミツコの\n水着をずらし…ごくり\nす、すごい本だわ！", 3, 10216, 1, 8, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あっ、背中の突起が\n当たって…\nく、くすぐったい…", 3, 10218, 1, 10, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この上でダーリンと\nいちゃいちゃ…\nへ、えへへ…", 3, 10219, 1, 11, 1, 139901, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んん…ファビュラス\nビーチの視線を\n独り占めしてしまい\nそうですわ…", 1, 10222, 1, 1, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フム…この部屋も\nリゾートスタイルに\n模様替えしてみては？", 1, 10223, 1, 2, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("音響盤で波音のBGM\nでも流しましょうか\n一気にリゾート気分を\n味わえますわよ♪", 1, 10224, 1, 3, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("秘書の目を盗んで\nひと時の休憩…\nふふ…ドリンクでも\nあれば完璧ですわね♪", 1, 10225, 1, 4, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年のセンス\n割とよろしいですわね\nホテルの内装について\n意見を貰おうかしら？", 1, 10226, 1, 5, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年へのプレゼント\n何がいいでしょうね？\n部屋の様子を見れば\n好みがわかるかも…", 1, 10227, 1, 101, 4, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ…サプライズで\nプレゼントですわ\nわたくしとお揃いの\n金・色・ビ・キ・ニ♪", 1, 10228, 1, 102, 8, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい仕事をするコツは\n高いモチベを保つこと\nこの水着も\nその一環でしてよ♪", 2, 10229, 1, 1, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ちょ、なんですの？\nあなたの持ってるそれ\n巨大化の秘薬じゃ\nないでしょうね…！？", 2, 10230, 1, 2, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("さあさあ準備は\nできたかしら？\n今からバカンスへ\n出発ですわよ～♪", 2, 10231, 1, 3, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("リゾートの夏は稼ぎ時\nですがたまには自分が\n休暇を取ってみるのも\n悪くありませんわね♪", 2, 10232, 1, 4, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あらあら、なんですの\n目を逸らしたりして？\n少年には少～し刺激が\n強すぎたかしら♪", 2, 10233, 1, 101, 4, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("少年、また今度デート\nして差し上げますわ\nもちろん仕事として…\n…仕事として、です", 2, 10234, 1, 102, 8, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("大事な会議は\n頭の回る午前中に\n片づけるのが\n鉄則ですわよっ！", 2, 10235, 1, 1, 1, 140001, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい仕事をするため\nお昼はしっかり\n食べませんとね！\n…お腹が出ない程度に", 2, 10236, 1, 2, 1, 140001, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今日は定時で\n上がれましたの？\nお疲れさまの乾杯でも\nしましょうか…♪", 2, 10237, 1, 3, 1, 140001, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("中々いい座り心地…\nバカンスには\nもってこいですわね♪", 3, 10239, 1, 2, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あら、かわいい\nリゾートとコラボして\n限定グッズを売れば…\nふふっ、アリですわね", 3, 10240, 1, 3, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海の香りのアロマ…\nふふ、売れそうですわ\nルイズマリーさんに\n発注しようかしら♪", 3, 10241, 1, 4, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("水着姿で暖まる…\nこれぞ贅沢の極み\nですわね", 3, 10242, 1, 5, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("もぐもぐ…フム\n中々いけますわね\nホテルのメニューに\n提案してみようかしら", 3, 10244, 1, 7, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("……っ！？\n表紙は経営学ですが\n中身はおピンク…絶対\nあの子の私物ですわ…", 3, 10245, 1, 8, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("フフ、あの鮫も\nぬいぐるみにすれば\nちょっとはかわいく\nなりますでしょうか？", 3, 10247, 1, 10, 1, 140001, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("オッホッホッ\nファビュラスな\n女神さまといった\nところでしょうか♪", 3, 10248, 1, 11, 1, 140001, 0, 0);
