INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここにいると\nなんか安心する…\nあの人のせいかな", 1, 10343, 1, 101, 4, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("隣にいたいって\nこの気持ちは\n設定なんかじゃない\nあたしが感じてること", 1, 10344, 1, 102, 8, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おや騎士さん\nお茶でもどーです？\nお菓子もあるんで\nサボりじゃないですよ", 2, 10345, 1, 1, 1, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("実はこの姿でなにが\nできるか、実験して\nみたいんですよね…\n助手募集中なんですが", 2, 10346, 1, 2, 1, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("翼、気になります？\n触ってもいいですけど\nくすぐるのはナシで", 2, 10347, 1, 3, 1, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("来ると思ってました\n騎士さんのこと\nだいぶ読めてきたんで\n的中率７割ですかね", 2, 10348, 1, 4, 1, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("急成長したせいで、\n歩く時のバランスが…\n…騎士さんちょっと\nおんぶお願いします", 2, 10349, 1, 101, 4, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("渋いのに甘かった\nあの紅茶…また\n淹れてほしいなって", 2, 10350, 1, 102, 8, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございます…\nふぁあ…眠気覚ましに\n散歩でも行きます？", 2, 10351, 1, 1, 1, 140501, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼の付け合わせは\nポテトサラダです\nもちろん甘い\nリンゴ入りで", 2, 10352, 1, 2, 1, 140501, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("夜更かし仲間ですね\n星がキレイですし\nよかったら空、一緒に\n飛んでみます？", 2, 10353, 1, 3, 1, 140501, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんな力があっても\nこの誘惑には\n勝てない…\nもう動きたくない…", 3, 10355, 1, 2, 1, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわふわ…\n触り心地いいな\n姉貴のほっぺたみたい", 3, 10356, 1, 3, 1, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ん？　…この匂い\nちょっとだけ\nはちみつっぽい？", 3, 10357, 1, 4, 1, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あったか…\nあー動きたくない…\n一生ここにいたーい…", 3, 10358, 1, 5, 1, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おにぎりに\n甘い具材入れたら\nどんな味になるか\n次、実験してみよ", 3, 10360, 1, 7, 1, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしも騎士さんに\nなにか作ってみるかな\nレシピレシピ…", 3, 10361, 1, 8, 1, 140501, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この場所…\n退屈しないわ\n面白そうな人や物が\nたくさんあるもの", 1, 10367, 1, 1, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("クー？　部屋の中で\n粗相をしてはダメよ\n後で散歩に連れて\n行ってあげるから", 1, 10368, 1, 2, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("気が抜けているようで\nとても穏やか\n…私にもこんな場所が\nあるといいんだけど", 1, 10369, 1, 3, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ついこのまま\nここにいたくなる…\nこれもある種の\n『呪い』かしら？", 1, 10370, 1, 4, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ここが、騎士の\n帰るべき居場所…\nちょっとだけ\nうらやましいわね", 1, 10371, 1, 5, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("静かなほうが好き\nだけど…騒がしい\n世界もちゃんと\n知っていかなきゃね", 1, 10372, 1, 101, 4, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんなに満たされても\nまだ足りないと思って\nしまう。『強欲』\nなのも困りものね", 1, 10373, 1, 102, 8, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私なんかに構っていて\nいいの？　ふふ、他の\n女の子に嫉妬されても\n知らないわよ？", 2, 10374, 1, 1, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("貴方とのおしゃべりは\n退屈しなくて好きよ\n私が知らない世界が\n見つかりそうだから", 2, 10375, 1, 2, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひねくれた性格だから\nひねくれた性格の人に\n惹かれる性質なの\nでも…貴方は別みたい", 2, 10376, 1, 3, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("そんなに私が欲しい？\nまぁ、罪滅ぼしって\nことなら…なんてね、\n冗談よ？", 2, 10377, 1, 4, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("私の居場所は私で\n見つける。でも、\nたまにはここへ立ち\n寄ってもいいかしら…", 2, 10378, 1, 101, 4, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("何も考えず、旅をする\nそうしたら私も…貴方\nのように大切な何かを\n見つけられるかしら", 2, 10379, 1, 102, 8, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ジオ・二ヴルヘルは\nずっと暗いから、\nこの世界の朝という\nのは慣れないわね", 2, 10380, 1, 1, 1, 140401, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お昼の時間ね\n手料理でも振る舞い\nましょうか？\nこう見えても得意なの", 2, 10381, 1, 2, 1, 140401, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("やっぱり夜は\n落ち着くわね\n静寂が全てを\n包み込んでくれる", 2, 10382, 1, 3, 1, 140401, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("思えば、こうやって\n腰を据えてくつろげる\nなんて、久しぶりな\n気がするわね", 3, 10384, 1, 2, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふふ、かわいいわね\nもちろんクーほどじゃ\nないけどね？", 3, 10385, 1, 3, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この香り、嫌いじゃ\nないわ。気分が\n鎮まって、余計なこと\nを考えなくて済むもの", 3, 10386, 1, 4, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("…あたたかい\nこの感覚も、私を\n満たしてくれる\n一つの答えなのかしら", 3, 10387, 1, 5, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("食事を楽しむ機会\nなんて多くはなかった\nけど、意外と悪くは\nないものね", 3, 10389, 1, 7, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("知識は身につけて\nおいて損はないわ\nいざという時の\nために…ね", 3, 10390, 1, 8, 1, 140401, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("敵影なーしっ\n今日もギルドハウスは\n安心安全ですっ♪", 1, 10396, 1, 1, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お水でざぶーんと\n流しちゃうので\nお部屋のお掃除も\nお任せですっ♪", 1, 10397, 1, 2, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("新ボディになったので\nライラエルさまたち\nとも、いつか海に\n遊びにいきたいですっ", 1, 10398, 1, 3, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ボディに書かれた\nこの文字…\nまるっこくて\nかわいいですねっ♪", 1, 10399, 1, 4, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("高いところに\n置かれたものでも\nこの伸びるアームなら\nキャッチも簡単ですっ", 1, 10400, 1, 5, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("裏世界の管理者には\nなりましたけどっ、\nわたしはこれまでと\n変わりませんよっ♪", 1, 10401, 1, 101, 4, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("胸の中にある\nたくさんの気持ち…\nわたしの大切な\n宝物ですっ♪", 1, 10402, 1, 102, 8, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ひゃっ\n上半身の装甲は\n薄めなので触られると\nくすぐったいですねっ", 2, 10403, 1, 1, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("腕のクローはいつでも\n切り替え可能ですっ♪\nハグのときは普通の\n腕なので安心ですよっ", 2, 10404, 1, 2, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("またギルドのお仕事が\nしたいですっ\nマスターのお役に\n立ちますのでっ♪", 2, 10405, 1, 3, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("また一緒に海へ遊びに\nいきませんかっ？\n泳ぐときはわたしが\nエスコートしますねっ", 2, 10406, 1, 4, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("他の国の海はどんな\n感じなんでしょうかっ\nいろんなお魚さんが\n見れるといいなーっ", 2, 10407, 1, 101, 4, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("成長は苦しいことも\nありますけど…\nそれでもわたしは成長\nしていきたいですっ", 2, 10408, 1, 102, 8, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おはようございますっ\n朝海水浴で\n目を覚ましましょうっ", 2, 10409, 1, 1, 1, 140601, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お魚さんを\n獲ってきましたっ！\nたくさん食べて午後も\nフルパワーですっ", 2, 10410, 1, 2, 1, 140601, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("海中から見る\n夜空はすごく\nキラキラだそうですっ\n一緒に見ませんかっ？", 2, 10411, 1, 3, 1, 140601, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("たくさん泳いだあとは\n休憩が大切ですっ♪\n充填完了したら、また\n遊びにいきましょうっ", 3, 10413, 1, 2, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ぎゅーってしたい\nですけど…\nまずは濡れたボディを\n乾かさないとですねっ", 3, 10414, 1, 3, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("香りを検知しましたっ\n落ち着く…って\nこんな気持ちなんで\nしょうかっ？", 3, 10415, 1, 4, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お水の乾燥よーしっ♪\n水中用モードでも\nメンテナンスは\n必要ですよねっ♪", 3, 10416, 1, 5, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("おいしいって気持ち…\nだんだんわかってきた\nような気がしますっ♪", 3, 10418, 1, 7, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この本…\n前に読んだときよりも\n気持ちがいっぱい\n伝わってきますっ", 3, 10419, 1, 8, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いつかは本物の\nお魚さんたちとも\nこんなふうに\n遊んでみたいですっ", 3, 10421, 1, 10, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この貝さん\nふかふかですっ\n海に持っていけば\nどこでも休めますねっ", 3, 10422, 1, 11, 1, 140601, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦士の帰還、って\nところね。やっぱり\nここは懐かしいかんじ\n家主の人柄かしら？", 1, 10425, 1, 1, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あの家具の陰、ハイド\nするのによさそうね\nかくれんぼでもしたら\nあたしの優勝かも♪", 1, 10426, 1, 2, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("アルファは待機\nブラボーは突入！\n…ふふ、すっかり\nハマっちゃったみたい", 1, 10427, 1, 3, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次の訓練はいつが\nいいかしら。レモンと\nハチミツ…じゃなくて\n的の準備をしなきゃね", 1, 10428, 1, 4, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この装備、レプリカを\n作ったら人気商品に\nなりそう。アキノさん\nに相談してみようかな", 1, 10429, 1, 5, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("次のお弁当プランを\n練っておかなきゃね\nあいつの「おいしい」\nが、あたしの報酬よ", 1, 10430, 1, 101, 4, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("誰かより…なんて不安\nはいらないのよね。今\nこの瞬間も、思い出は\n重なっていくんだから", 1, 10431, 1, 102, 8, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("なあに？\nそんなにあたしの\nスーツ姿が気になる？\n…って、見過ぎよ！？", 2, 10432, 1, 1, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("驚かせようったって\n残念♪　あんたが声を\nかけてくるパターンは\nお見通しなんだから♪", 2, 10433, 1, 2, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("見て。向こうの建物に\n怪しい影があるわ…\nあたしたちの出番ね\n作戦を練るわよ", 2, 10434, 1, 3, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あたしの後ろに立った\nやつ…手をあげて！\n…なーんてね♪", 2, 10435, 1, 4, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("どんな新しい世界でも\n新しい装備でも、ほら\nちゃーんと、あんたの\n知ってるあたしでしょ", 2, 10436, 1, 101, 4, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("うずうずしてるの\nここからまたあんたと\n始めるのは、まったく\n新しい冒険なんだって", 2, 10437, 1, 102, 8, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("今朝は一緒に演習する\nって約束でしょ？\nまた寝ぼけた顔して…\nはい、顔を洗いにゴー", 2, 10438, 1, 1, 1, 140701, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あーあー。こちら\nサレン、昼食をとるわ\nデザートは苺サンド\nオーケー、どうぞ", 2, 10439, 1, 2, 1, 140701, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("暗闇だって\nゴーグルがあれば\nあんたの寝顔も\n見えちゃうのよ♪", 2, 10440, 1, 3, 1, 140701, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この下にターゲットが\n隠れていたら…なんて\nこの装備だとついつい\n考えちゃうのよね", 3, 10442, 1, 2, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ターゲット発見！\n非常にかわいい様子\nただちにモフりを実行\nモフモフ…♪", 3, 10443, 1, 3, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…\n戦いで高揚した気持ち\nをここでリセット\nしなくちゃね", 3, 10444, 1, 4, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いろんなところに\n冒険に行ったけど、\n暖をとるありがたみは\nどこでもいっしょよね", 3, 10445, 1, 5, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹が空いては\nなんとやら、よ\nめいっぱい\n補給しないと♪", 3, 10447, 1, 7, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふんふん。上手に撃ち\n抜く方法…彼のハート\nを…ってこれ、恋愛\nマニュアルじゃない！", 3, 10448, 1, 8, 1, 140701, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("セーフゾーン到着…\n次に接敵するまでに\n物資を補給しないとね\n…なんちゃって♪", 1, 10450, 1, 1, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつの見た映画だと\n銃をカンフーみたいに\n構えてたわよね…\n参考にしようかしら…", 1, 10451, 1, 2, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふむ…この部屋\nエイム練習の的に\n使えそうなものは\nないかしら？", 1, 10452, 1, 3, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("GG…なるほど\nグッドゲームのことね\nグッドガイドのこと\nだと思っちゃったわ", 1, 10453, 1, 4, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("銃に泥ついてる…！\nさっきブースターの\n制御失敗して転んだ\nのよね…拭かなきゃ", 1, 10454, 1, 5, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつ、きっと勝って\n戻ってくるからカツ丼\n用意しときましょ…♪", 1, 10455, 1, 101, 4, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("あいつと肩を並べて\n戦うことになるなんて\nなんか不思議な気分ね", 1, 10456, 1, 102, 8, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("冒険に出る前に\nしっかり\nブリーフィング\nしときましょ", 2, 10457, 1, 1, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("男の子って、二丁拳銃\n好きな人多いわよね\nロマンってやつ？\nちょっと分かるけど", 2, 10458, 1, 2, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("しゅ、ずだだだ！\n索敵、クリア…\nあ！　ち、違う！\nこれイメトレだから！", 2, 10459, 1, 3, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("この服なかなか快適よ\n普段使い…にするには\nちょっと大胆か…\nあんたはどう思う？", 2, 10460, 1, 4, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("FPSにガイド妖精は\nいないのよね。慣れて\nきたらあたしがなって\nあげる。あんた専属よ", 2, 10461, 1, 101, 4, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("戦場にあんた一人が\n残っちゃったら自力で\n復帰してでも助けに\nいくわ。安心なさい♪", 2, 10462, 1, 102, 8, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ふわあ…おはよ\nさ、まずはエイム練習\nあんたは的役お願い♪\n…って、冗談よ冗談！", 2, 10463, 1, 1, 1, 140801, 1, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("12時の方向に敵！\n…じゃなくてお昼時ね\nお弁当…じゃなくて\nレーションあるわよ", 2, 10464, 1, 2, 1, 140801, 2, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("んっ…ふうー…\nあんたもストレッチ\nしておきなさい？\n走り疲れたでしょ？", 2, 10465, 1, 3, 1, 140801, 3, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("敵から隠れるのに\nちょうどいいと\n思ったけど…\n寝ちゃう、わね…♪", 3, 10466, 1, 2, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("ハードな訓練の後は\n可愛いものに癒される\nものなのよね…♪", 3, 10467, 1, 3, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("いい香り…深呼吸して\n気持ちを落ち着けたら\nトラッキングエイムも\nうまくいくはず", 3, 10468, 1, 4, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("安全地帯発見♪\n今のうちにHPを回復\nして、次の戦いに\n備えるわ", 3, 10469, 1, 5, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("お腹が空いたら\n戦えないもの\nできるときに\n腹ごしらえしなきゃね", 3, 10470, 1, 7, 1, 140801, 0, 0);
INSERT INTO `v1_6b0e425eda615c6da9a95761971ebaa8e58a1a5ab7b70f69dd9e5eb1be668261` VALUES ("スナイパーライフルに\nショットガン…\n銃にも色々\n種類があるのね", 3, 10471, 1, 8, 1, 140801, 0, 0);
